import net.pushl.datastructure.RangeSumQueryTree
class Solver(val stdio: MyConsole){
  import stdio._ // shadow Console.~
  def main() : Unit = {
    val n,q = nextInt
    val rsq = new RangeSumQueryTree[Int](n)
    for(i <- 1 to q){
      val com,_x,_y = nextInt
      if(com == 0){
        val (x,y) = (_x-1,_y)
        rsq(x) = rsq.get(x,x+1) + y
