    else {
      val (com, x, y) = l.head
      com match {
        case 0 => { update(x, y); solver(l.tail,acc) }
        case _ => solver(l.tail, find(x, y)::acc)
      }
    }
  }

  solver(list, Nil).foreach(println)
}

