sealed trait Segtree[M] {
  def value: M
  def size: Int
  def rangeQuery(a: Int, b: Int): M
  def updated(k: Int, x: M): Segtree[M]
}

case class Leaf[M : Monoid](value: M) extends Segtree[M] {
  override val size = 1
  override def rangeQuery(a: Int, b: Int): M =
    if (a <= 0 && 1 <= b) value else implicitly[Monoid[M]].empty
  override def updated(k: Int, x: M) = Leaf(x)
}

case class Node[M](lch: Segtree[M], rch: Segtree[M])(implicit m: Monoid[M]) extends Segtree[M] {
  override val value = m.append(lch.value, rch.value)
  override val size = lch.size + rch.size
  override def rangeQuery(a: Int, b: Int): M =
    if (a <= 0 && size <= b) value
    else if (b <= 0 || size <= a) m.empty
    else {
      val lSize = lch.size
      val left = lch.rangeQuery(a, b)
      val right = rch.rangeQuery(a - lSize, b - lSize)
      m.append(left, right)
    }
  override def updated(k: Int, x: M): Segtree[M] =
    if (k < lch.size) Node[M](lch.updated(k, x), rch)
    else Node[M](lch, rch.updated(k - lch.size, x))
}

object Segtree {
  implicit object IntMonoid extends Monoid[Int] {
    def empty = Int.MaxValue
    def append(a: Int, b: Int) = a min b
  }

  def build[M](n: Int)(implicit m: Monoid[M]): Segtree[M] =
    if (n <= 1) Leaf(m.empty)
    else Node(build(n / 2), build(n - n / 2))

  def processQuery(n: Int, qs: Seq[(Int, Int, Int)]): Seq[Int] =
    qs.foldLeft((Segtree.build[Int](n), List.empty[Int])) { case ((tree, res), (com, x, y)) =>
      com match {
        case 0 => (tree.updated(x, y), res)
        case _ => (tree, tree.rangeQuery(x, y + 1) +: res)
      }
    }._2.reverse
}

