  		val m = (l + r)/2
  		def branch(now: Node): Node = {
  			if(r-l<=1)Node(x)
  			else if(id < m)Node(updateRec(id,x,l,m, now.left), now.right)
  			else Node(now.left,updateRec(id,x,m,r,now.right))
  		}
  		t match {
  			case now:Node => branch(now)
  			case now:Tree => branch(nil)
  			case _ => nil
  		}
  	}

