typedef long long ll;

const int INF = 2147483647; // 2147483647 = 2^31-1

// SegmentTree seg(vector<int> A(N, INF));でセグメント木を生成
// seg.update(x, a);でx番目の要素をaに更新
// seg.getmin(x, y+1);でx番目からy番目の最小値を取得
struct SegmentTree{
private:
  int n;
  vector<int> node;

public:
  SegmentTree(vector<int> V){
    int sz = V.size();
    n = 1; while(n < sz) n *= 2;
    node.resize(2*n-1, INF);
    for(int i = 0; i < sz; i++) node[i+n-1] = V[i];
    for(int i = n-2; i >= 0; i--) node[i] = min(node[2*i+1], node[2*i+2]);
  }

  void update(int idx, int val){
    idx += (n - 1);
    node[idx] = val;
    while(idx > 0){
      idx = (idx - 1) / 2;
      node[idx] = min(node[2*idx+1], node[2*idx+2]);
    }
  }

  int getmin(int a, int b, int k = 0, int l = 0, int r = -1){
    if(r < 0) r = n;
    if(r <= a || b <= l) return INF;
    if(a <= l && r <= b) return node[k];
    int vl = getmin(a, b, 2*k+1, l, (l+r)/2);
    int vr = getmin(a, b, 2*k+2, (l+r)/2, r);
    return min(vl, vr);
  }
};

int main(){
  ios::sync_with_stdio(false);
  cin.tie(0);
  int n, q; cin >> n >> q;
  vector<int> A(n, INF);
  SegmentTree seg(A);
  vector<int> ans;
  REP(i, q){
    int c, x, y; cin >> c >> x >> y;
    if(c == 0){
      seg.update(x, y);
    }else{
      ans.push_back(seg.getmin(x, y+1));
    }
  }
  for(auto &i : ans) cout << i << endl;
}

