const int inf = (1ll << 31) - 1;

void init() {
	int _n = 1;
	while (_n < n) _n *= 2;
	n = _n;

	for (int i = 0; i < 2 * n; ++i) {
		seg[i] = inf;
	}
}

void update(int i, int x) {
	i += n - 1;
	seg[i] = x;

	while (i) {
		i = (i - 1) / 2;
		seg[i] = min(seg[2 * i + 1], seg[2 * i + 2]);
	}
}

int find(int s, int t, int k = 0, int l = 0, int r = n) {
	if (r <= s || t <= l) return inf;
	if (s <= l && r <= t) return seg[k];

	int m = (l + r) / 2;
	return min(find(s, t, 2 * k + 1, l, m), find(s, t, 2 * k + 2, m, r));
}

