template<typename T, typename Op>
struct SegTree {
    using M = Monoid<T,Op>;

    i64 n_orig_;
    i64 n_;
    vector<T> v_;
    Op op_;

    explicit SegTree(i64 n) {
        init(n);
        ALL(fill, v_, M::UNITY());
    }

    SegTree(i64 n, const T& x) {
        init(n);
        i64 i = n_;
        for(; i < n_+n_orig_; ++i)
            v_[i] = x;
        for(; i < 2*n_; ++i)
            v_[i] = M::UNITY();
        for(i = n_-1; i >= 1; --i)
            v_[i] = op_(v_[2*i], v_[2*i+1]);
    }

    template<typename ForwardIt>
    SegTree(ForwardIt first, ForwardIt last) {
        init(distance(first, last));
        i64 i = n_;
        for(; first != last; ++i, ++first)
            v_[i] = *first;
        for(; i < 2*n_; ++i)
            v_[i] = M::UNITY();
        for(i = n_-1; i >= 1; --i)
            v_[i] = op_(v_[2*i], v_[2*i+1]);
    }

    void update(i64 i, i64 x) {
        i += n_;
        v_[i] = x;
        while(i > 1) {
            i /= 2;
            v_[i] = op_(v_[2*i], v_[2*i+1]);
        }
    }

    i64 query(i64 i, i64 k) const {
        assert(0 <= i && i+k <= n_orig_);
        return query_impl(i, i+k, 1, 0, n_);
    }

private:
    void init(i64 n) {
        n_orig_ = n;
        n_ = pow2_ceil(n_orig_);
        v_.resize(2*n_);
    }

    i64 query_impl(i64 a, i64 b, i64 i, i64 l, i64 r) const {
        if(r <= a || b <= l) return M::UNITY();
        if(a <= l && r <= b) return v_[i];

        i64 xl = query_impl(a, b, 2*i,   l, (l+r)/2);
        i64 xr = query_impl(a, b, 2*i+1, (l+r)/2, r);
        return op_(xl, xr);
    }
};

void solve() {
    i64 N; RD(N);
    i64 Q; RD(Q);

    SegTree<i64,OpMin<>> segtree(N, (1LL<<31)-1);
    //DBG(segtree.v_);
    REP(_, Q) {
        i64 cmd; RD(cmd);
        if(cmd == 0) {
            i64 i; RD(i);
            i64 x; RD(x);
            segtree.update(i, x);
            //DBG(segtree.v_);
        }
        else if(cmd == 1) {
            i64 s,t; RD(s); RD(t);
            i64 n = t-s+1;
            i64 ans = segtree.query(s, n);
            PRINTLN(ans);
        }
        else {
            assert(false);
        }
    }

