    while(cin >> n >> q){
        SqrtDecomp<int32_t> rmq(n);
        for(int i = 0; i < q; i++){
            int a,b,c;
            cin >> a >> b >> c;
            if(a == 0){
                rmq.setVal(b,c);
            } else {
                cout << rmq.getMin(b,c+1) << endl;
            }
        }
    }
}

