    }
    else{
        int mid = l+(r-l)/2;
        tree[k] = min(updateUtil(tree, i, v, 2*k+1, l, mid), updateUtil(tree, i, v, 2*k+2, mid+1, r));
    }
    return tree[k];
}

void update(vector<int>& tree, const int& n, const int& i, const int& v){
    updateUtil(tree, i, v, 0, 0, n-1);
}

int findUtil(vector<int>& tree, const int& L, const int& R, const int& k, const int& l, const int& r){
    if(k > tree.size() || l > r || r < L || l > R) return INT_MAX;
    if(l >= L && r <= R) return tree[k];
    int mid = l+(r-l)/2;
    int lv = findUtil(tree, L, R, 2*k+1, l, mid);
    int rv = findUtil(tree, L, R, 2*k+2, mid+1, r);
    return min(lv, rv);
}

int find(vector<int>& tree, const int& n, const int& L, const int& R){
    return findUtil(tree, L, R, 0, 0, n-1);
}
int main(){
    int n, q, com, x, y;
    scanf("%d %d", &n, &q);
    int h = (int)ceil(log2(n));
    int max_size = 2*(int)pow(2, h)-1;
    vector<int> tree(max_size, INT_MAX);
    for(int i = 0; i < q; i++){
        scanf("%d %d %d", &com, &x, &y); 
        if(com == 0) update(tree, n, x, y);
        else if(com == 1) printf("%d\n", find(tree, n, x, y));
        else printf("undefined com\n");
    }
}

