int INF = (1 << 31) - 1;
struct segment_tree {
	int n;
	std::vector<int> data;
	void init(int &n_) {
		int N = 1;
		while (N < n_)N *= 2;
		n_ = N;
		for (int i = 0; i < N*2 - 1; i++)data.push_back(INF);
	}
	void update(int k, int x) {
		k += n - 1;
		data[k] = x;
		while (k > 0) {
			k = (k - 1) / 2;
			data[k] = std::min(data[k * 2 + 1], data[k * 2 + 2]);
		}
	}
	int find(int a, int b, int k, int l, int r) {
		if (b <= l || r <= a)return INF;
		if (a <= l&&r <= b)return data[k];
		int vl1 = find(a, b, k * 2 + 1, l, (l + r) / 2);
		int vl2 = find(a, b, k * 2 + 2, (l + r) / 2, r);
		return std::min(vl1, vl2);
	}
};

