template<typename T,T monoid = 1000000007>
struct SegmentTree{
	int length;
	vector<T> data;
	//data[i]の区間 = [l[i],r[i])
	vector<int> l;
	vector<int> r;

	inline T merge(const T& a,const T& b){
		return min(a,b);
	}

	void change(int i,T val){
		data[i+length-1] = val;
		for(int k = (i+length)/2-1;k >= 0;k = (k-1)/2){
			data[k] = merge(data[2*k+1],data[2*k+2]);
			if(!k)break;
		}
	}

	//[i,j)
	T query(int i,int j){
		T ans = monoid;
		queue<int> que;
		que.push(0);
		int k;
		while(que.size()){
			k = que.front();
			que.pop();
			if(r[k] <= i || j <= l[k]){
				continue;
			}
			if(i <= l[k] && r[k] <= j){
				ans = merge(ans,data[k]);
				continue;
			}
			que.push(2*k+1);
			que.push(2*k+2);
		}
		return ans;
	}

	SegmentTree(vector<T> v) : length(1) {
		while(!(length >= v.size()))length *= 2;
		data = vector<T>(length*2-1,monoid);
		for(int i = length-1;i < v.size();i++){
			data[i] = v[i-length+1];
		}
		for(int i = length-2;0 <= i;i--){
			data[i] = merge(data[i*2+1],data[i*2+2]);
		}
		l.resize(length*2-1);
		r.resize(length*2-1);
		for(int i = length-1;i < length*2-1;i++){
			l[i] = i-length+1;
			r[i] = min(i-length+2,v.size());
		}
		for(int i = length-2;0 <= i;i--){
			l[i] = l[i*2+1];
			r[i] = r[i*2+2];
		}
	};
};

