class segment_tree
{
private:
	std::vector<int>treedat;
	int treesiz;
	static const int inf = INT_MAX;
	int rawqry(int a, int b, int k, int l, int r)
	{
		if (r <= a || b <= l)return inf;
		if (a <= l && r <= b)return treedat[k];
		int m = (l + r) / 2;
		return std::min(rawqry(a, b, k * 2 + 1, l, m), rawqry(a, b, k * 2 + 2, m, r));
	}
public:
	void update(int k, int a)
	{
		k += (treesiz - 1);
		treedat[k] = a;
		while (k > 0)
		{
			k = (k - 1) / 2;
			treedat[k] = std::min(treedat[k * 2 + 1], treedat[k * 2 + 2]);
		}
	}
	int query(int a, int b) { return rawqry(a, b, 0, 0, treesiz); }
	segment_tree(int n)
	{
		treesiz = 1;
		while (treesiz < n)treesiz *= 2;
		treedat.resize(2*treesiz+1);
		std::fill(treedat.begin(), treedat.end(), inf);
	}
};

