using namespace std;

template <class T>
class SegmentTree
{
private:
	int n; // 葉の数
	vector<T> data; // データを格納するコンテナ
	T def;
	function<T(T, T)> operation; // 区間クエリで使う処理
	function<T(T, T)> update; // 点更新で使う処理

	// 区間[a, b)の総和, ノードk=[l, r)に着目している
	T _query(int a, int b, int k, int l, int r) {
		if (r <= a || b <= l) return def;
		if (a <= l && r <= b) return data[k];
		else {
			T c1 = _query(a, b, 2 * k + 1, l, (l + r) / 2); // 左の子
			T c2 = _query(a, b, 2 * k + 2, (l + r) / 2, r); // 右の子
			return operation(c1, c2);
		}
	}

public:
	// _n: 必要サイズ, _def: 初期値かつ単位元, _operation: クエリ関数, _updata: 点更新関数
	SegmentTree(size_t _n, T _def, function<T(T, T)> _operation, function<T(T, T)> _update)
		: n(_n), def(_def), operation(_operation), update(_update) {
		n = 1; while (n < _n) n *= 2;
		data = vector<T>(2 * n - 1, def);
	}

	// 場所iの値をxで更新
	void change(int i, T x) {
		i += n - 1;
		data[i] = update(data[i], x);
		while (i > 0) {
			i = (i - 1) / 2;
			data[i] = operation(data[i * 2 + 1], data[i * 2 + 2]);
		}
	}

	// 半開区間[a, b)でクエリを実行
	T query(int a, int b) {
		return _query(a, b, 0, 0, n);
	}

	// 添字でアクセス
	T operator[](int i) {
		return data[i + n - 1];
	}
};

void solve(const int & N, const int & Q, SegmentTree<long long> & st) {
	int c, x, y; cin >> c >> x >> y; // c: コマンド(0: 点更新, 1: 区間クエリ)

	if (c == 0) st.change(x, y);
	else {
		cout << st.query(x, y + 1) << endl;
	}
}

int main(void) {
	int N, Q; cin >> N >> Q;
	SegmentTree<long long> st(N, (1LL << 31) - 1
		, [](long long a, long long b) {return min(a, b); }
		, [](long long d, long long x) {return x; });

	rep(q, Q) solve(N, Q, st);

	return 0;
}

