            node[i]=x;
            while(i>0){
                i=(i-1)/2;
                node[i]=operation(node[2*i+1],node[2*i+2]);
            }
        }
        std::pair<int,int> range(int i){
            int k=0;
            while(!((1<<k)-1<=i&&i<=(1<<(k+1))-2))k++;
            int left=(strbeg+1)*(i+1-(1<<k))/(1<<k);
            int right=left-1+(strbeg+1)/(1<<k);
            return std::make_pair(left,right);
