    cin.tie(0);
    ios::sync_with_stdio(false);
    int N,Q;
    cin >> N >> Q;
    auto op = [](int a,int b){return min(a,b);};
    SegmentTree<int,decltype(op)> 
    seg(N,op,INT_MAX);
    for(int i=0;i<Q;i++){
        int c,x,y;
        cin >> c >> x >> y;
        if(c==0) seg.update(x,y);
        else cout << seg.query(x,y+1) << endl;
    }
}

