struct segment_tree {
  public:
    const int infty = (int)((1LL << 31) - 1);
    int n, ht, N;
    vector<int> dat;
    segment_tree(int sz) {
      n = sz;
      ht = 1;
      N = 1;
      while (N < n) {
        ht++;
        N <<= 1;
      }
      dat.resize(2 * N, infty);
    }
    segment_tree(vector<int> v) {
      n = v.size();
      ht = 1;
      N = 1;
      while (N < n) {
        ht++;
        N <<= 1;
      }
      dat.resize(2 * N);
      for (int i = 0; i < n; i++) {
        dat[N + i] = v[i];
      }
      for (int i = N - 1; i >= 1; i--) {
        dat[i] = min(dat[2 * i], dat[2 * i + 1]);
      }
    }
    void update (int i, int x) {
      i += N;
      dat[i] = x;
      i >>= 1;
      for (; i; i >>= 1) {
        dat[i] = min(dat[2 * i], dat[2 * i + 1]);
      }
    }
    int find (int l, int r, int k = 1, int L = 0, int R = -1) {
      if (R == -1) R = N;
      if (R <= l || r <= L) {
        return infty;
      } else if (l <= L && R <= r) {
        return dat[k];
      } else {
        int C = (L + R) >> 1;
        return min(find(l, r, 2 * k, L, C), find(l, r, 2 * k + 1, C, R));
      }
    }
};
