template<typename T> struct Monoid {
  T id;
  std::function<T(T, T)> op;
  Monoid(T e, std::function<T(T, T)> f) : id(e), op(f) {}
};

template<typename T> class SegTree {
  vector<T> data;
  Monoid<T> monoid;
  int size = 1;

  T _fold(const int &a, const int &b, const int &k = 1, const int &l = 0, int r = -1) {
    if (r == -1) r = size;
    if (r <= a || b <= l) return monoid.id;
    if (a <= l && r <= b) return data[k];
    return monoid.op(_fold(a, b, k * 2, l, (l + r) / 2), _fold(a, b, k * 2 + 1, (l + r) / 2, r));
  }

public:
  SegTree(const int &n, const Monoid<T> &m) : monoid(m) {
    while (size < n) size *= 2;
    data = vector<T>(2 * size, monoid.id);
  }

  T get(const int &i) { return data[i + size]; }
  T fold(const int &a, const int &b) { return _fold(a, b, 1, 0, size); } // [a, b)

  void update(int i, const T &x) {
    i += size;
    data[i] = x;
    while (i /= 2) data[i] = monoid.op(data[i * 2], data[i * 2 + 1]);
  }
};

