template <typename T>
class DynamicSegmentTree {
	using func_t = function<T(T, T)>;
	const ll n;
	const T id;
	func_t merge;
	node<T> *root;
	vector<node<T>> pool;
	int it;
	ll size(ll n) {
		ll res = 1;
		while (res < n) res <<= 1;
		return res;
	}
	node<T> *new_node() {
		pool[it].init(id);
		return &pool[it++];
	}
	T sub(ll l, ll r, node<T>* n, ll lb, ll ub) {
		if (n == nullptr || ub <= l || r <= lb) return id;
		if (l <= lb && ub <= r) return n->val;
		return merge(sub(l, r, n->l, lb, (lb + ub) / 2), sub(l, r, n->r, (lb + ub) / 2, ub));
	}
	node<T> *suc(ll v, node<T>* n, ll lb, ll ub, T val) {
		if (n == nullptr) n = new_node();
		if (lb + 1 == ub) {
			n->val = val;
			return n;
		}
		ll c = (lb + ub) / 2;
		if (v < c) {
			n->l = suc(v, n->l, lb, c, val);
		}
		else {
			n->r = suc(v, n->r, c, ub, val);
		}
		n->val = merge(n->l != nullptr ? n->l->val : id, n->r != nullptr ? n->r->val : id);
		return n;
	}
public:
	DynamicSegmentTree(ll n_, T id_, func_t merge_, int max_ = 1e7) :
		n(size(n_)), id(id_), merge(merge_), root(nullptr), pool(max_), it(0) {}
	void Update(ll p, T val) {
		root = suc(p, root, 0, n, val);
	}
	T Find(ll l, ll r) {
		return sub(l, r + 1, root, 0, n);
	}
};

