template <class T> class SegmentTreeRMQ {
private:
    vector<T> segtree_min;
    vector<T> segtree_max;
    const int N = 1<<19;
    const T limit_max = (1<<31)-1;
    const T limit_min = (1<<31);
public:
    SegmentTreeRMQ(){
        segtree_max = *new vector<T>(N*2,limit_min);
        segtree_min = *new vector<T>(N*2,limit_max);
    }
    void update(int idx, T val){
        idx += N-1;
        segtree_max[idx] = segtree_min[idx] = val;
        while(idx){
            idx = (idx-1)/2;
            segtree_max[idx] = max(segtree_max[idx*2+1],segtree_max[idx*2+2]);
            segtree_min[idx] = min(segtree_min[idx*2+1],segtree_min[idx*2+2]);
        }
    }
    T getmax(int a, int b) { return query_max(a,b,0,0,N); }
    T getmin(int a, int b) { return query_min(a,b,0,0,N); }
    T query_max(int a,int b,int k,int l,int r){
        if(r <= a || b <= l) return limit_min;
        if(a <= l && r <= b) return segtree_max[k];
        T vl = query_max(a,b,k*2+1,l,(l+r)/2);
        T vr = query_max(a,b,k*2+2,(l+r)/2,r);
        return max(vl,vr);
    }
    T query_min(int a,int b,int k,int l,int r){
        if(r <= a || b <= l) return limit_max;
        if(a <= l && r <= b) return segtree_min[k];
        T vl = query_min(a,b,k*2+1,l,(l+r)/2);
        T vr = query_min(a,b,k*2+2,(l+r)/2,r);
        return min(vl,vr);
    }
};


