void change(int id, int idx, int l, int r, int val)
{
    if(l+1==r)
    {
        seg[id]=val;
        return;
    }

    int mid=(l+r)/2;

    long long x1=inf,x2=inf;
    if(idx<mid)
        change(id*2, idx, l, mid, val);
    else
        change(id*2+1, idx, mid, r, val);

    seg[id]=min(seg[id*2],seg[id*2+1]);
}

int ask(int id, int L, int R, int l, int r)
{
    //cout<<L<<" "<<R<<" "<<l<<" "<<r<<" "<<seg[id]<<endl;
    if(l<=L && R<=r)
        return seg[id];

    int mid=(L+R)/2;
    long long   x1=inf,x2=inf;
    if(l<mid)
        x1=ask(id*2, L, mid, l, min(mid,r));
    if(r>mid)
        x2=ask(id*2+1, mid, R, max(mid,l), r);

    return min(x1,x2);
}

