#define RMQ_MAX ((1LL << 31) - 1)
template<typename T>
class RmqSparseTable{
public:
  RmqSparseTable(){}
  RmqSparseTable(const vector<T> &a){
    this->a = a;
    size = a.size();
    log_size = 1;
    for (int k = 1; k < size; k *= 2){
      log_size++;
    }
    rmq.resize(log_size, vector<int>(size, 0));
    for (int i = 0; i < size; i++){
      rmq[0][i] = i;
    }
    for (int i = 1; i < log_size; i++){
      for (int j = 0; j + (1 << i) - 1 < size; j++){
	int x = rmq[i - 1][j];
	int y = rmq[i - 1][j + (1 << (i - 1))];
	rmq[i][j] = a[x] <= a[y] ? x : y;
      }
    }
  }
  //O(NlogN)
  void build_table(const vector<T> &a){
    this->a = a;
    size = a.size();
    log_size = 1;
    for (int k = 1; k < size; k *= 2){
      log_size++;
    }
    rmq.resize(log_size, vector<int>(size, 0));
    for (int i = 0; i < size; i++){
      rmq[0][i] = i;
    }
    for (int i = 1; i < log_size; i++){
      for (int j = 0; j + (1 << i) - 1 < size; j++){
	int x = rmq[i - 1][j];
	int y = rmq[i - 1][j + (1 << (i - 1))];
	rmq[i][j] = a[x] <= a[y] ? x : y;
      }
    }
  }
  //O(N)
  void update(int index, T val){
    rmq[0][index] = index;
    a[index] = val;
    for (int i = 1; i < log_size; i++){
      for (int j = max(index - (1 << i) - 1, 0); j <= index; j++){
	if (j + (1 << i) - 1 >= size)break;
	int x = rmq[i - 1][j];
	int y = rmq[i - 1][j + (1 << (i - 1))];
	rmq[i][j] = a[x] <= a[y] ? x : y;
      }
    }
  }
  //range minimum query[i, j)
  //O(1)
  T query(int i, int j){
    int log_d = 31 - __builtin_clz(j - i);
    if (a[rmq[log_d][i]] <= a[rmq[log_d][j - (1 << log_d)]]){
      return rmq[log_d][i];
    }else{
      return rmq[log_d][j - (1 << log_d)];
    }
  }
  void show(){
    cerr << "--show--" << endl;
    for (int i = 0; i < rmq.size(); i++){
      for (int j = 0; j + (1 << i) -1 < rmq[i].size(); j++){
	cerr << a[rmq[i][j]] << " ";
      }
      cerr << endl;
    }
  }
private:
  int size;
  int log_size;
  vector<vector<T>> rmq;
  vector<T> a;
};
int N,Q;
vector<int> a;
int main(){
  scanf("%d %d", &N, &Q);
  a.resize(N, RMQ_MAX);
  int com,x,y;
  RmqSparseTable<int> rmq(a);
  for (int i = 0; i < Q; i++){
    scanf("%d %d %d", &com, &x, &y);
    if (com == 0){
      a[x] = y;
      rmq.update(x,y);
    }else{
      printf("%d\n", a[rmq.query(x, y + 1)]);
    }
  }


  return 0;
}

