        SegmentTree(vector<int> v)
        {
            int sz = v.size();
            n = 1;
            while (n < sz) {
                n *= 2;
            }
            node.resize(2 * n - 1, __INT32_MAX__);

            for (int i = 0; i < sz; i++) {
                node[n - 1 + i] = v[i];
