typedef long long int  ll;

const ll mod = 1e9+7;
const ll INF = 1e9;
const ll MAXN = 1e9;

ll seg_tree[MAXN];
ll a[MAXN];

void recalculate(ll node)  //get the current seg tree condition
{
	seg_tree[node] = min(seg_tree[2*node+1],seg_tree[2*node+2]);
}
void build_segtree(ll node,ll left,ll right)  //node = array's size
{
	if (left == right)  //we are in a leaf node
	{
		seg_tree[node] = pow(2,31)-1;
	}else
	{
		ll mid = (left+right)/2;
		build_segtree(2*node+1,left,mid);
		build_segtree(2*node+2,mid+1,right);
		recalculate(node);
	}
}

void update(ll node,ll left,ll right,ll x,ll y) //updete a[x] to y
{
	if (left == right)
	{
		seg_tree[left] = y;
	}else
	{
		ll mid = (left+right)/2;
		if (x <= mid)
		{
			update(node*2+1,left,mid,x,y);
		}else
		{
			update(node*2+2,mid+1,right,x,y);
		}
	}
}

ll query(ll node,ll left,ll right,ll x,ll y) // query for [x,y]
{
	if (x <= left && right <= y)
	{
		return seg_tree[node];
	}else
	{
		ll ans = INF;
		ll mid = (left+right)/2;
		if (mid <= x) //search left
		{
			ans = min(ans,query(node*2+1,left,mid,x,y));
		}
		if (mid+1 <= y) //search right
		{
			ans = min(ans,query(node*2+2,mid+1,right,x,y));
		}
		//else (x,y) ^ (left,right) = emptyset , so return -INF

		return ans;
	}
}



