    void update(std::size_t pos, T val){
        tree[len + pos] = val;
        for(pos = (len + pos) / 2; pos > 0; pos >>= 1){
            tree[pos] = op(tree[2 * pos], tree[2 * pos + 1]);
        }
    }

    T query(std::size_t left, std::size_t right){
        left += len;
        right += len;

        T v_l = e, v_r = e;
        while(left < right){
            if(left  & 1) v_l = op(v_l, tree[left++]);
            if(right & 1) v_r = op(tree[right - 1], v_r);
            left >>= 1;
            right >>= 1;
        }
        return op(v_l, v_r);
    }
};

int main(){
    int n, q, com, x, y;
    std::scanf("%d%d", &n, &q);
    segment_tree<int> st([](int x, int y){ return std::min(x, y); }, (1U << 31) - 1, n);

    for(int i = 0; i < q; ++i){
        std::scanf("%d%d%d", &com, &x, &y);
        if(com == 0){
            st.update(x, y);
        }else{
            std::printf("%d\n", st.query(x, y+1));
        }
    }

    return 0;
}

