template <class T> struct segment_tree_min_single_update{
    vector<T>arr;
    int size;
public:
    void init(const vector<T> &a){
        size=a.size();
        arr.resize(size*2-1);
        initialize(a,0,0,size-1);
        return ;
    }
    void set(T n,int SIZE){
        arr.resize(2*SIZE-1);
        size=SIZE;
        for(int i=0;i<arr.size();i++)arr[i]=n;
        return ;
    }
    void update(T n,int pos){
        add_val(n,0,0,size-1,pos);
        return ;
    }
    T find(int L,int R){
        return find_val(0,0,size-1,L,R);
    }
private:
    void initialize(const vector<T> &a,int now,int l,int r){
        if(l==r)arr[now]=a[l];
        else{
            int mid=(l+r)/2;
            initialize(a,now*2+1,l,mid);
            initialize(a,now*2+2,mid+1,r);
            arr[now]=min(arr[now*2+1],arr[now*2+2]);
        }
        return ;
    }
    void update_val(T n,int now,int l,int r,int pos){
        if(l>pos||r<pos)return ;
        if(l==r)arr[now]=n;
        int mid=(l+r)/2;
        update_val(n,now*2+1,l,mid,pos);
        update_val(n,now*2+2,mid+1,r,pos);
        arr[now]=min(arr[now*2+1],arr[now*2+2]);
        return ;
    }
    T find_val(int now,int l,int r,int L,int R){
        if(L>r||l>R)return INF;
        if(l>=L&&R>=r)return arr[now];
        int mid=(l+r)/2;
        return min(find_val(now*2+1,l,mid,L,R),find_val(now*2+2,mid+1,r,L,R));
    }
};
