int ans,n,tree[ TREE_N * 2 -1];

void update(int i,int x){
  i+=TREE_N-1;
  tree[i]=x;
  while(i>0){
    i=(i-1)/2;
    tree[i]=min(tree[i*2+1],tree[i*2+2]);
  }
}

void rec(int a,int b,int k=0,int l=0,int r=TREE_N){
  if((l<a&&a<r)||(l<b&&b<r)){
    int m=(l+r)/2;
    rec(a,b,k*2+1,l,m);
    rec(a,b,k*2+2,m,r);
  }else if(l<=a&&b<=r){
    if(ans>tree[k])ans=tree[k];
  }
}

