int num;

struct SegmentTree
{
    std::vector<int> segment;
    const int infval = std::numeric_limits<int>::max();

    SegmentTree(const int n)
    {
        Init(n);
    }

    void Init(const int n)
    {
        // サイズを 2 の累乗にして実装を簡単にする
        num = 1;
        while(num < n) num *= 2;
        segment.assign(2 * num - 1, infval);
    }

    void update(int index, int value)
    {
        // 葉のノード番号に変換
        index += num - 1;
        segment[index] = value;
        // 登りながら更新
        while(index > 0)
        {
            index = (index - 1) / 2;
            segment[index] = (std::min)(segment[2 * index + 1], segment[2 * index + 2]);
        }
    }

    // [first, last) の区間における最小値を返す
    // node , left , right は再帰呼び出しで必要となる引数
    // node : 節の番号, left, right : 節が対応している区間[left, right)
    int find(int first, int last, int node = 0, int left = 0, int right = num) const
    {
        // [first, last) が[left, right) と交差していない場合、inf を返す
        if (right <= first || last <= left) return infval;

        // [first, last) が [left, right) を完全に含んでいる場合、節に格納されている値を返す
        if (first <= left && right <= last) return segment[node];
        else
        {
            // 部分的に含んでいる場合は2つの子の最小値
            int vl = find(first, last, 2 * node + 1, left, (left + right) / 2);
            int vr = find(first, last, 2 * node + 2, (left + right) / 2, right);
            return (std::min)(vl, vr);
        }
    }
};

