#define INF 2147483647

struct RMQsq {

  /*　使い方まとめ　*/

  /*

  RMQsq myvec(n) // 宣言 nは必要な要素数
  myvec.at(i) // 配列のi番目にアクセス(0-index)
  myvec.update(i,k) // 配列のi番目をkに更新(0-index)
  myvec.rmin(i,j) // 配列の[i,j]の範囲の和を返す(0-index)

  myvec.debug() // 元データ配列とバケット配列を標準エラー出力

  */

  vector<int> data;
  vector<int> bucket;
  int sq;

  RMQsq(int n) { // 初期値はすべてINF
    sq = sqrt(n);
    if(sq*sq==n) sq--;
    sq++;
    data = Vi(sq*sq,INF);
    bucket = Vi(sq,INF);
  }

  int at(int k) {
    return data[k];
  }

  void update(int i,int k) {
    int ib = i/sq;
    data[i] = k;
    int minn = INF;
    int L = (i/sq)*sq,R = L+sq;
    rep(i,L,R){
      minn = min(minn,data[i]);
    }
    bucket[ib] = minn;
  }

  int rmin(int L,int R) { // [L,R]は範囲
    R++;
    int minn = INF;
    int dL,dR;

    rep(i,0,sq+1) {
      dL = i*sq,dR = (i+1)*sq; // [dL,dR]は小範囲

      if(dR <= L || R <= dL) continue; // 小範囲が完全に範囲外

      if(L <= dL && dR <= R) { // 小範囲が完全に範囲内
        minn = min(minn,bucket[i]);
      }

      else { // 小範囲が範囲と一部重なる
        rep(j,max(L,dL),min(R,dR)) {
          minn = min(minn,data[j]);
        }
      }
    }
    return minn;
  }

  void debug(){
    Verr(data);
    Verr(bucket);
  }

};


