	int64 e;
	MIN(int64 x = std::numeric_limits<int64>::max()) :e(x) {}
	MIN operator~() {
		return *this;
	}
	MIN operator+(const MIN &other) {
		if (e < other.e) return *this;
		return other;
	};
	MIN operator*(const MIN &other) {
		return other;
	}
};
int main() {
	std::ios::sync_with_stdio(false);
	std::cin.tie(0);
	uint32 n, q;
	std::cin >> n >> q;
	AVL<MIN> T;
	while (n--) {
		T = T.insert(0, MIN(2147483647));
	}
	uint32 c, x, y;
	while (q--) {
		//T.show();
		std::cin >> c >> x >> y;
		if (c) {
			std::cout << T.range(x, y + 1).e << "\n";
		}
		else {
			T = T.erase(x);
			//T.show();
			T = T.insert(x, MIN(y));
		}
	}
