const int H = 17;
const int N = 1 << H;
int L[N + 2], R[N + 2];

void update(int k, int v) {
  k++;
  int l = k;
  int r = k + 1;
  if (~k & 1) {
    L[r] = v;
  } else {
    R[l] = v;
  }
  for (int i = 0; i < H; i++) {
    if (~k & 1) {
      r += 1 << i;
    } else {
      l -= 1 << i;
    }
    k >>= 1;
    int m = l + r >> 1;
    if (~k & 1) {
      L[r] = min(L[m], R[m]);
    } else {
      R[l] = min(L[m], R[m]);
    }
  }
}

int query(int l, int r) {
  l++;
  r++;
  int res = INT_MAX;
  for (int i = r; i - (i & -i) >= l; i -= i & -i) {
    res = min(res, L[i]);
  }
  for (int i = l; i + (i & -i) <= r; i += i & -i) {
    res = min(res, R[i]);
  }
  return res;
}

int main() {
  int n, q;
  scanf("%d %d", &n, &q);
  for (int i = 0; i < n; i++) {
    update(i, INT_MAX);
  }
