#include <iostream>
#include <vector>
#include <algorithm>
#include <cmath>
using namespace std;

typedef long long ll;
const int INT_MAX = (1 << 31) - 1;

// RMQ
class SqrtDecomp{
    private:
        int N, sqrtN, K;
        vector<int> data;
        vector<int> min_bucket;
    public:
        SqrtDecomp(int N);
        void update(int i, int x);
        int query(int a, int b);
};

SqrtDecomp::SqrtDecomp(int n){
    N = n;
    sqrtN = ceil(sqrt(N));
    K = N / sqrtN + 1;
    for(int i=0; i<K*sqrtN; i++){
        data.push_back(INT_MAX);
    }
    for(int i=0; i<sqrtN; i++){
        min_bucket.push_back(INT_MAX);
    }
}

void SqrtDecomp::update(int i, int x){
    int b_idx = i / sqrtN;
    int l = b_idx*sqrtN, r = (b_idx+1)*sqrtN;
    data[i] = x;
    min_bucket[b_idx] = x;
    for(int j=l; j<r; j++){
        min_bucket[b_idx] = min(min_bucket[b_idx], data[j]);
    }

}

// [a, b)
int SqrtDecomp::query(int a, int b){
    int res = INT_MAX;
    for(int i=0; i<K; i++){
        int l = i*sqrtN, r = (i+1)*sqrtN;
        if (b <= l || r <= a) continue;
        else if (a <= l && r <= b){
            res = min(res, min_bucket[i]);
        }else{
            for(int j=max(a, l); j<min(b, r); j++) res = min(res, data[j]);
        }
    }
    return res;
}

int main(){
    int n, q; cin >> n >> q;
    SqrtDecomp sd(n);
    for(int i=0; i<q; i++){
        int com, x, y; cin >> com >> x >> y;
        if (com == 0) sd.update(x, y);
        else cout << sd.query(x, y+1) << endl;
    }
}

