#define loop(i,a,b) for(int i=a;i<int(b);i++)
#define rep(i,b) loop(i,0,b)

int const B = 1024;
template<class T>
struct RMQ {
    int n;
    enum : T { inf = INT_MAX };
    vector<T> Bmin;
    vector<vector<T>> dat;
    RMQ(int n_){
        n = n_;
        if(n%B) n += B-n%B;
        dat.assign(n/B,vector<T>(B,inf));
        Bmin.assign(n/B,inf);
    }
    void set(int k, T x){
        get(k) = x;
        Bmin[k/B] = inf;
        rep(i,B) Bmin[k/B] = min(Bmin[k/B], get(k/B*B+i));
    }
    int & get(int k){
        return dat[k/B][k%B];
    }
    int rmq(int l, int r){
        T res = inf;
        if(l/B != r/B){
            while(l%B) res = min(res, get(l++));
            while(r%B) res = min(res, get(--r));
            loop(i,l/B,r/B) res = min(res, Bmin[i]);
        } else {
            while(l<r) res = min(res, get(l++));
        }
        return res;
    }
};

int main(){
    int n,q;
    cin >> n >> q;
    RMQ<int> rmq(n);
    rep(i,q){
        int c,x,y;
        cin >> c >> x >> y;
        if(c) cout << rmq.rmq(x,y+1) << endl;
        else rmq.set(x,y);
    }
}

