struct SegTree
{
    vi dat;
    const int N;

    SegTree(int n): N(beki2(n)), dat(N*2+1, INF) {}

    void update(int i, int v)
    {
        dat[i+=N-1] = v;
        while (i > 0) {
            i = (i-1) / 2;
            dat[i] = min(dat[i*2+1], dat[i*2+2]);
        }
