#define RMQ_MAX ((1LL << 31) - 1)

template<typename T>
class RmqSparseTable{
public:
  RmqSparseTable(){}
  RmqSparseTable(const vector<T> &a){
    size = a.size();
    log_size = 1;
    for (int k = 1; k < size; k *= 2){
      log_size++;
    }
    for (int i = 0; i < log_size; i++){
      rmq[i].resize(size, 0);
    }
    //rmq.resize(log_size, vector<int>(size, 0));
    for (int i = 0; i < size; i++){
      rmq[0][i] = a[i];
    }
    for (int i = 1; i < log_size; i++){
      for (int j = 0; j + (1 << i) - 1 < size; j++){
	int x = rmq[i - 1][j];
	int y = rmq[i - 1][j + (1 << (i - 1))];
	rmq[i][j] = min(x, y);
      }
    }
  }
  //O(NlogN)
  void build_table(const vector<T> &a){
    size = a.size();
    log_size = 1;
    for (int k = 1; k < size; k *= 2){
      log_size++;
    }
    for (int i = 0; i < log_size; i++){
      rmq[i].resize(size, 0);
    }
    for (int i = 0; i < size; i++){
      rmq[0][i] = a[i];
    }
    for (int i = 1; i < log_size; i++){
      for (int j = 0; j + (1 << i) - 1 < size; j++){
	int x = rmq[i - 1][j];
	int y = rmq[i - 1][j + (1 << (i - 1))];
	rmq[i][j] = min(x, y);
      }
    }
  }
  //O(N)
  void update(const int& index, const T& val){
    rmq[0][index] = val;
    for (int i = 1; i < log_size; i++){
      for (int j = max(index - (1 << i) - 1, 0); j <= index; j++){
	if (j + (1 << i) - 1 >= size)break;
	int x = rmq[i - 1][j];
	int y = rmq[i - 1][j + (1 << (i - 1))];
	rmq[i][j] = min(x, y);
      }
    }
  }
  //range minimum query[i, j)
  //O(1)
  T query(const int& i, const int& j){
    int log_d = 31 - __builtin_clz(j - i);
    if (rmq[log_d][i] <= rmq[log_d][j - (1 << log_d)]){
      return rmq[log_d][i];
    }else{
      return rmq[log_d][j - (1 << log_d)];
    }
  }

  //---debug---
  void show(){
    cerr << "--show--" << endl;
    for (int i = 0; i < rmq.size(); i++){
      for (int j = 0; j + (1 << i) -1 < rmq[i].size(); j++){
	cerr << rmq[i][j] << " ";
      }
      cerr << endl;
    }
  }
private:
  int size;
  int log_size;
  vector<T> rmq[32];
};
int N,Q;
vector<int> a;
int main(){
  scanf("%d %d", &N, &Q);
  a.resize(N, RMQ_MAX);
  int com,x,y;
  RmqSparseTable<int> rmq(a);
  for (int i = 0; i < Q; i++){
    scanf("%d %d %d", &com, &x, &y);
    if (com == 0){
