void init(int* t){
	fill_n(t, (1 << 18) - 1, inf);
}

int updt(int* t, int i, int x, int k, int l, int r){
	if(r <= i || i < l){
		return t[k];
	}
	if(i <= l && r <= i + 1){
		return t[k] = x;
	}
	int m = (l + r) / 2;
	return t[k] = min(
		updt(t, i, x, 2 * k + 1, l, m),
		updt(t, i, x, 2 * k + 2, m, r)
	);
}
void updt(int* t, int i, int x){
	updt(t, i, x, 0, 0, n);
}

int qry(int* t, int a, int b, int k, int l, int r){
	if(r <= a || b <= l){
		return inf;
	}
	if(a <= l && r <= b){
		return t[k];
	}
	int m = (l + r) / 2;
	return min(
		qry(t, a, b, 2 * k + 1, l, m),
		qry(t, a, b, 2 * k + 2, m, r)
	);
}
int qry(int* t, int a, int b){
	return qry(t, a, b, 0, 0, n);
}

