	}
*/	int point_get(int a){
		int b = a / sz;
		return f(w[b], v[a]);
	}
	int range_get(int a, int b){
		int res = e;
		while(a < b && a % sz != 0){
			res = f(res, v[a]);
			++a;
		}
		while(a + sz <= b){
			res = f(res, w[a / sz]);
			a += sz;
		}
		while(a < b){
			res = f(res, v[a]);
			++a;
		}
		return res;
	}
};

