        n=1;
        while (n<_n) n*=2;
        dat.resize(2*n-1, INT_MAX);
    }

    void update(int k, int a) {
        k += n-1;
        dat[k] = a;
        while (k>0) {
            k = (k-1)/2;
            dat[k] = min(dat[k*2+1], dat[k*2+2]);
        }
