const int INF = INT32_MAX;

struct SegmentTree {
    vector<int> node;
    int n = 1;

    explicit SegmentTree(int sz) {
        while (n < sz) {
            n *= 2;
        }

        node.resize(2 * n - 1, INF);
    }

    void Update(int k, int a) {
        k += n - 1;
        node[k] = a;

        while (k > 0) {
            k = (k - 1) / 2;

            node[k] = min(node[k * 2 + 1], node[k * 2 + 2]);
        }
    }

    int GetMin(int a, int b, int k = 0, int l = 0, int r = -1) {
        if (r < 0) {
            r = n;
        }

        if (r <= a || b <= l) {
            return INF;
        }
        if (a <= l && r <= b) {
            return node[k];
        }

        int vl = GetMin(a, b, k * 2 + 1, l, (l + r) / 2);
        int vr = GetMin(a, b, k * 2 + 2, (l + r) / 2, r);
        return min(vl, vr);
    }

    int Node(int x) {
        return node[x + n - 1];
    }
};

