const int INF = (1LL << 31) - 1;


struct SegmentTree{
    int n;
    vector<int> value;
    int SIJK;

    SegmentTree(int N){
        SIJK = (1LL << 31) - 1; // compareの内容に応じて変える
        n = 1;
        while(n < N) n *= 2;
        value.assign(2 * n - 1, SIJK);
    }
    SegmentTree(vector<int> V){
        SIJK = (1LL << 31) - 1; // compareの内容に応じて変える
        n = 1;
        while(n < V.size()) n *= 2;
        value.assign(2 * n - 1, SIJK);
        rep(i, V.size()) value[i + n - 1] = V[i];
        for(int i = n - 2; i >= 0; i--){
            value[i] = compare(value[2 * i + 1], value[2 * i + 2]);
        }
    }

    int compare(int a, int b){
        return min(a, b); //問題に応じて変える
    }

    void update(int i, int x){
        i += n - 1;
        value[i] = x;
        while(i > 0){
            i = (i - 1)/2; // 親のノード
            value[i] = min(value[2 * i + 1], value[2 * i + 2]);
        }
    }

    int find(int a, int b, int k = 0, int l = 0, int r = -1){
        // [a, b) の区間に対するクエリについて
        // ノード k （区間 [l, r) 担当）が答える
        if(r < 0) r = n;
        if(r <= a || b <= l) return INF;
        if(a <= l && r <= b) return value[k];
        else{
            int m = (l + r) / 2;
            int tmp1 = find(a, b, 2 * k + 1, l, m);
            int tmp2 = find(a, b, 2 * k + 2, m, r);
            return compare(tmp1, tmp2);
        }
    }


};


