struct SegTree {
    int n;
    vi v;

    int pow2fit(int sz){
        int ret = 1;
        while(ret < sz) ret *= 2;
        return ret;
    }

    SegTree(int sz){
        n = pow2fit(sz);
        v = vi(2 * n - 1, inf);
    }

    // v[a] := x
    void update(int a, int x){
        int idx = n - 1 + a;
        v[idx] = x;

        while(idx > 0){
            idx = (idx - 1) / 2;
            chmin(v[idx], x);
        }
    }

    // get min [a, b)
    int getmin(int a, int b, int k = 0, int l = 0, int r = -1){
        if(r < 0) r = n;

        if(a >= r or l >= b) return inf;
        if(a <= l and r <= b) return v[k];

        return min(getmin(a, b, 2 * k + 1, l, (l + r) / 2),
                   getmin(a, b, 2 * k + 2, (l + r) / 2, r));
    }
};

