struct Node {
	int v;
	int i, j;
	int l, r;
};

static const int MAX = 100000;
static const int INFTY = (1 << 31) - 1;
int np;

Node T[2*MAX];

int makeSegmentTree(int l, int r) {
	int v = np++;
	int mid = (l + r) / 2;
	T[v].v = INFTY;
	T[v].i = l; T[v].j = r;
	if (l == r)return v;
	T[v].l = makeSegmentTree(l, mid);
	T[v].r = makeSegmentTree(mid + 1, r);
	return v;
}

int update(int v, int i, int x) {
	Node& node = T[v];
	if (node.i == node.j) {
		node.v = x;
		return x;
	}
	int mid = (node.i + node.j) / 2;
	if (i <= mid) {
		node.v = min(T[node.r].v, update(node.l, i, x));
	}
	else {
		node.v = min(T[node.l].v, update(node.r, i, x));
	}
	return node.v;
}

int findMin(int v, int i, int j) {
	if (i <= T[v].i && T[v].j <= j)return T[v].v;
	int minv = INFTY;
	int mid = (T[v].i + T[v].j) / 2;
	if (!(mid < i))minv = min(minv, findMin(T[v].l, i, j));
	if (mid < j)minv = min(minv, findMin(T[v].r, i, j));
	return minv;
}

int main() {
	int n, q;
	np = 0;
	scanf_s("%d %d", &n, &q);
	int root = makeSegmentTree(0, n - 1);
	int com, x, y;
	for (int i = 0; i < q; i++) {
		scanf_s("%d %d %d", &com, &x, &y);
		if (com == 0)update(root, x, y);
		else {
			int m = findMin(root, x, y);
			printf_s("%d\n", m);
		}
	}
	return 0;
}

