const int MAX_N = 1 << 17;
int n, q, data_min[2 * MAX_N - 1], data_max[2 * MAX_N - 1];

void init(int _n) {
    n = 1;
    while(n < _n) n *= 2;
    for(int i = 0; i < 2 * n - 1; ++i) data_min[i] = INT_MAX;
    for(int i = 0; i < 2 * n - 1; ++i) data_max[i] = INT_MIN;
}

void update(int k, int a) {
    k += n - 1;
    data_max[k] = data_min[k] = a;
    while(k > 0) {
	k = (k - 1) / 2;
	data_min[k] = min(data_min[k * 2 + 1], data_min[k * 2 + 2]);
	data_max[k] = max(data_max[k * 2 + 1], data_max[k * 2 + 2]);
    }
}

void query(int a, int b, int k, int l, int r, int& max_val, int& min_val) {
    int mid = (l + r) / 2;
    if(a <= l && r <= b) {
	max_val = data_max[k];
	min_val = data_min[k];
	return;
    } else if(b <= mid) {
	query(a, b, k * 2 + 1, l, (l + r) / 2, max_val, min_val);
    } else if(a > mid) {
	query(a, b, k * 2 + 2, (l + r) / 2 + 1, r, max_val, min_val);
    } else {
	int maxl, minl, maxr, minr;
	query(a, b, k * 2 + 1, l, (l + r) / 2, maxl, minl);
	query(a, b, k * 2 + 2, (l + r) / 2 + 1, r, maxr, minr);
	max_val = max(maxl, maxr);
	min_val = min(minl, minr);
    }
}


