template <typename Trait>
class SegmentTree {
public:
    /// ??????
    using T = typename Trait::value_type;

private:
    Trait m;
    std::vector<T> x;
    std::size_t size;

    void initialize(){
        for(int i = (int)size - 1; i >= 1; --i){
            x[i] = m(x[i * 2 + 0], x[i * 2 + 1]);
        }
    }

    T query(int ql, int qr, int k, int sl, int sr) const {
        if(sr <= ql || qr <= sl){ return m.id(); }
        if(ql <= sl && sr <= qr){ return x[k]; }
        const std::size_t sm = (sl + sr) / 2;
        const T vl = query(ql, qr, k * 2 + 0, sl, sm);
        const T vr = query(ql, qr, k * 2 + 1, sm, sr);
        return m(vl, vr);
    }

public:
    SegmentTree(std::size_t n = 0, const Trait &traits = Trait())
        : m(traits), size(1) {
        while(size < n){ size *= 2; }
        x.assign(size * 2, m.id());
        initialize();
    }

    template <typename Iterator>
    SegmentTree(Iterator first, Iterator last, const Trait &traits = Trait())
        : size(1), m(traits) {
        const std::size_t n = distance(first, last);
        while(size < n){ size *= 2; }
        x.resize(size * 2, m.default_value());
        copy(first, last, x.begin() + size);
        initialize();
    }

    void update(std::size_t i, const T &val){
        i += size;
        x[i] = val;
        while(i > 0){
            i /= 2;
            x[i] = m(x[i * 2 + 0], x[i * 2 + 1]);
        }
    }

    T query(std::size_t l, std::size_t r) const {
        return query(l, r, 1, 0, size);
    }

    T operator[](std::size_t i) const {
        return x[size + i];
    }
};

