/*
  Segment Tree
  区間に対する処理を O(log(n)) で行う
  下の例は RMQ

  コンストラクタ : binary_heap( 要素数 )
*/

#define L_CHILD(n)  (((n)<<1)+1)
#define R_CHILD(n)  (((n)<<1)+2)
#define PARERNT(n)  (((n)-1)>>1)
template<typename T>
struct segment_tree {
    vector<T> dat;
    int n;
    segment_tree(int size) {
        n = 1;
        while (n < size) n <<= 1;
        dat.assign(n << 1, inf);
    }

    const T& operator[](int i) const { return dat[i + n - 1]; }
    T& operator[](int i) { return dat[i + n - 1]; }

    void update(int k, const T& a){
        k += n - 1;
        dat[k] = a;
        while (k) {
            k = PARERNT(k);
            dat[k] = min(dat[L_CHILD(k)], dat[R_CHILD(k)]);
        }
    }

    const T query(int a, int b, int k = 0, int l = 0, int r = -1) const {
        if (r == -1) r = n;
        if (a <= l && r <= b){
            // [l, r) ⊂ [a, b)
            return dat[k];
        } else if (r <= a || b <= l){
            // [l, r) ∩ [a, b) = ?
            return inf;
        } else {
            // [l, r) ∩ [a, b) ≠ ?
            int center = (l + r) / 2;
            int vl = query(a, b, L_CHILD(k), l, center);
            int vr = query(a, b, R_CHILD(k), center, r);
            return min(vl, vr);
        }
    }
};

