#define Rep(i, n) for(int i=0;i<n;i++)
#define MAX_N (2<<17)
using namespace std;

int n, dat[2*MAX_N-1];

void init(int n_){
  n = 1;
  while(n < n_) n *= 2;
  Rep(i, 2*n-1) dat[i] = INT_MAX;
}

void update(int k, int a){
  int r = k+n-1;
  dat[r] = a;
  while(r > 0){
    r = (r-1)/2;
    dat[r] = min(dat[r*2+1], dat[r*2+2]);
  }
}

int rec(int a, int b, int k, int l, int r){
  if(r <= a || b <= l) return INT_MAX;

  if(a <= l && r <= b) return dat[k];
  else{
    int vl = rec(a, b, k*2+1, l, (l+r)/2);
    int vr = rec(a, b, k*2+2, (l+r)/2, r);
    return min(vl, vr);
  }
}

int query(int a, int b){
  return rec(a, b+1, 0, 0, n);
}

