				for(ll i = b; i < b + k; i++)
					mnn = min(mnn , ar[i]); 
			else if(b % k == k - 1) 
				for(ll i= b - k + 1; i <= b; i++) 
					mnn = min(mnn , ar[i]); 
			else 
				for(ll i = (b / k) * k;i < (b / k + 1) * k; i++) 
					mnn = min(mnn , ar[i]); 


