        arr.resize(a.size()+1);
        for(int i=1;i<arr.size();i++)arr[i]=a[i-1];
        for(int i=1;i<arr.size();i++)if(i+(i&-i)<arr.size())arr[i+(i&-i)]+=arr[i];
