std::vector<long long> create(int n, long long defaultValue) {
    int i = 1;
    while(i < n) i *= 2;
    return std::vector<long long>(2 * i - 1, defaultValue);
}

void update(std::vector<long long>& v, int i, long long data) {
    int n = (v.size() + 1) / 2;
    i += n - 1;
    v[i] = data;
    while(i > 0) {
        int p = (i - 1) / 2;
        v[p] = std::min(v[2 * p + 1], v[2 * p + 2]);
        i = p;
    }
}

long long queryImpl(const std::vector<long long>& v, int a, int b, int k, int l, int r, long long defaultValue) {
    if(r <= a || b <= l) return defaultValue;

    if(a <= l && r <= b) return v[k];
    else {
        auto vl = queryImpl(v, a, b, 2 * k + 1, l, (l + r) / 2, defaultValue);
        auto vr = queryImpl(v, a, b, 2 * k + 2, (l + r) / 2, r, defaultValue);
        return std::min(vl, vr);
    }
}

long long query(const std::vector<long long>& v, int a, int b, long long defaultValue) {
    return queryImpl(v, a, b, 0, 0, (v.size() + 1) / 2, defaultValue);
}

