    for(int i = 0 ; i < 2*N-1 ; i++){
      dat[i] = INF;
    }
  }

  void update(int i,int x){
    i += N-1; dat[i] = x; 
    while(i > 0){
      i = (i-1) / 2;
      dat[i] = min(dat[2*i+1],dat[2*i+2]);
    }
  }

  int find(int s,int t,int k,int l,int r){
    if(r <= s || t <= l) return INF;
    if(s <= l && r <= t) return dat[k];
    return min(find(s,t,2*k+1,l,(l+r)/2),find(s,t,2*k+2,(l+r)/2,r));
  }
};

