const ll INF = (1ll << 31)-1;
struct RMQ{
  vvi rmq;
  ll size;
  ll logsize;
  RMQ(ll size) : size(size){
    for(logsize=1;(1ll<<logsize)<logsize;logsize++);
    vvi rmq(logsize, vi(size,INF));
    swap(rmq, this->rmq);
  }
  ll find(ll s, ll t){
    ll ret=rmq[0][s];
    while(s<t){
      ll p; for(p=1;(1ll<<p)+s<t;p++); p--;
      ret=min(ret,rmq[p][s]);
      s += (1ll<<p);
    }
    return ret;

  }
  void update(ll i, ll x){
    rmq[0][i]=min(rmq[0][i],x);
    REP(j,logsize){
      ll p=(1ll<<j);
      rmq[j][i-(i%p)]=min(rmq[j][i-(i%p)],x);
    }
  }
};

int main(){
  ll n,q;cin>>n>>q;
  RMQ rmq(n);
  REP(i,q){
    ll com,x,y;cin>>com>>x>>y;
    if(com==0) rmq.update(x,y);
    else cout<<rmq.find(x,y)<<endl;
  }
}

