const ll YMAX = (1ll << 31) - 1;
vector<ll> dat;
int N;

void update(int k, int a) {
  k += N - 1;
  dat[k] = a;
  while (k > 0) {
    k = (k - 1) / 2;
    dat[k] = min(dat[k * 2 + 1], dat[k * 2 + 2]);
  }
}

int find(int a, int b, int k, int l, int r) {
  // [a, b) での最小値。[l, r) と節点kが対応
  if (r <= a || b <= l) return YMAX;
  if (a <= l && r <= b) return dat[k];
  else {
    int vl = find(a, b, k * 2 + 1, l, (l + r) / 2);
    int vr = find(a, b, k * 2 + 2, (l + r) / 2, r);
    return min(vl, vr);
  }
}

int main() {
  ios::sync_with_stdio(false);
  cin.tie(0);

  cin >> N;
  ll Q; cin >> Q;
  ll N_ = N;
  N = 1;
  while (N < N_) N *= 2;
  dat = vector<ll>(2 * N - 1, YMAX);

  for (ll i = 0; i < Q; i++) {
    int q, x, y;
    cin >> q >> x >> y;
    if (q == 0) {
      update(x, y);
    } else {
      int ans = find(x, y + 1, 0, 0, N);
      cout << ans << '\n';
    }
  }

  return 0;
}

