vector<int> data, backet;

int get(int l, int r) {
    int res = INT_MAX;
    for (int i = l; i <= r; ++i) {
        if (i % sqrtN == 0 && i + sqrtN <= r) {
            res = min(res, backet[i / sqrtN]);
            i += sqrtN - 1;
        } else {
            res = min(res, data[i]);
        }
    }
    return res;
}

