int get_left(int i, int n) {
  while (i < n)
    i <<= 1;
  return i - n;
}

int get_right(int i, int n) {
  i++;
  while (i <= n)
    i <<= 1;
  return i - n;
}

pair<int, int> get_range(int i, int n) {
  int fst = i;
  int snd = i + 1;
  while (fst < n)
    fst <<= 1;
  while (snd <= n)
    snd <<= 1;
  return make_pair(fst - n, snd - n);
}

void dump(vector<int> &st) {
  const int nn = st.size();
  int i, split = 1;

  for (i = 1; i < nn; i++) {
    if (i == (1 << split)) {
      cout << endl;
      split++;
    }
    cout << (st[i] == INT_MAX ? "inf" : to_string(st[i]));
    for (int j = 0; j < (nn >> split); j++) {
      cout << '\t';
    }
  }
  cout << endl;
}

void update(vector<int> &st, int i, int a) {
  const int nn = st.size();
  i += nn / 2;
  st[i] = a;

  for (;;) {
    i /= 2;
    st[i] = min(st[i * 2], st[i * 2 + 1]);
    if (i == 0)
      break;
  }
}

// return the mim in [l,r)
int find(vector<int> &st, int l, int r) {
  // assert(l<r);
  // cout << "find_min:" << make_pair(l, r) << endl;
  const int n = st.size() / 2;
  l += n;
  r += n;

  int current_min = INT_MAX;
  while (l < r) {
    while (1) {
      //  cout << get_range(l, n) << "\tl:" << l << endl;
      if (l & 1)
        break;
      l /= 2;
    }

    while (get_right(l, n) > r - n) {
      // cout << get_range(l, n) << endl;
      l <<= 1;
    }
    //  cout << get_range(l, n) << "\tl:" << l << endl;
    current_min = min(current_min, st[l]);
    l++;
    while (l <= n)
      l <<= 1;
  }
  return current_min;
}

int find2(vector<int> &st, int l, int r, int ll, int rr, int k) {
  // assert ( k > 0 );
  //cerr << make_pair(ll, rr) << endl;
  if (r <= ll || rr <= l || k < 1)
    return INT_MAX;

  if (l <= ll && rr <= r)
    return st[k];
  else {
    const int vr = find2(st, l, r, ll, (ll + rr) / 2, k * 2);
    const int vl = find2(st, l, r, (ll + rr) / 2, rr, k * 2 + 1);
    return min(vr, vl);
  }
}

