int find(int s, int t)
{
	int	start = (int)floor(s/range);
	int end = (int)floor(t/range);
	int min = a[s];

	for(int i=s; i<(start+1)*range; i++) 
		if(a[i]<min) min = a[i];
	for(int i=start+1; i<end; i++)
		if(sqra_min[i]<min) min = sqra_min[i];
	for(int i=end*range; i<=t; i++)
		if(a[i]<min) min = a[i];

	return min;
}

