#include <bits/stdc++.h>
#define REP(i, n) for (int i = 0; i < n; ++i)
#define REPR(i, n) for (int i = n - 1; i >= 0; --i)
#define FOR(i, a, b) for (int i = a; i < b; ++i)
#define FORR(i, a, b) for (int i = b - 1; i >= a; --i)
#define SORT(v) sort(v.begin(), v.end())
#define SORTR(v) sort(v.rbegin(), v.rend())
#define REV(v) reverse(v.begin(), v.end())
#define ITER(v) for (auto itr = v.begin(), itr != v.end(); ++itr)
#define LB(v, x) lower_bound(v.begin(), v.end(), x) - v.begin()
#define UB(v, x) upper_bound(v.begin(), v.end(), x) - v.begin()
#define SZ(v) (int)v.size()
using namespace std;
using ll = long long;
using P = pair<int, int>;

class SegmentTree {
    int n;
    const int e = INT_MAX;
    vector<int> node, lazy, lazy_flg;
    void eval(int k, int l, int r) {
        if (lazy_flg[k]) {
            lazy_flg[k] = false;
            node[k] = lazy[k];
            if (r - l > 1) {
                lazy_flg[2 * k] = lazy_flg[2 * k + 1] = true;
                lazy[2 * k] = lazy[2 * k + 1] = lazy[k];
            }
        }
    }

public:
    SegmentTree(const vector<int> &v) {
        int N = SZ(v);
        n = 1;
        while (n < N) n <<= 1;
        node.resize(2 * n, e);
        lazy.resize(2 * n);
        lazy_flg.resize(2 * n);
        REP(i, N) node[n + i] = v[i];
        for (int k = n - 1; k > 0; --k)
            node[k] = min(node[2 * k], node[2 * k + 1]);
    }
    void update(int a, int b, int x, int k = 1, int l = 0, int r = -1) {
        if (r < 0) r = n;
        eval(k, l, r);
        if (b <= l || r <= a) return;
        if (a <= l && r <= b) {
            lazy[k] = x;
            lazy_flg[k] = true;
            eval(k, l, r);
            return;
        }
        update(a, b, x, 2 * k, l, (l + r) / 2);
        update(a, b, x, 2 * k + 1, (l + r) / 2, r);
        node[k] = min(node[2 * k], node[2 * k + 1]);
    }
    int get(int a, int b, int k = 1, int l = 0, int r = -1) {
        if (r < 0) r = n;
        eval(k, l, r);
        if (b <= l || r <= a) return e;
        if (a <= l && r <= b) return node[k];
        return min(get(a, b, 2 * k, l, (l + r) / 2),
                   get(a, b, 2 * k + 1, (l + r) / 2, r));
    }
};

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);

    int n, q;
    cin >> n >> q;
    vector<int> a(n, INT_MAX);
    SegmentTree seg(a);
    REP(i, q) {
        int query;
        cin >> query;
        if (query == 0) {
            int i, x;
            cin >> i >> x;
            seg.update(i, i + 1, x);
        } else {
            int s, t;
            cin >> s >> t;
            cout << seg.get(s, t + 1) << endl;
        }
    }

    return 0;
}

