template<class M=int> class segnlmin {
    struct Node {
        Node *par, *left, *right;
        M v, laz;//合計
        Node(M e) : left(nullptr), right(nullptr), v(e), laz(e) {}
    };
    Node *root;
    int n, n0;
    M e = MAX(M);
    void eval(Node *n, int l, int r) {
        if (n->laz) {
            n->v += n->laz;
            if (r - l > 1) {
                if (!n->left) {
                    n->left = new Node(e);
                    n->left->par = n;
                }
                if (!n->right) {
                    n->right = new Node(e);
                    n->right->par = n;
                }
                n->left->laz += (n->laz) >> 1;
                n->right->laz += (n->laz) >> 1;
            }
            n->laz = 0;
        }
    }
    M f(M a, M b) { return min(a, b); }
    M get(int a, int b, Node *n, int l, int r) {
        eval(n, l, r);
        if (a <= l && r <= b) { return n->v; }
        if (r <= a || b <= l) { return e; }
        M lv = n->left ? get(a, b, n->left, l, (l + r) >> 1) : e;
        M rv = n->right ? get(a, b, n->right, (l + r) >> 1, r) : e;
        return f(lv, rv);
    }
    void add(int a, int b, M x, Node *n, int l, int r) {
        eval(n, l, r);
        if (r <= a || b <= l) { return; }
        if (a <= l && r <= b) {
            n->laz += (r - l) * x;
            eval(n, l, r);
        } else {
            if (!n->left) {
                n->left = new Node(e);
                n->left->par = n;
            }
            if (!n->right) {
                n->right = new Node(e);
                n->right->par = n;
            }
            add(a, b, x, n->left, l, (l + r) >> 1);
            add(a, b, x, n->right, (l + r) >> 1, r);
            n->v = f(n->left ? n->left->v : e, n->right ? n->right->v : e);
        }
    }
public:
    segnlmin(int n, M init = MAX(M)) : n(n), e(init) {
        n0 = 1;
        while (n0 < n) n0 <<= 1;
        root = new Node(e);
    }
    ~segnlmin() {
        delete root;
        root = nullptr;
    }
    void add(int a, int b, M x) { add(a, min(b, n0), x, root, 0, n0); }
    void add(int b = MAX(int)) { add(0, b); }
    void update(int k, M x) {
        M now = get(k, k + 1);
        add(k, k + 1, x - now);
    }
    M operator[](int i) { return get(i, i + 1); }
    M get(int a, int b) { return get(a, min(b, n0), root, 0, n0); }/*@formatter:on*/
    M get(int b = inf) { return get(0, b); }/*@formatter:on*/
};


