const ll INF = (1LL << 31) - 1LL;

struct SegmentTree {
private:
    int n;
    vector<ll> node;
public:
    SegmentTree(vector<ll>& v) {
        int size = v.size();
        n = 1;
        while (n < size) n *= 2;
        node.resize(2 * n - 1, INF);

        for (int i = 0; i < size; i++) {
            node.at(i + n - 1) = v.at(i);
        }
        for (int i = n - 2; i >= 0; i--) {
            node.at(i) = min(node.at(2 * i + 1), node.at(2 * i + 2));
        }
    }

    void update(int idx, int val) {
        int node_idx = idx + n - 1;
        node.at(node_idx) = val;
        int current_idx = node_idx;
        while (current_idx) {
            current_idx = (current_idx - 1) / 2;
            node.at(current_idx) = min(node.at(2 * current_idx + 1), node.at(2 * current_idx + 2));
        }
    }

    ll get_min(int query_left, int query_right, int cur_idx=0, int cur_left=0, int cur_right=-1) {
        if (cur_right < 0) cur_right = n;
        if (cur_right <= query_left || query_right <= cur_left) return INF;
        if (query_left <= cur_left && cur_right <= query_right) return node.at(cur_idx);
        ll val_from_left = get_min(query_left, query_right, 2 * cur_idx + 1, cur_left, (cur_left + cur_right) / 2);
        ll val_from_right = get_min(query_left, query_right, 2 * cur_idx + 2, (cur_left + cur_right) / 2, cur_right);
        return min(val_from_left, val_from_right);
    }
};


int main() {
    cin.tie(0); cout.tie(0);
    ios::sync_with_stdio(false);

    int n, q;
    cin >> n >> q;
    vector<ll> a_list(n, INF);
    SegmentTree segtree = SegmentTree(a_list);
    for (int i = 0; i < q; i++) {
        int op, x, y;
        cin >> op >> x >> y;
        if (op == 0) {
            segtree.update(x, y);
        }
        else {
            cout << segtree.get_min(x, y + 1) << "\n";
        }
    }
}

