void update(int x, int val)
{
    x += n - 1;
    data[x] = val;
    while (x > 0)
    {
        x = (x - 1) / 2;
        data[x] = min(data[x * 2 + 1], data[x * 2 + 2]);
    }
}

int find(int a, int b, int x, int l, int r)
{
    if (r <= a or b <= l)
        return INF;
    else if (a <= l and r <= b)
    {
        return data[x];
    }
    else
    {
        int vl, vr, nx;
        nx = x * 2;
        int m = (l + r) / 2;
        vl = find(a, b, nx + 1, l, m);
        vr = find(a, b, nx + 2, m, r);
        return min(vl, vr);
    }
}

