template<typename E> struct SegTree{
    using F=function<E(E,E)>;
    F f;//binary operation
    E Ei;//identity element
    int C=1;//capacity
    vector<E> D;
    SegTree(F f, E Ei): f(f),Ei(Ei) {}
    void init(const vector<E> &I){
        while(C<I.size()) C<<=1;
        D.resize(C*2);
        fill(D.begin(), D.end(),Ei);
        for(int i=0;i<I.size();i++) D[i+C]=I[i];
        for(int i=C-1;i>0;i--) D[i]=f(D[i*2],D[i*2+1]);
    }
    void update(int idx, E e){//0-indexed
        D[idx+=C]=e;
        while(idx>>=1) D[idx]=f(D[idx*2],D[idx*2+1]);
    }
    E query(int l,int r){//0-indexed, [l,r)
        E El=Ei, Er=Ei;
        for(l+=C,r+=C;l<r;l>>=1,r>>=1){
            if(l&1) El=f(El,D[l++]);
            if(r&1) Er=f(D[--r],Er);
        }
        return f(El,Er);
    }
};

