template <class M>
class segtree {
    private:
        //using value_type = typename M::value_type;
        typedef typename M::value_type value_type;
        value_type value;
        std::unique_ptr<segtree> lch, rch;
        int size;
        M append;
    public:
        segtree(int n) : value(M::init), size(n) {
            if (n <= 1) return;
            lch.reset(new segtree(n / 2));
            rch.reset(new segtree(n - n / 2));
        }
        value_type range_query(int a, int b) {
            if (a <= 0 && size <= b) return value;
            if (b <= 0 || size <= a) return M::init;
            int lsize = lch->size;
            auto left = lch->range_query(a, b),
                 right = rch->range_query(a - lsize, b - lsize);
            return append(left, right);
        }
        void update(int k, value_type x) {
            if (!lch && !rch) {
                value = x;
                return;
            }
            else if (k < lch->size) lch->update(k, x);
            else rch->update(k - lch->size, x);
            value = append(lch->value, rch->value);
        }
};

