class RMQ
{
    private:
        long long int elemnum;
        vector<long long int> result;

    public:
        RMQ(long long int n){
            elemnum = n;
            vector<long long int> tmp(2 * n, (long long int)pow(2, 31 - 1));
            result = tmp;
        }

        void addelem(long long int x, long long int value)
        {
            result[x + elemnum] = value;
            int tmp = (x + elemnum) / 2;
            while(tmp > 0){
                result[tmp] = min(result[tmp * 2], result[tmp * 2 + 1]);
                tmp = tmp / 2;
            }
        }

        long long int getminval(long long int targetl, long long int targetr, long long int nownum, long long int nowl, long long int nowr)
        {
            // cout << nowl << " " << nowr << endl;
            if(min(targetr, nowr) < max(targetl, nowl)) return (long long int)pow(2, 31 - 1);
            else if(targetl <= nowl && targetr >= nowr) return result[nownum];
            else {
                long long int tmp1 = getminval(targetl, targetr, 2 * nownum, nowl, (nowl + nowr) / 2);
                long long int tmp2 = getminval(targetl, targetr, 2 * nownum + 1, (nowl + nowr) / 2 + 1, nowr);
                return min(tmp1, tmp2);
            }
        }

        void printresult()
        {
            for(int i = 1; i < 2 * elemnum; i++){
                cout << result[i] << " ";
            }
            cout << endl;
        }

        int getelemnum()
        {
            return elemnum;
        }
};

int main()
{
    int n, q;
    cin >> n >> q;
    int tmp = 1;
    while(tmp < n) tmp = tmp * 2;
    RMQ ans = RMQ(tmp);
    for(int i = 0; i < q; i++){
        long long int com, x, y;
        cin >> com >> x >> y;
        if(com == 0){
            ans.addelem(x, y);
        } else {
            cout << ans.getminval(x, y, 1, 0, ans.getelemnum() - 1) << endl;
        }
        // ans.printresult();
    }
}

