void init(int N) {
	int btmsiz = 1;
	while (btmsiz < N) (btmsiz <<= 1);
	seg.btms = btmsiz;
	seg.trs = 2 * seg.btms - 1;
	for (int i = 0; i < seg.trs; i++) 
		seg.tree.push_back(inf);
	return;
}

void update(int id, int x) {
	id += seg.btms - 1;
	seg.tree[id] = x;
	while (id) {
		id = (id - 1) / 2;
		seg.tree[id] = min(seg.tree[id * 2 + 1], seg.tree[id * 2 + 2]);
	}
	return;
}

int RMQ(int l, int r, int nl, int nr, int nid) {
	if (l<=nl && nr<=r) {//completely wrapped
		return seg.tree[nid];
	}
	else if (nr<=l || r<=nl) {//conpletely unwrapped
		return inf;
	}
	else {
		int tmp;
		tmp = min(RMQ(l, r, nl, (nl + nr) / 2, nid * 2 + 1), 
			RMQ(l, r, (nl + nr) / 2, nr, nid * 2 + 2));
		return tmp;
	}
}

