  T _id;

 public:
  SegmentTree(const vector<T> &values, T id, function<T(T, T)> fn) : _id(id), _fn(move(fn)) {
    _size = values.size();
    _tree = vector<T>(_size * 2, _id);

    for (int i = 0; i < _size; i++) {
      _tree[i + _size] = values[i];
    }
    for (int i = _size - 1; i >= 1; i--) {
      _tree[i] = _fn(_tree[i << 1], _tree[i << 1 | 1]);
    }
  }

  /**
   * i 番目を value にする
   * @param i
   * @param value
   */
  auto update(int i, T value) -> void {
    assert(0 <= i && i < _size);

    i += _size;
    _tree[i] = value;
    i >>= 1;
    while (i > 0) {
      _tree[i] = _fn(_tree[i << 1], _tree[i << 1 | 1]);
      i >>= 1;
    }
  }

  /**
   * [l, r) に fn を適用した結果
   * @param l
   * @param r
   */
  auto query(int l, int r) -> T {
    assert(0 <= l && l < _size);
    assert(0 <= r && r <= _size);

    l += _size;
    r += _size;
    vector<T> ret, ret_r;
    while (0 < l && l < r) {
      if (l & 1) {
        ret.push_back(_tree[l++]);
      }
      if (r & 1) {
        ret_r.push_back(_tree[--r]);
      }
      l >>= 1;
      r >>= 1;
    }
    // ものいどは可換とは限らない
    reverse(ret_r.begin(), ret_r.end());
    ret.insert(ret.end(), ret_r.begin(), ret_r.end());
    return accumulate(ret.begin(), ret.end(), _id, _fn);
  }
};

