ll N,Q;


//与えられた要素数より大きくすること 配列範囲
const ll INT_INF = 1LL << 31;
//INF定義
const ll MAX_N = 1LL << 20;
ll n; //要素数が与えられた時、それ以上の最小の２＾k数が欲しい
ll dat[2*MAX_N - 1]; //RMQのサイズは２*MAX_N（ビットと混同しないように）

void init(ll a){
  n = 1;  while( n < a){ n *= 2;}
  for(ll i = 0; i < 2*n - 1 ; i++){
    dat[i] = INT_INF - 1;} // infで初期化,範囲外参照でREしやすいので注意
}
void update(ll k, ll a){
  k += n - 1;
  dat[k] = a;
  while( k > 0){
    k = ( k - 1)/ 2;
    dat[k] = min( dat[ 2* k + 1] , dat[2*k + 2]);}
}

//[a,b)での最小値を求める
// l , r　は　k番目のノードが[l,r)に対応していることを意味
ll query(ll a, ll b, ll k , ll l, ll r){
  if( r <= a || b <= l){ return INT_INF;}
  else if( a <= l && r <= b){ return dat[k];}
  else{
    ll vl = query(a,b,2*k + 1, l, ( l + r) / 2);
    ll vr = query(a, b, 2* k + 2, ( l + r) / 2, r);

  return min( vl, vr);}
}
