        }

        int rangemid = (rangebegin + rangeend) / 2;
        addvalrange(begin, end, e, ptr * 2 + 1, rangebegin, rangemid);
        addvalrange(begin, end, e, ptr * 2 + 2, rangemid, rangeend);

        int i1, i2;
        i1 = _geti(mintree, ptr * 2 + 1);
