        int r = getmaxrangeIdx(begin, end, ptr * 2 + 2, rangemid, rangeend);

        if (getval(l) >= getval(r))
            return l;
        else
            return r;
    }

    T getmaxrange(int begin, int end) {
        return getval(getmaxrangeIdx(begin, end));
    }
