#include <bits/stdc++.h>
using namespace std;

typedef long long lli;

const lli INF = (1LL << 31) - 1;
const int MAX_N = 1 << 17;

class LazySegTree{
  int n;
  lli dat[2*MAX_N-1], lazy[2*MAX_N-1];

public:
  LazySegTree(int _n = MAX_N){ 
    n = 1;
    while(n < _n) n *= 2;
    fill(dat,dat+2*n-1,INF);
    fill(lazy,lazy+2*n-1,INF);
  }

  void lazy_evaluate(int k){
    dat[k] = min(dat[k], lazy[k]); //
    if(k < n - 1){
      lazy[2*k+1] = min(lazy[2*k+1], lazy[k]); //
      lazy[2*k+2] = min(lazy[2*k+2], lazy[k]); //
    }
    lazy[k] = INF; //
  }

  void update(lli v, int a, int b){ update(v, a, b, 0, 0, n);}
  void update(lli v, int a, int b, int k, int l, int r){
    lazy_evaluate(k);

    if(a <= l && r <= b){
      lazy[k] = min(lazy[k], v); //
      lazy_evaluate(k);
    } else if(a < r && l < b){
      update(v, a, b, k*2+1, l, (l+r)/2);
      update(v, a, b, k*2+2, (l+r)/2, r);
      dat[k] = min(dat[2*k+1], dat[2*k+2]); //
    }
  }

  lli query(int a, int b){ return query(a, b, 0, 0, n);}
  lli query(int a, int b, int k, int l, int r){
    lazy_evaluate(k);

    if(r <= a || b <= l) return INF;
    else if(a <= l && r <= b) return dat[k];
    else {
      int v1 = query(a, b, k*2+1, l, (l+r)/2);
      int v2 = query(a, b, k*2+2, (l+r)/2, r);
      dat[k] = min(dat[2*k+1], dat[2*k+2]); //
      return min(v1, v2); //
    }
  }
};

