class RMQuery
{
public:
  int infty;
  int solve();
  void updateST( vector<int> &st, int ix );
  int findMin( vector<int> &st, int x, int y , int ix, int l, int r );
};

void RMQuery::updateST( vector<int> &st, int ix )
{
  if ( ix == 0 ) return;
  int p = (ix - 1) / 2;

  while ( true )
    {
      st[p] = min( st[2 * p + 1], st[2 * p + 2] );
      if ( p == 0 ) break;
      p = (p - 1) / 2;
    }

  return;
}

int RMQuery::findMin( vector<int> &st, int x, int y , int ix, int l, int r )
{
  if ( r <= x || y <= l ) return infty;
  if ( x <= l && r <= y )
    return st[ix];
  else
    return min( findMin( st, x, y, 2 * ix + 1, l, (l + r) / 2 ), findMin(st, x, y, 2 * ix + 2, (l + r) / 2, r ) );
  return 0;
}

int RMQuery::solve()
{

  int n, q, mn;

  cin >> n >> q;

  for ( mn = 1; mn < n; mn *= 2 );

  vector<int> st( 2 * mn , infty );

  for ( auto i = 0; i < q; ++i )
    {
      int com, x, y;
      cin >> com >> x >> y;
      if ( com == 0 )
        {
          st[ mn - 1 + x ] = y;
          updateST( st, mn - 1 + x );
        }
      else
        cout << findMin( st, x, y + 1, 0, 0, mn ) << endl;
    }

  return 0;
}

