#include <bits/stdc++.h>
using namespace std;

int N, Q;
int const INF = INT_MAX;
/*
AOJ DSL2_A
Range Minimum Query (RMQ)
数列 A = {a0,a1 ,...,an-1} に対し、次の２つの操作を行うプログラムを作成せよ。
update(i,x): aiをxに変更する。
find(s,t): as,as+1,...,atの最小値を出力する。
ただし、ai (i=0,1,...,n−1)は、231-1で初期化されているものとする。
入力
n q
com0 x0 y0
com1 x1 y1
...
comq−1 xq−1 yq−1
制約
1≤n≤100000
1≤q≤100000
comiが0のとき、0≤xi<n, 0≤yi<231−1
comiが1のとき、0≤xi<n, 0≤yi<n
入力例 1
3 5
0 0 1
0 1 2
0 2 3
1 0 2
1 1 2
出力例 1
1
2
*/
struct SegmentTree {
private:
    int n;
    vector<int> node;

public:
    SegmentTree(vector<int> v) {
        int sz = v.size();
        n = 1; while (n < sz) n *= 2;
        node.resize(2 * n - 1, INF);
        for (int i = 0; i < sz; i++) node[i + n - 1] = v[i];
        for (int i = n - 2; i >= 0; i--) node[i] = min(node[2 * i + 1], node[2 * i + 2]);
    }

    void update(int x, int val) {
        x += (n - 1);
        node[x] = val;
        while (x > 0) {
            x = (x - 1) / 2;
            node[x] = min(node[2 * x + 1], node[2 * x + 2]);
        }
    }

    int getmin(int a, int b, int k = 0, int l = 0, int r = -1) {
        if (r < 0) r = n;
        if (r <= a || b <= l) return INF;
        if (a <= l && r <= b) return node[k];

        int vl = getmin(a, b, 2 * k + 1, l, (l + r) / 2);
        int vr = getmin(a, b, 2 * k + 2, (l + r) / 2, r);
        return min(vl, vr);
    }
};

int main() {
    cin >> N >> Q;
    SegmentTree seg(vector<int>(N, INF));
    for (int i = 0; i < Q; i++) {
        int c, x, y; cin >> c >> x >> y;
        if (c == 0) seg.update(x, y);
        else cout << seg.getmin(x, y + 1) << endl;
    }
}

