/* SimpleSegTree(0-index) */

struct SimpleSegTree{
  typedef int Type;
  int segn2;
  Type initVal;
  vector<Type> data;
  function<Type(Type, Type)> merge;

  SimpleSegTree(function<Type(Type, Type)> merge, int n, int initVal):
    initVal(initVal), merge(merge)
  {
    for(segn2=1; segn2<n; segn2*=2);
    data.assign(segn2*2, initVal);
  }

  //get minimum value [a,b)
  Type query(int a, int b, int l = 0, int r = -1, int k = 0){
    if(r == -1) r = segn2;
    if(a <= l && r <= b) return data[k];
    if(r <= a || b <= l) return initVal;
    return merge(query(a,b,l,(l+r)/2,k*2+1),query(a,b,(l+r)/2,r,k*2+2));
  }

  //set kth number x
  void set(int k, Type x){
    k += segn2-1;
    data[k] = x;
    while(k > 0){
      k = (k-1)/2;
      data[k] = merge(data[k*2+1], data[k*2+2]);
    }
  }
};

#define RMinQ(n) SimpleSegTree([](SimpleSegTree::Type a, SimpleSegTree::Type b){ return min(a, b); }, n, INF);
#define RMaxQ(n) SimpleSegTree([](SimpleSegTree::Type a, SimpleSegTree::Type b){ return max(a, b); }, n, -INF);
#define RSumQ(n) SimpleSegTree([](SimpleSegTree::Type a, SimpleSegTree::Type b){ return a + b; }, n, 0);

