struct SegmentTree{
	vector<int> data;
	int sz;
	const int M0 = numeric_limits<int>::max();

	SegmentTree(int n){
		sz = 1;
		while(sz < n)	sz <<= 1;
		data.assign(sz << 1, M0);
	}

	void update(int i, int x){
		int k = sz + i;
		data[k] = x;
		while(k > 1){
			k >>= 1;
			data[k] = min(data[k << 1], data[k << 1 | 1]);
		}
	}

	int find(int a, int b, int k = 1, int l = 0, int r = -1){
		if(r == -1)	r = sz;
		if(b <= l || r <= a)	return M0;
		else if(a <= l && r <= b)	return data[k];
		else{
			return min(find(a, b, k << 1, l, (l + r) >> 1),
						find(a, b, k << 1 | 1, (l + r) >> 1, r));
		}
	}

	int operator[](const int& k) const{
		return data[sz + k];
	}
};

