template < typename T, typename M, typename = typename std::enable_if< std::is_base_of< Monoid< T >, M >::value > >
class SegmentTree
{
	const int N;
	std::vector< T > data;

public:
	SegmentTree( const int n ) : N( n ), data( 4 * N, M::identity() )
	{
		return;
	}

	SegmentTree( const std::vector< M > &src ) : N( src.size(), M::identity() )
	{
		init( src, 0, N );
		return;
	}

public:
	void update( const int p, const T &a )
	{
		return update( p, a, 0, 0, N );
	}

	T query( const int a, const int b )
	{
		return query( a, b, 0, 0, N );
	}

private:
	void init( const std::vector< T > &src, const int k, const int l, const int r )
	{
		if ( l + 1 == r )
		{
			data[k] = src[l];
			return;
		}

		const int mid = ( l + r ) / 2;
		init( src, k * 2 + 1, l, mid );
		init( src, k * 2 + 2, mid, r );
		data[k] = M::operation( data[ k * 2 + 1 ], data[ k * 2 + 2 ] );
		return;
	}

	void update( const int p, const T &a, const int k, const int l, const int r )
	{
		if ( !( l <= p && p < r ) )
		{
			return;
		}
		if ( l + 1 == r && l == p )
		{
			data[k] = a;
			return;
		}

		const int mid = ( l + r ) / 2;
		update( p, a, k * 2 + 1, l, mid );
		update( p, a, k * 2 + 2, mid, r );
		data[k] = M::operation( data[ k * 2 + 1 ], data[ k * 2 + 2 ] );
		return;
	}

	T query( const int a, const int b, const int k, const int l, const int r )
	{
		if ( a <= l && r <= b )
		{
			return data[k];
		}
		if ( b <= l || r <= a )
		{
			return M::identity();
		}

		const int mid = ( l + r ) / 2;
		return M::operation(
				query( a, b, k * 2 + 1, l, mid ),
				query( a, b, k * 2 + 2, mid, r )
				);
	}
};

