class RMQ {
	vector<ll> data;
	int size;
	int suffix;

public:
	RMQ() {}
	RMQ(int n) {
		suffix = -1;
		resize(n);
	}

	void resize(int n) {
		size = 1;
		while (size < n) {
			size <<= 1;
		}
		data.resize(size * 2 - 1, INFL);
	}

	ll& operator[](int i) {
		update();
		suffix = i;
		return data[i + size - 1];
	}

	void update() {
		if (suffix < 0)
			return;
		int k = suffix + size - 1;
		suffix = -1;
		while (k > 0) {
			k = (k - 1) / 2;
			data[k] = std::min(data[k * 2 + 1], data[k * 2 + 2]);
		}
	}

	ll min(int a, int b) {
		update();
		suffix = -1;
		return min(a, b, 0, 0, size);
	}

	ll min(int a, int b, int k, int l, int r) {
		if (r <= a || b <= l)
			return INFL;
		if (a <= l && r <= b)
			return data[k];
		int m = (l + r) / 2;
		return std::min(min(a, b, k * 2 + 1, l, m), min(a, b, k * 2 + 2, m, r));
	}
};

