int const inf = (1LL<<31)-1;
int const B = 1000;
struct RMQ {
    int n;
    vector<int> Bmin;
    vector<vector<int>> dat;
    RMQ(int n_){
        n = n_;
        while(n%B) n++;
        dat.assign(n/B,vector<int>(B,inf));
        Bmin.assign(n/B,inf);
    }
    void set(int idx, int x){
        Bmin[idx/B] = min(Bmin[idx/B], x);
        get(idx) = x;
    }
    int & get(int idx){
        return dat[idx/B][idx%B];
    }
    int rmq(int l, int r){
        int res = inf;
        if(l/B != r/B){
            while(l%B){
                res = min(res, get(l));
                l++;
            }
            while(r%B){
                r--;
                res = min(res, get(r));
            }
            while(l<r){
                res = min(res, Bmin[l/B]);
                l+=B;
            }
        } else {
            while(l<r){
                res = min(res, get(l));
                l++;
            }
        }
        return res;
    }
};

