void init(int idx, int left, int right){
	if(left == right) st[idx] = a[left];
	else {
		init(idx * 2, left, mid);
		init(idx * 2 + 1, mid + 1, right);
		st[idx] = min(st[2 * idx], st[2 * idx + 1]);
	}
}
void update(int idx, int left, int right, int pos, int val){
	if(left == right) st[idx] = val;
	else {
		if(pos > mid) update(2 * idx + 1, mid + 1, right, pos, val);
		else update(2 * idx, left, mid, pos, val);
		st[idx] = min(st[2 * idx], st[2 * idx + 1]);
	}
}
int query(int idx, int left, int right, int l, int r){
	if(l <= left && right <= r) return st[idx];
	if(l > right || r < left) return INTMAX;
	return min(query(2 * idx, left, mid, l, r), query(2 * idx + 1, mid + 1, right, l, r));
}
