template<typename M>
struct segment_tree {
    using monoid = M;
    using value_type = typename monoid::value_type;

    size_t size;
    vector<value_type> data;

    segment_tree(size_t n = 0) {
        size = 1;
        while(size < n) size *= 2;
        data.assign(size*2, monoid::id());
        //init();
    }

    template<typename InputIter>
    segment_tree(InputIter first, InputIter last) {
        size_t n = distance(first, last);
        size = 1;
        while(size < n) size *= 2;
        data.assign(size*2, monoid::id());
        copy(first, last, data.begin()+size);
        build();
    }

    void fill(const value_type& x) {
        data.assign(size*2, x);
        std::fill(data.begin()+size, data.end(), x);
        build();
    }

    template<typename Function>
    void init_with(Function f) {
        for(size_t i=0; i<size; ++i) {
            data[size+i] = f(i);
        }
        build();
    }


    void build() {
        for(size_t i = size - 1; i>0; --i) {
            data[i] = monoid::op(data[2*i], data[2*i+1]);
        }
    }

    void update(size_t i, const value_type& x) {
        data[i += size] = x;
        while(i/=2) {
            data[i] = monoid::op(data[2*i], data[2*i+1]);
        }
    }

    value_type accumulate(size_t l, size_t r) const {
        value_type al = monoid::id(), ar = monoid::id();
        for(l+=size, r+=size; l<r; l/=2, r/=2) {
            if(l&1) al = monoid::op(al, data[l++]);
            if(r&1) ar = monoid::op(data[--r], ar);
        }
        return monoid::op(al, ar);
    }

    value_type operator[](size_t i) const {
        return data[size+i];
    }

};

struct sum_monoid {
    using value_type = int;
    static constexpr value_type id() { return 0; }
    static constexpr value_type op(const value_type& lhs, const value_type& rhs) { return lhs + rhs; }
};

struct min_monoid {
    using value_type = int;
    static constexpr value_type id() { return numeric_limits<int>::max(); }
    static constexpr value_type op(const value_type& lhs, const value_type& rhs) { return min(lhs, rhs); }
};

using rsq = segment_tree<sum_monoid>;
using rmq = segment_tree<min_monoid>;

