template<typename T, typename F>
struct segment_tree {
    int n;
    F f;
    T zero;
    std::vector<T> data;
    segment_tree(int n, F f, const T &zero) : n(n), f(f), zero(zero), data(n << 1, zero) {}
    template<typename I> segment_tree(I begin, I end, const T &zero, F f) : n(end - begin), data(n << 1) {
        std::copy(begin, end, data.begin() + n);
        for (int i = n - 1; i > 0; i--) { data[i] = f(data[i << 1 | 0], data[i << 1 | 1]); }
    }
    void set(int i, const T &x) {
        assert(0 <= i && i < n);
        data[i += n] = x;
        while (i >>= 1) { data[i] = f(data[i << 1 | 0], data[i << 1 | 1]); }
    }
    T operator[](int i) const { return data[i + n]; }
    T get_sum(int l, int r, T zero) const {
        assert(0 <= l && l < n);
        assert(0 < r && r <= n);
        T a = zero, b = zero;
        for (l += n, r += n; l < r; l >>= 1, r >>= 1) {
            if (l & 1) { a = f(a, data[l++]); }
            if (r & 1) { b = f(data[--r], b); }
        }
        return f(a, b);
    }
};

