template<typename T>
class SegmentTree {
private:
    Int n;
    vector<T> node;
    T ident;
    T f(T x, T y) {
        return min(x, y);
    }
public:
    SegmentTree(vector<T> in, T identity_element) : n(in.size()), ident(identity_element) {
        node.resize(n * 2);
        rep(i, 0, n) node[n + i] = in[i];
        rrep(i, n, 1) node[i] = f(node[i<<1|0], node[i<<1|1]);
    }
    void update(Int i, T value) {
        i += n;
        node[i] = value;
        while (i > 1) {
            i >>= 1;
            node[i] = f(node[i<<1|0], node[i<<1|1]);
        }
    }
    T query(Int l, Int r) {
        T ret = ident;
        l += n, r += n;
        while (l < r) {
            if (l & 1) ret = f(ret, node[l++]);
            if (r & 1) ret = f(ret, node[--r]);
            l >>= 1, r >>= 1;
        }
        return ret;
    }
};

int main() {
