using namespace std;
class RMQ {
public:
    RMQ(int n, int v) {
        int i = 1;
        while(i < n){
            i *= 2;
        }
        tree = vector<int>(i*2-1, v);
        st_idx = i-1;
        s = i*2-1;
    };
    void update(int x, int v){
        int idx = x + st_idx;
        while(idx){
            if(tree[idx] > v){
                tree[idx] = v;
            }
            idx = (idx-1)/2;
        }
        tree[idx] = min(tree[idx], v);
    }
    int findMin(int l, int r){
        int minVal = (1 << 31) - 1;
        int idx_l = l + st_idx;
        int idx_r = r + st_idx;
        while(idx_l <= idx_r){
            if(idx_l == 0 && idx_r == 0){
                minVal = tree[0];
                break;
            }
            //cout << idx_l << ' ' << idx_r << ' ' << minVal << endl;
            if(idx_l%2 == 0){
                minVal = min(minVal, tree[idx_l]);
                idx_l /= 2;
            } else {
                idx_l = (idx_l-1)/2;
            }
            if(idx_r%2 == 1){
                minVal = min(minVal, tree[idx_r]);
                idx_r = (idx_r-2)/2;
            } else {
                idx_r = (idx_r-1)/2;
            }
        }
        return minVal;
    }
    void print(){
        for(int x : tree){
            cout << x << ' ';
        }
        cout << endl;
    }
private:
    vector<int> tree;
    int s;
    int st_idx;
};

int main(){
    int n, q;
    cin >> n >> q;
    RMQ rmq = RMQ(n, (1 << 31) - 1);
    int com, x, y;
    for(int i = 0; i < q; ++i){
        cin >> com >> x >> y;
        if(com){
            int v = rmq.findMin(x, y);
            cout << v << endl;
        } else {
            rmq.update(x, y);
         //   rmq.print();
        }
    }
}

