    std::cin >> n >> q;
    RMQ<long> rmq = RMQ<long>(std::pow(std::ceil(std::sqrt(n)), 2.0), (1LL << 31) - 1);
    REP(i, q) {
        std::cin >> c >> x >> y;
        if(c == 0) {
            rmq.update(x, y);
        } else {
            std::cout << rmq.find(x, y) << std::endl;
        }
    }
}

