template <typename T,typename E>
struct SegmentTree{
   using F=std::function<T(T,T)>;
   using G=std::function<T(T,E)>;

   int n;
   std::vector<T> dat;
   F f;
   G g;
   T d1;

   SegmentTree(){}
   SegmentTree(int n_,F f,G g,T d1):f(f),g(g),d1(d1)
   {
      n=1;
      while(n_>n) n<<=1;
      dat.assign(2*n,d1);
   }
   void set(int k,T x){
      dat[n+k]=x;
   }
   void build(){
      for(int i=n-1;i>=1;--i){
         dat[i]=f(dat[2*i],dat[2*i+1]);
      }
   }
   void change(int k,E x){
      k+=n;
      dat[k]=g(dat[k],x);
      while(k>>=1){
         dat[k]=f(dat[2*k],dat[2*k+1]);
      }
   }
   inline T query(int a,int b,int k=1,int l=0,int r=-1){
      if(r<0) r=n;
      if(b<=l||r<=a) return d1;
      if(a<=l&&r<=b) return dat[k];
      T vl=query(a,b,2*k,l,(l+r)/2);
      T vr=query(a,b,2*k+1,(l+r)/2,r);
      return f(vl,vr);
   }
};

