};





struct UnionFind //size-based
{
  vector<int> parent, treesize;

  UnionFind( int size ) : parent( size ) , treesize( size , 1 ) //constructor
  {
    for( int i = 0 ; i < size ; ++ i )
      {
	parent[i] = i;
      }
  }

  int root( int x )
  {
    if( parent[x] == x )
      {
	return x;
      }

    return parent[x] = root(parent[x]);
  }

  void unite( int x, int y )
  {
    x = root(x); 
    y = root(y);

    if( x == y )
      {
	return; 
      }

    if( treesize[x] < treesize[y] )
      {
	parent[x] = y;
	treesize[y] += treesize[x];
      }
    else
      {
	parent[y] = x;
	treesize[x] += treesize[y];	
      }

  }

  bool sametree( int x, int y )
  {
    return root(x) == root(y);
  }

  int gettreesize( int x )
  {
    return treesize[root(x)];
  }

};

template< typename Type_value >
struct SegmentTree //Range Minimum Query (RMQ)
{

private:
  int n;
  vector<Type_value> node;
  Type_value init_value_segtree;

public:
  SegmentTree( vector<Type_value> v, Type_value initial_value_segtree ) //constructor
  {
    int sz = v.size();
    init_value_segtree = initial_value_segtree;
    n = 1;
    while(n < sz)
      {
	n <<= 1;
      }

    node.resize(2*n-1, init_value_segtree);

    for( int i = 0 ; i < sz ; ++ i )
      {
	node[i+n-1] = v[i];
      }

    for( int i = n-2 ; i >= 0 ; -- i )
      {
	node[i] = min(node[2*i+1], node[2*i+2]);
      } 
  }

  void update(int x, Type_value val)
  {
    x += (n - 1);
    node[x] = val;

    while( x > 0 )
      {
	x = (x - 1) / 2;
	node[x] = min(node[2*x+1], node[2*x+2]);
      }
  }

  Type_value getmin( int a, int b, int k = 0, int l = 0, int r = -1 ) //getting minimum value in [a,b)
  {
    // k : index of the refered node
    // [l,r) : range covered by the k-th node 

    if( r < 0 )
      {
	r = n;
      } 
    if( r <= a or b <= l )
      {
	return init_value_segtree;
      } 
    if( a <= l and r <= b )
      {
	return node[k];
      }

    Type_value vl = getmin(a, b, 2*k+1, l, (l+r)/2);
    Type_value vr = getmin(a, b, 2*k+2, (l+r)/2, r);
    return min(vl, vr);
  }

};


