class SegmentTree {
private:
  int n;
  vi dat;

public:
  SegmentTree(int n) {
    this->n = 1;
    while (this->n < n) this->n *= 2;
    dat = vi(2 * this->n - 1, INT_MAX);
  }

  void update(int idx, int x)
  {
    idx = n + idx - 1;
    dat[idx] = x;

    while (idx > 0) {
      idx = (idx - 1) / 2;
      dat[idx] = min(dat[idx * 2 + 1], dat[idx * 2 + 2]);
    }
  }

  int query(int a, int b, int idx = 0, int l = 0, int r = INT_MIN)
  {
    if (r == INT_MIN) r = n;
    if (a >= r || l >= b) return INT_MAX;
    if (a <= l && r <= b) return dat[idx];

    int c = query(a, b, idx * 2 + 1, l, (l + r) / 2);
    int d = query(a, b, idx * 2 + 2, (l + r) / 2, r);
    return min(c, d);
  }
};

