struct SegTree{
    const ll INF = ll(pow(ll(2),ll(31))) - ll(1);
    //const ll INF=50;
    vector<ll> data;
    int data_num;
    SegTree(int n): data(){
        data_num=1;
        while(n!=0){
            n = n/2;
            data_num*=2;
        }
        data_num*=2;
        data_num--;
        rep(i,data_num) data.push_back(INF); 
    }

    void update(int i, ll x){
        i = (data_num+1)/2 -1 + i;
        data[i] = x;

        while(i>0){
            i = (i-1)/2;
            data[i]=min(data[i*2+1],data[i*2+2]);
        }
    }

    ll find(int s, int t){
        ll res = INF;
        s=(data_num+1)/2 -1 + s; t=(data_num+1)/2 -1 + t;
        res = min(res,data[s]); res = min(res,data[t]);
        while(t-s>1){
            s++; t--;
            t=(t-1)/2; s=(s-1)/2;
            res = min(res,data[s]); res = min(res,data[t]);
        }
        //cout << "min " << res << endl;
        return res;
    }

    void show(){
        //cout << "num " << data_num << endl;
        int layer=1;
        rep(i,data_num) {
            if(layer-1==i){
                layer*=2;
                cout << endl;
            }
            cout << data[i] << " ";
        }
        cout << endl;
    }

    void show_one(int k){
        cout << data[(data_num+1)/2 - 1 + k] << endl;
    }
};


