int n,q;
int st[MAX*2];

void init(){
  int tmp=1;
  while(tmp<n)tmp*=2;
  n=tmp;
  for(int i=0;i<n*2-1;i++)st[i]=INT_MAX;
}

void update(int k,int x){
  k+=n-1;
  st[k]=x;
  while(k>0){
    k=(k-1)/2;
    st[k]=min(st[k*2+1],st[k*2+2]);
  }
}

int find(int a,int b,int k,int l,int r){

  if(r<=a || b<=l)return INT_MAX;

  if(a<=l && r<=b)return st[k];

  int v1=find(a,b,k*2+1,l,(l+r)/2);
  int v2=find(a,b,k*2+2,(l+r)/2,r);
  return min(v1,v2);
}

