using namespace std;

template <typename T>
struct SegmentTree{
  typedef function<T(T,T)> F;
  int n;
  F f;
  T ti;
  vector<T> dat;

  SegmentTree(){}
  SegmentTree(F f,T ti):f(f), ti(ti) {}

  void init(int n_){
    n=1;
    while(n<n_) n<<=1;
    dat.assign(n<<1,ti);
  }

  void build(const vector<T> &v){
    int n_=v.size();
    init(n_);
    for(int i=0;i<n_;i++) dat[n+i]=v[i];
    for(int i=n-1;i;i--)
      dat[i]=f(dat[(i<<1)|0],dat[(i<<1)|1]);
  }

  void set_val(int k,T x){
    dat[k+=n]=x;
    while(k>>=1)
      dat[k]=f(dat[(k<<1)|0],dat[(k<<1)|1]);
  }

  T query(int a,int b){
    if(a>=b) return ti;
    T vl=ti,vr=ti;
    for(int l=a+n,r=b+n;l<r;l>>=1,r>>=1) {
      if(l&1) vl=f(vl,dat[l++]);
      if(r&1) vr=f(dat[--r],vr);
    }
    return f(vl,vr);
  }
};

int main() {
    int n, q;
    cin >>n>>q;
    SegmentTree<int> rmq([](int a, int b){return min(a, b);}, INT_MAX);
    rmq.init(n);
    for(int i=0;i<q;i++){
        int c, x, y;
        cin >> c >> x >> y;
        if(c) cout << rmq.query(x, y+1) << endl;
        else rmq.set_val(x, y);
    }
}

