template <typename T> struct RMQ{

    const ll NMAX = 1 << 17; // 131072
    const ll LL_MAX = 1e18 + 20;
    ll n;
    vector<T> dat;

    RMQ(ll _n){
        n = 1;
        // 2^pまでpaddingする
        while(n < _n) n *= 2;
        // 初期化
        dat.resize((2 * NMAX - 1), LL_MAX);
    }

    RMQ(ll _n, T _ini_val){
        n = 1;
        // 2^pまでpaddingする
        while(n < _n) n *= 2;
        // 初期化
        dat.resize((2 * NMAX - 1), LL_MAX);
        for(ll i = 0; i < 2 * n - 1; i++) dat[i] = _ini_val;
    }

    void update(ll k, T a){
        k += n - 1;
        dat[k] = a;
        while(k > 0){
            k = (k-1) / 2;
            dat[k] = min(dat[k * 2 + 1], dat[k * 2 + 2]);
        }
    }

    T query(ll a, ll b, ll k, ll l, ll r){
        // [a, b) の最小値を求める．
        // k := nodeの番号
        // kが[l, r)に対応している．
        // query(a, b, 0, 0, n)で外から呼ぶ

        // [a, b)と[l，r)が交差しないケース
        if(r <= a || b <= l){
            return LL_MAX;
        }

        if(a <= l && r <= b){
            // [a, b)を[l, r)含むケース
            return dat[k];
        }else{
            T vl = query(a, b, k * 2 + 1, l, (l + r) / 2);
            T vr = query(a, b, k * 2 + 2, (l + r) / 2, r);
            return min(vl, vr);
        }
    }

    T query(ll a, ll b){
        return query(a, b, 0, 0, n);
    }

};

int main(){
    ll N, Q;
    cin >> N >> Q;
    RMQ<ll> sg(N, (1LL<<31) - 1);
    rep(q, 0, Q){
        ll comm, x, y;
        cin >> comm >> x >> y;
        if(comm == 0) sg.update(x, y);
        else cout << sg.query(x, y+1) << endl;
    }
    return 0;
}

