template <typename T> class SegmentTree{
	public :
		SegmentTree(int size,T o,T(*func)(T,T)):out_of_range(o),op(func){
			n=1;
			while(n<size) n*=2;
			data=vector<T>(2*n,out_of_range);
			lazy=vector<bool>(2*n,false);
		}

		T update(int k,T x){
			assert(0<=k&&k<n);
			u(k,k+1,0,x,0,n);
		}

		T update(int a,int b,T x){
			assert(0<=a&&b<=n&&a<b);
			u(a,b,0,x,0,n);
		}

		T query(int a,int b){
			assert(0<=a&&b<=n&&a<b);
			return q(a,b,0,0,n);
		}

	private:
		vector<T> data;
		vector<bool> lazy;
		int n;
		const T out_of_range;
		T (*op)(T,T);

		inline void lazy_evaluate(int k){
			data[k*2+1]=data[k];lazy[k*2+1]=true;
			data[k*2+2]=data[k];lazy[k*2+2]=true;
			lazy[k]=false;
		}

		void u(int a,int b,int k,T x,int l,int r){
			if(r<=a || b<=l)
				return ;
			else if(a<=l&&r<=b){
				data[k]=x;
				lazy[k]=true;
			}else{
				if(lazy[k])
					lazy_evaluate(k);
				u(a,b,k*2+1,x,l,(l+r)/2);
				u(a,b,k*2+2,x,(l+r)/2,r);
				data[k]=op(data[k*2+1],data[k*2+2]);
			}
		}

		T q(int a,int b,int k,int l,int r){
			if(r<=a || b<=l)
				return out_of_range;
			else if(a<=l&&r<=b)
				return data[k];
 			else{
				if(lazy[k])
					return data[k];
				T vl = q(a,b,k*2+1,l,(l+r)/2);
				T vr = q(a,b,k*2+2,(l+r)/2,r);
				return op(vl,vr);
			}
		}
};

