class SegTree{

public:

	int n;
	vector<int> dat;
	vector<int> _kl;
	vector<int> _kr;

	int dummy = 2147483647;

	SegTree(int _n){
		init(_n);
	}

	void init(int n_){
		// set n
		n = 1;
		while(n < n_) n *=2;
        int nn = 2 * n - 1;

		// initialize vectors
		dat = vector<int>(nn * 2);
		_kl = vector<int>(nn * 2);
		_kr = vector<int>(nn * 2);

		// initialize kl, kr
		rep(k, nn){
			if(is_root(k)){
				_kl[k] = 0;
				_kr[k] = n;
			}
			else{
				if(is_cl(k)) {
					_kl[k] = _kl[pa(k)];
					_kr[k] = (_kl[pa(k)] + _kr[pa(k)]);
				}
				else{
					_kl[k] = (_kl[pa(k)] + _kr[pa(k)]);
					_kr[k] = _kr[pa(k)];
				}
			}
		}

		// initialize values
		rep(k, nn) dat[k] = dummy;
	}

	int pos(int i){ return i + n - 1; }
	int pa(int k){ return (k - 1) / 2; }
	int cl(int k){ return k * 2 + 1; }
	int cr(int k){ return k * 2 + 2; }
	bool is_root(int k){ return k == 0; }
	bool is_cl(int k){
		if(is_root(k)) return false;
		return cl(pa(k)) == k;
	}

	void update(int i, int a){
		int k = pos(i);
		dat[k] = a;
		while(!is_root(k)){
			k = pa(k);
			dat[k] = min(dat[cl(k)], dat[cr(k)]);
		}
	}

	int query(int il, int ir){
		return _query(il, ir, 0);
	}

	int _query(int il, int ir, int k){
		int kl = _kl[k];
		int kr = _kr[k];
		if(kr <= il || ir <= kl) return dummy;
		if(il <= kl && kr <= ir) return dat[k];
		else{
			int vl = _query(il, ir, cl(k));
			int vr = _query(il, ir, cr(k));
			return min(vl, vr);
		}
	}
};

