//セグメントツリー
//Range Minimum Query(RMQ)
//https://www.slideshare.net/iwiwi/ss-3578491
class SegmentTree {
	int leafNum;
	vector<int> tree;
	//戻り値：[a, b]の最小値
	//ノードkとkの区間l, r
	int query(int a, int b, int k, int l, int r) {
		if (r < a || l > b) return INF;			//kが[a,b]外
		if (l >= a && r <= b) return tree[k];	//kが[a,b]内
		int vl = query(a, b, k * 2 + 1, l, (l + r) / 2);		//左側のノードへ
		int vr = query(a, b, k * 2 + 2, (l + r + 1) / 2, r);	//右側のノードへ
		return min(vl, vr);
	}
public:
	SegmentTree(int n) {
		leafNum = maxbit(n * 2 - 1);
		tree.resize(leafNum * 2 - 1, INF);
	}
	void update(int idx, int x) {
		idx += leafNum - 1;
		tree[idx] = x;
		while (idx > 0) {
			idx = (idx - 1) / 2;
			tree[idx] = min(tree[idx * 2 + 1], tree[idx * 2 + 2]);
		}
	}
	int query(int a, int b) {
		return query(a, b, 0, 0, leafNum - 1);
	}
};


