// Segment Tree
// updateは0-indexed !!!
// 根 = 1
// iの親 = i>>1
// iの子供 = {i<<1, (i<<1)|1}
// iの兄弟 = i^1
// i番目の要素に相当するセグメント : dat[n+i]
typedef int data_t;
const data_t inf = ((1LL<<31)-1);
struct SegTree {
    vector<data_t> dat; int n;
    SegTree(int n_){
        int k = 1;
        while(k < n_) k<<=1;
        this->n = k;
        dat.assign(k*2, inf);
    }
    // 0-indexed !!!
    // ボトムアップ
    void update(int k, int x){
        int i = n + k; // leaf
        dat[i] = x;
        while(i != 1){ // 1 is root
            dat[i>>1] = min(dat[i], dat[i^1]);
            i>>=1;
        }
    }
    // 区間[a,b)の最小値を求める
    // kはセグメントの番号でl,rはそれが覆う開区間の両端
    // トップダウン
    data_t query(int a, int b, int k=1, int l=0, int r=-1){
        if(r == -1) r = n;
        if(r <= a || b <= l) return inf;
        if(a <= l && r <= b) return dat[k];
        int v1 = query(a, b, k<<1,   l,       (l+r)/2 );
        int v2 = query(a, b, k<<1|1, (l+r)/2, r       );
        return min(v1, v2);
    }
};

