const int MAX = 1 << 17;
T seg[MAX << 1];

void init_seg() {
	fill(seg, seg + (MAX << 1), id);
}
void init_seg(const vector<int>& v) {
	copy(v.begin(), v.end(), seg + MAX);
	for (int i = MAX - 1; i > 0; --i)
		seg[i] = op(seg[i << 1], seg[(i << 1) | 1]);
}
void init_seg(T val) {
	fill(seg + MAX, seg + (MAX << 1), val);
	for (int i = MAX - 1; i > 0; --i)
		seg[i] = op(seg[i << 1], seg[(i << 1) | 1]);
}

void update(int p, T val) {
	for (seg[p += MAX] = val; p > 1; p >>= 1) {
		seg[p >> 1] = op(seg[p], seg[p ^ 1]);
	}
}

T find(int l, int r) {
	T res1 = id, res2 = id;
	for (l += MAX, r += MAX; l < r; l >>= 1, r >>= 1) {
		if (l & 1) res1 = op(res1, seg[l++]);
		if (r & 1) res2 = op(seg[--r], res2);
	}
	return op(res1, res2);
}

