// 区間の更新と区間の最小値を返す O(Nlog(N)) で返す
// 最大値が欲しい場合は compare メソッド と INF を変更する
template <typename T>
class SegmentTree {
  using Fx = function<T(T, T)>;
  Fx fx;
  const T ex;
  int n;             // 最下段のノード数
  vector<T> node;

 public:
  SegmentTree(const vector<T>& v, Fx f, T e) : fx(f), ex(e) {
    int sz = v.size();
    n = 1;
    while (n < sz) n *= 2;      // N: 最下段の横幅
    node.resize(2 * n - 1, e);  // e で初期化

    // 最下段に値を挿入
    rep(i, sz) node[(n - 1) + i] = v[i];

    // 最下段以外を更新していく
    for (int i = n - 2; i >= 0; i--) {
      node[i] = fx(node[i * 2 + 1], node[i * 2 + 2]);
    }
  }

  void update(int i, T x) {
    i += n - 1;  // i 番目の葉のノード番号
    node[i] = x;
    while (i > 0) {
      i = (i - 1) / 2;  // ノード i の親ノードの番号に変える
      node[i] = fx(node[i * 2 + 1], node[i * 2 + 2]);  // 左右の子の min を計算し直す
    }
  }

  // [a, b) の区間に対するクエリについてノード k (区間 [l, r) 相当) が答える
  // 注意 [a, b) は半区間なので 区間 [m, n] の最小値を求めたい場合は find(m, n+1) とする
  T find(int a, int b, int k = 0, int l = 0, int r = -1) {
    if (r < 0) r = n;

    if (r <= a || b <= l) return ex;  // 区間がかぶらない場合は ex を返す
    if (a <= l && r <= b) {
      return node[k];  // ノード k の担当範囲がクエリ区間 [a, b) に完全に含まれる
    } else {
      int c1 = find(a, b, 2 * k + 1, l, (l + r) / 2);  // 左の子に値を聞く
      int c2 = find(a, b, 2 * k + 2, (l + r) / 2, r);  // 右の子に値を聞く
      return fx(c1, c2);
    }
  }
};

int main() {
  cin.tie(0);
  ios::sync_with_stdio(false);

  int n, q;
  cin >> n >> q;
  vector<int> v(n, int((1LL<<31)-1));
  auto f = [](int x1, int x2) -> int {return min(x1, x2);};
  SegmentTree<int> seg(v, f, (1LL<<31)-1);

  rep(i, q) {
    int cmd; cin >> cmd;
    if (cmd == 0) {
      int x, y; cin >> x >> y;
      seg.update(x, y);
    } else {
      int x, y; cin >> x >> y;
      cout << seg.find(x, y+1) << endl;
    }
  }

  return 0;
}

