template <typename T, class F = function<T(const T&, const T&)>>
class SegmentTree {
public:
  SegmentTree(size_t n, T i, F f) : identity(i), operation(f) {
    for (size = 1; size < n; size <<= 1) {}
    data.assign(size * 2, identity);
  }

  void update(size_t i, T value) {
    for (data[i += size] = value; i > 1; i >>= 1)
      data[i >> 1] = operation(data[i], data[i ^ 1]);
  }
  // [a,b)
  T query(size_t l, size_t r) {
    T res = identity;
    for (l += size, r += size; l < r; l >>= 1, r >>= 1) {
      if (l & 1) res = operation(res, data[l++]);
      if (r & 1) res = operation(res, data[--r]);
    }
    return res;
  }

private:
  size_t size;    // num of leaves
  vector<T> data; // root index is 1
  T identity;
  F operation;
};

