int find(int a,int b,int k, int l, int m) {

	if (m <= a || b <= l) {
		return INF;
	}
	if (a <= l && m <= b) {
		return dat[k];
	}
	int lv = find(a,b,k * 2 + 1,l, (l + m) / 2);
	int mv = find(a,b,k * 2 + 2,(l + m) / 2, m);
