struct LinearFunction { double a, b; };

struct Monoid {
  using T = LinearFunction;
  static T op(const T& lhs, const T& rhs) { return {lhs.a * rhs.a, lhs.a * rhs.b + lhs.b}; }
  static constexpr T e() { return {1, 0}; }
};

template<class Monoid> struct SegmentTree {
  using T = typename Monoid::T;
  struct node {
    lint l, r;
    T val = Monoid::e();
    unique_ptr<node> cl = nullptr, cr = nullptr;
  };

  lint n;
  unique_ptr<node> root;

  SegmentTree(lint n) : n(n), root(new node {0, n}) {}

  T get(lint l, lint r) {
    auto get = [&](auto get, const auto& v) -> T {
      if (l <= v->l and v->r <= r) return v->val;
      T resl = Monoid::e(), resr = Monoid::e();
      int m = v->l + v->r >> 1;
      if (l < m) {
        if (v->cl == nullptr) v->cl.reset(new node {v->l, m});
        resl = get(get, v->cl);
      }
      if (m < r) {
        if (v->cr == nullptr) v->cr.reset(new node {m, v->r});
        resr = get(get, v->cr);
      }
      return Monoid::op(resl, resr);
    };
    return get(get, root);
  }

  void set(lint i, const T& a) {
    auto set = [&](auto set, const auto& v) -> void {
      if (v->r - v->l == 1) {
        v->val = a;
        return;
      }
      int m = v->l + v->r >> 1;
      if (i < m) {
        if (v->cl == nullptr) v->cl.reset(new node {v->l, m});
        set(set, v->cl);
        v->val = Monoid::op(v->cl->val, v->cr != nullptr ? v->cr->val : Monoid::e());
      } else {
        if (v->cr == nullptr) v->cr.reset(new node {m, v->r});
        set(set, v->cr);
        v->val = Monoid::op(v->cl != nullptr ? v->cl->val : Monoid::e(), v->cr->val);
      }
    };
    set(set, root);
  }
};

int main() {
  cin.tie(nullptr); ios::sync_with_stdio(false);
  struct RMQ {
    using T = int;
    static T op(const T& lhs, const T& rhs) { return lhs < rhs ? lhs : rhs; }
    static constexpr T e() { return numeric_limits<T>::max(); };
  };
  int n, q; cin >> n >> q;
  SegmentTree<RMQ> st(n);
  for (int iq = 0; iq < q; ++iq) {
    int c, x, y; cin >> c >> x >> y;
    if (!c) st.set(x, y);
    else cout << st.get(x, y + 1) << '\n';
  }
}

