template<typename T> class SqrtDecomposition{
public:
    int N,B;
    vector<T> dat,bucket;
    const T e;
    T (*calc)(T,T);

    SqrtDecomposition(int N,T e = INF<T>(),T (*calc)(T,T) = [](T l,T r)->T{return min(l,r);}):N(N),B(sqrt(N)),e(e),calc(calc){
        dat=vector<T>(N,e);
        bucket=vector<T>(N/B+1,e);
    }
    inline T get(int v){return dat[v];}
    void set(int v,T a){
        dat[v]=a;

        bucket[v/B]=e;
        FOR(i,v/B*B,v/B*B+B) bucket[v/B]=calc(bucket[v/B],dat[i]);
    }
    //[a,b)
    T query(int a,int b){
        T res=e;
        // left,right
        while(a<b && a%B!=0)res=calc(res,dat[a]),a++;
        while(a<b && b%B!=0)b--,res=calc(res,dat[b]);

        FOR(i,a/B,b/B)res=calc(res,bucket[i]);

        return res;
    }
};

