template<class Monoid>
class SegmentTree {
    using Func = std::function<Monoid(Monoid, Monoid)>;
    int N;

    std::vector<Monoid> segment;

    const Func op;
    const Monoid id;

    bool dirty_flag;
public:
    // id : op = max なら -INT_MAX
    SegmentTree(int n, const Func biop, const Monoid& M1)
    : op(biop), id(M1), dirty_flag(false) {
        N = 1;
        while(N < n) N <<= 1;
        segment.assign(2 * N, id);
    }

    void set(int k, const Monoid &a){
        dirty_flag = true;
        segment[k + N] = a;
    }

    void build() {
        for (int k = N - 1; k > 0; --k) {
            segment[k] = op(segment[2 * k], segment[2 * k + 1]);
        } // end k
        dirty_flag = false;
    }

    void update(int k, const Monoid& a){
        k += N;
        segment[k] = a;
        while(k >>= 1){
            segment[k] = op(segment[k*2], segment[k*2+1]);
        }
    }

    // -> op [a, b)
    Monoid query(uint a, uint b){
        if(dirty_flag) build();
        dirty_flag = false;
        Monoid L = id, R = id;
        for (a += N, b += N; a < b; a >>= 1, b >>= 1) {
            if(a & 1) L = op(L, segment[a++]);
            if(b & 1) R = op(segment[--b], R);
        } // end i
        return op(L, R);
    }

    Monoid operator[](const int &k) const{
        return segment[k + N];
    }
};
int main(){
