using namespace std;

class RMQ
{
private:

	vector<long long> data; int size;

	long long find(int a, int b, int k, int l, int r);

public:

	static const long long INF = 1LL << 60;

	RMQ(int size_)
	{
		int x = (int)(ceil(log2(size_))) + 1;

		size = (int)(pow(2, x));

		data.resize(size * 2, INFTY);
	}

	void update(int i, long long x);

	long long query(int s, int t);
};

void RMQ::update(int i, long long x)
{
	i += size - 1;

	data[i] = x;

	while (i > 0)
	{
		i = (i - 1) / 2;

		data[i] = min(data[2 * i + 1], data[2 * i + 2]);
	}
}

long long RMQ::find(int a, int b, int k, int l, int r)
{
	if (r <= a || b <= l) { return INFTY; }

	if (a <= l && r <= b) { return data[k]; }

	else
	{
		long long vl = find(a, b, 2 * k + 1, l, (l + r) / 2);
		long long vr = find(a, b, 2 * k + 2, (l + r) / 2, r);

		return min(vl, vr);
	}
}

long long RMQ::query(int s, int t)
{
	return find(s, t, 0, 0, size);
}

