const int INF = 2147483647;

std::vector<int> value;
int N;

void update(int i, int x) {
  i += N - 1;
  value[i] = x;
  while (i > 0) {
    i = (i - 1) / 2;
    value[i] = std::min(value[2 * i + 1], value[2 * i + 2]);
  }
}

int query(int a, int b, int k, int l, int r) {
  // [l r)                [l r)
  //       [a b) or [a b)
  if (r <= a or b <= l)
    return INF;

  //      [l r)
  //   [a       b)
  else if (a <= l and r <= b)
    return value[k];

  else
    return std::min(query(a, b, 2 * k + 1, l, (l + r) / 2),
                    query(a, b, 2 * k + 2, (l + r) / 2, r));
}

int main() {
  int n, q;
  std::cin >> n >> q;
  N = 1;
  while (N < n)
    N *= 2;

  value = std::vector<int>(2 * N - 1, INF);

  for (int j = 0; j < q; ++j) {
    int c;
    std::cin >> c;

    // update
    if (c == 0) {
      int i, x;
      std::cin >> i >> x;
      update(i, x);
    }
    // query
    else {
      int s, t;
      std::cin >> s >> t;
      std::cout << query(s, t + 1, 0, 0, N) << std::endl;
    }
  }
}

