        int x=1;
        while(x<_size)x*=2;
        _size = x;
        dat.resize(_size*2);
    }

    void update(int m,T x){
        int i = m+_size;
        dat[i] = x;     //initialize
        for(; i!=1; i/=2){
            dat[i/2] = min(dat[i],dat[i^1]);    //minimum
        }
    }

