class UnionFind {
public:
	vector<int> parent;
	vector<int> rank;
	vector<int> v_size;

	UnionFind(int N) : parent(N), rank(N, 0), v_size(N, 1) {
		rep(i, N) {
			parent[i] = i;
		}
	}

	int root(int x) {
		if (parent[x] == x) return x;
		return parent[x] = root(parent[x]); //経路圧縮
	}

	void unite(int x, int y) {
		int rx = root(x);
		int ry = root(y);

		if (rx == ry) return; //xの根とyの根が同じなので、何もしない。
		if (rank[rx] < rank[ry]) {
			parent[rx] = ry;
			v_size[ry] += v_size[rx];
		}
		else {
			parent[ry] = rx;
			v_size[rx] += v_size[ry];
			if (rank[rx] == rank[ry]) rank[rx]++;
		}
	}

	bool same(int x, int y) {
		return (root(x) == root(y));
	}

	int count_tree() {
		int N = parent.size();
		int res = 0;

		rep(i, N) {
			if (root(i) == i) res++;
		}

		return res;
	}

	int size(int x) {
		return v_size[root(x)];
	}
};




class wUnionFind {
public:
	vector<int> parent;
	vector<int> diff_weight; //親との差分。
	vector<int> rank;

	wUnionFind(int N) : parent(N), diff_weight(N, 0), rank(N, 0) {
		rep(i, N) {
			parent.at(i) = i;
		}
	}

	int root(int x) {
		if (parent.at(x) == x) return x;

		int r = root(parent.at(x));
		diff_weight.at(x) += diff_weight.at(parent.at(x)); //累積和
		return parent.at(x) = r;
	}

	//x の重みを出力する関数。
	int weight(int x) {
		root(x);
		return diff_weight.at(x);
	}

	//weight.at(y) - weight.at(x) == w となるようにする。
	bool unite(int x, int y, int w) {
		int rx = root(x);
		int ry = root(y);
		int diff_weight_to_ry_from_rx = w + weight(x) - weight(y);

		if (rx == ry) return false; //xの根とyの根が同じなので、何もしない。
		if (rank.at(rx) < rank.at(ry)) {
			parent.at(rx) = ry;
			diff_weight.at(rx) = -diff_weight_to_ry_from_rx;
		}
		else {
			parent.at(ry) = rx;
			diff_weight.at(ry) = diff_weight_to_ry_from_rx;
			if (rank.at(rx) == rank.at(ry)) rank.at(rx)++;
		}

		return true;
	}

	bool same(int x, int y) {
		return (root(x) == root(y));
	}

	int count_tree() {
		int N = parent.size();
		int res = 0;

		rep(i, N) {
			if (root(i) == i) res++;
		}

		return res;
	}
};




class SegmentTree {
public:
	int ini = INF;
	int Size;  //対象の配列サイズ以上の2冪。
	vector<int> node;

	SegmentTree(int N) : Size(N), node(N) { initialize(N); }
	SegmentTree(int N, int ini) : ini(ini), Size(N), node(N) { initialize(N); }
	SegmentTree(vector<int> v) : Size(v.size()), node(v.size()) { initialize(v); }
	SegmentTree(vector<int> v, int ini) : ini(ini), Size(v.size()), node(v.size()) { initialize(v); }


	//初期化
	void initialize(int N) {
		int new_N = 1;
		while (new_N < N) new_N *= 2;

		Size = new_N;
		node.assign(2 * Size - 1, ini);
	}

	//初期化
	void initialize(vector<int> v) {
		int new_N = 1;
		while (new_N < (int)v.size()) new_N *= 2;

		Size = new_N;
		node.assign(2 * Size - 1, ini);

		//葉の初期化 (nodeの後ろに入れる, 二分木の一番下)
		for (int i = 0; i < (int)v.size(); i++) node.at(Size - 1 + i) = v.at(i);

		//上りながら初期化 (0-indexedの場合、例えば、3 の子は、7, 8)
		//!!!!!!!!!!!!!問題に合わせて定義する!!!!!!!!!!!!!
		for (int i = Size - 2; i >= 0; i--) {
			node.at(i) = min(node.at(2 * i + 1), node.at(2 * i + 2));
		}
	}


	// k 番目の値 (0-indexed) を x に変更する。
	void update(int k, int x) {
		//葉のノードの番号 (等比数列の和の公式)
		k += Size - 1;
		node.at(k) = x;

		//上りながら更新 (0-indexedの場合、例えば、3 の子は、7, 8)
		while (k > 0) {
			k = (k - 1) / 2;

			//子の最小値を親の最小値とする。
			//!!!!!!!!!!!!!問題に合わせて定義する!!!!!!!!!!!!!
			node.at(k) = min(node.at(k * 2 + 1), node.at(k * 2 + 2));
		}
	}


	//[a, b) の、例えば最小値を計算する。[l, r) は、ノード k に対応する区間を与える。
	//query_sub(a, b, 0, 0, Size) で呼べばよい。
	//!!!!!!!!!!!!!問題に合わせて定義する!!!!!!!!!!!!!
	int query_sub(int a, int b, int k, int l, int r) {
		if (r <= a || b <= l) return ini;  // 交差しない。
		if (a <= l && r <= b) return node.at(k); // 完全に含む。
		else {
			int vl = query_sub(a, b, k * 2 + 1, l, (l + r) / 2);
			int vr = query_sub(a, b, k * 2 + 2, (l + r) / 2, r);
			return min(vl, vr);
		}

	}

	//[a, b) の、例えば最小値を計算する。
	int query(int a, int b) {return query_sub(a, b, 0, 0, Size);}
};




//転倒数を返す (comp = less_equal<int>() の場合)。
//comp = greater<int>() の場合は、N_C_2 - 転倒数 を返すことになる。
int my_merge(vector<int>& A, vector<int>& B, int left, int mid, int right, function <bool(int, int)> comp) {
	int i = left; //Aを分割したときの、左側の配列を差す添え字。
	int j = mid;  //Aを分割したときの、右側の配列を差す添え字。
	int k = 0;  //分割した後の配列 (一時的に) B に保存。

	int res = 0;

	while (i < mid && j < right) {
		if (comp(A.at(i), A.at(j))) B.at(k++) = A.at(i++);
		else {
			B.at(k++) = A.at(j++);
			res += mid - i;
		}
	}

	//左側をBに移動し尽くしたので、右側を順に入れていく。
	if (i == mid) {
		while (j < right) {
			B.at(k++) = A.at(j++);
		}
	}
	else { //右側をBに移動し尽くしたので、左側を順に入れていく。
		while (i < mid) {
			B.at(k++) = A.at(i++);
		}
	}

	//Aに値を戻す。
	rep(l, k) {
		A.at(left + l) = B.at(l);
	}

	return res;
}


int my_merge_sort(vector<int>& target, vector<int>& tempo, int left, int right, function <bool(int, int)> comp) {

	int mid, res = 0;
	if (left == right || left == right - 1) return res;

	mid = (left + right) / 2;
	res += my_merge_sort(target, tempo, left, mid, comp);
	res += my_merge_sort(target, tempo, mid, right, comp);
	res += my_merge(target, tempo, left, mid, right, comp);
	return res;
}


int my_merge_sort(vector<int>& target, vector<int>& tempo, int left, int right) {
	return my_merge_sort(target, tempo, left, right, less_equal<int>());
}





ld calc_dist(int x1, int x2, int y1, int y2) {
