//ラングレス圧縮
vector<pair<int, char>> compress(string S) {
	int N = S.size();
	vector<pair<int, char>> memo;

	int tempo = 1;
	for (int i = 1; i < N; i++) {
		if (i != N - 1) {
			if (S.at(i) == S.at(i - 1)) tempo++;
			else {
				memo.push_back(MP(tempo, S.at(i - 1)));
				tempo = 1;
			}
		}
		else {
			if (S.at(i) == S.at(i - 1)) {
				tempo++;
				memo.push_back(MP(tempo, S.at(i - 1)));
			}
			else {
				memo.push_back(MP(tempo, S.at(i - 1)));
				memo.push_back(MP(1, S.at(i)));
			}
		}
	}

	return memo;
}




//平方分割
class SqrtDecomposition {
public:
	int ini = INF;  //初期値

	int N = 1;  //元の配列のサイズ (data)
	int width = 1; // ~ sqrt(N)
	int size = 1;  // 平方分割した後の、bucket vector のサイズ。

	vector<int> data;  //対象の配列
	vector<int> bucket;  //平方分割した後のバケット

	//コンストラクタ
	SqrtDecomposition(int N) : N(N), width(sqrt(N)), data(N) {
		size = N / width + 1;
		if (N % width == 0) size--;
		data.assign(N, ini);
		bucket.assign(size, ini);
	}

	//ベクトルでコンストラクト。
	SqrtDecomposition(vector<int> data) : N((int)data.size()), width(sqrt((int)data.size())), data(data) { initialize(); }

	//ベクトルと、問題に合わせた初期値でコンストラクト。
	SqrtDecomposition(vector<int> data, int ini) : ini(ini), N((int)data.size()), width(sqrt((int)data.size())), data(data) { initialize(); }


	//バケットの初期化
	void initialize() {
		size = N / width + 1;
		if (N % width == 0) size--;
		bucket.assign(size, ini);

		for (int i = 0; i < size; i++) {
			CalcBucket(i);
		}
	}


	//data[n] を x に変更
	void update(int n, int x) {
		data[n] = x;
		int tempo = n / width;
		CalcBucket(tempo);
	}


	//区間に対する更新クエリ (足す場合)
	//問題に応じて定義する。
	void add(int l, int r, int x) {
		int lb = l / width + 1;
		if (l % width == 0) lb--;
		int rb = r / width;

		if (lb < rb) {
			for (int i = lb; i < rb; i++) {
				bucket[i] += x;
			}
			for (int i = l; i < lb * width && i < r; i++) {
				data[i] += x;
			}
			for (int i = max(rb * width, l); i < r; i++) {
				data[i] += x;
			}
		}
		else {
			for (int i = l; i < r; i++) {
				data[i] += x;
			}
		}
	}


	//findクエリ (最小値の場合)。[l, r)
	//問題に応じて定義する。
	int find(int l, int r) {
		int lb = l / width + 1;
		if (l % width == 0) lb--;
		int rb = r / width;

		int res = ini;
		if (lb < rb) {
			for (int i = lb; i < rb; i++) {
				res = min(res, bucket[i]);
			}
			for (int i = l; i < lb * width && i < r; i++) {
				res = min(res, data[i]);
			}
			for (int i = max(rb * width, l); i < r; i++) {
				res = min(res, data[i]);
			}
		}
		else {
			for (int i = l; i < r; i++) {
				res = min(res, data[i]);
			}
		}

		return res;
	}


	//n番目のバケットを計算 (最小値の場合)
	//!!!!!!!!!!!!!問題に合わせて定義する!!!!!!!!!!!!!
	void CalcBucket(int n) {
		bucket[n] = ini;
		for (int i = n * width; i < (n + 1) * width && i < N; i++) {
			bucket[n] = min(bucket[n], data[i]);
		}
	}


	//デバッグ用。表示。
	void DataShow() {
		rep(i, N) cout << data[i] << endl;
	}

	void BucketShow() {
		rep(i, size) cout << bucket[i] << endl;
	}

};




signed main() {
	int N, Q;
	cin >> N >> Q;

	int M = (1LL << 31) - 1;
	vector<int> a(N, M);
	SqrtDecomposition memo(a, M);

	rep(q, Q) {
		int com, x, y;
		cin >> com >> x >> y;

		if (com == 0) {
			memo.update(x, y);
		}
		else {
			int res = memo.find(x, y + 1);
			cout << res << endl;
		}

	}


}

