int main() {
    ll N,Q;
    cin >> N >> Q;
    SegmentTree seg(vector<ll>(N,INF));
    for(int i=0;i<Q;i++){
        ll c;
        cin >> c;
        ll x,y;
        cin >> x >> y;
        if(c==0) seg.update(x,y);
        else cout << seg.find(x,y+1) << endl;
    }

    return 0;
}

