// セグ木
template<typename T,typename F,T UNIT>
struct ST{
  int size;
  vector<T> seg;
  F func;
  vector<int> seg_sz;

  ST(const vector<T> &v,F func) : func(func){
    // initialize
    seg.resize( ( size = v.size() ) << 1 , UNIT);
    // set
    // n A[n]まで見た
    int n = 0; seg_sz.pb(0);
    while(n < size){
      // これからm個の配列を埋める
      int m = 1 << (31 - __builtin_clz(size ^ n) );
      for(int i = n; i < n + m; i++){
        //trc(n , m , i);
        seg[n + m + i] = v[i];
      }
      seg_sz.pb( (n += m) );
    }
    //
    build();
  }

  void build(){
    vector<int>::const_iterator it = seg_sz.begin();
    while(1){
      int l = *(it++);
      if(it == seg_sz.end()) return;
      int r = *it;
      const int dif = l << 1; // k 添え字のズレ
      for( int i = r - l - 1; i > 0; i-- ){
        seg[dif | i] = func(seg[dif | (i << 1)] , seg[dif | (i << 1) | 1]);
      }
    }    
  }

  void update(int k, T& x){
    vector<int>::const_iterator it = upper_bound(seg_sz.begin() , seg_sz.end() , k);
    seg[ (k += *it) ] = x; 
    it--; k -= (*it) << 1; const int dif = (*it) << 1;
    //trc(k , dif);
    // [*it , *(it + 1) ) 間のセグ木を更新 添え字はdifずれている
    while(k >>= 1){
      seg[dif | k] = func(seg[dif | (k << 1)] , seg[dif | (k << 1) | 1]);
    }
  }
  // [a,b)へのクエリ
  T query(int a, int b){
    //trc("query" , a , b);
    if(a < 0){a = 0;} b--; // いったん閉区間にする

    // おなじセグ木に乗せる処理
    T ret = UNIT;
    vector<int>::const_iterator itl = upper_bound(seg_sz.begin() , seg_sz.end() , a),
      itr = upper_bound(seg_sz.begin() , seg_sz.end() , b);
    itl--; const int cur_sz = *(itr--) - *itr;// 右側の載っているセグ木のサイズ
    //trc(ret , *itl , *itr);
    while(itl != itr) {
      if(a == *itl) ret = func(ret , seg[ ( (*itl++) << 1 ) | 1 ]);
      else ret = func(ret , query(a , (*(++itl))) );
      a = *itl;
      //trc(ret , *itl , *itr);
    }
    const int dif = (*itr) << 1;
    // 普通のセグ木の処理 セグ木のサイズはcur_sz a,bは添え字はdifずれる
    T L = UNIT, R = UNIT;
    for( a += cur_sz - *itr , b += cur_sz + 1 - *itr ; a<b; a>>=1,b>>=1){
      if(a & 1) L = func(L,seg[dif | (a++)]);
      if(b & 1) R = func(seg[dif | (--b)],R);
    }
    return func(ret , func(L, R) );
  }

  T operator[](const int &k) const{
    vector<int>::const_iterator it = upper_bound(seg_sz.begin() , seg_sz.end() , k);
    return seg[ *it + k ];
  }

};

