template <typename T>
class RMQ {
private:
	vector<T> _dat;
	int _n;
	T _initial;

public:
	RMQ(int n, int initial) {
		init(n, initial);
	}

	void init(int n, T initial) {
		_initial = initial;
		_n = 1;
		while(_n < n) _n *= 2;
		_dat.resize(_n*2-1, _initial);
	}

	void update(int x, T y) {
		x += _n-1;
		_dat[x] = y;
		while(x > 0) {
			x = (x-1) / 2;
			_dat[x] = min(_dat[x*2+1], _dat[x*2+2]);
		}
	}

	T query(int a, int b) {
		return query(a, b, 0, 0, _n);
	}

	T query(int a, int b, int k, int l, int r) {
		if(b<=l || r<=a) return _initial;
		if(a<=l && r<=b) return _dat[k];
		return min( query(a,b,k*2+1,l,(l+r)/2), query(a,b,k*2+2,(l+r)/2,r) );
	}
};

int main() {
	int n, q;
