// 1 点更新区間取得

// T, E はそれぞれ要素, 作用素の型
// f, g, h はそれぞれ要素のマージ、作用素を作用させる、作用素のマージ用のラムダ式
// d1, d0 はそれぞれ要素、作用素の単位元
// ti は要素の初期値, 渡さない場合は単位元で埋められる
// p は区間に対して作用素を作用させる回数が長さに応じて変化する場合用のラムダ式

// dat は要素を保持しておくための配列
// laz は作用素を保持しておくための配列
// init(), では要素数に応じて動的に配列を確保
// build() では初期値が与えられた場合に O(N) で構築

template <typename T, typename E>
struct SegmentTree{
    using F = function<T(T, T)>;
    int n;
    F f;
    T ti;
    vector<T> dat;
    SegmentTree(){};
    SegmentTree(F f, T ti, const vector<int> &v):f(f),ti(ti){
        int sz = v.size();
        n = 1;
        while(n < sz) n <<= 1;
        dat.assign(2 * n - 1, ti);
        for(int i = 0; i < sz; i++) dat[n - 1 + i] = v[i];
        for(int i = n - 2; i >= 0; i--) dat[i] = f(dat[2 * i + 1], dat[2 * i + 2]);
    }

    // x 番目(0 - indexed) の要素を val に更新
    void update(int x, T val){
        x += (n - 1);
        dat[x] = val;
        while(x > 0){
            x = (x - 1) / 2;
            dat[x] = f(dat[2 * x + 1], dat[2 * x + 2]);
        }
    }

    // 区間[a, b)を取得する
    T get(int a, int b, int k, int l, int r){
        if(r <= a || b <= l) return ti;
        if(a <= l && r <= b) return dat[k];
        T vl = get(a, b, k * 2 + 1, l, (l + r) / 2);
        T vr = get(a, b, k * 2 + 2, (l + r) / 2, r);
        return f(vl, vr);
    }

    T get(int  a, int b){
        return get(a, b, 0, 0, n);
    }
};


