using namespace std;

int INIT = 2147483647;

class SegmentTree {
    int size;
    vector<int> p;
public:
    SegmentTree(int n) {
        // 0-indexed
        size = 1;
        while(size<n) size *= 2;
        p = vector<int>(2*size-1, INIT);
    }

    void update(int i, int x) {
        int s = size+i-1;
        p[s] = x;
        while(s > 0) {
            s = (s - 1) / 2;
            p[s] = min(p[2*s+1], p[2*s+2]);
        }
    }

    int find(int s, int t) {
        return query(s, t, 0, 0, size);
    }

    int query(int s, int t, int k, int l, int r) {
        if(r<=s || t<=l) return INIT;
        if(s<=l && r<=t) return p[k];
        int lv = query(s, t, 2*k+1, l, (l+r)/2);
        int rv = query(s, t, 2*k+2, (l+r)/2, r);
        return min(lv, rv);
    }
};

int main() {
    int n, q, com, x, y;
    cin >> n >> q;
    SegmentTree S(n);

    for(int i = 0; i < q; i++) {
        cin >> com >> x >> y;
        if(com == 0) {
            S.update(x, y);
        }
        else if(com == 1) {
            cout << S.find(x, y+1) << endl;
        }
    }
}

#include <bits/stdc++.h>
using namespace std;

template <typename Monoid>
class SegmentTree {
	using T = typename Monoid::type;
	const int n;
	vector<T> data;
	int size(int n) {
		int res;
		for (res = 1; res < n; res <<= 1);
		return res;
	}
public:
	SegmentTree(int n_) :
		n(size(n_)), data(n * 2, Monoid::id()) {}
	void init(const vector<T>& data_) {
		for (int i = 0; i < (int)data_.size(); i++)
			data[i + n] = data_[i];
		for (int i = n - 1; i >= 0; i--)
			data[i] = Monoid::op(data[i * 2], data[i * 2 + 1]);
	}
	void update(int p, T val) {
		p += n;
		data[p] = val;
		while (p >>= 1) data[p] = Monoid::op(data[p * 2], data[p * 2 + 1]);
	}
	void add(int p, T val) {
		p += n;
		data[p] += val;
		while (p >>= 1) data[p] = Monoid::op(data[p * 2], data[p * 2 + 1]);
	}
	T find(int i) {
		return data[i + n];
	}
	T find(int l, int r) {
		l += n; r += n + 1;
		T res1 = Monoid::id(), res2 = Monoid::id();
		while (l < r) {
			if (l & 1) res1 = Monoid::op(res1, data[l++]);
			if (r & 1) res2 = Monoid::op(data[--r], res2);
			l >>= 1; r >>= 1;
		}
		return Monoid::op(res1, res2);
	}
};

struct RMQ {
	using type = int;
	static const type id() { return INT_MAX; }
	static type op(const type& l, const type & r) { return min(l, r); }
};

int main()
{
	int n, q, com, x, y;
	scanf("%d%d", &n, &q);
	SegmentTree<RMQ> seg(n);
	while (q--) {
		scanf("%d%d%d", &com, &x, &y);
		if (com) printf("%d\n", seg.find(x, y));
		else seg.update(x, y);
	}
	return 0;
}

