const ll B = 512;
struct SqrtComposition
{
    ll N, K;
    vector<ll> data;
    vector<ll> backet;
    SqrtComposition(ll n) : N(n)
    {
        K = (N + B - 1) / B;
        data.assign(K * B, INF);
        backet.assign(K, INF);
    }
    void update(ll i, ll val)
    {
        ll k = i / B;
        data[i] = val;
        ll mn = val;
        for (ll j = k * B; j < (k + 1) * B; j++)
        {
            chmin(mn, data[j]);
        }
        backet[k] = mn;
    }
    ll getmin(ll a, ll b)
    {
        ll ans = INF;
        for (ll k = 0; k < K; k++)
        {
            ll l = k * B;
            ll r = (k + 1) * B;
            if (r <= a || b <= l)
            {
                continue;
            }
            if (a <= l && r <= b)
            {
                chmin(ans, backet[k]);
            }
            else
            {
                for (ll i = max(l, a); i < min(r, b); i++)
                {
                    chmin(ans, data[i]);
                }
            }
        }
        return ans;
    }
};

