    class MaiPrinter {
        int stack_p;
        char stack[32];
    public:
        template<typename T>
        void output_integer(T var) {
            if (var == 0) {
                putchar_unlocked('0');
                return;
            }
            if (var < 0) {
                putchar_unlocked('-');
                var = -var;
            }
            stack_p = 0;
            while (var) {
                stack[stack_p++] = '0' + (var % 10);
                var /= 10;
            }
            while (stack_p)
                putchar_unlocked(stack[--stack_p]);
        }
        MaiPrinter& operator<<(char c) {
            putchar_unlocked(c);
            return *this;
        }
        MaiPrinter& operator<<(int var) {
            output_integer<int>(var);
            return *this;
        }
        MaiPrinter& operator<<(long long var) {
            output_integer<long long>(var);
            return *this;
        }
        MaiPrinter& operator<(int var) {
            output_integer<int>(var);
            putchar_unlocked(' ');
