__inline int nextInt(void) {

    register int res = 0;
    register bool neg = false;

    while (*p < '0' || *p > '9')
        if (*p++ == '-')neg ^= 1;

    while (*p >= '0' && *p <= '9')
        res = res * 10 + *p++ - '0';

    return neg ? -res : res;

}

