}

#define N 100005

struct Node {

	int lt, rt, mid, mini;

}tree[N << 2];

void build(int t, int l, int r) {

	Node &tr = tree[t];

	tr.lt = l, tr.rt = r;
	tr.mini = 2147483647;

	if (l ^ r) {
		tr.mid = (l + r) >> 1;
		build(t << 1, l, tr.mid);
		build(t << 1 | 1, tr.mid + 1, r);
	}

}

int query(int t, int l, int r) {

	Node &tr = tree[t];

	if (tr.lt == l && tr.rt == r)
		return tr.mini;

	if (r <= tr.mid)
		return query(t << 1, l, r);
	if (l > tr.mid)
		return query(t << 1 | 1, l, r);
	return min(
		query(t << 1, l, tr.mid),
		query(t << 1 | 1, tr.mid + 1, r)
	);

}

void change(int t, int x, int y) {

	Node &tr = tree[t];

	if (tr.lt == tr.rt) {
		tr.mini = y; return;	
	}

	if (x <= tr.mid)
		change(t << 1, x, y);
	else
		change(t << 1 | 1, x, y);

	tr.mini = min(
		tree[t << 1].mini,
		tree[t << 1 | 1].mini
	);

}

signed main(void) {

	fread(p, 1, LIMIT, stdin);

	register int n, m;

	n = nextInt();
	m = nextInt();

	build(1, 0, n - 1);

	for (register int i = 1, k, x, y; i <= m; ++i) {

		k = nextInt();
		x = nextInt();
		y = nextInt();

		if (k)printf("%d\n", query(1, x, y));
		else change(1, x, y);

	}	

}

