void init(int an){
  n = 1;
  while(n < an){
    n *= 2;
  }
  for(int i=0;i < 2*n-1;i++){
    tree[i] = INT_MAX;
  }
}

void update(int i,int x){
  i += n - 1;
  tree[i] = x;
  while(i > 0){
    i = (i-1)/2;
    tree[i] = min( tree[2*i+1], tree[2*i+2] );
  }
}

int query(int a,int b,int k,int l,int r){
  if(b <= l || r <= a){
    return INT_MAX;
  }else if(a <= l && r <= b){
    return tree[k];
  }else{
    return min(
      query( a, b, 2*k+1, l, (l+r)/2),
      query( a, b, 2*k+2, (l+r)/2, r)
    );
  }
}

