        auto p = split(root, l);

        auto a = p.first;

        auto q = split(p.second, r - l + 1);

        auto b = q.first;
        auto c = q.second;


        ll res = -1;
        if (b) res = b->mi;

        root = merge(merge(a, b), c);


        return res;
    }

