const int MAX_N = 1 << 17;

class SegTree{
private:
    int dat[2*MAX_N - 1];
public:
    int n;
    SegTree(int n);
    void update(int k, int a);
    int query(int a, int b, int k, int l, int r);
};

SegTree::SegTree(int n_){
    n = 1;
    // 葉の数 n を2のべき乗にする
    while(n < n_) n *= 2;
    REP(i, 2*n-1) dat[i] = INT_MAX;
}

// 配列arrのk番目の値をaに変更
void SegTree::update(int k, int a){
    // arr[k]に対応する葉の節点
    k += n - 1;
    // 葉をaに更新
    dat[k] = a;
    // 木を登りながら各節点の最小値を更新
    while (k > 0){
        k = (k - 1) / 2;
        dat[k] = min(dat[2*k+1], dat[2*k+2]);
    }
}

// [a, b) の最小値を求める
int SegTree::query(int a, int b, int k, int l, int r){
    if (r <= a || b <= l) return INT_MAX;
    if (a <= l && r <= b) return dat[k];
    else{
        // vl:左の子の値, vr:右の子の値 をそれぞれ再帰的に求める
        int vl = query(a, b, 2*k+1, l, (l+r)/2);
        int vr = query(a, b, 2*k+2, (l+r)/2, r);
        return min(vl, vr);
    }
}

