		if(l <= bucket_l && bucket_r <= r){
			chmin(res,bucketMin [i]);
			continue;
		}
		FOR(j,bucket_l,bucket_r){
			if(l <= j && j < r){
				chmin(res,A [j]);
			}
		}
	}
	return res;
}

