//初期化→子ノードから再帰的にO(n)
//区間の最小値、更新→定数個のノードにしか
//アクセスしないのでO(log n)

//利点
//平衡処理が必要ない
//ノードの個数n+n/2+n/4+...<2n

//木の持ち方
//配列でノードに番号をつける
//上の段から、同じ段では左から順に番号を振る
//この振り方だと、
//番号nの親:(n-1)/2(を切り捨て)
//      子:2n+1,2n+2,...
#include<iostream>
using namespace std;

const int INT_MAX=2147483647;
const int MAX_N=100010;

int n;
int dat[MAX_N*4];

void init(){//初期化
    //全ての値をINT_MAXにする
    for(int i=0; i<n*2-1; i++)dat[i]=INT_MAX;
}

//値の更新
//場所iに対応する一番下のノードはn+i-1
//そこから(n-1)/2を繰り返して親をたどる
void update(int i,int x){//i番目の値をxに変更
    //葉のノードの番号
    i+=n-1;
    dat[i]=x;
    //登りながら更新
    while(i>0){
        i=(i-1)/2;//親ノード
        dat[i]=min(dat[i*2+1],dat[i*2+2]);//子ノードの中で小さいものを取る
    }
}

//最小値の取得→再帰
//区間[i,j]とそのノードの区間が一致しない→INT_MAXを返しておく
//区間[i,j]とそのノードの区間を完全に含む→その接点の持つ値を返す
//どちらでもない→2つの子ノードについて再帰的に計算
int query(int a,int b,int k,int l,int r){//要求区間[a,b)のmin,いまのノードk,対象区間[l,r)で再帰的に計算,query(a,b,0,0,n)と呼ぶ
    //区間が交差しない→
    if(r<=a || b<=l) return INT_MAX;
    //区間を完全に含む
    if(a<=l && r<=b) return dat[k];//その接点の持つ値
    else{
        int vl=query(a,b,k*2+1,l,(l+r)/2);//子ノード[l,(l+r)/2)についてminを計算
        int vr=query(a,b,k*2+2,(l+r)/2,r);
        return min(vl,vr);
    }
}

