    for(int i=0; i<32; i++){
        if(n2>=n){
            n=n2;
            break;
        }
        n2*=2;
    }//これを行うことでセグメント木は完全二分木となり扱いやすくなる

    init();
    for(int i=0; i<q; i++){
        int c,x,y;
        cin>>c>>x>>y;
        if(c==0)update(x,y);
        else if(c==1) cout<<query(x,y+1,0,0,n)<<endl;
    }
    return 0;
}

