template<typename T>
class SegTree {
  int n;
  T def;
  vector<T> data;
  function<T(T, T)> operation; // query で
  function<T(T, T)> update; // change で

  T _query(int a, int b, int k, int l, int r) {
    if (r <= a || b <= l) return def;
    if (a <= l && r <= b) return data[k];
    T c1 = _query(a, b, 2 * k + 1, l, (l + r) / 2);
    T c2 = _query(a, b, 2 * k + 2, (l + r) / 2, r);
    return operation(c1, c2);
  }

public:
  SegTree<T>(int _n, T _def,
      function<T(T, T)> _operation, function<T(T, T)> _update)
    : def(_def), operation(_operation), update(_update) {
      n = 1;
      while (n < _n) n *= 2;
      data = vector<T>(2 * n - 1, def);
    }

  T query(int a, int b) {
    return _query(a, b, 0, 0, n);
  }

  void change(int i, T x) { // i を x に変える (operation は関係ない)
    i += n - 1;
    data[i] = update(data[i], x);
    while (i > 0) {
      i = (i - 1) / 2;
      data[i] = operation(data[i * 2 + 1], data[i * 2 + 2]);
    }
  }

  T operator[](int i) { return data[i + n - 1]; }
  void out() { rep(i, n) cout << data[i + n - 1] << " "; cout << endl; }
};

void solve() {
  int n, q;
  cin >> n >> q;

  SegTree<int> seg(n, (1LL << 31) - 1,
    [](int a, int b) { return min(a, b); }, // query
    [](int a, int b) { return b; }); // change, ただ変更するだけ

  rep(i, q) {
    int com, x, y;
    cin >> com >> x >> y;
    if (com == 0) {
      seg.change(x, y);
      continue;
    }
    cout << seg.query(x, y + 1) << endl;
  }
}

