const int inf=1073741823;
const i64 llinf=4611686018427387903LL;

class rmtree{
public:
    int nd;
    int wdt;
    i64 *node;
	int *ind;
    void make(int n){
        int k=1;
        while(k<n) k*=2;
        wdt=k;
        nd=wdt*2-1;
        node=new i64[nd]{};
		ind=new int[nd]{};
        for(int i=0;i<nd;i++){
            node[i]=llinf;
            ind[i]=-1;
        }
    }
    void add(int k,i64 x){
        k+=wdt-1;
        node[k]=x;
        ind[k]=k;
    }
    void calc(void){
        func_calc(0);
    }
    void func_calc(int k){
        int k1=k*2+1;
        int k2=k*2+2;
        if(k1>=nd || k2>=nd) return;
        if(node[k1]==-1) func_calc(k1);
        if(node[k2]==-1) func_calc(k2);
        if(node[k1]<node[k2]) node[k]=node[k1];
        else node[k]=node[k2];
        if(node[k1]<node[k2]) ind[k]=ind[k1];
        else ind[k]=ind[k2];
    }
    void update(int k,i64 x){
        k+=wdt-1;
        node[k]=x;
        ind[k]=k;
        while(k>0){
            k=(k-1)/2;
            if(node[k*2+1]<node[k*2+2]) node[k]=node[k*2+1];
            else node[k]=node[k*2+2];
			if(node[k*2+1]<node[k*2+2]) ind[k]=ind[k*2+1];
			else ind[k]=ind[k*2+2];
        }
    }
    i64 query(int a,int b){
        return func_query(a,b,0,0,wdt);
    }
    i64 func_query(int a,int b,int k,int l,int r){
        if(r<=a || b<=l) return llinf;
        if(a<=l && r<=b) return node[k];
        else{
            i64 vl=func_query(a,b,k*2+1,l,(l+r)/2);
            i64 vr=func_query(a,b,k*2+2,(l+r)/2,r);
            return min(vl,vr);
        }
    }
    int indery(int a,int b){
        return func_indery(a,b,0,0,wdt);
    }
    int func_indery(int a,int b,int k,int l,int r){
        if(r<=a || b<=l) return -1;
        if(a<=l && r<=b) return ind[k];
        else{
            int li=func_indery(a,b,k*2+1,l,(l+r)/2);
            int ri=func_indery(a,b,k*2+2,(l+r)/2,r);
			if(li==-1){
				if(ri==-1) return -1;
				else return ind[ri];
			}
			else if(ri==-1) return ind[li];
			else{
				if(node[ind[li]]<node[ind[ri]]) return ind[li];
				else return ind[ri];
			}
        }
    }
    void refr(void){
        delete[] node;
        delete[] ind;
    }
};

