template <typename T>
class SegmentTree{
private:
  int size;
  vector<T> vec;
  T e;
  function<T(T,T)> f;
  function<T(T,T)> upd;

  int aux(int x, int y, int i, int l, int r){
    if(r<=x || y<=l) return e;
    else if(x<=l && r<=y) return vec[i];
    else return f(aux(x,y,i*2+1,l,(l+r)/2), aux(x,y,i*2+2,(l+r)/2,r));
  };

public:
  SegmentTree(int n, T e, function<T(T,T)> f, function<T(T,T)> upd):
    size((1<<((int)ceil(log(n)/log(2))+1))-1), vec(size, inf), f(f), e(e), upd(upd){}
  void update(int i, T x){
    int j = i+(size+1)/2-1;
    vec[j] = upd(vec[j], x);
    --j;
    while(j>=0){
      vec[j/2] = f(vec[(j/2)*2+1], vec[(j/2)*2+2]);
      (j /= 2) -= 1;
    }
  }

  int find(int x, int y){return aux(x,y,0,0,(size+1)/2);}
};


int main(){
  cin.tie(0);
  ios::sync_with_stdio(false);

  int n,q; cin >> n >> q;
  SegmentTree<int> rmq(n, inf, [](int a, int b){return min(a,b);}, [](int a, int b){return b;});

  REP(i,q){
