const int max_n = 4*100005;
int n;
int dat[max_n];

// 初期化
void init_seg (int n_ )
{
	// 簡単の為、要素数を2のべき乗に
	n = 1;
	while (n < n_ ) n *= 2;

	// すべての値を INT_MAX に
	rep (i, 2*n - 1 ) dat[i] = INT_MAX;
}

// k 番目の値 ( 0-indexed ) を a に変更
void update (int k, int a )
{
	// 葉の節点
	k += n - 1;
	dat[k] = a;

	// 登りながら更新
	while (k > 0 ){
		k = (k - 1 )/2;
		dat[k] = min (dat[2*k + 1], dat[2*k + 2] );
	} // end while
}

/*
	[a, b ) の最小値を求める
	後ろの方の引数は、計算の簡単なための引数
	k は節点の番号、l, r はその節点 [l, r ) に対応づいていることを表す
	したがって、外からは query (a, b, 0, 0, n ) として呼ぶ
 */
int query (int a, int b, int k, int l, int r )
{
	// [a, b ) と [l, r ) が交差しなければ INT_MAX
	if (r <= a || b <= l ) return INT_MAX;

	// [a, b ) が [l, r ) を完全に含んでいれば、この節点の値
	if (a <= l && r <= b ) return dat[k];
	else{
	// そうでなければ、2つの子の最小値
		int vl = query (a, b, 2*k + 1, l, (l+r)/2 );
		int vr = query (a, b, 2*k + 2, (l+r)/2, r );
		return min (vl, vr );
	} // end if
}

int main()
{
	ios_base::sync_with_stdio(0);
	int n_, q; cin >> n_ >> q;
	init_seg (n_ );

	rep (i, q ){
		int com, x, y; cin >> com >> x >> y;
		if (com == 0 ){	// update
			update (x, y );
		}else{			// find 
			int res = query (x, y+1, 0, 0, n );
			cout << res << endl;
		} // end if
	} // end loop

	return 0;
}

