const ll infi = ((ll)1 << 31) -1;
class segment_tree{
  private:
    ll N = 1;
    vector<ll> data;
    ll inf = infi;
  public:

    segment_tree(vector<ll> vec){
      ll m = vec.size();
      while(N < m) N *= 2;
      data.resize(2*N, inf);

      for(int i=0;i<m;i++) update(i,vec[i]);
    }

    void update(ll k, ll a){
      k += N - 1;
      data[k] = a;
      while(k > 0){
        k = (k-1) / 2;
        data[k] = min(data[k * 2 + 1], data[k * 2 + 2]);
      }
    }

    // [a,b) のクエリを処理する
    int query_(ll a, ll b, ll k, ll l, ll r){
      // [a,b)　と [l,r) が交差しない時
      if(r <= a || b <= l) return inf; 

      // 完全に含まれている時
      if(a <= l && r <= b) return data[k];
      else{
        ll mid = (l + r) / 2;
        // 2つの子の最小値
        ll vl = query_(a,b,k*2+1,l,mid);
        ll vr = query_(a,b,k*2+2,mid,r);
        return min(vl, vr);
      }
    }

    int query(ll a, ll b){
      return query_(a, b, 0, 0, N);
    }
};

