template <class Integral, class T,
	std::size_t bitsize = std::numeric_limits<Integral>::digits()>
	class WaveletMatrixSum {
	public:
		using key_type = Integral;
		using linked_type = T;
		using value_type = std::pair<key_type, linked_type>;
		using size_type = std::size_t;

	private:
		using uint32 = std::uint_least32_t;
		static size_type popcount32(uint32 c) {
#ifdef __GNUC__
			return __builtin_popcount(c);
#elif _MSC_VER_
			return _mm_popcnt_u32(c);
#else
			c = (c & 0x55555555) + ((c >> 1) & 0x55555555);
			c = (c & 0x33333333) + ((c >> 2) & 0x33333333);
			c = (c + (c >> 4)) & 0x0F0F0F0F;
			c += c >> 8;
			c += c >> 16;
			return static_cast<size_type>(c) & 0x3F;
#endif
		}
		struct FID {
			std::vector<uint32> dic;
			size_type cnt;
			key_type bit;
			std::vector<linked_type> sum;

			FID() {}

			void set(const size_type index) {
				dic[index >> 4 | 1] |= static_cast<uint32>(1) << (index & 0x1f);
			}
			void build() {
				const size_type len = dic.size();
				for (size_type j = 2; j < len; j += 2)
					dic[j] = dic[j - 2] + popcount32(dic[j - 1]);
			}

			size_type rank(const size_type last) const {
				return static_cast<size_type>(
					dic[last >> 4 & ~static_cast<size_type>(1)]) +
					popcount32(dic[last >> 4 | 1] &
					(static_cast<size_type>(1) << (last & 0x1f)) - 1);
			}
			bool access(const size_type index) const {
				return dic[index >> 4 | 1] >> (index & 0x1f) & 1;
			}
			linked_type range(const size_type first, const size_type last) const {
				return sum[last] - sum[first];
			}
		};
		std::array<FID, bitsize> matrix;
		value_type NOT_FOUND;
		size_type size_;

	public:
		WaveletMatrixSum(const std::vector<value_type> &data,
			const value_type NOT_FOUND = value_type())
			: size_(data.size()), NOT_FOUND(NOT_FOUND) {
			const size_type len = data.size(), block = ((len >> 5) + 1) << 1;
			std::vector<size_type> C(len), L(len), R(len);
			std::iota(C.begin(), C.end(), static_cast<size_type>(0));
			size_type l, r;
			key_type temp = static_cast<key_type>(1) << (bitsize - 1);
			for (auto &x : matrix) {
				x.dic.resize(block, 0);
				x.bit = temp;
				temp = temp >> 1 & ~temp;
				l = 0;
				r = 0;
				for (size_type i = 0; i < len; ++i)
					if (data[C[i]].first & x.bit)
						R[r++] = C[i], x.set(i);
					else
						L[l++] = C[i];
				x.cnt = l;
				x.build();
				std::swap(C, L);
				std::copy(R.begin(), R.begin() + r, C.begin() + l);
				for (size_type i = 0; i < len; ++i)
					x.sum.reserve(len + 1);
				x.sum.emplace_back();
				for (const auto e : C)
					x.sum.emplace_back(x.sum.back() + data[e].second);
			}
		}

		size_type size() const noexcept { return size_; }
		bool empty() const noexcept { return size() == 0; }

		value_type access(size_type index) const {
			assert(index < size());
			key_type ret = 0;
			for (const auto &x : matrix)
				if (x.access(index))
					ret |= x.bit, index = x.rank(index) + x.cnt;
				else
					index -= x.rank(index);
			return value_type(ret, matrix.back().range(index, index + 1));
		}
		value_type operator[](const size_type index) const {
			assert(index < size());
			return access(index);
		}
		size_type rank(size_type first, size_type last, const key_type data) const {
			assert(first <= size());
			assert(last <= size());
			assert(first <= last);
			for (const auto &x : matrix)
				if (data & x.bit)
					first = x.rank(first) + x.cnt, last = x.rank(last) + x.cnt;
				else
					first -= x.rank(first), last -= x.rank(last);
			return last - first;
		}
		linked_type rank_sum(size_type first, size_type last,
			const key_type data) const {
			assert(first <= size());
			assert(last <= size());
			assert(first <= last);
			for (const auto &x : matrix)
				if (data & x.bit)
					first = x.rank(first) + x.cnt, last = x.rank(last) + x.cnt;
				else
					first -= x.rank(first), last -= x.rank(last);
			return matrix.back().range(first, last);
		}
		value_type quantile(size_type first, size_type last, size_type k) const {
			assert(first < size());
			assert(last <= size());
			assert(first < last);
			assert(last - first > k);
			key_type ret = 0;
			for (const auto &x : matrix) {
				const size_type l = x.rank(first), r = x.rank(last);
				if (r - l > k)
					first = l + x.cnt, last = r + x.cnt, ret |= x.bit;
				else
					first -= l, last -= r, k -= r - l;
			}
			return value_type(ret, matrix.back().range(last - k - 1, last - k));
		}
		value_type rquantile(size_type first, size_type last, size_type k) const {
			assert(first < size());
			assert(last <= size());
			assert(first < last);
			assert(last - first > k);
			return quantile(first, last, last - first - k - 1);
		}
		size_type less_than(size_type first, size_type last,
			const key_type data) const {
			assert(first <= size());
			assert(last <= size());
			assert(first <= last);
			size_type ret = 0;
			for (const auto &x : matrix) {
				if (data & x.bit) {
					ret += last - first + x.rank(first) - x.rank(last);
					first = x.rank(first) + x.cnt;
					last = x.rank(last) + x.cnt;
				}
				else {
					first -= x.rank(first);
					last -= x.rank(last);
				}
			}
			return ret;
		}
		linked_type less_than_sum(size_type first, size_type last,
			const key_type data) const {
			assert(first <= size());
			assert(last <= size());
			assert(first <= last);
			linked_type ret = linked_type();
			for (const auto &x : matrix) {
				if (data & x.bit) {
					ret = ret + x.range(first - x.rank(first), last - x.rank(last));
					first = x.rank(first) + x.cnt;
					last = x.rank(last) + x.cnt;
				}
				else {
					first -= x.rank(first);
					last -= x.rank(last);
				}
			}
			return ret;
		}
		size_type at_least(size_type first, size_type last,
			const key_type data) const {
			assert(first <= size());
			assert(last <= size());
			assert(first <= last);
			size_type ret = 0;
			for (const auto &x : matrix) {
				if (data & x.bit) {
					first = x.rank(first) + x.cnt;
					last = x.rank(last) + x.cnt;
				}
				else {
					ret += x.rank(last) - x.rank(first);
					first -= x.rank(first);
					last -= x.rank(last);
				}
			}
			return last - first + ret;
		}
		linked_type at_least_sum(size_type first, size_type last,
			const key_type data) const {
			assert(first <= size());
			assert(last <= size());
			assert(first <= last);
			linked_type ret = linked_type();
			for (const auto &x : matrix) {
				if (data & x.bit) {
					first = x.rank(first) + x.cnt;
					last = x.rank(last) + x.cnt;
				}
				else {
					ret = ret + x.range(x.rank(first) + x.cnt, x.rank(last) + x.cnt);
					first -= x.rank(first);
					last -= x.rank(last);
				}
			}
			return ret + matrix.back().range(first, last);
		}
		size_type greater_than(size_type first, size_type last,
			const key_type data) const {
			assert(first <= size());
			assert(last <= size());
			assert(first <= last);
			size_type ret = 0;
			for (const auto &x : matrix) {
				if (data & x.bit) {
					first = x.rank(first) + x.cnt;
					last = x.rank(last) + x.cnt;
				}
				else {
					ret += x.rank(last) - x.rank(first);
					first -= x.rank(first);
					last -= x.rank(last);
				}
			}
			return ret;
		}
		linked_type greater_than_sum(size_type first, size_type last,
			const key_type data) const {
			assert(first <= size());
			assert(last <= size());
			assert(first <= last);
			linked_type ret = linked_type();
			for (const auto &x : matrix) {
				if (data & x.bit) {
					first = x.rank(first) + x.cnt;
					last = x.rank(last) + x.cnt;
				}
				else {
					ret = ret + x.range(x.rank(first) + x.cnt, x.rank(last) + x.cnt);
					first -= x.rank(first);
					last -= x.rank(last);
				}
			}
			return ret;
		}
		size_type at_most(size_type first, size_type last,
			const key_type data) const {
			assert(first <= size());
			assert(last <= size());
			assert(first <= last);
			size_type ret = 0;
			for (const auto &x : matrix) {
				if (data & x.bit) {
					ret += last - first + x.rank(first) - x.rank(last);
					first = x.rank(first) + x.cnt;
					last = x.rank(last) + x.cnt;
				}
				else {
					first -= x.rank(first);
					last -= x.rank(last);
				}
			}
			return last - first + ret;
		}
		linked_type at_most_sum(size_type first, size_type last,
			const key_type data) const {
			assert(first <= size());
			assert(last <= size());
			assert(first <= last);
			linked_type ret = linked_type();
			for (const auto &x : matrix) {
				if (data & x.bit) {
					ret = ret + x.range(first - x.rank(first), last - x.rank(last));
					first = x.rank(first) + x.cnt;
					last = x.rank(last) + x.cnt;
				}
				else {
					first -= x.rank(first);
					last -= x.rank(last);
				}
			}
			return ret + matrix.back().range(first, last);
		}
		size_type rangefreq(size_type first, size_type last, const key_type lower,
			const key_type upper) const {
			assert(first <= size());
			assert(last <= size());
			assert(first <= last);
			assert(lower <= upper);
			return less_than(first, last, upper) - less_than(first, last, lower);
		}
		linked_type rangefreq_sum(size_type first, size_type last,
			const key_type lower, const key_type upper) const {
			assert(first <= size());
			assert(last <= size());
			assert(first <= last);
			assert(lower <= upper);
			return less_than_sum(first, last, upper) -
				less_than_sum(first, last, lower);
		}
		linked_type maxk_sum(size_type first, size_type last, size_type k) const {
			assert(first <= size());
			assert(last <= size());
			assert(first <= last);
			assert(last - first >= k);
			linked_type ret = linked_type();
			for (const auto &x : matrix) {
				const size_type l = x.rank(first), r = x.rank(last);
				if (r - l > k) {
					first = l + x.cnt;
					last = r + x.cnt;
				}
				else {
					ret = ret + x.range(l + x.cnt, r + x.cnt);
					first -= l;
					last -= r;
					k -= r - l;
				}
			}
			return ret;
		}
		linked_type mink_sum(size_type first, size_type last, size_type k) const {
			assert(first <= size());
			assert(last <= size());
			assert(first <= last);
			assert(last - first >= k);
			linked_type ret = linked_type();
			for (const auto &x : matrix) {
				const size_type l = first - x.rank(first), r = last - x.rank(last);
				if (r - l > k) {
					first = l;
					last = r;
				}
				else {
					ret = ret + x.range(l, r);
					first += x.cnt - l;
					last += x.cnt - r;
					k -= r - l;
				}
			}
			return ret;
		}
		value_type successor(const size_type first, const size_type last,
			const key_type data) const {
			assert(first <= size());
			assert(last <= size());
			assert(first <= last);
			const size_type k = less_than(first, last, data);
			return last - first == k ? NOT_FOUND : rquantile(first, last, k);
		}
		value_type predecessor(const size_type first, const size_type last,
			const key_type data) const {
			assert(first <= size());
			assert(last <= size());
			assert(first <= last);
			const size_type k = greater_than(first, last, data);
			return last - first == k ? NOT_FOUND : quantile(first, last, k);
		}
		value_type strict_succ(const size_type first, const size_type last,
			const key_type data) const {
			assert(first <= size());
			assert(last <= size());
			assert(first <= last);
			const size_type k = greater_than(first, last, data);
			return k ? quantile(first, last, k - 1) : NOT_FOUND;
		}
		value_type strict_pred(const size_type first, const size_type last,
			const key_type data) const {
			assert(first <= size());
			assert(last <= size());
			assert(first <= last);
			const size_type k = less_than(first, last, data);
			return k ? rquantile(first, last, k - 1) : NOT_FOUND;
		}
};
