using namespace std;

class RMQ
{
	int n;
	vector<int> dat;
public:
	RMQ(int n_)
	{
		n = 1;
		while (n < n_)
		{
			n *= 2;
		}
		dat.resize(2 * n - 1);
		for (int i = 0; i < 2 * n - 1; ++i)
		{
			dat[i] = INT_MAX;
		}
	}
	void update(int k, int a)
	{
		k += n - 1;
		dat[k] = a;
		while (k > 0)
		{
			k = (k - 1) / 2;
			dat[k] = min(dat[2 * k + 1], dat[2 * k + 2]);
		}
	}
	int query(int a, int b, int k = 0, int l = 0, int r = 0)
	{
		if (r <= l)
		{
			r = n;
		}
		if (r <= a || b <= l)
		{
			return(INT_MAX);
		}
		if (a <= l && r <= b)
		{
			return(dat[k]);
		}
		int vl = query(a, b, 2 * k + 1, l, (l + r) / 2);
		int vr = query(a, b, 2 * k + 2, (l + r) / 2, r);
		return(min(vl, vr));
	}
};

void solve()
{
	int n, q;
	cin >> n >> q;
	RMQ r(n);
	for (int i = 0; i < q; ++i)
	{
		int com, x, y;
		cin >> com >> x >> y;
		if (com == 0)
		{
			r.update(x, y);
		}
		else
		{
			cout << r.query(x, y + 1) << endl;
		}
	}
}

int main()
{
	solve();
	return(0);
}

