template <class T> struct carstain_tree{
    struct node{
        T val;
        int left;
        int right;
        int parent;
        void init(){
            right=left=parent=-1;
            return ;
        }
    };
    vector<node>map;
    int root;
    int size;
public:
    void init(){
        root=-1;
        size=0;
        map.clear();
        return ;
    }
    void push(T n){
        node temp;
        temp.init();
        temp.val=n;
        map.push_back(temp);
        if(size==0)root=0;
        else insert(size-1,size);
        size++;
        return ;
    }
    void in_print(){
        inorder(root);
        printf("\n");
        return ;
