        while (n < v.size()) n *= 2;
        node.resize(2*n-1, inf);
        for (int i=0; i<v.size(); ++i) node[i+n-1] = v[i];
        for (int i=n-2; i>=0; --i) node[i] = min(node[i*2+1], node[i*2+2]);
    }
    SegmentTree(T N) : inf((1LL<<31)-1) {
        n = 1;
        while (n < N) n *= 2;
        node.resize(2*n-1, inf);
    }

    void update(T x, T val) {
        x += (n-1);
        node[x] = val;
        while (x > 0) {
            x = (x-1)/2;
            node[x] = min(node[2*x+1], node[2*x+2]);
        }
    }

    // [a, b)
    T query(T a, T b, T k=0, T l=0, T r=-1) {
