template<class M>
struct Treap{
	struct Node{
		M val;
		Node *lch, *rch;
		unsigned long long pri;
		int cnt;
		M sum;
		Node(){}
		Node(M v, unsigned long long p): val(v), pri(p), cnt(1), sum(v){
			lch = rch = (Node *)NULL;
		}
	};

	M def;
	using F = function<M(M, M)>;
	F add;

	Node *root = NULL;
	vector<Node> node;


	Treap (int n, M d, const F f): node(n), def(d), add(f){}

	int count(Node *t){ return !t ? 0 : t->cnt;}
	M sum(Node *t){ return !t ? def : t->sum;}

	unsigned long long xor128(){
		static unsigned long long x=123456789, y=362436069, z=521288629, w=88675123;
  		unsigned long long t=(x^(x<<11));
  		x=y; y=z; z=w;
  		return ( w=(w^(w>>19))^(t^(t>>8)) );
	}

	Node *getNewNode(M v){
		static int i = 0;
		node[i] = Node(v, xor128());
		return &(node[i++]); 
	}

	Node *update(Node *t){
		t->cnt = count(t->lch) + 1 + count(t->rch);
		t->sum = add(add(sum(t->lch), t->val), sum(t->rch)) ;
		return t;
	}

	Node *merge(Node *l, Node *r){
		if(!l || !r) return !l ? r : l;
		if(l->pri > r->pri){
			l->rch = merge(l->rch, r);
			return update(l);
		}else{
			r->lch = merge(l, r->lch);
			return update(r);
		}
	}

	pair<Node*, Node*> split(Node *t, int k){
		if(!t) return make_pair((Node *)NULL, (Node *)NULL);
		if(k <= count(t->lch)){
			auto s = split(t->lch, k);
			t->lch = s.second;
			return make_pair(s.first, update(t));
		}else{
			auto s = split(t->rch, k-count(t->lch)-1);
			t->rch = s.first;
			return make_pair(update(t), s.second);
		}
	}

	void insert(int k, M val){
		auto t1 = split(root, k);
		auto nd = getNewNode(val);
		root = merge(merge(t1.first, nd), t1.second);
	}

	void erase(int k, M val){
		auto t1 = split(root, k);
		auto t2 = split(t1.second, 1);
		root = merge(t1.first, t2.second);
	}

	void update(int k, M val){
		auto t1 = split(root, k);
		auto t2 = split(t1.second, 1);
		t2.first->val = t2.first->sum = val; 
		root = merge(t1.first, merge(t2.first, t2.second));
	}

	M get(int l, int r){
		auto t1 = split(root, l);
		auto t2 = split(t1.second, r-l);
		M ret = sum(t2.first);
		root = merge(t1.first, merge(t2.first, t2.second));
		return ret;
	}
};

int main(){
	int n, q;
	cin >> n >> q;
	Treap<int> tree(n, INT_MAX, [](int a, int b){ return min(a, b);});
	for(int i = 0;i < n;i++) tree.insert(i, INT_MAX);
	while(q--){
		int com, x, y;
		cin >> com >> x >> y;
		if(com == 0){
			tree.update(x, y);
		}else{
			cout << tree.get(x, y+1) << endl;
		}
	}

	return 0;

}

