template<class data_type> class dynamic_memory_allocation_segtree{
private:
    class node{
    public:
        data_type data;
        int left,right;
        node *left_child,*right_child;
        node(const data_type &data_,const int left_,const int right_){
            data=data_;
            left=left_;
            right=right_;
            left_child=right_child=NULL;
        }
    };
    data_type id,initial_value;
    std::function<data_type(data_type,data_type)> fun;
    node root;

    data_type update(node *node_,const int index,const data_type &new_value){
        if(node_->right-node_->left==1) return node_->data=new_value;
        const int mid=(node_->left+node_->right)/2;
        data_type left_value=id,right_value=id;
        if(index<mid){
            if(node_->left_child==NULL) node_->left_child=new node(id,node_->left,mid);
            if(node_->right_child!=NULL) right_value=node_->right_child->data;
            left_value=update(node_->left_child,index,new_value);
        }else{
            if(node_->left_child!=NULL) left_value=node_->left_child->data;
            if(node_->right_child==NULL) node_->right_child=new node(id,mid,node_->right);
            right_value=update(node_->right_child,index,new_value);
        }
        return node_->data=fun(left_value,right_value);
    }

    data_type query(node* node_,const int left,const int right){
        if(left<=node_->left and node_->right<=right) return node_->data;
        if(node_->right<=left or right<=node_->left) return id;
        data_type left_value=id,right_value=id;
        if(node_->left_child!=NULL) left_value=fun(left_value,query(node_->left_child,left,right));
        if(node_->right_child!=NULL) right_value=fun(right_value,query(node_->right_child,left,right));
        return fun(left_value,right_value);
    }

public:
    dynamic_memory_allocation_segtree()=default;
    dynamic_memory_allocation_segtree(const int left,const int right,const std::function<data_type(data_type,data_type)> &fun_,const data_type &id_,const data_type &initial_value_):
    root(id_,left,right){ init(left,right,fun_,id_,initial_value_); }

    void init(const int left,const int right,const std::function<data_type(data_type,data_type)> &fun_,const data_type &id_,const data_type &initial_value_){
        root=node(id_,left,right);
        id=id_;
        fun=fun_;
        initial_value=initial_value_;
    }

    void update(int index,const data_type &new_value){ update(&root,index,new_value); }
    data_type query(const int left,const int right){ return query(&root,left,right); }
};

void solve(){
    int n,q;
    cin >> n >> q;
    dynamic_memory_allocation_segtree<int> seg(0,n,[](int x,int y){ return min(x,y); },numeric_limits<int>::max(),numeric_limits<int>::max());
