void update(int i, int x){
    i += n - 1;
    st[i] = x;
    while(i > 0){
        i = (i-1) / 2;
        st[i] = min(st[i*2+1], st[i*2+2]);
    }
}

int find(int a, int b, int i, int l, int r){
    if(b <= l || r <= a) return MAX;
    if(a <= l && r <= b) return st[i];
    int vl = find(a,b,i*2+1,l,(l+r)/2);
    int vr = find(a,b,i*2+2,(l+r)/2,r);
    return min(vl,vr);
}

