template<typename T>
class segment_tree{
private:
    vector<T> value; // ノードの値を持つ配列
public:
    int leafnum;             // 葉の数
    T m_val;     //最大値
    int bilower(int x){
        int ans = 1;
        while(ans < x) ans <<= 1;
        return ans;
    }
    //constructor
    //nodenumは要素数、maxvalは値の最大値
    segment_tree(int nodenum, T maxval){
        leafnum = bilower(nodenum);
        value = vector<T> (2*leafnum, maxval);
        m_val = maxval;
    }
    void update(int i, T x){
        // i 番目の葉の値を x に変える
        i += leafnum - 1; // i 番目の葉のノード番号
        value[i] = x;
        while (i > 0) {
            i = (i - 1) / 2; // ノード i の親ノードの番号に変える
            value[i] = min(value[i * 2 + 1], value[i * 2 + 2]); // 左右の子の min を計算しなおす
        }
    }
    T query(int a, int b, int k, int l, int r){
        // [a, b)の区間に対するクエリについて
        // ノード k （区間 [l, r) 担当）が答える
        if (r <= a || b <= l) return m_val+1; // 区間が被らない場合は 200001 を返す
        if (a <= l && r <= b) return value[k]; // ノード k の担当範囲がクエリ区間 [a, b)             
        else{ //に完全に含まれる
            T r1 = query(a, b, 2 * k + 1, l, (l + r) / 2); // 左の子に値を聞く
            T r2 = query(a, b, 2 * k + 2, (l + r) / 2, r); // 右の子に値を聞く
            return min(r1, r2); // 左右の子の値の min を取る
        }
    }
};

int main(){
    int n,q; cin >> n >> q;
    segment_tree<ll> seg(n, (1<<31)-1);
    int com,x,y;
    rep(i,q){
        cin >> com >> x >> y;
        if(com == 1){
            cout << seg.query(x,y+1,0,0,seg.leafnum) << endl;
        }else{
            seg.update(x,y);
        }
    }
}

