// 素集合データ構造 (Union-Find)
struct union_find{
    vector<int> par;
    vector<int> rank;
    union_find(int n) : par(n), rank(n){
        for(int i = 0; i < n; i++){
            par[i] = i; rank[i] = 0;
        }
    }
    int root (int x){
        if(par[x] == x) return x;
        par[x] = root(par[x]);
        return par[x];
    }
    void unite(int x, int y){
        int rx = root(x);
        int ry = root(y);
        if (rx == ry) return;
        if (rank[rx] < rank[ry]){
            par[rx] = ry;
        }
        else{
            par[ry] = rx;
            if (rank[rx] == rank[ry]) rank[rx]++;
        }
    }
    bool same(int x, int y){
        int rx = root(x);
        int ry = root(y);
        return rx == ry;
    }
};

/* セグメント木によるrmq */
struct rmq{
    int n; long arr[MAX];
    rmq(int n_){
        n = 2;
        while(n < n_) n *= 2;
        rep(i, n*2) arr[i] = (1L << 31) - 1;
    }
    void update(int k, int a){
        k += n - 1;
        arr[k] = a;
        while(k > 0){
            k = (k - 1) / 2;
            arr[k] = min(arr[k * 2 + 1], arr[k * 2 + 2]);
        }
    }
    long query(int a, int b, int k, int l, int r){
        // cout << k << " " << l << " " << r << endl;
        if(r <= a || b <= l) return (1L << 31) - 1;
        if(a <= l && r <= b) return arr[k];
        else{
            int vl = query(a, b, k * 2 + 1, l, (l + r) / 2);
            int vr = query(a, b, k * 2 + 2, (l + r) / 2, r);
            return min(vl, vr);
        }
    }
    void show(){
        rep(i, n*2){
            cout << arr[i] << " "; 
        }
        cout << endl;
    }
};

