    int blockID = getID(index) , start = blockID*blockSZ , end = (blockID+1)*blockSZ-1 ;

    for(int i=start ; i<=end ;i++)
    {
        if(i==start) BLOCK[blockID] = arr[i] ;
        else BLOCK[blockID] = min(BLOCK[blockID],arr[i]);
    }
}

