/** 区间表示：[p->dl,p->dr]
 *  从0开始计数，[0,n-1]
 *  线段树RSQ
 *
 */

struct Node
{
    int dl,dr,s;
    Node *pl,*pr;
};
int n,q;
static const int inf=(1<<31)-1;

void build(Node *&p,int l,int r)
{
    p=(Node *)malloc(sizeof(Node));
    p->dl=l,p->dr=r,p->s=inf;
    p->pl=null,p->pr=null;
    int mid=(l+r)/2;
    //到叶子节点处不需要再 继续分割，否则会无线循环下去，以为mid处没有值
    if(r>l)
    {
        build(p->pl,l,mid);
        build(p->pr,mid+1,r);//此处表示的都是闭区间
    }
}
int query(Node *&p,int l,int r)
{
    ///一个查询区间最终必然被分成若干个小的区间和，最后一个定会完全和区间贴合
    if(p->dl==l &&p->dr==r)
        return p->s;
    int mid=(p->dl+p->dr)/2;
    ///判断查询区间与当前区间的位置关系
    //全部位于左侧
    if(r<=mid)
        return query(p->pl,l,r);
    //全部位于右侧
    else if(l>mid)
        return query(p->pr,l,r);
    //两个都有
    else
        return min(query(p->pl,l,mid),query(p->pr,mid+1,r));
}

void update(Node *&p,int x,int data)
{
    if(p->dl==p->dr)//找到最后一个叶子节点
    {
        p->s=data;
        return;
    }
    int mid=(p->dl+p->dr)/2;
    if(x<=mid)
        update(p->pl,x,data);
    else
        update(p->pr,x,data);
    p->s=min(p->pl->s,p->pr->s);
}
int main()
{
    int i,type,tx,ty;
    Node *tree=null;
    scanf("%d%d",&n,&q);
    build(tree,0,n-1);
    for(i=0;i<q;i++)
    {
        scanf("%d%d%d",&type,&tx,&ty);
        if(type==0)
        {
            update(tree,tx,ty);
        }else
        {
            int ans=query(tree,tx,ty);
            printf("%d\n",ans);
        }
    }
    return 0;
}

