#define MAX 2147483647;
using namespace std;
int n;
int arr[100005];
struct Node {
	int min;
	int lowerLimit;
	int upperLimit;
	struct Node *left;
	struct Node *right;
};
Node* makeSegmentTree(int lower, int upper) {


	Node* node = (Node*)malloc(sizeof(Node));
	node->lowerLimit = lower;
	node->upperLimit = upper;

	if (lower == upper) {
		node->left = NULL;
		node->right = NULL;
		node->min = arr[lower];
		return node;
	}

	int middle = (lower + upper) / 2;
	node->left = makeSegmentTree(lower,middle);
	node->right = makeSegmentTree(middle+1,upper);
	node->min = min(node->left->min, node->right->min);

	return node;
}
int findMin(Node *node,int lower, int upper) {
	if (lower <= node->lowerLimit && upper >= node->upperLimit) {
		//printf("[%d,%d]:%d", node->lowerLimit, node->upperLimit,node->min);
		return node->min;
	}
	int middle = (node->lowerLimit + node->upperLimit) / 2;
	int minLeft = MAX;
	int minRight = MAX;

	//rintf("middle:%d\n", middle);

	if (lower <= middle) {
		minLeft = findMin(node->left, lower, upper);
	}
	if (upper >= (middle + 1)) {
		minRight = findMin(node->right,lower, upper);
	}
	return min(minLeft, minRight);
}
void update(Node *node,int position,int value) {
	if (node->lowerLimit == node->upperLimit) {
		node->min = value;

		return;
	}
	int middle = (node->upperLimit + node->lowerLimit) / 2;
	if (position <= middle) {
		update(node->left, position, value);
	}
	else {
		update(node->right, position, value);
	}
	int leftMin = node->left->min;
	int rightMin = node->right->min;
	node->min = min(leftMin, rightMin);
}
void preorder(Node *node) {
	if (node == NULL) {
		return;
	}
	printf("[%d,%d]:%d\n", node->lowerLimit, node->upperLimit,node->min);
	preorder(node->left);
	preorder(node->right);
}
void inorder(Node* node) {
	if (node == NULL) {
		return;
	}
	inorder(node->left);
	printf("[%d,%d]:%d\n", node->lowerLimit, node->upperLimit, node->min);
	inorder(node->right);
}
