	int q,op,l,r;
	//freopen("D:\\in.txt", "r", stdin);
	scanf("%d %d", &n, &q);

	for (int i = 0; i < n; i++) {
		arr[i] = MAX;
	}

	Node* root;
	root = makeSegmentTree(0,n-1);

	while (q--) {
		scanf("%d %d %d", &op, &l, &r);
		if (op == 0) {
			arr[l] = r;
			update(root,l, r);
		}
		else if(op == 1){
			int minQuery = findMin(root,l, r);
			printf("%d\n", minQuery);
