  vector<T> dat; // セグメント木
  long long SEG_MAX = 2147483647;

public:
  SegmentTreeRMQ(T num_elements) {
    this->init(num_elements);
  }

  SegmentTreeRMQ() {
    cout << "要素数を入力してください。" << endl;
  }

  void init(T num_elements) {
    // 要素数は2のべき乗にする。
    this->n_ = 1;
    while (n_ < num_elements) n_ *= 2;
    // todo: resize対応
    dat = vector<T>(n_ * 2 - 1, SEG_MAX);
  }

  void showSegTree() {
    for (int i = 0; i < n_ * 2 - 1; ++i) {
      cout << dat[i] << " ";
    }
    cout << "\n";
  }

  // k番目の値をaに更新
  void update(int k, int a) {
    // 葉の節点
    k += n_ - 1;
    dat[k] = a;

    while (k > 0) {
      k = (k - 1) / 2;
      dat[k] = min(dat[k * 2 + 1], dat[k * 2 + 2]);
    }
  }

  // [a,b)の最小値を求める
  // [l,r)を見ている
  T query(T a, T b, int k, int l, int r) {
    if (b < l or r < a) return SEG_MAX;

    if (a <= l and r <= b) {
      return dat[k];
    }
    else {
      T vl = query(a, b, k*2 + 1, l, (l + r) / 2);
      T vr = query(a, b, k*2 + 2, (l + r) / 2 + 1, r);

      return min(vl,vr);
    }
  }
};

