      N002<long> u(n, (1LL << 31) - 1,
                   [](long x, long y){ return std::min(x, y); });
      for(long i = 0; i < q; ++i) {
         long c, x, y;
         scan(c, x, y);
         if( c == 0 )
            update(u, x, y);
         else
            printf("%ld\n", rangeCompose(u, x, y + 1));
      }
   }
};

