template <typename NodeType, typename FuncType>
struct SegmentTree {
    int length;
    vector<NodeType> node;
    NodeType identity;
    FuncType func;

    SegmentTree(int length_, NodeType identity_, FuncType func_) : identity(identity_), func(func_) {
        length = 1;
        while (length < length_) length <<= 1;
        node.resize(length << 1, identity);
    }

    void change(int idx, NodeType val) {
        idx += length;
        node[idx] = val;
        while (idx >>= 1) node[idx] = func(node[(idx << 1) | 0], node[(idx << 1) | 1]);
    }

    NodeType query(int l, int r) {
        l += length; r += length;
        NodeType vl = identity, vr = identity;
        while (l < r) {
            if (l & 1) vl = func(vl, node[l++]);
            if (r & 1) vr = func(node[--r], vr);
            l >>= 1; r >>= 1;
        }
        return func(vl, vr);
    }
};

