class SegTree{
	int n;
	vector<int> seg;
public:
	SegTree(int n_){
		n = 1;
		while(n < n_) n = n << 1;
		REP(i, 2*n-1){
			seg.push_back((1<<31)-1);
		}
	}

	void update(int i, int x){
		i = i + n - 1;
		seg[i] = x;
		while(i > 0){
			i = (i-1)/2;
			seg[i] = min(seg[i*2+1], seg[i*2+2]);
		}
	}

	ll a(int s, int t){
		return find(s, t, 0, 0, n);
	}

	ll find(int s, int t, int x, int l, int r){
		ll res = (1<<31)-1;

		if(r <= s || t <= l) return res;
		if(s <= l && r <= t) return seg[x];

		res = min(res, find(s, t, x*2+1, l, (l+r)/2));
		res = min(res, find(s, t, x*2+2, (l+r)/2, r));
		return res;
	}
};

int main(void){
	int n, q;
	cin >> n >> q;
	SegTree sg(n);
	REP(i, q){
		int com, x, y;
		cin >> com >> x >> y;
		if(com == 0){
			sg.update(x, y);
		}else{
			cout << sg.a(x, y+1) << endl;
		}
	}
}

