long long update( int ini, int fin, int nd, int x, long long v ){


	if( x < ini || x > fin )
		return T[nd];

	if( ini == fin ){
		T[nd] = v;
		return T[nd];
	}

	int l = nd << 1;
	int r = l | 1;
	int m = ( ini + fin ) >> 1;

	long long n1 = update( ini, m, l, x, v );
	long long n2 = update( m + 1, fin, r, x, v );
	T[nd] = min(n1, n2);	
	return T[nd];
}

long long query( int ini, int fin, int nd, int s, int t ){

	if( s > fin || t < ini )
		return INF;

	if( s <= ini && fin <= t )
		return T[nd];

	int l = nd << 1;
	int r = l | 1;
	int m = ( ini + fin ) >> 1;

	long long n1 = query( ini, m, l, s, t );
	long long n2 = query( m + 1, fin, r, s, t );
	return min(n1, n2);	
}


