struct SegmentTree {
    int n;
    vector<int> heap;

    SegmentTree(int n): n(n) {
        heap.assign(4 * n, INF);
    }

    void update(int id, int l, int r, int q, int v) {
        if (id == -1) {
            return;
        }
        if (l == r) {
            heap[id] = v;
        }
        else {
            int m = l + (r - l)/2;
            if (q >= l && q <= m) {
                update(2 * id, l, m, q, v);
            }
            else if (q > m && q <= r) {
                update(2 * id + 1, m + 1, r, q, v);
            }
            pushup(id);
        }
    }

    int query (int id, int l, int r, int ql, int qr) {
        if (ql <= l &&  r <= qr) {
            return heap[id];
        }
        else {
            int m = l + (r - l)/2;
            int lvalue = INF;
            int rvalue = INF;
            if (ql <= m && qr >= l) {
                lvalue = query(2 * id, l, m, ql, qr);
            }
            else if (qr > m && ql <= r) {
                rvalue = query(2 * id + 1, m + 1, r, ql, qr);
            }
            return min(lvalue, rvalue);
        }
    }

    void pushup(int id) {
        heap[id] = min(heap[2 * id], heap[2 * id + 1]); 
    }

};

