constexpr int B = 330;

inline void chmin (int &a, int b) {
    if (a > b) a = b;
}

int main() {
    int n, q, op, x, y;
    cin >> n >> q;
    vector<int> a(B * B, INT_MAX), b(B, INT_MAX);

    auto update = [&] (int i, const int &x) -> void {
        const int id = i / B, k = id * B;
        a[i] = x; b[id] = INT_MAX;
        for (int j = k; j < k + B; j++) chmin(b[id], a[j]);
    };

    auto find_min = [&] (int l, int r) -> int {
        int res = INT_MAX;
        for (int i = l / B + 1; i < r / B; i++) chmin(res, b[i]);
        int vl = min(r, l / B * B + B), vr = max(l, r / B * B);
        for (int i = l; i < vl; i++) chmin(res, a[i]);
        for (int i = vr; i < r; i++) chmin(res, a[i]);
        return res;
    };

    while (q--) {
        cin >> op >> x >> y;
        if (op == 0) update(x, y);
        else cout << find_min(x, y + 1) << '\n';
    }

    return 0;
}

