unsigned long long clp(unsigned long long x)
{
    x -= 1;
    x = x | (x >>  1);
    x = x | (x >>  2);
    x = x | (x >>  4);
    x = x | (x >>  8);
    x = x | (x >> 16);
    x = x | (x >> 32);
    return x + 1;
}

// a[0], a[1], ... , a[n - 1] is a given array of length n.
// T is the type of elements of array a.
// ZERO is a element such that for any element x, f(x, ZERO) == x.
// e.g. f(x, y) = sum(x, y), ZERO = 0.
// e.g. f(x, y) = min(x, y), ZERO = INFINITY.
template <class T>
class segment_tree
{
    private:
        const size_t n;
        const T ZERO;
        function<T(T, T)> f;
        T *a;
    public:
        segment_tree(size_t size, T ZERO, function<T(T, T)> f) : n(clp(size)), ZERO(ZERO), f(f)
        {
            //printf("n is initialized: %d\n", n);
            a = new T[2 * n - 1];
            fill(a, a + 2 * n - 1, ZERO);
        }
        template <class Iterator>
        segment_tree(Iterator first, Iterator last, int ZERO, function<T(T, T)> f) : n(clp(distance(first, last))), ZERO(ZERO), f(f)
        {
            size_t size = distance(first, last);
            a = new T[2 * n - 1];
            fill(a, a + 2 * n - 1, ZERO);
            /*
            for (int i = 0; i < size; ++i) {
                a[i] = {kk*/
        }
        ~segment_tree() {
            delete [] a;
        }
        void update(size_t i, T x)
        {
            i += n - 1;
            a[i] = x;
            while (i) {
                i = (i - 1) / 2;
                a[i] = f(a[2 * i + 1], a[2 * i + 2]);
            }
            /*printf("updated:\n");
            for (int i = 0; i < 2 * n - 1; i++) {
                printf("a[%d] = %d\n", i, a[i]);
            }*/
        }
        T query(size_t query_first, size_t query_last, size_t k = 0, size_t node_first = 0, size_t node_last = 0)
        {
            if (k == 0) {
                node_last = n;
            }
            if (node_last <= query_first || query_last <= node_first) {
                return ZERO;
            }
            if (query_first <= node_first && node_last <= query_last) {
                return a[k];
            } else {
                size_t node_mid = (node_first + node_last) / 2;
                T vl = query(query_first, query_last, k * 2 + 1, node_first, node_mid);
                T vr = query(query_first, query_last, k * 2 + 2, node_mid, node_last);
                return f(vl, vr);
            }
        }
};

