struct Segtree{
        using F = std::function<ll(ll,ll)>;
        std::vector<ll> seg;
        int size;
        ll unit;
        F func;

        Segtree(int n, ll u, F f): unit(u), func(f) {
                size = 1;
                while(size<n) size <<= 1;
                seg.assign(2*size-1, unit);
                for(int k=size-2; k>=0; k--) seg[k] = func(seg[2*k+1], seg[2*k+2]);
        }

        void update(int idx, ll x){
                idx += size-1;
                seg[idx] = x;
                while(idx>0){
                        idx = (idx-1) / 2;
                        seg[idx] = func(seg[2*idx+1], seg[2*idx+2]);
                }
        }

        ll query(int a, int b, int k=0, int l=0, int r=-1){
                if(r<0) r = size;
                if(b<=l or r<=a) return unit;
                if(a<=l and r<=b) return seg[k];
                ll lvalue = query(a, b, 2*k+1, l, (l+r)/2);
                ll rvalue = query(a, b, 2*k+2, (l+r)/2, r);
                return func(lvalue, rvalue);
        }
};


