class SegmentTree{
    vector<int> tree;
    int index;
    int evaluation(int a,int b){
        return min(a,b);
    }
    public:
    int size=0;
    SegmentTree(int n){
        int len = 1;
        while(len<n)len *= 2;
        tree.resize(len*2-1,max_int);
        index = len-1;
        size = len;
    }
    void update(int a,int x){
        a += index;
        tree[a] = x;
        while(a>0){
            a = (a-1)/2;
            tree[a] = evaluation(tree[a*2+1],tree[a*2+2]);
        }
    }
    int query(int a,int b){
        return query(a,b,0,0,size);
    }
    int query(int a,int b,int k,int l,int r){
        if(b<=l||r<=a)return max_int;
        if(a<=l&&r<=b)return tree[k];
        int vl=query(a,b,2*k+1,l,(l+r)/2);
        int vr=query(a,b,2*k+2,(l+r)/2,r);
        return evaluation(vl,vr);
    }

    void Print() {
        Debug(tree);
    }
};

