size_t ceil_pow2(size_t n)
{
    size_t res = 1;
    while (res < n) res <<= 1;
    return res;
}

template<class M, class F>
class SegTree
{
    size_t N;
    F f;
    std::vector<M> a;

    M query_r(size_t L, size_t R, size_t k, size_t l, size_t r)
    {
        if (r <= L || R <= l)
            return a[0];
        else if (L <= l && r <= R)
            return a[k];
        else
        {
            size_t c = l + (r - l) / 2;
            M m1 = query_r(L, R, 2*k  , l, c);
            M m2 = query_r(L, R, 2*k+1, c, r);
            return f(m1, m2);
        }
    }

public:

    explicit SegTree(size_t n, F f, M e)
    : N(ceil_pow2(n)), f(f), a(2 * N, e)
    {}

    template<class InItr>
    explicit SegTree(InItr first, InItr last, F f, M e)
    : SegTree(std::distance(first, last), f, e)
    {
        size_t i = 0;
        InItr it = first;
        while (it != last)
        {
            update(i++, *it++);
        }
    }

    void update(size_t i, M x)
    {
        i += N;
        a[i] = x;

        for (size_t ii = i / 2; ii > 0; ii /= 2)
        {
            a[ii] = f(a[2*ii], a[2*ii+1]);
        }
    }

    M query(size_t L, size_t R)
    {
        return query_r(L, R, 1, 0, N);
    }

};

