//再帰タイプ
template<typename T_n>//使うときはsegment_tree<double> S(left,right,_default);のように型を指定する
struct segment_tree{
	typedef struct node_{
		T_n value;
		int left,right; //[left,right)
		struct node_ *left_child,*right_child;
	}* node;
	node parent_node = new node_;
	T_n default_value;//範囲外の場合の評価値
	T_n eval(T_n a, T_n b){//segment_treeの評価関数
		return min(a,b);
	}
	T_n back_propagation(T_n before, T_n after){//伝播する値を計算
		return min(before,after);
	}
	segment_tree(int left,int right,T_n _default){//どんな範囲でも作れる
		default_value = _default;
		make_segtree_(parent_node,left,right);
	};
	void make_segtree_(node p,int left,int right){
		p->left=left;
		p->right=right;
		p->value=default_value;
		if(left+1!=right){
			node q=new node_, r=new node_;
			p->left_child=q;
			p->right_child=r;
			make_segtree_(q,left,(left+right)/2);
			make_segtree_(r,(left+right)/2,right);
		}else{//要素数が1個
			p->left_child=NULL;
			p->right_child=NULL;
		}
	}
	T_n query(int left,int right){
		return query_(parent_node,left,right);
	}
	T_n query_(node p,int left,int right){
		if(p->right<=left || right<=p->left)return default_value;
		if(left<=p->left && p->right<=right)return p->value;
		return eval( query_(p->left_child,left,right), query_(p->right_child,left,right) );
	}
	void change(int pos,T_n value){
		change_(parent_node,pos,value);
	}
	T_n change_(node p,int pos,T_n value){
		//上に差分を伝播
		T_n diff;
		if(p->left<=pos && pos<p->right){//入っているなら
			if(p->left==pos && pos+1==p->right){//justなら
				diff = back_propagation(p->value,value);
			}else{
				diff = eval(change_(p->left_child,pos,value), change_(p->right_child,pos,value));
			}
			p->value = eval(p->value,diff);
		}else{
			diff=default_value;
		}
		return diff;//差分が上に伝播する
	}
};

