void init(int firstN){
    while(N < firstN)
        N *= 2;
}

void update(int loc, int value){
    loc += N - 1;
    table[loc] = value;
    if(N == 1)
        return;
    int parent = (loc - 1) / 2;
    while(true){
        table[parent] = min(table[2 * parent + 1], table[2 * parent + 2]);
        if(parent == 0)
            break;
        else
            parent = (parent - 1) / 2;
    }
}

int query(int searchLeft, int searchRight, int nodeId, int nodeLeft, int nodeRight){
    if(searchRight < nodeLeft || searchLeft > nodeRight)
        return MAX;
    if(searchLeft <= nodeLeft && searchRight >= nodeRight)
        return table[nodeId];

    int leftMin = query(searchLeft, searchRight, 2*nodeId+1, nodeLeft, (nodeLeft+nodeRight)/2);
    int rightMin = query(searchLeft, searchRight, 2*nodeId+2, (nodeLeft+nodeRight)/2+1, nodeRight);

    return min(leftMin, rightMin);
}

