using namespace std;

template<class T, class U> struct SegmentTree {
    using F = function<T(T, T)>;
    using G = function<T(T, U)>;
    int n;
    T id;
    vector<T> data;
    F f;
    G g;

    SegmentTree(int sz, F f, G g, T def) : f(f), g(g) {
        n = 1; id = def;
        while (n < sz) n *= 2;
        data = vector<T>(2*n-1, id);
    }
    void update (int i, T x) {
        i += n - 1;
        data[i] = g(data[i], x);
        while (i > 0) {
            i = (i - 1) / 2;
            data[i] = f(data[i * 2 + 1], data[i * 2 + 2]);
        }
    }
    T query(int a, int b, int k = 0, int l = 0, int r = -1) {
        if (r < 0) r = n;
        if (r <= a || b <= l) return id;
        if (a <= l && r <= b) return data[k];
        T vl = query(a, b, 2 * k + 1, l, (l + r) / 2);
        T vr = query(a, b, 2 * k + 2, (l + r) / 2, r);
        return f(vl, vr);
    }
};

int main() {
    int N, Q;
    cin >> N >> Q;

    auto f = [](int a, int b) { return min(a, b); };
    auto g = [](int a, int b) { return b; };
    SegmentTree<int, int> sg(N, f, g, INT_MAX);
    for (int q = 0; q < Q; q++) {
        int c, x, y;
        cin >> c >> x >> y;
        if (c&1) {
            if (x > y) swap(x, y);
            int res = sg.query(x, y+1);
            printf("%d\n", res);
        } else {
            sg.update(x, y);
        }
    }
    return 0;
}

