typedef long long Long;

const Long INF = ((Long)1<<31) - 1;

class SegTree {
public:
    int m_n;
    vector<Long> m_data;

    SegTree( int n ) { Init( n ); }

    void Init( int n ) {

	m_n = 1;
	while ( m_n < n ) m_n <<= 1;

	m_data.resize( 2*m_n - 1, INF );
    }

    void Update( int k, Long val ) {

	k += m_n - 1;

	m_data[k] = val;

	while ( k > 0 ) {
	    k = ( k - 1 )/2;
	    m_data[k] = min( m_data[2*k+1], m_data[2*k+2] );
	}
    }

    Long RMQ( int a, int b ) {
	return query( a, b + 1, 0, 0, m_n );
    }

protected:

    Long query( int a, int b, int k, int l, int r ) {

	if ( b <= l || a >= r ) return INF;

	if ( a <= l && r <= b ) return m_data[k];

	Long left = query( a, b, 2*k+1, l, (l+r)/2 );
	Long right = query( a, b, 2*k+2, (l+r)/2, r );

	return min( left, right );
    }

};


int main() {

    int n, q;

    cin >> n >> q;

    SegTree seg( n );

    int c, x, y;
    for ( int i=0; i<q; ++i ) {

	cin >> c >> x >> y;
	if ( c == 0 ) seg.Update( x, y );
	else cout << seg.RMQ( x, y ) << endl;

    }

    return 0;
}

