//main code

class SegTree {
private:
	LL n;
	VL node;
public:
	SegTree(const VL& v)
	{
		LL sz = v.size();
		n = 1;while(n < sz) n *= 2; // 最低限必要な最下段のノード数(2のべき乗)
		node.resize(2*n-1, INT64_MAX);
		for (int i = 0; i < sz; i++) {
			node[n+i-1] = v[i];
		}
		for (int i = n-2; i >= 0; i--) {
			node[i] = min(node[i*2+1], node[i*2+2]);
		}
	};

	void update(LL pos, LL val)
	{
		LL k = n+pos-1;
		node[k] = val;
		while (k > 0) {
			k = (k-1)/2;
			node[k] = min(node[2*k+1], node[2*k+2]);
		}
	}

	// [a,b)区間内の要素の最小値を答える
	// [l,r)が対象区間, kが今いるノード
	LL getmin(LL a, LL b, LL k=0, LL l=0, LL r=-1)
	{
		if (r == -1) r = n;
		LL ret = INT64_MAX;
		if (r <= a or l >= b) return ret;
		if (l >= a and r <= b) return node[k];

		//対象区間の一部が要求区間である
		LL vl = getmin(a, b, k*2+1, l, (l+r)/2);
		LL vr = getmin(a, b, k*2+2, (l+r)/2, r);
		return min(vl, vr);
	}
};

