#define INF 2147483647
struct SqrtDecomposition {
  ll N, K, sqrtN;
  vector<ll> data;
  vector<ll> bucketMin;
  SqrtDecomposition(ll n) : N(n) {
    sqrtN = sqrt(N)+1;
    K = (N + sqrtN - 1) / sqrtN;
    data.assign(K * sqrtN, INF);
    bucketMin.assign(K, INF);
  }
  void update(ll x, ll y) {
    ll k = x / sqrtN;
    ll minVal = data[x] = y;
    for (ll i = k * sqrtN; i < (k + 1) * sqrtN; ++i) {
      minVal = min(minVal, data[i]);
    }
    bucketMin[k] = minVal;
  }
  // [x, y)
  ll find(ll x, ll y) {
    ll minVal = INF;
    for (ll k = 0; k < K; ++k) {
      ll l = k * sqrtN, r = (k + 1) * sqrtN;
      if (r <= x || y <= l)
        continue;
      if (x <= l && r <= y) {
        minVal = min(minVal, bucketMin[k]);
      } else {
        for (ll i = max(x, l); i < min(y, r); ++i) {
          minVal = min(minVal, data[i]);
        }
      }
    }
    return minVal;
  }
};

int main(void){
    long long n,q;
    cin>>n>>q;
    SqrtDecomposition sd(n);
    for(ll i=0;i<q;i++){
        long long c,x,y;
        cin>>c>>x>>y;
        if(c){
            cout<<sd.find(x,y+1)<<endl;
        }else{
            sd.update(x,y);
        }
    }
    return 0;
}

