            tree[idx] = min(tree[idx << 1], tree[(idx << 1) + 1]);
        }
    }

    T get(int begin, int end, int left, int right, int idx) {
        if (begin <= left && right <= end) return tree[idx];
        if (right <= begin || end <= left) return inf;

        int mid = (left + right) / 2;
        return min(get(begin, end, left, mid, idx << 1), get(begin, end, mid, right, (idx << 1) + 1));
    }

    inline T get(int begin, int end) {
        return get(begin, end, 0, n, 1);
    }

};



