	const ::std::size_t f, l;

public:
	using value_type = ::std::size_t;
	using reference = value_type;
	class repitr {
		friend rep;
		value_type i;
		repitr(value_type x) noexcept : i(x) {}

	public:
		void operator++() noexcept { ++i; }
		reference operator*() const noexcept { return i; }
		bool operator!=(const repitr x) const noexcept { return i != x.i; }
	};
	explicit rep(value_type first, value_type last) noexcept
		: f(first), l(last) {}
	repitr begin() const noexcept { return repitr(f); }
	repitr end() const noexcept { return repitr(l); }
};
class revrep {
	const ::std::size_t f, l;

public:
	using value_type = ::std::size_t;
	using reference = value_type;
	class revrepitr {
		friend revrep;
		value_type i;
		revrepitr(value_type x) noexcept : i(x) {}

	public:
		void operator++() noexcept { --i; }
		reference operator*() const noexcept { return i; }
		bool operator!=(const revrepitr x) const noexcept { return i != x.i; }
	};
	explicit revrep(value_type first, value_type last) noexcept
		: f(first), l(last) {}
	revrepitr begin() const noexcept { return revrepitr(l - 1); }
	revrepitr end() const noexcept { return revrepitr(f - 1); }
};
