template<typename T>
struct SegTree{
  const T e = numeric_limits<T>::max(); //単位元
  vector<T> dat;
  int n;
  SegTree(int n_): n(), dat(4*n_, (1LL<<31)-1){
    int x = 1;
    while(n_ > x) x *= 2;
    n = x;
  }

  SegTree(vector<T> v): n(), dat(4*v.size(), e){
    int x = 1;
    int n_ = v.size();
    while(n_ > x) x *= 2;
    n = x;
    for(int i = 0; i < n_; i++) dat.at(i+n-1) = v.at(i);
    for(int i = n-2; i >= 0; i--) dat.at(i) = min(dat.at(2*i+1), dat.at(2*i+2)); //演算
  }

  void set(int i, T x){dat.at(i + n-1) = x;}
  void build(){
    for(int i = n-2; i >= 0; i--) dat.at(i) = min(dat.at(2*i+1), dat.at(2*i+2)); //演算
  }

  void update(int i, T x){
    i += n-1;
    dat.at(i) = x;
    while(i > 0){
      i = (i-1)/2;
      dat.at(i) = min(dat.at(2*i+1), dat.at(2*i+2)); //演算
    }
  }

  T query_sub(int a, int b, int k, int l, int r){
    if(r <= a || b <= l) return e;
    else if(a <= l && r <= b) return dat.at(k);
    else{
      T vl = query_sub(a, b, 2*k+1, l, (l+r)/2);
      T vr = query_sub(a, b, 2*k+2, (l+r)/2, r);
      return min(vl, vr); //演算
    }
  }
  T query(int a, int b){return query_sub(a, b, 0, 0, n);}

  T getval(int i){return dat.at(i+n-1);}
};

int main(){
  ios::sync_with_stdio(false);
  cin.tie(nullptr);
  ll n, q;
  cin >> n >> q;
  SegTree<ll> st(n);
  while(q--){
    int query;
    ll x, y;
    cin >> query;
    cin >> x >> y;
    if(query == 0){
      st.update(x, y);
    }
    else{
      cout << st.query(x, y+1) << endl;
    }
  }
}

