int sqrtN;
int N, Q;
vector<int> data, backet;

int get(int l, int r) {
    int res = INT_MAX;
    for (int i = l; i <= r; ++i) {
        if (i % sqrtN == 0 && i + sqrtN <= r) {
            res = min(res, backet[i / sqrtN]);
            i += sqrtN - 1;
        } else {
            res = min(res, data[i]);
        }
    }
    return res;
}

void update(int p, int val) {
    data[p] = val;
    for (int i = (p / sqrtN) * sqrtN; i - (p / sqrtN) * sqrtN <= sqrtN; ++i) {
        backet[p / sqrtN] = min(backet[p / sqrtN], data[i]);
    }
}

void debug() {
    cerr << "data = ";
    for (int e : data) cerr << e << " ";cerr << endl;
    cerr << "backet = ";
    for (int e : backet) cerr << e << " ";cerr << endl;
}

int main() {
    scanf("%d%d", &N, &Q);
    sqrtN = sqrt(N);
    data.resize(N, INT_MAX);
    backet.resize(sqrtN + 2, INT_MAX);
    while (Q--) {
        int c, x, y;
        //debug();
        scanf("%d%d%d", &c, &x, &y);
        if (c) {
            cout << get(x, y) << endl;
        } else {
            update(x, y);
        }
    }
}

