#include <iostream>
using namespace std;

unsigned tree[1<<18];
int n, q;
const unsigned inf=-1;

void build(int id=0, int l=0, int r=n)
{
    if (r-l<2) {
        tree[id]=(1LL<<31)-1;
        return;
    }
    int m=l+r>>1;
    build(2*id+1, l, m);
    build(2*id+2, m, r);
}

void update(int x, int y, int v, int id=0, int l=0, int r=n)
{
    if (x>=r or y<=l) return;
    if (x<=l and r<=y) {
        tree[id]=v;
        return;
    }
    int m=l+r>>1;
    int L=2*id+1, R=L+1;
    update(x, y, v, L, l, m);
    update(x, y, v, R, m, r);
    tree[id]=min(tree[L], tree[R]);
}

unsigned find(int x, int y, int id=0, int l=0, int r=n)
{
    if (x>=r or y<=l) return inf;
    if (x<=l and r<=y) return tree[id];
    int m=l+r>>1;
    return min(find(x, y, 2*id+1, l, m), find(x, y, 2*id+2, m, r));
}

