    scanf("%d%d", &n, &q);
    init(n);
    for(int i = 0; i < q; i++){
        int c, x, y;
        scanf("%d%d%d", &c, &x, &y);
        if(c == 0){
            update(x, y, 0, 0, n);
        }else{
            int ret = find(x, y+1, 0, 0, n);
            printf("%d\n", ret);
        }
    }

    return 0;
}

