	repi(i, 0, 2 * m - 1) dat[i] = max_value;
}

void update(ll k, ll a) {
	k += n;
	dat[k] = a;
	while (k > 0) {
		k = (k - 1) / 2;
		dat[k] = min(dat[k * 2 + 1], dat[k * 2 + 2]);
	}
}

ll query(ll a, ll b, ll k, ll l, ll r) {
	if (r < a || b < l) 
		return max_value;
	if (a <= l && r <= b) 
		return dat[k];
	else {
		ll vl = query(a, b, k * 2 + 1, l, (l + r) / 2);
		ll vr = query(a, b, k * 2 + 2, (l + r + 1) / 2, r);
		return min(vl, vr);
	}
}

