class SegTreeRMQ {
private:
    std::vector<int> node;

public:
    explicit SegTreeRMQ(int sz) :node(sz * 2, hoge) {}

    int size() { return node.size() / 2; }

    void update(int x, int val) {
        x += size();
        node[x] = val;
        while (x /= 2) {
            node[x] = min(node[x * 2],node[x * 2 + 1]);
        }
    }

    int getmin(int p, int q) {
        if(p == q)return node[p+size()];
        int ret = hoge;
        p += size();
        q += size();
        while (p < q) {
            if (p % 2 == 1) {
                ret = min(ret,node[p]);
                ++p;
            }
            p /= 2;
            if (q % 2 == 1) {
                --q;
                ret = min(ret,node[q]);
            }
            q /= 2;
        }
        return ret;
    }
    void show(){
        for(int i = 0;i < node.size();i++){
            cout<<node[i]<<" ";
        }
        cout<<endl;
    }
};

