            size=1;
            while (size<n_) size*=2;
            for (int i=0; i<2*size-1; i++) node[i]=INT_MAX;
        }

        void update(int k,int a){
            k+=size-1;
            node[k]=a;
            while (k>0){
                k=(k-1)/2;
                node[k]=min(node[2*k+1],node[2*k+2]);
            }
        }

        int get_min(int queryL,int queryR,int k=0,int nodeL=0,int nodeR=-1){
