                int nodeM=(nodeL+nodeR)/2;
                int vl=get_min(queryL,queryR,k*2+1,nodeL,nodeM);
                int vr=get_min(queryL,queryR,k*2+2,nodeM,nodeR);
                return min(vl,vr);
            }
        }
    };

