#define CLR(a) memset((a), 0 ,sizeof(a))

const int MAX_N=400004;
int dat[MAX_N];
int N;

int init(){
	fill(dat,dat+MAX_N,INF);
}
int find(int a,int b,int k=0, int l=0,int r=N){
	if(r<=a||b<=l)return INF;
	if(a<=l&&r<=b){
		return dat[k];
	}else{
		int vl=find(a,b,k*2+1,l,(l+r)/2);
		int vr=find(a,b,k*2+2,(l+r)/2,r);
		return min(vl,vr);
	}
}

void update(int k,int x){
	k+=N;
	dat[k]=x;
	while(k>0){
		k=(k-1)/2;
		dat[k]=min(dat[k*2+1],dat[k*2+2]);
	}
}

int main(){
	int Q;
	cin>>N>>Q;
	init();
	REP(i,Q){
		int c,x,y;
		cin>>c>>x>>y;
		if(c==0){
			update(x,y);
		}else{
			cout<<find(x,y+1)<<endl;
		}
	}
	//REP(i,SZ(res))cout<<res[i]<<endl;
	return 0;
}

