template <class T> struct segment_tree_min_multi_update{
    struct node{
        T val;
        T lazytag;
    };
    vector<node> arr;
public:
    void init(const vector<T> &a){
        arr.resize(2*a.size()-1);
        initialize(a,0,0,a.size()-1);
        return ;
    }
    void set(T n,int size){
        arr.resize(2*size-1);
        arr[0].val=n;
        arr[0].lazytag=n;
        for(int i=1;i<arr.size();i++)arr[i].lazytag=0;
        return ;
    }
    void update(T n,int L,int R){
        update_val(n,0,0,(int)arr.size()-1,L,R);
        return ;
    }
