        return find_val(0,0,(int)arr.size()-1,L,R);
    }
private:
    void initialize(const vector<T> &a,int now,int l,int r){
        if(l==r)arr[now]=a[l];
        else {
            int mid=(l+r)/2;
            initialize(a,now*2+1,l,mid);
            initialize(a,now*2+2,mid+1,r);
            arr[now]=min(arr[now*2+1],arr[now*2+2]);
        }
        return ;
    }
    void update_val(T n,int now,int l,int r,int L,int R){
        if(L>r||l>R)return ;
        if(R>=r&&l>=L){
            arr[now].val=n;
            arr[now].lazytag=n;
            return ;
        }
        int mid=(l+r)/2;
        if(arr[now].lazytag!=0){
            arr[now*2+1].val=arr[now].lazytag;
            arr[now*2+1].lazytag=arr[now].lazytag;
            arr[now*2+2].val=arr[now].lazytag;
            arr[now*2+2].lazytag=arr[now].lazytag;
            arr[now].lazytag=0;
        }
        update_val(n,now*2+1,l,mid,L,R);
        update_val(n,now*2+2,mid+1,r,L,R);
        arr[now].val=min(arr[now*2+1].val,arr[now*2+2].val);
        return ;
    }
    T find_val(int now,int l,int r,int L,int R){
        if(L>r||l>R)return INF;
        if(R>=r&&l>=L)return arr[now].val;
        int mid=(l+r)/2;
        arr[now*2+1].val+=arr[now].lazytag;
        arr[now*2+1].lazytag+=arr[now].lazytag;
        arr[now*2+2].val+=arr[now].lazytag;
        arr[now*2+2].lazytag+=arr[now].lazytag;
        arr[now].lazytag=0;
        return min(find_val(now*2+1,l,mid,L,R),find_val(now*2+2,mid+1,r,L,R));
    }
};
