int query(int l, int r, int a, int b, int pos) {
	if (l <= a && b <= r) { return dat[pos]; }
	if (l > b)return 2147483647; if (r < a)return 2147483647;
	int D1 = query(l, r, a, (a + b + 1) / 2 - 1, pos * 2);
	int D2 = query(l, r, (a + b + 1) / 2, b, pos * 2 + 1);
	return min(D1, D2);
}
