		int c; cin >> c;
		if (c == 0) {
			//update(i,x)
			int i, x; cin >> i >> x;
			update(i, x);
		}
		else {
			//find(s,t)
			int s, t;
			cin >> s >> t;
			cout << query(s, t + 1, 0, 0, n) << endl;
		}
	}
	return 0;
}

