struct node {
    int l, r, m;
    ll v;
    struct node *cl, *cr;
};

typedef struct node node_t;

node_t *mktree(int l, int r) {
    auto ret = new node_t;
    ret->l = l;
    ret->r = r;
    ret->m = (l + r) / 2;
    ret->v = ((ull) 1 << (ull) 31) - 1;
    if (r - l > 1) {
        ret->cl = mktree(l, ret->m);
        ret->cr = mktree(ret->m, r);
    }
    return ret;
}

void update(int i, ll x, node_t *t) {
    if (t->r - t->l <= 1) {
        if (t->l == i) {
            t->v = x;
        } else {
            throw;
        }
    } else {
        if (i < t->m) {
            update(i, x, t->cl);
        } else {
            update(i, x, t->cr);
        }
        t->v = min(t->cl->v, t->cr->v);
    }
}

ll find(int s, int t, node_t *r) {
    if (s <= r->l && r->r <= t) return r->v;
    ll ret = inf;
    if (s < r->m) ret = min(ret, find(s, t, r->cl));
    if (r->m < t) ret = min(ret, find(s, t, r->cr));
    return ret;
}

