  public:
    SegmentTree(vector<int> vec)
    {
        int size = vec.size();

        while (N < size)
            N *= 2;

        node.resize(2 * N - 1, INT_MAX);

        rep(i, size) node[i + N - 1] = vec[i];
        for(int i = N - 2; i >= 0; i--) node[i] = min(node[2 * i + 1], node[2 * i + 2]);
    }

    void update(int i, int value)
    {
        i += N - 1;
        node[i] = value;
        while(i > 0)
