template<class T>class SegmentTree {
	using Func = function<T(T, T)>;
	int N; T init;
	vector<T> A;
	Func F;
	int ceil2(int n)noexcept { int m = 1; while (m < n)m *= 2; return m; }

public:
	SegmentTree(int n, const T& init_, const Func f)
		: N(ceil2(n)), init(init_), A(N * 2, init), F(f) {}
	SegmentTree(const vector<T>& vec, const T& init_, const Func f) : init(init_), F(f) { build(vec); }
	void build(const vector<int>& v) {
		N = ceil2(v.size());
		A.assign(N * 2);
		for (int i = 0; i < v.size(); ++i) {
			A[i + N] = v[i];
		}
		for (int i = N - 1; i > 0; --i) {
			A[i] = F(A[i * 2], A[i * 2 + 1]);
		}
	}
	void update(int i, const T& x) {
		assert(0 <= i && i < N);
		i += N; A[i] = x;
		while (i >>= 1) {
			A[i] = F(A[i * 2], A[i * 2 + 1]);
		}
	}
	T operator[](int i) {
		assert(0 <= i && i < N);
		return A[i + N];
	}
	T operator()(int l, int r) { // [l, r)
		assert(0 <= l && l < r && r <= N);
		T L = init, R = init;
		for (l += N, r += N; l < r; l >>= 1, r >>= 1) {
			if (l & 1)L = F(L, A[l++]);
			if (r & 1)R = F(A[--r], R);
		}
		return F(L, R);
	}
};

