template<class T>
class SegTree {
    T unit;
    size_t size;
    vector<T> node;
    function<T(T, T)> op, up;

    T _query(size_t a, size_t b, size_t k, size_t l, size_t r) {
        if (r<=a || b<=l) return unit;
        if (a<=l && r<=b) return node[k];
        else {
            T c1 = _query(a, b, 2*k+1, l, (l+r)/2);
            T c2 = _query(a, b, 2*k+2, (l+r)/2, r);
            return op(c1, c2);
        }
    }
public:
    SegTree(size_t _n, T _unit,  function<T(T, T)> _op, 
            function<T(T, T)> _up) 
            : unit(_unit), op(_op), up(_up) {
        size = 1;
        while(size < _n) size<<=1;
        node.resize(2*size-1, unit);
    }

    T operator[](size_t i) {
        return node[i+size-1];
    }

    void update(size_t x, ll val) {
        x += size-1;
        node[x] = up(node[x], val);
        while(x > 0) {
            x = (x-1)/2;
            node[x] = op(node[2*x+1], node[2*x+2]);
        }
    }
    T query(size_t a, size_t b) {
        return _query(a, b, 0, 0, size);
    }
};

