template<typename T>
class bucket {
private:
    ll bsz;
    function<T(T, T)>operation;
    T identity;
    vector<T>dat, buc;
public:
    bucket(ll dsz, ll bsz, function<T(T, T)>opr, T id)
        :bsz(bsz), operation(opr), identity(id),
        dat(dsz, identity), buc((dsz + bsz - 1) / bsz)
    {
        update();
    }
    T &operator[](ll idx)
    {
        return dat[idx];
    }
    void update()
    {
        REP(b, buc.size()) {
            auto itr = dat.begin() + b * bsz;
            buc[b] = accumulate(itr, itr + bsz, identity, operation);
        }
    }
    void update(ll idx, T val)
    {
        dat[idx] = val;
        ll b = idx / bsz;
        auto itr = dat.begin() + b * bsz;
        buc[b] = accumulate(itr, itr + bsz, identity, operation);
    }
    T query(ll l, ll r)
    {
        T ret = identity;
        REP(b, buc.size()) {
            ll lt = std::max(l, b * bsz), rt = std::min(r, (b + 1) * bsz);
            if (lt < rt) {
                if (rt - lt == bsz)ret = operation(ret, buc[b]);
                else for (ll i = lt; i < rt; ++i)ret = operation(ret, dat[i]);
            }
        }
        return ret;
    }
    static bucket<T>sum(ll dsz, ll bsz)
    {
        return bucket<T>(dsz, bsz, plus<T>(), static_cast<T>(0));
    }
    static bucket<T>product(ll dsz, ll bsz)
    {
        return bucket<T>(dsz, bsz, multiplies<T>(), static_cast<T>(1));
    }
    static bucket<T>max(ll dsz, ll bsz, T id = numeric_limits<T>::min())
    {
        return bucket<T>(dsz, bsz, static_cast<const T & (*)(const T &, const T &)>(std::max), id);
    }
    static bucket<T>min(ll dsz, ll bsz, T id = numeric_limits<T>::max())
    {
        return bucket<T>(dsz, bsz, static_cast<const T & (*)(const T &, const T &)>(std::min), id);
    }
};
