struct QuerySqrtDecomposition {
  vector< int > use, idx, rev;

  QuerySqrtDecomposition(int N) : use(N + 1), rev(N + 1, -1) {}

  void add(int l, int r) { // [l, r)
    use[l] = true;
    use[r] = true;
  }

  void add(int k) {
    add(k, k + 1);
  }

  void build() {
    for(int i = 0; i < use.size(); i++) {
      if(use[i]) idx.emplace_back(i);
    }
    for(int i = 0; i + 1 < idx.size(); i++) {
      for(int j = idx[i]; j < idx[i + 1]; j++) {
        rev[j] = i;
      }
    }
    rev[idx.back()] = (int) idx.size() - 1;
  }

  inline int size() const { return (int) idx.size() - 1; }

  inline int l(int k) const { return idx[k]; }

  inline int r(int k) const { return idx[k + 1]; }

  inline int operator[](int k) const { return rev[k]; }
};


