template <typename T>
class RMQ{
private:
  int size;
  vector<T> vec;


  int aux(int x, int y, int i, int l, int r){
    if(r<=x || y<=l) return inf;
    else if(x<=l && r<=y) return vec[i];
    else return min(aux(x,y,i*2+1,l,(l+r)/2), aux(x,y,i*2+2,(l+r)/2,r));
  };

public:
  RMQ(int n): size((1<<((int)ceil(log(n)/log(2))+1))-1), vec(size, inf){}
  void update(int i, int x){
    int j = i+(size+1)/2-1;
    vec[j] = x;
    --j;
    while(j>=0){
      vec[j/2] = min(vec[(j/2)*2+1], vec[(j/2)*2+2]);
      if(j==0) break;
      (j /= 2) -= 1;
    }    
  }

  int find(int x, int y){
    return aux(x,y,0,0,(size+1)/2);
  }
};

