template<typename T>
struct SegmentTree {
private:
    int n; //最下層のノード数。v.size以上の最小の2ベキ。
    vector<T> node;

public:
    SegmentTree(vector<T> v) { //O(n)
        n = 1LL << ((int)log2(v.size())+1);
        node.resize(n-1);
        move(v.begin(), v.end(), back_inserter(node));
        node.resize(2*n-1, INF);
        for(int i=n-2; i>=0; --i) node[i] = min(node[2*i+1], node[2*i+2]);
    }
    void update(int x, int val) { //O(logn)
        x += n - 1; //最下段ノード
        node[x] = val;
        while(x > 0) {
            x = (x - 1) / 2;
            node[x] = min(node[2*x+1], node[2*x+2]);
        }
    }
    T getmin(int a, int b, int k=0, int l=0, int r=-1) { //O(logn)
        if(r < 0) r = n;
        if(r <= a || b <= l) return INF;
        if(a <= l && r <= b) return node[k];

        return min(getmin(a, b, 2*k+1, l, (l+r)/2), getmin(a, b, 2*k+2, (l+r)/2, r));
    }
};

