#define RED 0
#define BLACK 1
#define INF INT_MAX

using namespace std;

struct RBTree{

  struct node_t{
    int val,size,rank,color;
    node_t *lp,*rp;

    node_t(int v):val(v){
      size = 1;
      rank = 0;
      color = BLACK;
      lp = rp = NULL;
    }

    node_t(node_t *l,node_t *r,int c){
      val = min(r->val,l->val);
      size = l->size + r->size;
      rank = r->rank + r->color;
      color = c;
      lp=l, rp=r;
    }

    bool isBlack(){return color;}
    bool isRed(){return !color;}
  };


  int size(node_t *x){return !x?0:x->size;}

  node_t *merge_r(node_t *l,node_t *r){

    if(l->rank < r->rank){
      node_t *tmp = merge(l, r->lp);
      if(r->isBlack() && tmp->isRed() && tmp->lp->isRed()){
	if(r->rp->isBlack()){
	  return new node_t(tmp->lp, new node_t(tmp->rp,r->rp,RED),BLACK);
	}
	else {
	  return new node_t(new node_t(tmp->lp,tmp->rp,BLACK),
			    new node_t(r->rp->lp,r->rp->rp,BLACK),RED); 	
	}
      }
      else {
	return new node_t(tmp,r->rp,r->color);
      }
    }
    else if(l->rank > r->rank){
      node_t *tmp = merge(l->rp, r);
      if(l->isBlack() && tmp->isRed() && tmp->rp->isRed()){
	if(l->lp->isBlack()){
	  return new node_t(new node_t(l->lp,tmp->lp,RED),tmp->rp,BLACK);
	}
	else {
	  return new node_t(new node_t(l->lp->lp,l->lp->rp,BLACK),
			    new node_t(tmp->lp,tmp->rp,BLACK),RED);
	}
      }
      else {
	return new node_t(l->lp,tmp,l->color);
      }
    }
    else {
      return new node_t(l,r,RED);
    }
  }

  node_t *merge(node_t *l, node_t *r){
    if(!l || !r)return l?l:r;
    node_t *res = merge_r(l,r);
    res->color = BLACK;
    return res;
  }

  typedef pair<node_t *,node_t *>P;

  P split(node_t *t,int k){
    if(k == 0)return P(0,t);
    if(size(t) == k)return P(t,0);

    if(k<=size(t->lp)){
      P tmp=split(t->lp,k);
      return P(tmp.first,merge(tmp.second, t->rp));
    } else {
      P tmp=split(t->rp,k-size(t->lp));
      return P(merge(t->lp,tmp.first),tmp.second);
    }
  }

  node_t *root;
  RBTree(){
    //root = new node_t(INF);
  }

  node_t *insert(node_t *t,int k,int val){
    pair<node_t *,node_t *>s=split(t,k);
    t=merge(s.first, new node_t(val));
    t=merge(t,s.second);
    return t;
  }

  node_t *erase(node_t *t,int k){
    pair<node_t *,node_t *>s1,s2;
    s2=split(t,k+1);
    s1=split(s2.first,k);
    delete s1.second;
    return (t=merge(s1.first,s2.second));
  }

  void insert(int k,int val){ root=insert(root,k,val); }
  void erase(int k){ root=erase(root,k); }

  void update(int id,int val){
    erase(id);
    insert(id,val);
  }

  int query(node_t *x, int left, int right){
    if(right <= 0 || x->size <= left)return INF;
    if(left <= 0 && x->size <= right)return x->val;
    int lsize = x->lp->size;
    int lv = query(x->lp,left,right);
    int rv = query(x->rp,left-lsize,right-lsize);
    return min(lv,rv);
  }
  /*
  int query(int l,int r){
    pair<node_t *,node_t *>s1,s2;
    s2=split(root,r);
    s1=split(s2.first,l);
    int res=s1.second->val;
    root = merge(s1.first,merge(s1.second,s2.second));
    return res;
  }
  */
};

int main(void){

  int n,q,com,x,y;
  RBTree t;

  cin >> n >> q;

  for(int i=0;i<=n;i++)t.insert(i,INF);

  while(q--){
    cin >> com >> x >> y;
    if(com==0)t.update(x,y);
    else cout << t.query(t.root,x,y+1) << endl;
  }

  return 0;
}

