using namespace std;
template <typename T> class SegmentTree {
  using F = std::function<T(T, T)>;

private:
  F operation; // 葉ノード更新時処理、区間に対する処理
  T e;         // 単位元
  vector<T> data;
  size_t n;

  void init(int n_) {
    n = 1;
    while (n < n_)
      n *= 2;
    data.resize(n * 2, e);
  }

public:
  SegmentTree(size_t N, T e, F operation) : e(e), operation(operation) {
    init(N);
  }

  template <typename Ite>
  SegmentTree(size_t N, T e, F operation, Ite start, Ite end)
      : e(e), operation(operation) {
    init(N);
    build(start, end);
  }
  template <typename Ite> void build(Ite start, Ite end) {
    for (auto i = start; i < end; i++) {
      int idx = i - start + n;
      data[idx] = *i;
    }
    for (int i = n - 1; i > 0; i--) {
      data[i] = operation(data[2 * i], data[2 * i + 1]);
    }
  }

  void set_val(int idx, T x) {
    // idxの値をxに更新
    data[idx += n] = x;
    while (idx /= 2)
      data[idx] = operation(data[2 * idx], data[2 * idx + 1]);
  }

  T query(size_t a, size_t b) {
    // [a,b)の処理
    T vl = e, vr = e;
    for (int l = a + n, r = b + n; l < r; l /= 2, r /= 2) {
      if (l % 2)
        vl = operation(vl, data[l++]);
      if (r % 2)
        vr = operation(data[--r], vr);
    }
    return operation(vl, vr);
  }

  const T &operator[](size_t idx) { return data[idx + n]; }
};

