#define FOR(i, m, n) for (int i = (m); i < (n); ++i)
#define REP(i, n) FOR(i, 0, n)

typedef int64_t ll;

ll INF = ll(1e16);

int get_n(int n) {
    int ret = 1; while(ret < n) ret <<= 1;

    return ret;
}

struct SegTree {
    int N;
    vector<ll> dat;

    explicit SegTree(int n): N(get_n(n)), dat(2*N - 1, INF) {}
    explicit SegTree(const vector<ll> & v) {
        N = get_n(v.size());
        dat.resize(2*N - 1, INF);

        REP(i, v.size()) dat[N + i - 1] = v[i];
        for (int i=N-2; i > -1; --i) dat[i] = _op(dat[2*i + 1], dat[2*i + 2]);
    }

    ll _op(ll a, ll b) {
        return min(a, b);
    }

    ll _up(ll& a, ll b) {
        a = b;
    }

    void update(int i, ll v) {
        i += N - 1;
        _up(dat[i], v);

        while(i > 0) {
            i = (i - 1) / 2;
            dat[i] = _op(dat[2*i + 1], dat[2*i + 2]);
        }
    }

    // query for [a, b), k: current node id, [l, r): current range.
    ll query(int a, int b, int k=0, int l=0, int r=-1) {
        if (r < 0) r = N;

        if (b <= l || r <= a) return INF;
        if (a <= l && r <= b) return dat[k];

        int mid = (l + r) / 2;
        ll c1 = query(a, b, 2*k + 1, l, mid);
        ll c2 = query(a, b, 2*k + 2, mid, r);

        return _op(c1, c2);
    }
};

struct LazySegTree {
    int N;
    vector<ll> dat;
    vector<ll> lazy;

    explicit LazySegTree(int n): N(get_n(n)), dat(2*N - 1, INF), lazy(2*N - 1, 0) {}
    explicit LazySegTree(const vector<ll>& v) {
        N = get_n(v.size());
        dat.resize(2*N - 1);
        lazy.resize(2*N - 1, 0);

        REP(i, N) dat[N + i - 1] = v[i];
        for (int i = N-2; i > -1; --i) dat[i] = _op(dat[2*i + 1], dat[2*i + 2]);
    }

    ll _op(ll a, ll b) {
        return a + b;
    }

    void eval(int k, int l, int r) {
        if (lazy[k] == 0) return;

        dat[k] += lazy[k];

        if(r - l > 1) {
            lazy[2*k+1] += k / 2;
            lazy[2*k+2] += k / 2;
        }

        lazy[k] = 0;
    }

    void update(int a, int b, int v, int k=0, int l=0, int r=-1) {
        if(r < 0) r = N;

        if (b <= l || r <= a) return;

        eval(k, l, r);

        if (a <= l && r <= b) {
            lazy[k] += (r - l) * v ;
            return;
        }

        int mid = (l + r) / 2;
        update(a, b, v, 2 * k + 1, l, mid);
        update(a, b, v, 2 * k + 2, mid, r);
        dat[k] = _op(dat[2*k+1], dat[2*k+2]);
    }

    ll query(int a, int b, int k=0, int l=0, int r=-1) {
        if(r < 0) r = N;

        if (b <= l || r <= a) return 0;

        eval(k, l, r);

        if(a <= l && r <= b) return dat[k];

        int mid = (l + r) / 2;
        ll c1 = query(a, b, k, l, mid);
        ll c2 = query(a, b, k, mid, r);
        return _op(c1, c2);
    }
};


