#include <bits/stdc++.h>
using namespace std;

const int INF = (1LL<<31)-1;

class RMQ{
private:
    int N;
    vector<int> data;

    int find(int a, int b, int k, int l, int r){
        if(r <= a || b <= l)
            return INF;
        if(a <= l && r <= b)
            return data[k];
        int x1 = find(a, b, 2*k+1, l, (l+r)/2);
        int x2 = find(a, b, 2*k+2, (l+r)/2, r);
        return min(x1, x2);
    }

public:
    RMQ(int N_){
        N = 1;
        while(N < N_)
            N <<= 1;
        data.assign(2*N-1, INF);
    }

    void update(int x, int a){
        x += N-1;
        data[x] = a;
        while(x){
            x = (x-1)/2;
            data[x] = min(data[2*x+1], data[2*x+2]);
        }
    }
    int find(int a, int b){
        return find(a, b, 0, 0, N);
    }
};

int main(){
    int N, Q;
    cin >> N >> Q;

    RMQ rmq(N);

    for(int i=0; i<Q; i++){
        int com, x, y;
        cin >> com >> x >> y;
        if(com == 0){
            rmq.update(x, y);
        }
        if(com == 1){
            cout << rmq.find(x, y+1) << endl;
        }
    }

    return 0;
}

