template<typename T>
class SegmentTree {
private:
    std::vector<T> data, lazy;
    std::vector<bool> lazyFlag;
    int size;
    const std::function<T(T, T)> op, change;
    const T initVal;
    void push(int l, int r, int k) {
        if (this->lazyFlag[k]) {
            this->data[k] = change(this->data[k], this->lazy[k]);
            if (k * 2 + 2 < this->size * 2 - 1) {
                this->lazyFlag[k * 2 + 1]
                = this->lazyFlag[k * 2 + 2]
                = true;
                this->lazy[k * 2 + 1]
                = this->lazy[k * 2 + 2]
                = this->lazy[k];
            }
            this->lazyFlag[k] = false;
        }
    }
    void update(int l, int r, int L, int R, int k, T val) {
        this->push(l, r, k);
        if (L <= l && r <= R) {
            this->lazy[k] = val;
            this->lazyFlag[k] = true;
            this->push(l, r, k);
        } else if (R <= l || r <= L) {
            return;
        } else if (r - l > 1) {
            const int mid = (l + r) / 2;
            this->update(l, mid, L, R, k * 2 + 1, val);
            this->update(mid, r, L, R, k * 2 + 2, val);
            data[k] = op(data[k * 2 + 1], data[k * 2 + 2]);
        }
    }
    T query(int l, int r, int L, int R, int k) {
        this->push(l, r, k);
        if (L <= l && r <= R) {
            return data[k];
        } else if (R <= l || r <= L) {
            return this->initVal;
        } else {
            const int mid = (l + r) / 2;
            const T left = this->query(l, mid, L, R, k * 2 + 1);
            const T right = this->query(mid, r, L, R, k * 2 + 2);
            return op(left, right);
        }
    }
public:
    SegmentTree(const int size_, T initVal_, std::function<T(T, T)> op_, std::function<T(T, T)> change_)
        : op(op_), change(change_), initVal(initVal_) {
        this->size = 1;
        while (this->size < size_) this->size <<= 1;
        data.resize(this->size * 2 - 1, this->initVal);
        lazy.resize(this->size * 2 - 1, this->initVal);
        lazyFlag.resize(this->size * 2 - 1, false);
    }
    void update(int l, int r, T val) {
        this->update(0, this->size, l, r, 0, val);
    }
    T query(int l, int r) {
        return this->query(0, this->size, l, r, 0);
    }
    void output() {for_each(data.begin(), data.end(), [](int e){cout << e << " ";});cout<<endl;}
};

int main() {
    int n, q;
    cin >> n >> q;
    SegmentTree<int> seg(n, INT_MAX, [](int l, int r) {
        return min(l, r);
    }, [](int l, int r) {
        return r;
    });
    while (q--) {
        //seg.output();
        int c, x, y;
        cin >> c >> x >> y;
        if (c) {
            cout << seg.query(x, y + 1) << endl;
        } else {
            seg.update(x, x + 1, y);
        }
    }
}

