template<typename Type>
struct SqrtDecomp {
    int SIZE;
    // node の前半には op2 を適用した値が入っているはずで、
    // 後半には op1 を適用した値が入っているはず

    // lazy は一様更新 → op1 を適用した値が入っているはず
    vector<Type> node, lazy, need_upd;
    Type (*op1) (Type x, Type y, int sz);
    Type (*op2) (Type x, Type y);
    Type I;

    SqrtDecomp( vector<Type> vec,
                Type (*g_op1) (Type x, Type y, int sz),
                Type (*g_op2) (Type x, Type y),
                Type X) {
        int N = vec.size();
        SIZE = 1; while(SIZE * SIZE < N) SIZE++;
        I = X, op1 = g_op1, op2 = g_op2;

        node.resize(SIZE*SIZE + SIZE, I);
        lazy.resize(SIZE, I);
        need_upd.resize(SIZE, 0);

        for(int i=0; i<SIZE; i++) {
            Type rep_val = I;
            for(int j=0; j<SIZE && i*SIZE+j<N; j++) {
                int idx = SIZE + (i*SIZE + j);
                node[idx] = vec[j];
                rep_val = op2(rep_val, node[idx]);
            }
            node[i] = rep_val;
        }
    }

    void lazy_eval(int k) {
        int l = SIZE*k, r = SIZE*(k+1);
        // printf("lazy_eval: %d, lazy[k] = %d, l =  %d, r = %d\n", k, lazy[k], l, r);
        if(need_upd[k]) {
            Type seg_val = I;

            // 該当する下のノードをまず更新
            for(int i=l; i<r; i++) {
                int idx = SIZE + i;
                node[idx] = op1(node[idx], lazy[k], 1);
                seg_val = op2(seg_val, node[idx]);
            }

            // 上のノードを更新
            node[k] = seg_val;
        }
        lazy[k] = I;
        need_upd[k] = false;
    }

    void update(int l, int r, Type val) {
        int lidx = l / SIZE, ridx = r / SIZE;
        // 左端の更新
        for(int k=l; k<min(r, SIZE*(lidx+1)); k++) {
            lazy_eval(lidx);
            int idx = SIZE + k;
            node[idx] = op1(node[idx], val, 1);
            node[lidx] = op2(node[lidx], val);
        }

        if(lidx != ridx) {
            // 真ん中 (lazy を更新)
            for(int k=lidx+1; k<ridx; k++) {
                lazy[k] = op1(lazy[k], val, 1);
                need_upd[k] = true;
            }

            // 右端の更新
            for(int k=SIZE*ridx; k<r; k++) {
                lazy_eval(ridx);
                int idx = SIZE + k;
                node[idx] = op1(node[idx], val, 1);
                node[ridx] = op2(node[ridx], val);
            }
        }
    }

    Type query(int l, int r) {
        int lidx = l / SIZE, ridx = r / SIZE;
        // printf("lidx = %d, ridx = %d\n", lidx, ridx);
        Type ret = I;

        // 左端の取得
        for(int k=l; k<min(r, SIZE*(lidx+1)); k++) {
            lazy_eval(lidx);
            int idx = SIZE + k;
            ret = op2(ret, node[idx]);
        }

        if(lidx != ridx) {
            for(int k=lidx+1; k<ridx; k++) {
                // 全体の値と lazy の値を考慮して値を計算
                Type val = (need_upd[k] ? op1(node[k], lazy[k], SIZE) : node[k]);
                ret = op2(ret, val);
            }

            for(int k=SIZE*ridx; k<r; k++) {
                lazy_eval(ridx);
                int idx = SIZE + k;
                ret = op2(ret, node[idx]);
            }
        }

        return ret;
    }

    void print_debug() {
        printf("<< node >>\n");
        printf("upper bucket:\n");
        for(int i=0; i<SIZE; i++) {
            int l = SIZE*i, r = SIZE*(i+1);
            printf("[%6d, %6d) -> %d\n", l, r, node[i]);
        }
        printf("lower bucket:\n");
        for(int i=0; i<SIZE*SIZE; i++) {
            int idx = SIZE + i;
            printf("[%6d, %6d) -> %d\n", i, i+1, node[idx]);
        }

        printf("<< lazy >>\n");
        printf("upper bucket:\n");
        for(int i=0; i<SIZE; i++) {
            int l = SIZE*i, r = SIZE*(i+1);
            printf("[%6d, %6d) -> %d\n", l, r, lazy[i]);
        }
        printf("\n");
    }
};


