int n;
int q;
ll a[100000];
int sqrtn = 512;
int K;
ll b[100000*2];

void update(int idx, ll x) {
  a[idx] = x;
  int bidx = idx/sqrtn;
  b[bidx] = ((ll)1<<31) - 1;
  rep(i, bidx*sqrtn, (bidx+1)*sqrtn) {
    chmin(b[bidx], a[i]);
  }
}

ll find(int x, int y) {
  ll result = ((ll)1<<31) - 1;
  rep(k, K) {
    int l = k*sqrtn;
    int r = (k+1)*sqrtn;
    if (r <= x || y <= l) continue;
    if (x <= l && r <= y) {
      chmin(result, b[k]);
    } else {
      rep(i, max(x, l), min(y, r)) {
        chmin(result, a[i]);
      }
    }
  }
  return result;
}

int main() {
  ios::sync_with_stdio(false);
  n = in();
  q = in();
  K = (n+sqrtn-1)/sqrtn;
  rep(i, n) a[i] = ((ll)1<<31) - 1;
  rep(i, n*2) b[i] = ((ll)1<<31) - 1;
  rep(i, q) {
    int c = in();
