typedef long long ll;

const ll B=1000;

ll a[max_n],m[max_n/B];

void update(ll i,ll x){
  a[i]=x;
  for(int j=i/B;j<i/B+B;j++)
    m[i/B]=min(m[i/B],a[j]);
}

ll find(ll s,ll t){
  ll res=INT_MAX;

  for(int i=s/B+1;i<t/B;i++){
    res=min(res,m[i]);
  }

  for(int i=s;i<min(s-s%B+B,t+1);i++)res=min(res,a[i]);
  for(int i=max(s,t-t%B);i<=t;i++)res=min(res,a[i]);

  return res;
}

int main(void){
  int n,q;

