template <class Value> class SegmentTree {
public:
  using value_type = Value;
  using operator_type = std::function<Value(Value, Value)>;

private:
  int n;
  std::vector<value_type> data;
  std::vector<int> lidx;
  std::vector<int> ridx;
  const operator_type op;
  const value_type id;

public:
  SegmentTree(const operator_type op, const value_type id,
              const std::vector<value_type> &a)
      : op(op), id(id) {
    n = 1;
    while (n < a.size())
      n *= 2;
    data.assign(2 * n - 1, id);
    lidx.assign(2 * n - 1, -1);
    ridx.assign(2 * n - 1, -1);
    for (int i = 0; i < n; ++i) {
      if (i < a.size())
        data[i + n - 1] = a[i];
      lidx[i + n - 1] = i;
      ridx[i + n - 1] = i + 1;
    }
    build();
  }

  void build() {
    for (int i = n - 2; i >= 0; --i) {
      data[i] = op(data[2 * i + 1], data[2 * i + 2]);
      lidx[i] = lidx[2 * i + 1];
      ridx[i] = ridx[2 * i + 2];
    }
  }

  void set(int i, const value_type &x) {
    i += n - 1;
    data[i] = x;
    while (i > 0) {
      i = (i - 1) / 2;
      data[i] = op(data[2 * i + 1], data[2 * i + 2]);
    }
  }

  value_type get(int l, int r) { return _get(l, r, 0); }

private:
  value_type _get(int l, int r, int k) {
    if (ridx[k] <= l || r <= lidx[k])
      return id;
    if (l <= lidx[k] && ridx[k] <= r)
      return data[k];
    value_type res1 = _get(l, r, 2 * k + 1);
    value_type res2 = _get(l, r, 2 * k + 2);
    return op(res1, res2);
  }
};

int main() {
  int n, q;
  std::cin >> n >> q;
  long long inf = (1LL << 31) - 1;
  std::vector<long long> a(n, inf);

  SegmentTree<long long> seg(
      [](long long a, long long b) { return std::min(a, b); }, inf, a);
  for (int i = 0; i < q; ++i) {
    int c, x, y;
    std::cin >> c >> x >> y;
    if (c == 0)
      seg.set(x, y);
    else
      std::cout << seg.get(x, y + 1) << std::endl;
  }
}

