template< typename Monoid >
struct SegmentTree {
    using F = function< Monoid(Monoid, Monoid) >;
    int size;
    vector< Monoid > data;

    const F f;
    const Monoid M1;

    SegmentTree(int n, const F f, const Monoid &M1) : f(f), M1(M1) {
        size = 1;
        while(size < n) size *= 2;
        data.assign(2*size-1, M1);
    }

    SegmentTree(vector<Monoid> vec, const F f, const Monoid &M1) : f(f), M1(M1) {
        size = 1;
        while(size < sz(vec)) size *= 2;
        data.assign(2*size-1, M1);

        rep(i, size) data[i+size-1] = vec[i];
        for(int i=sz(vec)-2; i>=0; i--) data[i] = f(data[2*i+1], data[2*i+2]);
    }

    void update(int x, const Monoid &val) {
        x += size-1;
        data[x] = val;
        while(x) {
            x = (x-1) / 2;
            data[x] = f(data[2*x+1], data[2*x+2]);
        }
    }

    Monoid query(int a, int b, int k=0, int l=0, int r=-1) {
        if (r<0) r = size;
        if (r<=a || l>=b) return M1;
        if (a<=l && b>=r) return data[k];
        Monoid val_l = query(a, b, 2*k+1, l, (l+r)/2);
        Monoid val_r = query(a, b, 2*k+2, (l+r)/2, r);
        return f(val_l, val_r);
    }
};

