#define INF      2147483647
typedef unsigned int uint;

uint n_array;
uint queries;
vector<uint> D;

void init(uint n_req){
  n_array = 1;
  while( n_array < n_req ){
    n_array *= 2;
  }
  D.resize(2*n_array-1);
  for( uint i = 0 ; i <= 2*n_array-1 ; i++ ){
    D[i] = INF;
  }
}

void update(uint k, uint a){
  k += n_array - 1;
  D[k] = a;
  while( k > 0 ){
    k = (k-1) / 2;
    D[k] = min( D[k*2+1] ,D[k*2+2] );
  }
}

uint query(uint a, uint b, uint k, uint l, uint r) {
  if( r <= a || b <= l ){ // case 1
    return INF;
  }else if( a<= l && r <= b ){ // case 2
    return D[k];
  }
  // case 3
  uint vl = query( a, b, k*2+1, l, (l+r)/2 );
  uint vr = query( a, b, k*2+2, (l+r)/2, r );
  return min( vl, vr );
}

uint findMin(uint a, uint b){
  return query(a, b+1, 0, 0, n_array);
}

void printD(){
  int i = 0;
  for (const auto& e : D) {
     printf("[%d]" ,i); i++;
     std::cout << e << std::endl;
  }
}

