template<class T>
class segtree{
    public:
    int n; vector<T> data;
    T id;
    function<T(T,T)> op;
    function<T(T,T)> upd;
    segtree(size_t _n, T _id, function<T(T,T)> _op, function<T(T,T)> _upd)
    : id(_id), op(_op), upd(_upd){
        n = 1;
        while(n < _n) n *= 2;
        data = vector<T>(2*n-1, id);
    }
    T _query(int a, int b, int k, int l, int r){
        if(r <= a || b <= l) return id;
        if(a <= l && r <= b) return data[k];
        else{
            T ll = _query(a, b, k*2+1, l, (l+r)/2);
            T rr = _query(a, b, k*2+2, (l+r)/2, r);
            return op(ll, rr);
        }
    }
    T query(int a, int b){
        return _query(a, b, 0, 0, n);
    }
    void update(int i, T x){
        i += n-1;
        data[i] = upd(data[i], x);
        while(i > 0){
            i = (i-1)/2;
            data[i] = op(data[i*2+1], data[i*2+2]);
        }
    }
    T operator[](int i){
        return data[i+n-1];
    }
};

