struct segtree {
	int N = 1;
	vi val;
	segtree(int n) {
		while (N < n) N *= 2;
		val = vi(2*N);
		for (int i = 0; i < 2 * N;i++) {
			val[i] = INF;
		}
	}
	void replace(int k, int a) {
		k += N;
		val[k] = a;
		while (k > 0) {
			k =  k / 2;
			val[k] = min(val[k * 2],val[k * 2 + 1]);
		}
	}
	int minim(int a, int b) { return minim(a, b, 1, 0, N); }
	int minim(int a, int b, int k,int l, int r) {
		if (r <= a || b <= l) return INF;
		if (a <= l && r <= b) return val[k];
		int m = (l + r) / 2;
		return min(minim(a, b, k * 2, l, m), minim(a, b, k * 2 + 1, m, r));
	}
};

