int main(){
  int m,a,b,c;
  scanf("%d %d",&n,&m);
  init();
  for(int i=0;i<m;i++){
    scanf("%d %d %d",&a,&b,&c);
    if(a == 0) updata(b,c);
    else cout << find(P(b,c),0,0,n-1) << endl; 
  }
