void init(){
  int l=1;
  while(l < n){
    l<<=1;
  }
  n = l;
  for(int i=0;i<=n*2;i++){
    data[i] = INF;
  }
  return;
}

void updata(int i,int x){
  i += n-1;
  data[i] = x;
  while(i > 0){
    i = (i-1)/2;
    data[i] = min(data[i*2+1],data[i*2+2]);
  }
  return;
}

int find(P a,int node,int left,int right){
  if(right < a.first || a.second < left) return INF;
  if(a.first <= left && right <= a.second) return data[node];
  int c1 =find(a,node*2+1,left,(right+left)/2);
  int c2 = find(a,node*2+2,(left+right)/2+1,right);
  return min(c1,c2);
}

