struct RMQ
{
	int N;
	ll gt;
	ll a[N_SIZE];
	ll seg[N_SIZE * 2];
	void init(int n) {
		N = n;
		REP(i, 30) {
			if ((1 << i) >= N) {
				gt = (1 << i) - 1;
				break;
			}
		}
		REP(i, N) {
			a[i] = (1 << 31) - 1;
		}
		REP(i, N_SIZE * 2) {
			seg[i] = (1 << 31) - 1;
		}
		REP(i, N)seg[i + gt] = a[i];
	}
	void update(int k, int x) {
		k += gt;
		seg[k] = x;
		while (k) {
			k = (k - 1) / 2;//???????????????
			seg[k] = min(seg[k * 2 + 1], seg[k * 2 + 2]);
		}
	}
	ll query(int a, int b, int k, int l, int r) {//[a,b)????????????????°????,k=0,l=0,r=gt
		if (r <= a || b <= l) {
			return (1 << 31) - 1;
		}

		if (a <= l&&r <= b)return seg[k];
		else {
			return min(query(a, b, k * 2 + 1, l, (l + r) / 2),
				query(a, b, k * 2 + 2, (l + r) / 2, r));
		}
	}
	void print() {
		REP(i, 2 * (gt + 1))cout << "!" << i << " " << seg[i] << endl;
