using namespace std;
int *tree;
int N;

void createTree(int n_){
    int n = 1;
    //int size = pow(2, (log2(N)+1) ) - 1;
    //int h = log2(N) + 1;
    while (n < n_){
        n *= 2;
    }
    N = n;
    tree = new int[2*N-1-1];
    for (int i = 0; i < 2*N-1-1; ++i) {
        tree[i] = INT_MAX;
    }
};
void updateTree(int index, int x){

    index += N -1;
    tree[index] = x;
    while(index > 0){
        index = (index - 1) / 2;
        tree[index] = min(tree[index*2+1],tree[index*2+2]);
    }
};
int query(int a, int b, int k, int l, int r){
    if( r < a || b < l ){
        return INT_MAX;
    }
    if( a <= l && r <= b ){
        return tree[k];
    }
    int vl = query(a, b, k*2+1, l, (l+r)/2);
    int vr = query(a, b, k*2+2, (l+r)/2+1, r);
    return min(vl,vr);
};

int RMQ(int a, int b){
    return query(a, b+1, 0, 0, N);
};

int main() {
    int q; // size of data set and number of queries

    int action, op1, op2; // action 0 - update ;  1 - find

    int cnt = 0;
    cin >> N >> q;
    int ans[q];
    createTree(N);

    int testArr[N];

    for (int i = 0; i < q; ++i) {

        cin >> action >> op1 >> op2;
        if (action == 0){
            updateTree(op1, op2);
        } else if(action == 1){
            for (int j = 0; j < N; ++j) {
                testArr[j] = tree[j];
            }
            ans[cnt] = RMQ(op1, op2);
            cnt++;
        }

    }
    for (int i = 0; i < cnt; ++i) {
        cout << ans[i] << endl;
    }

    return 0;
}

