template <class T>
struct SegmentTree {
private:
    int n;
    using F = function<T(T,T)>;
    F func;
    vector<T> node;
    T initial;
public:
// vector, function,iniの順番に突っ込む。
    SegmentTree(vector<T> v,F f,T ini) {
        func = f;
        initial = ini;
        int sz = v.size();
        n = 1; while(n < sz) n *= 2;
        node.resize(2*n-1, initial);
        for(int i=0; i<sz; i++) node[i+n-1] = v[i];
        for(int i=n-2; i>=0; i--) node[i] = func(node[2*i+1], node[2*i+2]);
    }

    void update(int x, T val) {
        x += (n - 1);
        node[x] = val;
        while(x > 0) {
            x = (x - 1) / 2;
            node[x] = func(node[2*x+1], node[2*x+2]);
        }
    }

    int find(int a, int b, int k=0, int l=0, int r=-1) {
        if(r < 0) r = n;
        if(r <= a || b <= l) return initial;
        if(a <= l && r <= b) return node[k];

        int vl = find(a, b, 2*k+1, l, (l+r)/2);
        int vr = find(a, b, 2*k+2, (l+r)/2, r);
        return func(vl, vr);
    }
};

int main() {
    int n,q;
    cin >> n >> q;
    lli ini ;
    ini =  ((lli) 1<<31) -1; 
    vector<lli> v(n,ini);
    //ここのsegmentTree<int>はtemplateと関係している。
    //seg(vector,λ式、初期値の順に突っ込む)
    SegmentTree<lli> seg(v,[](lli a,lli b){return min(a,b);},ini);
    for(int i=0; i<q; i++) {
        lli c, x, y; cin >> c >> x >> y;
        if(c == 0) seg.update(x, y);
        else cout << seg.find(x, y+1) << endl;
    }    
    return 0;
}

