template <class T> struct carstain_tree{
    struct node{
        T val;
        int left;
        int right;
        int parent;
        void init(){
            right=left=parent=-1;
            return ;
        }
    };
    vector<node>map;
    int root;
    int size;
public:
    void init(){
        root=-1;
        size=0;
        map.clear();
        return ;
    }
    void push(T n){
        node temp;
        temp.init();
        temp.val=n;
        map.push_back(temp);
        if(size==0)root=0;
        else insert(size-1,size);
        size++;
        return ;
    }
    void in_print(){
        inorder(root);
        printf("\n");
        return ;
    }
    void pre_print(){
        preorder(root);
        printf("\n");
        return ;
    }
    void post_print(){
        postorder(root);
        printf("\n");
        return ;
    }
private:
    void insert(int now,int n){
        if(map[n].val>map[now].val){
            map[now].right=n;
            map[n].parent=now;
        }
        else if(now==root){
            root=n;
            map[n].left=now;
            map[now].parent=n;
        }
        else{
            insert(map[now].parent,n);
            if(map[map[now].parent].right!=now){
                map[now].parent=n;
                map[n].left=now;
            }
        }
        return ;
    }
    void inorder(int now){
        if(map[now].left!=-1){
            inorder(map[now].left);
            printf(" ");
        }
