        a[i] = rand()%2;
        if(a[i] == 0){
            b[i] = rand()%n;
            c[i] = rand()%10;
        } else {
            b[i] = rand()%n;
            c[i] = rand()%n;
            if(b[i] > c[i]) swap(b[i], c[i]);
        }
    }
    return make_tuple(n,q,a,b,c);
}

