static const int MAX_N = 100005;
static const int INF = (1LL << 31) - 1;

struct ST {
  int seg[MAX_N * 2], n;

  void init(int pn) {
    n = 1;
    while (n < pn) n *= 2;
    fill(seg, seg + MAX_N * 2, INF);
  }

  void update(int i, int x) {
    i = n + i - 1;
    seg[i] = x;

    while (i) {
      i = (i - 1) / 2;
      seg[i] = min(seg[2 * i + 1], seg[2 * i + 2]);
    }
  }

  int minq(int s, int t, int p, int l, int r) {
    if (t <= l || r <= s) return INF;
    if (s <= l && r <= t || r - l == 1) return seg[p];

    return min(minq(s, t, 2 * p + 1, l, r / 2), minq(s, t, 2 * p + 2, r / 2 + 1, r));
  }
};

