void stablo(int ind, int left, int right)
{
    if(left==right)
    {
        seg[ind]=niz[left];
        return;
    }
    int mid=(left+right)/2;
    stablo(ind*2,left,mid);
    stablo(ind*2+1,mid+1,right);
    seg[ind]=min(seg[ind*2],seg[ind*2+1]);
    return;
}
void update(int ind, int left, int right, int poz, int val)
{
    if(left==right)
    {
        seg[ind]=min(seg[ind],val);
        return;
    }
    int mid=(left+right)/2;
    if(poz<=mid)
    {
        update(ind*2,left,mid,poz,val);
        seg[ind]=min(seg[ind],seg[ind*2]);
    }
    else
    {
        update(ind*2+1,mid+1,right,poz,val);
        seg[ind]=min(seg[ind],seg[ind*2+1]);
    }
    return;
}
long long query(int ind, int left, int right, int l, int r)
{
    if(left>=l && right<=r)
    {
        return seg[ind];
    }
    if(right<l || left>r)
    {
        return INT_MAX;
    }
    int mid=(left+right)/2;
    return min(query(ind*2,left,mid,l,r),query(ind*2+1,mid+1,right,l,r));
}
