struct segtree{
	mono seg[1<<20];
	int sz;
	void init(int n){
		sz=1;
		while(sz<n)sz*=2;
		for(int i=0;i<sz*2;i++)seg[i].init();
	}
	void set(int a,mono x){
		a+=sz-1;
		seg[a]=x;
	}
	void build(int k,int l,int r){
		if(l==r)return;
		build(k*2+1,l,(l+r-1)/2);
		build(k*2+2,(l+r+1)/2,r);
		seg[k]=func(seg[k*2+1],seg[k*2+2]);
	}
	void up(int a,mono x){
		a+=sz-1;
		seg[a]=x;
		while(a>0){
			a=(a-1)/2;
			seg[a]=func(seg[a*2+1],seg[a*2+2]);
		}
	}
	mono query(int a,int b,int l,int r,int k){
		if(a<=l&&r<=b)return seg[k];
		mono res;
		res.init();
		if(r<a||b<l)return res;
		return func(query(a,b,l,(l+r-1)/2,k*2+1),query(a,b,(l+r+1)/2,r,k*2+2));
	}
};
