    const int block_size = sqrt(n);
    vector<int> block(n / block_size + 1, INF);
    while(q--) {
        int com, x, y;
        cin >> com >> x >> y;
        if(com == 0) { // update
            a[x] = y;
            int b = x / block_size;
            for(int i = b * block_size; i < (b + 1) * block_size; ++i) {
                block[b] = min(block[b], a[i]);
            }
        } else {
            int ans = INF;
            for(int b = 0; b < (int)block.size(); ++b) {
                if(x <= b * block_size && (b + 1) * block_size <= y) {
                    ans = min(ans, block[b]);
                } else if(x / block_size == b || y / block_size == b) {
                    for(int j = max(b * block_size, x); j < min((b + 1) * block_size, y + 1); ++j) {
                        ans = min(ans, a[j]);
                    }
                }
            }
            cout << ans << endl;
        }
    }
}

