template<typename T> struct SegmentTree {
    int size;
    vector<T> data;
    function<T(T,T)> op;

    SegmentTree( vector<T> v, function<T(T,T)> op ) :op(op) {
        int n = v.size();
        size = 1;
        while( size < n ) size <<= 1;
        data.resize( size*2, v[0] );
        rep( i, n ) data[size+i] = v[i];
        for( int i=size-1; i>0; i-- ) data[i] = op( data[2*i], data[2*i+1] );
    }

    void update( int k, T x ) {
        k += size;
        data[k] = x;
        while(k >>= 1) data[k] = op( data[2*k], data[2*k+1] );
    }

    T query( int a, int b ) {
        a += size; b += size;
        T L = data[a++], R = data[--b];
        for( ; a < b; a>>=1, b>>=1 ) {
            if(a & 1) L = op( L, data[a++] );
            if(b & 1) R = op( data[--b], R );
        }
        return op(L, R);
    }
};


