    }

    void update(int q, int v) {
        update(rootId, lRange, rRange, q, v);
    }

    void ensureChidren(int nodeId){
        if (heap[nodeId].lchild == NIL) {
            int id = newNode();
            heap[nodeId].lchild = id;
        }
        if (heap[nodeId].rchild == NIL) {
            int id = newNode();
            heap[nodeId].rchild = id;
        }
    }

    void update(int nodeId, int l, int r, int q, int v) {
        if (q < l || q > r) {
            return;
        }
        if (l == r) {
            heap[nodeId].minv = v;
            return;
        }
        int m = l + (r - l)/2;

        ensureChidren(nodeId);

        update(heap[nodeId].lchild, l, m, q, v);
        update(heap[nodeId].rchild, m + 1, r, q, v);

        pullUp(nodeId); 
    }

    int query(int ql , int qr) {
        return query(rootId, lRange, rRange, ql, qr);
    }

    int query(int nodeId, int l, int r, int ql , int qr) {
        if (nodeId == NIL || ql > r || qr < l) {
            return INF;
        }
        //printf("%d %d %d\n", nodeId, l, r);
        Node node = heap[nodeId];

        if (ql <= l && r <= qr) {
            return node.minv;
        }
        int m = l + (r - l) / 2;
        return min(query(node.lchild, l, m, ql, qr), 
                query(node.rchild, m + 1, r, ql, qr));
    }

    void pullUp(int nodeId) {
        Node node = heap[nodeId];
        heap[nodeId].minv = min(heap[heap[nodeId].lchild].minv, heap[heap[nodeId].rchild].minv);
    }

    int newNode() {
        heap.push_back(Node());
        return heap.size() - 1;    
    }   
};


int main() {
    int n, q;
    cin >> n >> q;

    SegmentTree sg = SegmentTree(0, n - 1);

    for (int i = 0; i < q; i++) {
        int cmd;
        cin >> cmd;
        if (cmd == 0) {
            int pos, v;
            cin >> pos >> v;
            sg.update(pos, v);
        }
        else {
            int ql, qr;
            cin >> ql >> qr;
            cout << sg.query(ql, qr) << endl;
        }
    }
    return 0;
}

