typedef long long ll;
struct SegmentTree{
  int n_, n = 1;
  int MAX = 2147483647;
  int v[202020];
  SegmentTree(int n_):n_(n_){
    while(n < n_) n *= 2; // 2の冪乗が扱いやすい
    FOR(i,0,2*n) v[i] = MAX;
  }
  // k番目の要素をaに変更
  void update(int k, int a){
    k += n - 1; // ノード番号にする
    v[k] = a;
    while(k > 0){
      k = (k - 1) / 2;
      v[k] = min(v[2 * k + 1], v[2 * k + 2]);
    }
  }
  // [a, b)の最小値,kはノード番号
  // query(a,b,0,0,n)を呼ぶ
  int query_(int a, int b, int k, int l, int r){
    if(b <= l || r <= a) return MAX;
    if(a <= l && r <= b) return v[k];
    int vl = query_(a, b, 2 * k + 1, l, (l + r) / 2);
    int vr = query_(a, b, 2 * k + 2, (l + r) / 2, r);
    return min(vl, vr);
