template<typename T>
class SegTree {
private:
  std::vector<T> dat_;
  size_t size_;
  T Update_(size_t i_node, size_t left, size_t right,
    size_t left_bound, size_t right_bound) noexcept;
public:
  SegTree() = delete;
  SegTree(size_t num){
    size_t n = 1;
    while(n < num) n <<= 1;
    size_ = n;
    dat_ = std::vector<T>(2 * size_, std::numeric_limits<T>::max());
  }

  size_t size(){return size_;}

  void Update(size_t i, T val) noexcept;

  T Find(size_t left, size_t right) noexcept {
    return Update_(1, left, right + 1, 0, size_);
  }

  void Dump() noexcept;

};

template<typename T>
T SegTree<T>::Update_(size_t i_node, size_t left, size_t right,
  size_t node_left_bound, size_t node_right_bound) noexcept {
  assert(left <= right);
  assert(node_left_bound <= node_right_bound);

  // no overlap(outisde)
  if(right <= node_left_bound || node_right_bound <= left)
    return std::numeric_limits<T>::max();

  // include whole interval
  if(left <= node_left_bound && node_right_bound <= right)
    return dat_[i_node];

  // partial overlap
  return std::min<T>(
    Update_(i_node * 2, left, right, node_left_bound,
      node_left_bound + (node_right_bound - node_left_bound) / 2),
    Update_(i_node * 2 + 1, left, right,
      node_left_bound + (node_right_bound - node_left_bound) / 2,
      node_right_bound));
}

template<typename T>
void SegTree<T>::Update(size_t i, T val) noexcept {
  T orig = dat_[i + size_];
  dat_[i + size_] = val;
  size_t index = (i + size_) / 2;
  while(index > 0){
    dat_[index] = std::min<T>(dat_[index * 2], dat_[index * 2 + 1]);
    index >>= 1;
  }
}

template<typename T>
void SegTree<T>::Dump() noexcept {
  std::cout << "SegTree dump:";
  for (int i = 1; i < 2 * size_; ++i)
  {
      if(i & (i - 1) == 0) {
        std::cout << std::endl;
      }
      std::cout << dat_[i] << " ";
  }
  std::cout << std::endl;
}

