template <typename T>
struct SegTree {
    int n;
    vector <T> data;
    T def;
    function<T(T, T)> operation;
    function<T(T,T)> updateop;

    T _query(int a, int b, int k, int l, int r){
        if(r <=a || b <= l) return def;
        if(a <= l && r <= b) return data[k];
        else return operation(_query(a, b, 2 * k + 1, l, (l + r) / 2),
        _query(a, b, 2 * k + 2, (l + r) / 2, r));
    }

    SegTree(vector <T> &v, T _def, function<T(T,T)> _operation, function<T(T,T)> _update)
    :def(_def), operation(_operation), updateop(_update) {
        n = 1;
        int sz = v.size();
        while(n < sz) n <<= 1;
        data.resize(2 * n - 1, def);
        rep(i, sz) update(i, v[i]);
    }
    SegTree(size_t _n, T _def, function<T(T,T)> _operation, function<T(T,T)> _update)
    :def(_def), operation(_operation), updateop(_update) {
        n = 1;
        while(n < _n) n <<= 1;
        data.resize(2 * n - 1, def);
    }
    void update(int i, T x){
        i += n-1;
        data[i] = updateop(data[i], x);
        while(i > 0) {
            i = (i-1)/2;
            data[i] = operation(data[i*2 + 1], data[i * 2 + 2]);
        }
    }

    T query(int a, int b){
        return _query(a, b, 0, 0, n);
    }

    T operator[](int i){
        return data[i + n - 1];
    }
};
