template<class T> struct SegTree {
	typedef size_t U;
	U n; T init;
	vector<T> d, s;
	SegTree(U _n, T init) : n(1), init(init) {
		while (n < _n) n <<= 1;
		d = vector<T>(2 * n - 1, init);
		s = vector<T>(2 * n - 1, 0);
	}
	void set(U i, T x) { add(i, x - get(i, i + 1)); }
	void add(U i, T x) { add(i, i + 1, x); }
	void add(U a, U b, T x) { add(a, b, x, 0, 0, n); }
	T add(U a, U b, T x, U k, U l, U r) {
		if (b <= l || r <= a) return d[k];
		if (a <= l && r <= b) {
			s[k] += x;
			return d[k] += x;
		}
		U m = (l + r) / 2;
		return d[k] = min(
			add(a, b, x, 2 * k + 1, l, m),
			add(a, b, x, 2 * k + 2, m, r)
		) + s[k];
	}
	T get(U a, U b) { return get(a, b, 0, 0, n); }
	T get(U a, U b, U k, U l, U r) {
		if (b <= l || r <= a) return init;
		if (a <= l && r <= b) return d[k];
		U m = (l + r) / 2;
		return min(
			get(a, b, 2 * k + 1, l, m),
			get(a, b, 2 * k + 2, m, r)
		) + s[k];
	}
};

