template<typename T>
class RMQ {
    int n;
    vector<T> data;
    const T INIT_VALUE;
    int get(int a, int b, int k, int l, int r){
        if(r <= a || b <= l)return INIT_VALUE;
        if(a <= l && r <= b)return data[k];
        T lv = get(a, b, (k << 1) + 1, l, (l + r) >> 1);
        T rv = get(a, b, (k << 1) + 2, (l + r) >> 1, r);
        return min(lv, rv);
    }
public:
    RMQ(int _n, int INIT_VALUE):INIT_VALUE(INIT_VALUE){
        for(n = 1; n < _n; n <<= 1);
        data.assign((n << 1) - 1, INIT_VALUE);
    }
    void update(int k, T v){
        k += n - 1;
        data[k] = v;
        while(0 < k){
            k = (k - 1) >> 1;
            data[k] = min(data[(k << 1) + 1], data[(k << 1) + 2]);
        }
    }
    T get(int a, int b){
        return get(a, b, 0, 0, n);
    }
};

