void updateTree(int index, int *st){
    if(index==0){
        if(index+2<n){
            st[index] = min(st[index+1],st[index+2]);
        }
        return;
    }
    if(index%2==0){
        st[(index-1)/2] = min(st[index-1],st[index]);
        updateTree((index-1)/2, st);
    }
    else{
        st[(index-1)/2] = min(st[index+1],st[index]);
        updateTree((index-1)/2, st);
    }
}

int updatePos(int pos, int value, int ss, int se, int index, int *st){
    if(ss==se){
        if(se==pos){
            st[index] = value;
            //printf("change %d to %d\n",index,value);
            return index;
        }
    }
    if(pos>=ss && pos<=se){
        if(st[index] > value){
            st[index]=value;
            //printf("change %d to %d\n",index,value);
        }
        int mid = (ss+se)/2;
        if(pos<=mid){
            return updatePos(pos, value, ss, mid, index*2+1,st);
        }
        else{
            return updatePos(pos, value, mid+1, se, index*2+2,st);
        }
    }
}

int getSmallest(int ss, int se, int qs, int qe, int *st, int index){
    if(qs<=ss && qe>=se){
        return st[index];
    }
    if(se<qs || qe<ss){
        return INT_MAX;
    }
    int mid = (ss+se)/2;
    return min(getSmallest(ss,mid,qs,qe,st,2*index+1),
               getSmallest(mid+1,se,qs,qe,st,2*index+2));
}

int constructSTUtil(int ss, int se, int *st, int index){
    if(ss==se){
        st[index] = arr[ss];
        return st[index];
    }
    int mid = (ss+se)/2;
    st[index] = min(constructSTUtil(ss, mid, st, 2*index+1),
                    constructSTUtil(mid+1, se, st, 2*index+2));
    return st[index];
}

int* constuctSegTree(){
    int x = (int)(ceil(log2(n)));
    // Maximum size of segment tree
    int max_size = 2*(int)pow(2, x) - 1;
    int *st = new int[max_size];
    constructSTUtil(0, n-1, st, 0);
    return st;
}

