struct SegmentTree {
private:
    ll n;
    vector<ll> node;

public:

    SegmentTree(vector<ll> v) {
        ll sz = v.size();
        n = 1;
        while(n < sz) {
            n *= 2;
        }
        node.resize(2*n - 1, INF);
        rep(i, sz) {
            node[i+n-1] = v[i];
        }
        for(ll i = n-2; i >= 0; i--) {
            node[i] = min(node[2*i + 1], node[2*i + 2]);
        }
    }

    // i番目の葉の値をxに変える
    void update(ll i, ll x) {
        i += n-1;  // i番目の葉のノード番号
        node[i] = x;
        while(i > 0) {
            i = (i - 1)/2;  // ノードiの親ノードの番号に変える
            node[i] = min(node[2*i + 1], node[2*i + 2]);  // 左右の子のminを計算する
        }
    }

    // 区間[a,b)の最小値を返す
    ll getmin(ll a, ll b, ll k = 0, ll l = 0, ll r = -1) {
        // 区間[a,b)に対するクエリについてノードk(区間[l, r)担当)が答える
        if(r < 0) {
            r = n;  // 最初に呼び出されたときの対象区間は[0,n)
        }
        if(b <= l || r <= a) {
            return INF;  // 区間が被らない場合はINFを返す
        }
        if(a <= l && r <= b) {
            return node[k];  // ノードkの担当範囲が区間[a,b)に完全に含まれる
        }
        // 一部だけ範囲が被る場合は左右の子に委託する
        ll c1 = getmin(a, b, 2*k + 1, l, (l + r)/2);
        ll c2 = getmin(a, b, 2*k + 2, (l + r)/2, r);
        return min(c1, c2);  // 左右の子の値のminをとる
    }

};

