const ll INF = (1LL << 31) - 1;
const int MAX_N = 1 << 17;

int n;
ll dat[2 * MAX_N - 1];

void init(int n_) {
    // n: num of elements in the bottom row
    // let n be the power of 2
    n = 1;
    while (n < n_) n *= 2;

    // set all values by INF
    REP(i, 2 * n - 1) dat[i] = INF;
}

// change the k-th(0-index) value to a
void update(int k, int a) {
    // set a in the leaf
    k += n - 1;
    dat[k] = a;

    // update upward
    while (k > 0) {
        k = (k - 1) / 2;
        dat[k] = min(dat[2 * k + 1], dat[2 * k + 2]);
    }
}

// get the minimum value in [a, b)
// k: num of the node corresponds to [l, r)
// call like this: 'query(a, b, 0, 0, n)'
int query(int a, int b, int k, int l, int r) {
    // if [a, b) & [l, r) = 0, then return INF
    if (r <= a || b <= l) return INF;

    // if [a, b) covers the whole [l, r),
    // then return the value of this node
    if (a <= l && r <= b) return dat[k];

    // otherwise, return the min of two children
    int vl = query(a, b, k * 2 + 1, l, (l + r) / 2);
    int vr = query(a, b, k * 2 + 2, (l + r) / 2, r);

    return min(vl, vr);
}

