void update(const int &index, std::vector<int> &vec){
	if (index % 2 == 0){
		if (index != 0){
			if (vec.at(index - 1) < vec.at(index)){
				if (vec.at((index - 1) / 2) != vec.at(index - 1)){
					vec.at((index - 1) / 2) = vec.at(index - 1);
					update((index - 1) / 2, vec);
				}
			}else{
				if (vec.at((index - 1) / 2) != vec.at(index)){
					vec.at((index - 1) / 2) = vec.at(index);
					update((index - 1) / 2, vec);
				}
			}
		}else{
			vec.at(0) = (vec.at(1) > vec.at(2) ? vec.at(2):vec.at(1));
		}
	}else{
		if (vec.at(index + 1) < vec.at(index)){
			if (vec.at(index / 2) != vec.at(index + 1)){
				vec.at(index / 2) = vec.at(index + 1);
				update(index / 2, vec);
			}
		}else{
			if (vec.at(index / 2) != vec.at(index)){
				vec.at(index / 2) = vec.at(index);
				update(index / 2, vec);
			}
		}
	}
}
int find(int start, int end, const std::vector<int> &vec){
	if (start == end){
		return vec.at(start);
	}else if(start > end){
		return INT_MAX;
	}else{
		int min = find(start >> 1, (end >> 1) - 1, vec);
		if (start % 2 == 0){
			if (min > vec.at(start)){
				min = vec.at(start);
			}
		}
		if (end % 2 == 1){
			if (min > vec.at(end)){
				min = vec.at(end);
			}
		}
		return min;
	}
}
