  void update(ll i, ll x) {
    i += n - 1; // 葉のノード
    dat[i] = x;
    while (i > 0) { // 更新
      i = (i - 1) / 2;
      dat[i] = min(dat[2 * i + 1], dat[2 * i + 2]);
    }
  }

  // [a, b)の最小値
  // k:ノードの番号 [l, r)がkに対応づいている
  // query(a, b, 0, 0, n)と呼ぶ
  ll query(int a, int b, int k = 0, int l = 0, int r = -1) {
    if (r == -1) r = n;
    if (r <= a || b <= l) return INF;
