		//対象に一部が含まれる
		T aL=findquary(left, right, index * 2, atStart, atStart + (atStop - atStart) / 2);
		T aR= findquary(left, right, index * 2 +1,  atStart +(atStop - atStart) / 2, atStop);
		return func(aL,aR);
	}
	T upquary(int index){ //q1
		return func(seg[index],seg[index+1]);
	}
	public:
	int size; //size of segmenttree
	T init;//unit
