template<typename T,typename E>
class SegmentTree{
private:
  typedef function<T(T,T)> F;//保持したいデータの関数
  typedef function<T(T,E)> G;//1点更新
  int n;
  F f;
  G g;
  T d1;//初期値
  E d0;
  vector<T> data;//データが格納されている配列
public:
  SegmentTree(){};
  SegmentTree(int n_,F f,G g,T d1,
	      vector<T> v=vector<T>()):
    f(f),g(g),d1(d1){
    init(n_);
    if(n_==(int)v.size()) build(n_,v);
  }

  void init(int n_){
    n=1;
    while(n<n_) n*=2;
    data.clear();
    data.resize(2*n-1,d1);
  }

  void build(int n_,vector<T> v){
    for(int i=0;i<n_;i++) data[i+n-1]=v[i];
    for(int i=n-2;i>=0;i--) data[i]=f(data[i*2+1],data[i*2+2]);
  }

  void update(int k,E a){
    k+=n-1;
    data[k]=g(data[k],a);
    while(k>0){
      k=(k-1)/2;
      data[k]=f(data[k*2+1],data[k*2+2]);
    }
  }
  inline T query(int a,int b){
    T vl=d1,vr=d1;
    for(int l=a+n,r=b+n;l<r;l>>=1,r>>=1){
      if(l&1) {
	vl=f(vl,data[l-1]);
	l++;
      }
      if(r&1){
	vr=f(data[r-2],vr);
	r--;
      }
    }
    return f(vl,vr);
  }

};




