#define M 17
struct segtree{
	int a[1<<(M+1)];
	const int INIT=INT_MAX;
	void init(){
		fill(a, a+(1<<(M+1)), INIT);
	}

	void set(int p, int x){
		a[(1<<M)+p]=x;
		for(int i=M-1; i>=0; i--){
			int k=1<<(M-i);
			int j=p/k;
			a[(1<<i)+j]=min(
					a[(1<<(i+1))+j*2+0],
					a[(1<<(i+1))+j*2+1]);
		}
	}

	int get(int l, int r, int p=0, int q=0){
		int k=1<<(M-p);
		int f=k*q, g=k*(q+1);
		int ret;
		if(r<=f || g<=l){
			ret=INIT;
		}else if(l<=f && g<=r){
			ret=a[(1<<p)+q];
		}else{
			ret=min(
					get(l, r, p+1, q*2+0),
					get(l, r, p+1, q*2+1));
		}
		// printf("get(%d, %d, %d, %d)=%d\n", l, r, p, q, ret);
		return ret;
	}
};

