	int query(int a, int b, int k, int l, int r) //[a,b):query,k:今のノードの番号,[l,r):今のノードに対応するsegment
	{
		if (r <= a || b <= l)return INT_MAX;
		if (a <= l && r <= b)return dat[k];
		else
		{
			int val_l = query(a, b, 2 * k + 1, l, (l + r) / 2);
			int val_r = query(a, b, 2 * k + 2, (l + r) / 2, r);
			return min(val_l, val_r);
		}
	}
};

void solve()
{
	int n, q;
	cin >> n >> q;
	SegTreeRMQ st(n);
	vector<int> ans;
	rep(i, q)
	{
		int com, x, y;
		cin >> com >> x >> y;
		if(com == 0)
		{
			st.update(x, y);
		}
		else
		{
			int a = st.query(x, y+1, 0, 0, st.n);
			ans.push_back(a);
		}
	}
	rep(i, sz(ans))cout << ans[i] << endl;
	return;
}

int main()
{
	cin.tie(0);
	ios::sync_with_stdio(false);
	cout << fixed << setprecision(15);
	solve();
	return 0;
}

