struct SegmentTree{
    int n, sz;
    vector<Monoid> node;

    Monoid f(Monoid a, Monoid b){
        return min(a, b);
    }
    Monoid M1 = numeric_limits<Monoid>::max();

    SegmentTree(vector<Monoid> v){
        sz = v.size();
        n = 1;
        while(n < sz) n *= 2;
        node.assign(2 * n, M1);
        for(int i = 0; i < sz; ++i) node[n + i] = v[i];
        for(int i = n - 1; i > 0; --i) node[i] = f(node[i * 2], node[i * 2 + 1]);
    }

    void update(int k, Monoid val){
        k += n;
        node[k] = val;
        while(k >>= 1){
            node[k] = f(node[k * 2], node[k * 2 + 1]);
        }
    }

    Monoid query(int a, int b){
        Monoid l = M1, r = M1;
        for(a += n, b += n; a != b; a >>= 1, b >>= 1){
            if(a & 1) l = f(l, node[a++]);
            if(b & 1) r = f(node[--b], r);
        }
        return f(l, r);
    }
};

