using namespace std;

template <typename Monoid>
struct SegmentTree {
    using Func = function<Monoid(Monoid, Monoid)>;
    const Func F;
    const Monoid E;

    int SIZE = 1;
    vector<Monoid> node;

    SegmentTree(int n, const Func f, const Monoid &e) : F(f), E(e) {
        while (SIZE < n) SIZE *= 2;
        node.assign(SIZE * 2, E);
    }

    void set(int a, const Monoid &val) { node[a + SIZE] = val; }

    void build() {
        for (int k = SIZE - 1; k > 0; k--) {
            node[k] = F(node[2 * k], node[k * 2 + 1]);
        }
    }

    void update(int a, const Monoid &val) {
        int k = a + SIZE;
        node[k] = val;
        while (k >>= 1) node[k] = F(node[2 * k], node[2 * k + 1]);
    }

    Monoid query(int a, int b) {
        Monoid leftVal = E, rightVal = E;
        for (int left = a + SIZE, right = b + SIZE; left < right;
             left >>= 1, right >>= 1) {
            if (left & 1) leftVal = F(leftVal, node[left]), left += 1;
            if (right & 1) right -= 1, rightVal = F(rightVal, node[right]);
        }
        return F(leftVal, rightVal);
    }

    inline Monoid operator[](int a) { return node[a + SIZE]; }
};

int main() {
    int N, Q;
    cin >> N >> Q;
    SegmentTree<long long> seg(
        N, [](long long a, long long b) { return min(a, b); }, (1ll << 31) - 1);
