class RMQ
{
private:

	int size;

	vector<long long> minvalue;
	vector<long long> maxvalue;

	pair<long long, long long> _query(int a, int b, int k, int l, int r)
	{
		if (r <= a || b <= l) { return make_pair(INF, -INF); }
		if (a <= l && r <= b) { return make_pair(minvalue[k], maxvalue[k]); }

		pair<long long, long long> vl = _query(a, b, 2 * k + 1, l, (l + r) / 2);
		pair<long long, long long> vr = _query(a, b, 2 * k + 2, (l + r) / 2, r);

		return make_pair(min(vl.first, vr.first), max(vl.second, vr.second));
	}

public:

	RMQ(int size_)
	{
		for (size = 1; size < size_;) { size <<= 1; }

		minvalue = vector<long long>(size * 2 - 1, INF);
		maxvalue = vector<long long>(size * 2 - 1, -INF);
	}

	void update(int i, long long x)
	{
		i += size - 1;

		minvalue[i] = x;
		maxvalue[i] = x;

		while (i > 0)
		{
			i = (i - 1) / 2;

			minvalue[i] = min(minvalue[2 * i + 1], minvalue[2 * i + 2]);
			maxvalue[i] = max(maxvalue[2 * i + 1], maxvalue[2 * i + 2]);
		}
	}

	pair<long long, long long> query(int s, int t)
	{
		return _query(s, t, 0, 0, size);
	}
};

