template<typename Monoid>
class segment_tree {
	std::vector<Monoid> tree;
	std::uint_fast32_t size;
public:
	segment_tree(std::uint_fast32_t length) {
		size = length - 1;
		size |= size >> 1;
		size |= size >> 2;
		size |= size >> 4;
		size |= size >> 8;
		size |= size >> 16;
		++size;
		tree = std::vector<Monoid>(size << 1);
		initialize();
	}
	void initialize() {
		std::uint_fast32_t i = size << 1;
		while (size < i--) { tree[i] = Monoid(); }
		++i;
		while (--i) { tree[i] = tree[i << 1] + tree[i << 1 | 1]; }
	}
	void update(std::uint_fast32_t index,std::function<Monoid(Monoid)> F) {
		index += size;
		tree[index] = F(tree[index]);
		while (index >>= 1) tree[index] = tree[index << 1] + tree[index << 1 | 1];
	}
	Monoid range(std::uint_fast32_t begin, std::uint_fast32_t end) {
		Monoid retL, retR;
		for (begin += size, end += size;begin < end;begin >>= 1, end >>= 1) {
			if (begin & 1) retL = retL + tree[begin++];
			if (end & 1)  retR = tree[end - 1] + retR;
		}
		return retL + retR;
	}
	Monoid operator[](std::uint_fast32_t index) {
		return tree[size + index];
	}
};

