class Range_Query {
private:
	struct segdata_t {
		int val;
	};
	int n;
	vector<segdata_t> seg;
	void update_rule(int k) {
		int l = k * 2 + 1, r = k * 2 + 2;
		seg[k].val = min(seg[l].val, seg[r].val);
	}
	int find_rule(int s, int t, int l, int r, int k) {
		if (s == l&&t == r) return seg[k].val;
		else {
			int mid = (l + r) / 2;
			if (s < mid&&mid < t) {
				int result1 = find_rule(s, mid, l, mid, k * 2 + 1);
				int result2 = find_rule(mid, t, mid, r, k * 2 + 2);
				return min(result1, result2);
			}
			else if (s < mid) {
				return find_rule(s, t, l, mid, k * 2 + 1);
			}
			else if (mid < t) {
				return find_rule(s, t, mid, r, k * 2 + 2);
			}
		}
	}
public:
	Range_Query(int N, vi a) {
		n = (int)pow(2, ceil(log2(N)));
		seg.resize(n * 2 - 1);
		Loop(i, N) {
			seg[n - 1 + i].val = a[i];
		}
		Loop(i, n - N) {
			seg[n - 1 + N + i].val = INT_MAX;
		}
		Loopr(i, n - 1) {
			update_rule(i);
		}
	}
	void update(int k, int x){
		k += n - 1;
		seg[k].val = x;
		while (k > 0) {
			k = (k - 1) / 2;
			update_rule(k);
		}
	}
	int fnd(int s, int t) {
		return find_rule(s, t, 0, n, 0);
	}
};


