constexpr ll inf = 1e15;
constexpr ll mod = 1e9+7;

class SegTree {
    int n = 1;
    // represents the tree as an array
    // parent of k: (k-1)/2, child of k: 2*k+1, 2*k+2
    vector<ll> nodes;

public:
    SegTree(int size, ll v) {
        while (n < size) n*= 2;
        nodes.resize(2*n-1, v);
    }

    SegTree(vector<ll> v) {
        while (n < v.size()) n*= 2;
        nodes.resize(2*n-1, inf);

        for (int i = 0; i < v.size(); i++) nodes[n-1+i] = v[i];
        for (int i = n-2; i >= 0; i++) nodes[i] = min(nodes[2*i+1], nodes[2*i+2]);
    }

    // return minimum value in [a, b). ([l, r) is interval in which k is.)
    ll rmq(int a, int b, int k = 0, int l = 0, int r = 0) {
        if (l >= r) r = n;
        if (r <= a || b <= l) return inf;
        if (a <= l && r <= b) return nodes[k];

        ll vl = rmq(a, b, 2*k+1, l, (l+r)/2);
        ll vr = rmq(a, b, 2*k+2, (l+r)/2, r);
        return min(vl, vr);
    }

    void update(int k, ll v) {
        k += n - 1;
        nodes[k] = v;
        // traverse from leaf to root
        while (k>0) {
            k = (k-1)/2;
            nodes[k] = min(nodes[k*2+1], nodes[k*2+2]);
        }
    }
};

