using namespace std;

template<typename T>
class SegTree {
public:
	SegTree(int n, function<T(T,T)> operation, function<T(T,T)> update, T identity = T())
	{
		int ne = 1;
		while (ne < n) {
			ne *= 2;
		}
		this->n_  = n;
		this->ne_ = ne;

		this->data_ = vector<T>(this->ne_ * 2, identity);

		this->operation_ = operation;
		this->update_    = update;
		this->identity_ = identity;
	}

	const T& Val(int i) const
	{
		return this->data_[i + this->ne_ - 1];
	}

	void Update(int i, const T& v)
	{
		int idx          = i + this->ne_ - 1;
		this->data_[idx] = this->update_(this->data_[idx], v);

		while (idx != 0) {
			idx      = (idx - 1) / 2;
			int lidx = idx * 2 + 1;
			int ridx = idx * 2 + 2;
			this->data_[idx] = this->operation_(this->data_[lidx], this->data_[ridx]);
		}
	}

	T QueryOpen(int l, int r) const
	{
		return this->QueryInternal(l, r, 0, this->ne_, 0);
	}

	T QueryClose(int l, int r) const
	{
		return QueryOpen(l, r + 1);
	}

private:
	T QueryInternal(int l, int r, int lc, int rc, int idx) const
	{
		if (l <= lc && rc <= r) {
			return this->data_[idx];
		}
		if (rc <= l || r <= lc) {
			return this->identity_;
		}

		int m = (lc + rc) / 2;

		int lidx = idx * 2 + 1;
		int ridx = idx * 2 + 2;

		if (r <= m) {
			return this->QueryInternal(l, r, lc , m, lidx);
		}
		else if (m <= l) {
			return this->QueryInternal(l, r, m, rc, ridx);
		}
		else {
			return this->operation_(
				this->QueryInternal(l, r, lc, m, lidx),
				this->QueryInternal(l, r, m, rc, ridx)
			);
		}
	}

	size_t           n_;
	size_t           ne_;
	vector<T>        data_;
	function<T(T,T)> operation_;
	function<T(T,T)> update_;
	T                identity_;
};

int main()
{
	ios_base::sync_with_stdio(false);
	cin.tie(NULL);
	cout << fixed << setprecision(20);

	int n, q; cin >> n >> q;

	auto operation = [](int64_t lhs, int64_t rhs) {
		return min(lhs, rhs);
	};
	auto update = [](int64_t orig, int64_t val) {
		return val;
	};

	SegTree<int64_t> st(n, operation, update, ((int64_t)1 << 31) - 1);

	REP(q) {
		int64_t o, x, y; cin >> o >> x >> y;

		if (o == 0) {
			st.Update(x, y);
		}
		else {
			cout << st.QueryClose(x, y) << endl;
		}
	}
}

