		if (query == UPDATE) {
			if (v.size() == 0) {
				v.push_back(std::make_pair(x, y));
			} else {
				for (size_t j = 0; j < v.size(); j++) {
					if (v[j].first >= x) {
						if (v[j].first == x) {
							v[j].second = y;
						} else {
							v.insert(v.begin() + j, std::make_pair(x, y));
