// Segment Tree
template <class M> class ST {
    void init(int n_) {
        for (n = 1, lev = 0; n < n_; n <<= 1, ++lev);
        d.assign(n << 1, e1);
    }

public:
    int n, lev;
    vector<M> d;
    virtual void assign(int, M) = 0;
    virtual M f(M, M) = 0;
    const M e1;

    ST(M e1) : e1(e1) {}

    void build(const vector<M>& v) {
        int n_ = v.size();
        init(n_);
        for (int i = 0; i < n_; ++i) d[n + i] = v[i];
        for (int i = n - 1; i > 0; --i) d[i] = f(d[(i << 1) | 0], d[(i << 1) | 1]);
    }
    void build(int n_) { init(n_); }

    void update(int k, M x) {
        assign(k += n, x);
        while (k >>= 1) d[k] = f(d[(k << 1) | 0], d[(k << 1) | 1]);
    }

    M query(int a, int b) {
        M L = e1, R = e1;
		for (int l = a + n, r = b + n; l < r; l >>= 1, r >>= 1) {
            if (l & 1) L = f(L, d[l++]);
            if (r & 1) R = f(d[--r], R);
		}
        return f(L, R);
    }
    M query(int a) { return query(a, a + 1); }
};

// Range Maximum Query (RMQ)
template <class M> struct RMQ : public ST<M> {
    RMQ(M e1 = numeric_limits<M>::min()) : ST<M>(e1) {}
    M f(M a, M b) override { return max(a, b); }
    void assign(int k, M x) override { this->d[k] = x; }
};

// Range Minimum Query (RmQ)
template <class M> struct RmQ : public ST<M> {
    RmQ(M e1 = numeric_limits<M>::max()) : ST<M>(e1) {}
    M f(M a, M b) override { return min(a, b); }
    void assign(int k, M x) override { this->d[k] = x; }
};

// Range Sum Query (RSQ)
template <class M> struct RSQ : public ST<M> {
    RSQ(M e1 = 0) : ST<M>(e1) {}
    M f(M a, M b) override { return a + b; }
    void assign(int k, M x) override { this->d[k] += x; }
};

