using namespace std;

struct node
{
	int num,l,r,ls,rs;
	node(int _l,int _r)
	{
		num=INT_MAX;
		l=_l;
		r=_r;
	}
};

vector<node> T;

int make(int l,int r)
{
	int id=T.size();
	T.push_back(node(l,r));
	T[id].ls=(l+1==r?-1:make(l,(l+r)/2));
	T[id].rs=(l+1==r?-1:make((l+r)/2,r));
	return id;
}

void update(int id,int x,int t)
{
	if(T[id].l+1==T[id].r)
	{
		if(T[id].l==x) T[id].num=t;
		return ;
	}
	int mid=(T[id].l+T[id].r)>>1;
	if(x<mid)
		update(T[id].ls,x,t);
	else
		update(T[id].rs,x,t);
	T[id].num=min(T[T[id].ls].num,T[T[id].rs].num);
}

int getmin(int id,int l,int r)
{
	if(l==r||T[id].l>=r||T[id].r<=l)
		return INT_MAX; 
	if(T[id].l>=l&&T[id].r<=r)
		return T[id].num;
	int mid=(T[id].l+T[id].r)>>1,mi=INT_MAX;
	if(l<mid)
		mi=min(mi,getmin(T[id].ls,l,r));
	if(r>mid)
		mi=min(mi,getmin(T[id].rs,l,r));
	return mi;
}

int main()
{
	T.reserve(100100);
	int n,q;
	scanf("%d%d",&n,&q);
	make(0,n);
	for(int i=0;i<q;i++)
	{
		int com,x,y;
		scanf("%d%d%d",&com,&x,&y);
		if(com==0) update(0,x,y);
		else printf("%d\n",getmin(0,x,y+1));
	}
}

