const int bB = 8;
const int B = 1 << bB;

int up(int x) {
	return (x + (1 << bB) - 1) >> bB;
}

int down(int x) {
	return x >> bB;
}

int main()
{
	ios::sync_with_stdio(false), cin.tie(0);
	int n, q;
	cin >> n >> q;
	const int H = up(n);
	vector<int> bv(H, INT_MAX), v(n, INT_MAX);
	while (q--) {
		int com, x, y;
		cin >> com >> x >> y;
		if (com == 0) {
			v[x] = y;
			int p = down(x);
			bv[p] = INT_MAX;
			for (int i = p << bB; i < n && i < (p << bB) + B; i++) {
				bv[p] = min(bv[p], v[i]);
			}
		}
		else {
			y++;
			int res = INT_MAX;
			for (int i = x; i < y && i < (up(x) << bB); i++) {
				res = min(res, v[i]);
			}
			if (up(x) <= down(y)) {
				for (int i = up(x); i < down(y); i++) {
					res = min(res, bv[i]);
				}
				for (int i = down(y) << bB; i < y; i++) {
					res = min(res, v[i]);
				}
			}
			printf("%d\n", res);
		}
	}
	return 0;
}

