    cin >> n >> q;

    SegmentTree<int> seg(n, [] (int a, int b) { return min(a, b); }, iINF);

    for(int i = 0; i < q; i++) {
        int com, x, y;
        cin >> com >> x >> y;

        if (com == 0) {
            seg.update(x, y);
        } else {
            cout << seg.query(x, y + 1) << endl;
        }
    }

    return 0;
}

