template<typename T>
class ScapegoatTree_Leaf {
public:
	struct Node {
		int range[2]; // [range[0], range[1])
		T val;
		Node *p = NULL, *l = NULL, *r = NULL;
		bool removed = false, leaf;
		int sz = 1, dc = 0;

		Node(Node* par, int rangel, int ranger, Node* left, Node* right) :leaf(false), val(T()), p(par), l(left), r(right) { range[0] = rangel, range[1] = ranger; }
		Node(Node* par, int t, T _val) :leaf(true), val(_val), p(par) { range[0] = t, range[1] = t + 1; }
		void upd() {
			if (!leaf) {
				sz = 1 + l->sz + r->sz;
				dc = removed + l->dc + r->dc;
				range[0] = l->range[0];
				range[1] = r->range[1];
				val = (l->removed ? T() : l->val) + (r->removed ? T() : r->val);
			}
			else
			{
				dc = removed;
			}
		}
		int size() {
			return sz - dc;
		}
	};

	Node* root = NULL;

	void updpath(Node* node) {
		Node* cur = node;
		while (cur != NULL) {
			cur->upd();
			cur = cur->p;
		}
	}


	int depth(Node* node) {
		Node* cur = node;
		int c = 0;
		while (cur != root) {
			cur = cur->p;
			c++;
		}
		return c;
	}

	void getarrayandremove(vector<Node*>& ar, Node* node) {
		if (node->leaf) {
			if (node->removed) {
				delete node;
			}
			else
				ar.push_back(node);
		}
		else {
			getarrayandremove(ar, node->l);
			getarrayandremove(ar, node->r);
			delete node;
		}
	}

	Node* makeBST(vector<vector<Node*>> ar, Node* p, int l, int r) {
		if (r - l == 1) {
			if (ar[l].size() == 1) {
				ar[l][0]->p = p;
				return ar[l][0];
			}
			else {

				Node *lleaf = ar[l][0], *rleaf = ar[l][1], *inter = new Node(p, lleaf->range[0], rleaf->range[1], lleaf, rleaf);
				lleaf->p = inter;
				rleaf->p = inter;

				inter->upd();
				return inter;
			}
		}
		int mid = (l + r) / 2;
		Node* cur = new Node(p, -1, -1, NULL, NULL); // updで範囲決定
		cur->l = makeBST(ar, cur, l, mid);
		cur->r = makeBST(ar, cur, mid, r);
		cur->upd();
		return cur;
	}

	Node* rebuild(Node* node) {
		vector<Node*> ar;
		vector<vector<Node*>> f;
		ar.reserve(node->sz);
		getarrayandremove(ar, node);

		int res = ar.size(), fc = 1;
		while (fc * 2 < ar.size())
			fc *= 2;

		for (int i = 0; ar.size() > i; i++) {
			f.push_back(vector<Node*>());
			f[f.size() - 1].push_back(ar[i]);
			if (res <= fc) {
				i++;
				f[f.size() - 1].push_back(ar[i]);
			}
			res--;
		}

		Node* nn = makeBST(f, node->p, 0, ar.size());

		if (node->p)
			node->p = nn;
		else
			root = nn;

		updpath(nn);
		return nn;
	}

	void remove(Node* node) {
		if (node == NULL) return;
		node->removed = true;
		updpath(node);

		if (root->dc * 4 > root->sz) {
			rebuild(root);
		}
	}

	void remove(int t) {
		remove(search(t));
	}

	Node* search(int t, bool b = false) {
		if (root == NULL) return NULL;

		Node* cur = root;

		while (!cur->leaf) {
			if (cur->l->range[1] > t) {
				cur = cur->l;
			}
			else if (cur->l->range[1] <= t) {
				cur = cur->r;
			}
		}
		if (cur->range[0] == t) return cur;
		else return b ? cur : NULL;
	}

	Node* insert(int t, T val) {
		if (root == NULL) {
			return root = new Node(NULL, t, val);
		}

		Node *node = search(t, true), *l, *r, *newleaf;

		if (node->range[0] == t) {
			node->removed = false, node->val = val;
			updpath(node);
			return node;
		}

		if (node->range[0] > t) {
			r = node, newleaf = l = new Node(NULL, t, val);
		}
		if (node->range[0] < t) {
			newleaf = r = new Node(NULL, t, val); l = node;
		}

		Node*  inter = new Node(node->p, l->range[0], r->range[1], l, r);
		if (node->p) {
			if (node->range[1] == node->p->range[1])
				node->p->r = inter;
			else
				node->p->l = inter;
		}
		else root = inter;
		l->p = inter;
		r->p = inter;
		inter->l = l;
		inter->r = r;

		updpath(inter);

		if (depth(newleaf) > (log(root->sz) / log(3.0 / 2))) {
			Node* cur = newleaf;
			while (cur->sz * 3 <= cur->p->sz * 2) {
				cur = cur->p;
			}
			rebuild(cur->p);
		}

		return newleaf;
	}

	T rangequery(int l, int r, Node* node = NULL) { // [l.r)
		if (root == NULL) return T();
		if (node == NULL) node = root;
		l = max(l, node->range[0]);
		r = min(r, node->range[1]);

		if (l == node->range[0] && r == node->range[1]) return node->val;
		if (l >= r) return T();
		T ret = T();
		ret = ret + rangequery(l, node->l->range[1], node->l);
		ret = ret + rangequery(node->r->range[0], r, node->r);
	}
};

