template <class T> struct SegmentTreeMax {

    int N;
    vector<T> node;
    const T INF = numeric_limits<T>::min() / 2;

    SegmentTreeMax (int n) : N(2<<(int)log2(n)) { 
        node.resize(N<<1, INF);
    }

    void update(int idx, T val){
        idx += N;
        node[idx] = val;
        while (idx > 0) {
            node[idx>>1] = max(node[idx], node[idx^1]);
            idx >>= 1;
        }
    }

    T get_max(int l, int r) { 
        T ret = INF;
        l += N, r += N;
        while (l < r) {
            if (l & 1) ret = max(ret, node[l++]);
            if (r & 1) ret = max(ret, node[--r]);
            l >>= 1; r >>= 1;
        }
        return ret;
    }

};

template <class T> struct SegmentTreeMin {

    int N;
    vector<T> node;
    const T INF = numeric_limits<T>::max() / 2;

    SegmentTreeMin (int n) : N(2<<(int)log2(n)) { 
        node.resize(N<<1, INF);
    }

    void update(int idx, T val){
        idx += N;
        node[idx] = val;
        while (idx > 0) {
            node[idx>>1] = max(node[idx], node[idx^1]);
            idx >>= 1;
        }
    }

    T get_min(int l, int r) { 
        T ret = INF;
        l += N, r += N;
        while (l < r) {
            if (l & 1) ret = min(ret, node[l++]);
            if (r & 1) ret = min(ret, node[--r]);
            l >>= 1; r >>= 1;
        }
        return ret;
    }

};

