                idx_l = (idx_l-1)/2;
            }
            if(idx_r%2 == 1){
                minVal = min(minVal, tree[idx_r]);
                idx_r = (idx_r-2)/2;
            } else {
                idx_r = (idx_r-1)/2;
            }
