	int n, q;
	cin >> n >> q;

	for(int i = 0; i < TREE_SIZE; i++){
		seg_tree[i] = INF;
	}

	for(int i = 0; i < q; i++){
		long long int num, a, b;
		cin >> num >> a >> b;
		if(num == 0){
			change(a, b);
		}else{
			cout << query(a, b + 1, 1, 0, TREE_SIZE / 2) << endl;
		}
	}

	return 0;
}

