//流量0の逆辺も張らないと正しく求まらないので注意
Weight maximumFlow(const Graph &ag, int s, int t) {

	Graph g(ag);
	for (int i = 0; i < ag.size(); ++i) {
		for (int j = 0; j < ag[i].size(); ++j) {
			int d = ag[i][j].dst;
			int s = ag[i][j].src;

			bool ok = false;
			for (int k = 0; k < ag[d].size(); ++k) {
				if (ag[d][k].src == s) {
					ok = true;
					break;
				}
			}
			if (!ok) {
				g[d].push_back(Edge(d, s, 0));
			}
		}
	}

	int n = g.size();
	Matrix flow(n, Array(n)), capacity(n, Array(n));
	REP(u, n) FOR(e, g[u]) capacity[e->src][e->dst] += e->weight;

	Weight total = 0;
	while (1) {
		queue<int> Q; Q.push(s);
		vector<int> prev(n, -1); prev[s] = s;
		while (!Q.empty() && prev[t] < 0) {
			int u = Q.front(); Q.pop();
			FOR(e, g[u]) if (prev[e->dst] < 0 && RESIDUE(u, e->dst) > 0) {
				prev[e->dst] = u;
				Q.push(e->dst);
			}
		}
		if (prev[t] < 0) return total; // prev[x] == -1 <=> t-side
		Weight inc = INF;
		for (int j = t; prev[j] != j; j = prev[j])
			inc = min(inc, RESIDUE(prev[j], j));
		for (int j = t; prev[j] != j; j = prev[j])
			flow[prev[j]][j] += inc, flow[j][prev[j]] -= inc;
		total += inc;
	}
}

struct vert {
	int deg;
	int s;
	int id;
	vert(int a, int b, int c) {
		deg = a;
		s = b;
		id = c;
	}
};

#define N (1<<17) 
// update(l,r,v) := [l,r]の区間に対してvを一様に足す. k,a,bは飾り

struct NODE {
	int sum;//更新された値. この値を参照する時は評価が完全に完了しているようにする.
	int lazy;	//遅延されている値を保存している
	NODE() {
		sum = lazy = 0;
	}
};

NODE seg[2 * N];

// inlineつけないと大変なことになるよ!(遅い)
inline void lazy_evaluate_node(int k, int a, int b) {
	seg[k].sum += seg[k].lazy * (b - a + 1);
	if (k < N) { // 2*k(左の子番号) < 2*N (節点の数) のイメージで. 末端ノードじゃなきゃ伝搬するのと等価.
		seg[2 * k].lazy += seg[k].lazy;	//次は君が伝搬してね☆って感じ.
		seg[2 * k + 1].lazy += seg[k].lazy;
	}
	seg[k].lazy = 0;
}

inline void update_node(int k) { // kの子が既に評価されていることが前提. 末端以外のときしか呼び出さないような位置に書くのでif文要らない.
	seg[k].sum = seg[2 * k].sum + seg[2 * k + 1].sum;
}

// update(l,r,v) := [l,r]を更新する. 区間は1-indexed.
void update(int l, int r, int v, int k = 1, int a = 1, int b = N) {
	lazy_evaluate_node(k, a, b); 	// とりあえず辿ったノードは都合がいいので伝搬しとけ精神.

	if (b < l || r < a) //[a,b]と[l,r]が交差している場合
		return;
	if (l <= a && b <= r) { // [l,r]が[a,b]を完全に含んでいる場合
		seg[k].lazy += v;
		lazy_evaluate_node(k, a, b); //一回遅延評価しとかないと都合悪いので.
		return;
	}

	int m = (a + b) / 2;
	update(l, r, v, 2 * k, a, m);
	update(l, r, v, 2 * k + 1, m + 1, b);
	update_node(k);
}

// get(l,r) := [l,r]に対するクエリの答えを得る. 区間は1-indexed.
int get(int l, int r, int k = 1, int a = 1, int b = N) {
	lazy_evaluate_node(k, a, b); // とりあえず辿ったノードは都合がいいので伝搬しとけ精神.

	if (b < l || r < a) //[a,b]と[l,r]が交差している場合
		return 0;

	if (l <= a && b <= r) { // [l,r]が[a,b]を完全に含んでいる場合
		return seg[k].sum;
	}

	int m = (a + b) / 2;
	int vl = get(l, r, 2 * k, a, m);
	int vr = get(l, r, 2 * k + 1, m + 1, b);
	update_node(k);
	return vl + vr;
}

class Hei {


public:
	const int normalsize;
	vector<pair<vector<long long int>, long long int>>squares;


	Hei(const int n,const long long int initializenum) :normalsize(sqrt(n)){
		int rest = n;
		while (rest > 0) {
			squares.push_back(make_pair(vector<long long int>(min(rest,normalsize), initializenum), initializenum));
			rest -= normalsize;
		}
	}

	void update(const long long int i, const long long int x) {
		int square = i%normalsize;
		squares[square].first[i - square*normalsize] = x;
		squares[square].second = min(x,squares[square].second);
	}

	//[l,r]
	long long int get(const int l,const int r) {
		assert(l<=r);

		int lsquare = l/normalsize;
		int rsquare = r/normalsize;
		if (lsquare == rsquare) {
			long long int amin(INF);
			for (int i = l - lsquare*normalsize; i <= r - rsquare*normalsize; ++i) {
				amin = min(amin,squares[lsquare].first[i]);
			}
			return amin;
		}
		else {
			long long int amin(INF);
			for (int i = l - lsquare*normalsize; i <= squares[lsquare].first.size(); ++i) {
				amin = min(amin,squares[lsquare].first[i]);
			}
			for (int i = lsquare + 1; i < rsquare; ++i) {
				amin = min(amin, squares[lsquare].second);
			}
			for (int i =0; i <= r - rsquare*normalsize; ++i) {
				amin = min(amin, squares[rsquare].first[i]);
			}
			return amin;
		}

	}

};

