//前処理Ｏ(n)
//クエリ処理Ｏ(log n)
//与えられた区間内の「最小値」を求める。

const int MAX_N=(1<<17);

int n,dat[2*MAX_N-1];

//初期化
void init(int n_){
  n=1;
  while(n<n_)n*=2;
  for(int i=0;i<2*n-1;i++)dat[i]=INF;
}

//k番目の値（０-indexed）をaに変更。
void update(int k,int a){
  //葉の節点
  k+=n-1;
  dat[k]=a;
  //根に向かって登りながら更新。
  while(k>0){
    k=(k-1)/2;
    dat[k]=min(dat[2*k+1],dat[2*k+2]);
  }
}

//[a,b)の最小値を求める。
//kは節点番号。ｌ、ｒは節点kに対応する区間[l,r)を表す。
//呼び出し方：query(a,b,0,0,n);
int query(int a,int b,int k,int l,int r){
  //[a,b)と[l,r)が交差しないとき。解に影響がない値ＩＮＦを返す。
  if(r<=a||b<=l)return INF;

  //[a,b)の中に[l,r)が完全に含まれているとき。節点kの値を返す。
  if(a<=l&&r<=b)return dat[k];
  else{
    //交差はするが、完全には含まれていないとき。二つの子の最小値を再帰で求める。
    int vl=query(a,b,2*k+1,l,(l+r)/2);
    int vr=query(a,b,2*k+2,(l+r)/2,r);
    return min(vl,vr);
  }
}


signed main(){
  int n,q;cin>>n>>q;
  init(n);
  for(int i=0;i<q;i++){
    int com,x,y;cin>>com>>x>>y;
    if(com==0){
      update(x,y);
    }else{
      cout<<query(x,y+1,0,0,n)<<endl;
    }
  }
  return 0;
}

