class SegmentTree {
private:
    std::size_t n;
    std::vector<long long> data;
private:
    static std::size_t arrangeSize(std::size_t n) {
        std::size_t m = 1;
        while(m < n) m *= 2;
        return m;
    }
    long long queryImpl(int a, int b, int i, int l, int r, long long defaultValue) const noexcept {
        if(r <= a || b <= l) return defaultValue;

        if(a <= l && r <= b) return data[i];
        else {
            long long left = queryImpl(a, b, 2 * i + 1, l, (l + r) / 2, defaultValue);
            long long right = queryImpl(a, b, 2 * i + 2, (l + r) / 2, r, defaultValue);
            return std::min(left, right);
        }
    }
public:
    SegmentTree(std::size_t n, long long defaultValue = std::numeric_limits<long long>::max())
            :n(arrangeSize(n)), data(2 * arrangeSize(n) - 1, defaultValue){}
    void update(std::size_t m, long long val) noexcept {
        int cur = m + n - 1;
        data[cur] = val;
        while(0 < cur) {
            int p = (cur - 1) / 2;
            data[p] = std::min(data[2 * p + 1], data[2 * p + 2]);
            cur = p;
        }
    }
    long long query(int a, int b, long long defaultValue = std::numeric_limits<long long>::max()) const noexcept {
        return queryImpl(a, b, 0, 0, n, defaultValue);
    }
};

