int n,q,com,x,y;
vector<int> dt;
vector<int> backet;

void find(int a,int b){
	int res=INF;
	for(long long i=a;i<b+1;){
		if(i%B==0 && i+B-1<=b){
			res=min(res,backet[i/B]);
			i+=B;
		}else{
			res=min(res,dt[i]);
			i++;
		}
	}
	cout<<res<<endl;
}

void update(int i,int x){
	dt[i]=x;
	int res=INF;
	for(long long j=i-i%B;j<min(n,i+B);j++){
		res=min(res,dt[j]);
	}
	backet[i/B]=res;
}

int main(){
	cin>>n>>q;
	rep(i,n)dt.push_back(INF);
	rep(i,n/B)backet.push_back(INF);
	rep(i,q){
		cin>>com>>x>>y;
		if(com==0)update(x,y);
		else find(x,y);
	}
	return 0;
}

