namespace RangeMinimumQuery {
  template<typename T, std::size_t N>
  void Init(T (&xs)[N], T max_value) {
    static_assert( (N & (~(N - 1))) == N, "N != 2^n");
    for(int i = 0; i < (int)N; ++i) {
      xs[i] = max_value;
    }
  }
  template<typename T, std::size_t N>
  void Update2(T (&xs)[N], int index) {
    if( index <= 1 ) return;
    int parent = index >> 1;
    int brother = index ^ 0x01;
    if( xs[index] < xs[brother] ) {
      xs[parent] = xs[index];
    }
    else {
      xs[parent] = xs[brother];
    }
    Update2(xs, parent);
  }
  template<typename T, std::size_t N>
  void Update(T (&xs)[N], int index0, const T& value) {
    xs[(N >> 1) + index0] = value;
    Update2(xs, (N >> 1) + index0);
  }
  template<typename T, std::size_t N>
  T Query2(T (&xs)[N], int left, int right, int rl, int rr, int id) {
    if( rr <= left or right <= rl ) return xs[0];
    if( left <= rl and rr <= right ) return xs[id];
    int rm = (rl + rr) / 2;
    return std::min(Query2(xs, left, right, rl, rm, (id << 1) + 0),
                    Query2(xs, left, right, rm, rr, (id << 1) + 1));
  }
  // [left0, right0)
  template<typename T, std::size_t N>
  T Query(T (&xs)[N], int left0, int right0) {
    return Query2(xs, left0, right0, 0, N >> 1, 1);
  }
};
