	int mid = (l + r) >> 1;
	if (y <= mid)
		return find(t << 1, l, mid, x, y);
	if (x > mid)
		return find(t << 1 | 1, mid + 1, r, x, y);
	else
		return min(
			find(t << 1, l, mid, x, mid),
			find(t << 1 | 1, mid + 1, r, mid + 1, y)
		);
}

