// Range Minimum Query　区間の最小値に対する処理
class SegTree {
public:
	void init(int _n, ll init_value) {
		n = 1;
		while (n < _n) n *= 2; // 要素数を2の冪乗にする
		dat.resize(2 * n - 1);
		REP(i, dat.size()) dat[i] = init_value;
		max_value = init_value;
	}

	// k番目の値をaに変更
	void update(int k, int a) {
		k += n - 1;
		dat[k] = a;
		while (k > 0) {
			k = (k - 1) / 2;
			dat[k] = min(dat[k * 2 + 1], dat[k * 2 + 2]);
		}
	}

	size_t size() { return n; }

	// [a, b)の最小値
	ll query(int a, int b) { return q_rec(a, b, 0, 0, n); }
private:
	ll q_rec(int a, int b, int k, int l, int r) {
		if (r <= a or b <= l) return max_value;
		if (a <= l and r <= b) return dat[k];
		else {
			ll vl = q_rec(a, b, k * 2 + 1, l, (l + r) / 2);
			ll vr = q_rec(a, b, k * 2 + 2, (l + r) / 2, r);
			return min(vl, vr);
		}
	}

	vector<ll> dat;
	int n;
	ll max_value;
};

