template<typename T>
struct segtree {
    T INF = ((ll)1 << 31) - 1;
    int n;
    vector<T> dat;

    void init(int n_) {
        n = 1;
        while (n < n_) {
            n *= 2;
        }
        dat.assign(2 * n - 1, INF);
    }

    void update(int k, T a) {
        k += n - 1;
        dat[k] = a;
        while (k > 0) {
            k = (k - 1) / 2;
            dat[k] = min(dat[k * 2 + 1], dat[k * 2 + 2]);
        }
    }

    T basequery(int a, int b, int k, int l, int r) {
        if (r <= a || b <= l) {
            return INF;
        }
        if (a <= l && r <= b) {
            return dat[k];
        } else {
            T vl = basequery(a, b, k * 2 + 1, l, (l + r) / 2);
            T vr = basequery(a, b, k * 2 + 2, (l + r) / 2, r);
            return min(vl, vr);
        }
    }

    //[l, r)の範囲の最小値を返す
    T query(int l, int r) {
        return basequery(l, r, 0, 0, n);
    }
};

