template<class T>
class SegTree{
public:
    int N;
    vector<T> dat;
    T def;
    function<T(T, T)> ope;
    function<T(T, T)> upd;

    SegTree(int _N, T _def, function<T(T, T)> _ope, function<T(T, T)> _upd){
        N = 1;
        while(N < _N) N *= 2;

        def = _def;
        ope = _ope;
        upd = _upd;
        dat.resize(2 * N - 1, def);
    }

    T Query(int a, int b, int k, int l, int r){
        if(r <= a || b <= l) return def;
        if(a <= l && r <= b) return dat[k];
        else {
            T c1 = Query(a, b, 2 * k + 1, l, (l + r) / 2);
            T c2 = Query(a, b, 2 * k + 2, (l + r) / 2, r);
            return ope(c1, c2);
        }
    }

    T query(int a, int b){
        return Query(a, b, 0, 0, N);
    }

    void update(int k, T x){
        k += N - 1;
        dat[k] = upd(dat[k], x);
        while(k > 0){
            k = (k - 1) / 2;
            dat[k] = ope(dat[k * 2 + 1], dat[k * 2 + 2]);
        }
    }
};

