template<typename T>
struct segtree{
	function<T(T,T)>calcfn;
	function<T(T,T)>updatefn;
	int n;
	T defvalue;
	vector<T>dat;
	segtree():n(0){};
	segtree(int n_,T defvalue_=numeric_limits<T>::max(),
		function<T(T,T)>calcfn_=[](T a,T b){return a<b?a:b;},
		function<T(T,T)>updatefn_=[](T a,T b){return b;}
	):defvalue(defvalue_),calcfn(calcfn_),updatefn(updatefn_)
	{
		init(n_);
	};
	void init(int n_)
	{
		n=1;
		while(n<n_)n<<=1;
		dat.assign(2*n-1,defvalue);
	}
	void copy(vector<T>v)
	{
		for(int i=0;i<v.size();i++)dat[i+n-1]=v[i];
		for(int i=n-2;i>=0;i++)dat[i]=calcfn(dat[i*2+1],dat[i*2+2]);
	}
	void update(int i,T a)
	{
		i+=n-1;
		dat[i]=updatefn(dat[i],a);
		while(i>0)
		{
			i=(i-1)/2;
			dat[i]=calcfn(dat[2*i+1],dat[2*i+2]);
		}
	}
	T query_(int a,int b,int i,int l,int r)
	{
		if(r<=a||b<=l)return defvalue;
		else if(a<=l&&r<=b)return dat[i];
		else
		{
			return calcfn(
				query_(a,b,i*2+1,l,(l+r)/2),
				query_(a,b,i*2+2,(l+r)/2,r)
			);
		}
	}
	T query(int a,int b)//[a,b)
	{
		return query_(a,b,0,0,n);
	}
};
main()
{
	int n,q;cin>>n>>q;
	segtree<int>rmq(n);
	for(int i=0;i<q;i++)
	{
		int c,x,y;cin>>c>>x>>y;
		if(c)cout<<rmq.query(x,y+1)<<endl;
		else rmq.update(x,y);
	}
}

