const int INF = 2147483647;

struct SegmentTree {
    int n;
    vector<int> heap;

    SegmentTree(int n): n(n) {
        heap.assign(4 * n, INF);
    }

    void update(int id, int l, int r, int q, int v) {
        if (id == -1) {
            return;
        }
        if (l == r) {
            heap[id] = v;
        }
        else {
            int m = l + (r - l)/2;
            if (q >= l && q <= m) {
                update(2 * id, l, m, q, v);
            }
            else if (q > m && q <= r) {
                update(2 * id + 1, m + 1, r, q, v);
            }
            pushup(id);
        }
    }

    int query (int id, int l, int r, int ql, int qr) {
        if (ql <= l && r <= qr) {
            return heap[id];
        }
        else {
            int m = l + (r - l)/2;
            int lvalue = INF;
            int rvalue = INF;
            if (ql <= m && qr >= l) {
                lvalue = query(2 * id, l, m, ql, qr);
            }
            if (qr > m && ql <= r) {
                rvalue = query(2 * id + 1, m + 1, r, ql, qr);
            }
            return min(lvalue, rvalue);
        }
    }

    void pushup(int id) {
        heap[id] = min(heap[2 * id], heap[2 * id + 1]); 
    }

};

int main() {
    int n, q;
    cin >> n >> q;
    SegmentTree sg = SegmentTree(n);

    for (int i = 0; i < q; i++) {
        int cmd;
        cin >> cmd;
        if (cmd == 0) {
            int pos, v;
            cin >> pos >> v;
            sg.update(1, 0, n - 1, pos, v);
        }
        else {
            int ql, qr;
            cin >> ql >> qr;
            cout << sg.query(1, 0, n - 1, ql, qr) << endl;
        }
    }
    return 0;
}

