struct segTree{
      ll n;
      vector<ll> dat;
      segTree(ll n_){
            n = 1;
            //かんたんのため要素数を2冪にする
            while(n < n_) n *= 2;
            //すべての値をinfにする
            for(ll i = 0; i < 2*n-1; i++) dat.push_back(longinf);
            dat.push_back(n);
      }
      //k番目の値(0-indexed)をaに変更
      void update(ll k,ll a){
            //葉の節点
            k += dat.back() - 1;
            dat[k] = a;
            while(k > 0){
                  k = (k - 1) / 2;
                  dat[k] = min (dat[k * 2 + 1], dat[k * 2 + 2]);
            }
      }
      //[a,b)の最小値を求める
      //後ろの方の引数は、計算のかんたんのための引数
      //kは節点の番号,l,rはその節点が[l,r)に対応づいていることを表す
      //したがって外からはq(a, b, 0, 0, n)と呼ぶ
      ll q(ll a,ll b,ll k,ll l,ll r){
            //[a,b)と[l,r)が交差しなければ,inf
            if(r<=a||b<=l) return longinf;
            //[a,b)が[l,r)を完全に含んでいればこの節点の値
            if(a<=l&&r<=b) return dat[k];
            else{
                  //そうでなければ2つの子の最小値
                  ll vl = q(a,b,k*2+1,l,(l+r)/2);
                  ll vr = q(a,b,k*2+2,(l+r)/2,r);
