template <typename T>
class DynamicSegmentTree {
private:
	const ll n;
	const T id;
	function<T(T, T)> merge;
	node<T> *root;
private:
	T value(node<T> *t) {
		return t ? t->val : id;
	}
	T sub(ll l, ll r, node<T>* n, ll lb, ll ub) {
		if (n == nullptr || ub <= l || r <= lb) return id;
		if (l <= lb && ub <= r) return n->val;
		ll c = (lb + ub) / 2;
		return merge(sub(l, r, n->l, lb, c), sub(l, r, n->r, c, ub));
	}
	node<T> *suc(ll p, node<T>* t, ll lb, ll ub, T val) {
		if (t == nullptr) t = new node<T>(id);
		if (lb + 1 == ub) {
			t->val = val;
			return t;
		}
		ll c = (lb + ub) / 2;
		if (p < c) {
			t->l = suc(p, t->l, lb, c, val);
		}
		else {
			t->r = suc(p, t->r, c, ub, val);
		}
		t->val = merge(value(t->l), value(t->r));
		return t;
	}
public:
	DynamicSegmentTree(ll n_, T id_, function<T(T, T)> merge_) :
		n(1 << (int)ceil(log2(n_))), id(id_), merge(merge_), root(nullptr) {}
	~DynamicSegmentTree() { if (root) delete root; }
	void update(ll p, T val) {
		root = suc(p, root, 0, n, val);
	}
	T find(ll l, ll r) {
		return sub(l, r + 1, root, 0, n);
	}
};

