#include <iostream>
#include <vector>
#include <limits>
#include <cmath>

using namespace std;

const int INF = numeric_limits<int>::max();

// [begin, end) of an array
// [left, right): range of the query
// current_idx: index of the node in segment_tree corresponding to a range in the original array
int query(int segment_tree[], int left, int right, int current_idx, int begin, int end){
	if(end <= left || begin >= right){
		return INF;
	}
	if(left <= begin && right >= end){
		return segment_tree[current_idx];
	}

	int left_val = query(segment_tree, left, right, 2 * current_idx + 1, begin, (begin + end) / 2); // value of the left child (left half range)
	int right_val = query(segment_tree, left, right, 2 * current_idx + 2, (begin + end) / 2, end); // value of the right child (right half range)
	return min(left_val, right_val);
}

// [left, right]
int find(int segment_tree[], int n, int left, int right){
	return query(segment_tree, left, right + 1, 0, 0, n);
}

void update(int segment_tree[], int n, int i, int x){
	int current_idx = i + n - 1; // tree index corresponding to the element i in array A
	segment_tree[current_idx] = x;
	while(current_idx > 0){
		current_idx = (current_idx - 1) / 2; // get the parent index
		segment_tree[current_idx] = min(segment_tree[2 * current_idx + 1], segment_tree[2 * current_idx + 2]); // update the child nodes
	}
}

int initRMQ(int original_size){
	int n = 1;
	// make the size of the array to be power of n
	while(n < original_size){
		n *= 2;
	}
	return n;
}

int main(){
	int original_size, q;
	cin >> original_size >> q;
	int n = initRMQ(original_size);
	int segment_tree[2 * n - 1];

	for(auto i = 0; i < 2 * n - 1; ++i){
		segment_tree[i] = INF;
	}

	for(auto i = 0; i < q; ++i){
		int cmd;
		int x,y;
		cin >> cmd >> x >> y;
		if(cmd == 0){
			update(segment_tree, n, x, y);
		}else if(cmd == 1){
			cout << find(segment_tree, n, x, y) << endl;
		}
	}
}

