int main(){
	int n; cin >> n;
	int q; cin >> q;
	vector<int> A(n,2147483647);
	int interval = sqrt(n);
	vector<int> B(interval+1,2147483647);

	FOR(i,q){
		int com, x, y; cin >> com >> x >> y;
		if(com == 0){
			A[x] = y;
			int s = x/interval;
			int tmp = A[s];
			for(int j = s * interval; j < min((s+1)*interval,n); j++)
				tmp = min(A[j],tmp);
			B[s] = tmp;
		}
		if(com == 1){
			int tmp = A[x];
			int j = x;
			while(j <= y){
				if(j % interval == 0 && y - j >= interval - 1){
					tmp = min(B[j/interval], tmp);
					j += interval;
				}
				else{
					tmp = min(A[j],tmp);
					j++;
				}
			}
			cout << tmp << endl;
		}
	}
	return 0;
}

