using namespace std;
int seg[262156], d;
void update(int i, int x) {
	i |= 1 << d; seg[i] = x;
	while(i > 1) {
		i >>= 1;
		seg[i] = min(seg[i * 2], seg[i * 2 + 1]);
	}
}
int query(int a, int b, int k, int l, int r) {
	if(a <= l && r <= b) return seg[k];
	if(r <= a || b <= l) return 2147483647;
	int lc = query(a, b, k, l, (l + r) >> 1);
	int rc = query(a, b, k, (l + r) >> 1, r);
	return min(lc, rc);
}
int n, q, tp, x, y;
int main() {
	scanf("%d%d", &n, &q);
	d = 32 - __builtin_clz(n);
	fill(seg, seg + (1 << (d + 1)), 2147483647);
	while(q--) {
		scanf("%d%d%d", &tp, &x, &y);
		if(tp == 0) update(x, y);
		else {
			int ret = query(x, y + 1, 1, 0, 1 << d);
			printf("%d\n", ret);
		}
	}
	return 0;
}

