class SegmentTreeMin{
    int n = 0;
    vector<int> dat;
public:
    SegmentTreeMin(){}
    SegmentTreeMin(int m, int fill = INF){
        int i = 1;
        while(i < m) i *= 2;
        n = i;
        dat.resize(2*i - 1);
        REP(j, 2*i-1) dat[j] = fill;
    }

    void update(int k, int a){
        k += n - 1;
        int moto = dat[k];
        dat[k] = a;
        while(k){
            k = (k - 1) / 2;
            dat[k] = min(dat[2*k+1], dat[2*k+2]);
        }
    }

    int getMin(int a, int b, int k=0, int l=0, int r=-1){
        //[a, b[であることに注意
        if(r < 0) r = n;
        if(r <= a || b <= l) return 2147483647;
        if(a <= l && r <= b) return dat[k];

        int vl = getMin(a, b, 2*k+1, l, (l+r)/2);
        int vr = getMin(a, b, 2*k+2, (l+r)/2, r);
        return min(vl, vr);
    }

    int getvalue(int k){
        return dat[k+n-1];
    }
};

