struct Segmin{
	//       1
	//   2        3
	// 4   5   6    7


	private:
	public:

	// (1<<15)=32768
	// 1<<16 = 65536
	// 1<<17 = 131072
	// 1<<18 = 262144

	int cor=(1<<18);

	vector<pa> vec;

	void shoki1(){
		vec.resize(2*cor+3, mp((1ll<<31)-1,0));
		for(int i=cor;i<2*cor;i++)vec[i].second=i-cor;
	}

	void shoki2(){
		for(int i=cor-1;i>0;i--) {
			if(vec[2*i].first<=vec[2*i+1].first) vec[i]=vec[2*i];
			else vec[i]=vec[2*i+1];
		}
	}

	void updadd(int x,int w){
		//x 項目に w加算
		x+=cor;
		vec[x].first+=w;
		x/=2;
		while(x){
			if(vec[2*x].first<=vec[2*x+1].first) vec[x]=vec[2*x];
			else vec[x]=vec[2*x+1];
			x/=2;
		}
	}

	void updchan(int x,int w){
		//x項目をwに変更
		x+=cor;
		vec[x].first=w;
		x/=2;
		while(x){
			if(vec[2*x].first<=vec[2*x+1].first) vec[x]=vec[2*x];
			else vec[x]=vec[2*x+1];
			x/=2;
		}
	}


	// [a,b)
	// k-th node
	// k no kukanha [l,r)
	pa segmin(int a,int b){
		a+=cor;
		b+=cor;
		pa ans=mp((1ll<<31)-1,-1);
		while(a<b){
			if(a&1){
				ans=min(ans,vec[a]);
				a++;
			}
			if(b&1){
				b--;
				ans=min(ans,vec[b]);
			}
			a/=2;
			b/=2;
		}
		return ans;

	}



};




