template <typename T>
struct min_ {
    T operator()(T x, T y) {
        return min(x, y);
    }
};

template <typename T, class F=min_<T>>
struct SegmentTree {
    size_t n;
    T e;
    vector<T> tree;
    F qfunc;
    SegmentTree(size_t m, T e=0): n(1), e(e) {
        qfunc = F();
        while (n < m) n <<= 1;
        tree = vector<T>(n<<1, e);
    }
    T range_query(size_t a, size_t b, size_t i=1, size_t l=0, size_t r=-1) {
        if (!~r) r = n;
        if (a<=l && r<=b) return tree[i];

        T vl=e, vr=e;
        size_t c=(l+r)>>1;

        if (a < c) vl=qfunc(e, range_query(a, b, i<<1|0, l, c));
        if (c < b) vr=qfunc(e, range_query(a, b, i<<1|1, c, r));

        return qfunc(vl, vr);
    }
    void update(size_t i, T x) {
        i += n;
        tree[i] = x;
        while (i>>1) {
            tree[i>>1] = qfunc(tree[i^1], tree[i]);
            i >>= 1;
        }
    }
};

