// セグメント木 の ライブラリ を 使ってみる.
// http://judge.u-aizu.ac.jp/onlinejudge/review.jsp?rid=3233348#1
// 初期化 → 子ノードから再帰的にO(n)
// 区間の最小値、更新→定数個のノードにしかアクセスしないのでO(log n)
// 利点
// 平衡処理が必要ない.
// ノードの個数 n + n / 2 + n / 4 + ... < 2n

// 木の持ち方
// 配列でノードに番号をつける.
// 上の段から、同じ段では左から順に番号を振る.
// この振り方だと, 番号n の 親: (n - 1) / 2 (を切り捨て)
//                          子: 2n + 1, 2n + 2,...
#include <bits/stdc++.h>
using namespace std;
// const int INT_MAX = 2147483647;
// const int MAX_N = 100010;
int n;
int dat[400040];
// 初期化
void init(){
    //全ての値を, INT_MAX にする.
    for(int i = 0; i < n * 2 - 1; i++) dat[i] = 2147483647;
}

// 値の更新
// 場所i に 対応する一番下のノードは, n + i - 1
// そこから (n - 1) / 2 を繰り返して親をたどる.
// i番目 の 値を x に変更.
void update(int i, int x){
    // 葉のノードの番号.
    i += n - 1;
    dat[i] = x;
    // 登りながら更新.
    while(i > 0){
        //親ノード
        i = (i - 1) / 2;
        //子ノードの中で小さいものを取る
        dat[i] = min(dat[i * 2 + 1], dat[i * 2 + 2]);
    }
}

// 最小値の取得 → 再帰
// 区間[i, j] と そのノードの区間が一致しない → INT_MAXを返しておく
// 区間[i, j] と そのノードの区間を完全に含む → その接点の持つ値を返す
// どちらでもない → 2つの子ノードについて再帰的に計算
// 要求区間[a, b) の min, いまのノードk, 対象区間[l, r) で 再帰的に計算, query(a, b, 0, 0, n) と呼ぶ
int query(int a, int b, int k, int l,int r){
    // 区間が交差しない
    if(r <= a || b <= l) return 2147483647;
    // 区間を完全に含む
    if(a <= l && r <= b) return dat[k]; //その接点の持つ値.
    else{
        // 子ノード[l, (l + r) / 2) について min を計算.
        int vl = query(a, b, k * 2 + 1,          l, (l + r) / 2);
        int vr = query(a, b, k * 2 + 2,(l + r) / 2,           r);
        return min(vl,vr);
    }
}

int main(){

    // 1. 入力情報取得.
    int q;
    scanf("%d %d", &n, &q);

    // 2. セグメント木構築.
    int n2 = 1;
    // n が 2 の階乗でない場合, nを 2の階乗 にする
    // → これを行うことでセグメント木は完全二分木となり扱いやすくなる
    for(int i = 0; i < 32; i++){
        if(n2 >= n){
            n = n2;
            break;
        }
        n2 *= 2;
    }
    init();

    // 3. 各判定クエリに対し, 出力を行う.
    for(int i = 0; i < q; i++){
        int c, x, y;
        scanf("%d %d %d", &c, &x, &y);
        if(c == 0) update(x,y);
        else       printf("%d\n", query(x, y + 1, 0, 0, n));
    }

    return 0;

}

