using namespace std;

class SegmentTree {
public:
    unsigned int n = 1;
    vector<int> dat;

    SegmentTree(const vector<int> &v) {
        while (n < v.size()) { n *= 2; }   // sz以上の最小の2冪
        dat.resize(2 * n - 1, INT_MAX);

        // 最下段
        for (int i = 0; i < v.size(); ++i) {
            dat[i + n - 1] = v[i];  // 最下段はn - 1からはじまる
        }
        // 木の全体を更新
        for (int i = n - 2; i >= 0; --i) {
            dat[i] = min(dat[2 * i + 1], dat[2 * i + 2]);
        }
    }

    // 元の配列でのidxをxにし、木を更新
    void update(int idx, int x) {
        idx += n - 1;   // 木での対象のインデックス
        dat[idx] = x;
        while (idx > 0) {
            idx = (idx - 1) / 2;                                  // 親のインデックス
            dat[idx] = min(dat[idx * 2 + 1], dat[idx * 2 + 2]);   // 左の子と右の子
        }
    }

    // 区間[a, b)の最小値
    int query(int a, int b) {
        return this->query(a, b, 0, 0, n);
    }

private:

    // [a, b)の最小値をノードk（区間[l, r]）から検索
    int query(int a, int b, int k, int l, int r) {
        assert(a < b && l < r);
        // 範囲外
        if (r <= a || b <= l) {
            return INT_MAX;
        }
        // 完全に含む
        if (a <= l && r <= b) {
            return this->dat[k];
        }
            // 一部含む
        else {
            int vl = query(a, b, k * 2 + 1, l, (l + r) / 2);    // 左の子
            int vr = query(a, b, k * 2 + 2, (l + r) / 2, r);    // 右の子
            return min(vl, vr);
        }
    }
};


int main(){
    cin.tie(0);
