  fill(seg, seg + n * 2ll - 1ll, inf);
}

void update(int k, long long x)
{
  k = k + n - 1;

  seg[k] = x;
  while (k){
    k = (k - 1) / 2;
    seg[k] = min(seg[k * 2 + 1], seg[k * 2 + 2]);
