constexpr std::uint64_t upperPow2(std::uint64_t x, std::uint64_t r = 1) {
  return x <= r ? r : upperPow2(x, r + r);
}

template <typename T>
struct Max {
  typedef T value_type;
  static const value_type default_value =
      std::numeric_limits<value_type>::min() + 100;
  static value_type merge(const value_type& a, const value_type& b) {
    return std::max(a, b);
  }
  static value_type eval(std::int64_t L, std::int64_t R, value_type v,
                         value_type lazy) {
    return v + lazy;
  }
};

template <typename T>
struct Min {
  typedef T value_type;
  static const value_type default_value =
      std::numeric_limits<value_type>::max() - 100;
  static value_type merge(const value_type& a, const value_type& b) {
    return std::min(a, b);
  }
  static value_type eval(std::int64_t L, std::int64_t R, value_type v,
                         value_type lazy) {
    return v + lazy;
  }
};

template <typename T>
struct Sum {
  typedef T value_type;
  static const value_type default_value = value_type();
  static value_type merge(const value_type& a, const value_type& b) {
    return a + b;
  }
  static value_type eval(std::int64_t L, std::int64_t R, value_type v,
                         value_type lazy) {
    return v + (R - L) * lazy;
  }
};
}
