template<class NODE>
struct SegmentTree {
	vector<NODE> node;
	using M = function<NODE(NODE, NODE)>;
	M merge;
	const NODE NODE_UNITY;
	int n;
	SegmentTree (int n_, M m, NODE node_unity) : merge(m), NODE_UNITY(node_unity) {
		n = 1;
		while (n < n_) n *= 2;
		node.resize(n * 2 - 1, NODE_UNITY);
	}
	void set(int p, NODE v) {
		p += n - 1;
		node[p] = v;
		while (p) {
			p = (p-1) / 2;
			node[p] = merge(node[p*2+1] , node[p*2+2]);
		}
	}
	NODE get(int a, int b, int k = 0, int l = 0, int r = -1) {
		if (r < 0) r = n;
		if (a <= l && r <= b) {
			return node[k];
		} else if (b <= l || r <= a) {
			return NODE_UNITY;
		}
		return merge(get(a, b, k * 2 + 1, l, (l+r) / 2), get(a, b, k * 2 + 2, (l+r) / 2, r));
	}
};

