template<typename Monoid, typename Operand>
struct RBnode {
	RBnode *ch[2], *par;
	Monoid value, sum;
	Operand lazy;
	uint32 size, height;
	bool color, reversed;//true=black
};
template<typename Monoid, typename Operand>
class RBTrees {
	using Node = RBnode<Monoid, Operand>;
public:
	std::vector<Node> nodes;
	uint32 itr;
	bool balanced;
	Monoid insdata;
	RBTrees(size_t maxsize) {
		nodes.resize(maxsize + 1);
		itr = 0;
		nodes[0].ch[0] = &nodes[0];
		nodes[0].ch[1] = &nodes[0];
		nodes[0].par = nullptr;
		nodes[0].size = 0;
		nodes[0].height = 1;
		nodes[0].color = 1;
	}
	Node *nil(void) {
		return &nodes[0];
	}
	Node *update(Node *node) {
		node->sum = node->value;
		if (node->ch[0] != &nodes[0]) {
			node->sum = node->ch[0]->sum + node->sum;
		}
		if (node->ch[1] != &nodes[0]) {
			node->sum = node->sum + node->ch[1]->sum;
		}
		node->size = node->ch[0]->size + 1 + node->ch[1]->size;
		return node;
	}
	void push(Node *node) {
		node->ch[0]->lazy = node->ch[0]->lazy * node->lazy;
		node->ch[1]->lazy = node->ch[1]->lazy * node->lazy;
		node->value = node->value * node->lazy;
		node->sum = node->sum * node->lazy;
		node->lazy.inactive();
		if (node->reversed) {
			node->ch[0]->reversed ^= 1;
			node->ch[1]->reversed ^= 1;
			std::swap(node->ch[0], node->ch[1]);
			node->sum.reverse();
			node->value.reverse();
			node->reversed = 0;
		}
		return;
	}
	Node *rotate(Node *node, uint32 dir) {
		Node *t = node->ch[dir ^ 1];
		node->ch[dir ^ 1] = t->ch[dir];
		node->height = t->ch[dir]->height;
		t->height = node->height + node->color;
		t->color = node->color;
		node->color = 0;
		t->par = node->par;
		node->par = t;
		t->ch[dir] = update(node);
		return update(t);
	}
	Node *insert(Node *root, const Monoid &value, uint32 position) {
		nodes[++itr].ch[0] = &nodes[0];
		nodes[itr].ch[1] = &nodes[0];
		nodes[itr].value = value;
		nodes[itr].sum = value;
		nodes[itr].lazy.inactive();
		nodes[itr].size = 1;
		nodes[itr].height = 1;
		nodes[itr].color = 0;
		nodes[itr].reversed = 0;
		push(root);
		root = _subins(root, position);
		if (!root->color) {
			root->height += 1;
			root->color = 1;
		}
		return root;
	}
	Node *_subins(Node *node, uint32 pos) {
		if (node == &nodes[0]) {
			balanced = 1;
			return &nodes[itr];
		}
		push(node->ch[0]);
		push(node->ch[1]);
		if (node->ch[0]->size < pos) {
			node->ch[1] = _subins(node->ch[1], pos - node->ch[0]->size - 1);
			node->ch[1]->par = node;
			if (balanced) {
				return _inbal(node, 1);
			}
		}
		else {
			node->ch[0] = _subins(node->ch[0], pos);
			node->ch[0]->par = node;
			if (balanced) {
				return _inbal(node, 0);
			}
		}
		return update(node);
	}
	Node *flip(Node *node) {
		node->ch[0]->color = 1;
		node->ch[0]->height += 1;
		node->ch[1]->color = 1;
		node->ch[1]->height += 1;
		node->color = 0;
		return node;
	}
	Node *_inbal(Node *node, uint32 dir) {
		if (!node->color) {
			push(node->ch[dir ^ 1]);
			return update(node);
		}
		balanced = 0;
		if (!node->ch[dir ^ 1]->color) {
			if (node->ch[dir]->ch[dir]->color&&node->ch[dir]->ch[dir ^ 1]->color) {
				return update(node);
			}
			balanced = 1;
			return flip(update(node));
		}
		if (!node->ch[dir]->ch[dir ^ 1]->color) {
			node->ch[dir] = rotate(node->ch[dir], dir);
		}
		if (node->ch[dir]->ch[dir]->color) {
			return update(node);
		}
		return rotate(node, dir ^ 1);
	}
	Node *access(Node *root, uint32 position) {
		while (1) {
			if (position > root->ch[0]->size) {
				position -= root->ch[0]->size + 1;
				root = root->ch[1];
			}
			else if (position < root->ch[0]->size) {
				root = root->ch[0];
			}
			else {
				return root;
			}
		}
	}
	Node *erase(Node *root, uint32 position) {
		push(root);
		if (root->ch[0]->size > position) {
			root->ch[0] = erase(root->ch[0], position);
			if (balanced) {
				return _erbal(update(root), 0);
			}
			return update(root);
		}
		else if (root->ch[0]->size < position) {
			root->ch[1] = erase(root->ch[1], position - root->ch[0]->size - 1);
			if (balanced) {
				return _erbal(update(root), 1);
			}
			return update(root);
		}
		if (root->ch[0] != &nodes[0]) {
			if (root->ch[1] != &nodes[0]) {
				root->ch[1] = erase(root->ch[1], 0);
				root->value = insdata;
				if (balanced) {
					return _erbal(update(root), 1);
				}
				return update(root);
			}
			root->ch[0]->color = 1;
			++root->ch[0]->height;
			balanced = 0;
			return root->ch[0];
		}
		else {
			insdata = root->value;
			if (root->ch[1] != &nodes[0]) {
				root->ch[1]->color = 1;
				++root->ch[1]->height;
				balanced = 0;
				return root->ch[1];
			}
			balanced = root->color;
			return &nodes[0];
		}
	}
	Node *_erbal(Node *node, uint32 dir) {
		if (node->ch[dir ^ 1]->ch[0]->color&&node->ch[dir ^ 1]->ch[1]->color) {
			node->height = node->ch[dir ^ 1]->height + node->color;
			if (node->ch[dir ^ 1]->color) {
				if (node->color) {
					node->ch[dir ^ 1]->color = 0;
					node->ch[dir ^ 1]->height -= 1;
					node->height -= 1;
					return node;
				}
				node->ch[dir ^ 1]->color = 0;
				node->ch[dir ^ 1]->height -= 1;
				node->color = 1;
				balanced = 0;
				return node;
			}
			node = rotate(node, dir);
			node->ch[dir] = _erbal(node->ch[dir], dir);
			node->height = node->ch[dir]->height + node->color;
			return node;
		}
		balanced = 0;
		if (node->ch[dir ^ 1]->ch[dir ^ 1]->color) {
			node->ch[dir ^ 1] = rotate(node->ch[dir ^ 1], dir ^ 1);
		}
		node = rotate(node, dir);
		++node->height;
		++node->ch[0]->height;
		node->ch[0]->color = 1;
		++node->ch[1]->height;
		node->ch[1]->color = 1;
		return node;
	}
	Monoid range(Node *root, uint32 begin, uint32 end) {
		Node *t = root;
		Monoid ret;
		while (1) {
			if (t->ch[0]->size < begin) {
				begin -= t->ch[0]->size + 1;
				end -= t->ch[0]->size + 1;
				t = t->ch[1];
				continue;
			}
			if (t->ch[0]->size < end) {
				end -= t->ch[0]->size + 1;
				ret = t->value;
				root = t->ch[0];
				t = t->ch[1];
				break;
			}
			t = t->ch[0];
		}
		while (root != &nodes[0]) {
			if (root->ch[0]->size < begin) {
				begin -= root->ch[0]->size + 1;
				root = root->ch[1];
				continue;
			}
			if (root->ch[1] != &nodes[0]) ret = (root->value + root->ch[1]->sum) + ret;
			else ret = root->value + ret;
			root = root->ch[0];
		}
		while (t != &nodes[0]) {
			if (t->ch[0]->size < end) {
				end -= t->ch[0]->size + 1;
				if (t->ch[0] != &nodes[0]) ret = ret + (t->ch[0]->sum + t->value);
				else ret = ret + t->value;
				t = t->ch[1];
				continue;
			}
			t = t->ch[0];
		}
		return ret;
	}
	void show(Node *node) {
		std::cout << "(";
		if (node->ch[0] != &nodes[0]) {
			show(node->ch[0]);
			std::cout << "←";
		}
		std::cout << node->value.e << " " << node->color << " " << node->height;
		if (node->ch[1] != &nodes[0]) {
			std::cout << "→";
			show(node->ch[1]);
		}
		std::cout << ")";
		return;
	}
	void check(Node *node) {
		if (node->ch[0] != &nodes[0]) {
			if (node->ch[0]->par != node)
				std::cerr << "#\n";
			check(node->ch[0]);
		}
		if (node->ch[1] != &nodes[0]) {
			if (node->ch[1]->par != node)
				std::cerr << "#\n";
			check(node->ch[1]);
		}
	}
};
struct SUB {
	int32 e;
	bool a;
	SUB() { set(); }
	SUB(int32 x, bool y) { e = x; a = y; }
	void set() { a = false; }
	void inactive(void) {
		a = false;
	}
	SUB operator*(const SUB &other) {
		if (other.a) return other;
		return *this;
	}
};
struct MIN {
	int32 e;
	MIN() { set(); }
	MIN(int32 x) { e = x; }
	void set() { e = 2147483647; }
	void reverse(void) {}
	MIN operator+(const MIN &other) {
		if (e < other.e) return *this;
		return other;
	};
	MIN operator*(const SUB &other) {
		if (other.a) return MIN(other.e);
		return *this;
	}
};
int main(void) {
	std::ios::sync_with_stdio(false);
	std::cin.tie(0);
	uint32 n, q;
	std::cin >> n >> q;
	RBTrees<MIN, SUB> T(n + q);
	RBnode<MIN, SUB> *r = T.nil();
	int64 com, y;
	uint32 x;
	rep(i, 0, n) {
		r = T.insert(r, MIN(2147483647), 0);
	}
	//T.show(r);std::cout << "\n";
	rep(i, 0, q) {
		std::cin >> com >> x >> y;
		if (com == 0) {
			r = T.erase(r, x);
			//T.show(r);std::cout << "\n";
			r = T.insert(r, MIN(y), x);
			//T.show(r);std::cout << "\n";
		}
		else {
			std::cout << T.range(r, x, y + 1).e << "\n";
		}
		//T.check(r);
	}
	return 0;
}

