int n, q, N;
int dat[4*100000];

void init(){
	N = 1;
	while(N < n) N *= 2;
	rep(i,N*2) dat[i] = INT_MAX;
}

void update(int x, int y){
	x += N-1;
	dat[x] = y;
	while(x > 0){
		x = (x-1)/2;
		dat[x] = min(dat[x*2+1],dat[x*2+2]);
	}
}

int query(int a, int b, int t, int r, int l){
	if(a >= l || b <= r) return INT_MAX;
	if(a <= r && l <= b) return dat[t];
	return min(query(a,b,t*2+1,r,(r+l)/2),query(a,b,t*2+2,(r+l)/2,l));
}

int main(){
	scanf("%d%d",&n,&q);
	init();
	rep(i,q){
		int com, x, y;
		scanf("%d%d%d",&com,&x,&y);
		if(com == 0){
			update(x,y);
		} else{
			printf("%d\n",query(x,y+1,0,0,N));
		}
	}
}

