template <class T = long long>
class ST {	//非再帰抽象化セグ木
   private:
	int n;
	vector<T> vec;
	T unit;
	function<T(T, T)> operation;

   public:
	ST(int _n, function<T(T, T)> _operation, T _unit = 0) : n(_n), operation(_operation), unit(_unit) { vec.assign(n * 2, unit); }
	void update(int idx, T x) {
		idx += n;
		vec[idx] = x;
		idx >>= 1;
		while(idx > 0) {
			vec[idx] = operation(vec[(idx << 1)], vec[(idx << 1) | 1]);
			idx >>= 1;
		}
	}
	T get(int lef, int rig) {
		T a = unit, b = unit;
		lef += n;
		rig += n;
		while(lef < rig) {
			if(lef & 1) a = operation(a, vec[lef]);
			if(rig & 1) b = operation(vec[rig - 1], b);
			(lef += 1) >>= 1;
			rig >>= 1;
		}
		return operation(a, b);
	}
};

int main() {
	// https://onlinejudge.u-aizu.ac.jp/courses/library/3/DSL/all/DSL_2_A
	int n, q;
	cin >> n >> q;
	ST<int> st(
		n, [](int a, int b) { return min(a, b); }, (int)((1LL << 31) - 1));
