template <class T>
class SegmentTree{
  ll N;
  vector<T> data;
  T def;
  function<T(T,T)> operation;
  function<T(T,T)> update;

  T _query(ll a,ll b,ll k,ll l,ll r){
      if(b <= l || r <= a) return def;
      if(a <= l && r <= b){
          return data[k];
      }else{
          T c1 = _query(a,b,k*2+1,l,(l+r)/2);
          T c2 = _query(a,b,k*2+2,(l+r)/2,r);
          return operation(c1,c2);
      }
  }
  public:
  SegmentTree(size_t _N,T _def,function<T(T,T)> _operaition,function<T(T,T)> _update):def(_def),operation(_operaition),update(_update){
          N = 1;
          while(N < _N){
              N *= 2;
          }
          data = vector<T>(2*N-1,def);
  }

  void change(ll i,T x){
      i += N-1;
      data[i] = update(data[i],x);
      while(i > 0){
          i = (i-1)/2;
          data[i] = operation(data[i*2+1],data[i*2+2]);
      }
  }

  T query(ll a,ll b){
      return _query(a,b,0,0,N);
  }

  T operator[](ll i){
      return data[i+N-1];
  }
};

int main(){
    ll N,Q;cin >> N >> Q;
    auto f = [](ll a,ll b){return min(a,b);};
    auto g = [](ll a,ll b){return b;};
    SegmentTree<ll> ST(N,INF,f,g);
    rep(i,Q){
        ll t,x,y;cin >> t >> x >> y;
        if(t == 0){
            ST.change(x,y);
        }else{
            cout << ST.query(x,y+1) << endl;
        }
    }
}

