template<class T>
class SqrtDecomposition {
private:
    const size_t B, _size;
    T const init;
    vector<T> a, b;

public:
    SqrtDecomposition(const size_t size = 0,
               T const &init_ = numeric_limits<T>::max(),
               const size_t B_ = 310)
        : B(B_), _size(size), init(init_),
          a(size, init), b(size/B + 1, init){}

    SqrtDecomposition(const vector<T> &a, const size_t B = 310)
        : B(B), _size(a.size()), init(numeric_limits<T>::max()),
          a(a), b(_size/B + 1, init){
        for(size_t i = 0; i < a.size(); i++){
            b[i/B] = min(b[i/B], a[i]);
        }
    }

    size_t size() const {
        return _size;
    }

    T get(const size_t &l, const size_t &r) const {
        T res = numeric_limits<T>::max();
        size_t i = l;
        while(i < r){
            if(i%B == 0 && i + B <= r){
                res = min(res, b[i/B]);
                i += B;
            } else {
                res = min(res, a[i]);
                i++;
            }
        }
        return res;
    }

    void set(const size_t &p, const T &x){
        a[p] = x, b[p/B] = init;
        size_t s = p/B, end = min(p - p%B + B, size());
        for(size_t i = p - p%B; i < end; i++){
            b[s] = min(b[s], a[i]);
        }
    }

    vector<T> to_a(int l = -1, int r = -1){
        if(l == -1) l = 0;
        if(r == -1) r = size();
        vector<T> res(r-l);
        for(int i = l; i < r; i++) res[i-l] = get(i,i+1);
        return res;
    }
};

typedef vector<int> vi;
vector<int> solve(int n, int q, const vi &a, const vi &b, const vi &c){
    vector<int> ans;
    SqrtDecomposition<int32_t> rmq(n, (1LL<<31)-1);
    for(int i = 0; i < q; i++){
        if(a[i] == 0){
            rmq.set(b[i],c[i]);
        } else {
            ans.push_back(rmq.get(b[i],c[i]+1));
        }
    }
    return ans;
}

