void init(int n) {
	sz = 1;
	while (sz < n) sz *= 2;
	REP(i, 2 * sz - 1) dt[i] = INIT;
}

void update(int k, int a) {
	k += sz - 1;
	dt[k] = a;
	while (k > 0) {
		k = (k - 1) / 2;
		dt[k] = min(dt[k * 2 + 1], dt[k * 2 + 2]);
	}
}

lint query(lint a, lint b, lint k = 0, lint l = 0, lint r = sz) {
	if (r <= a || b <= l) return INIT;
	if (a <= l && r <= b) return dt[k];
	else {
		lint vl = query(a, b, k * 2 + 1, l, (l + r) / 2);
		lint vr = query(a, b, k * 2 + 2, (l + r) / 2, r);
		return min(vr, vl);
	}
}

