template <class Monoid> class SegmentTree{
    int N;
    Monoid unit;
    vector<Monoid> tree;
    using FX = function<Monoid(Monoid,Monoid)>;
    FX func;

    public:

    void _build(vector<Monoid> &array){
        for (int i = N; i < 2*N; i++) tree[i] = array[i - N];
        for (int i = N - 1;i >= 0; i--) tree[i] = func(tree[i << 1],tree[i << 1|1]);
    }

    SegmentTree(int _N,Monoid _unit,FX _func) :N(_N),unit(_unit),func(_func),tree(2*N,unit) {
        //_build(array);
    }

    void update(int K,Monoid x){
        K += N;
        tree[K] = x;
        while (K > 1){
            K >>= 1;
            tree[K] = func(tree[K << 1],tree[K << 1|1]);
        }
    }

    Monoid query(int L,int R){
        L += N; R += N;
        Monoid vL = unit,vR = unit;
        while (L < R){
            if (L&1){
                vL = func(vL,tree[L]);
                L ++;
            }
            if (R&1){
                R --;
                vR = func(tree[R],vR);
            }
            L >>= 1; R >>= 1;
        }
        return func(vL,vR);
    }
};

