int FindMin(vector<int> data, int x, int y){
    vector<int> next;

    if(data.size() == 1)
        return data[0];

    for(int i = x; i <= y; i += 2){
        if(i + 1 > y)
            next.push_back(data[i]);
        else
            next.push_back(data[i] < data[i + 1] ? data[i] : data[i + 1]);
    }

    return FindMin(next);
}

int FindMin(vector<int> data){
    vector<int> next;

    if(data.size() == 1)
        return data[0];

    for(vector<int>::size_type i = 0; i < data.size(); i += 2){
        if(i + 1 > data.size() - 1)
            next.push_back(data[i]);
        else
            next.push_back(data[i] < data[i + 1] ? data[i] : data[i + 1]);
    }

    return FindMin(next);
}

