struct SegmentTree{
private:
    int n;
    vector<int> node;
public:
    SegmentTree(vector<int> v){
        int sz = v.size();
        n = 1;
        while(n < sz) n*=2;
        node.resize(2*n-1,INF);
        rep(i,sz) node[i+n-1] = v[i];
        rrep(i,n-2)node[i] = min(node[2*i+1],node[2*i+2]);
    }
    void update(int x,int val){
        x += (n-1);
        node[x] = val;
        while(x>0){
            x = (x-1)/2;
            node[x] = min(node[2*x+1],node[2*x+2]);
        }
    }
    int getmin(int a,int b,int l=0,int r=-1,int k=0){
        if(r<0) r = n;
        if(r <= a || b <= l) return INF;
        if(a <= l && r <= b) return node[k];
        int mid = (l+r)/2;
        int vl = getmin(a,b,l,mid,2*k+1);
        int vr = getmin(a,b,mid,r,2*k+2);
        return min(vl,vr);
    }
};
