const int INF = (1 << 31) - 1;
const int BACKET = 500;

int arr[100000];
int bac[201];

void update(int x, int y) {
    arr[x] = y;
    bac[x / BACKET] = min(bac[x / BACKET], y); 
}

int find(int s, int t) {
    int minv = INF;
    if (t - s >= BACKET) {
        for (int i = s; i < ((int)(s / BACKET) + 1) * BACKET; i++) {
            minv = min(minv, arr[i]);
        }
        for (int i = (int)(s / BACKET) + 1; i <= (int)(t / BACKET) - 1; i++) {
            minv = min(minv, bac[i]);
        }
        for (int i = (int)(t / BACKET) * BACKET; i <= t; i++) {
            minv = min(minv, arr[i]);
        }
    }
    else {
        for (int i = s; i <= t; i++) {
            minv = min(minv, arr[i]);
        }
    }

    return minv;
}

