    int n, q, com, x, y;
    cin >> n >> q;
    for (int i = 0; i < n; i++) {
        arr[i] = i;
    }
    fill(arr, arr + n, INF);
    fill(bac, bac + (n + BACKET - 1) / BACKET, INF);

    while (q--) {
        cin >> com >> x >> y;
        if (com == 0) {
            update(x, y);
        }
        else {
            cout << find(x, y) << endl;
