struct Heihou{
    vector<int> data;
    vector<int> bucket;
    int sqrtN=512;
    Heihou(int n){
        data.resize((n+sqrtN-1)/sqrtN*sqrtN,(1LL<<31)-1);
        bucket.resize((n+sqrtN-1)/sqrtN,(1LL<<31)-1);
    }

    void updata(int i,int x){
        data[i]=x;
        int l=i/sqrtN;
        int mi=(1LL<<31)-1;
        for(int k=l*sqrtN;k<(l+1)*sqrtN;k++){
            mi=min(mi,data[k]);
        }
        bucket[l]=mi;
    }

    int find(int s,int t){
        int mi=(1LL<<31)-1;
        for(int k=0;k<bucket.size();k++){
            if((k+1)*sqrtN<s or t<k*sqrtN)continue;
            if(s<=k*sqrtN and (k+1)*sqrtN<=t)mi=min(mi,bucket[k]);
            else {
                for(int p=max(s,(k)*sqrtN);p<=min(t,(k+1)*sqrtN);p++){
                    mi=min(mi,data[p]);
                }
            }
        }
        return mi;
    }

    void debugb(int n){
        cout<<"bucket"<<endl;
        rep(i,0,n)cout<<bucket[i]<<" ";
        cout<<endl<<"data"<<endl;
        rep(i,0,n)cout<<data[i]<<" ";
        cout<<endl;
    }


};


