    if (left_idx == right_idx) {
        for (int i = left; i <= right; i++) {
            ans = min(ans, data[i]);
        }
        return ans;
    }

    for (int i = left; i < ( (left_idx + 1) * RMQ_WIDTH); i++) {
        ans = min(ans, data[i]);
