    for (int i = (right_idx * RMQ_WIDTH); i <= right ; i++) {
        ans = min(ans, data[i]);
    }

    for (int i = left_idx + 1; i < right_idx; i++) {
        ans = min(ans, RMQ[i]);
    }

    return ans;
