constexpr int MAX_N = 100000, INF = (1 << 31) - 1;

int n, q;

int seg[MAX_N * 4];

void init(int x) {

	n = 1;

	while (x > n)
		n *= 2;

	for (int i = 0; i < n * 2 - 1; ++i)
		seg[i] = INF;
}

void update(int k, int a) {

	k += n - 1;

	seg[k] = a;

	while (k > 0) {

		k = (k - 1) / 2;

		seg[k] = std::min(seg[k * 2 + 1], seg[k * 2 + 2]);
	}
}

int query(int a, int b, int k, int l, int r) {

	if (r <= a || b <= l)
		return INF;

	if (a <= l&&r <= b)
		return seg[k];

	int vl = query(a, b, k * 2 + 1, l, (l + r) / 2);
	int vr = query(a, b, k * 2 + 2, (l + r) / 2, r);

	return std::min(vl, vr);
}

int main() {

	std::cin >> n >> q;

	init(n);

	int t, x, y;

	for (int i = 0; i < q; ++i) {

		std::cin >> t >> x >> y;

		if (t == 0)
			update(x, y);
		else
			std::cout << query(x, y + 1, 0, 0, n) << std::endl;
	}

	system("pause");

	return 0;
}

#include <bits/stdc++.h>
using namespace std;

constexpr long long INF = ((long long)1<<31)-1;

class SegTree{
public:
	int N;
	vector<long long> Dat;
	SegTree(int n){
		if((n & (n - 1)) == 0) N = n;
		else{
			N = 1;
			while(n > 0){
				N <<= 1;
				n >>= 1;
			}
		}
		Dat.resize(2 * N - 1, INF);
	}

	void update(int i, int x){
		i += N - 1;
		Dat[i] = x;
		while(i > 0){
			i = (i - 1) / 2;
			Dat[i] = min(Dat[i * 2 + 1], Dat[i * 2 + 2]);
		}
	}

	long long find(int a, int b, int k, int l, int r){
		if(r < a || b <= l) return INF;
		if(a <= l && r < b) return Dat[k];
		long long vl = find(a, b, k * 2 + 1, l, (l + r) / 2);
		long long vr = find(a, b, k * 2 + 2, 1 + (l + r) / 2, r);
		return min(vl, vr);
	}
};

int main(){
	cin.tie(0);
	ios::sync_with_stdio(false);
	int n, q;
	cin >> n >> q;
	SegTree st(n);
	while(q--){
		int t, x, y;
		cin >> t >> x >> y;
		if(t == 0) st.update(x, y);
		else cout << st.find(x, y+1, 0, 0, n-1) << "\n";
	}
}

