using namespace std;

int segment_tree_size = 1;
vector<int> minimum_segment_tree;

void item_change(int point, int number){
    point += segment_tree_size - 1;
    minimum_segment_tree[point] = number;
    while(point > 0){
        point = (point - 1) / 2;
        minimum_segment_tree[point] = min(minimum_segment_tree[point * 2 + 1], minimum_segment_tree[point * 2 + 2]);
    }
}

int range_minimum(int left, int right, int point_left, int point_right, int now){
    if(point_right <= left || right <= point_left){
        return 2147483647;
    }else if(left <= point_left && point_right <= right){
        return minimum_segment_tree[now];
    }else{
        return min(range_minimum(left, right, point_left, (point_left + point_right) / 2, now * 2 + 1),
                   range_minimum(left, right, (point_left + point_right) / 2, point_right, now * 2 + 2));
    }
}

int main(){
    int N, Q;
    cin >> N >> Q;
    while(segment_tree_size < N){
        segment_tree_size *= 2;
    }
    minimum_segment_tree.resize(segment_tree_size * 2 + 1);
    fill(minimum_segment_tree.begin(), minimum_segment_tree.end(), 2147483647);
    for(int i = 0; i < Q; i++){
        int com, x, y;
        cin >> com >> x >> y;
        if(com){
            cout << range_minimum(x, y + 1, 0, segment_tree_size, 0) << endl;
        }else{
            item_change(x, y);
        }
    }
}

