    int n, q;
    cin >> n >> q;
    RangeMinimumQuery rmq;
    rmq.init(n);
    while(q--){
        int com, x, y;
        cin >> com >> x >> y;
        if(com){
            cout << rmq.query(x, y + 1) << "\n";
        }else{
            rmq.update(x, y);
        }
    }
}

