class segment_tree {
  vector<int> xs;
public:
  segment_tree(int n) : xs(1 << (lg(2 * n - 1) + 1)) {}
  segment_tree(int n, function<int(int)> f) : segment_tree(n) {
    const int m = ::size(xs);
    dotimes(i, n)
      xs[m/2+i] = f(i);
    for (int i = m/2-1; i >= 1; i--)
      xs[i] = min(xs[2*i], xs[2*i+1]);
  }
  int operator[](int i) {
    return xs[::size(xs)/2+i];
  }
  void update(int i, int x) {
    i += ::size(xs) / 2;
    xs[i] = x;
    for (i /= 2; i >= 1; i /= 2)
      xs[i] = min(xs[2*i], xs[2*i+1]);
  }
  int query(const int i, const int j) {
    function<int(int, int, int)> rec;
    rec =
      [&](int k, int a, int b) {
        if (i <= a && b <= j)
          return xs[k];
        int c = a + (b - a) / 2;
        return j <= c ? rec(2*k, a, c) : c <= i ? rec(2*k+1, c, b) : min(rec(2*k, a, c), rec(2*k+1, c, b));
      };
    return rec(1, 0, ::size(xs)/2);
  }
};

