template<typename T> class SegmentTree {
    public:
    int n;
    int init_value = INT_MAX;
    T data[2*MAX_N-1];

    SegmentTree(int n, T init_value=INT_MAX){
        // 2のべき乗にする
        this->n = 1;
        while(this->n < n) this->n <<= 1;
        this->init_value = init_value;
        rep(2*(this->n)-1){
            data[i] = init_value;
        }
    }

    void update(int i, int x){
        i += n-1;
        data[i] = x;
        while(i){
            i = (i-1)/2;
            data[i] = min(data[2*i+1], data[2*i+2]);
        }
    }

    T find(int s, int t, int k, int kl, int kr){
        if(kr <= s || t <= kl) return init_value;
        if(s <= kl && kr <= t) return data[k];
        int kc = (kl+kr)/2;
        int vl = find(s, t, 2*k+1, kl, kc);
        int vr = find(s, t, 2*k+2, kc, kr);
        return min(vl, vr);
    }
};

