#include<iostream>
#include<algorithm>
using namespace std;

#define INF 2147483647

#define MAX_N 131072
//  131072 = 2^17

int tree[ MAX_N*2 ];
int L[ MAX_N*2 ];
int R[ MAX_N*2 ];

int dfs(int a,int b,int k){  
  if(R[k]<=a || b<=L[k])return INF;
  if(a<=L[k] && R[k]<=b)return tree[k];
  return min(dfs(a,b,k*2+1),dfs(a,b,k*2+2));
}

int getMin(int a,int b){
  return dfs(a,b,0);
}

