LL fac[SIZE], finv[SIZE], inv[SIZE];
void combInit() {
    fac[0] = fac[1] = 1;
    finv[0] = finv[1] = 1;
    inv[1] = 1;
    for( int i = 2; i < SIZE; ++i ) {
        fac[i] = (fac[i - 1] * i) % MOD;
        inv[i] = MOD - inv[MOD % i] * (MOD / i) % MOD;
        finv[i] = (finv[i - 1] * inv[i]) % MOD;

    }
}

LL comb(int n, int k) {
    if( n < k ) return 0;
    if( n < 0 || k < 0 ) return 0;
    return (fac[n] * (finv[k] * finv[n - k] % MOD)) % MOD;

}

vector< int > Div( int n ) {
    vector< int > ret;
    for( int i = 1; i * i <= n; ++i ) {
        if( n % i == 0 ) {
            ret.pb( i );

            if( i * i != n ) ret.pb( n / i );
        }
    }
    sort( all( ret ) );
    return ret;
}

class SegTreeMin {
public:
    int n;
    vector< int > node;

    SegTreeMin(vector< int > v) {
        int sz = v.size();
        n = 1;
        while( n < sz ) n <<= 1;
        node.resize(2 * n - 1, INF);

        for( int i = 0; i < sz; ++i ) {
                node[i + n - 1] = v[i];

        }
        for( int i = n - 2; i >= 0; --i ) {
            node[i] = min(node[2 * i + 1], node[2 * i + 2]);

        }
    }

    void Update(int x, int val) {
        x += n - 1;
        node[x] = val;
        while( x > 0 ) {
            x = (x - 1) >> 1;
            node[x] = min(node[2 * x + 1], node[2 * x + 2]);

        }
    }

    int Query(int a, int b, int k = 0, int l = 0, int r = -1) {
        if( r < 0 ) {
            r = n;

        }

        if( r <= a || b <= l ) {
            return INF;

        }
        if( a <= l && r <= b ) {
            return node[k];

        }

        int vl = Query(a, b, 2 * k + 1, l, (l + r) / 2);
        int vr = Query(a, b, 2 * k + 2, (l + r) / 2, r);
        return min(vl, vr);

    }

};

