    vector< int > v(n);
    for( int i = 0; i < n; ++i ) {
        v[i] = INF;

    }

    SegTreeMin seg(v);

    while( q-- ) {
        int com, x, y;
        cin >> com >> x >> y;
        if( com == 0 ) {
            seg.Update(x, y);

        } else {
            cout << seg.Query(x, y + 1) << endl;

        }
    }
    return 0;
}

