const int inf = (int)((1U<<31)-1);

class Segment_Tree{
private:
  int N;
  vector<int> nlist;
public:
  Segment_Tree(int n){
    N = 1;
    while(N < n) N *= 2;
    nlist.resize(2*N-1);
    for(int i=0;i<2*N-1;++i){
      nlist[i] = inf;
    }
  }

  void update(int k,int x){
    k += N - 1;
    nlist[k] = x;
    while(k > 0){
      k = (k-1)/2;
      nlist[k] = min(nlist[k*2+1],nlist[k*2+2]);
    }
  }

  int query(int a,int b){
    return query(a,b,0,0,N);
  }

  int query(int a,int b,int x,int l,int r){
    if(r <= a || b <= l) return inf;
    if(a <= l && r <= b) return nlist[x];
    int m = (l+r)/2;
    return min(query(a,b,2*x+1,l,m),query(a,b,2*x+2,m,r));    
  }
};

