template <typename T>
struct segtree {
	int n;
	vector<T> tree;
	T def = numeric_limits<T>::max(), none = numeric_limits<T>::max();

	segtree(int n_) {
		for (n = 1; n < n_; n *= 2) {

		}
		tree.assign(2 * n, def);
	}

	T get(int index) {
		assert(0 <= index && index < n);
		return tree[n + index];
	}

	T merge(T a, T b) {
		return min(a, b);
	}

	void update(int index, T x) {
		assert(0 <= index && index < n);
		tree[index += n] = x;
		for (index /= 2; index; index /= 2) {
			tree[index] = merge(tree[2 * index], tree[2 * index + 1]);
		}
	}

	T query(int a, int b, int index, int l, int r) {
		assert(0 <= a && a < b && b <= n);
		assert(0 <= l && l < r && r <= n);
		if (r <= a || b <= l) {
			return none;
		}
		if (a <= l && r <= b) {
			return tree[index];
		}
		T puni = query(a, b, 2 * index, l, (l + r) / 2);
		T muni = query(a, b, 2 * index + 1, (l + r) / 2, r);
		return merge(puni, muni);
	}

	T query(int l, int r) {
		assert(0 <= l && l < r && r <= n);
		return query(l, r, 1, 0, n);
	}
};

