#include <bits/stdc++.h>
using namespace std;

const int id = INT_MAX;

int op(int l, int r) {
	return min(l, r);
}

struct node {
	int pos, val, all;
	node *lch, *rch;
	node(int p, int v)
		: pos(p), val(v), all(v), lch(nullptr), rch(nullptr) {}
};

void update_up(node* t) {
	t->all = op(op((t->lch ? t->lch->all : id), t->val), (t->rch ? t->rch->all : id));
}

node *update(node* t, int p, int val, int lb, int ub) {
	if (!t) return new node(p, val);
	if (t->pos == p) {
		t->val = val;
		update_up(t);
		return t;
	}
	int m = (lb + ub) >> 1;
	if (p < m) {
		t->lch = update(t->lch, p, val, lb, m);
	}
	else {
		t->rch = update(t->rch, p, val, m, ub);
	}
	update_up(t);
	return t;
}

int find(node* t, int l, int r, int lb, int ub) {
	if (!t || r <= lb || ub <= l) return id;
	if (l <= lb && ub <= r) return t->all;
	int m = (lb + ub) >> 1;
	return op(find(t->lch, l, r, lb, m), find(t->rch, l, r, m, ub));
}

int main()
{
	int n, q;
	scanf("%d%d", &n, &q);
	node *seg = nullptr;
	while (q--) {
		int com, x, y;
		scanf("%d%d%d", &com, &x, &y);
		if (com == 0) {
			seg = update(seg, x, y, 0, n);
		}
		else {
			printf("%d\n", find(seg, x, y + 1, 0, n));
		}
	}
	return 0;
}

#include<bits/stdc++.h>
using namespace std;

struct range_minimum_query{

  // 管理したい元の配列のサイズ以上の2冪。

  int n;

  // セグメント木(完全二分木)を管理する一次元配列。

  vector<int> segtree;

  // minの単位元としてのINF。値は2^31-1。

  const int INF = INT_MAX;



  // @param sz 管理したい元の配列のサイズ

  // nをsz以上の2冪にし、セグメント木のサイズを2*n-1、値をINFに初期化する。

  range_minimum_query(int sz){

    for(n = 1; n<sz;) n <<= 1;

    segtree.assign(2*n-1,INF);
  }

   // 元の配列の[l,r)のminを求める。

  // @param l,r [l,r)が求めたいminの元の配列での範囲。

  // @param a,b [a,b)が現在見ている頂点の持つminの元の配列における範囲。

  // @param k   セグメント木の現在見ている頂点のindex

  // @return    セグメント木により、求められた[l,r)の最小値。

  // 上からDFSして、[l,r)内の頂点であれば自身の値を返し、そうでなければ単位元を返す。

  // このようにして帰ってきた値を全てminしたものが求めたいものである。

  // デフォルト引数にn(非staticなメンバ変数)を指定できないため、オーバーロードしている。

  int find(int l, int r){

    return find(l,r,0,n,0);

  }

  int find(int l, int r, int a, int b, int k){

    // [a,b)が[l,r)の外側なら、影響のない単位元INFを返す。

    if(b<=l || r<=a) return INF;



    // [a,b)が[l,r)の内側なら、その頂点は[l,r)内で最も大きい区間minを持つので、それを返す。

    else if(l<=a && b<=r) return segtree[k];



    // どちらでもなければ(解説スライドでの赤線を跨いでいる状態)、もっと細分されたものを確認する必要があるため、子を確認する。

    // 左側の子は[a,(a+b)/2)の区間minを持ち、indexは2*k+1

    // 右側の子は[(a+b)/2,b)の区間minを持ち、indexは2*k+2

    // この２つの[l,r)内の区間minのminを返してやれば良い。

    // 現在見ている頂点が葉に該当する場合は必ず上の２つの条件のどちらかで捕捉されるため考えなくて良い。

    else return min(find(l,r,a,(a+b)/2,2*k+1), find(l,r,(a+b)/2,b,2*k+2));

  }



  // 指定した頂点とその影響する範囲の値を更新する。  

  // @param i 書き換えたい値の元の配列におけるindex

  // @param x 更新後の値

  void update(int i, int x){

    // 解説スライドの通り、元の配列を持つ最下段の長さをn(2冪)とすると、

    // その上のセグメント木の構造を持つ部分は n/2 + n/4 + n/8 + .. + 1 = n-1(等比級数の公式より)

    // よって、元の配列を最初に更新したいので、元の配列部分のindexに修正するため、n-1を加える。

    i += n-1;



    // その頂点をxに更新する。

    segtree[i] = x;

    // 更新した最下段の情報の影響する範囲を更新する。

    // 具体的には更新した頂点の祖先全てが対象となる。

    while(i>0){

      // 親ノードへと移動

      i = (i-1)/2;

      // 自分の子２つを比較し、小さい方を得る。

      segtree[i] = min(segtree[2*i+1], segtree[2*i+2]);

    }

  }

};


int main(){
    int n,q,l,r,c;
    cin>>n>>q;


    range_minimum_query rmq(n);


    for(int i=0;i<q;i++){

        cin>>c;

        if(c==0){
            cin>>l>>r;
            rmq.update(l,r);
        }
        else{
            cin>>l>>r;
            cout << rmq.find(l,r+1) << endl;
        }
    }
}

#include <bits/stdc++.h>
using namespace std;

const long long INF = INT_MAX;
struct SegmentTree {
private:
    long long n;
    vector<long long> node;

public:
    SegmentTree(vector<long long> v) {
        long long sz = v.size();
        n = 1; while(n < sz) n *= 2;
        node.resize(2*n-1, INF);
        for(long long i=0; i<sz; i++) node[i+n-1] = v[i];
        for(long long i=n-2; i>=0; i--) node[i] = min(node[2*i+1], node[2*i+2]);
    }

    void update(long long x, long long val) {
        x += (n - 1);
        node[x] = val;
        while(x > 0) {
            x = (x - 1) / 2;
            node[x] = min(node[2*x+1], node[2*x+2]);
        }
    }

    long long getmin(long long a, long long b, long long k=0, long long l=0, long long r=-1) {
        if(r < 0) r = n;
        if(r <= a || b <= l) return INF;
        if(a <= l && r <= b) return node[k];

        long long vl = getmin(a, b, 2*k+1, l, (l+r)/2);
        long long vr = getmin(a, b, 2*k+2, (l+r)/2, r);
        return min(vl, vr);
    }
};

int main() {
    long long N, Q;
    cin >> N >> Q;
    SegmentTree seg( vector<long long>(N, INF) );
    for(long long i = 0; i<Q; i++) {
        long long c, x, y;
        cin >> c >> x >> y;
        if(c == 0) seg.update(x, y);
        else cout << seg.getmin(x, y+1) << endl;
    }    
}

