    sscanf(s, "%d %d %d", &t, &a, &b);
    if(t == 0) {
      int curr = a / BACKET;
      bool update = small[curr] == A[a] && sz[curr] == 1;
      A[a] = b;
      if(small[curr] == b) {
        ++sz[curr];
      } else if(small[curr] > b) {
        small[curr] = b;
        sz[curr] = 1;
      } else if(update) {
        small[curr] = INF;
        sz[curr] = 1;
        for(int i = 0; i < BACKET; i++) {
          if(small[curr] == A[curr * BACKET + i]) {
            ++sz[curr];
          } else if(small[curr] > A[curr * BACKET + i]) {
            small[curr] = A[curr * BACKET + i];
            sz[curr] = 1;
          }
        }
      }
    } else {
      int begin = (a + BACKET - 1) / BACKET;
      int end   = b / BACKET;
      int ret = INF;
      if(begin >= end) {
        for(int i = a; i <= b; i++) chmin(ret, A[i]);
      } else {
        for(int i = begin; i < end; i++) chmin(ret, small[i]);
        if(ret > small[begin - 1]) for(int i = begin * BACKET - 1; i >= a; i--) chmin(ret, A[i]);
        if(ret > small[end]) for(int i = end * BACKET; i <= b; i++) chmin(ret, A[i]); 
      }
      printf("%d\n", ret);
    }
  }
}

