template<typename T>
struct Solver2 {
   Int n;
   T e;
   std::function<T(T,T)> f;
   std::vector<Int> ls, rs;
   std::vector<T> xs;
   Solver2(Int n_, T e_, std::function<T(T,T)> f_)
      : n(round2(n_)), e(e_), f(f_), ls(2*n), rs(2*n), xs(2*n, e) {
      for(Int i = n; i < 2 * n; ++i) {
         ls[i] = i-n;
         rs[i] = i-n+1;
      }
      for(Int i = n - 1; i >= 1; --i) {
         ls[i] = ls[2*i];
         rs[i] = rs[2*i+1];
      }
   }
   Int round2(Int x) {
      Int res = 1;
      while( not ( res >= x ) ) res *= 2;
      return res;
   }
   void update(Int k) {
      if( k == 0 ) return;
      if( k < n ) xs[k] = f(xs[2*k], xs[2*k+1]);
      update(k/2);
   }
   void update(Int i, T x) {
      xs[i+n] = x;
      update(i+n);
   }
   void update(Int i, std::function<T(T)> g) {
      xs[i+n] = g(xs[i+n]);
      update(i+n);
   }
   T query(Int left, Int right, Int k = 1) {
      if( right <= ls[k] or rs[k] <= left ) return e;
      if( n <= k ) return xs[k];
      if( left <= ls[k] and rs[k] <= right ) return xs[k];
      return f(query(left, right, 2*k), query(left, right, 2*k+1));
   }
};

struct Solver {
   Solver() { fprintf(stderr, "--------Solver begin--------\n"); }
   ~Solver() { fprintf(stderr, "--------Solver end--------\n"); }
   void solve() {
      Int n, q; scan(n, q);
      Solver2<Int> rmq(n, (1LL<<31)-1, [](Int x, Int y){return std::min(x,y);});
      for(Int i = 0; i < q; ++i) {
         Int a, b, c; scan(a, b, c);
         if( a == 0 ) {
            rmq.update(b, c);
         }
         if( a == 1 ) {
            fprintf(stderr, "query : [%ld, %ld)\n", b, c+1);
            printf("%ld\n", rmq.query(b, c+1));
         }
      }
   }
};

