  for (int i = 0; i < Q; i++){
    int com,x,y;
    cin >>com>> x >> y;
    if (com == 0){
      arr[x] = y;
    }else{
      SquareBucket<int> rmq(arr);
      cout << rmq.range_minimum(x, y + 1) << endl;
    }
  }
}

