const int DEPTH = 17;
const int INF = ((1LL << 31) - 1);
class Segtree {
	int value[1 << (DEPTH + 1)];
public:
	Segtree() {
		for (int i = 0; i < (1 << (DEPTH + 1)); i++) {
			value[i] = INF;
		}
	}
	void update(int pos, int x) {
		pos = (1 << DEPTH) - 1 + pos;
		value[pos] = x;
		while (pos > 0) {
			pos = (pos - 1) / 2;
			value[pos] = min(value[pos * 2 + 1], value[pos * 2 + 2]);
		}
	}
	//[l, r)
	int getMin(int l, int r, int a = 0, int b = (1 << DEPTH), int id = 0) {
		if (a >= r || b <= l) return INF;
		if (l <= a && b <= r) return value[id];
		int x = getMin(l, r, a, a + (b - a) / 2, id * 2 + 1);
		int y = getMin(l, r, a + (b - a) / 2, b, id * 2 + 2);
		return min(x, y);
	}
};

