			if(a > b)
				swap(a,b);

			if(a < 0)
				a = 0;
			if(b > N)
				b = N - 1;

			return recursion_min(1,a,b,0,N);
		}

		void update(ll a,int i){
			i += N;
			st[i] = a;

			while(i > 1){
				if(st[i] >= st[i / 2])
					break;
				st[i / 2] = st[i];
				i /= 2;
			}
		}

		~RmQ(){
