struct SegmentTree {
	int n;
	SegmentTree(int m, int v = 0) {
		for (n = 1; n < m; n *= 2);
		d.assign(n * 2, v);
	}
	void update(int i, int x) {
		d[n + i] = x;
		for (int j = (n + i) / 2; j > 0; j >>= 1)
			d[j] = min(d[j * 2], d[j * 2 + 1]);
	}
	// [l, r)
	int query(int l, int r) {
		assert(l < r);
		int mini = get(l);
		for (; l && l + (l&-l) <= r; l += l&-l)
			mini = min(mini, d[(n + l) / (l&-l)]);
		for (; l < r; r -= r&-r)
			mini = min(mini, d[(n + r) / (r&-r) - 1]);
		return mini;
	}
	int get(int i) { return d[n + i]; }
};

