// segment tree template
template< typename Monoid >
struct SegmentTree {
    using F = function< Monoid(Monoid, Monoid) >;

    int sz;
    vector<Monoid> seg;
    const F f;
    const Monoid M1;

    // init
    // n: the number of elements, f: biop [](param1, param2){ret;}
    // M: enherit of Monoid
    SegmentTree(int n, const F f, const Monoid &M1) : f(f), M1(M1) {
        sz = 1;
        while(sz < n){
            sz <<= 1;
        }
        seg.assign(2 * sz, M1);
    }

    // set(k, x)
    // substitute x in a_k
    void set(int k, const Monoid &x) {
        seg[k + sz] = x;
    }

    // build
    void build() {
        for(int k = sz - 1; k > 0; k--) {
            seg[k] = f(seg[2 * k + 0], seg[2 * k + 1]);
        }
    }

    // update(k, x)
    // update a_k
    void update(int k, const Monoid &x) {
        k += sz;
        seg[k] = x;
        while(k >>= 1) {
            seg[k] = f(seg[2 * k + 0], seg[2 * k + 1]);
        }
    }

    // find(a, b)
    // Note: range is [a, b), not [a, b] (b is NOT included)
    Monoid find(int a, int b) {
        Monoid L = M1;
        Monoid R = M1;
        for(a += sz, b += sz; a < b; a >>= 1, b >>= 1) {
            if(a & 1){
                L = f(L, seg[a++]);
            }
            if(b & 1){
                R = f(seg[--b], R);
            }
        }
        return f(L, R);
    }

    Monoid operator[](const int &k) const {
        return seg[k + sz];
    }
};

