int dx[] = { -1, 0, 1,  0 };
int dy[] = {  0, 1, 0, -1 };

typedef vector<int> vi;
typedef vector<vi> vvi;
typedef vector<double> vd;
typedef vector<vd> vvd;
typedef vector<bool> vb;

template <typename T = int>
struct RMQ {
  vector<vector<T>> seg;
  vector<int> sizes;
  int N, K;
  RMQ(const vector<T>& v) {
    N = v.size();
    K = static_cast<int>(log2(N));
    seg.resize(K + 1);
    sizes.resize(K + 1);
    seg[0] = v;
    sizes[0] = 1;
    unsigned int s = 1;
    for (int k = 1; k <= K; ++k) {
      seg[k].resize(N - s - s + 1);
      for (int x = 0; x + s + s <= N; ++x) {
        seg[k][x] = std::max<T>(seg[k-1][x], seg[k-1][x + s]);
      }
      s <<= 1;
      sizes[k] = s;
    }
  }

  T max(int i, int j) { // [ i .. j ]
    if (i >= j) return seg[0][i];
    const int m = static_cast<int>(log2(j - i + 1));
    return std::max<T>(seg[m][i], seg[m][j - sizes[m] + 1]);
  }

  void update(int i, T x) {
    seg[0][i] = x;
    int s = 1;
    vi is = { i, i-s };
    for (int k = 1; k <= K; ++k) {
      vi js;
      s <<= 1;
      for (int i: is) {
        if (i < 0 or i >= seg[k].size()) continue;
        if (i + s/2 >= seg[k-1].size()) continue;
        seg[k][i] = std::max<T>(seg[k-1][i], seg[k-1][i + s/2]);
        js.push_back(i);
        js.push_back(i-s);
      }
      is = js;
    }
  }

  void debug() {
    rep (i, seg.size()) cerr << "seg[" << i << "] = " << seg[i] << endl;
  }
};

int main() {

  int n, q; cin >> n >> q;
  vector<Integer> xs(n, -((1L<<31)-1));
  RMQ<Integer> rmq(xs);

  rep (_, q) {
    int com, x, y; cin >> com >> x >> y;
    if (com == 0) {
      rmq.update(x, -y);
    } else {
      cout << -rmq.max(x, y) << endl;
    }
  }

  return 0;
}

