const ll MAX_N=1<<20;
//セグメント木を持つグローバル配列
ll n,dat[2*MAX_N-1];
//初期化
void init(ll n_){
    //簡単のため要素数を2のべき乗に
    n=1;
    while(n<n_)n*=2;
    //全ての値をinfに
    for(ll i=0;i<2*n-1;i++)dat[i]=(1<<31)-1;
}
//k番目の値(0-indexed)をaに変更
void update(ll k,ll a){
    //葉の節点
    k+=n-1;
    dat[k]=a;
    //登りながら更新
    while(k>0){
        k=(k-1)/2;
        dat[k]=min(dat[k*2+1],dat[k*2+2]);
    }
}
//[a,b)の最小値を求める
//後ろの方の引数は、計算の簡単のための引数
//kは節点の番号、l,rはその節点が[l,r)に対応づいていることを表す。
//従って、[a,b)の最小値を求めたい時はquery(a,b,0,0,n)として呼ぶ
ll query(ll a,ll b,ll k,ll l,ll r){
    //[a,b)と[l,r)が交差しなければinf
    if(r<=a||b<=l)return inf;
    //[a,b)が[l,r)を完全に含んでいれば、この節点の値
    if(a<=l&&r<=b)return dat[k];
    else{
        //そうでなければ、2つの子の最小値
        ll vl=query(a,b,k*2+1,l,(l+r)/2);
        ll vr=query(a,b,k*2+2,(l+r)/2,r);
        return min(vl,vr);
    }
}
