template<typename T, typename U>
T Max(T arg1, U arg2) {
  T arg2T = static_cast<T>(arg2);
  if( arg1 < arg2T ) return arg2T;
  return arg1;
}

template<typename T, typename U>
T Min(T arg1, U arg2) {
  T arg2T = static_cast<T>(arg2);
  if( arg2T < arg1 ) return arg2T;
  return arg1;
}

template<typename T, u32 maxN>
class RMQ {
  static_assert(maxN == (maxN & (-maxN)), "maxN must be 2^n");
public:
  RMQ(T init_value);
  T find(u32 s, u32 t);
  void update(u32 i, T x);
private:
  T find2(u32 s, u32 t, u32 id, u32 a, u32 b);
  void update2(u32 id);  
  T data[maxN * 2];
  T init_value;
};

template<typename T, u32 maxN>
RMQ<T, maxN>::RMQ(T init_value_) {
  init_value = init_value_;
  for(u32 i = 0; i < maxN * 2; ++i) {
    data[i] = init_value;
  }
}

template<typename T, u32 maxN>
T RMQ<T, maxN>::find(u32 s, u32 t) {
  return find2(s, t + 1, 1, 0, maxN);
}

template<typename T, u32 maxN>
T RMQ<T, maxN>::find2(u32 s, u32 t, u32 id, u32 a, u32 b) {
  t = Min(t, b);
  s = Max(s, a);
  if( s == a and t == b ) return data[id];
  if( t <= a ) return init_value;
  if( b <= s ) return init_value;
  u32 m = (a + b) / 2;
  T min_left  = find2(s, t, id * 2    , a, m);
  T min_right = find2(s, t, id * 2 + 1, m, b);
  return Min(min_left, min_right);  
}

template<typename T, u32 maxN>
void RMQ<T, maxN>::update(u32 i, T x) {
  data[i + maxN] = x;
  update2((i + maxN) >> 1);
}

template<typename T, u32 maxN>
void RMQ<T, maxN>::update2(u32 id) {
  if( id == 0 ) return;
  data[id] = Min(data[id * 2], data[id * 2 + 1]);
  update2(id >> 1);
}

