#include <bits/stdc++.h>
using namespace std;

typedef long long int ll;
ll INF = (1ll << 31) - 1;

struct SegmentTree {
 private:
  int n;  // 最下段のノード数
  vector<int> node;

 public:
  SegmentTree(vector<int> v) {
    int sz = v.size();
    n = 1;
    while (n < sz) n *= 2;
    node.resize(2 * n - 1, INF);

    // 最下段に突っ込む
    for (int i = 0; i < sz; i++) node[(n - 1) + i] = v[i];

    // 最下段以外を更新していく
    for (int i = n - 2; i >= 0; i--) {
      node[i] = min(node[i * 2 + 1], node[i * 2 + 2]);
    }
  }

  // i番目の要素をvalに変更する
  void update(int i, int val) {
    // まず最下段(2n-1)を変更する
    i += n - 1;
    node[i] = val;

    // 上に行きながら更新していく
    while (i > 0) {
      i = (i - 1) / 2;  // 親へ
      node[i] = min(node[2 * i + 1], node[2 * i + 2]);
    }
  }

  // [a,b) 中の最小値を返す。[l,r)は対称区間の左端と右端。
  int getmin(int a, int b, int now = 0, int l = 0, int r = -1) {
    // 初期化
    if (r < 0) r = n;

    // 俺は関係ないとき -> 答えの邪魔にならない値を返す
    if (r <= a || b <= l) return INF;

    // 要求区間の中にノードがすっぽり入ってる → 計算候補として返す
    if (a <= l && r <= b) return node[now];

    // ノードの一部分だけ要求区間に入ってる → 子を再帰的に探索する
    int vl = getmin(a, b, 2 * now + 1, l, (l + r) / 2);  // 子(左)
    int vr = getmin(a, b, 2 * now + 2, (l + r) / 2, r);  // 子(右)
    return min(vl, vr);
  }
};

// ============================================================

int main() {
  int n, q;
  cin >> n >> q;

  vector<int> v(n, INF);
  SegmentTree seg(v);

  int c, x, y;
  for (int i = 0; i < q; i++) {
    cin >> c >> x >> y;
    if (c == 0) {
      seg.update(x, y);
    } else {
      cout << seg.getmin(x, y + 1) << endl;  // 半開区間なので
    }
  }
}

