int main()
{
    lint n, q;
    scanf("%lld %lld\n", &n, &q);
    const lint init_value = (lint)((lint)1 << (lint)31) - (lint)1;
    lint b_num = floor(sqrt(n));
    lint b_size = n / b_num;
    vector<lint> a(n);
    vector<lint> b(b_num);
    for (int i=0; i<n; ++i){
        a[i] = init_value;
    }
    for (int i=0; i<b_num; ++i){
        b[i] = init_value;
    }
    lint com, x, y;
    lint b_l, b_r, backet_num;
    for (int query=0; query<q; ++query){
        scanf("%lld %lld\n", &com, &x, &y);
        // update
        if(com == 0){
            a[x] = y;
            lint b_n = x / b_size;
            if(b_n < b_num){
                b[b_n] = a[b_n*b_size];
                for (int i=b_n*b_size+1; i<(b_n+1)*b_size; ++i){
                    b[b_n] = min(b.at(b_n), a.at(i));
                }
            }
        }
        // find
        else {
            lint itr = x;
            backet_num = itr / b_size;
            b_l = backet_num * b_size;
            b_r = min(n - 1, b_l + b_size - 1);
            lint query_ans = LINF;
            while(x <= itr && itr <= y){
                if(backet_num < b_num && x <= b_l && b_r <= y){
                    query_ans = min(query_ans, b.at(backet_num));
                    backet_num++;
                    b_l = backet_num * b_size;
                    b_r = min(n - 1, b_l + b_size - 1);
                }
                else {
                    query_ans = min(query_ans, a.at(itr));
                    itr++;
                    backet_num = itr / b_size;
                    b_l = backet_num * b_size;
                    b_r = min(n - 1, b_l + b_size - 1);
                }
            }
            printf("%lld\n", query_ans);
        }
        // debug
        /*
        cout << "query: " << query << endl;
