class cRMQ
{
	int max = 100000;
	int m_n;
	vector<int> va;
public:
	cRMQ(int n);
	void update(int i, int x);
	int find(int s, int t);
	int find(int s, int t, int k, int l, int r);
	void print()
	{
		for(int i = 0; i < m_n; ++i)
		{
			cout << va[i];
		}
		cout << "\n";
	}
};

cRMQ::cRMQ(int n)
{
	m_n = 1;
	while (m_n < n) m_n *= 2;
	va.resize(max);
	for(int i = 0; i < 2 * m_n - 1; ++i)
		va[i] = infty;
}

void cRMQ::update(int k, int x)
{
	k += m_n - 1;
	va[k] = x;
	while(k > 0)
	{
		k = (k - 1) / 2;
		va[k] = min(va[k * 2 + 1], va[k * 2 + 2]);
	}
}
int cRMQ::find(int s, int t)
{
	return find(s, t, 0, 0, m_n);
}
int cRMQ::find(int s, int t, int k, int l, int r)
{
	if (r <= s || t <= l)return infty;
	if (s <= l && r <= t)return va[k];
	int m = (l + r) / 2;
	return min(find(s, t, k * 2 + 1, l, m), find(s, t, k * 2 + 2, m, r));
}

