typedef long long int LL;

const LL inf = (1LL << 31) - 1;

class RMQ
{
private:
	LL n;
	std::vector<LL>dat;

public:
	void init(LL n_)
	{
		n = 1;
		while (n < n_) n *= 2;
		dat.resize(2 * n - 1, inf);
	}

	void update(LL k, LL x)
	{
		k += n - 1;
		dat[k] = x;
		while (k > 0)
		{
			k = (k - 1) / 2;
			dat[k] = std::min(dat[2 * k + 1], dat[2 * k + 2]);
		}
	}

	// [a, b)
	LL get_min(LL a, LL b, LL k = 0, LL l = 0, LL r = -1)
	{
		if (r < 0) r = n;
		if (b <= l || r <= a) return inf;
		if (a <= l && r <= b) return dat[k];
		LL vl = get_min(a, b, k * 2 + 1, l, (l + r) / 2);
		LL vr = get_min(a, b, k * 2 + 2, (l + r) / 2, r);
		return std::min(vl, vr);
	}
};

