template<typename T>
struct SegmentTree {
	private:
        using Func = function<T(T, T)>;

        int n;
        vector<T> node;

        T init_v;
        Func func;

    public:

        SegmentTree(vector<T> a, Func _func, T _init_v) {
            int sz = a.size();
            n = 1;
            init_v = _init_v;
            func = _func;

            while (n < sz) n <<= 1;
            node.resize(2 * n - 1, init_v);
            for (int i = 0; i < sz; i++) node[i + n - 1] = a[i];
            for (int i = n - 2; i >= 0; i--) node[i] = func(node[i * 2 + 1], node[i * 2 + 2]);
        }

        void update(int pos, T v) {
            int k = pos + n - 1;
            node[k] = v;
            while (k > 0) {
                k = (k - 1) / 2;
                node[k] = func(node[k * 2 + 1], node[k * 2 + 2]);
            }
        }

        T get(int pos) {
            int k = pos + n - 1;
            return node[k];
        }

        T query(int a, int b, int k = 0, int l = 0, int r = -1) {
            if (r < 0) r = n;
            if (r <= a || b <= l) return init_v;
            if (a <= l && r <= b) return node[k];
            T lv = query(a, b, k * 2 + 1, l, (l + r) / 2);
            T rv = query(a, b, k * 2 + 2, (l + r) / 2, r);
            return func(lv, rv);
        }

        int size(){
            return n;
        }
};

int func(int a, int b){
    return min(a,b);
}

int main(void){
    int n,q; cin >> n >> q;
    vector<int> a(n, INT_INF);

    SegmentTree<int> st(a, func, INT_INF);
    REP(i,q){
        int c,x,y; cin >> c >> x >> y;
        if(c)  cout << st.query(x,y+1, 0, 0, st.size()) << endl;
        else st.update(x, y);
    }
    return 0;
}

