//http://tsutaj.hatenablog.com/entry/2017/03/29/204841
struct SegmentTree{//SegmentTree seg(vec) のように宣言する
    int n;
    vector<int> dat;

    //元配列vをセグメント木で表現する
    SegmentTree(vector<int> vec){
        int siz = vec.size();
        n = 1;
        while(n < siz) n *= 2;
        dat.resize(2 * n - 1, INF);
        for(int i = 0; i < siz; i++) dat[i + n - 1] = vec[i];//最下段に値をいれる
        for(int i = n - 2; i >= 0; i--) dat[i] = min(dat[2 * i + 1], dat[2 * i + 2]);//下の段から順番に値をいれる
    }

    void update(int k, int val){
        //最下段のノードにアクセスする
        k += (n - 1);
        //最下段のノードを更新したら、下の段から順番に値をいれる
        dat[k] = val;
        while(k > 0){
            k = (k - 1) / 2;
            dat[k] = min(dat[2 * k + 1], dat[2 * k + 2]);
        }
    }

    int query(int a, int b, int k = 0, int l = 0, int r = -1){
        //最初に呼び出されたときの対象区間は[0, n)
        if(r < 0) r = n;
        //要求区間と対象区間が交わらなければ、INF
        if(r <= a || b <= l) return INF;
        //要求区間が対象区間を完全に含んでいれば、対象区間を答えの計算に使う
        if(a <= l && r <= b) return dat[k];
        //要求区間が対象区間の一部を含んでいれば、
        int vl = query(a, b, 2 * k + 1, l, (l + r) / 2);
        int vr = query(a, b, 2 * k + 2, (l + r) / 2, r);
        return min(vl, vr);
    }
};

