#define len (1<<18)
vl seg(len*2,2147483647);

void update(ll ind,ll x){
	ind+=len;
	seg[ind]=x;
	while(true){
		ind/=2;
		if(ind==0)break;
		seg[ind]=min(seg[ind*2],seg[ind*2+1]);
	}
}

int RMQ(ll l,ll r){
	ll ans=2147483647;
	l+=len; r+=len;
	while(l<r){
		if(l%2==1){
			chmin(ans,seg[l]);
			l++;
		}
		l/=2;
		if(r%2==1){
			chmin(ans,seg[r-1]);
			--r;
		}
		r/=2;
	}
	return ans;
}

