// Binary heap structure.
int *H;  // H[1], H[2], ... , H[n], H[n+1], H[n+2], ... , H[2n].

// keep on condition: H[x] = min(H[2x], H[2x+1]). O(log(n)).
void update(int x, int y, int n)
{
    x++;
    for(x += n, H[x] = y; x > 1; x >>= 1) // x >>= 1 means x /= 2.
        H[x >> 1] = min(H[x], H[x ^ 1]);  // x ^ 1: x = 2m then x + 1, x = 2m + 1 then x - 1.
    return;
}

// binary search. O(log(n)). very fast.
int find(int x, int y, int n)
{
    int least = INT_MAX; // x, y starts from leaf, usually.
    x++; y++;
    for(x += n, y += n; x <= y; x = ((x + 1) >> 1), y = ((y - 1) >> 1)){
        if(x & 1){ least = min(least, H[x]); }
        if(!(y & 1)){ least = min(least, H[y]); }
    }
    return least;
}

int main()
{
    H = new int [1 << 18];
    int n, q;
    scanf("%d %d", &n, &q);
    int cmd, x, y;

    fill(H, H + 2 * n + 1, INT_MAX);

    while(q){
        scanf("%d %d %d", &cmd, &x, &y);
        if(cmd){
            printf("%d\n", find(x, y, n));
        }else{
            update(x, y, n);
        }
        q--;
    };
    delete [] H;
    return 0;
}

