const int Interval = 512;
struct SqrtDecomp{
  typedef long long Type;
  const int n;
  vector<Type> arr,buc;
  const Type ide;

  Type func(Type a,Type b){
    return min(a,b);
  }

  Type update_func(Type a,Type x){
    return x;
  }

  SqrtDecomp(const vector<Type>& init,const Type& ide_) : n(init.size()),ide(ide_),arr(init),buc(init.size() / Interval + 1,ide){
    for(int i = 0;i < n;i++){
      buc[i / Interval] = func(buc[i / Interval],arr[i]);
    }
  }

  Type get_inter(int l,int r){
    Type res = ide;
    while(l < r){
      if(l % Interval == 0 && l + Interval <= r){
        res = func(res , buc[l / Interval]);
        l += Interval;
      }
      else{
        res = func(res , arr[l]);
        l++;
      }
    }
    return res;
  }

  void update(int idx,const Type& x){
    arr[idx] = update_func(arr[idx] , x);
    buc[idx / Interval] = ide;
    int start = idx - idx % Interval;
    int end = start + Interval;
    for(int i = start;i < end;i++){
      buc[idx / Interval] = func(buc[idx / Interval],arr[i]);
    }
  }
};
