// 半開区間で与えられる
int find(int l, int r){
    l += SEG_LEN;
    r += SEG_LEN;
    int ret = INF;

    while (l < r ){
        if (l%2 == 1){
            chmin(ret, seg[l]);
            l++;
        }
        l /= 2;

        if (r%2 == 1){
            chmin(ret, seg[r-1]);
            r--;
        }
        r /= 2;
    }
    return ret;
}

int sum(int l, int r){
    l += SEG_LEN;
    r += SEG_LEN;
    int ret = 0;
    while (l < r){
        if (l%2 == 1){
            ret += seg[l];
            l++;
        }
        l /= 2;

        if (r%2 == 1){
            ret += seg[r-1];
            r--;
        }
        r /= 2;
    }
    return ret;
}


