#include<cstdio>
#include<algorithm>
#define N 100000
#define MAX (1<<31)-1
using namespace std;
int A[N], T[4*N];

void build(int l, int r, int k) {
    if (l == r) {
        T[k] = A[l];
        return;
    }
    int mid = (l + r) / 2;
    build(l, mid, k * 2);
    build(mid + 1, r, k * 2 + 1);
    T[k] = min(T[2 * k], T[2 * k + 1]);
}
void updata(int in, int data ,int l, int r ,int k) {
    if (l == r) {
        A[l] = T[k] = data;
        return;
    }
    int mid = (l + r) / 2;
    if (in <= mid) updata(in, data, l, mid, k * 2);
    else updata(in, data, mid + 1, r, k * 2 + 1);
    T[k] = min(T[2 * k], T[2 * k + 1]);
}
int find(int L, int R, int l, int r, int k) {
    if (L <= l && r <= R) return T[k];
    int mid = (l + r) / 2;
    int ans = MAX;
    if (mid >= L) ans = min(ans, find(L, R, l, mid, k * 2));
    if (mid < R) ans = min(ans, find(L, R, mid + 1, r, k * 2 + 1));
    return ans;
}
int main() {
    int n, q;
    scanf("%d%d", &n, &q);
    for (int i = 0; i < n; i++)
        A[i] = MAX;
    build(0, n - 1, 1);
    int com, x, y;
    while (q--) {
        scanf("%d%d%d", &com, &x, &y);
        if (com == 0) updata(x, y, 0, n - 1, 1);
        else printf("%d\n", find(x, y, 0, n - 1, 1));
    }
    return 0;
}

