template<class T>
class sg_tree : public vector<T>{
    private:
    lli n;
    T default_value;
    T _query(lli a,lli b,lli k,lli l,lli r){
        if(r <= a || b <= l) return default_value;
        if(a <= l && r <= b) return (*this)[k];
        else {
            T vl = _query(a,b,k*2+1,l,(l+r)/2);
            T vr = _query(a,b,k*2+2,(l+r)/2,r);
            return func(vl,vr);
        }
    }
    public:
    sg_tree():vector<T>(){

    }
    sg_tree(lli n,T d = (1ll << 31) - 1):vector<T>(n*4,d){
		this->n = 1;
        while(n > this->n) this->n <<= 1;
        this->default_value = d;
    }
    void update(lli i,lli x){
        i += n - 1;
        (*this)[i] = x;
        while(i > 0){
            i = (i - 1) / 2;
            (*this)[i] = func((*this)[i * 2 + 1],(*this)[i * 2 + 2]);
        }

    }
    T query(lli a,lli b){
        return _query(a,b,0,0,n);
    }
    T func(T a,T b){
        return min(a,b);
    }
};

