  static const int MAX_N = 1 << 17;
  int n, dat[2 * MAX_N - 1];
  RMQ(int n_) { init(n_); }

  void init(int n_) {
    n = 1;
    while (n < n_) n *= 2;
    REP(i, 2 * n - 1) dat[i] = INT_MAX;
  }

  void update(int k, int a) {
    k += n - 1;
    dat[k] = a;
    while (0 < k) {
