      node[i]=min(node[i*2+1],node[i*2+2]);
    }

  }

  Segtree(int n){
    init(n);
  }

  void update(int k,int x){
    k+=n-1;
    node[k]=x;
    while(k>0){
      k=(k-1)/2;
      node[k]=min(node[k*2+1],node[k*2+2]);
    }
    //cout<<endl;
