    if(r<=a || l>=b)
      return INF;
    if(l<=a&&b<=r)
      return node[k];

      int left=query(a,(a+b)/2,l,r,k*2+1);
      int right=query((a+b)/2,b,l,r,k*2+2);

      return min(left,right);
  }

  int find(int l,int r){
    return query(0,n,l,r,0);
  }

};

