template<typename T, int MAX_N>
struct segment_tree_min {
    int N;
    T arr[MAX_N << 1]; // loose

    segment_tree_min(int n, T INF) {
        N = 1;
        while (N < n) N *= 2;

        for (int i = 0; i < N; ++i) {
            arr[i] = INF;
        }
    }

    void update(int i, T v) {
        int j = i + N-1;

        arr[j] = v;
        while (j > 0) {
            j = (j-1) / 2;
            arr[j] = min(arr[2*j+1], arr[2*j+2]);
        }
    }

    T query(int a, int b) {
        return query(a, b, 0, 0, N);
    }

    T query(int a, int b, int k, int l, int r) {
        if (b <= l || r <= a) return INF;
        if (a <= l && r <= b) return arr[k];

        int m = (l+r)/2;
        return min(query(a, b, 2*k+1, l, m), query(a, b, 2*k+2, m, r));
    }
};

