const intt init = (1 << 31) - 1;

intt n, q;
intt t[maxx << 2];

void build (intt v, intt l, intt r) {
    if (l == r) {
        t[v] = init;
        return;
    }
    intt mid = (l + r) >> 1;
    build (v << 1, l, mid);
    build (v << 1 | 1, mid + 1, r);
    t[v] = min (t[v << 1], t[v << 1 | 1]);
}

void update (intt v, intt l, intt r, intt i, intt val) {
    if (i < l || i > r)
        return;
    if (l == r) {
        t[v] = val;
        return;
    }
    intt mid = (l + r) >> 1;
    update (v << 1, l, mid, i, val);
    update (v << 1 | 1, mid + 1, r, i, val);
    t[v] = min (t[v << 1], t[v << 1 | 1]);
}

intt query (intt v, intt l, intt r, intt i, intt j) {
    if (j < l || i > r)
        return init;
    if (i <= l && r <= j)
        return t[v];
    intt mid = (l + r) >> 1;
    return min (query (v << 1, l, mid, i, j), query (v << 1 | 1, mid + 1, r, i, j));
}

