const int MAX_N = 1 << 20;

//葉の数
int N;
//扱うデータ型をllとしている.適宜修正.
ll dat[2 * MAX_N - 1];

void init(int n_){
	//簡単のため, 要素数を2のべき乗に
	N = 1;
	while(N < n_) N *= 2;

	//初期化処理をここに書く
	rep(i,2 * N - 1){
		dat[i] = LINF;
	}
}

//k番目の値について, 処理を行う
//例として, aに変更している
void update(int k, int a){
	//葉のノード番号
	k += N-1;

	//葉の更新処理をここに書く.
	dat[k] = a;

	//登りながら更新.
	while(k > 0){
		k = (k-1) / 2;
		//中間ノードの更新処理をここに書く.
		dat[k] = min(dat[k * 2 + 1], dat[k * 2 + 2]);
	}

	return;
}

//[a,b)における評価値を得る. ここでは最小値としている.
//nowが現在の接点番号, nowは[l, r)に対応している.
//呼ぶ時は query(a,b,0,0,N)
ll query(int a, int b, int now, int l, int r){
	//[a,b)と[l,r)が交差しなければ, 無を返す.
	//評価値が最小値ならばINT_MAX. 修正すること.
	if(r <= a || b <= l) return LINF;

	// [a, b)が[l, r)を完全に含んでいれば, このノードの値
	if(a <= l && r <= b){
		return dat[now];
	}else{
		//そうでなければ, 2つの個の複合値
		//ここでは, 2つの子の最小値. 修正すること.
		ll vl = query(a, b, now*2+1, l, (l+r)/2);
		ll vr = query(a, b, now*2+2, (l+r)/2, r);
		return min(vl, vr);
	}
}

int main(void){
	int n,q;cin>>n>>q;
	init(n);
	rep(i,q){
		ll com,x,y;
		cin>>com>>x>>y;
		if(com == 0){
			update(x, y);
		}else{
			cout<<query(x, y+1, 0, 0, N)<<endl;
		}
	}
	return 0;
}

