#include <iostream>
#include <vector>
#include <functional>
using namespace std;
const int INF = 2147483647;

template<class M> struct SegmentTree
{
	// 要素数
	int n;
	// 扱いたい大きさ(要素数)より大きい2冪として持つ
	int size;
	// tree 本体に乗っている値．2*size のノードを持つ．
	// data[1] を root として data[0] は使用しない
	vector<M> data;
	// モノイド上の演算
	const function<M(M, M)> op;
	// 単位元
	const M ID;

	// n は要素の数．init_vals の size は n 以下であること（足りない分は単位元で初期化される）
	SegmentTree(int n, function<M(M, M)> op, M id, const vector<M> &init_vals=vector<M>()) : n(n), op(op), ID(id) {
		size = 1;
		while (size < n) size <<= 1;
		data.assign(size * 2, ID);
		for (int i = 0; i < init_vals.size(); i++) data[size+i] = init_vals[i];
		for (int i = size-1; i > 0; i--) data[i] = op(data[2*i], data[2*i+1]);
	}

	// idx 番目の要素を x に変更
	// O( log(size) )
	void update(int idx, M x) {
		idx += size;
		data[idx] = x;
		// 親のノードたちも更新
		while (idx /= 2) {
			data[idx] = op(data[2*idx], data[2*idx+1]);
		}
	}

	// 区間 [l,r) で演算した結果を返す
	// O( log(size) )
	M query(int l, int r) {
		M L = ID, R = ID;
		for (l += size, r += size; l < r; l /= 2, r /= 2) {
			if (l & 1) L = op(L, data[l]), l++;
			if (r & 1) r--, R = op(data[r], R);
		}
		return op(L, R);
