template<class T,class F,class G>
inline void prseg<T,F,G>::put(int num,T val){
	num+=node;
	dat[num]=appg(val,dat[num]);
	int h=num<(1<<hgt)-1?hgt-1:hgt;
	for(int i=0;i<h;++i){
		num=(num-1)/2;
		dat[num]=appf(dat[num*2+1],dat[num*2+2]);
	}
	return;
}
template<class T,class F,class G>
inline T prseg<T,F,G>::get(int first,int last){
	first+=node;
	last+=node;
	T x=id;
	while(first<last){
		if(!(first&1)) x=appf(dat[first],x);
		if(!(last&1)) x=appf(dat[--last],x);
		first/=2;
		last/=2;
	}
	return x;
}
template<class T,class F,class G>
inline void prseg<T,F,G>::set(int num,T val){
	dat[num+node]=val;
