    void update(ll x, ll val) {

        x += (n - 1); 
        node[x] = val; 
        while(x > 0) { 
            x = (x - 1) / 2;
            node[x] = min(node[2*x+1],node[2*x+2]); 
        }
    }

    ll getor(ll a, ll b, ll k=0, ll l=0, ll r=-1) {

        if(r < 0) r = n; 
        if(r <= a || b <= l) return INF; 
        if(a <= l && r <= b) return node[k];


        ll vl = getor(a, b, 2*k+1, l, (l+r)/2);

        ll vr = getor(a, b, 2*k+2, (l+r)/2, r);

        return min(vl,vr); 
    }
};

