template<class T>
class SegTree{
	int n;                       //葉の数
	vector<T> data;              //格納するデータ
	T def;                       //単位元
	function<T(T, T)> operation; //区間クエリで使う処理
	function<T(T, T)> update;    //点更新で使う処理

	//区間[a, b)の総和
	T _query(int a, int b, int k, int l, int r){
		if(r <= a || b <= l)return def;
		if(a <= l && r <= b)return data[k];
		T c1 = _query(a, b, 2 * k + 1, l, (l + r) / 2);
		T c2 = _query(a, b, 2 * k + 2, (l + r) / 2, r);
		return operation(c1, c2);
	}
public:

	//_n : 要素数, _def : 単位元, _operation : クエリ関数, _update : 更新関数
	SegTree(int _n, T _def, function<T(T,T)> _operation, function<T(T,T)> _update) : def(_def), operation(_operation), update(_update){
			n = 1;
			while(n < _n)n *= 2;
			data = vector<T> (2 * n - 1, def);
	}

	//[a, b)の区間クエリを実行
   T query(int a, int b){
		return _query(a, b, 0, 0, n);
	}

	void change(int i, T x){
		i += n - 1;
		data[i] = update(data[i], x);
		while(i  > 0){
			i = (i - 1) / 2;
			data[i] = operation(data[i * 2 + 1], data[i * 2 + 2]);
		}
	}

	T operator[] (int i){
		return data[i + n - 1];
	}
};

//_n : 要素数, _def : 単位元, _operation : クエリ関数, _update : 更新関数

int main()
{
	ll n, q;
	cin >> n >> q;
