class ST_RMinQ
{
public:
    int n;
    vector<int> dat;

    // 管理する数列のsizeを与える
    // 内部では2の冪の配列で管理
    ST_RMinQ(int size) {
        n = 1;
        while (n < size) {
            n *= 2;
        }

        dat.resize(2 * n - 1);

        // 全ての値をINT_MAXで初期化
        for (size_t i = 0; i < 2 * n - 1; i++)
        {
            dat[i] = INT_MAX;
        }
    }

    // k番目(0-indexed)の値をaに変更
    void update(int k, int a) {
        k += n - 1;     // n-1を足すとセグメント木の一番下の節点を表すインデックスになる
        dat[k] = a;
        // 登りながら更新
        while (k > 0) {
            k = (k - 1) / 2;
            dat[k] = min(dat[k * 2 + 1], dat[k * 2 + 2]);
        }
    }   

    // [a, b)の区間(0-indexed)の最小値を求める
    int query(int a, int b) {
        return query_sub(a, b, 0, 0, n);
    }

private:

    // [a, b)の最小値を求める
    // 後ろの引数は簡単のための引数
    // kは節点番号、l,rはその節点が[l, r)に対応していることを表す
    int query_sub(int a, int b, int k, int l, int r) {
        if (r <= a || b <= l) {
            return INT_MAX;
        }

        // [a, b)が[l, r)を完全に含んでいればその値
        if (a <= l && r <= b) {
            return dat[k];
        } else {
            // そうでなければ、2つの子の最小値
            int vl = query_sub(a, b, k * 2 + 1, l, (l + r) / 2);
            int vr = query_sub(a, b, k * 2 + 2, (l + r) / 2, r);
            return min(vl, vr);
        }
    }
};

