    typedef ll T;
    static const T init = -((1ll << 31) - 1);

public:
    class Node {
        unique_ptr<Node> childlen[2];
    public:
        const ll begin;
        const ll end;
        T val;
        Node(ll b, ll e) :begin(b), end(e), val(init) {  }

        inline ll center() const {return (begin + end) / 2;
        }

        // Node????????°??????????????????????????????
        inline bool cover(ll be, ll en) const {
            return begin <= be && en <= end;
        }
        // Node????????°?????????????????????
        inline bool cover(ll i) const {
            return begin <= i && i <= end;
        }
        // Node????????°????????????????????????????????????
        inline bool covered_by(ll be, ll en) const {
            return be <= begin && end <= en;
        }

        // ??????????????????
        inline Node& child(int idx) {
            if (!childlen[idx]) {
                if (idx == 0)
                    childlen[idx].reset(new Node(begin, center()));
                else
                    childlen[idx].reset(new Node(center(), end));
            }
            return *childlen[idx];
        }

        inline Node& nextnode(ll i) {
            return child((begin + end) / 2 <= i);
        }
    };
private:
    inline void updatenode(Node& node) {
        // if (node.end - node.begin <= 1)return;
        node.val = max(node.child(0).val, node.child(1).val);
    }
public:

    Node root;

    segtree_sparse(ll begin, ll end) :root(begin, end) {}

    const Node& getmaxrange(ll begin, ll end, Node& node) const {
        if (node.covered_by(begin, end))
            return node;
        if (node.center() <= begin)
            return getmaxrange(begin, end, node.child(1));
        if (end <= node.center())
            return getmaxrange(begin, end, node.child(0));

        const Node& left = getmaxrange(begin, end, node.child(1));
        const Node& right = getmaxrange(begin, end, node.child(0));
        return (left.val < right.val) ? right : left;
    }
    const Node& getmaxrange(ll begin, ll end) {
        return getmaxrange(begin, end, root);
    }

    const Node& setval(ll idx, T val, Node& node) {
        if (node.begin != idx || node.end != idx+1) {
            auto& term = setval(idx, val, node.nextnode(idx));
            updatenode(node);
            return term;
        }
        node.val = val;
        return node;
    }

    const Node& setval(ll idx, T val) {
        return setval(idx, val, root);
    }

};



