class SegmentTree {
private:
	int sequence_size_{1};
	std::vector<int> container_;
	int find_impl_(int, int, int, int, int);
	int update_impl_(int, int, int, int, int);
public:
	SegmentTree(int);
	void update(int, int);
	int find(int, int);
};

SegmentTree::SegmentTree(int n)
{
	// 要素数は簡単のために2べきで
	while (sequence_size_ < n) sequence_size_ <<= 1;
	// 根ノード:0
	// 内部ノード:[1, sequence_size - 1)
	// 葉ノード（数列要素）:[sequence_size - 1, 2 * sequence_size - 1)
	container_.resize(2 * sequence_size_ - 1, ((long long)1 << 31) - 1);
}

// 数列のplaceの場所をkeyに変える
int SegmentTree::update_impl_(int place, int key, int index, int node_left, int node_right)
{
	// 葉ノードならただ更新してその値を返す
	// 範囲に入ってたらその範囲で再帰して範囲の最小値を返す
	// 範囲に入ってたらそのまま値を返す
	if (node_left + 1 == node_right && node_left == place)
		container_[index] = key;
	else if (node_left <= place && place < node_right)
	{
		int mid{(node_left + node_right) / 2};
		int left_min{this->update_impl_(place, key, 2 * index + 1, node_left, mid)};
		int right_min{this->update_impl_(place, key, 2 * index + 2, mid, node_right)};
		container_[index] = std::min(left_min, right_min);
	}
	return container_[index];
}

void SegmentTree::update(int place, int key)
{
	this->update_impl_(place, key, 0, 0, this->sequence_size_);
}

// 入力範囲[left, right)に対する最小値を探す
// 注目しているノードindexの範囲は[node_left, node_right)
int SegmentTree::find_impl_(int left, int right, int index, int node_left, int node_right)
{
	if (left + 1 ==  right) return container_[index];
	if (node_right <= left || right <= node_left) return ((long long)1 << 31) - 1;
	if (left <= node_left && node_right <= right)
		return container_[index];

	int mid{(node_left + node_right) / 2};
	int left_min{this->find_impl_(left, right, 2 * index + 1, node_left, mid)};
	int right_min{this->find_impl_(left, right, 2 * index + 2, mid, node_right)};
	return std::min(left_min, right_min);
}

int SegmentTree::find(int left, int right)
{
	return this->find_impl_(left, right, 0, 0, this->sequence_size_);
}

