// intersects returns whether [a1, b1) \cap [a2, b2) is nonempty
bool intersects(int a1, int b1, int a2, int b2) {
  return ((a2 >= a1 and a2 < b1) or (a1 >= a2 and a1 < b2));
}

struct Seg {
  int start;
  int end;
  int x;
  Seg *l;
  Seg *r;
  Seg(int start, int end, int x) : start(start), end(end), x(x) {
    if (end > start + 1) {
      l = new Seg(start, (start + end) / 2, x);
      r = new Seg((start + end) / 2, end, x);
    }
  }
  int Get(int s, int t) {
    if (s <= start and t >= end) {
      return x;
    } else if (intersects(s, t, l->start, l->end) and
               intersects(s, t, r->start, r->end)) {
      return min(l->Get(s, t), r->Get(s, t));
    } else if (intersects(s, t, l->start, l->end)) {
      return l->Get(s, t);
    } else { // intersects right interval
      return r->Get(s, t);
    }
  }
  void Set(int i, int new_x) { // 1-indexed
    if (start == end - 1) {
      x = new_x;
      return;
    }
    (i < l->end ? l : r)->Set(i, new_x);
    x = min(l->x, r->x);
  }
};

int main() {
  int n, q;
  cin >> n >> q;
  auto seg = new Seg(1, n + 1, numeric_limits<int>::max());
  int c, x, y;
  while (cin >> c >> x >> y) {
    if (c == 0)
      seg->Set(x + 1, y); // internal repr. is 1-indexed
    if (c == 1)
      cout << seg->Get(x + 1, y + 2) << endl; // and uses open intervals
  }
}

