string longestCommonPrefix(vector<string>& strs) {
    int n = INT_MAX;
    if (strs.size() <= 0) {
        return "";
    }
    if (strs.size() == 1) {
        return strs[0];
    }
    // get the min length
    for (int i = 0; i < strs.size(); i ++) {
        n = strs[i].length() < n ? strs[i].length() : n ;
    }
    for (int i = 0; i < n; i ++) { // check each character
        for (int j = 1; j < strs.size(); j ++) {
            if (strs[j][i] != strs[j - 1][i]) { // we find a mis-match
                return strs[0].substr(0, i);
            }
        }
    }
    // prefix is n-length
    return strs[0].substr(0, n);
}

namespace PrimeLib {
	//* 素数判定 is_prime<unsigned>(N)
	template<typename T, std::enable_if_t<std::is_unsigned<T>::value, std::nullptr_t> = nullptr>
	bool is_prime(const T n) {
		if (n < 4) return n == 2 || n == 3;
		if (n % 2 == 0 || n % 3 == 0 || (n % 6 != 1 && n % 6 != 5)) return false;
		for (T i = 5; i * i <= n; i += 6) if (n % i == 0 || n % (i + 2) == 0) return false;
		return true;
	}
	//* 素数テーブル生成　エラトステネスの篩 10^7 => 1s
	//* 1e9を素因数分解したい時，sqrt(1e9)まで(31623程)を生成すればよい
	vector<ll> primeTable(ll n) {
		vector<bool> table(n - 1);
		vector<ll> ret;
		for (ll i = 0; i < n - 1; ++i) {
			if (table[i] == false) {
				ll num = i + 2;
				ret.push_back(i + 2);
				for (int j = i + num; j < n - 1; j += num)
					table[j] = true;	
			}
		}
		return ret;
	}
	vector<ll> factorize(ll n, vector<ll> &pt) {
		vector<ll> ret;
		int pos = 0;
		ll c = n;
		while (c != 1) {
			ll p = pt[pos];
			ret.push_back(0);
			while (c % p == 0) {
				ret[pos]++;
				c /= p;
			}
			pos++; if (pos >= pt.size()) break;
		}
		//assert(c == 1);
		// if c is still not 1, 
		// there's one prime num bigger than sqrt(N)
		if (c != 1 ) ret.push_back(1);
		return ret;
	}
}

