	}

	void makeTree(int r) {
		root = r;
		p = make_v<int>(size);
		p[root] = -1;
		mtdfs(root);
		auto idxs = make_v<int>(size);
		iota(all(idxs), 0);
		leaf_idx = set<int>(all(idxs));
		FOR(i, 1, size)
			leaf_idx.erase(p[i]);
	}

	void makeEulerTour() {
		assert(root >= 0);
		et_begin = make_v<int>(size);
		et_end = make_v<int>(size);
		tmp_k = 0;
		etdfs(root, -1);
	}

	int size, root;
	vector<int> p; // parent for each node. parent of root = -1
	vector<int> euler_tour;
	vector<int> et_begin, et_end;
	set<int> leaf_idx;

	int tmp_k;
private:	
	void mtdfs(int c) {
		REP(i, to[c].size()) {
			int next = to[c][i];
			if (p[c] == next) continue;
			p[next] = c;
			mtdfs(next);
		}
	}
	void etdfs(int vidx, int pidx) {
		et_begin[vidx] = tmp_k;
		euler_tour.push_back(vidx);
		tmp_k++;
		REP(i, to[vidx].size()) {
			if (to[vidx][i] != pidx) {
				etdfs(to[vidx][i], vidx);
				euler_tour.push_back(vidx);
				tmp_k++;
			}
		}
		et_end[vidx] = tmp_k;
	}
};

class RangeMinimumQuery {
public:
	int size;
	vector<ll> seg;

	RangeMinimumQuery(int s, ll initial_value = INT64_MAX) {
		size = 1;
		while (size < s)
			size <<= 1;
		seg = make_v<ll>(2 * size);
		fill_v(seg, initial_value);
	}

	void update(int idx, ll value) {
		idx += size-1;
		seg[idx] = value;
		while (idx) {
			idx = (idx - 1) / 2;
			int lcidx = idx * 2 + 1;
			seg[idx] = min(seg[lcidx], seg[lcidx + 1]);
		}
	}

	// [l, r) , include v[l], not include v[r]
	ll query(int l, int r) {
		return query_rec(l, r, 0, 0, size);
	}
private:
	ll query_rec(int l, int r, int k, int lc, int rc) {
		if (rc <= l or r <= lc)
			return INT64_MAX;
		else if (l <= lc and rc <= r)
			return seg[k];
		else {
			int lcidx = k * 2 + 1, pidx = (lc + rc) / 2;
			return min(
				query_rec(l, r, lcidx, lc, pidx),
				query_rec(l, r, lcidx + 1, pidx, rc)
			);
		}
	}
};

