	SegmentTree(int s, ll initial_value = INT64_MAX) {
		size = 1;
		while (size < s)
			size <<= 1;
		minimum = make_v<ll>(2 * size);
		fill_v(minimum, initial_value);
		lazy = make_v<ll>(2 * size);
		fill_v(lazy, initial_value);
	}

	void update(int idx, ll value) {
		idx += size-1;
		minimum[idx] = value;
		//lazy[idx] = value;
		while (idx) {
			idx = (idx - 1) / 2;
			int lcidx = idx * 2 + 1;
			minimum[idx] = min(minimum[lcidx], minimum[lcidx + 1]);
			//lazy[idx] = min(lazy[lcidx], lazy[lcidx + 1]);
		}
	}

	void update(int l, int r, ll addValue) {
		update_rec(l, r, 0, 0, size, addValue);
	}

	// [l, r) , include v[l], not include v[r]
	ll query(int l, int r) {
		return query_rec(l, r, 0, 0, size);
	}
private:
	ll query_rec(int l, int r, int k, int lc, int rc) {
		lazy_eval(k);
		if (rc <= l or r <= lc)
			return INT64_MAX;
		else if (l <= lc and rc <= r)
			return minimum[k];
		else {
			int lcidx = k * 2 + 1, pidx = (lc + rc) / 2;
			return min(
				query_rec(l, r, lcidx, lc, pidx),
				query_rec(l, r, lcidx + 1, pidx, rc)
			);
		}
	}

	void lazy_eval(int k) {
		ll lk = lazy[k];
		minimum[k] += lk;
		if (k < size - 1) {
			int lcidx = 2 * k + 1;
			lazy[lcidx] += lk;
			lazy[lcidx + 1] += lk;
		}
		lazy[k] = 0;
	}
	void update_rec(int l, int r, int k, int lc, int rc, ll addValue) {
		if (rc <= l or r <= lc)
			return;
		else if (l <= lc and rc <= r) {
			lazy[k] += addValue;
			lazy_eval(k);
		} else {
			lazy_eval(k);
			int lcidx = k * 2 + 1, pidx = (lc + rc) / 2;
			update_rec(l, r, lcidx, lc, pidx, addValue);
			update_rec(l, r, lcidx + 1, pidx, rc, addValue);
			minimum[k] = min(minimum[lcidx], minimum[lcidx + 1]);
		}
	}
};

