using namespace std;

struct SegTree {
    int n;
    vector<int> node;
    SegTree(int sz) {
        n = 1;
        while (n < sz) n *= 2;
        node.resize(2 * n - 1, INT_MIN);
    }
    void update(int p, int v) {
        p += n - 1;
        node[p] = v;
        while (p) {
            p = (p - 1) / 2;
            node[p] = min(node[2 * p + 1], node[2 * p + 2]);
        }
    }
    int get(int a, int b, int k = 0, int l = 0, int r = -1) {
        if (r < 0) r = n;
        if (b <= l || r <= a) return INT_MIN;
        if (a <= l && r <= b) return node[k];
        return min(get(a, b, k * 2 + 1, l, (l+r) / 2), get(a, b, k * 2 + 2, (l+r) / 2, r));

    }
};

int main()
{
    int n, q;
    cin >> n >> q;
    SegTree s(n);
    while (q--) {
        int c, x, y;
        cin >> c >> x >> y;
        if (c == 0) {
            s.update(x, y);
        } else {
            cout << s.get(x, y+1) << endl;
        }
    }
}

