/* 
   requirement
   Val : default / copy constructor
   Map : Val operator() (Val, Val)
*/
template<class Val, class Map>
struct SegmentTree {
    int n;
    Map mp;
    vector<Val> data;
    const Val Id; // identity element
    explicit SegmentTree(int n_, const Val& id_ = Val())
        : mp(Map()), Id(id_) { init(n_);}
    void init(int n_) {
        for(n = 1; n < n_; n <<= 1);
        data.assign(2 * n - 1, Id);
    }
    void update(int k, Val a) {//0-indexed
        k += n - 1;
        data[k] = a;
        while(k > 0) {
            k = (k - 1) >> 1;
            data[k] = mp(data[k * 2 + 1], data[k * 2 + 2]); 
        }
    }
    Val __query(int a, int b, int k, int l, int r) {
        if(r <= a || b <= l) return Id;
        if(a <= l && r <= b) return data[k];
        else {
            Val val_l = __query(a, b, k * 2 + 1, l, (l + r) >> 1);
            Val val_r = __query(a, b, k * 2 + 2, (l + r) >> 1, r);
            return mp(val_l, val_r);
        }
    }
    Val query(int a, int b) { //[a, b)
        return __query(a, b, 0, 0, n);
    }
};

