template<typename T>
class RangeMinimumQuery {
public:
	RangeMinimumQuery(){}
	RangeMinimumQuery(int n, T init, function<bool(const T&, const T&)> cmp = less<T>()){
		for (size = 1; size < n; size <<= 1);
		val.assign(size * 2 - 1, init);
		this->init = init;
		this->cmp = cmp;
	}

	void update(int k, T x){
		k += size - 1;
		val[k] = x;
		while (k > 0){
			k = (k - 1) / 2;
			val[k] = cmp(val[k * 2 + 1], val[k * 2 + 2]) ? val[k * 2 + 1] : val[k * 2 + 2];
		}
	}

	T get(int l, int r){
		return get(l, r, 0, 0, size);
	}

	T get(int l, int r, int k, int a, int b){
		if (r <= a || b <= l) return init;
		if (l <= a && b <= r) return val[k];
		int m = (a + b) / 2;
		T vl = get(l, r, k * 2 + 1, a, m);
		T vr = get(l, r, k * 2 + 2, m, b);
		return cmp(vl, vr) ? vl : vr;
	}

private:
	int size;
	T init;
	vector<T> val;
	function<bool(const T&, const T&)> cmp;
};
