/* construct sparse table */
void constructST(int** ST, unsigned long long* A, int n)
{
	int m = (int)(log2((float)n)) + 1; // range of p, second subscript of ST[i][p]

	for (int i=0; i<n; i++) ST[i][0] = i;

	for (int p=1; p<m; p++) {
		for (int i=0; i<n; i++) {
			int q = min(i + (1<<(p-1)), n-1);
			if (A[ST[i][p-1]] < A[ST[q][p-1]]) ST[i][p] = ST[i][p-1];
			else ST[i][p] = ST[q][p-1];
		}
	}
}

void updateST(int** ST, unsigned long long* A, int index, int n)
{
	int m = (int)(log2((float)n)) + 1; // range of p, second subscript of ST[i][p]

	for (int p=1; p<m; p++) {
		int start = max(0, index-(1<<p)+1);
		for (int i=start; i<=index; i++) {
			int q = min(i + (1<<(p-1)), n-1);
			if (A[ST[i][p-1]] < A[ST[q][p-1]]) ST[i][p] = ST[i][p-1];
			else ST[i][p] = ST[q][p-1];
		}
	}
}

/* range minimum query for sparse table */
int rmqST(unsigned long long* M, int** ST, int i, int j)
{
	if (i==j) return ST[i][0];
	int p = abs((int)log2((float)(j-i)));
	if (M[ST[i][p]] < M[ST[j-(1<<p)+1][p]]) return ST[i][p];
	else return ST[j-(1<<p)+1][p];
}

void calcBitSequence(unsigned long long* B, std::bitset<8>* l, int m)
{
	int* g = new int[m];

	for (int i=0; i<m; i++) g[i] = i-1;

	std::stack<int> st;

	// calculate g[0..m-1]
	for (int i=m-1; i>=0; i--) {
		while (!st.empty() && B[i] < B[st.top()]) {
			g[st.top()] = i; st.pop();
		}
		if (i>0 && B[i-1] > B[i]) st.push(i);
	}
	while (!st.empty()) {
		g[st.top()] = -1; st.pop();
	}

	// calculate bit sequence l[0], ..., l[m-1]
	// assumption : l[i] is resized by m 
	for (int j=1; j<m; j++) {
		if (g[j] >= 0) {
			l[j] = l[g[j]];
			l[j].set(g[j]);
		}
		else l[j].reset();
	}

	delete[] g;
}

int rmqBS(std::bitset<8>* l, int m, int i, int j)
{
	std::bitset<8> mask(256-(1<<i));
	std::bitset<8> tmp = mask & l[j];
	if (tmp.none()) return j;
	else {
		for (int k=0; k<m; k++) {
			if (tmp.test(k)) return k;
		}
	}
}

bool isSameBlock(int i, int j, int m)
{
	return i/m == j/m;
}

// * this function returns the minimum value! (not its index)
unsigned long long rmq(unsigned long long* A, std::bitset<8>** l, int m, unsigned long long* M, int** ST, int k, int i, int j)
{
	if (isSameBlock(i, j, m)) {
		int res_bs = i - i%m + rmqBS(l[i/m], m, i%m ,j%m);
		//std::cout << "  rmqBS(" << i/m << "," << m << "," << i%m << "," << j%m << ") : res_bs = " << res_bs << std::endl;
		return A[res_bs];
	}

	int el = -1;
	for (; el < i; el+=m);
	int sr = (k-1)*m;
	for (; sr > j; sr -= m);
	int left = (el+1) / m;
	int right = sr/m - 1;

	int res_bs1 = m * (left-1) + rmqBS(l[left-1], m, i%m, el%m);
	//std::cout << "  rmqBS(" << left-1 << "," << m << "," << i%m << "," << el%m << ") : res_bs1 = " << res_bs1 << std::endl;
	int res_bs2 = m * (right+1) + rmqBS(l[right+1], m, sr%m, j%m);
	//std::cout << "  rmqBS(" << right+1 << "," << m << "," << sr%m << "," << j%m << ") : res_bs2 = " << res_bs2 << std::endl;
	if (left <= right) {
		int res_st = rmqST(M, ST, left, right);
		//std::cout << "  rmqST(" << left << "," << right << ") = " << res_st << std::endl;
		if (A[res_bs1] <= A[res_bs2]) {
			if (A[res_bs1] <= M[res_st]) return A[res_bs1];
			else return M[res_st];
		} else {
			if (A[res_bs2] <= M[res_st]) return A[res_bs2];
			else return M[res_st];
		}
	}
	else {
		return min(A[res_bs1], A[res_bs2]);
	}

}

void process(unsigned long long* A, std::bitset<8>** l, int m, unsigned long long* M, int** ST, int k, int n)
{
	for (int i=0; i<k; i++) {
		int size = (i<k-1) ? m : n%m;
		if (size==0) size = m;
		int offset = m*i;
		calcBitSequence(A + offset, l[i], size);
		M[i] = A[offset + rmqBS(l[i], m, 0, size-1)];
	}

	constructST(ST, M, k);
}

void update(unsigned long long* A, int i, std::bitset<8>** l, int m, unsigned long long* M, int** ST, int k, int n)
{
	int block_index = i/m;
	int offset = m * block_index;
	calcBitSequence(A + offset, l[block_index], m);
	int size;
	if (block_index < k-1) size = m;
	else size = n - m*(k-1);
	unsigned long long value = A[offset + rmqBS(l[block_index], m, 0, size-1)];
	if (value != M[block_index]) {
		M[block_index] = value;
		updateST(ST, M, block_index, k);
	}
}

