int n, q;

struct segtree {
  int l, r, x;
  segtree *sl, *sr;

  segtree(int l, int r) : l(l), r(r), x(2147483647) {
    if (l != r) {
      int m = l + r >> 1;
      sl = new segtree(l, m);
      sr = new segtree(m + 1, r);
    }
  }

  void update(int k, int v) {
    if (l == k && r == k) {
      x = v;
      return;
    }

    int m = l + r >> 1;
    if (k <= m)
      sl->update(k, v);
    else
      sr->update(k, v);
    x = min(sl->x, sr->x);
  }

  int query(int ql, int qr) {
    if (ql == l && qr == r) return x;
    int m = l + r >> 1;
    if (qr <= m)
      return sl->query(ql, qr);
    else if (ql > m)
      return sr->query(ql, qr);
    else
      return min(sl->query(ql, m), sr->query(m + 1, qr));
  }
};

segtree *s;

int main() {
  cin >> n >> q;
  s = new segtree(0, n - 1);
  for (int i = 0; i < q; i++) {
    int c, x, y; cin >> c >> x >> y;
    if (c == 0) {
      s->update(x, y);
    } else {
      cout << s->query(x, y) << endl;
    }
  }
}

