void init(int n_)
{
    for(int i=0;i<=n_*2;i++) node[i]=INF;
}

void pushup(int rt)
{
    node[rt]=min(node[rt<<1|1],node[rt<<1]);
}

void print_tree()
{
    for(int i=1;i<=10;i++)
        printf("%d ",node[i]);
    printf("\n");
}

void update(int rt,int left,int right,int target,int value)
{
    if(left==right){
        node[rt]=value;
        return ;
    }
    if(target<=mid) update(lson,target,value);
    else if(target>mid) update(rson,target,value);
    pushup(rt);
}

int query(int rt,int left,int right,int L,int R)
{
    //printf("%d %d %d %d %d\n",rt,left,right,L,R);
    if(left==L&&R==right) return node[rt];
    if(R<left&&right<L) return INF;
    if(mid>=R) query(lson,L,R);
    else if(mid<L) query(rson,L,R);
    else return min(query(lson,L,mid),query(rson,mid+1,R));
}

