struct segment{
    int size;
    vector< ll > data;
    segment(int size):size(size){ data.resize(size*2+1,INF); }
    void update(int p,ll v){
        p+=size-1; data[p]=v;
        while(p>1){
            p/=2;
            data[p]=min(data[p*2],data[p*2+1]);
        }
    }
    ll query(int a,int b,int p,int l,int r){
        if(r<=a||b<=l) return INF;
        if(a<=l&&r<=b) return data[p];
        return min(query(a,b,p*2,l,(l+r)/2),query(a,b,p*2+1,(l+r)/2,r));
    }
};

