const int MAXN=4e5+10;
int N,Q;

uint seg[MAXN];

uint init(int cur,int l,int r){
    if (r-l==1)
        return seg[cur]=ini;
    else{
        auto mid=(l+r)/2;
        return seg[cur]=min(
            init(cur*2,l,mid),
            init(cur*2+1,mid,r)
        );
    }
}

uint find(int ql,int qr,int l,int r,int cur){
    if (ql==l&&qr==r) return seg[cur];

    auto mid=(l+r)/2;
    if (qr<=mid) return find(ql,qr,l,mid,cur*2);

    if (ql>=mid) return find(ql,qr,mid,r,cur*2+1);

    return min(
        find(ql,mid,l,mid,cur*2),
        find(mid,qr,mid,r,cur*2+1)
    );
}

uint update(int i,int x,int l,int r,int cur){
    if (r-l==1) return seg[cur]=x;

    auto mid=(l+r)/2;
    if (i>=mid) return seg[cur]=min(seg[cur*2],update(i,x,mid,r,cur*2+1));
    else return seg[cur]=min(update(i,x,l,mid,cur*2),seg[cur*2+1]);
}

