struct RMQ{
  vvi rmq;
  ll size;
  ll logsize;
  RMQ(ll size) : size(size){
    for(logsize=1;(1ll<<logsize)<=size;logsize++);
    vvi rmq(logsize, vi(size,INF));
    swap(this->rmq,rmq);
  }
  ll find(ll s, ll t){
    if(s+1==t) return rmq[0][s];
    ll p; for(p=0;(1ll<<p)+s<t;p++); p--;
    return min(rmq[p][s],find((1ll<<p)+s,t));
  }
  void update(ll i, ll x){
    rmq[0][i]=min(rmq[0][i],x);
    FOR(j,1,logsize){
      ll p=(1ll<<j);
      rmq[j][i-(i%(p/2))]=min(rmq[j][i-(i%(p/2))],x);
    }
  }
};

