int size;
vector<int> node((1 << 19) - 1);

void init(int n_, vector<int>& node) {
    size = 1;
    while (size < n_) size *= 2;
    for (int i = 0; i < 2 * size - 1; i++) node[i] = INT_MAX;
}

void update(int k, int a, vector<int>& node) {
    k += size - 1;
    node[k] = a;
    while (k > 0){
        k = (k - 1) / 2;
        node[k] = min(node[2 * k + 1], node[2 * k + 2]);
    }
}

int get_min(int queryL, int queryR, vector<int>& node, int k = 0, int nodeL = 0, int nodeR = -1) {
    if (nodeR == -1) nodeR = size;
    if (nodeR <= queryL || queryR <= nodeL) return INT_MAX;
    if (queryL <= nodeL && nodeR <= queryR) return node[k];
    else{
        int nodeM = (nodeL + nodeR) / 2;
        int vl = get_min(queryL, queryR, node, 2 * k + 1, nodeL, nodeM);
        int vr = get_min(queryL, queryR, node, 2 * k + 2, nodeM, nodeR);
        return min(vl, vr);
    }
}

int n, q;

int main(){
    cin.tie(0);
    ios::sync_with_stdio(false);
    cin >> n >> q;
    init(n, node);
    rep(i, q) {
        int com, x, y;
        cin >> com >> x >> y;
        if (com == 0) update(x, y, node);
        else cout << get_min(x, y + 1, node) << endl;
    }
}

