class Segtree {
public:
    Segtree(li n) {
        nn = 1;
        while (nn < n) {
            nn *= 2;
        }
        data.resize(nn * 2 - 1);
        for (auto && item : data) {
            item = bit(31) - 1;
        }
    }

    inline void update(li i, li x) {
        i += nn - 1;
        data[i] = min(data[i], x);
        while (i > 0) {
            i = (i - 1) / 2;
            data[i] = min(data[i * 2 + 1], data[i * 2 + 2]);
        }
    }

    inline li query_(li a, li b, li k, li l, li r) {
        if (r <= a || b <= l) return INF;
        if (a <= l && r <= b) return data[k];
        li mid = (l + r) / 2;
        li vl = query_(a, b, k * 2 + 1, l, mid);
        li vr = query_(a, b, k * 2 + 2, mid, r);
        return min(vl, vr);
    }

    inline li query(li a, li b) {
        li l = 0;
        li r = nn;
        li k = 0;
        if (r <= a || b <= l) return INF;
        if (a <= l && r <= b) return data[k];
        li mid = (l + r) / 2;
        li vl = query_(a, b, k * 2 + 1, l, mid);
        li vr = query_(a, b, k * 2 + 2, mid, r);
        return min(vl, vr);
    }

    li nn;
    vector<li> data;
};
