#define INF 2147483647

class RMQ{
public:
  int n;
  vector<int> d;

  RMQ(int size){
    initRMQ(size);
  }

  void initRMQ(int size){
    n = 1;
    //the size of array is power of 2
    while(n < size) n *= 2;
    //initialize all node in the segment tree
    //d.resize(2*i, numeric_limits<float>::infinity());
    d.resize(2*n, INF);
  }

  void update(int k, int a){
    k += n-1; //convert array index to tree index
    d[k] = a;
    while(k > 0){
      k = (k-1)/2;
      d[k] = min(d[k*2+1], d[k*2+2]);
    }
  }

  //[a, b]
  int findMin(int a, int b){
    return query(a, b+1, 0, 0, n);
  }

  //[a, b)
  int query(int a, int b, int k, int l, int r){
    //if(r <= a || b <= l) return numeric_limits<float>::infinity();  //case 1
    if(r <= a || b <= l) return INF;
    if(a <= l && r <= b) return d[k]; //case 2
    //case 3
    int vl = query(a, b, k*2+1, l, (l+r)/2);
    int vr = query(a, b, k*2+2, (l+r)/2, r);
    return min(vl, vr);
  }
};

