  int com, x, y;
  cin >> n >> q;

  RMQ rmq(n);

  for(int i=0 ; i<q ; ++i){
    cin >> com >> x >> y;
    if(com == 0) rmq.update(x, y);
    else if(com == 1) cout << rmq.findMin(x, y) << endl;
  }
}

