void change(int k, int x){
	int p = 0;
	int y;
	while (l[p] + 1 < r[p]){
		a[p] = min(a[p], x);
		y = (l[p] + r[p]) / 2;
		if (k < y){
			if (sl[p] == -1){
				l[nx] = l[p];
				r[nx] = y;
				sl[p] = nx;
				p = nx;
				nx++;
			}
			else{
				p = sl[p];
			}
		}
		else{
			if (sr[p] == -1){
				l[nx] = y;
				r[nx] = r[p];
				sr[p] = nx;
				p = nx;
				nx++;

			}
			else{
				p = sr[p];
			}
		}
	}
	a[p] = min(a[p], x);
	return;
}
//探索(0<=l<r<=n)範囲は(l<=x<r)初期は(l,r,0)
int min_search(int ll, int rr, int k){
	int vl, vr;
	if (rr <= l[k] || r[k] <= ll)return MOD;
	else if (ll <= l[k] && r[k] <= rr) return a[k];
	else{
		if (sl[k] != -1)vl = min_search(ll, rr, sl[k]);
		else vl = MOD;
		if (sr[k] != -1)vr = min_search(ll, rr, sr[k]);
		else vr = MOD;
		return min(vl, vr);
	}
}


