template <class T>
class SegmentTree{
private:
    int n;
    vector<T> dat;
    T def;
    function<T(T, T)> operation;
    function<T(T, T)> update;

    T _query(int a, int b, int k, int l, int r){
        // [a, b), [l, r)
        if(r<=a or b<=l) return def;
        else if(a<=l and r<=b) return dat[k];
        else{
            T c1 = _query(a, b, 2*k+1, l, (l+r)/2);
            T c2 = _query(a, b, 2*k+2, (l+r)/2, r);
            return operation(c1, c2);
        }
    }

    void _change(int i, T x){
        i += n - 1;
        dat[i] = update(dat[i], x);
        while(i){
            i = (i-1) / 2;
            dat[i] = operation(dat[2*i+1], dat[2*i+2]);
        }
    }

public:
    T query(int a, int b){
        return _query(a, b, 0, 0, n);
    }

    void change(int i, T x){
        _change(i, x);
    }

    T operator[](int i){
        return dat[i+n-1];
    }

    SegmentTree(size_t _n, T _def, function<T(T, T)> _operation,
                function<T(T, T)> _update)
            : def(_def), operation(_operation), update(_update){
        n = 1;
        while(n < _n){
            n *= 2;
        }
        dat = vector<T>(2*n-1, def);
    }
};

