using namespace std;

class RMQ{

public:
    int N;
    int dat[2 * MAX_N - 1];

    RMQ(int n){
        int k = 1;
        while (k < n) k *= 2;
        N = k;
        for(int i = 0; i < 2 * N - 1; i++){
            dat[i] = inf;
      }
    }

    void update(int i,int x){
        i += N - 1;
        dat[i] = x;
        while(i > 0){
            i = (i - 1) / 2;
            dat[i] = min(dat[2 * i + 1], dat[2 * i + 2]);
        }
    }

    int find(int a, int b, int k, int l, int r){
        if(r <= a || b <= l)return inf;
        if(a <= l && r <= b)return dat[k];

        int mid = (l + r) / 2;
        return min(find(a, b, 2 * k + 1, l, mid), find(a, b, 2 * k + 2, mid, r));
    }

    int _find(int a, int b){
        return find(a, b, 0, 0, N);
    }

};

int main(int argc, const char * argv[]) {
    int n, q, c, x, y;
    cin >> n >> q;
    RMQ rmq(n);

    for (int i = 0; i < q; i ++){
        cin >> c >> x >> y;
        if (c == 0){
            rmq.update(x, y);
        }
        else {
            cout << rmq._find(x, y + 1) << endl;
        }
    }

    return 0;
}

