			ar[b] = c;

			if(b % k == 0)
				for(ll i = b; i < b + k; i++)
					mnn = min(mnn , ar[i]);

			else if(b % k == k - 1)
				for(ll i = b - k + 1; i <= b; i++)
					mnn = min(mnn , ar[i]);

			else
				for(ll i = (b / k) * k; i < (b / k + 1) * k; i++)
					mnn = min(mnn , ar[i]);


			mn[b / k].sc = mnn;
		}

		else{
			ll mnn = 1e18 + 10;

			for(ll i = (b / k) * k; i <= b; i++)
				mnn = min(mnn , ar[i]);

			for(ll i = c; i < ((c / k) + 1) * k; i++)
				mnn = min(mnn , ar[i]);

			for(ll i = (b / k) + 2; i < (c / k); i++)
				mnn = min(mnn , mn[i].sc);

			ans.PB(mnn);
		}
	}


