template<typename T> struct segment_tree{
    int tree_size;
    vector<T> segment_tree_array;

    void resize(int size_number){
        tree_size = 1;
        while(tree_size < size_number){
            tree_size *= 2;
        }
        segment_tree_array.resize(tree_size);
        for(int i = 0; i < tree_size * 2 - 1; i++){
            segment_tree_array[i] = new T();
        }
    }

    void fill(int size_number, int value){
        tree_size = 1;
        while(tree_size < size_number){
            tree_size *= 2;
        }
        segment_tree_array.resize(tree_size);
        for(int i = 0; i < tree_size * 2 - 1; i++){
            segment_tree_array[i] = value;
        }
    }

    void change(int position, T value){
        position += tree_size - 1;
        segment_tree_array[position] = value;
        while(position){
            position = (position - 1) / 2;
            segment_tree_array[position] = segment_tree_array[position * 2 + 1] + segment_tree_array[position * 2 + 2];
        }
    }

    struct point{
        int now, point_left, point_right, back;
        T ans;
        bool calculated;
    };

    T calculation(int left, int right){
        return calcuration_recursion(left, right, 0, 0, tree_size);
    }

    int calcuration_recursion(int left, int right, int now, int point_left, int point_right){
        if(right <= point_left || point_right <= left){
            return new T();
        }else if(left <= point_left && point_right <= right){
            return segment_tree_array[now];
        }else{
            return calcuration_recursion(left, right, now * 2 + 1, point_left, (point_left + point_right) / 2) +
                   calcuration_recursion(left, right, now * 2 + 2, (point_left + point_right) / 2, point_right);
        }
    }
};




