    public:
    segtree(ll n){
        siz=1;
        while(siz<n) siz*=2;
        node.resize(siz*2,inf);
    }
    void upd(ll pos,ll x){
        pos+=siz-1;
        node[pos]=x;
        while(pos>0){
            pos=(pos-1)/2;
            node[pos]=min(node[pos*2+1],node[pos*2+2]);
        }
