template <typename Monoid>
struct SegmentTree {
private:
    using Func = function<Monoid(Monoid, Monoid)>;
    const Func UPDATE, OPERATION;
    const Monoid E;
    int SIZE = 1;
    vector<Monoid> node;

public:
    // SegmentTree(int n, const Func update, const Monoid &e)
    //     : UPDATE(update), E(e) {
    //     OPERATION = UPDATE;
    //     while (SIZE < n) SIZE *= 2;
    //     node.assign(SIZE * 2, E);
    // }

    SegmentTree(int n, const Func operation, const Func update, const Monoid &e) 
        : OPERATION(operation), UPDATE(update), E(e) {
            while (SIZE < n) SIZE *= 2;
            node.assign(SIZE * 2, E);
        }

    void set(int a, const Monoid &val) { node[a + SIZE] = val; }

    void build() {
        for (int k = SIZE - 1; k > 0; k--) {
            node[k] = OPERATION(node[2 * k], node[k * 2 + 1]);
        }
    }

    void update(int a, const Monoid &val) {
        int k = a + SIZE;
        node[k] = UPDATE(node[k], val);
        while (k >>= 1) node[k] = OPERATION(node[2 * k], node[2 * k + 1]);
    }

    Monoid query(int a, int b) {
        Monoid leftVal = E, rightVal = E;
        for (int left = a + SIZE, right = b + SIZE; left < right; left >>= 1, right >>= 1) {
            if (left & 1) leftVal = OPERATION(leftVal, node[left]), left += 1;
            if (right & 1) right -= 1, rightVal = OPERATION(rightVal, node[right]);
        }
        return OPERATION(leftVal, rightVal);
    }

    inline Monoid operator[](int a) { return node[a + SIZE]; }
};

