template <typename T> struct SegmentTree {
  struct Node {
    T v;
    Node(T v) : v(v) {}
    Node operator*(const Node &r) const {
      return Node(min(v, r.v));
    }
  };

  Node e = Node((1ll << 31) - 1);
  size_t n;
  vector<Node> seg;

  SegmentTree(size_t size) : n(1 << (32 - __builtin_clz(size - 1))), seg(2 * n, e) {}

  void update(int k, const Node &x) {
    for (seg[k + n] = x, k = (k + n) / 2; k; k >>= 1) {
      seg[k] = seg[2 * k] * seg[2 * k + 1];
    }
  }

  Node query(int a, int b, int k, int l, int r) {
    if (r <= a || b <= l) return e;
    if (a <= l && r <= b) return seg[k];
    return query(a, b, 2 * k, l, (l + r) / 2) * query(a, b, 2 * k + 1, (l + r) / 2, r);
  }

  void update(int k, T x) {
    update(k, Node(x));
  }

  T query(int a, int b) {
    return query(a, b, 1, 0, n).v;
  }
};


