const int MAX_N = 100000; // 1 << 20; // > 10^6

class SegTree{

public:

	int n;
	int dat[2 * MAX_N - 1];
	int dummy = (1 << 31) - 1;

	SegTree(int _n){
		init(_n);
	}

	void init(int n_){
		n = 1;
		while(n < n_) n *=2;
		// initialize
		rep(i, 2 * n - 1) dat[i] = dummy;
	}

	void update(int k, int a){
		// update from bottom
		k += n-1;
		dat[k] = a;
		while(k > 0){
			k = (k - 1) / 2;
			dat[k] = min(dat[k*2+1], dat[k*2+2]);
		}
	}

	// min of [a, b)
	int query(int a, int b){
		return _query(a, b, 0, 0, n);
	}

	// min of [a, b)
	// node k, corresponding [l, r)
	int _query(int a, int b, int k, int l, int r){
		if(r <= a || b <= l) return dummy;
		if(a <= l && r <= b) return dat[k];
		else{
			int vl = _query(a, b, k*2+1, l, (l+r)/2);
			int vr = _query(a, b, k*2+2, (l+r)/2, r);
			return min(vl, vr);
		}
	}
};


