class SegTree
{
public:
    SegTree() {}
    ~SegTree() {}
    SegTree(int n_)
    : n((u32)1 << n_), dat(vs32(2 * n - 1, INF))
    {}

    void update(int k, int a)
    {
        k += n - 1;
        dat[k] = a;
        while (k > 0)
        {
            k = (k - 1) / 2;
            dat[k] = MIN(dat[k * 2 + 1], dat[k * 2 + 2]);
        }
    }

    // return the minimum value in the range [a, b)
    // set k, l, r = 0, 0, n when you call this function
    int query(int a, int b, int k, int l, int r)
    {
        if (r <= a || b <= l) return INF;

        if (a <= l && r <= b)
        {
            return dat[k];
        }
        else
        {
            int vl = query(a, b, k * 2 + 1, l, (l + r) / 2);
            int vr = query(a, b, k * 2 + 2, (l + r) / 2, r);
            return MIN(vl, vr);
        }
    }

    static const u32 INF = ((u32)1 << 31) - 1;
    int n;
    vs32 dat;
};

