  seg[k] = x;
  while (k > 0) {
    k = (k-1)/2;
    seg[k] = min(seg[k*2+1], seg[k*2+2]);
  }
}

int find(int s, int t, int k, int l, int r) {
  if (r <= s || t <= l) return INT_MAX;
  if (s <= l && r <= t) return seg[k];
  int vl = find(s,t,k*2+1,l,(l+r)/2);
  int vr = find(s,t,k*2+2,(l+r)/2,r);
