//幅優先探索(8パズル)
ll bfs(vll hajime) {
	struct pazzle { vll id; ll depth; };

	vll goal = { 1,2,3,4,5,6,7,8,0 };

	map<vll, bool> hantei;

	deque<pazzle> p;
	p.pub({ hajime,0 });
	while (!p.empty()) {
		if (p[0].id == goal)return p[0].depth;

		ll pos = find(ALL(p[0].id), 0) - p[0].id.begin();
		if (pos % 3 != 2) {
			swap(p[0].id[pos], p[0].id[pos + 1]);
			if (!hantei[p[0].id]) {
				p.pub({ p[0].id,p[0].depth + 1 });
				hantei[p[0].id] = true;
			}
			swap(p[0].id[pos], p[0].id[pos + 1]);
		}
		if (pos % 3 != 0) {
			swap(p[0].id[pos], p[0].id[pos - 1]);
			if (!hantei[p[0].id]) {
				p.pub({ p[0].id,p[0].depth + 1 });
				hantei[p[0].id] = true;
			}
			swap(p[0].id[pos], p[0].id[pos - 1]);
		}
		if (pos >= 3) {
			swap(p[0].id[pos], p[0].id[pos - 3]);
			if (!hantei[p[0].id]) {
				p.pub({ p[0].id,p[0].depth + 1 });
				hantei[p[0].id] = true;
			}
			swap(p[0].id[pos], p[0].id[pos - 3]);
		}
		if (pos <= 5) {
			swap(p[0].id[pos], p[0].id[pos + 3]);
			if (!hantei[p[0].id]) {
				p.pub({ p[0].id,p[0].depth + 1 });
				hantei[p[0].id] = true;
			}
			swap(p[0].id[pos], p[0].id[pos + 3]);
		}

		p.pof();
	}
}

//反復深化IDA*(15パズル)
ll manhattan[16][16];
ll dfs(vll &state,ll depth,ll limit,ll prestep) {
	ll summ = 0;
	rep(i, 0, 16)if (state[i] != 0)summ += manhattan[state[i] - 1][i]; else summ += manhattan[15][i];
	if (summ == 0)return depth;
	if (depth + summ > limit)return -1;

	ll cnt = 46;
	ll pos = find(ALL(state), 0) - state.begin();
	if (pos % 4 != 3 && prestep != 2) {
		swap(state[pos], state[pos + 1]);
		ll ret = dfs(state, depth + 1, limit, 1);
		if (ret != -1 && ret < cnt)cnt = ret;
		swap(state[pos], state[pos + 1]);
	}
	if (pos % 4 != 0 && prestep != 1) {
		swap(state[pos], state[pos - 1]);
		ll ret = dfs(state, depth + 1, limit, 2);
		if (ret != -1 && ret < cnt)cnt = ret;
		swap(state[pos], state[pos - 1]);
	}
	if (pos > 3 && prestep != 4) {
		swap(state[pos], state[pos - 4]);
		ll ret = dfs(state, depth + 1, limit, 3);
		if (ret != -1 && ret < cnt)cnt = ret;
		swap(state[pos], state[pos - 4]);
	}
	if (pos < 12 && prestep != 3) {
		swap(state[pos], state[pos + 4]);
		ll ret = dfs(state, depth + 1, limit, 4);
		if (ret != -1 && ret < cnt)cnt = ret;
		swap(state[pos], state[pos + 4]);
	}

	if (cnt == 46)return -1;
	else return cnt;
}

//bit全探索(n!探索=>bit DP)
bool zt01(vll a, ll m) {
	ll n = a.size(), j = 1, k = 0, l = 0;
	vll dp(1 << n); dp[0] = 0;
	//dp不可時:rep(i,0,n)if(bit & (1<<i))
	rep(i, 1, 1 << n) {
		k++;
		dp[i] = dp[i - j] + a[l];
		if (k == j) { j *= 2; k = 0; l++; }
		if (dp[i] == m)return true;
	}
	return false;
}

//nCk全探索(k≠0)
ll nec(ll bit) {
	//for(ll bit=(1<<k)-1;bit<(1<<n);bit=nec(bit))
	ll x = bit & -bit, y = bit + x;
	return (((bit & ~y) / x) >> 1) | y;
}

//乱数生成[0,4294967295]
ll ransu() {
	static unsigned int TX = 123456789, TY = 362436069, TZ = 521288629, TW = 88675123;
	unsigned int tt = (TX ^ (TX << 11));
	TX = TY; TY = TZ; TZ = TW;
	return (TW = (TW ^ (TW >> 19)) ^ (tt ^ (tt >> 8)));
}

