const int INF = 2147483647;

struct Node {
  int lp, rp; // [l, r)
  int v;
  Node *lc, *rc;
  Node(int v_, int lp_, int rp_)
    : v(v_), lp(lp_), rp(rp_) {
  }
  ~Node() {
    delete lc;
    delete rc;
  }
};

int minv(Node* x, Node* y) {
  if (!x) return (!y)?INF:y->v;
  if (!y) return x->v;
  return min(x->v, y->v);
}

void update(Node *t, int k, int a) {
  if (t->rp - t->lp == 1 and t->lp == k) {
    t->v = a;
    return;
  } 
  int mid = (t->lp + t->rp) / 2;
  if (k < mid) {
    if (!(t->lc)) t->lc = new Node(INF, t->lp, mid);
    update(t->lc, k, a);
  } else {
    if (!(t->rc)) t->rc = new Node(INF, mid, t->rp);
    update(t->rc, k, a);
  }
  t->v = minv(t->lc, t->rc);
  return;
}

// min([a,b))
int query(Node* t, int a, int b) {
  if (!t) return INF;
  if (t->rp <= a || b <= t->lp) return INF;
  else if (a <= t->lp && t->rp <= b) return t->v;
  else {
    int vl = query(t->lc, a, b);
    int vr = query(t->rc, a, b);
    return min(vl, vr);
  }
}

