void createTree(int n_){
    int n = 1;
    while (n < n_){
        n *= 2;
    }
    N = n;
    tree = new int[2*N-1-1];
    for (int i = 0; i < 2*N-1-1; ++i) {
        tree[i] = psINF;
    }
};
void updateTree(int index, int x){

    index += N -1;
    tree[index] = x;
    while(index > 0){
        index = (index - 1) / 2;
        tree[index] = min(tree[index*2+1],tree[index*2+2]);
    }
};
int query(int a, int b, int k, int l, int r){
    if( r < a || b < l ){
        return psINF;
    }
    if( a <= l && r <= b ){
        return tree[k];
    }
    int vl = query(a, b, k*2+1, l, (l+r)/2);
    int vr = query(a, b, k*2+2, (l+r)/2+1, r);
    return min(vl,vr);
};

int RMQ(int a, int b){
    return query(a, b+1, 0, 0, N);
};

