const int N = 1e5 + 10;
const ll inf = 1e18;
struct SEG{
  ll data[N*4];
  int n;
  SEG(int t) {
    t++;
    t = max(16, t);
    n = 1;
    while(n < t) n <<= 1;
    for(int i= 0; i < n * 2; i++) data[i] = (1ll << 31) - 1;
  }
  void set(int i, ll x) {
    i += n-1;
    data[i] = x;
    while(i > 0) i = (i - 1) / 2, data[i] = min(data[i * 2 + 1], data[i * 2 + 2]);
  }
  ll query(int a, int b, int k = 0, int l = 0, int r = -1){
    if(r<0)r=n;
    if(b <= l || r <= a) return inf;
    if(a <= l && r <= b) return data[k];
    return min(
        query(a, b, k * 2 +1, l, (l + r)>>1),
        query(a, b, k * 2 +2, (l + r)>>1, r));
  }
};

