using namespace std;

template <typename T,typename U> class SegmentTree{
	public :
		// rewrite
		inline T get(U x){
			return x;
		}

		inline T merge(T l,T r){
			return min(l,r);
		}

		int n;
		SegmentTree(int size,T o):out(o){
			for(n=1;n<size;n<<=1);
			data=vector<T>(2*n,out);
			flag=vector<bool>(2*n,false);
			lazy=vector<U>(2*n);
		}

		void update(int a,int b,U x,int k,int l,int r){
			if(r<=a||b<=l) return;
			if(a<=l&&r<=b){data[k]=get(x),flag[k]=true,lazy[k]=true;return;}
			lazy_evaluate(k,l,r);
			update(a,b,x,k*2+1,l,(l+r)/2);
			update(a,b,x,k*2+2,(l+r)/2,r);
			data[k]=merge(data[k*2+1],data[k*2+2]);
		}

		void update(int a,int b,U x){return update(a,b,x,0,0,n);}

		T query(int a,int b,int k,int l,int r){
			if(r<=a||b<=l) return out;
			if(a<=l&&r<=b) return data[k];
			lazy_evaluate(k,l,r);
			T vl = query(a,b,k*2+1,l,(l+r)/2);
			T vr = query(a,b,k*2+2,(l+r)/2,r);
			return merge(vl,vr);
		}

		T query(int a,int b) {return query(a,b,0,0,n);}

	private:
		vector<T> data;
		vector<bool> flag;
		vector<U> lazy;
		const T out;

		inline void lazy_evaluate(int k,int l,int r){
			if(flag[k]==false) return;
			U x=lazy[k];
			update(l,(l+r)/2,x,k*2+1,l,(l+r)/2);
			update((l+r)/2,r,x,k*2+2,(l+r)/2,r);
			flag[k]=false;
		}
};

