        node.resize(2*n-1,INF);

        for(int i=0; i<sz ; i++) node[i+n-1] = vect[i];
        for(int i=n-2; i>=0 ; i--) node[i] = min(node[2*i+1], node[2*i+2]);//ここをうまく書き換える
    }

    void update(int x, T val){
        x += (n-1);

        node[x] = val;
        while(x > 0){
            x = (x-1) / 2;
            node[x] = min(node[2*x+1], node[2*x+2]);
        }
