struct RMQ {
    T sq;
    std::vector<T> data;
    std::vector<T> bucket;
    RMQ(T size){
        sq = std::ceil(std::sqrt(size));
        data.resize(size, -1);
        bucket.resize(std::ceil(std::sqrt(size)), -1);
    }  
    RMQ(T size, T init): data(size, init){
        sq = std::ceil(std::sqrt(size));
        data.resize(size, init);
        bucket.resize(std::ceil(std::sqrt(size)), init);
    }
    void update(T i, T x) {
        data[i] = x;
        if(bucket[i/sq] > x){
            bucket[i/sq] = x;
        }
    }
    T find(T s, T t) {
        if(s == t) return data[s];

        T val = std::pow(2, 31) - 1;
        REP(i, sq) {
            T l = i*sq, r = (i+1)*sq;
            if(r <= s || t <= l) {
                continue;
            }

            if(s <= l && r <= t) {
                val = std::min(val, bucket[i]);
            } else {
                FOR(j, std::max(s, l), std::min(t, r)) {
                    val = std::min(val, data[j]);
                }
            }
        }
        return val;
    }
};

int main(){
    int n, q, c, x, y;
    std::cin >> n >> q;
    RMQ<long> rmq = RMQ<long>(n, std::pow(2, 31) - 1);
    REP(i, q) {
        std::cin >> c >> x >> y;
        if(c == 0) {
            rmq.update(x, y);
        } else {
            std::cout << rmq.find(x, y) << std::endl;
        }
    }
}

