using namespace std;
#define ui unsigned int



void build_tree(vector<ui>& tree, vector<ui>& v,
		ui node, ui i, ui j) {

  	if (i == j) {

		tree[node] = v[i];
		return;
	}

	build_tree(tree, v, node*2, i, (i+j)/2); 
	build_tree(tree, v, node*2+1, 1+(i+j)/2, j);

	tree[node] = min(tree[node*2], tree[node*2+1]);
}



void update(vector<ui>& tree, ui node,
		ui index, ui val, ui i, ui j) {

	if (index<i || index>j) return;
	if (i==j){ tree[node]=val; return; }

	update(tree, 2*node, index, val, i, (i+j)/2);
	update(tree, 2*node+1, index, val, (i+j)/2+1, j);
	tree[node] = min(tree[2*node], tree[2*node+1]);
}



ui query_tree(vector<ui>& tree, ui node,
	   	ui i, ui j, ui start, ui end) {

	if (i > end || j < start) return -1;
	if (i >= start && j <= end) return tree[node];

	return  min(
				query_tree(tree, 2*node, i, (i+j)/2, start, end),
				query_tree(tree, 2*node+1, (i+j)/2+1, j, start, end));
}


int main(){

	ui n, q, in, val, b;
	scanf("%u %u", &n, &q);
	vector<ui> v(n+1), tree(pow(2,ceil(1+log2(n))));
	build_tree(tree, v, 1, 1, n);



	for (int i=0; i<q; i++){

		scanf("%u %u %u", &b, &in, &val);

		if (b == 0) update(tree, 1, in+1, val, 1, n);
		else cout << query_tree(tree, 1, 1, n, in+1, val+1) << endl;
	}

	return 0;
}

