int max(int x, int y) {
	return x > y ? x : y;	
}

int min(int x, int y) {
	return x < y ? x : y;	
}

const int N = 100005;
const int INIT = 2147483647;

int n, m;

struct Node {

	int lt, rt, minimum;

}tree[N << 2];

void buildTree(int p, int l, int r) {

	tree[p].lt = l;
	tree[p].rt = r;
	tree[p].minimum = INIT;

	if (l == r)return;

	int mid = (l + r) >> 1;

	buildTree(p << 1, l, mid);
	buildTree(p << 1 | 1, mid + 1, r);

	return;

}

int query(int p, int l, int r) {

	if (tree[p].lt == l && tree[p].rt == r)
		return tree[p].minimum;

	int mid = (tree[p].lt + tree[p].rt) >> 1;

	if (r <= mid)
		return query(p << 1, l, r);
	if (l > mid)
		return query(p << 1 | 1, l, r);
	return min(
		query(p << 1, l, mid),
		query(p << 1 | 1, mid + 1, r)
	);

}

void change(int p, int x, int y) {

	if (tree[p].lt == tree[p].rt) {
		tree[p].minimum = y;
		return;
	}

	int mid = (tree[p].lt + tree[p].rt) >> 1;

	if (x <= mid)
		change(p << 1, x, y);
	else
		change(p << 1 | 1, x, y);

	tree[p].minimum = min(
		tree[p << 1].minimum,
		tree[p << 1 | 1].minimum
	);

	return;

}

signed main(void) {

	fread(p, 1, LIMIT, stdin);

	n = nextInt();
	m = nextInt();

	buildTree(1, 1, n);

	for (register int i = 1; i <= m; ++i) {

		int k = nextInt();
		int x = nextInt();
		int y = nextInt();

		if (k)
			printf("%d\n", query(1, x + 1, y + 1));
		else
			change(1, x + 1, y);

	}

	return 0;

}

