template <class T> struct Ass {
	using value_type = T;
	value_type a;
	bool f;
	Ass() : f(0) {}
	explicit Ass(const value_type &x) : a(x), f(1) {}
	explicit Ass(value_type &&x) : a(std::move(x)), f(1) {}
	Ass operator+(const Ass &o) const { return o.f ? o : *this; }
};

template <class T> struct Add {
	using value_type = T;
	value_type a;
	Add() : a(0) {}
	explicit Add(const value_type &x) : a(x) {}
	explicit Add(value_type &&x) : a(std::move(x)) {}
	Add operator+(const Add &o) const { return Add(a + o.a); }
};

template <class T> struct Mini {
	using value_type = T;
	value_type a;
	Mini() : a(std::numeric_limits<value_type>::max()) {}
	explicit Mini(const value_type &x) : a(x) {}
	explicit Mini(value_type &&x) : a(std::move(x)) {}
	Mini operator+(const Mini &o) const { return Mini(std::min(a, o.a)); }
	Mini operator*(const Ass<value_type> &o) const {
		return o.f ? Mini(o.a) : *this;
	}
	Mini operator*(const Add<value_type> &o) const { return Mini(a + o.a); }
};

template <class T> struct Maxi {
	using value_type = T;
	value_type a;
	Maxi() : a(std::numeric_limits<value_type>::lowest()) {}
	explicit Maxi(const value_type &x) : a(x) {}
	explicit Maxi(value_type &&x) : a(std::move(x)) {}
	Maxi operator+(const Maxi &o) const { return Maxi(std::max(a, o.a)); }
	Maxi operator*(const Ass<value_type> &o) const {
		return o.f ? Maxi(o.a) : *this;
	}
	Maxi operator*(const Add<value_type> &o) const { return Maxi(a + o.a); }
};

template <class T> struct Sum {
	using value_type = T;
	using size_type = std::size_t;
	value_type a;
	size_type s;
	Sum() : a(0), s(0) {}
	explicit Sum(const value_type &x, const size_type y) : a(x), s(y) {}
	explicit Sum(value_type &&x, const size_type y) : a(std::move(x)), s(y) {}
	Sum operator+(const Sum &o) const { return Sum(a + o.a, s + o.s); }
	Sum operator*(const Ass<value_type> &o) const {
		return o.f ? Sum(o.a * s, s) : *this;
	}
	Sum operator*(const Add<value_type> &o) const { return Sum(a + o.a * s, s); }
};

