template<typename T, typename E> struct LazySegmentTree {
  using F = function<T(T, T)>;
  using G = function<T(T, E)>;
  using H = function<E(E, E)>;
  using P = function<E(E, int)>;

  struct QueryObject {
    int a, b;
    E x;
    int k;
    int l, r;
    QueryObject(int a, int b, E x = 0, int k = 0, int l = 0, int r = -1)
        : a(a), b(b), x(x), k(k), l(l), r(r) {}
  };

  struct QueryType {
    virtual T outOfRange(LazySegmentTree<T, E>& lst, QueryObject& o) = 0;
    virtual T cover(LazySegmentTree<T, E>& lst, QueryObject& o) = 0;
    virtual T join(LazySegmentTree<T, E>& lst, QueryObject& o, T vl, T vr) = 0;
    T query(LazySegmentTree<T, E>& lst, QueryObject o) {
      if (o.r < 0) o.r = lst.n;
      lst.eval(o.r - o.l, o.k);
      if (o.b <= o.l || o.r <= o.a) return outOfRange(lst, o);
      if (o.a <= o.l && o.r <= o.b) return cover(lst, o);
      QueryObject o1 = o, o2 = o;
      o1.k = o.k * 2 + 1; o1.r = (o.l + o.r) / 2;
      o2.k = o.k * 2 + 2; o2.l = (o.l + o.r) / 2;
      T vl = query(lst, o1);
      T vr = query(lst, o2);
      return join(lst, o, vl, vr);
    }
  };

  struct Setter : QueryType {
    enum setter { RUQ, RAQ };
    T outOfRange(LazySegmentTree<T, E>& lst, QueryObject& o) {
      return lst.data[o.k];
    }
    T cover(LazySegmentTree<T, E>& lst, QueryObject& o) {
      lst.lazy[o.k] = lst.h(lst.lazy[o.k], o.x);
      lst.eval(o.r - o.l, o.k);
      return lst.data[o.k];
    }
    T join(LazySegmentTree<T, E>& lst, QueryObject& o, T vl, T vr) {
      return lst.data[o.k] = lst.f(vl, vr);
    }
  };

  struct Getter : QueryType {
    enum getter { RMQ, RSQ };
    T outOfRange(LazySegmentTree<T, E>& lst, QueryObject& o) {
      return lst.initT;
    }
    T cover(LazySegmentTree<T, E>& lst, QueryObject& o) {
      return lst.data[o.k];
    }
    T join(LazySegmentTree<T, E>& lst, QueryObject& o, T vl, T vr) {
      return lst.f(vl, vr);
    }
  };

  F add() {
    return [&](const T& x, const T& y) -> const T { return x + y; };
  }
  F minimum() {
    return [&](const T& x, const T& y) -> const T { return min(x, y); };
  }
  G ex_assign(E initE) {
    return [&initE](const T& x, const E& y) -> const T { return (y == initE) ? x : y; };
  }
  P ex_multiplies(E initE) {
    return [&initE](const E& x, int y) -> const E { return (x == initE) ? x : x * y; };
  }

  int n;
  T initT;
  E initE;
  F f;
  G g;
  H h;
  P p;
  vector<T> data;
  vector<E> lazy;
  QueryType *type;

  LazySegmentTree() {}
  LazySegmentTree(QueryType *type_) { type = type_; }
  LazySegmentTree(int n_, int setter, int getter,
      T initT_ = INT_MAX, E initE_ = INT_MAX, vector<T> v = vector<T>()) {
    setQuery(setter, getter, initT_, initE_);
    n = 1;
    while (n < n_) n *= 2;
    data.assign(n * 2 - 1, initT);
    lazy.assign(n * 2 - 1, initE);
    if (n_ == v.size()) build(v);
  }
  void build(vector<T> v) {
    for (int i = 0; i < v.size(); ++i) data[i + n - 1] = v[i];
    for (int i = n - 2; i >= 0; --i) {
      data[i] = f(data[i * 2 + 1], data[i * 2 + 2]);
    }
  }
  void setQuery(int setter, int getter, T initT_, E initE_) {
    initT = vector<T>{initT_, 0}[getter];
    initE = vector<E>{initE_, 0}[setter];
    f = vector<F>{minimum(), add()}[getter];
    g = vector<G>{ex_assign(initE), add()}[setter];
    h = vector<H>{ex_assign(initE), add()}[setter];
    p = ex_multiplies(initE);
  }
  inline void eval(int len, int k) {
    if (lazy[k] == initE) return;
    if (k * 2 + 1 < n * 2 - 1) {
      lazy[k * 2 + 1] = h(lazy[k * 2 + 1], lazy[k]);
      lazy[k * 2 + 2] = h(lazy[k * 2 + 2], lazy[k]);
    }
    data[k] = g(data[k], p(lazy[k], len));
    lazy[k] = initE;
  }
  T setData(int a, int b, E x) {
    LazySegmentTree<T, E> lst(new Setter());
    QueryObject obj(a, b, x);
    return lst.type->query(*this, QueryObject{a, b, x});
  }
  T getData(int a, int b) {
    LazySegmentTree<T, E> lst(new Getter());
    QueryObject obj(a, b);
    return lst.type->query(*this, QueryObject{a, b});
  }
};

int main() {
  cin.tie(0);
  ios::sync_with_stdio(false);

  int n, q; cin >> n >> q;
  LazySegmentTree<ll, ll> seg(n, LazySegmentTree<ll, ll>::Setter::RUQ, LazySegmentTree<ll, ll>::Getter::RSQ);

  while (q--) {
    int com; cin >> com;
    if (com) {
      int s, t; cin >> s >> t;
      cout << seg.getData(s, t + 1) << endl;
    } else {
      int s, t, x; cin >> s >> t >> x;
      seg.setData(s, t + 1, x);
    }
  }
  return 0;
}

