class RMQ{
public:
  typedef long long ll;
  ll INF = 1LL<<55;
  int n,n_;
  vector<ll> dat;
  int toMax;

  //初期化
  RMQ(){n=-1;}
  RMQ(int n_,int toMax = 0):n_(n_),toMax(toMax){
    n=1;
    while(n<n_)n*=2;
    dat.resize(2*n-1,INF);
  }

  //k番目の値をaに変更
  void update(int k,ll a){
    if(toMax) a *= -1;
    k+=n-1;
    dat[k]=a;
    while(k>0){
      k=(k-1)/2;
      dat[k]=min(dat[k*2+1],dat[k*2+2]);
    }
  }

  //[a,b)の最小値を求める query(a,b,0,0,n)
  ll find(int a,int b,int k,int l,int r){
    if(r<=a||b<=l)return INF;
    if(a<=l&&r<=b)return dat[k];
    ll vl = find(a,b,k*2+1,l,(l+r)/2);
    ll vr = find(a,b,k*2+2,(l+r)/2,r);
    return min(vl,vr);
  }

  ll find(int a,int b){
    assert(a <= b), assert(a <= n_ && b <= n_), assert(a >= 0 && a >= 0);
    return (toMax? -1:1) * find(a,b,0,0,n);
  }
};

