class SegTree
{
private:

	int size;

	vector<long long> lcmvalue;

	long long _query(int a, int b, int k, int l, int r)
	{
		if (r <= a || b <= l) { return 1; }
		if (a <= l && r <= b) { return lcmvalue[k]; }

		long long vl = _query(a, b, 2 * k, l, (l + r) / 2);
		long long vr = _query(a, b, 2 * k + 1, (l + r) / 2, r);

		return lcm(vl, vr) % 1000000007;
	}

public:

	SegTree(int size_)
	{
		for (size = 1; size < size_;) { size <<= 1; }

		lcmvalue = vector<long long>(size * 2, 1);
	}

	void update(int i, long long x)
	{
		i += size;

		lcmvalue[i] = x;

		while (i > 1)
		{
			i = i / 2;

			lcmvalue[i] = lcm(lcmvalue[2 * i], lcmvalue[2 * i + 1]) % 1000000007;
		}
	}

	long long query(int s, int t)
	{
		return _query(s, t, 1, 0, size);
	}
};


long long gcd(long long a, long long b)
{
	if (a == 0) { return b; }
	if (b == 0) { return a; }

	if (a > b) { return gcd(b, a % b); }

	return gcd(a, b % a);
}

long long lcm(long long a, long long b)
{
	return a / gcd(a, b) * b;
}

