}

void pushup(int rt)
{
    node[rt]=min(node[rt<<1|1],node[rt<<1]);
}

void update1(int rt,int left,int right,int target,int value)
{
    if(left==right){
        node[rt]=value;
        return ;
    }
    if(target<=mid) update1(lson,target,value);
    else if(target>mid) update1(rson,target,value);
    pushup(rt);
}

void update2(int target,int value)
{
    int v = target + n;
    node[v] =value;
    v /= 2;
    while (v > 0) {
        node[v] = min(node[2 * v], node[2 * v + 1]);
        v /= 2;
    }
}

int query(int rt,int left,int right,int L,int R)
{
    //printf("%d %d %d %d %d\n",rt,left,right,L,R);
    if(left==L&&R==right) return node[rt];
    if(R<left&&right<L) return INF;
    if(mid>=R) query(lson,L,R);
    else if(mid<L) query(rson,L,R);
    else return min(query(lson,L,mid),query(rson,mid+1,R));
}

