using namespace std;

void input(int n, int *x) {
	for (int i = 0; i < n; i++)
		x[i] = INT_MAX;
}

void init(int *s, int *x, int idx, int left, int right) {
	if (left == right) {
		s[idx] = x[left];
		return;
	}
	int mid = (left + right) / 2;
	init(s, x, 2 * idx, left, mid);
	init(s, x, 2 * idx + 1, mid + 1, right);
	s[idx] = min(s[2 * idx], s[2 * idx + 1]);
	return;
}

void update(int *s, int idx, int left, int right, int p, int val) {
	if (left == right) {
		s[idx] = val;
		return;
	}
	int mid = (left + right) / 2;
	if (p <= mid)
		update(s, 2 * idx, left, mid, p, val);
	else
		update(s, 2 * idx + 1, mid + 1, right, p, val);
	s[idx] = min(s[2 * idx], s[2 * idx + 1]);
	return;
}

int query(int *s, int idx, int left, int right, int l, int r) {
	if (l <= left && r >= right)
		return s[idx];
	if (l > right || r < left)
		return INT_MAX;
	return min(query(s, 2 * idx, left, (left + right) / 2, l, r), query(s, 2 * idx + 1, (left + right) / 2 + 1, right, l, r));
}

int main() {
	int n, x[100000], *s, q;
	s = new int[262143];
	cin >> n >> q;
	input(n, x);
	init(s, x, 1, 1, n);
	for (q; q > 0; q--) {
		int com, a, b;
		cin >> com >> a >> b;
		if (com == 0)
			update(s, 1, 1, n, a + 1, b);
		else
			cout << query(s, 1, 1, n, a + 1, b + 1);
	}
	delete[] s;
	return 0;
}

