template<typename item_type> struct min_segment_tree{
    int tree_size;
    vector<item_type> segment_tree_array;
    item_type identity_element;

    void resize(int size_number){
        tree_size = 1;
        while(tree_size < size_number){
            tree_size *= 2;
        }
        segment_tree_array.resize(tree_size);
        for(int i = 0; i < tree_size * 2 - 1; i++){
            segment_tree_array[i] = identity_element;
        }
    }

    void fill(int size_number, item_type value){
        tree_size = 1;
        while(tree_size < size_number){
            tree_size *= 2;
        }
        segment_tree_array.resize(tree_size);
        for(int i = 0; i < tree_size * 2 - 1; i++){
            segment_tree_array[i] = value;
        }
    }

    void change(int position, item_type value){
        position += tree_size - 1;
        segment_tree_array[position] = value;
        while(position){
            position = (position - 1) / 2;
            segment_tree_array[position] = min(segment_tree_array[position * 2 + 1], segment_tree_array[position * 2 + 2]);
        }
    }

    struct point{
        int now, point_left, point_right, back;
        item_type ans;
        bool calculated;
    };

    item_type calculation(int left, int right){
        return calcuration_recursion(left, right, 0, 0, tree_size);
    }

    item_type calcuration_recursion(int left, int right, int now, int point_left, int point_right){
        if(right <= point_left || point_right <= left){
            return identity_element;
        }else if(left <= point_left && point_right <= right){
            return segment_tree_array[now];
        }else{
            return min(calcuration_recursion(left, right, now * 2 + 1, point_left, (point_left + point_right) / 2),
                       calcuration_recursion(left, right, now * 2 + 2, (point_left + point_right) / 2, point_right));
        }
    }
};

int main(){
    int n, q;
    cin >> n >> q;
    min_segment_tree<int> segtree;
    segtree.identity_element = int((1l << 31) - 1);
    segtree.fill(n, (1 << 31) - 1);
    for(int i = 0; i < q; i++){
        int com, x, y;
        cin >> com >> x >> y;
        if(com){
            cout << segtree.calculation(x, y + 1) << endl;
        }else{
            segtree.change(x, y);
        }
    }
}

