template <typename T>
struct SegmentTree {
   private:
    vector<T> node;
    int n;
    function<T(T, T)> func;
    T init_v;

   public:
    // 初期化
    SegmentTree(vector<T> &a, function<T(T, T)> _func, T _init_v) {
        int sz = a.size();
        func = _func;
        init_v = _init_v;
        n = 1;
        while (n < sz) n *= 2;
        node.resize(2 * n, _init_v);
        for (int i = 0; i < sz; ++i) node[i + n - 1] = a[i];
        for (int i = n - 2; i >= 0; --i) node[i] = func(node[i * 2 + 1], node[i * 2 + 2]);
    }

    void update(int pos, T v) {
        int k = pos + n - 1;
        node[k] = v;
        while (k > 0) {
            k = (k - 1) / 2;
            node[k] = func(node[k * 2 + 1], node[k * 2 + 2]);
        }
    }

    T get(int pos) {
        int k = pos + n - 1;
        return node[k];
    }

    // [a, b)
    T query(int a, int b, int k = 0, int l = 0, int r = -1) {
        if (r < 0) r = n;
        if (r <= a || b <= l) return init_v;
        if (a <= l && r <= b) return node[k];
        T lv = query(a, b, k * 2 + 1, l, (l + r) / 2);
        T rv = query(a, b, k * 2 + 2, (l + r) / 2, r);
        return func(lv, rv);
    }
};

int main() {
    int n, q;
    cin >> n >> q;
    auto f = [](int a, int b) -> int { return a < b ? a : b; };
    vector<int> a(n, INT_MAX);
    SegmentTree<int> Sgt(a, f, INT_MAX);
    int com, x, y;
    while (q--) {
        cin >> com >> x >> y;
        if (com == 0) {
            // update
            Sgt.update(x, y);
        } else {
            // find
            cout << Sgt.query(x, y + 1) << endl;
        }
    }
    return 0;
}

