//===========================================
//===========================================

RMQ::RMQ(int size){
  init(size);
}
//@end RMQ()



void RMQ::init(int size){
  n=1;

  // calc necessary size of array
  while(n < size )n*=2;

  rangeMin.resize(2*n-1);
  for(int i=0; i<2*n-1; i++){
    rangeMin[i] = INF;
  }
}
//@end init()


void RMQ::update(int k, int a){
  k += n-1;
  rangeMin[k] = a;
  while( k>0 ){
    k = (k-1)/2;
    rangeMin[k] = min(rangeMin[k*2+1] , rangeMin[k*2+2]);
  }
}
//@end update()



int RMQ::find(int a, int b){
  return query(a, b+1, 0, 0, n);
}
//@end findMin()



int RMQ::query(int a, int b, int k, int l, int r){
  if( r <= a || b <= l )return INF;
  if( a <= l && r <= b )return rangeMin[k];

  int vl = query(a,b, k*2+1, l, (l+r)/2);
  int vr = query(a,b, k*2+2, (l+r)/2, r);
  return min(vr,vl);
}
//@end query()

