const ll sqrtN = 512;
const ll INF = (1LL << 31) - 1;

struct SqrtDecomposition {
	int N, K;
	vector<ll>data;
	vector<ll>bucketMin;
	SqrtDecomposition(ll n) :N(n) {
		K = (N + sqrtN - 1) / sqrtN;
		data.assign(K*sqrtN,INF);
		bucketMin.assign(K,INF);
	}
	void update(ll x, ll y) {
		ll k = x / sqrtN;
		ll minVal = data[x] = y;
		for (int i = k*sqrtN; i < (k + 1)*sqrtN; ++i)
			minVal = min(minVal, data[i]);
		bucketMin[k] = minVal;
	}
	int find(ll x, ll y) {
		ll minVal = INF;
		for (int k = 0; k < K; ++k) {
			ll l = k * sqrtN, r = (k + 1) * sqrtN;
			if (r <= x || y <= l)continue;
			if (x <= l && y >= r)
				minVal = min(minVal, bucketMin[k]);
			else {
				for (int i = max(x, l); i < min(y, r); ++i)
					minVal = min(minVal,data[i]);
			}
		}
		return minVal;
	}
};

int main()
{
	ll N, Q; cin >> N >> Q;
	SqrtDecomposition decomp(N);
	while (Q--) {
		int c, x, y;
		cin >> c >> x >> y;
		if (c == 0)decomp.update(x, y);
		else cout << decomp.find(x, y + 1) << endl;
	}
	return 0;
}

