const int kIntMax = INT_MAX;

class SegmentTree {
  public:
    SegmentTree(int _n)
    {
      n = 1;
      while (n < _n) {
        n = n << 1;
      }
      node.resize(2*n-1);
      std::fill(node.begin(), node.end(), kIntMax);
    }
    void update(int index, int x)
    {
      int i = n-1+index;
      node.at(i) = x;
      while (0 < i) {
        i = (i-1) / 2;
        node.at(i) = std::min(node.at(2*i+1), node.at(2*i+2));
      }
    }
    int find(int begin, int end)
    {
      _find(begin, end, 0, 0, n);
    }
  private:
    std::vector<int> node;
    int n;
    int _find(int begin, int end, int index, int tree_begin, int tree_end)
    {
      if (end <= tree_begin || tree_end <= begin) {
        return kIntMax;
      }
      if (begin <= tree_begin && tree_end <= end) {
        return node.at(index);
      }
      int l = _find(begin, end, 2*index+1, tree_begin, (tree_begin+tree_end)/2);
      int r = _find(begin, end, 2*index+2, (tree_begin+tree_end)/2, tree_end);
      return std::min(l, r);
    }
};

int main()
{
  int n, q;
  std::cin >> n >> q;
  //scanf("%d%d", &n, &q);
  SegmentTree tree(n);
  for (int i = 0; i < q; i++) {
    int com, x, y;
    std::cin >> com >> x >> y;
    //scanf("%d%d%d", &com, &x, &y);
    if (com == 0) {
      tree.update(x, y);
    } else if (com == 1) {
      std::cout << tree.find(x, y+1) << '\n';
      //printf("%d\n", tree.find(x, y+1));
    } else {
      std::cerr << "Unknown operation\n";
      //fputs("Unknown operation\n", stderr);
      exit(1);
    }
  }
  return 0;
}

