using ll = long long;
using namespace std;

template <class T> class SegTree {
    int N;
    vector<T> data;
    T ide; // Identity element (Initial value)
    function<T(T, T)> operation; // Function for range query
    function<T(T, T)> updater; // Function for point update

    T _query(int a, int b, int k, int l, int r) {
        if (r <= a || b <= l) return ide;
        if (a <= l && r <= b) {
            return data[k];
        } else {
            T left = _query(a, b, 2 * k + 1, l, (l + r) / 2);
            T right = _query(a, b, 2 * k + 2, (l + r) / 2, r);
            return operation(left, right);
        }
    }

public:
    // int n:                       Size of array
    // T ide:                       Identity element
    // function<T(T, T)> operation: Function to merge elements
    // function<T(T, T)> updater:    (old data[i], some value x) -> new data[i]
    SegTree(size_t n, T ide, function<T(T, T)> operation,
            function<T(T, T)> updater) : ide(ide), operation(operation), updater(updater) {
        N = 1;
        while (N < n) N *= 2;
        data.resize(2 * N - 1, ide);
    }

    void update(int i, T x) {
        i += N - 1;
        data[i] = updater(data[i], x);
        while (i > 0) {
            i = (i - 1) / 2;
            data[i] = operation(data[i * 2 + 1], data[i * 2 + 2]);
        }
    }

    T query(int a, int b) {
        return _query(a, b, 0, 0, N);
    }

    T operator[](int i) {
        return data[i + N - 1];
    }
};

// AOJ Range Minimum Query
int main() {
    int N, Q;
    cin >> N >> Q;

    ll ide = (1LL << 31) - 1;
    auto operation = [](ll left, ll right) -> ll { return min(left, right); };
    auto updater = [](ll old, ll x) -> ll { return x; };
    auto seg = new SegTree<ll>(N, ide, operation, updater);

    for (int q = 0; q < Q; q++) {
        int c, x, y;
        cin >> c >> x >> y;
        if (!c) seg->update(x, y);
        else cout << seg->query(x, y+1) << endl;
    }
}

#include<bits/stdc++.h>
using namespace std;
#define int long long
#define REP(i, n) for(int i=0;i<(n);++i)
#define ln '\n'
// Range Minimum Query
// abstracted

template <typename T, typename F>
struct SegmentTree {
	int n; T *dat;
	T identity; F merge;
	SegmentTree(F f, T id) : merge(f), identity(id){}
	void init(int siz){
		n = 1; while(n < siz) n <<= 1;
		dat = new T[n*2-1];
		REP(i, n*2-1) dat[i] = identity;
	}
	void set(int i, T x){
		dat[i+n-1] = x;
	}
	void build(void){
		for(int i = n-2; i >= 0; i--){
			dat[i] = merge(dat[i*2 + 1], dat[i*2 + 2]);
		}
	}
	void update(int i, T x){
		i += n-1;
		dat[i] = x;
		while(i > 0){
			i = (i-1) / 2;
			dat[i] = merge(dat[i*2 + 1], dat[i*2 + 2]);
		}
	}
	T query(int l, int r){  // [l, r)(0-indexed), 処理だけ 1-indexed で考える
		l += n, r += n;
		T res = identity;
		while(l < r){
			if(r & 1){
				--r; res = merge(res, dat[r-1]);
			}
			if(l & 1){
				res = merge(res, dat[l-1]);
				++l;
			}
			l >>= 1; r >>= 1;
		}
		return res;
	}
};

