	int N, Q; cin >> N >> Q;
	auto f = [](int a, int b){ return min(a, b); };
	SegmentTree<int, decltype(f)> seg(f, (1ll<<31)-1);
	seg.init(N);
	REP(_, Q){
		int com, x, y; cin >> com >> x >> y;
		if(com) cout << seg.query(x, y+1) << ln;
		else seg.update(x, y);
	}
}

