#include <iostream>
#include <vector>
#include <cmath>
#include <fstream>
#include <cstdlib>

#define DATA_MAX 100000
#define QUERY_MAX 100000

#define LEFT 0
#define RIGHT 1

using namespace std;

class SegTree{
    struct Node{
        int index;
        int value;
    };

private:
    vector<vector<Node> > Tree;
    const int MAX_VALUE;
    int DNum, QNum;

    Node min(Node &d1, Node &d2){
        return d1.value < d2.value ? d1 : d2;
    }

    void CreateTree(vector<Node>::size_type level){
        vector<Node>::size_type before;

        Tree.resize(Tree.size() + 1);
        before = Tree[level - 1].size();
        Tree[level].resize(before & 1 ? before / 2 + 1 : before / 2);

        for(vector<Node>::size_type i = 0; i < Tree[level].size(); i++){
            Tree[level][i].index = (int)(i * 2);
            Tree[level][i].value = MAX_VALUE;
        }

        if(Tree[level].size() == 1)
            return;

        CreateTree(Tree.size());
    }

    void UpDate(int x, int y){
        int target = x;
        Tree[0][target].value = y;

        for(vector<vector<Node> >::size_type level = 1; level < Tree.size(); level++){
            if(target == Tree[level - 1].size() - 1 && Tree[level - 1].size() & 1)
                Tree[level][target / 2] = Tree[level - 1][target];
            else
                Tree[level][target / 2] = min(Tree[level - 1][target], Tree[level - 1][target + (target & 1 ? -1 : 1)]);
            target /= 2;
        }
    }

    int Find(vector<vector<Node> >::size_type level, vector<Node>::size_type key, int x, int y){
        int right = -1, left = -1;

        if(x == y)
            return Tree[0][x].value;

        if(x <= Tree[level][key].index && Tree[level][key].index <= y)
            return Tree[level][key].value;

        if(level == 0)
            return -1;

        left = Find(level - 1, 2 * key, x, y);
        if(left == -1 || level == Tree.size() - 1)
            right = Find(level - 1, 2 * key + 1, x, y);

        if(level == Tree.size() - 1){
            //cout << "left = " << left << " right = " << right << endl;

            if(left == -1)
                return right;
            else if(right == -1)
                return left;
            else
                return left < right ? left : right;
        }
        else{
            return left == -1 ? right : left;
        }
    }

    void OutTree(){
        for(vector<vector<Node> >::size_type i = 0; i < Tree.size(); i++){
            for(vector<Node>::size_type j = 0; j < Tree[i].size(); j++){
                cout << "(" << Tree[i][j].index << ", " << Tree[i][j].value << ")  ";
            }
            cout << endl;
        }
        cout << endl << endl;
    }

public:
    SegTree() : MAX_VALUE(pow(2, 31) - 1){
        Tree.resize(1);
    }

    void Init(){
        cin >> DNum >> QNum;
        if(!(1 <= DNum && DNum <= DATA_MAX) || !(1 <= QNum && QNum <= QUERY_MAX))
            exit(1);

        Tree[0].resize(DNum);
        for(vector<int>::size_type i = 0; i < Tree[0].size(); i++){
            Tree[0][i].index = (int)i;
            Tree[0][i].value = MAX_VALUE;
        }

        CreateTree(Tree.size());

        //OutTree();
    }

    void ReadQuery(){
        int com, x, y;

        for(int c = 0; c < QNum; c++){
            cin >> com >> x >> y;
            if(com == 0){
                if(!(0 <= x && x < DNum) || !(0 <= y && y < MAX_VALUE))
                    exit(2);
                UpDate(x, y);
                //OutTree();
            }
            else if(com == 1){
                if(!(0 <= x && x < DNum) || !(0 <= y && y < DNum))
                    exit(3);
                cout << Find(Tree.size() - 1, 0, x, y) << endl;
            }
            else
                exit(4);
        }
    }
};

int main(){
    SegTree sg;

    sg.Init();
    sg.ReadQuery();

    return 0;
}

