template<typename T, typename E>
class SegTree{
	using F = function<T(T, T)>;
	using G = function<T(T, E)>;
	int32 n;
	F f;
	G g;
	T d0; // e0:F
	vector<T> node;
public:
	SegTree(int32 _n, F f, G g, T d0):f(f), g(g), d0(d0){
		init(_n);
	}
	SegTree(vector<T> v, F f, G g, T d0):f(f), g(g), d0(d0){
		node = v;
		init(v.size());
		for(int32 i = n-2;i >= 0;i--){
			node[i] = f(node[i*2+1], node[i*2+2]);
		}
	}

	void init(int32 _n){
		n = 1;
		while(n < _n) n *= 2;
		node.resize(2*n-1, d0);
	}

	void update(int32 k, E x){
		k += n-1;
		node[k] = g(node[k], x);
		while(k){
			k = (k-1)/2;
			node[k] = f(node[k*2+1], node[k*2+2]);
		}
	}

	T query(int32 a, int32 b, int32 k=0, int32 l=0, int32 r=-1){
		if(r < 0) r = n;
		if(b <= l || r <= a) return d0;
		if(a <= l && r <= b) return node[k];
		return f(query(a, b, k*2+1, l, (l+r)/2), query(a, b, k*2+2, (l+r)/2, r));
	}
};

