		seg[i] = INF;
}

void update(int k, int a) {

	k += n - 1;

	seg[k] = a;

	while (k > 0) {

		k = (k - 1) / 2;

		seg[k] = std::min(seg[k * 2 + 1], seg[k * 2 + 2]);
