class SegmentTree {
private:
  int N;
  vector<int> data;

  int parent(int k) { return (k - 1) / 2; }
  int left_child(int k) { return 2 * k + 1; }
  int right_child(int k) { return 2 * k + 2; }

  int rmq(int a, int b, int k, int l, int r) {
    if (r <= a || b <= l) return INF;
    if (a <= l && r <= b) return data[k];
    int vl = rmq(a, b, left_child(k), l, (l + r) / 2);
    int vr = rmq(a, b, right_child(k), (l + r) / 2, r);
    return min(vl, vr);
  }

public:
  SegmentTree(int n) {
    N = 1;
    while (N < n) N <<= 1; 
    data = vector<int>(2*N-1, INF);
  }

  void update(int p, int value) {
    p += N - 1;
    data[p] = value;

    while (0 < p) {
      p = parent(p);
      data[p] = min(data[left_child(p)], data[right_child(p)]);
    }
  }

  int rmq(int a, int b) {
    return rmq(a, b, 0, 0, N);
  }
};

