using namespace std;

const bool RED=false,BLACK=true;

struct RedBlackTree{
private:
  struct node_t{
    node_t *lch, *rch;
    bool color;
    int rank,size,val,mini;

    node_t(){
      lch=rch=NULL;
      color=BLACK;
      val=mini=INF;
      rank=0,size=1;
    }

    node_t(int val):val(val){
      mini=INF;
      lch=rch=NULL;
      rank=0;
      size=1;
    }

    node_t(node_t *lch,node_t *rch,bool col)
      :lch(lch),rch(rch),color(col){
      val=mini=INF;
      size=0;
    }

    bool isLeaf(){return !lch && !rch;}
  };

  node_t *root;

  inline node_t *node(int val){
    return update(new node_t(val));
  }

  inline node_t *node(node_t *l,node_t *r,bool col){
    return update(new node_t(l,r,col));
  }

  inline bool color(node_t *t){return !t?RED:t->color;}
  inline int size(node_t *t){return !t?0:t->size;}
  inline int mini(node_t *t){return !t?INF:t->mini;}
  inline int rank(node_t *t){return !t?0:t->rank;}

  inline node_t *update(node_t *t){
    if(!t)return t;
    t->size=size(t->lch)+size(t->rch)+t->isLeaf();
    t->mini=min(min(mini(t->lch),mini(t->rch)),t->val);
    t->rank=rank(t->rch)+color(t->rch);
    return t;
  }

  node_t *mergeSub(node_t *l,node_t *r){

    l=update(l),r=update(r);

    if(l->rank < r->rank){
      node_t *c=mergeSub(l,r->lch);
      if(r->color==BLACK && c->color==RED && c->lch->color==RED){
	if(r->rch->color==BLACK){
	  return node(c->lch,node(c->rch,r->rch,RED),BLACK);
	} else {
	  node_t *lch=node(c->lch,c->rch,BLACK);
	  node_t *rch=node(r->rch->lch,r->rch->rch,BLACK);	  
	  //node_t *lch=node(c->lch->lch,c->lch->rch,BLACK);
	  //node_t *rch=node(c->rch,r->rch,BLACK);
	  return node(lch,rch,RED);
	}
      }
      return node(c,r->rch,RED);
    }
    else if(l->rank > r->rank){
      node_t *c=mergeSub(l->rch,r);
      if(l->color==BLACK && c->color==RED && c->rch->color==RED){
	if(l->lch->color==BLACK){
	  return node(node(l->lch,c->lch,RED),c->rch,BLACK);
	} else {
	  node_t *lch=node(l->lch->lch,l->lch->rch,BLACK);
	  node_t *rch=node(c->lch,c->rch,BLACK);
	  //node_t *lch=node(l->lch,c->lch,BLACK);
	  //node_t *rch=node(c->rch->lch,c->rch->rch,BLACK);
	  return node(lch,rch,RED);
	}
      }
      return node(l->lch,c,RED);
    } 
    return node(l,r,RED);
  }

  node_t *insert(node_t *t,int k,int val){
    pair<node_t *,node_t *>s=split(t,k);
    node_t *tmp=node(val);
    t=merge(s.first,tmp);
    t=merge(t,s.second);
    return update(t);
  }

  node_t *erase(node_t *t,int k){
    pair<node_t *,node_t *>s1,s2;
    s2=split(t,k+1);
    s1=split(s2.first,k);
    delete s1.second;
    return update((t=merge(s1.first,s2.second)));
  }

  node_t *find(node_t *t, int k){
    pair<node_t *,node_t *>s1,s2;
    s2=split(t,k+1);
    s1=split(s2.first,k);
    node_t *res=s1.second;
    t=update((t=merge(s1.first,s1.second)));
    t=update((t=merge(t,s2.second)));
    return res;
  }

public:

  RedBlackTree():root(NULL){}

  node_t *merge(node_t *l,node_t *r){
    l=update(l),r=update(r);
    if(!l || !r)return l?l:r;
    node_t *c=mergeSub(l,r);
    if(c->color==RED)return node(c->lch,c->rch,BLACK);
    return update(c);
  }

  /*
  pair<node_t*,node_t*> split(node_t *a,int k){
    //a=update(a);
    if(k==0)return make_pair((node_t*)NULL,a);
    if(size(a)<=k)return make_pair(a,(node_t*)NULL);

    if(size(a->lch)>=k){
      pair<node_t*,node_t*>p=split(a->lch,k);
      return make_pair(p.first,merge(p.second,a->rch));
    } else {
      pair<node_t*,node_t*>p=split(a->rch,k-size(a->lch));
      return make_pair(merge(a->lch,p.first),p.second);
    }
    //return make_pair(update(a->lch),update(a->rch));
  }
  */

  pair<node_t*,node_t*> split(node_t *a,int k){
    a=update(a);
    if(k==0)return make_pair((node_t*)NULL,a);
    if(size(a)<=k)return make_pair(a,(node_t*)NULL);

    if(k<size(a->lch)){
      pair<node_t*,node_t*>p=split(a->lch,k);
      return make_pair(update(p.first),merge(p.second,a->rch));    
    } 
    else if(k>size(a->lch)){
      pair<node_t*,node_t*>p=split(a->rch,k-size(a->lch));     
      return make_pair(merge(a->lch,p.first),update(p.second));
    }
    return make_pair(update(a->lch),update(a->rch));
  }

  void insert(int k,int val){ root=insert(root,k,val); }
  void erase(int k){ root=erase(root,k); }
  node_t *find(int k){ return find(root,k); }

  void update(int id,int val){
    erase(id);
    insert(id,val);
  }

  int rmq(node_t *t, int l,int r){
    if(r<=0 || size(t)<=l)return INF;
    if(l<=0 && size(t)<=r)return mini(t);
    int szl=size(t->lch);
    int vl=rmq(t->lch,l,r);
    int vr=rmq(t->rch,l-szl,r-szl);
    return min(vl,vr);
  }

  int rangeMinimumQuery(int l,int r){

    return rmq(root,l,r);

    pair<node_t *,node_t *>s1,s2;
    s2=split(root,r);
    s1=split(s2.first,l);
    int res=mini(s1.second);
    root=merge(s1.first,merge(s1.second,s2.second));
    return res;
  }

  void revolve(int l,int r,int t){
    t%=(r-l);
    pair<node_t*, node_t*>a,b,c;
    c=split(root, r);
    b=split(c.first, r-t);
    a=split(b.first, l);
    cout << endl;
    for(int i=0;i<2;i++)cout << find(i)->val << " ";
    cout << endl;
    cout << endl;
    root=merge(a.first, b.second);
    root=merge(root, a.second);
    root=merge(root, c.second);
  }

  int getSize(){
    return size(root);
  }
};


