	scanf("%d%d", &N, &Q);
	RMQ<int> seg(N);
	while(Q--) {
		scanf("%d%d%d", &c, &x, &y);
		if(c == 0) seg.update(x, y);
		else printf("%d\n", seg.query(x, y + 1));
	}
}

