class RMQ{
public:

  int n;
  vector<int> A;

  const int INF = (1LL<<31)-1;

  RMQ(){}

  RMQ(int n_){
    n = 1;
    while( n_ > n ) n *= 2;
    n = n * 2 - 1;
    A.resize( n, INF );
  }

  void update(int x, int a){
    x += n / 2;
    A[x] = a;
    while(x){
      x = ( x + 1 ) / 2 - 1;
      A[x] = min( A[x*2+1], A[x*2+2] );
    }
  }

  int find(int a, int b, int l, int r, int k = 0){
    if( r <= a || b <= l ) return INF;
    if( a <= l && r <= b ) return A[k];
    int v1 = find( a, b, l, r-(l+r)/2, k*2+1 );
    int v2 = find( a, b, l+(l+r)/2, r, k*2+2 );
    return min( v1, v2 );
  }

};

