int find_min(int left,int right,int node,int nodeleft,int noderight)
{
    if(right < nodeleft ||left > noderight)
      return Max_INF;
    if(right >= noderight && left <= nodeleft)
      return range_min[node];
    int mid=(nodeleft+noderight)/2;
    int minleft=find_min(left,right,node*2,nodeleft,mid);
    int minright=find_min(left,right,node*2+1,mid+1,noderight);
    return Min(minleft,minright);
}

