{
    if(nodeleft > position || noderight < position) return range_min[node];
    if(nodeleft == noderight) return range_min[node]=new_value;
    int mid=(nodeleft+noderight)/2;
    int minleft=update(position,new_value,node*2,nodeleft,mid);
    int minright=update(position,new_value,node*2+1,mid+1,noderight);
    return range_min[node]=Min(minleft,minright);
}

