	for ( int i = p1 * k; i < min(n, (p1 + 1) * k); i ++ ) {
		dp[p1] = min( dp[p1], a[i] );
	}	
}

ll query (ll l, ll r ) {
	ll p1 = find(l), p2 = find(r);
	ll ret = inf;
	for ( int i = p1 + 1; i < p2; i++ ) {
		ret = min(ret, dp[i]);
	}
	for ( int i = l; i < min(r, min(n, (p1 + 1) * k)); i++ ) {
		ret = min(ret, a[i]);
	}
	for ( int j = max(l, p2 * k); j <= r; j++ )
		ret = min(ret, a[j]);
	return ret;
}
