inline int Calcu(int a,int b){
    return std::min(a,b);
}

class SegTree{
    private:
        int n;
        int g;
        std::vector<int> data;
    public:

        SegTree(std::vector<int> a, int _g){
            g = _g;
            for (n = 1; n < (int) a.size(); n *= 2);
            data.resize(n * 2, g);
            for (int i = 0; i < (int) a.size(); i++) data[i + n] = a[i];
            for (int i = n - 1; i >= 1; i--)
                data[i] = Calcu(data[i * 2], data[i * 2 + 1]);
        }
        int min_rec(int l, int r, int node, int node_l, int node_r) {
            if (node_r <= l || node_l >= r) return g;
            if (node_l >= l && node_r <= r) return data[node];
            int mid = (node_l + node_r) / 2;
            return Calcu(
                min_rec(l, r, node * 2, node_l, mid),
                min_rec(l, r, node * 2 + 1, mid, node_r));
        }

        int min(int l,int r){
            return min_rec(l,r,1,0,n);
        }

        void assign(int index, int val){
            data[index += n] = val;
            for(;index /= 2;)
                data[index] = Calcu(data[index * 2],data[index * 2 + 1]);
        }
};



