template<class T, class Upd>
struct SegmentTree {
    int n;
    Upd upd;
    vector<T> data;
    const T Lim;
    explicit SegmentTree(int n_, const T& Lim_)
        : upd(Upd()), Lim(Lim_) { init(n_);}
    void init(int n_) {
        for(n = 1; n < n_; n <<= 1);
        data.assign(2 * n - 1, Lim);
    }
    void update(int k, T a) {//0-indexed
        k += n - 1;
        data[k] = a;
        while(k > 0) {
            k = (k - 1) >> 1;
            data[k] = upd(data[k * 2 + 1], data[k * 2 + 2]); 
        }
    }
    T __query(int a, int b, int k, int l, int r) {
        if(r <= a || b <= l) return Lim;
        if(a <= l && r <= b) return data[k];
        else {
            T val_l = __query(a, b, k * 2 + 1, l, (l + r) >> 1);
            T val_r = __query(a, b, k * 2 + 2, (l + r) >> 1, r);
            return upd(val_l, val_r);
        }
    }
    T query(int a, int b) { //[a, b)
        return __query(a, b, 0, 0, n);
    }
};

