template<class T_monoid>
class SegmentTree {
private:
    int SegSize;
    vector<T_monoid> Segments;
    const T_monoid InitValue;
    function<T_monoid(T_monoid, T_monoid)> Func;
    //query
    T_monoid Q(int p, int q, int node, int l, int r) {
        if(r <= p || q <= l) return InitValue;
        if(p <= l && r <= q) return Segments[node];
        else {
            T_monoid child1 = Q(p, q, node*2+1, l, (l+r)/2);
            T_monoid child2 = Q(p, q, node*2+2, (l+r)/2, r);
            return Func(child1, child2);
        }
    }

public:
    //construcor
    SegmentTree(int n, function<T_monoid(T_monoid,T_monoid)> func, T_monoid InitValue):
        Func(func), InitValue(InitValue) //initialize
    {
        SegSize = 1;
        while(SegSize < n) SegSize <<= 1;
        Segments.assign(SegSize*2-1, InitValue);
    }

    //construct//
    void input(int index, T_monoid value) {
        Segments[index+SegSize-1] = value;
    }
    void build() { 
        for(int i = SegSize-2; i >= 0; --i) {
            Segments[i] = Func(Segments[i*2+1], Segments[i*2+2]);
        }
    }

    //member funcs//
    void update(int index, T_monoid value) {
        index += SegSize -1;
        Segments[index] = value;
        while(index != 0) {
            index = (index-1)/2;
            Segments[index] = Func(Segments[index*2+1], Segments[index*2+2]);
        }
    }

    //query for [p, q)
    T_monoid query(int s, int t) {
        return Q(s, t, 0, 0, SegSize);
    }

    int size() {
        return SegSize;
    }

    T_monoid operator[] (int index) {
        return Segments[index+SegSize-1];
    }
};

