struct Monoid {
    Monoid() {}
    using T = int;
    T operator()(const T& a, const T& b) {
        return a < b ? a : b;
    }
    T identity() {return std::numeric_limits<T>().max();}
};

class SegmentTree {
private:
    using T = Monoid::T;
    std::vector<T> seg;
    Monoid ope;
    const int size;
    const int cap;
public:
    SegmentTree() : size(0), cap(0) {}
    SegmentTree(const int &sz) : size(sz), cap(sz << 2), seg(sz << 2, ope.identity()) {}
    void update(int idx, const T &val) {
        ++idx;
        for (seg[idx += size] = val; idx > 1; idx >>= 1) {
            seg[idx >> 1] = ope(seg[idx], seg[idx ^ 1]);
        }
    }
    T get(int left, int right) {
        ++left; ++right;
        T res = ope.identity();
        for (left += size, right += size; left <= right; left >>= 1, right >>= 1) {
            if (left & 1) res = ope(res, seg[left++]);
            if (right & 1) res = ope(res, seg[--right]);
        }
        return res;
    }
};

