using namespace std;
const int psINF = 2147483647;
int tree[10000000*2-1];
int N;

void createTree(int n_){
    int n = 1;
    while (n < n_){
        n *= 2;
    }
    N = n;
    for (int i = 0; i < 2*N; ++i) {
        tree[i] = psINF;
    }

};
void updateTree(int index, int x){

    index += N -1;
    tree[index] = x;
    while(index > 0){
        index = (index - 1) / 2;
        tree[index] = min(tree[index*2+1],tree[index*2+2]);
    }
};

int query(int a, int b, int k, int l, int r){
    if( r < a || b < l ){
        return psINF;
    }
    if( a <= l && r <= b ){
        return tree[k];
    }else{
        int vl = query(a, b, k*2+1, l, (l+r)/2);
        int vr = query(a, b, k*2+2, (l+r)/2+1, r);
        return min(vl,vr);
    }

};

int RMQ(int a, int b){
    return query(a, b+1, 0, 0, N-1);
};

int main() {
    int q; // size of data set and number of queries
    int action, op1, op2; // action 0 - update ;  1 - find    
    cin >> N >> q;
    createTree(N);

    for (int i = 0; i < q; ++i) {
        cin >> action >> op1 >> op2;
        if (action == 0){
            updateTree(op1, op2);
        } else if(action == 1){
            cout << RMQ(op1, op2) << endl;
        }
    }
    return 0;
}

