	while(N<N_) N*=2;
	N*=2;
	for(int i=1;i<N;i++) seg[i]=INF;
}
void update(int Num,int value){
	int num=Num;
	seg[num]=value;
	num/=2;
	while(num>0){
		seg[num]=min(seg[num*2],seg[num*2+1]);
		num/=2;
	}
}
void query(int left,int right,int tree_num,int tree_left,int tree_right){
	if(left>tree_right||right<tree_left) return;
	if(right>=tree_right&&left<=tree_left){
		ANS=min(ANS,seg[tree_num]);
		return;
	}
	query(left,right,tree_num*2,tree_left,(tree_left+tree_right)/2);
	query(left,right,tree_num*2+1,(tree_left+tree_right)/2+1,tree_right);
}
