template <typename T>
class SegmentTree {
	const int n;
	const T id;
	function<T(T, T)> merge;
	vector<T> data;
public:
	SegmentTree(int n_, T id_, function<T(T, T)> merge_) :
		n(1 << (int)ceil(log2(n_))), id(id_), merge(merge_), data(n * 2, id) {}
	void Init(const vector<T>& data_) {
		for (int i = 0; i < (int)data_.size(); i++)
			data[i + n] = data_[i];
		for (int i = n - 1; i >= 0; i--)
			data[i] = merge(data[i * 2], data[i * 2 + 1]);
	}
	void Update(int p, T val) {
		p += n;
		data[p] = val;
		while (p >>= 1) data[p] = merge(data[p * 2], data[p * 2 + 1]);
	}
	T Find(int l, int r) {
		l += n; r += n + 1;
		T res1 = id, res2 = id;
		while (l < r) {
			if (l & 1) res1 = merge(res1, data[l++]);
			if (r & 1) res2 = merge(data[--r], res2);
			l >>= 1; r >>= 1;
		}
		return merge(res1, res2);
	}
};

