template<class T>
class SegmentTree
{
public:ssize_t
        long long n;
        std::vector<T> nodes;

        SegmentTree(std::vector<T> v)
        {
                long long sz = (long long)v.size();
                n = 1;
                while (n < sz) n *= 2;
                nodes.resize(2*n - 1, (1LL<<31)-1);

                for (long long i = 0; i < sz; ++i) {
                        nodes[(n-1) + i] = v[i];       
                }
                for (long long i = n-2; i >= 0; --i) {
                        nodes[i] = min(nodes[2*i + 1], nodes[2*i + 2]);
                }
        }

        void update(T pos, T val)
        {
                pos += n - 1;
                nodes[pos] = val;

                while (pos > 0) {
                        pos = (pos - 1) / 2;
                        nodes[pos] = min(nodes[2*pos + 1], nodes[2*pos + 2]);
                }
        }

        // [a, b]
        T find(T a, T b, T k=0, T l=0, T r=-1)
        {
                if (r < 0) {
                        r = n;
                        ++b;
                }
                if (r <= a or b <= l) return (1LL<<31)-1;
                if (a <= l and r <= b) return nodes[k];
                return min(
                        find(a, b, 2*k+1, l, (l+r)/2),
                        find(a, b, 2*k+2, (l+r)/2, r)
                );
        }


};





