template <typename T>
class Zip {
  vector<T> d;
  bool flag;
public:
  Zip() {
    flag = false;
  }
  void add(T x) {
    d.push_back(x);
    flag = true;
  }
  ll getNum(T x) { // T need to have operator < !!
    if (flag) {
      sort(d.begin(), d.end());
      d.erase(unique(d.begin(), d.end()), d.end());
      flag = false;
    }
    return lower_bound(d.begin(), d.end(), x) - d.begin();
  }
  ll size() {
    if (flag) {
      sort(d.begin(), d.end());
      d.erase(unique(d.begin(), d.end()), d.end());
      flag = false;
    }
    return (ll)d.size();
  }
};

/**** Union Find ****/

class UnionFind {
  vector<ll> par, rank; // par > 0: number, par < 0: -par
public:
  void init(ll n) {
    par.resize(n, 1); rank.resize(n, 0);
  }
  ll getSize(ll x) {
    return par[find(x)];
  }
  ll find(ll x) {
    if (par[x] > 0) return x;
    return -(par[x] = -find(-par[x]));
  }
  void merge(ll x, ll y) {
    x = find(x);
    y = find(y);
    if (x == y) return;
    if (rank[x] < rank[y]) {
      par[y] += par[x];
      par[x] = -y;
    } else {
      par[x] += par[y];
      par[y] = -x;
      if (rank[x] == rank[y]) rank[x]++;
    }
  }
  bool isSame(ll x, ll y) {
    return find(x) == find(y);
  }
};

/**** Segment Tree ****/
class SegmentTree {
public:
  vector<ll> node;
  ll n;//データの個数
  ll initial_value;
public:
  void Init(ll n_,ll initial_value_){
    n=1;
    while(n<n_)n*=2;
    node.resize(2*n);
    for(int i=0;i<2*n;i++){
      node[i]=initial_value_;
    }
    initial_value=initial_value_;
  }
  void Update(ll k,ll a){
    //k番目のやつをaにする
    //それに従って親も変わっていく
    k+=n;
    node[k]=a;
    while(k>0){
      k=k/2;
      node[k]=lmin(node[k*2],node[k*2+1]);
    }
  }
  void Watch(){
    for(ll i=0;i<2*n;i++){
      cout<<node[i]<<endl;
    }
  }
  ll Query(ll a,ll b,ll k,ll l,ll r){//[a,b)
    if(r<=a||b<=l)return initial_value;
    if(a<=l&&r<=b)return node[k];
    else{
      ll vl=Query(a,b,k*2,l,(l+r)/2);
      ll vr=Query(a,b,k*2+1,(l+r)/2,r);
      return lmin(vl,vr);
    }
  }
};


