class RMQ {

private:
	int n;
	int dat[2 * (1 << 17) - 1];
	const int INF = 2147483647;
public:
	RMQ() {};
	RMQ(int n) { init(n); }
	void init(int N_) {

		//要素数は2のべき乗にする
		n = 1;
		while (n < N_) { n *= 2; }




		//すべての値をINTMAXで初期化
		for (int i = 0; i < 2 * n - 1; i++) {
			dat[i] = INF;
		}

	}
	//dat[k]の値をaに変更する
	//葉を変更した後、節へ遡りながら値を変更していく
	void update(int k, int a) {
		k += n - 1;
		dat[k] = a;

		while (k > 0) {
			k = (k - 1) / 2;//indexの補正のためk-1をしてから２で割る
			dat[k] = min(dat[k * 2 + 1], dat[k * 2 + 2]);//最小値を格納する
		}
	}

	/*
	dat[a]〜dat[b]の範囲の最小値を求める

	kはこの節点のindex
	節点kはdat[l]〜dat[k]の範囲を担当している（これで通じるよね？）とする
	*/
	int query(int a, int b) {
		//return query(a, b , 0, 0, n);
		return query(a, b + 1, 0, 0, n);
	}

	int query(int a, int b, int k, int l, int r) {
		//求めたい範囲と担当範囲がかぶっていなかったのでINT_MAXを返す
		if (r <= a || b <= l) { return INF; }

		if (a <= l && r <= b) {
			return dat[k];
		}//求めたい範囲を完全に含んでいた場合はこの節点の値
		else {
			//一つ下に降りると担当範囲は1/2になる
			//２つの子の最小値を返す
			int vl = query(a, b, k * 2 + 1, l, (l + r) / 2);
			int vr = query(a, b, k * 2 + 2, (l + r) / 2, r);
			return min(vl, vr);
		}
	}


};

