template <typename T> class SegmentTree {
    const int array_size;        // もとの配列のサイズ
    int tree_size;               // segment treeで使う配列のサイズ
    std::vector<T> data;
    std::function<T (T,T)> op;
    T unit;

public:
    enum Mode {
        RangeMinimumQuery,
        RangeMaximumQuery,
    };

    SegmentTree(int array_size, Mode mode) : array_size(array_size) {
        if (mode == RangeMinimumQuery) {
            unit = INT_MAX;
            op = [](int a, int b) { return std::min(a, b); };
        }
        else if (mode == RangeMaximumQuery) {
            unit = -INT_MAX;
            op = [](int a, int b) { return std::max(a, b); };
        }

        tree_size = 1;
        while (tree_size < array_size) { tree_size *= 2; }   // _n以上の最小の2冪
        data.resize(2 * tree_size - 1, unit);
    }

    template <typename F> SegmentTree(int array_size, T unit, F op) : array_size(array_size), unit(unit), op(op) {
        while (tree_size < array_size) { tree_size *= 2; }   // _n以上の最小の2冪
        data.resize(2 * tree_size - 1, unit);
    }

    // 元の配列でのidxをxにし、木を更新
    void update(int idx, T x) {
        assert(0 <= idx and idx < array_size);
        idx += tree_size - 1;   // 木での対象のインデックス
        data[idx] = x;
        while (idx > 0) {
            idx = (idx - 1) / 2;                                    // 親のインデックス
            data[idx] = op(data[idx * 2 + 1], data[idx * 2 + 2]);   // 左の子と右の子
        }
    }

    // op(array[left, right))
    T query(int left, int right) {
        assert(0 <= left and left < right and right <= array_size);
        return query(left, right, 0, 0, tree_size);
    }

private:
    // [a, b)の目的値をノードk（区間[l, r]）から検索
    int query(int a, int b, int k, int l, int r) {
        assert(a < b && l < r);
        // 範囲外
        if (r <= a || b <= l) {
            return unit;
        }
        // 完全に含む
        if (a <= l && r <= b) {
            return this->data[k];
        }
            // 一部含む
        else {
            int vl = query(a, b, k * 2 + 1, l, (l + r) / 2);    // 左の子
            int vr = query(a, b, k * 2 + 2, (l + r) / 2, r);    // 右の子
            return op(vl, vr);
        }
    }
};



