struct SegmentTree {
    using func=function<Monoid(Monoid, Monoid)>;
    int n;
    vector<Monoid> seg;
    const func f;
    const Monoid e;
    SegmentTree(int len, func f, const Monoid e) : f(f), e(e) {
        n = 1;
        while (n < len)n *= 2;
        seg.assign(2 * n - 1, e);
    }
    SegmentTree(vi &dat, const func f, const Monoid e) : f(f), e(e) {
        n = 1;
        int asz = dat.size();
        while (n < asz)n *= 2;
        seg.assign(2 * n - 1, e);
        rep(i, asz) seg[i + n - 1] = Monoid(i, dat[i]);
        rer(i, n - 2)seg[i] = f(seg[i * 2 + 1], seg[i * 2 + 2]);
    }
    void update(int k, int v) {
        seg[k + n - 1] = Monoid(k, v);
        k += n - 1;
        while (k) {
            k = (k - 1) / 2;
            seg[k] = f(seg[k * 2 + 1], seg[k * 2 + 2]);
        }
    }
    void del(int k) {
        update(k, e.v);
    }
    void add(int k, int v) {
        update(k, v + seg[k + n - 1].v);
    }
    //高速なquery 葉から辿る
    Monoid query_bottomup(int l, int r) {
        Monoid ret = e;
        l += n - 1;
        r += n - 1;
        while (l < r) {
            //右なら、次に右上へ移動してしまうので
            if (!(l & 1)) {
                ret = f(ret, seg[l]);
            }
            //右なら、左を取らないと機会を逃す
            if (!(r & 1)) {
                ret = f(ret, seg[r - 1]);
            }
            l >>= 1;
            r = (r - 1) >> 1;
        }
        return ret;
    }
    Monoid query(int a, int b, int k, int l, int r) {
        if (r <= a || b <= l)return e;
        else if (a <= l && r <= b)return seg[k];
        else {
            Monoid sl = query(a, b, k * 2 + 1, l, (l + r) / 2);
            Monoid sr = query(a, b, k * 2 + 2, (l + r) / 2, r);
            return f(sl, sr);
        }
    }
    //***************************
    //入れ替えることでbottomupと入れ替えられる
//    Monoid get(int a = 0, int b = -1) { return query(a, b == -1 ? n : b, 0, 0, n); }
    Monoid get(int a = 0, int b = -1) { return query_bottomup(a, b == -1 ? n : b); }

    //***************************
    int geti(int a = 0, int b = -1) { return get(a, b).i; }
    ll getv(int a = 0, int b = -1) { return get(a, b).v; }
    int operator()(int a = 0, int b = -1) { return get(a, b).v; }
    Monoid operator[](int k) const { return seg[k + n - 1]; }
