template<typename T>
class segment_tree{
	int n;
	T fval;
	function<T(T,T)> operation;
	vector<T> dat;

	T _query(int a, int b, int k, int l, int r){
		if(r <= a || b <= l){
			return fval;
		}

		if(a <= l && r <= b){
			return dat[k];
		}else {
			T vl = _query(a, b, k * 2 + 1, l, (l + r) / 2 );
			T vr = _query(a, b, k * 2 + 2, (l + r) / 2, r);
			return operation(vl, vr);
		}
	}

public:

	segment_tree(){

	}

	segment_tree(int n_, T val, function<T(T,T)> fun){
		init(n_, val, fun);
	}

	void init(int n_, T val, function<T(T,T)> fun){
		fval = val;

		operation = fun;

		n = 1;

		while(n < n_) n *= 2;

		dat.resize(2 * n - 1);

		for(int i = 0; i < 2 * n - 1; i++) dat[i] = fval;
	}

	void update(int k, T a){
		k += n - 1;
		dat[k] = a;
		while(k > 0){
			k = (k - 1) / 2;
			dat[k] = operation(dat[k*2 + 1],dat[k*2 + 2]);
		}
	}

	T query(int a, int b){
		return _query(a, b, 0, 0, n);
	}

};

