// write [ StarrySkyTree<> sst(n) ] when using this snippet.
template<typename T = ll, bool QUERY_IS_GETMAX = true>
struct StarrySkyTree {
	std::vector<T> seg, laz;
	int size;
	T inf;
	std::function<T(T&, T&)> func;
	StarrySkyTree() {}
	StarrySkyTree(int n) : inf((QUERY_IS_GETMAX ? std::numeric_limits<T>::min() : std::numeric_limits<T>::max())), func([](T& a, T& b) {return (QUERY_IS_GETMAX ? std::max(a, b) : std::min(a, b)); }) {
		init(n);
	}
	void init(int n) {
		size = 1;
		while (size < n) size *= 2;
		seg.resize(size * 2);
		laz.resize(size * 2);
	}
	void push(int k, int l, int r) {
		seg[k] += laz[k];
		if (r - l > 1) {
			laz[k * 2 + 1] += laz[k];
			laz[k * 2 + 2] += laz[k];
		}
		laz[k] = 0;
	}
	void update(int a, int b, T v, int k, int l, int r) {
		push(k, l, r);
		if (r <= a || b <= l) return;
		if (a <= l && r <= b) {
			laz[k] += v;
			push(k, l, r);
		}
		else {
			update(a, b, v, k * 2 + 1, l, (l + r) / 2);
			update(a, b, v, k * 2 + 2, (l + r) / 2, r);
			seg[k] = func(seg[k * 2 + 1], seg[k * 2 + 2]);

		}
	}
	// add v to [a,b)
	void update(int a, int b, T v) {
		update(a, b, v, 0, 0, size);
	}
	T query(int a, int b, int k, int l, int r) {
		push(k, l, r);
		if (r <= a || b <= l) return inf;
		if (a <= l && r <= b) return seg[k];
		T vl = query(a, b, k * 2 + 1, l, (l + r) / 2);
		T vr = query(a, b, k * 2 + 2, (l + r) / 2, r);
		return func(vl, vr);
	}
	// return min(or max) in [a,b)
	T query(int a, int b) {
		return query(a, b, 0, 0, size);
	}
};

// ------------>8---------- LazySegmentTree ---------->8------------

// write [ LazySegmentTree st(n, SUM/MAX/MIN, ADD/UPD) ] when using this snippet.
enum QUERY_SEG_LazySegmentTree { SUM, MAX, MIN };
enum QUERY_LAZ_LazySegmentTree { ADD, UPD };
template<class SEG, class LAZ>
class LazySegmentTree {
private:
	std::vector<SEG> seg;
	std::vector<LAZ> laz;
	std::vector<bool> isUpdated;
	int ARY_SIZE;
	SEG eSeg;
	LAZ eLaz;
	std::function<SEG(SEG&, SEG&)> mergeSeg;
	std::function<LAZ(LAZ&, LAZ&)> mergeLaz;
	std::function<SEG(SEG&, LAZ&, int)> applyLaz;

	void push(int k, int l, int r) {
		if (!isUpdated[k]) {
			seg[k] = applyLaz(seg[k], laz[k], r - l);
			if (r - l > 1) {
				mergeLaz(laz[k * 2 + 1], laz[k]); isUpdated[k * 2 + 1] = false;
				mergeLaz(laz[k * 2 + 2], laz[k]); isUpdated[k * 2 + 2] = false;
			}
			isUpdated[k] = true;
			laz[k] = eLaz;
		}
	}
public:
	LazySegmentTree(int n, QUERY_SEG_LazySegmentTree qSeg, QUERY_LAZ_LazySegmentTree qLaz) : ARY_SIZE(1) {
		ARY_SIZE = 1;
		while (ARY_SIZE < n) ARY_SIZE *= 2;
		seg.resize(ARY_SIZE * 2 - 1);
		laz.resize(ARY_SIZE * 2 - 1);
		isUpdated.resize(ARY_SIZE * 2 - 1, true);

		switch (qSeg) {
			case SUM:
				eSeg = 0;
				mergeSeg = [](SEG& l, SEG& r) { return l + r; };
				break;
			case MAX:
				eSeg = std::numeric_limits<SEG>::lowest();
				mergeSeg = [](SEG& l, SEG& r) { return std::max(l, r); };
				break;
			case MIN:
				eSeg = std::numeric_limits<SEG>::max();
				mergeSeg = [](SEG& l, SEG& r) { return std::min(l, r); };
				break;
			default:
				struct INVALID_QUERY_TYPE_ERROR {};
				throw INVALID_QUERY_TYPE_ERROR();
				break;
		}

		switch (qLaz)
		{
			case ADD:
				eLaz = 0;
				mergeLaz = [](LAZ& l, LAZ& r) { return l += r; };
				if (qSeg == SUM) applyLaz = [](SEG& s, LAZ& l, int w) { return s += l * w; };
				else applyLaz = [](SEG& s, LAZ& l, int w) { return s += l; };
				break;
			case UPD:
				eLaz = 0;
				mergeLaz = [](LAZ& l, LAZ& r) { return l = r; };
				if (qSeg == SUM) applyLaz = [](SEG& s, LAZ& l, int w) { return s = l * w; };
				else applyLaz = [](SEG& s, LAZ& l, int w) { return s = l; };
				break;
			default:
				struct INVALID_QUERY_TYPE_ERROR {};
				throw INVALID_QUERY_TYPE_ERROR();
				break;
		}
	}
	void update(int a, int b, SEG v, int k, int l, int r) {
		push(k, l, r);
		if (r <= a || b <= l) return;
		if (a <= l && r <= b) {
			LAZ la(v);
			mergeLaz(laz[k], la);
			isUpdated[k] = false;
			push(k, l, r);
		}
		else {
			update(a, b, v, k * 2 + 1, l, (l + r) / 2);
			update(a, b, v, k * 2 + 2, (l + r) / 2, r);
			seg[k] = mergeSeg(seg[k * 2 + 1], seg[k * 2 + 2]);
		}
	}
	// add v to [a,b)
	void update(int a, int b, SEG v) {
		update(a, b, v, 0, 0, ARY_SIZE);
	}
	SEG query(int a, int b, int k, int l, int r) {
		push(k, l, r);
		if (r <= a || b <= l) return eSeg;
		if (a <= l && r <= b) return seg[k];
		SEG vl = query(a, b, k * 2 + 1, l, (l + r) / 2);
		SEG vr = query(a, b, k * 2 + 2, (l + r) / 2, r);
		return mergeSeg(vl, vr);
	}
	// return min(or max) in [a,b)
	SEG query(int a, int b) {
		return query(a, b, 0, 0, ARY_SIZE);
	}
};

using LST = LazySegmentTree<ll, ll>;
// ------------>8---------- LazySegmentTree ---------->8------------

signed main() {
	INIT;

	VAR(int, n, Q);

	LST lst(n, MIN, UPD);
	REP(i, n) lst.update(0, n, (1 << 30) - 1 + (1 << 30));
	REP(_, Q) {
		VAR(int, c, x, y);
		if (c == 0) {
			lst.update(x, x + 1, y);
		}
		else {
			OUT(lst.query(x, y + 1))BR;
		}
	}

	return 0;
}

