template<class T>
class SqrtDecomp {
private:
    const size_t B, _size;
    T const init;
    vector<T> a, b;

public:
    SqrtDecomp(const size_t size = 0,
               T const &init = numeric_limits<T>::max(),
               const size_t B = 150)
        : B(B), _size(size), init(init),
          a(size, init), b(size/B + 1, init){}

    SqrtDecomp(const vector<T> &a, const size_t B = 150)
        : B(B), _size(a.size()), init(numeric_limits<T>::max()),
          a(a), b(_size/B + 1, init){
        for(size_t i = 0; i < a.size(); i++){
            b[i/B] = min(b[i/B], a[i]);
        }
    }

    size_t size() const {
        return _size;
    }

    T get(const size_t &l, const size_t &r) const {
        T res = numeric_limits<T>::max();
        size_t i = l;
        while(i < r){
            if(i%B == 0 && i + B <= r){
                res = min(res, b[i/B]);
                i += B;
            } else {
                res = min(res, a[i]);
                i++;
            }
        }
        return res;
    }

    void set(const size_t &p, const T &x){
        a[p] = x, b[p/B] = init;
        size_t s = p/B, end = min(p - p%B + B, size());
        for(size_t i = p - p%B; i < end; i++){
            b[s] = min(b[s], a[i]);
        }
    }

    vector<T> to_a(int l = -1, int r = -1){
        if(l == -1) l = 0;
        if(r == -1) r = size();
        vector<T> res(r-l);
        for(int i = l; i < r; i++) res[i-l] = get(i,i+1);
        return res;
    }
};

