    vector<int> v; v.assign(N,0);
    for (int i=0; i<N; i++) v[i] = INT_MAX;

    SegmentTree st(v);

    for (int i=0; i<Q; i++){
        int op;
        cin >> op;

        if (op == 0){                       // modify v[p] to val
            int p, val;
