const int INF = 2147483647;

struct Traits{
	typedef int val_t;
	Traits(){}
	val_t def_val(){ return INF; }
	val_t prop(const val_t &l, const val_t &	r){
		return min(l, r);
	}
};

template<typename T>
struct SegTree{
	typedef typename T::val_t val_t;
	vector<val_t> val;
	T tr;
	int n;

	SegTree(int size):tr(){
		n=1;
		while(n<size) n<<=1;
		val=vector<val_t>(2*n, tr.def_val());
	}
	SegTree(const vector<val_t> &in):tr(){
		n=1;
		while(n<in.size()) n<<=1;
		val=vector<val_t>(2*n, tr.def_val());
		for(int i=n-1 + in.size()-1;i>=0;i--){
			if(n-1 <= i) val[i] = in[i - (n-1)];
			else val[i] = tr.prop(val[i*2+1],val[i*2+2]);
		}
	}
	//i 番目の要素を a に更新する
	void update(int i,val_t a){
		i += n-1;
		val[i] = a;
		while(i > 0){
			i = (i-1)/2;
			val[i] = tr.prop(val[i*2+1],val[i*2+2]);
		}
	}
	//[a, b) の値を取ってくる
	val_t query(int a,int b,int k,int l,int r){
		if(r<=a||b<=l) return tr.def_val();
		if(a<=l&&r<=b) return val[k];
		return tr.prop(query(a, b, k*2+1, l, (l+r)/2),
					   query(a, b, k*2+2, (l+r)/2, r)
					  );
	}
	val_t query(int a, int b){
		return query(a, b, 0, 0, n);
	}
};


