struct None {} none;
template<class T> struct optional {
  bool b; T t;
  optional() : b(false), t() {}
  optional(None rhs) : b(false), t() { (void)rhs; }
  optional(T t) : b(true), t(t) {}
  operator bool() const { return b; }
  T& operator*() { return t; }
  auto& operator=(None rhs) { (void)rhs; b=false; return *this; }
  auto& operator=(T const& rhs) { b=true; t = rhs; return *this; }
};


template <class T, class Op> struct OptionalSegmentTree { // (M, op) : monoid
  using size_t = std::size_t;
  Op o; size_t n; std::vector<optional<T>> dat;
  OptionalSegmentTree() {}
  OptionalSegmentTree(Op o, size_t n_=0) : o(o), n(0), dat() { init(n_); }
  void init(size_t const& n_) { n=1; while(n<n_) n<<=1; dat.assign(2*n, none); }
  void build(std::vector<T> const& v) {
    size_t n_ = v.size(); init(n_);
    for(size_t i=0;i<n_;++i) dat[n+i] = v[i];
    for(size_t i=n;i-->0;) dat[i] = op(dat[i<<1], dat[i<<1|1]);
  }
  auto op(optional<T> x, optional<T> y) {
    optional<T> r;
    if(x) if(y) r = o(*x, *y); else r = x; else r = y;
    return r;
  }
  auto operator[](size_t const& i) const { return dat[n+i]; }
  void update(size_t k) { while(k>>=1) dat[k] = op(dat[k<<1], dat[k<<1|1]); }
  void set(size_t k, T const& v) { dat[k+=n] = v; update(k); }
  auto get(size_t a, size_t b) { // [a. b)
    optional<T> l, r;
    for(a+=n, b+=n; a<b; a>>=1, b>>=1) {
      if(a & 1) l = op(l, dat[a++]);
      if(b & 1) r = op(dat[--b], r);
    }
    return op(l, r);
  }
};
template <class T, class Op> auto make_optseg(Op op, std::size_t n=0) { return OptionalSegmentTree<T, Op>(op, n); }



