typedef long long ll;
const int INT_MAX = (1 << 31) - 1;

// RMQ
class SqrtDecomp{
    private:
        int N, sqrtN, K;
        vector<int> data;
        vector<int> min_bucket;
    public:
        SqrtDecomp(int N);
        void update(int i, int x);
        int query(int a, int b);
};

SqrtDecomp::SqrtDecomp(int n){
    N = n;
    sqrtN = ceil(sqrt(N));
    K = N / sqrtN;
    for(int i=0; i<K*sqrtN; i++){
        data.push_back(INT_MAX);
    }
    for(int i=0; i<sqrtN; i++){
        min_bucket.push_back(INT_MAX);
    }
}

void SqrtDecomp::update(int i, int x){
    int b_idx = i / sqrtN;
    int l = b_idx*sqrtN, r = (b_idx+1)*sqrtN;
    data[i] = x;
    min_bucket[b_idx] = INT_MAX;
    for(int i=l; i<r; i++){
        min_bucket[b_idx] = min(min_bucket[b_idx], data[i]);
    }

}

// [a, b)
int SqrtDecomp::query(int a, int b){
    int res = INT_MAX;
    for(int i=0; i<K; i++){
        int l = i*sqrtN, r = (i+1)*sqrtN;
        if (b < l || r <= a) continue;
        else if (a <= l && r <= b){
            res = min(res, min_bucket[i]);
        }else{
            for(int i=max(a, l); i<min(b, r); i++) res = min(res, data[i]);
        }
    }
    return res;
}

int main(){
    int n, q; cin >> n >> q;
    SqrtDecomp sd(n);
    for(int i=0; i<q; i++){
        int com, x, y; cin >> com >> x >> y;
        if (com == 0) sd.update(x, y);
        else cout << sd.query(x, y+1) << endl;
    }
}

