class SegTreeRMQ{
public:
    SegTreeRMQ(int N){
        init(N);
    }
    void init(int N){
        int s = 1;
        while(s < N){
            s*=2;
        }
        dat = std::vector<int>(s,2147483647);
        n = s;
    }
    void update(int i,int x){
        i += n - 1;
        dat[i]= x;
        while(i > 0){
            i = (i-1) / 2;
            dat[i] = min(dat[i * 2 + 1],dat[i * 2 + 2]);
        }
    }
    //使う時は変数名.query(a,b,k,l,変数名getSize())
    int query(int a,int b,int k,int l,int r){
        if(a == b){
            return dat[a+n/2];
        }
      //  cout<<k<<endl;
        if(r <= a || b<= l)return 2147483647;
        if(a <= l && r <= b)return dat[k];
        else{
            int vl = query(a,b,k * 2 + 1,l,(l+r)/2);
            int vr = query(a,b,k * 2 + 2,(l+r)/2,r);
            return min(vl,vr);
        }
    }
    int getSize(){
        return n;
    }
    void show(){
        for(int a = 0;a < dat.size();a++){
            cout<<dat[a]<<" ";
        }
        cout<<endl;
        return;
    }
private:
    int n;
    std::vector<int> dat;
};

