int find(int from, int to) {

#ifdef debug
    dout << "------ find( " << from << ", " << to << ")\n";
#endif

    assert(from<=to);
    assert(to<N);


    int i = from + pow2k;
    int j = to + pow2k;

    int ans = INF;

    int limit = pow2k;

#ifdef debug
    disp(i);
    disp(j);
    disp(limit);
    disp(ans);
#endif
    while( i<j and limit<=i and j<2*limit ) {

        if( i==r(p(i)) ) ans = min(ans, a[i]), i = p(i) + 1;
        else i = p(i);

        if( j==l(p(j)) ) ans = min(ans, a[j]), j = p(j) - 1;
        else j = p(j);

        limit /= 2;

#ifdef debug
        dout << "--- while-loop --- \n";
        disp(i);
        disp(j);
        disp(limit);
        disp(ans);
#endif
    }

    if( i==j and limit<=i and j<2*limit ) {
#ifdef debug
        dout << "--- last check --- \n";
        dout << "check a[" << i << "] = " << a[i] << endl;
#endif
        assert(i==j);
        ans = min( ans, a[i] );
    }

#ifdef debug
    dout << "--- FINAL --- \n";
    disp(i);
    disp(j);
    disp(limit);
    disp(ans);
#endif
    return ans;

}


