using namespace std;
using T=int;

class SegmentTree{

    vector<T> dat;
    int N;
    T E;
    function<T(T,T)> merge;
    T query_impl(int a,int b,int k,int l,int r){
        if(a<=l && r<=b) return dat[k];
        if(r<=a || b<=l) return E;
        int mid=(l+r)/2;
        T c1v=query_impl(a,b,k*2+1,l,mid);
        T c2v=query_impl(a,b,k*2+2,mid,r);
        return merge(c1v,c2v);
    }
    public:
    SegmentTree(size_t N,function<T(T,T)> merge,T E):E(E),merge(merge){
        while(this->N<N){
            this->N*=2;
        }
        dat.assign(this->N*2-1,E);
    }
    void update(int pos,T val){
        pos+=N-1;
        dat[pos]=val;
        while(pos!=0){
            int par=(pos-1)/2;
            int c1=par*2+1;
            int c2=par*2+2;
            dat[par]=merge(dat[c1],dat[c2]);
            pos=par;
        }
    }
    T query(int a,int b){
        assert(a<=b);
        return query_impl(a,b,0,0,N);
    }

};

T mymin(T a,T b){return min(a,b);}
