class SegmentTree{
    private:
        const int INTINF = ((1 << 31) - 1);
        static const int MAX_N = 1 << 17;
        int n, dat[2 * MAX_N -1];

    public:
        void init(int n_){
            n = 1;
            while(n < n_) n*= 2;
            for(int i=0; i< 2*n-1; i++) dat[i] = INTINF;
        }

        // k番目の値(0-indexed)をaに変更
        void update(int k, int a){
            k += n-1;
            dat[k] = a;
            while(k > 0){
                k = (k-1) /2;
                dat[k] = min(dat[k*2 + 1], dat[k * 2 + 2]);
            }
        }

        //[a, b)の最小値を求める
        int simple_query(int a, int b){
            return query(a, b, 0, 0, n);
        }

        int query(int a, int b, int k, int l, int r){
            if(r <= a || b <= l) return INTINF;

            if(a <= l && r <= b) return dat[k];
            else{
                int vl = query(a, b, k * 2 + 1, l, (l + r) / 2);
                int vr = query(a, b, k * 2 + 2, (l + r) / 2, r);
                return min(vl, vr);
            }
        }

        // 全てのノードの値を表示
        void debug(){
            for(int i=0; i<n * 2 -1; i++){
                if(i == n-1) cout << "leaf->" << endl;
                cout << dat[i] << endl;
            }
        }
};


