	int range_value(node_treap<T> *t) { return !t ? def() : t->range_value; }

	node_treap<T> *update(node_treap<T> *t) {
		t->count = count(t->ch[0]) + count(t->ch[1]) + 1;
		t->range_value = operation(operation(range_value(t->ch[0]), range_value(t->ch[1])), t->range_value);
		return t;
	}

	// ?????????????????¨???????????????
	node_treap<T> *Merge(node_treap<T> *l, node_treap<T> *r) {
		if (!l || !r)return !l ? r : l;

		if (l->priority > r->priority) {
			l->ch[1] = Merge(l->ch[1], r);
			return update(l);
		}
		else {
			r->ch[0] = Merge(l, r->ch[0]);
			return update(r);
		}
	}

