struct Segtree {
	ll n;
	vector<ll>node;
	Segtree(vector<ll>v) {
		int size = v.size();
		n = 1; while (n < size)n *= 2;//最下段の個数
		node.resize(2 * n - 1, LLINF);//全体の個数は2n-1
		rep(i, size)node[i + n - 1] = v[i];//最下段
		for(ll i = n - 2; i >= 0; --i)node[i] = min(node[i * 2 + 1], node[i * 2 + 2]);//下から更新
	}
	void update(ll x,ll num) {
		x += (n - 1);
		node[x] = num;
		while (x > 0) {
			x = (x - 1) / 2;
			node[x] = min(node[x * 2 + 1], node[x * 2 + 2]);
		}
	}
	ll find(ll s, ll t, ll p = 0,ll l=0,ll r=-1) {
		if (r < 0)r = n;
		if (r <= s || t <= l)return LLINF;//範囲外
		if (s <= l && r <= t)return node[p];//完全に含む
		ll ln = find(s, t, 2 * p + 1, l, (l + r) / 2);
		ll rn = find(s, t, 2 * p + 2, (l + r) / 2,r);
		return min(ln, rn);
	}
};
