namespace SegmentTrees{

    template<typename T>
    class RmQ{
    private:
        vector<T> dat;
        int Pow2Fit(int n){
            int d=1;while((d<<1)<=n)d<<=1;return d;
        }
    public:
        int n,size;
        RmQ(int _n){
            n=Pow2Fit(_n)<<1;
            size=2*n-1;
            dat=vector<T>(size,INF<T>());
        }
        void set(int v,T a){
            v+=n-1;
            dat[v]=a;
            while(v>0){
                int parent=v=(v-1)/2;
                int chl=parent*2+1,chr=parent*2+2;
                dat[parent]=min(dat[chl],dat[chr]);
            }
        }
        T get(int v){//v
            return dat[v+n-1];
        }
        T query(int a,int b){//[a,b)
            return query(0,a,b,0,n);
        }
    private:
        T query(int v,int a,int b,int l,int r){//[a,b)
            if(r<=a || b<=l)return INF<T>();//out range
            if(a<=l && r<=b)return dat[v];

            T vl=query(v*2+1,a,b,l,(l+r)/2),vr=query(v*2+2,a,b,(l+r)/2,r);
            return min(vl,vr);
        }
    };
}
