template<typename T>
struct SegmentTree{
    vector<T> data;
    ll sz=1;

    SegmentTree(ll n){
        while(sz<n)sz<<=1;
        data.resize(2*sz,T::e);
    }

    void set(ll k,T node){
        data[k+sz]=node;
    }

    void build(){
        rrep(i,1,sz)data[i]=data[2*i]*data[2*i+1];
    }

    void update(ll k,T node){
        k+=sz;
        data[k]=node;
        while(k>1){
            k>>=1;
            data[k]=data[2*k]*data[2*k+1];
        }
    }

    T query(ll a,ll b,ll l=0,ll r=-1,ll k=1){
        if(r==-1)r=sz;
        if(r<=a||b<=l)return T::e;
        if(a<=l&&r<=b)return data[k];
        return query(a,b,l,(l+r)/2,2*k)*query(a,b,(l+r)/2,r,2*k+1);
    }

    T operator[](const ll &k)const{
        return data[k+sz];
    }
};

