	for (int i = n - 2; i >= 0; i--) { node[i] = min(node[2 * i + 1], node[2 * i + 2]); }

}
int find(int x,int y,int k,int l,int r, vector<int>& node) {
	if (r <= x || y <= l)return INT_MAX;
	if (x <= l && r <= y) return node[k];

