int n, q;
int mx[105000];

int init(int n_)
{
	int n = 1;
	while (n < n_)n *= 2;
	for (int i = 0; i < 2 * n; i++) {
		mx[i] = (1 << 30) - 1 + (1 << 30);
	}
	return n;
}

void update(int ind, int val)
{
	ind += n;
	mx[ind] = val;
	ind /= 2;
	while (ind > 0) {
		int l = mx[2 * ind];
		int r = mx[2 * ind + 1];
		mx[ind] = min(l, r);
		ind /= 2;
	}
}

int find(int l, int r, int bottom = 0, int top = n, int node = 1)
{
	if (l <= bottom&&top <= r)return mx[node];
	if (top <= l || r <= bottom)return INF;

	int mid = (bottom + top) / 2;
	int lmx = find(l, r, bottom, mid, 2 * node);
	int rmx = find(l, r, mid, top, 2 * node + 1);

	return min(lmx, rmx);
}


int main()
{
	cin >> n >> q;

	n=init(n);

	int k, x, y;
	for (int i = 0; i < q; i++) {
		cin >> k >> x >> y;
		if (k == 0)update(x, y);
		if (k == 1)cout<<find(x, y + 1,0,n,1)<<endl;
	}

	return 0;
}

