struct SegmentTree{
	vector<int> data;
	int sz;

	SegmentTree(int n){
		sz = getsize(n);
		data.assign(sz*2, unit());
	}

	int unit(){
		return (1LL<<31)-1;
	}

	int getsize(int n){
		int ret = 0;
		while((1<<ret)<=n) ret++;
		return (1<<ret);
	}

	int update(int k,int x){
		k += sz-1;
		data[k] = x;
		while(k){
			k = (k-1)/2;
			data[k] = min(data[2*k+1], data[2*k+2]);
		}

		return 0;
	}

	int get(int a,int b){
		return _get(a,b,0,0,sz);
	}

	int _get(int a, int b, int k, int l, int r){
		if(b<=l||r<=a) return unit();
		if(a<=l&&r<=b) return data[k];

		return min(_get(a,b,2*k+1,l,(l+r)/2), _get(a,b,2*k+2,(l+r)/2,r));
	}

	int size(){
		return sz;
	}

	int find(int k){
		return data[k];
	}
};

