template<typename T>
struct RangeMinimumQuery {
    const T INF;
    int n;
    std::vector<T> val;

    RangeMinimumQuery(int size, T inf = std::numeric_limits<T>::max()) : INF(inf) {
        for (n = 1; n < size; ) n <<= 1;
        val.assign(2 * n + 1, INF);
    }
    void update(int idx, T v) {
        idx += n - 1;
        val[idx] = v;
        while (idx > 0) {
            idx = (idx - 1) >> 1;
            val[idx] = std::min(val[idx * 2 + 1], val[idx * 2 + 2]);
        }
    }
    T find(int l, int r) {
        T res = INF;
        l += n - 1; r += n - 1;
        while (l < r) {
            if (!(l & 1)) res = std::min(res, val[l]);
            if (!(r & 1)) res = std::min(res, val[r - 1]);
            l >>= 1;
            r = (r - 1) >> 1;
        }
        return res;
    }
};

