template<typename T, int M>
struct RMQ {
    T arr[2*M];
    T INF;
    int N;

    RMQ(int N_, T INF_) {
        INF = INF_;
        for (int j = 0; j < M; ++j) {
            arr[j] = INF;
        }

        N = 1;
        while (N < N_) N *= 2;
    }

    void update(int x, int a) {
        int ind = N - 1 + x;

        arr[ind] = a;

        while (ind > 0) {
            ind = (ind - 1) / 2;
            arr[ind] = min(arr[ind*2 + 1], arr[ind*2 + 2]);
        }
    }

    T query(int x, int y) {
        return query_(x, y, 0, 0, N);
    }

    T query_(int x, int y, int v, int l, int r) {
        if (y <= l || r <= x) return INF;

        if (x <= l && r <= y) return arr[v];

        T vl = query_(x, y, 2*v + 1, l, (l + r) / 2);
        T vr = query_(x, y, 2*v + 2, (l + r) / 2, r);

        return vl < vr ? vl : vr;
    }
};

int main() {
    int n, q;
    cin >> n >> q;
    RMQ<int, 100000> rmq(n, ((1 << 30) - 1) * 2 + 1);

    for (int j = 0; j < q; ++j) {
        int com, x, y;
        cin >> com >> x >> y;

        if (com == 0) {
            rmq.update(x, y);
        }

        if (com == 1) {
            int response = rmq.query(x, y+1);
            cout << response << endl;
        }
    }

    return 0;
}

