template<typename T>
struct SegmentTree {
	SegmentTree(int n_){
		for (n = 1; n < n_; n <<= 1);
		val.assign(n * 2 - 1, INF);
	}
	void update(int k, T x){
		k += n - 1;
		val[k] = x;
		while (k){
			k = (k - 1) / 2;
			val[k] = std::min(val[k * 2 + 1], val[k * 2 + 2]);
		}
	}
	T min(int l, int r, int k, int a, int b){
		if (r <= a || b <= l) return INF;
		if (l <= a && b <= r) return val[k];
		int m = (a + b) / 2;
		T vl = min(l, r, k * 2 + 1, a, m);
		T vr = min(l, r, k * 2 + 2, m, b);
		return std::min(vl, vr);
	}
	T min(int l, int r){
		return min(l, r, 0, 0, n);
	}
private:
	int n;
	vector<T> val;
};

