	while(NN < n_) NN <<= 1;
	for(int i=0;i<2*NN-1;++i) dat[i] = INF;
  }

  // dat[idx] = a, 0-indexed
  void update(int idx, int a){
	idx += NN - 1;
	dat[idx] = a;
	while(idx > 0){
	  idx = (idx - 1) / 2;
	  dat[idx] = min(dat[idx*2+1], dat[idx*2+2]);
	}
  }

  // calc min of [a,b)
  int query(int a, int b, int k, int l, int r){
	// no intersect
	if(r <= a || b <= l) return INF;

	// completely contain
	if(a <= l && r <= b) return dat[k];
