template <typename Monoid>
struct SegmentTree {
   using F = function<Monoid(Monoid, Monoid)>;

   int sz;
   vector<Monoid> seg;

   const F f;
   const Monoid M;

   SegmentTree(int n, const F& f, const Monoid& M) : f(f), M(M) {
      sz = 1;
      while (sz < n) sz <<= 1;
      seg.assign(2 * sz, M);
   }

   void set(int k, const Monoid& x) {
      seg[sz + k] = x;
   }

   void build() {
      for (int k = sz - 1; k > 0; --k) {
         seg[k] = f(seg[2 * k], seg[2 * k + 1]);
      }
   }

   void update(int k, const Monoid& x) {
      k += sz;
      seg[k] = x;
      while (k >>= 1) seg[k] = f(seg[2 * k], seg[2 * k + 1]);
   }

   Monoid query(int l, int r) {
      Monoid L = M, R = M;
      for (l += sz, r += sz; l < r; l >>= 1, r >>= 1) {
         if (l & 1) L = f(L, seg[l++]);
         if (r & 1) R = f(R, seg[--r]);
      }
      return f(L, R);
   }

   Monoid operator[](const int& k) const {
      return seg[sz + k];
   }
};

int main() {
   ios::sync_with_stdio(false);
   cin.tie(0);

   int n, q; cin >> n >> q;
   SegmentTree<int> seg(n, [](int l, int r) {return min(l, r); }, INT_MAX);
   seg.build();
   rep(i, q) {
      int com; cin >> com;
      int x, y; cin >> x >> y;
      if (com == 0) seg.update(x, y);
      else cout << seg.query(x, y + 1) << endl;
   }
}

