template<class T>
struct SegmentTree{
    using F=function<T(T,T)>;
    F f;
    T init;
    int sz;
    vector<T> seg;
    SegmentTree(int n,T init,F f):init(init),f(f){
        sz=1;
        while(sz<n) sz<<=1;
        seg.resize(sz<<1,init);
    }
    // 代入
    void set(int id,T x){
        seg[id+sz]=x;
    }
    // 構築
    void build(){
        for(int k=sz-1;k>0;k--){
            seg[k]=f(seg[2*k],seg[2*k+1]);
        }
    }
    // 更新
    void update(int id,T x){
        id+=sz;
        seg[id]=x;
        while(id>>=1){
            seg[id]=f(seg[2*id],seg[2*id+1]);
        }
    }
    // [l,r)の結果を取得
    T get(int l,int r){
        T L=init,R=init;
        l+=sz,r+=sz;
        for(;l<r;l>>=1,r>>=1){
            if(l&1) L=f(L,seg[l++]);
            if(r&1) R=f(seg[--r],R);
        }
        return f(L,R);
    }
    // debug
    void debug(){
        int i=1;
        for(int r=1;r<2*sz;r<<=1){
            while(i<r){
                cout<<seg[i]<<" ";
