const int INF = (1LL << 31) - 1;

struct segtree
{
    int n;
    vint dat;
    segtree(int count, int start)
    {
        int c = 1 << (int)(log2(count) + 1);
        dat = vint(2 * c, start);
        n = c;
    }

    void update(int i, int x)
    {
        int k = i + n;
        dat[k] = x;
        while (k / 2)
        {
            k /= 2;
            dat[k] = min(dat[k * 2], dat[k * 2 + 1]);
        }
    }

    int subGetMin(int a, int b, int k, int l, int r)
    {
        // out
        if (b <= l || a >= r)
        {
            return INF;
        }
        // completely contained
        if (a <= l && b >= r)
        {
            return dat[k];
        }
        // partially contained
        // call child
        int newK = k * 2;
        int vl = subGetMin(a, b, newK, l, (l + r) / 2);
        int vr = subGetMin(a, b, newK + 1, (l + r) / 2, r);
        return min(vl, vr);
    }

    int getMin(int a, int b)
    {
        return subGetMin(a, b, 1, 0, n);
    }
};

int main()
{
    int n, q;
    cin >> n >> q;
    segtree st(n, INF);
    rep(i, q)
    {
        int t, x, y;
        cin >> t >> x >> y;
        if (t)
        {
            int m = st.getMin(x, y + 1);
            cout << m << endl;
        }
        else
        {
            st.update(x, y);
        }
    }
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int N, Q;
int const inf = INT_MAX;

struct SegmentTree {
private:
    int n;
    vector<int> node;
public:
    SegmentTree(vector<int> v) {
        int sz = v.size();
        n = 1;
        // 2の累乗の大きさにする
        while (n < sz) n *= 2;
        // 余りをinfで埋める
        node.resize(2*n-1, inf);
        // 葉を構築
        for (int i = 0; i < sz; i++) {
            node[i+n-1] = v[i];
        }
        // 親を構築
        for (int i = n - 2; i >= 0; i--) {
            node[i] = min(node[2*i+1], node[2*i+2]);
        }
    }

    void update(int x, int val) {
        x += (n - 1);
        node[x] = val;
        while (x > 0) {
            x = (x - 1) / 2;
            node[x] = min(node[2*x+1], node[2*x+2]);
        }
    }

    int getmin(int a, int b, int k = 0, int l = 0, int r = -1) {
        if (r < 0) r = n;
        if (r <= a || b <= l) return inf;
        if (a <= l && r <= b) return node[k];
        int vl = getmin(a, b, 2*k+1, l, (l+r) / 2);
        int vr = getmin(a, b, 2*k+2, (l+r) / 2, r);
        return min(vl, vr);
    }
};

int main() {
    cin >> N >> Q;
    SegmentTree seg( vector<int>(N, inf) );
    for (int i = 0; i < Q; i++) {
        int c, x, y; cin >> c >> x >> y;
        if (c == 0) seg.update(x, y);
        else cout << seg.getmin(x, y+1) << endl;
    }
}

