typedef pair<int,int> pi;
typedef pair<int,pi> pipi;
typedef pair<pi,pi> ppi;
#define F first
#define S second
#define MP make_pair
#define PB push_back
const int N=1e5+10;
const int Q=1e5+10;
const int SQRTN=47+10;
const int INF=(1LL<<31)-1;
bool cmp(ppi a,ppi b){return a.F.F/SQRTN==b.F.F/SQRTN?a.F.S==b.F.S?a.F.F<b.F.F:a.F.S<b.F.S:a.F.F<b.F.F;}
int main(){
    int n,q,a[N],now=-1,nowl=0,nowr=-1,k,l,r,ans[Q];
    multiset<int> s;
    vector<ppi> v[SQRTN];
    vector<pipi>upd;
    scanf("%d%d",&n,&q);
    for(int i=0;i<n;i++)a[i]=INF;
    for(int i=0;i<q;i++){
        scanf("%d%d%d",&k,&l,&r);
        if(k==0){
            upd.PB(MP(l,MP(r,r)));
            i--;
            q--;
        }
        else v[l/SQRTN].PB(MP(MP(r,static_cast<int>(upd.size()-1)),MP(l,i)));
    }
    for(int i=0;i<SQRTN;i++)if(!v[i].empty()){
        sort(v[i].begin(),v[i].end(),cmp);
        for(int j=0;j<v[i].size();j++){
            while(now<v[i][j].F.S){
                now++;
                upd[now].S.S=a[upd[now].F];
                a[upd[now].F]=upd[now].S.F;
                if(nowl<=upd[now].F&&upd[now].F<=nowr){
                    s.erase(s.find(upd[now].S.S));
                    s.insert(upd[now].S.F);
                }
            }
            while(now>v[i][j].F.S){
                a[upd[now].F]=upd[now].S.S;
                if(nowl<=upd[now].F&&upd[now].F<=nowr){
                    s.erase(s.find(upd[now].S.F));
                    s.insert(upd[now].S.S);
                }
                now--;
            }
            while(nowr<v[i][j].F.F)s.insert(a[++nowr]);
            while(nowr>v[i][j].F.F)s.erase(s.find(a[nowr--]));
            while(nowl<v[i][j].S.F)s.erase(s.find(a[nowl++]));
            while(nowl>v[i][j].S.F)s.insert(a[--nowl]);
            ans[v[i][j].S.S]=*s.begin();
        }
    }
    for(int i=0;i<q;i++)printf("%d\n",ans[i]);
}

#include <iostream>
