class RmQ{
	private:
		ll *st;
		static const ll INF = 1000000000000000; 
		ll N;
		ll recursion_construct(int i){
			if(i >= N){
				return st[i];
			}
			return st[i] = min(recursion_construct(i * 2),recursion_construct(i * 2 + 1));
		}
		ll recursion_min(int i,int a,int b,int p,int q){//[a,b) [p,q)
			if(a <= p && q <= b)
				return st[i];
			if(b <= p || q <= a)
				return INF;

			return min(recursion_min(i * 2,a,b,p,(p + q) / 2),recursion_min(i * 2 + 1,a,b,(p + q) / 2,q));
		}

	public: 
		RmQ(int n){
			N = 1;
			while(N < n)
				N *= 2;
			st = (ll*)malloc(N * 2 * sizeof(ll));
			REP(i,N * 2)
				st[i + 1] = INF;
		}

		void set(ll a,int i){//i?????????a(0<=i<=n-1??????)
			st[N + i] = a;
		}

		void construct(){
			recursion_construct(1);
		}

		ll range_min(int a,int b){
			if(a > b)
				swap(a,b);

			if(a < 0)
				a = 0;
			if(b > N)
				b = N - 1;

			return recursion_min(1,a,b,0,N);
		}

		void update(ll a,int i){
			i += N;
			st[i] = a;

			while(i > 1){
				if(st[i] >= st[i / 2])
					break;
				st[i / 2] = st[i];
				i /= 2;
			}
		}

		~RmQ(){
			free(st);
		}
};

