long long INF = (1 << 31) - 1;

class SegmentTree {
private:
	long long Size;
	vector<long long> Node;
public:
	SegmentTree(long long N) {
		Size = 1;
		while (Size < N) Size <<= 1;
		Node.resize(Size * 2, INF);
	}
	void Update(long long K, long long X) {
		K += Size;
		Node[K] = X;
		while (K > 1) {
			K >>= 1;
			Node[K] = min(Node[K * 2], Node[K * 2 + 1]);
		}
	}
	long long Query(long long L, long long R) {
		long long NOWS = Size, ANS = INF;
		while (R > L) {
			if (L & 1) {
				ANS = min(ANS, Node[L + NOWS]);
				L++;
			}
			if (R & 1) {
				ANS = min(ANS, Node[R - 1 + NOWS]);
				R--;
			}
			L >>= 1, R >>= 1, NOWS >>= 1;
		}
		return ANS;
	}
};

int main() {
	long long N, Q;
	cin >> N >> Q;
	SegmentTree Seg(N);
	for (int i = 0; i < Q; i++) {
		long long Mode;
		cin >> Mode;
		if (Mode == 0) {
			long long K, X;
			cin >> K >> X;
			Seg.Update(K, X);
		}
		else {
			long long L, R;
			cin >> L >> R;
			cout << Seg.Query(L, R + 1) << endl;
		}
	}
}

