constexpr u32 DEF = 2147483647;

class segtree {
	::std::vector<u32> tree;
public:
	explicit segtree(const u32 size) :tree(size << 1, DEF) {}
	u32 fold(u32 first, u32 last)const {
		u32 ret = DEF;
		first += tree.size() >> 1;
		last += tree.size() >> 1;
		while (first < last) {
			if (first & 1) ret = ::std::min(ret, tree[first++]);
			if (last & 1)ret = ::std::min(ret, tree[--last]);
			first >>= 1;
			last >>= 1;
		}
		return ret;
	}
	void set(u32 index, const u32 value) {
		index += tree.size() >> 1;
		tree[index] = value;
		while (index >>= 1)
			tree[index] = ::std::min(tree[index << 1], tree[index << 1 | 1]);
	}
};

