	ST(vector<num> v) {
		int sz = v.size();
		n = 1; while (n < sz)n *= 2;
		node.resize(n * 2 - 1, INF);

		for (int i = 0; i < sz; i++)node[i + n - 1] = v[i];
		for (int i = n - 2; i >= 0; i--)node[i] = min(node[2 * i + 1], node[2 * i + 2]);
	}
	void update(int x, num val) {
		x += (n - 1);
		node[x] = val;
		while (x > 0) {
			x = (x - 1) / 2;
			node[x] = min(node[2 * x + 1], node[2 * x + 2]);
		}
