typedef struct segtree{
	struct node{
		node *cl,*cr;
		int dat;
		node(){
			cl=NULL,cr=NULL,dat=INF;
		}
	};
	node root;
	ll siz;
	void init(int sizes){
		siz=sizes;
		root=node();
	}
	void eval(node *v,int a,int b){
		if(a+1<b){
			if(v->cl==NULL)v->cl=new node();
			if(v->cr==NULL)v->cr=new node();
		}
	}
	void upd(node *v,int a,int b,int L,int R,int val){
		if(b<=L||R<=a)return;
		if(L<=a&&b<=R){
			v->dat=val;
			return;
		}
		eval(v,a,b);
		int m=(a+b)>>1;
		upd(v->cl,a,m,L,R,val);
		upd(v->cr,m,b,L,R,val);
		v->dat=min(v->cl->dat,v->cr->dat);
	}
	void upd(ll L,ll R,ll val){
		upd(&root,0,siz,L,R,val);
	}
	ll qry(node *v,int a,int b,int L,int R){
		if(b<=L||R<=a)return INF;
		if(L<=a&&b<=R){
			return v->dat;
		}
		eval(v,a,b);
		int m=(a+b)>>1;
		ll vl=qry(v->cl,a,m,L,R);
		ll vr=qry(v->cr,m,b,L,R);
		return min(vl,vr);
	}
	ll qry(ll L,ll R){
		return qry(&root,0,siz,L,R);
	}
}segtree;
