constexpr ll inf = ((1<<30)-1)*2+1 ;

class Bucket{
  public:
  vector<ll> buc,v;
  ll N,sqn,K;
  Bucket(){};
  Bucket(ll n){
    N = n;
    sqn = sqrt(N);
    K = (n + sqn - 1) /sqn;
    buc.assign(K,inf);
    v.assign(K * sqn,inf);
  }
  void update(int x,int y){
    v[x] = y;
    ll m = inf;
    int k = x / sqn;
    for(int i = k * sqn; i < (k + 1) * sqn;++i){
      m = min(m,v[i]);
    }
    buc[k] = m;
  }
  ll query(int x,int y){
    ll res = inf;
    for (int k = 0; k < K; ++k) {
      int l = k * sqn, r = (k + 1) * sqn;
      if (r <= x || y <= l)
        continue;
      if (x <= l && r <= y) {
        res = min(res,buc[k]);
      } else {
        for (int i = max(x, l); i < min(y, r); ++i) {
          res = min(res,v[i]);
        }
      }
    }
    return res;
  }
  void Debug(){
    for(int i = 0; i < N;++i){
      cout << buc[i/sqn] << ' ';
    }
    cout << endl;
    for(int i = 0; i < N;++i){
      cout << v[i] << ' ';
    }
    cout << endl;
  }
};

