struct segtree {
    int n,out;
    vector<int> data,lazy;

    segtree(int _n,int _out){
       	n=1<<(32-__builtin_clz(_n));
        cerr << n << endl;
       	out=_out;
        data.assign(2*n-1,out);
        lazy.assign(2*n-1,out);
    }

    inline int vmerge(int a,int b){return min(a,b);}

    inline void lazy_eval(int k,int l,int r){
        if(r-l<=1) return;
        if(lazy[k]==out) return;
        rep(i,2) data[2*k+1+i]=lazy[k],lazy[2*k+1+i]=lazy[k];
        lazy[k]=out;
    }

    int update(int a,int b,int x,int k,int l,int r){
        if(b<=l||r<=a) return data[k];
        if(a<=l&&r<=b) return lazy[k]=x,data[k]=x;
        lazy_eval(k,l,r);
        const int m=(l+r)/2;
        return data[k]=vmerge(update(a,b,x,2*k+1,l,m),update(a,b,x,2*k+2,m,r));
    }

    int query(int a,int b,int k,int l,int r){
        if(b<=l||r<=a) return out;
        if(a<=l&&r<=b) return data[k];
        lazy_eval(k,l,r);
        const int m=(l+r)/2;
        return vmerge(query(a,b,2*k+1,l,m),query(a,b,2*k+2,m,r));
    }
};

