/*
 * Segment Tree
 * Construction: O(n)
 * Update:       O(log n)
 * Query:        O(log n)
 */

#include <functional>
#include <iostream>
#include <vector>
#include <climits>
using namespace std;

class SegmentTree {
    const int n; // array size
    const int M; // initial value

    int (*f)(int, int); // operation

public:
    vector<int> t; // tree

    SegmentTree(int n, int M, int (*f)(int, int)) : n(n), M(M), f(f), t(2 * n, M) {}

    void build() { // build the tree
        for (int i = n - 1; i > 0; --i)
            t[i] = f(t[i << 1], t[i << 1 | 1]);
    }

    void update(int k, int val) { // set val at k th
        k += n;
        for (t[k] = val; k > 1; k >>= 1)
            t[k >> 1] = f(t[k], t[k ^ 1]);
    }

    int query(int l, int r) { // query on interval [l, r)
        int res = M;
        for (l += n, r += n; l < r; l >>= 1, r >>= 1) {
            if (l & 1) res = f(res, t[l++]);
            if (r & 1) res = f(res, t[--r]);
        }
        return res;
    }
};

void rmq() {
    int n, q;
    cin >> n >> q;
    SegmentTree T(n, INT_MAX, [](int a, int b) { return min(a, b); });
    T.build();

    while (q--) {
        int com, x, y;
        cin >> com >> x >> y;
        if (com)
            cout << T.query(x, y + 1) << endl;
        else
            T.update(x, y);
    }
}

