using namespace std;

class SegTree{
private:
  int n;
  // 1-index (tree[0] is dummy), leaves are tree[n]-tree[2n-1]
  vector<int> tree;
  const int defVal = 2147483647;
public:
  SegTree(int _n){
    int t;
    t = 1;
    while (t<_n) t*=2;
    n = t;
    tree = vector<int>(2*n, defVal);
    //cerr << "finish init" << endl;
    //cerr << "tree size is " << 2*n << endl;
  }
  void update(int k, int a){
    k += n;
    //cerr << "update:  [" << k << "] = " << a << endl;
    tree[k] = a;
    while (k>1){
      k /= 2;
      tree[k] = tree[k*2]<tree[k*2+1]? tree[k*2]:tree[k*2+1];
    }
  }
  // stab function
  int query(int l, int r){ return _query(l,r,1,0,n);}
  // k:注目してるノード,対応する範囲がkl-kr
  int _query(int l, int r, int k, int kl, int kr){
    // それ以上潜らなくていいパターン
    if (kr<=l || r<=kl) return defVal;
    else if (l<=kl && kr<=r) return tree[k];
    else {
      int vl, vr;
      vl = _query(l,r, k*2, kl, (kl+kr)/2);
      vr = _query(l,r, k*2+1, (kl+kr)/2,kr);
      return vl<vr? vl:vr;
    }
  }
};

