//抽象化セグ木を書いてみる
template <typename T>
struct MySegtree
{
    int n;                       //葉の数
    vector<T> data;              //データを格納
    T define;                    //単位元(かつ初期値)
    function<T(T, T)> operation; //区間クエリ用
    function<T(T, T)> update;    //1点更新クエリ用

    //区間[a,b)の総和 ノード k=[l,r)に注目
    T _query(int a, int b, int k, int l, int r)
    {
        if (a >= r || b <= l)
            return define; //どうやっても範囲が交差しないため単位元を返しておく
        if (a <= l && r <= b)
            return data[k]; //a<=(l,r)<=bとなっている時は区間[l,r)の演算結果が格納されているノードkのデータを上に返す
        else
        {
            T c1 = _query(a, b, 2 * k + 1, l, (l + r) / 2); //左の子をチェック
            T c2 = _query(a, b, 2 * k + 2, (l + r) / 2, r); //右の子をチェック
            return operation(c1, c2);
        }
    }

public:
    //メンバ初期化子リストによる初期化
    MySegtree(size_t _n, T _define, function<T(T, T)> _operation, function<T(T, T)> _update) : define(_define), operation(_operation), update(_update)
    {
        n = 1;
        while (n < _n)
        { //nが配列のサイズ_nを超えるまで
            n *= 2;
        }
        data = vector<T>(2 * n - 1, define); //サイズが2n-1で初期値define(単位元)の配列
    }
    //i番目の要素をxに更新(i:0-indexed)
    void change(int i, T x)
    {
        i += n - 1; //葉にアクセスするには+(n-1)する
        data[i] = update(data[i], x);
        while (i > 0)
        {
            i = (i - 1) / 2;                                       //インクリメントして2で割ることで切り捨てて１つ上位のノードへいける
            data[i] = operation(data[i * 2 + 1], data[i * 2 + 2]); //i番目のデータを２つの子の演算で更新
        }
    }
    //区間[a,b)に対してクエリを実行
    T query(int a, int b)
    {
        return _query(a, b, 0, 0, n); //根から走査していく
    }
    T operator[](int i)
    {
        return data[i + (n - 1)]; //i番目の葉のデータを返す
    }
};
int main()
{
    cout << fixed << setprecision(30);
    ll n, q;
    cin >> n >> q;
    MySegtree<ll> tree(
        n, (1ll << 31) - 1,
        [](ll a, ll b) -> ll { return min(a, b); }, //二項演算はmin(a,b)
        [](ll a, ll b) -> ll { return b; });        //a番目はbに変更
    loop(i, q)
    {
        ll z, x, y;
        cin >> z >> x >> y;
        if (z == 0)
        {
            tree.change(x, y);
        }
        else
        {
            putout(tree.query(x, y + 1));
        }
    }
    return 0;
}

