    rep(i,q){
        int com,x,y;
        cin>>com>>x>>y;
        if(com==0){
            st.update(x,y);
        }else{
            cout<<st.query(x,y+1)<<endl;
        }

    }
}

#include <bits/stdc++.h>
using namespace std;
const int INF = 2147483647;

struct SegmentTree {
private:
    int n;
    vector<int> node;
    //int nとvector<int> nodeの2つを変数に持つ。
    //nは扱う配列の要素数で、nodeはまさにsegtree本体

public:
    //初期化処理。segtreeを使うときは最初にこれを宣言する。
    SegmentTree(vector<int> v) {
        int sz = v.size(); //vは扱う配列の長さ
        n = 1; while(n < sz) n *= 2; //nはvの配列を全て入れるために必要なseg treeの葉の数
        node.resize(2*n-1, INF); //★演算によって単位元を変える。segtreeでは全部で2n-1の配列が必要。最小値を求めるのであれば、最初は単位元であるINFで初期化しておく
        //例えばv.size()が2のべき乗で無かった場合は、最終的な計算結果に影響のないような単位元の葉を用意しておく必要がある
        for(int i=0; i<sz; i++) node[i+n-1] = v.at(i); //segtreeの葉の部分に扱う配列を埋め込む
        for(int i=n-2; i>=0; i--) node[i] = min(node[2*i+1],node[2*i+2]); //★演算によって変える場所　segtreeを作る(注目しているnode iの子ノードを見て二項演算をして、node iの値を決定する)
    }

    void update(int x, int val) {
        //一点更新処理。x番目の要素をvalに変更する
        x += (n - 1); //配列のx番目の要素を更新しようとするとき、segtreeで対応する要素はx+n-1番目である
        node[x] = val; //segtree上で値を更新
        while(x > 0) { //葉から根に向かってsegtreeの要素を更新していく
            x = (x - 1) / 2;
            node[x] = min(node[2*x+1],node[2*x+2]); //★演算によって変える
        }
    }

    int getor(int a, int b, int k=0, int l=0, int r=-1) {
        //区間取得処理。求めたいのは区間[a,b)の中で演算しつづけた結果(たとえばこの区間の最小値)
        //自分がいるノードのindex(何階にいるか？)
        //ノードkは元の配列でいうとどの区間をカバーしているか？
        if(r < 0) r = n; //最初に呼び出す時はノードk=0はsegtreeの根なので区間は[0,n)を指す
        if(r <= a || b <= l) return INF; //今のノードが求める区間と無関係の場合は、最終的な答えに影響しない単位元(最小値を求めたい場合は単位元はINF)を返す 演算によって変える
        if(a <= l && r <= b) return node[k]; //今見ている区間[l,r)が答えを求めたい区間[a,b)に完全に含まれるなら、この区間について演算し続けた結果(=node[k];例えば最小値)を返す

        //上記に当てはまらない場合
        //kの子ノードを見に行って、再帰的に処理を行う k=0の場合はノード1と2を見る
        int vl = getor(a, b, 2*k+1, l, (l+r)/2); //kの子ノード(left)の子孫のうち、求めたい区間に含まれる要素について演算し続けた結果を返す
        int vr = getor(a, b, 2*k+2, (l+r)/2, r); //kの子ノード(right)の子孫のうち、求めたい区間に含まれる要素について演算し続けた結果を返す
        return min(vl,vr); //演算によって変える場所 子ノードの子孫のうち、演算しつづけた結果を返す
    }
};

int main(){
    int N; cin >> N;
    vector<int> a(N,INF);
    SegmentTree tree(a);
    int Q; cin >> Q;
    for(int i=0;i<Q;i++){
        bool type; cin >> type;
        if(!type){
            int first,second; cin >> first >> second;
            tree.update(first,second);
        }else{
            int first,second;
            cin >> first >> second;
            cout << tree.getor(first,second+1) << endl;
        }
    }
}

