        data_num = origin_v.size();
        width = 1;
        depth = 1;
        while(width<data_num){
            width *= 2;
            depth++;
        }

        nodes.resize(2*width-1,0);//ここの値を要求によって変える   ほしいのは...総和:0 総績:1 最小:numeric_limits<int>::max()-5 最大:numeric_limits<int>::min()+5
        REP(i,data_num){
