            if(i&1){
                mini_update(i + width - 1);
            }
        }
        if((data_num&1)){
            mini_update(data_num + width - 2);
        }

        //changed.resize(2*width-1, false);

    }
    ~Segment_tree(){}

    void mini_update(int where){

        int x = where;

        while(x > 0) {
            x = (x - 1) / 2;
        nodes[x] = min(nodes[2*x+1], nodes[2*x+2]);
