/***
    Range Minimum/Maximum Query 
    Segment Tree
    length of sequence is N
    manipulates a sequence A = { a0, a1,... ,a(N-1) } with the following operations
    $ find(x,y) : report the minimum element in a(x), a(x+1),... ,a(y)
    $ update(x,y) : change a(x) to y
    time complexity of each queries are O(logN)
 */
#include<bits/stdc++.h>

using namespace std;

const int IINF = INT_MAX;

class RMQ{
private:
  int limit,N;
  vector<int> dat;
public:
  void init(int n_){
    N = n_;
    limit = 1;
    while(limit<n_) limit*=2;
    dat.clear();
    dat.resize(2*limit,IINF);
  }

  int _build(int cur,int L,int R,const vector<int> &buf){
    if( !( 0 <= cur && cur < 2*limit ) ) return IINF;
    if( L == R-1 ) {
      if( L >= N ) return IINF;
      dat[cur] = buf[L];
    } else {
      int vl = _build(cur*2+1,L,(L+R)/2,buf);
      int vr = _build(cur*2+2,(L+R)/2,R,buf);
      dat[cur] = min(vl,vr);
    }
    return dat[cur];
  }

  void build(const vector<int> &buf){ _build(0,0,limit,buf); };

  void update(int k,int a){
    k += limit-1;
    dat[k] = a;
    while(k > 0){
      k = (k-1)/2;
      dat[k] = min(dat[k*2+1],dat[k*2+2]);
    }
  }

  int _query(int a,int b,int k,int l,int r){
    if(r<=a || b<=l) return IINF;
    else if(a<=l && r<=b)return dat[k];
    int vl = _query(a,b,k*2+1,l,(l+r)/2);
    int vr = _query(a,b,k*2+2,(l+r)/2,r);
    return min(vl,vr);
  }

  int query(int a,int b){ return _query(a,b,0,0,limit); }
};

int main(){
  int N,Q;
  cin >> N >> Q; // length of sequence, the number of query

  RMQ rmq;
  rmq.init(N); // initialy, all elements are 2^31-1
  /* 
    vector<int> init;
    // input initial values to initi
    rmq.build(init);
   */
  for(int i=0;i<Q;i++) {
    int opr,x,y;
    cin >> opr >> x >> y;
    if( opr == 0 ) rmq.update(x,y); // update
    else if( opr == 1 ) printf("%d\n",rmq.query(x,y+1)); // find
  }
  return 0;
}

