template<typename T>
struct SegmentTree {
private:
	ll n;
	vector<T> node;
	T ex;
	T(*f)(T,T);

public:
	SegmentTree() {}
	//初期化
	SegmentTree(int size, T(*_f)(T,T), T _ex, T ini) {
		n = 1;
		while (n < size)n *= 2;
		f = _f;
		ex = _ex;
		node.resize(2 * n - 1, ex);
		//最下段に順番に値を入れる。
		REP(i, size)node[i + n - 1] = ini;
		//親に伝えていく
		REPR(i, size - 1)node[i] = f(node[i * 2 + 1], node[i * 2 + 2]);
	}

	//k番目(0-indexed)をaに変更
	void update(ll k, ll a) {
		//最下段のインデックスを取得
		k += n - 1;
		//値を代入
		node[k] = a;

		//上りながら更新
		while (k > 0) {
			k = (k - 1) / 2;
			node[k] = f(node[k * 2 + 1], node[k * 2 + 2]);
		}
	}

	//[a,b)の範囲のcalcの結果を求める
	//kは接点番号、l,rはそれが[l,r)に対応づいていることを表す。
	//外からは(a,b)で呼び出し。
	ll query(ll a, ll b, ll k = 0, ll l = 0, ll r = -1) {

		//初回呼び出し時探索範囲を[0,n)に設定。
		if (r < 0)r = n;
		//[a,b)と[l.r)が交差しない。
		if (r <= a || b <= l) {
			return ex;
		}
		//[a,b)が[l,r)を完全に含む。
		if (a <= l && r <= b)return node[k];
		else {
			T vl = query(a, b, k * 2 + 1, l, (l + r) / 2);
			T vr = query(a, b, k * 2 + 2, (l + r) / 2, r);
			return f(vl, vr);
		}
	}
};


