template<class T>
class SqrtDecomp {
    //private:
public:
    const size_t B, _size;
    T const init;
    vector<T> b, a;
public:
    SqrtDecomp(const size_t size = 0,
               T const &init = numeric_limits<T>::max(),
               const size_t B = 150)
        : B(B), _size(size),
          init(init), b(size/B + 1, init), a(size, init){}

    size_t size() const {
        return _size;
    }

    T get(size_t l, const size_t &r) const {
        T res = numeric_limits<T>::max();
        while(l < r){
            if(l%B == 0 && l + B <= r){
                res = min(res, b[l/B]);
                l += B;
            } else {
                res = min(res, a[l]);
                l++;
            }
        }
        return res;
    }

    void set(const size_t &p, const T &x){
        a[p] = x, b[p/B] = init;
        size_t s = p/B, end = min(p - p%B + B, size());
        for(size_t i = p - p%B; i < end; i++){
            b[s] = min(b[s], a[i]);
        }
    }

    vector<T> to_a(int l = -1, int r = -1){
        if(l == -1) l = 0;
        if(r == -1) r = size();
        vector<T> res(r-l);
        for(int i = l; i < r; i++) res[i-l] = get(i,i+1);
        return res;
    }
};

vector<int> naive(int n, int q, const vi &a, const vi &b, const vi &c){
    vector<int> ans;
    vector<int> arr(n,(1LL<<31)-1);
    for(int i = 0; i < q; i++){
        if(a[i] == 0){
            arr[b[i]] = c[i];
        } else {
            int res = (1LL<<31)-1;
            for(int j = b[i]; j <= c[i]; j++){
                res = min(res,arr[j]);
            }
            ans.push_back(res);
        }
    }
    return ans;
}

vector<int> solve(int n, int q, const vi &a, const vi &b, const vi &c){
    vector<int> ans;
