const int MAXN = 100000, INF = 2147483647;
int n, q, t[4 * MAXN + 5];

void ptupt(int l, int r, int pt, int p, int val) {
    if (r < pt || l > pt) return;
    if (l == r && l == pt) {
        t[p] = val;
        return;
    }
    int mid = (l + r) >> 1;
    ptupt(l, mid, pt, p << 1, val);
    ptupt(mid + 1, r, pt, p << 1 | 1, val);
    t[p] = min(t[p << 1], t[p << 1 | 1]);
}

int qry(int l, int r, int tl, int tr, int p) {
    if (r < tl || l > tr) return INF;
    if (tl <= l && r <= tr) {
        return t[p];
    }
    int rt = INF, mid = (l + r) >> 1;
    rt = min(rt, qry(l, mid, tl, tr, p << 1));
    rt = min(rt, qry(mid + 1, r, tl, tr, p << 1 | 1));
    return rt;
}

int main() {
    cin >> n >> q;
    fill(t, t + 4 * MAXN + 3, INF);
    while (q--) {
        int t1, t2, t3;
        cin >> t1 >> t2 >> t3;
        if (t1 == 0) ptupt(0, n - 1, t2, 1, t3);
        else cout << qry(0, n - 1, t2, t3, 1) << endl;
    }
}

