// 抽象 SegmentTree (0-indexed・一点更新・区間取得)
// update, combine 関数を持つクラスを別途定義して使う
template <typename MonoidType, class SegFunc>
struct SegmentTree {
    // node, identity element
    int n;
    vector<MonoidType> node;
    MonoidType E0;

    inline void build(int m, const vector<MonoidType> &v = vector<MonoidType>()) {
        if(v.size()) m = v.size();
        n = (1 << (32 - __builtin_clz(m - 1)));

        node = vector<MonoidType>(2*n, E0);
        if(v.size()) {
            for(int i=0; i<m; i++) {
                node[n+i] = v[i];
            }
            for(int i=n-1; i>=1; i--) {
                node[i] = SegFunc::combine(node[i << 1], node[i << 1 | 1]);
            }
        }
    }

    // initialize
    SegmentTree() {}
    SegmentTree(int n_, MonoidType E0_,
                vector<MonoidType> v = vector<MonoidType>()) : E0(E0_) {
        build(n_, v);
    }

    // update k-th element (applied value: x)
    void update(int k, MonoidType x) {
        k += n;
        node[k] = SegFunc::update(node[k], x);
        while(k > 0) {
            k >>= 1;
            node[k] = SegFunc::combine(node[k << 1], node[k << 1 | 1]);
        }
    }

    // range query for [a, b)
    // 非再帰のアイデア: http://d.hatena.ne.jp/komiyam/20131202/1385992406
    MonoidType query(int a, int b) {
        MonoidType vl = E0, vr = E0;
        for(int l=a+n, r=b+n; l<r; l>>=1, r>>=1) {
            if(l & 1) vl = SegFunc::combine(vl, node[(l++)]);
            if(r & 1) vr = SegFunc::combine(node[(--r)], vr);
        }
        return SegFunc::combine(vl, vr);
    }
};


