const int kIntMax = 0x7fffffff;

class SegmentTree {
  public:
    vector<int> node;
    int n;
    SegmentTree(int _n)
    {
      n = 1;
      while (n < _n) {
        n = n << 1;
      }
      node.resize(2*n-1);
      std::fill(node.begin(), node.end(), kIntMax);
    }
    void update(int index, int x)
    {
      int i = n-1+index;
      node.at(i) = x;
      while (0 < i) {
        i = (i-1) / 2;
        node.at(i) = min(node.at(2*i+1), node.at(2*i+2));
      }
    }
    int find(int begin, int end)
    {
      _find(begin, end, 0, 0, n);
    }
  private:
    int _find(int begin, int end, int index, int tree_begin, int tree_end)
    {
      if (end <= tree_begin || tree_end <= begin) {
        return kIntMax;
      }
      if (begin <= tree_begin && tree_end <= end) {
        return node.at(index);
      }
      int l = _find(begin, end, 2*index+1, tree_begin, (tree_begin+tree_end)/2);
      int r = _find(begin, end, 2*index+2, (tree_begin+tree_end)/2, tree_end);
      return min(l, r);
    }
};

int main()
{
  int n, q;
  std::cin >> n >> q;
  SegmentTree tree(n);
  for (int i = 0; i < q; i++) {
    int com, x, y;
    std::cin >> com >> x >> y;
    if (com == 0) {
      tree.update(x, y);
    } else if (com == 1) {
      std::cout << tree.find(x, y+1) << '\n';
    } else {
      std::cerr << "Unknown operation\n";
      exit(1);
    }
  }
  return 0;
}

#include <bits/stdc++.h>

using namespace std;

template<typename T> class SegmentTree {
private:
  const T INF;
  int n;
  vector<T> d;

  T query(int a, int b, int k, int l, int r) {
    if (r <= a || b <= l) return INF;
    if (a <= l && r <= b) return d[k];
    T vl = query(a, b, k * 2 + 1, l, (l + r) / 2);
    T vr = query(a, b, k * 2 + 2, (l + r) / 2, r);
    return function(vl, vr);
  }

protected:
  virtual T function(T l, T r) = 0;

public:
  SegmentTree(int m) : INF(numeric_limits<T>::max()) {
    n = 1 << (32 - __builtin_clz(m - 1));
    d.resize(2 * n - 1, INF);
  }

  void update(int k, T a) {
    k += n - 1;
    d[k] = a;
    while (k > 0) {
      k = (k - 1) / 2;
      d[k] = function(d[k * 2 + 1], d[k * 2 + 2]);
    }
  }

  // [a,b)
  T query(int a, int b) {
    return query(a, b, 0, 0, n);
  }
};

template<typename T> class RMQ : public SegmentTree<T> {
protected:
  T function(T l, T r) {
    return min(l, r);
  }

public:
  RMQ(int n) : SegmentTree<T>(n) {}
};

int main() {
