void init(int l,int r,int now){
    b[now].l=l;
    b[now].r=r;
    b[now].n=2147483647;
    if(r==l){
        a[r].t=a[l].t=now;
        return;
    }
    int mid=(l+r)/2;
    init(l,mid,now*2);
    init(mid+1,r,now*2+1);
}
void maintain(int now){
    int temp=b[now].n;
    if(b[now].r-b[now].l<2)b[now].n=min(a[b[now].l].n,a[b[now].r].n);
    else b[now].n=min(b[now*2].n,b[now*2+1].n);
    if(temp!=b[now].n)maintain(now/2);
}
int dp(int now,int l,int r){
    if(b[now].l>=l&&b[now].r<=r)return b[now].n;
    else if(b[now].l>r||b[now].r<l){
        return -1;
    }
    int a,b;
    a=dp(now*2,l,r);
    b=dp(now*2+1,l,r);
    if(a<0&&b<0)return -1;
    if(a<0)return b;
    if(b<0)return a;
    return min(dp(now*2,l,r),dp(now*2+1,l,r));
}
