// ini：上限（下限）,base：元の配列,monoid：モノイド,tree：セグ木,depth：treeの深さ,
// basesize：baseの要素数,treesize：treeの要素数,num：treesize-basesize
// 初期値（上限とか下限）を決定
template <class num_type>
struct segtree {
    int num, depth, basesize, treesize;
    vector<num_type> base, tree;
    using func_type = num_type(num_type&, num_type&);
    num_type (*monoid)(num_type& a, num_type& b);
    map<num_type, int> size_map;
    num_type ini;
    // 元の配列, モノイド, 初期値
    segtree(vector<num_type> tmp1, func_type tmp2, num_type tmp3)
        : base(tmp1), monoid(tmp2), ini(tmp3) {
        basesize = (int)base.size();
        num = 1;
        depth = 1;
        while (num < basesize) {
            num *= 2;
            depth++;
        }
        tmp3 = num;
        int tmp4 = 1;
        while (tmp3 > 0) {
            size_map[tmp3] = tmp4 - 1;
            tmp3 /= 2;
            tmp4 *= 2;
        }
        num--;
        treesize = num * 2 + 1;
        tree.assign(treesize, ini);
        for (int i = num; i < num + basesize; i++) { tree[i] = base[i - num]; }
        for (int i = num + basesize; i < treesize; i++) { tree[i] = ini; }
        for (int i = num - 1; i > -1; i--) {
            tree[i] = monoid(tree[2 * i + 1], tree[2 * i + 2]);
        }
    }
    // 条件を満たす(サンプルの条件はs以下になること)最大のインデックスを返す関数
    template <class func_type2>
    int max_index(func_type2 index_func) {
        int i = 0;
        while (i < num) {
            int k = 2 * i + 1;
            if (index_func(tree[k + 1])) {
                i = k + 1;
                continue;
            }
            if (index_func(tree[k])) {
                i = k;
                continue;
            }
            return -1;
        }
        return i - num;
    }
    template <class func_type2>
    int min_index(func_type2 index_func) {
        int i = 0;
        while (i < num) {
            int k = 2 * i + 1;
            if (index_func(tree[k])) {
                i = k;
                continue;
            }
            if (index_func(tree[k + 1])) {
                i = k + 1;
                continue;
            }
            return -1;
        }
        return i - num;
    }

    // 半開区間[lower,upper)の最小値（とか）を探す関数
    num_type search(int lower, int upper) {
        num_type ret = ini;
        vector<pair<int, int>> stack(1, make_pair(0, num + 1));
        vector<num_type>* tree_local = &tree;
        map<num_type, int>* size_map_local = &size_map;
        // func_type monoid_local = monoid;
        int l, r, m, s = 1;
        while (s) {
            tie(l, r) = stack.back();
            stack.pop_back();
            if (lower <= l && r <= upper) {
                ret = min(
                    ret,
                    (*tree_local)[(*size_map_local)[(r - l)] + l / (r - l)]);
                s--;
            } else {
                m = (l + r) / 2;
                if (upper <= m) {
                    stack.push_back({l, m});
                } else if (m <= lower) {
                    stack.push_back({m, r});
                } else {
                    stack.push_back({l, m});
                    stack.push_back({m, r});
                    s++;
                }
            }
        }
        return ret;
    }

    // base[i]をsに更新してセグ木全体を更新する関数
    void update(int index, num_type new_value) {
        int i = index + num;
        tree[i] = new_value;
        while (i) {
            i = (i - 1) / 2;
            num_type temp = monoid(tree[2 * i + 1], tree[2 * i + 2]);
            if (tree[i] != temp) {
                tree[i] = temp;
                continue;
            }
            break;
        }
    }

    // 和がw以上となる最小のインデックスを求める
    int lowerbound(num_type w) {
        if (w <= 0) { return 0; }
        if (w > tree[0]) { return basesize; }
        int x = 0;
        for (int i = 0; i < depth - 1; i++) {
            if (tree[2 * x + 1] < w) {
                w -= tree[2 * x + 1];
                x = 2 * x + 2;
            } else {
                x = 2 * x + 1;
            }
        }
        return x - num;
    }
};

