#include <functional>
#include <iostream>
#include <vector>
using namespace std;

template <typename T, typename E> class SegmentTree {
  private:
    using F = function<T(T, T)>;
    using G = function<T(T, E)>;
    int sz;
    const T id;
    const F f;
    const G g;
    vector<T> dat;

  public:
    SegmentTree(F f, G g, T id) : f(f), g(g), id(id) {}
    void init(int n) {
        for(sz = 1; sz < n;)
            sz <<= 1;
        dat.assign(sz << 1, id);
    }
    void build(const vector<T> &v) {
        int n = v.size();
        init(n);
        for(int i = 0; i < n; i++)
            dat[sz + i] = v[i];
        for(int i = sz; --i;)
            dat[i] = f(dat[i << 1], dat[i << 1 | 1]);
    }
    void update(int k, E x) {
        k += sz;
        dat[k] = g(dat[k], x);
        while(k >>= 1)
            dat[k] = f(dat[k << 1], dat[k << 1 | 1]);
    }
    T query(int l, int r) const {
        T vl = id, vr = id;
        for(l += sz, r += sz; l < r; l >>= 1, r >>= 1) {
            if(l & 1) vl = f(vl, dat[l++]);
            if(r & 1) vr = f(dat[--r], vr);
        }
        return f(vl, vr);
    }
};

int main() {
    cin.tie(nullptr);
    ios::sync_with_stdio(false);

    int N, Q;
    cin >> N >> Q;

    auto f = [](int a, int b) { return min(a, b); };
    auto g = [](int a, int b) { return b; };
    SegmentTree<int, int> seg(f, g, INT32_MAX);
    seg.init(N);

    int c, x, y;
    while(Q--) {
        cin >> c >> x >> y;
        if(c)
            cout << seg.query(x, y + 1) << "\n";
        else
            seg.update(x, y);
    }
}

