int n, q, data[200010];
int INF = (1LL << 31) - 1;

void init(int &n_) {
	int n = 1;
	while (n < n_)n *= 2;
	n_ = n;
	for (int i = 0; i < 2 * n - 1; i++)data[i] = INF;
}
void update(int k,int x) {
	k += n - 1;
	data[k] = x;
	while (k > 0) {
		k = (k - 1) / 2;
		data[k] = std::min(data[k * 2 + 1], data[k * 2 + 2]);
	}
}
int find(int a, int b, int k, int l,int r) {
	if (r <= a)return INF;
	if (b <= l)return INF;
	if (a <= l&&r <= b)return data[k];
	int val1 = find(a, b, k * 2 + 1, l, (r + l) / 2);
	int val2 = find(a, b, k * 2 + 2, (r + l) / 2, r);
	return std::min(val1,val2);
}

int main() {
	std::cin >> n >> q;
	init(n);
	for (int i = 0; i < q; i++) {
		int a, b, c;
		std::cin >> a >> b >> c;
		if (a == 0)update(b, c);
		else std::cout << find(b, c + 1, 0, 0, n) << std::endl;
	}
	return 0;
}

