template<class Monoid> struct SegmentTree {
    using func=function<Monoid(Monoid, Monoid)>;
    int n;
    vector<Monoid> seg;
    const func f;
    const Monoid e;
    SegmentTree(int len, func f, const Monoid e) : f(f), e(e) {
        n = 1;
        while (n < len)n <<= 1;
        seg.assign((n << 1) - 1, e);
    }
    SegmentTree(vi &dat, const func f, const Monoid e) : f(f), e(e) {
        n = 1;
        int asz = dat.size();
        while (n < asz)n <<= 1;
        seg.assign((n << 1) - 1, e);
        rep(i, asz) seg[i + n - 1] = dat[i];
        rer(i, n - 2)seg[i] = f(seg[(i << 1) | 1], seg[(i << 1) + 2]);
    }
    void update(int k, Monoid v) {
        seg[k + n - 1] = v;
        k += n - 1;
        while (k) {
            k = (k - 1) >> 1;
            seg[k] = f(seg[(k << 1) | 1], seg[(k << 1) + 2]);
        }
    }
    void del(int k) {
        update(k, e.v);
    }
    void add(int k, int v) {
        update(k, v + seg[k + n - 1].v);
    }
    vector<Monoid> rvs;
    //高速なquery 葉から辿る
    Monoid query_bottomup(int l, int r) {
        rvs.clear();
        Monoid ret = e;
        l += n - 1;
        r += n - 1;
        while (l < r) {
            //右なら、次に右上へ移動してしまうので
            if (!(l & 1)) {
                ret = f(ret, seg[l]);
            }
            //右なら、左を取らないと機会を逃す
            if (!(r & 1)) {
                rvs.pb(seg[r - 1]);
            }
            l >>= 1;
            r = (r - 1) >> 1;
        }
        rer(i, sz(rvs) - 1) {
            ret = f(ret, rvs[i]);
        }
        return ret;
    }
    Monoid query(int a, int b, int k, int l, int r) {
        if (r <= a || b <= l)return e;
        else if (a <= l && r <= b)return seg[k];
        else {
            Monoid sl = query(a, b, (k << 1) | 1, l, (l + r) >> 1);
            Monoid sr = query(a, b, (k << 1) + 2, (l + r) >> 1, r);
            return f(sl, sr);
        }
    }
    //***************************
    //入れ替えることでbottomupと入れ替えられる
//    Monoid get(int a = 0, int b = -1) { return query(a, b == -1 ? n : b, 0, 0, n); }
    Monoid get(int a = 0, int b = -1) { return query_bottomup(a, b == -1 ? n : b); }
    Monoid getv(int a = 0, int b = -1) { return query_bottomup(a, b == -1 ? n : b); }

    //***************************
    int operator()(int a = 0, int b = -1) { return get(a, b); }
    Monoid operator[](int k) { return seg[k + n - 1]; }
#ifdef _DEBUG
    void debu() {
        rep(i, min(n, 10ll)) {
            int v = operator[](i).v;
            if (v == MIN(ll) || v == MAX(ll)) {
                cerr << "e ";
            } else {
                cerr << v << " ";
            }
        }
        cerr << "" << endl;
    }
#else
    inline void debu(){;}
#endif
};
