void update(int i, int x, vector<int> &data, int n) {
  i += n - 1;
  data[i] = x;
  while (i > 0) {
    i = (i - 1) / 2;
    data[i] = min(data[2 * i + 1], data[2 * i + 2]);
  }
}

int find(int a, int b, int k, int l, int r, vector<int> &data) {
  if (r <= a or b <= l) {
    return inf;
  } else if (a <= l and r <= b) {
    return data[k];
  } else {
    int vl = find(a, b, 2 * k + 1, l, (l + r) / 2, data);
    int vr = find(a, b, 2 * k + 2, (l + r) / 2, r, data);
    return min(vl, vr);
  }
}

