const int INF = 1e18;
const int MOD_N = 1e9+7;

template<typename T, typename F> class SegmentTree
{
   private:
      int n;
      vector<T> node;
      F f;
   public:
      SegmentTree(int sz, const F& func, T inf) : f(func) {
         n = 1; while(n < sz) n *= 2;
         node.resize(2*n-1, inf);
      }
      SegmentTree(const vector<T>& v, const F& func) : f(func) {
         int sz = v.size();
         n = 1; while(n < sz) n *= 2;
         node.resize(2*n-1);
         for(int i=0; i<sz; i++) node[i+n-1] = v[i];
         for(int i=n-2; i>=0; i--) node[i] = f(node[2*i+1], node[2*i+2]);
      }
      void update(int a, int b, T val, int k=0, int l=0, int r=-1) {
         // update [a, b)
         if(r < 0) r = n;
         if(r <= a || b <= l) return;
         if(a <= l && r <= b) { node[k] = val; return; }
         if(node[k] != -1) {
            node[2*k+1] = node[2*k+2] = node[k];
            node[k] = -1;
         }
         update(a, b, val, 2*k+1, l, (l+r)/2);
         update(a, b, val, 2*k+2, (l+r)/2, r);
      }
      T find(int a, int b, int k=0, int l=0, int r=-1) {
         // return f[a, b)
         if(r < 0) r = n;
         if(r <= a || b <= l) return INF;
         if (node[k] != -1) return node[k];
         // if(a <= l && r <= b) return node[k];
         int vl = find(a, b, 2*k+1, l, (l+r)/2);
         int vr = find(a, b, 2*k+2, (l+r)/2, r);
         return f(vl, vr);
      }
      void update(int i, T val) {
         update(i, i+1, val);
      }
      T find(int i) {
         return find(i, i+1);
      }
};
template<typename T> class RMQ {
   private:
