/// 2分セグメント木。RMQとかが解ける。
template<class T = int, class TParentFunc = const T& (*)(const T&, const T&)>
struct SegTree
{
	int size;
	vector<T> tree;
	TParentFunc parent;
	unsigned msb(unsigned v) { REP(i, 5) v |= v >> (1 << i); return (v >> 1) + 1; }

	SegTree(int count, TParentFunc parentBuilder = std::min, T initialFill = INF)
		: size(msb(count - 1) << 1)
		, tree(size * 2)
		, parent(parentBuilder)
	{
		fill(partof(tree, size, size), initialFill);
		rebuild();
	}

	// []を使うと更新されないのでrebuildすること。数が少なければupdateの方がよい。
	T& operator[](int i) { return tree[i + size]; }
	void rebuild() { RREP(i, size) { tree[i] = parent(tree[i * 2], tree[i * 2 + 1]); } }

	void update(int index, T value)
	{
		tree[index + size] = value;
		for (int i = (index + size) / 2; i > 0; i /= 2)
			tree[i] = parent(tree[i * 2], tree[i * 2 + 1]);
	}

	T query(int s, int e, int i, int l, int r, T value)
	{
		if (r <= s || e <= l) return value;
		if (s <= l && r <= e) return parent(value, tree[i]);
		value = query(s, e, i * 2, l, (l + r) / 2, value);
		value = query(s, e, i * 2 + 1, (l + r) / 2, r, value);
		return value;
	}

	T query(int start, int count, T initialValue)
	{
		return query(start, start + count, 1, 0, size, initialValue);
	}
};

