    int n, q;
    cin >> n >> q;
    SegmentTree seg(vector<long long>(n, 0));
    for (int i = 0; i < q; i++) {
        int c, x, y;
        cin >> c >> x >> y;
        if (c == 0) {
            seg.update(x, y);
        } else {
            cout << seg.get(x, y) << endl;
        }
    }
    return 0;
}

