template<typename T>
struct SegmentTree {
private:
    using Func = function<T(T, T)>;

    int n;
    vector<T> node;

    T init_v;
    Func func;

public:

    SegmentTree(vector<T> a, Func _func, T _init_v) {
        int sz = a.size();
        n = 1;
        init_v = _init_v;
        func = _func;

        while (n < sz) n *= 2;
        node.resize(2 * n, init_v);
        for (int i = 0; i < sz; i++) node[i + n - 1] = a[i];
        for (int i = n - 2; i >= 0; i--) node[i] = func(node[i * 2 + 1], node[i * 2 + 2]);
    }

    void update(int pos, T v) {
        int k = pos + n - 1;
        node[k] = v;
        while (k > 0) {
            k = (k - 1) / 2;
            node[k] = func(node[k * 2 + 1], node[k * 2 + 2]);
        }
    }

    T get(int pos) {
        int k = pos + n - 1;
        return node[k];
    }

    T query(int a, int b, int k = 0, int l = 0, int r = -1) {
        if (r < 0) r = n;
        if (r <= a || b <= l) return init_v;
        if (a <= l && r <= b)return node[k];
        T lv = query(a, b, k * 2 + 1, l, (l + r) / 2);
        T rv = query(a, b, k * 2 + 2, (l + r) / 2, r);
        return func(lv, rv);
    }

};


const int sqrtN = 1024;
const int INF = INT_MAX;

struct SqrtDecomposition {

    int N, K;
    vector<int> data;
    vector<int> bucket;

    SqrtDecomposition(int n) : N(n) {
        K = (N + sqrtN - 1) / sqrtN;
        data.assign(K * sqrtN, INF);
        bucket.assign(K, INF);
    }

    void update(int pos, int x) {
        int k = pos / sqrtN;
        data[pos] = x;
        int v = INF;
        for (int i = k * sqrtN; i < (k + 1) * sqrtN; i++) {
            v = min(v, data[i]);
        }
        bucket[k] = v;
    }

    int query(int a, int b) {
        int ret = INF;
        for (int k = 0; k < K; k++) {
            int l = k * sqrtN;
            int r = (k + 1) * sqrtN;
            if (r <= a or b <= l) continue;
            if (a <= l and r <= b) ret = min(ret, bucket[k]);
            for (int i = max(a, l); i < min(b, r); i++) {
                ret = min(ret, data[i]);
            }
        }
        return ret;
    }

};

int main() {

    int N, Q;
    scanf("%d %d", &N, &Q);

    SqrtDecomposition deco(N);

    while (Q--) {
        int c, x, y;
        scanf("%d %d %d", &c, &x, &y);
        if (c == 0) {
            deco.update(x, y);
        } else {
            printf("%d\n", deco.query(x, y + 1));
        }
    }

}

