template<class T>
class SqrtDecomp {
private:
    const size_t B;
    size_t _size;
    vector<T> rangeVal, elemVal;
public:
    SqrtDecomp(const size_t size = 0,
               T const &initVal = numeric_limits<T>::max(),
               const size_t rangeSize = 1)
        : B(rangeSize),
          _size(size),
          rangeVal(size/B + (size%B ? 1 : 0), initVal),
          elemVal(size, initVal){}

    size_t size() const {
        return _size;
    }

    T getMin(const size_t l, const size_t r) const {
        T res = numeric_limits<T>::max();
        if(l/B == r/B){
            for(size_t i = l; i < r; i++){
                res = min(res, elemVal[i]);
            }
        } else {
            if(l%B != 0){
                for(size_t i = l; i < (l/B+1)*B; i++){
                    res = min(res, elemVal[i]);
                }
            }
            for(size_t i = (l+B-1)/B; i < r/B; i++){
                res = min(res, rangeVal[i]);
            }
            if(r%B != 0){
                for(size_t i = r-r*B; i < r; i++){
                    res = min(res, elemVal[i]);
                }
            }
        }
        return res;
    }

    void setVal(const size_t p, const T &x){
        elemVal[p] = x;
        for(size_t i = p/B*B; i < min(size(), p/B*B+B); i++){
            rangeVal[i/B] = min(rangeVal[i/B], elemVal[i]);
        }
    }

    vector<T> to_a(int l = -1, int r = -1){
        if(l == -1) l = 0;
        if(r == -1) r = size();
        vector<T> res(r-l);
        for(int i = l; i < r; i++) res[i-l] = getMin(i,i+1);
        return res;
    }
};

