class SqrtDecomposition
{
    const int UNIT{2147483647};                            // 単位元
    const int OPERATOR(int a, int b) { return min(a, b); } // 演算子
    int bucket_size;

private:
    vector<int> elements;
    vector<int> buckets;

public:
    SqrtDecomposition(int n)
    {
        bucket_size = floor(sqrt(n));
        const int bucket_num = ceil(n, bucket_size);
        elements.assign(bucket_num * bucket_size, UNIT);
        buckets.assign(bucket_num, UNIT);
    }
    void update(int pos, int val)
    {
        int bucket_pos = pos / bucket_size;
        elements[pos] = val;
        int accumulation = UNIT;
        for (int i = bucket_pos * bucket_size; i < (bucket_pos + 1) * bucket_size; i++)
            accumulation = OPERATOR(elements[i], accumulation);

        buckets[bucket_pos] = accumulation;
    }
    int query(int left, int right)
    {
        int accumulation = UNIT;
        for (int i = 0; i < buckets.size(); i++)
        {
            int bucket_left = i * bucket_size;
            int bucket_right = (i + 1) * bucket_size;

            if (bucket_right <= left || right <= bucket_left)
                continue;

            if (left <= bucket_left && bucket_right <= right)
                accumulation = OPERATOR(buckets[i], accumulation);
            else
                for (int j = max(left, bucket_left); j < min(right, bucket_right); j++)
                    accumulation = OPERATOR(elements[j], accumulation);
        }

        return accumulation;
    }
};

signed main()
{
    cin.tie(0);
    ios::sync_with_stdio(0);

    int n, q;
    cin >> n >> q;
    SqrtDecomposition sq(n);

    for (int i = 0; i < q; i++)
    {
        int com, x, y;
        cin >> com >> x >> y;

        if (com == 0)
            sq.update(x, y);
        else
            cout << sq.query(x, y + 1) << "\n";
    }
}

