template <typename T>
struct SegTree {
	int n; // 与えられた配列の要素数m以上の最小の2冪
	T e; function<T(T, T)> op;
	vector<T> a; // Segment Treeを実装するためのノード数 2*n-1 の配列
	int num_of_elements(int m) { int res = 1; while (res < m) res *= 2; return res; }
	void chop(T &x, T y) { x = op(x, y); }
	SegTree(int m, T e_, const function<T(T, T)> &op_) {
		n = num_of_elements(m); e = e_; op = op_;
		a = vector<T>(2 * n - 1, e);
	}
	SegTree(vector<T> &a_, T e_, const function<T(T, T)> &op_) {
		SegTree(a_.size(), e_, op_);
		rep(i, a_.size()) a[i + n - 1] = a_[i];
		rep3(k, n - 2, -1) a[k] = op(a[2 * k + 1], a[2 * k + 2]);
	}
	void operate(int i, T val) {
		int k = i + n - 1;
		chop(a[k], val);
		while (k > 0) {
			k = (k - 1) / 2;
			chop(a[k], val);
		}
	}
	void update(int i, T val) {
		int k = i + n - 1;
		a[k] = val;
		while (k > 0) {
			k = (k - 1) / 2;
			a[k] = op(a[2 * k + 1], a[2 * k + 2]);
		}
	}
	T get(int i) { return a[i + n - 1]; }
	vector<T> gets() { vector<T> res(n); rep(i, n) res[i] = a[i + n - 1]; return res; }
	T get(int i, int j, int k, int l, int r) { // [i,j)
		if (j <= l or r <= i) return e;
		if (i <= l and r <= j) return a[k];
		T vl = get(i, j, 2 * k + 1, l, (l + r) / 2);
		T vr = get(i, j, 2 * k + 2, (l + r) / 2, r);
		return op(vl, vr);
	}
	T get(int i, int j) {
		return get(i, j, 0, 0, n);
	}
};

