template<class T, class F, T unit>
class SegmentTree {
  public:
    int n;
    vector<T> data;
    F f;
    SegmentTree(int nn) : n(1) {
        while(n < nn) n *= 2;
        data.resize(2 * n - 1, unit);
    }
    //index k in [0, n) ????????? val ?????´??°
    void update(int k, T val) {
        assert(0 <= k and k < n);
        k += n - 1;
        data[k] = val;
        while(k > 0) {
            k = parent(k);
            data[k] = f(data[left_child(k)], data[right_child(k)]);
        }
    }
    // [a, b) 
    int query(int a, int b) {
        assert(0 <= a and a < b and b <= n);
        return query(a, b, 0, 0, n);
    }
  private:
    //[a, b) ????????¨???, now???????????´???, [l,r)?????????????????´???
    T query(int a, int b, int now, int l, int r){
        if( out_of_range(a, b, l, r) ) return unit;
        if( within_range(a, b, l, r) ) return data[now];
        else { // cross range
            T vleft = query(a, b, left_child(now), l, (l + r) / 2);
            T vright = query(a, b, right_child(now), (l + r) / 2, r);
            return f(vleft, vright);
        }
    }
    bool out_of_range(int a, int b, int l, int r) { return r <= a or b <= l; }
    bool within_range(int a, int b, int l, int r) { return a <= l and r <= b; }
    int left_child(int i) { return i * 2 + 1; }
    int right_child(int i) { return i * 2 + 2; }
    int parent(int i) { return (i - 1) / 2; }
};

