template <typename T>
class segtree_min
{
  public:
    vector<T> data;
    int size;
    segtree_min<T>(int size_) : size(1)
    {
        while (size < size_)
            size <<= 1;
        data.assign(size * 2, numeric_limits<T>::max());
    }
    segtree_min<T>(vector<T> &src) : size(1)
    {
        while (size < src.size())
            size <<= 1;
        data.assign(size * 2, numeric_limits<T>::max());
        for (int i = 0; i < src.size(); i++)
        {
            update(i, src[i]);
        }
    };
    void update(int idx, int v)
    {
        int f = idx + size - 1;
        data[f] = v;
        while (f)
        {
            --f /= 2;
            data[f] = min(data[f * 2 + 1], data[f * 2 + 2]);
        }
    }
    T rmin(int l, int r)
    { //return min[l,r)
        int f = l + size - 1;
        int k = 1;
        while (f % 2 && l + k * 2 <= r)
        {
            f /= 2;
            k *= 2;
        }
        if (l + k > r)
            return numeric_limits<T>::max();
        if (l + k == r)
            return data[f];
        else
            return min(data[f], rmin(l + k, r));
    }
    void dump(){
        for(int i=0;i<size*2;i++){
            cout << data[i] << " ";
        }cout << endl;
    }
};

