template<class T>
class SqrtDecomp {
private:
    const size_t B;
    size_t _size;
    vector<T> rangeVal, elemVal;
public:
    SqrtDecomp(const size_t size = 0,
               T const &initVal = numeric_limits<T>::max(),
               const size_t rangeSize = 3000)
        : B(rangeSize),
          _size(size),
          rangeVal((size+B-1)/B, initVal),
          elemVal(size, initVal){}
    int size() const {
        return _size;
    }
    T getMin(const size_t l, const size_t r) const {
        T res = numeric_limits<T>::max();
        if(l/B == r/B){
            for(size_t i = l; i < r; i++){
                res = min(res, elemVal[i]);
            }
        } else {
            assert(false);
            for(size_t i = l; i < (l+B-1)/B*B; i++) res = min(res, elemVal[i]);
            for(size_t i = (l+B-1)/B; i < r/B; i++) res = min(res, rangeVal[i]);
            for(size_t i = r/B*B; i < r; i++) res = min(res, elemVal[i]);
        }
        return res;
    }
    void setVal(const size_t pos, const T &x){
        elemVal[pos] = x;
        rangeVal[pos/B] = min(rangeVal[pos/B], x);
    }
};

int main(){
    int n,q;
    while(cin >> n >> q){
        SqrtDecomp<int32_t> rmq(n);
        for(int i = 0; i < q; i++){
            int a,b,c;
            cin >> a >> b >> c;
            if(a == 0){
                rmq.setVal(b,c);
            } else {
                cout << rmq.getMin(b,c+1) << endl;
            }
        }
    }
}

