    cin >> n >> q;
    vector<int> com(q), x(q), y(q);
    REP(i, q) cin >> com[i] >> x[i] >> y[i];
    vector<int> a(n, INF);

    SegmentTree st(a);

    REP(i, q){
        if(com[i]) cout << st.query(x[i], y[i] + 1) << endl;
        else st.update(x[i], y[i]);
    }
    return 0;
}

