class RMQ {
  static const int MAXN=1<<17;
private:
  int n;
  int dat[2*MAXN-1];
public:
  RMQ (int N) {
    init(N);
  }
  void init(int N) {
    n=1;
    while (n<N) {
      n*=2;
    }
    for (int i=0; i<2*n-1; i++) {
      dat[i]=INT_MAX;
    }
  }
  void update(int i,int x) {
    i+=n-1;
    dat[i]=x;
    while (i) {
      i=(i-1)/2;
      dat[i]=min(dat[2*i+1],dat[2*i+2]);
    }
  }
  int find (int s,int t,int k,int l,int r) {
    if (r<=s || t<=l) {
      return INT_MAX;
    }
    if (s<=l && r<=t) {
      return dat[k];
    } else {
      int m=(l+r)/2;
      int vl=find(s,t,k*2+1,l,m);
      int vr=find(s,t,k*2+2,m,r);
      return min(vl,vr);
    }
  }
  int find(int s,int t) {
   return find(s,t,0,0,n);
   }
};
