const int sqrtN = 512;

struct SqrtDecomposition {
	int N, K;
	vector<int> data;
	vector<int> bucketMin;
	SqrtDecomposition(int n) : N(n) {
		K = (N + sqrtN - 1) / sqrtN;
		data.assign(K*sqrtN, INT_MAX);
		bucketMin.assign(K, INT_MAX);
	}

	void update(int x, int y) {
		int k = x / sqrtN;
		data[x] = y;
		int minV = INT_MAX;
		for (int i = k * sqrtN; i < (k + 1)*sqrtN; ++i) {
			minV = min(minV, data[i]);
		}
		bucketMin[k] = minV;
	}

	//[x, y)
	int find(int x, int y) {
		int minV = INT_MAX;
		for (int k = 0; k < K; ++k) {
			int l = k * sqrtN, r = (k + 1) * sqrtN;
			if (r <= x || y <= l) continue;
			if (x <= l && r <= y) {
				minV = min(minV, bucketMin[k]);
			}
			else {
				for (int i = max(x, l); i < min(y, r); ++i) {
					minV = min(minV, data[i]);
				}
			}
		}
		return minV;
	}
};
int main() {
	cin.tie(0);
	ios::sync_with_stdio(false);

	int n, q; cin >> n >> q;
	SqrtDecomposition sd(n);

	for (int i = 0; i < q; ++i) {
