// intersects returns whether [a1, b1) \cap [a2, b2) is nonempty
bool intersects(int a1, int b1, int a2, int b2) {
  if (a1 == b1 or a2 == b2)
    return false;
  return ((a2 >= a1 and a2 < b1) or (a1 >= a2 and a1 < b2));
}

struct Seg {
  vector<Node> v;
  int n;
  // pre : x is s.t. op(y, x) = y, all y
  //       examples: 0 for op=sum, MAX for op=min, MIN for op=max, etc
  Seg(int n_in, int x) {
    n = n_in + (n_in % 2); // make tree full
    v = vector<Node>(2 * n);
    for (int k = n; k < 2 * n; ++k)
      v[k] = {k - n + 1, k - n + 2, x};
    for (int k = n - 1; k > 0; --k)
      v[k] = {v[2 * k].start, v[2 * k + 1].end,
              min(v[2 * k].x, v[2 * k + 1].x)};
  }
  int Get(int p, int s, int t) {
    if (s <= v[p].start and t >= v[p].end) {
      return v[p].x;
    } else if (intersects(s, t, v[2 * p].start, v[2 * p].end) and
               intersects(s, t, v[2 * p + 1].start, v[2 * p + 1].end)) {
      return min(Get(2 * p, s, t), Get(2 * p + 1, s, t));
    } else if (intersects(s, t, v[2 * p].start, v[2 * p].end)) {
      return Get(2 * p, s, t);
    } else {
      return Get(2 * p + 1, s, t);
    }
  }
  int Get(int s, int t) { // [s, t)
    return Get(1, s, t);
  }
  void Set(int i, int x) { // 1-indexed
    v[n - 1 + i].x = x;
    for (int p = (n - 1 + i) / 2; p > 0; p /= 2)
      v[p].x = min(v[2 * p].x, v[2 * p + 1].x);
  }
};

int main() {
  int n, q;
  cin >> n >> q;
  Seg seg(n, numeric_limits<int>::max());
  int c, x, y;
  while (cin >> c >> x >> y) { // 0-indexed and closed => convert
    if (c == 0)
      seg.Set(x + 1, y);
    if (c == 1)
      cout << seg.Get(x + 1, y + 2) << endl;
  }
}

