// 1-index
template <class Monoid>
class SegTree {
   private:
    using T = typename Monoid::T;
    size_t n;
    const size_t sz;
    typedef tuple<int,size_t,size_t> tp;
    vector<T> t;

    void prop_to(size_t i) { t[i] = Monoid::op(t[2*i+1],t[2*i+2]); }

   public:
    SegTree(size_t m, const T& v = Monoid::identity())
        : sz(m), t(2*m-1, v) {}

    template <class InputIt>
    SegTree(InputIt first, InputIt last)
        : sz(distance(first, last)){
        n = 1; while(n < sz) n <<= 1;
        t.resize(2*n-1,Monoid::identity());
        copy(first, last, begin(t) + (n-1));
        for (int i = (n-2); i >= 0; --i) prop_to(i);
    }

    void set(size_t i, const T& v) {
        t[i += (n-1)] = v;
        while (i && ((--i) >>= 1)) prop_to(i);
        if(n >= 2) prop_to(0);
    }

    //T get(size_t i) { return t[i + (n-1)]; }

    T getminval(size_t l, size_t r) {
        T ret = Monoid::identity();
        stack<tp> st;
        st.push(make_tuple(0,0,n));
        while (!st.empty()) {
            tp state = st.top();st.pop();
            size_t lb = get<1>(state);
            size_t ub = get<2>(state);
            int node = get<0>(state);
            if (r <= lb || ub <= l) continue;
            if (l <= lb && ub <= r) ret = Monoid::op(ret,t[node]);
            else {
                st.push(make_tuple(2*node+1,lb,(lb+ub)/2));
                st.push(make_tuple(2*node+2,(lb+ub)/2,ub));
            }
        }
        return ret;
    }
};

