const ll INF = pow(2,33);

struct SegmentTree{
    vector<ll> node;
    ll cou;
    ll size;
    SegmentTree(int n=1, int first_value = 0){
        cou = 0;
        while( n > (int)pow(2,cou) ) cou++;
        cou++;
        node.resize((int)pow(2,cou),first_value);
        size = (int)pow(2,cou);
    }
    void update(int index, ll value ){
        update_node(convert(index),value);
    }
    void update_node(int node_index, ll value ){
        // 本人と親を更新

        // 処理次第
        node[node_index] = value;

        if( node_index == 0 ) return;

        ll c1,c2;
        c1 = child1(parent(node_index));
        c2 = c1+1;
        // 処理次第。最小値の場合は、左右の子の小さい方を値とする   
        ll val = min( node[c1], node[c2] );
        update_node(parent(node_index),val);
    }
    // [a,b)に対して答える
    ll query(int a, int b, int k, int l, int r) {
        if (r <= a || b <= l){
            return INF; // 区間が被らない場合は INF を返す
        }
        if (a <= l && r <= b){
            return node[k]; // ノード k の担当範囲がクエリ区間 [a, b) に完全に含まれる
        }else {
            // 一部だけ範囲が被る場合は左右の子に委託する
            ll c1 = query(a, b, 2 * k + 1, l, (l + r) / 2); // 左の子に値を聞く
            ll c2 = query(a, b, 2 * k + 2, (l + r) / 2, r); // 右の子に値を聞く
            return min(c1, c2); // 左右の子の値の min を取る
        }
    }

    int parent(int node_index){
        return (node_index-1)/2;
    }
    int convert(int origin){
        return origin    +(int)(pow(2,cou-1)-1);
    }
    int rconvert(int node_index){
        return node_index-(int)(pow(2,cou-1)-1);
    }
    int child1( int node_index){
        return node_index*2+1;
    }
};

int main(void){
    ll n,q;
    std::cin >> n>>q;
    SegmentTree seg(n,(int)(pow(2,31)-1));

    for (int i = 0; i < q; i++) {
        int c,x,y;
        std::cin >> c>>x>>y;
        if(c==0){
            seg.update(x,y);
        }else{
            std::cout << seg.query(x,y+1,0,0,seg.size/2) << std::endl;
        }
    }
}

