#define bitsize 31
public:
	dynamic_wavelet_matrix(std::vector<T> &a) :tree(bitsize) {
		length = a.size();
		std::vector<std::vector<char>> t(2, std::vector<char>(a.size()));
		std::vector<std::vector<uint32>> c(2, std::vector<uint32>(a.size()));
		i = a.size();
		while (~(--i)) {
			c[bitsize & 1 ^ 1][i] = i;
			t[bitsize & 1 ^ 1][i] = a[i] >> (bitsize - 1) & 1;
		}
		tree[bitsize - 1].set(t[bitsize & 1 ^ 1]);
		i = bitsize;
		uint32 itr, j;
		while (--i) {
			itr = 0;
			for (j = 0;j < a.size();++j) {
				if (!t[i&1][j]) {
					c[i & 1 ^ 1][itr] = c[i & 1][j];
					t[i & 1 ^ 1][itr] = a[c[i & 1][j]] >> (i - 1) & 1;
					++itr;
				}
			}
			for (j = 0;j < a.size();++j) {
				if (t[i & 1][j]) {
					c[i & 1 ^ 1][itr] = c[i & 1][j];
					t[i & 1 ^ 1][itr] = a[c[i & 1][j]] >> (i - 1) & 1;
					++itr;
				}
			}
			tree[i - 1].set(t[i & 1 ^ 1]);
		}
		return;
	};
	void insert(uint32 position, const T &data) {
		i = bitsize;
		while (~(--i)) {
			if (tree[i].insert(data >> i & 1, position)) position = tree[i].border + tree[i].rank(position);
			else position -= tree[i].rank(position);
		}
		return;
	}
	void erase(uint32 position) {
		i = bitsize;
		while (~(--i)) {
			if (tree[i].erase(position)) position = tree[i].border + tree[i].rank(position);
			else position -= tree[i].rank(position);
		}
		return;
	}
	void update(uint32 position, const T &data) {
		erase(position);
		insert(position, data);
		return;
	}
	T min(uint32 begin, uint32 end) {
		T ret = 0;
		uint32 a, b;
		i = bitsize;
		while (~(--i)) {
			a = tree[i].rank(begin);
			b = tree[i].rank(end);
			if (b + begin == a + end) {
				ret |= (T)1 << i;
				begin = a + tree[i].border;
				end = b + tree[i].border;
			}
			else {
				begin -= a;
				end -= b;
			}
		}
		return ret;
	}
	T access(uint32 position) {
		T ret = 0;
		i = bitsize;
		while (~(--i)) {
			if (tree[i].access(position)) {
				ret |= (T)1 << i;
				position = tree[i].border + tree[i].rank(position);
			}
			else position -= tree[i].rank(position);
		}
		return ret;
	}
	T rank(uint32 begin, uint32 end, const T &data) {
		i = bitsize;
		while (~(--i)) {
			if (data >> i & 1) {
				begin = tree[i].border + tree[i].rank(begin);
				end = tree[i].border + tree[i].rank(end);
			}
			else {
				begin -= tree[i].rank(begin);
				end -= tree[i].rank(end);
			}
		}
		return end - begin;
	}
	T rangefreq(uint32 begin, uint32 end, uint32 rank) {
		T ret = 0;
		uint32 a, b;
		i = bitsize;
		while (~(--i)) {
			a = tree[i].rank(begin);
			b = tree[i].rank(end);
			if (b > a + rank) {
				ret |= (T)1 << i;
				begin = a + tree[i].border;
				end = b + tree[i].border;
			}
			else {
				begin -= a;
				end -= b;
				rank -= b - a;
			}
		}
		return ret;
	}
