    void update(int x, ll val) {
        {
            //最下段のノードにアクセスする
            x += (n - 1);
            node[x] = val;
            while(x > 0) {
                x = (x - 1) / 2;
                node[x] = min(node[2 * x + 1], node[2 * x + 2]);
            }
        }
    }

    // 対象区間 : 各ノードがカバーしている区間
    // 要求区間 [a, b) 中の要素の最小値を答える
    // k := 自分がいるノードのインデックス
    // 対象区間は [l, r) にあたる
    ll getmin(int a, int b, int k = 0, int l = 0, int r = -1) {
        //最初に呼び出された時の対象区間は[0, n)
        if(r < 0) {
            r = n;
        }
        if(r <= a || b <= l) {
            //[l.r) \cap [a, b)_= \emptyset
            //要求区間が対象区間と交わらない->適当に返す
            return INF;
        }
        if(a <= l and r <= b) {
            //要求区間が対象区間を完全にconver
            //[l, r) \subset [a, b)
            return node[k];
        }
        //
        //左側の子がvl
        //右側の子がvr
        //新しい対象区間は，現在の対象
        ll vl = getmin(a, b, 2 * k + 1, l, (l + r) / 2);
        ll vr = getmin(a, b, 2 * k + 2, (l + r) / 2, r);
        return min(vl, vr);
    }
};

int main() {
    int N, Q;
    cin >> N >> Q;
    SegmentTree seg(vector<ll>(N, pow(2, 31) - 1));
    string ans;
    for(int i = 0; i < Q; i++) {
        int c, x, y;
        cin >> c >> x >> y;
        if(c == 0)
            seg.update(x, (ll)y);
        else {
            ans += to_string(seg.getmin(x, y + 1)) + "\n";
        }
    }
    cout << ans.substr(0, ans.size() - 1) << endl;
    return 0;
}

