template<typename Monoid>
struct SegmentTree {
    using T = typename Monoid::T;
    const size_t n;
    vector<T> t;

    void prop_to(std::size_t i) { t[i] = Monoid::op(t[i << 1], t[i << 1 | 1]); }

    SegmentTree(size_t n, const T& v = Monoid::identity()) : n(n), t(n << 1, v) {}
    template <class InputIt>
    SegmentTree(InputIt first, InputIt last) : n(distance(first, last)), t(n << 1, Monoid::identity()) {
        copy(first, last, begin(t) + n);
        for (size_t i = n; i > 0; i--) prop_to(i);
    }

    void update(size_t i, const T& v) {
        t[i += n] = v;
        while (i >>= 1) prop_to(i);
    }
    T query(size_t l, size_t r) {
        T res = Monoid::identity();
        for (l += n, r += n; l < r; l >>= 1, r >>= 1) {
            if (l & 1) res = Monoid::op(res, t[l++]);
            if (r & 1) res = Monoid::op(res, t[--r]);
        }
        return res;
    }
    T get(size_t i) { return t[i + n]; }
};

struct RMQ {
    using T = int;
    static T op(T a, T b) { return min(a, b); }
    static constexpr T identity() { return (1LL << 31) - 1; }
};

template <class T>
struct SegmentTreeRecursive {
    using func = function<T(T, T)>;
    int size;
    vector<T> data;
    func merger, updater;
    T ident;
    SegmentTreeRecursive(int n, func update_func, func merge_func, T identity_element)
     : updater(update_func), merger(merge_func), ident(identity_element) {
        size = 1;
        while (size < n) size <<= 1;
        data.resize(size * 2, ident);
    }
    void update(int i, T x) {
        i += size - 1;
        data[i] = updater(data[i], x);
        while (i > 0) {
            i = (i - 1) / 2;
            data[i] = merger(data[i * 2 + 1], data[i * 2 + 2]);
        }
    }
    T query(int wishL, int wishR, int watchL = 0, int watchR = -1, int k = 0) {
        if(watchR == -1) watchR = size;
        if(watchR <= wishL || wishR <= watchL) return ident;
        if(wishL <= watchL && watchR <= wishR) return data[k];
        T ld = query(wishL, wishR, watchL, (watchL + watchR) / 2, k * 2 + 1);
        T rd = query(wishL, wishR, (watchL + watchR) / 2, watchR, k * 2 + 2);
        return merger(ld, rd);
    }
    T at(int i) {
        return data[i+size-1];
    }
};

