    }

    REP(i,q){
        ll com,x,y;
        scanf("%lld%lld%lld",&com,&x,&y);

        if(com == 0)
            a.update(y,x);
        else{
            printf("%lld\n",a.range_min(x,y + 1));
        }
    }
    return 0;
}

