int _find(int a, int b, int k, int l, int r){
  if(a <= l && r <= b) return segtree[k];
  else if(r <= a || b <= l) return (1L<<31)-1;
  else{
    int lv = _find(a, b, k * 2 + 1, l, (l + r) / 2);
    int rv = _find(a, b, k * 2 + 2, (l + r) / 2, r);
    return min(lv, rv);
  }
}

