struct node{
  int first;// [0],1,2,3
  int mid;  // 0,1,[2],3
  int last; // 0,1,2,[3]
  int min;
};

node nodes[MAX_V*2];
int offset;

void update(int i, int x){
  nodes[offset+i].min=x;
  if(offset+i==0) return;
  int p=(offset+i-1)/2;
  while(true){
    int minimum = min(nodes[p*2+1].min,nodes[p*2+2].min);
    if(nodes[p].min!=minimum){
      nodes[p].min=minimum;
      p=(p-1)/2;
    }
    else break;
  }
}
int find(int s, int t, int i){
  if(nodes[i].first==s&&nodes[i].last==t)
    return nodes[i].min;
  if(t<nodes[i].mid)
    return find(s,t,i*2+1);
  if(s>=nodes[i].mid)
    return find(s,t,i*2+2);
  return min(find(s,nodes[i].mid-1,i*2+1),find(nodes[i].mid,t,i*2+2));
}

