const ll INF=(1LL<<31)-1;

class Segtree{
    public:
        ll N=1;
        ll dat[1000000];
        explicit Segtree(ll sz){
            while(N<sz) N*=2;
        }

        ll unit(){
            return INF;
        }
        ll calc(ll a,ll b){
            return min(a,b);
        }
        void update(ll k,ll a){
            k+=N-1;
            dat[k]=a;
            while(k>0){
                k=(k-1)/2;
                this->dat[k]=calc(dat[2*k+1],dat[2*k+2]);
            }
        }
        ll query(ll a,ll b,ll k,ll l,ll r){
            if(r<=a||b<=l)return unit();
            if(a<=l&&r<=b)return dat[k];
            ll m=(l+r)/2;
            ll u=query(a,b,2*k+1,l,m);
            ll v=query(a,b,2*k+2,m,r);
            return calc(u,v);
        }


        void m_init(){
            for(int i=0;i<N;i++)update(i,INF);
        }
};

