const ll tS = 1LL << 20;

vll sT(tS, (1LL << 31) - 1);

void update(ll i, ll x) {
  i += tS / 2;
  sT[i] = x;
  while (true) {
    i /= 2;
    if (i == 0) break;
    sT[i] = min(sT[2 * i], sT[2 * i + 1]);
  }
}

ll find(ll l, ll r) {
  ll ans = INF;
  l += tS / 2;
  r += tS / 2 + 1;
  while (l < r) {
    if (l % 2 == 1) {
      chmin(ans, sT[l]);
      l++;
    }
    l /= 2;
    if (r % 2 == 1) {
      chmin(ans, sT[r-1]);
      r--;
    }
    r /= 2;
  }
  return ans;
}

