template<class T>
class SqrtDecomp {
    //private:
public:
    const size_t B;
    T const initVal;
    size_t _size;
    vector<T> rangeVal, elemVal;
public:
    SqrtDecomp(const size_t size = 0,
               T const &initVal = numeric_limits<T>::max(),
               const size_t rangeSize = 150)
        : B(rangeSize),
          initVal(initVal),
          _size(size),
          rangeVal(size/B + 1, initVal),
          elemVal(size, initVal){}

    size_t size() const {
        return _size;
    }

    T getMin(size_t l, const size_t &r) const {
        T res = numeric_limits<T>::max();
        while(l < r){
            if(l%B == 0 && l + B <= r){
                res = min(res, rangeVal[l/B]);
                l += B;
            } else {
                res = min(res, elemVal[l]);
                l++;
            }
        }
        return res;
    }

    void setVal(const size_t p, const T &x){
        elemVal[p] = x;
        rangeVal[p/B] = initVal;
        size_t l = p - p%B, r = l + B, s = l/B;
        for(size_t i = l; i < min(r,size()); i++){
            rangeVal[s] = min(rangeVal[s], elemVal[i]);
        }
    }

    vector<T> to_a(int l = -1, int r = -1){
        if(l == -1) l = 0;
        if(r == -1) r = size();
        vector<T> res(r-l);
        for(int i = l; i < r; i++) res[i-l] = getMin(i,i+1);
        return res;
    }
};

vector<int> naive(int n, int q, const vi &a, const vi &b, const vi &c){
    vector<int> ans;
    vector<int> arr(n,(1LL<<31)-1);
    for(int i = 0; i < q; i++){
        if(a[i] == 0){
            arr[b[i]] = c[i];
        } else {
            int res = (1LL<<31)-1;
            for(int j = b[i]; j <= c[i]; j++){
                res = min(res,arr[j]);
            }
            ans.push_back(res);
        }
    }
    return ans;
}

vector<int> solve(int n, int q, const vi &a, const vi &b, const vi &c){
    vector<int> ans;
    SqrtDecomp<int32_t> rmq(n, (1LL<<31)-1);
    for(int i = 0; i < q; i++){
        if(a[i] == 0){
            rmq.setVal(b[i],c[i]);
        } else {
            ans.push_back(rmq.getMin(b[i],c[i]+1));
        }
    }
    return ans;
}

