void initRMQ() {

	int n_ = 2 * n - 1;
	n = 1;
	while (n < n_)
		n *= 2;
	for (int i = 0; i < 2 * n - 1; ++i)
		segmenttree[i] = infinit;


}

void update(int x, int y) {

	int i = x + n - 1;
	segmenttree[i] = y;

	while (i > 0) {
		i = (i - 1) / 2;
		segmenttree[i] = min(segmenttree[i * 2 + 1], segmenttree[i * 2 + 2]);

	}

}

