typedef long long ll;

const int INF = 2147483647;
// const int INF = (1 << 30) - 1;
// const ll LL_INF = (1LL << 62) - 1;
// const ll MOD = 1e9 + 7;

// セグメント木による RMQ (Range Minimum Query) の実装
// RMQ以外にする場合は、minの部分を全て他の関数に置換する
//
// 計算量
// - 初期化: O(nlogn)
//   - O(n)でも実装できるが、O(nlogn)の実装になっている
//   - init後にupdateで初期化
// - update: O(logn)
// - query: O(logn)

const int MAX_N = 1 << 17;

// セグメント木を持つグローバル配列
int n;
int dat[2 * MAX_N - 1];

// 初期化
void init(int n_) {
  // 簡単のため、要素数を2のべき乗に
  n = 1;
  while (n < n_) {
    n *= 2;
  }

  // すべての値をINFに
  for (int i = 0; i < 2 * n - 1; i++) {
    dat[i] = INF;
  }
}

// k番目の値 (0-indexed) をaに変更
void update(int k, int a) {
  // 葉の節点
  k += n - 1;
  dat[k] = a;
  // 登りながら更新
  while (k > 0) {
    k = (k - 1) / 2;
    dat[k] = min(dat[k * 2 + 1], dat[k * 2 + 2]);
  }
}

// [a, b) の最小値を求める
// 後ろのほうの引数は、計算の簡単のための引数。
// kは節点の番号、l, rはその節点が [l, r) に対応づいていることを表す。
// したがって、外からは inner_query(a, b, 0, 0, n) として呼ぶ。
int inner_query(int a, int b, int k, int l, int r) {
  // [a, b) と [l, r) が交差しなければ INF
  if (r <= a || b <= l) {
    return INF;
  }

  // [a, b) が [l, r) を完全に含んでいれば、この節点の値
  if (a <= l && r <= b) {
    return dat[k];
  } else {
    // そうでなければ、2つの子の最小値
    int vl = inner_query(a, b, k * 2 + 1, l, (l + r) / 2);
    int vr = inner_query(a, b, k * 2 + 2, (l + r) / 2, r);
    return min(vl, vr);
  }
}

// [a, b) の最小値を求める
int query(int a, int b) { return inner_query(a, b, 0, 0, n); }

int n_, q;

// http://judge.u-aizu.ac.jp/onlinejudge/description.jsp?id=DSL_2_A&lang=jp
int main() {
  ios::sync_with_stdio(false);
  cin.tie(0);
  cin >> n_ >> q;
  init(n_);

  for (int i = 0; i < q; i++) {
    int com, x, y;
    cin >> com >> x >> y;

    if (com == 0) {
      update(x, y);
    } else {
      cout << query(x, y + 1) << endl;
    }
  }
  return 0;
}

#include <bits/stdc++.h>
using namespace std;
using ll = long long;

template <typename T>
class node {
public:
	node<T> *l, *r;
	T val;
	node() {}
	node(T val_, node<T>* l_ = nullptr, node<T>* r_ = nullptr) : l(l_), r(r_), val(val_) {}
	void init(T val_, node<T>* l_ = nullptr, node<T>* r_ = nullptr) {
		val = val_;
		l = l_;
		r = r_;
	}
};

template <typename T>
class DynamicSegmentTree {
	using func_t = function<T(T, T)>;
	const ll n;
	const T id;
	func_t merge;
	node<T> *root;
	vector<node<T>> pool;
	int it;
	ll size(ll n) {
		ll res = 1;
		while (res < n) res <<= 1;
		return res;
	}
	node<T> *new_node() {
		pool[it].init(id);
		return &pool[it++];
	}
	T sub(ll l, ll r, node<T>* n, ll lb, ll ub) {
		if (ub <= l || r <= lb) return id;
		if (l <= lb && ub <= r) return n->val;
		return merge(n->l != nullptr ? sub(l, r, n->l, lb, (lb + ub) / 2) : id, n->r != nullptr ? sub(l, r, n->r, (lb + ub) / 2, ub) : id);
	}
	void suc(ll v, node<T>* n, ll lb, ll ub, T val) {
		if (ub - lb <= 1) {
			n->val = val;
			return;
		}
		ll c = (lb + ub) / 2;
		if (v < c) {
			if (n->l == nullptr) n->l = new_node();
			suc(v, n->l, lb, c, val);
		}
		else {
			if (n->r == nullptr) n->r = new_node();
			suc(v, n->r, c, ub, val);
		}
		n->val = merge(n->l != nullptr ? n->l->val : id, n->r != nullptr ? n->r->val : id);
	}
public:
	DynamicSegmentTree(ll n_, int max_, T id_, func_t merge_) :
		n(size(n_)), id(id_), merge(merge_), pool(max_)
	{
		it = 0;
		root = new_node();
	}
	void Update(ll p, T val) {
		suc(p, root, 0, n, val);
	}
	T Find(ll l, ll r) {
		return sub(l, r + 1, root, 0, n);
	}
};

int main()
{
	int n, q, com, x, y;
	cin >> n >> q;
	DynamicSegmentTree<int> dst(1000000000000ll, 10000000, 0x7fffffff, [](int l, int r) { return min(l, r); });
	while (q--) {
		cin >> com >> x >> y;
		if (com) {
			cout << dst.Find(x, y) << endl;
		}
		else {
			dst.Update(x, y);
		}
	}
	return 0;
}

#include <bits/stdc++.h>
using namespace std;



unsigned long long xor128() {
    static unsigned long long rx = 123456789, ry = 362436069, rz = 521288629, rw = 88675123;
    unsigned long long rt = (rx ^ (rx << 11));
    rx = ry;
    ry = rz;
    rz = rw;
    return (rw = (rw ^ (rw >> 19)) ^ (rt ^ (rt >> 8)));
}


template<class T> class treap{
public:

    struct node{
        T val,sum,mini,maxi;
        node *left , *right;
        bool init;
        int pri;
        unsigned sz;
        node(){
            sz = 1;
            init=true;
            pri=xor128();
            left = right = NULL;
        }
        node(T val,int pri):val(val),pri(pri),sz(1){
            init = false;
            sum = 0;
            mini = INT_MAX;
            maxi = INT_MIN;
            left = right = NULL;
        }
    };

    node *root;

    treap():root(NULL){}

    treap(int n):root(NULL){
        for(int i=0;i<n;i++){
            init_insert();
        }
    }

    unsigned size(){ return size(root); }
    unsigned size(node *v){ return !v?0:v->sz; }
    T sum(node *v){ return !v || v->init ?    0    : v->sum  ; }
    T MIN(node *v){ return !v || v->init ? INT_MAX : v->mini ; }
    T MAX(node *v){ return !v || v->init ? INT_MIN : v->maxi ; }

    node *update(node *v){
        v->sz = size(v->left)+size(v->right)+1;
        v->sum = sum(v->left)+sum(v->right)+ (v->init?0:v->val);
        v->mini = min( v->init?INT_MAX:v->val , min( MIN(v->left) , MIN(v->right) ) );
        v->maxi = max( v->init?INT_MIN:v->val , max( MAX(v->left) , MAX(v->right) ) );
        return v;
    }

    node *merge(node *s , node *t){
        if( !s || !t )return s?s:t;
        if( s->pri > t->pri){
            s->right = merge( s->right , t );
            return update(s);
        }
        else{
            t->left = merge( s, t->left);
            return update(t);
        }
    }

    pair<node*,node*> split(node *v,unsigned k){

        if(!v)return pair<node*,node*>(NULL,NULL);

        if( k <= size(v->left) ){
            pair<node*,node*> s = split( v->left, k );
            v->left = s.second;
            return make_pair( s.first , update(v) );
        }

        else{
            pair<node*,node*> s = split( v->right, k-size(v->left)-1 );
            v->right = s.first;
            return make_pair( update(v) , s.second );
        }
    }

    node *find(unsigned k){
        node *v=root;
        while(v){
            unsigned s = size(v->left);
            if( s > k ) v = v->left;
            else if( s == k )break;
            else{
                v = v->right;
                k -= s+1;
            }
        }
        return v;
    }

    void point_add(int k,T val){ point_add(root,k,val); }
    void point_add(node *v,int k,T val){
        if( k < size(v->left) )point_add(v->left,k,val);
        else if( k > size(v->left) )point_add(v->right,k-size(v->left)-1,val);
        else v->val += val,v->init=false;
        update(v);
    }

    void point_update(int k,T val){ point_update(root,k,val); }
    void point_update(node *v,int k,T val){
        if( k < size(v->left) )point_update(v->left,k,val);
        else if( k > size(v->left) )point_update(v->right,k-size(v->left)-1,val);
        else v->val = val,v->init=false;
        update(v);
    }

    // [ l , r )
    int range_query(unsigned l,unsigned r,int Q){
        T val;

        pair<node*,node*> R = split( root , r );
        pair<node*,node*> L = split( R.first , l );
        node *M = L.second;

        if(Q==1)val=M->mini;
        if(Q==2)val=M->maxi;
        if(Q==3)val=M->sum;

        root = merge(merge(L.first,M),R.second);

        return val;
    }

    int getval(int k){
        node *t=find(k);
        return t->val;
    }

    void init_insert(){
        node *t = root;
        int k = 0;
        pair<node*,node*> s = split(t,k);
        t = merge( s.first , new node());
        t = merge( t , s.second );
        root = update(t);
    }
    void insert(unsigned k,T val){ root = insert(root,k,val,xor128()); }
