template <int NV>
class SegTree
{
  int n;
  vector <Node> seg_tree;
  Node MAXNODE(){
    return Node(INT_MAX);
  }
  Node comp(Node &a, Node &b) {
    if (a.x < b.x) {
      return a;
    }else{
      return b;
    }
  }
 public:
  SegTree(){
    seg_tree.resize(NV * 2, Node());
  }
  void init(int n_){
    n = 1;
    while(n < n_) {
      n *= 2;
    }
  }

  inline void update(int k, Node &a) {//k????????????(0-indexed)???a????????´
    k += n - 1;
    seg_tree[k] = a;
    while (k > 0) {
      k = (k - 1) / 2;
      seg_tree[k] = comp(seg_tree[k * 2 + 1], seg_tree[k * 2 + 2]);
    }
  }
  inline Node query(int a, int b, int k, int l, int r) {
    if (r <= a || b <= l) {
      return MAXNODE();
    }
    if (a <= l && r <= b) {
      return seg_tree[k];
    }
    Node vl = query(a, b, k * 2 + 1, l, (l + 2) / 2);
    Node vr = query(a, b, k * 2 + 2, (l + r) / 2, r);
    return comp(vl, vr);
  }
  inline Node query(int a, int b) {
    return query(a, b, 0, 0, n);
