struct RmQ{
  //Ranged minimum Query

  int n;
  vector<int> node;
  //1-indexed

  RmQ(int size){
    int t=1;
    while(t<size){
      t*=2;
    }

    node.clear();
    node.resize(t*2,INT_MAX);
    n=t;
  }

  void update(int i,int val){
    i=i+n;
    node[i]=val;
    i/=2;

    while(i>0){
      node[i]=min(node[i*2],node[i*2+1]);
      i/=2;
    }
  }

  int find(int s,int t,int k=1,int left=0,int right=-1){
    if(right<0)right=n;

    if(right<=s||left>=t){
      return INT_MAX;
    }

    if(left>=s&&right<=t){
      return node[k];
    }

    return min(find(s,t,k*2,left,(left+right)/2),find(s,t,k*2+1,(left+right)/2,right));
  }
};

