//セグメント木によるRMQの実装(Range Minimum Query)
//セグメント木はモノイド（例:和、積、min, max, gcd, lcm)に使える((a*b)*c=a*(b*c) かつ 単位元eが存在)
//関数は、init, update, query
const int MAX_N = 1 << 17;
int n_edited; //頂点数
int seg_dat[2 * MAX_N - 1];

void init(int n_){ //初期化、要素数を２のべき乗(n_edited)にする
    n_edited=1; // n_editedの初期化
    while(n_edited<n_){
        n_edited *= 2;
    }
    for(int i=0; i<2*n_edited-1;i++){
        seg_dat[i] = INF; //最小値を求めるから、INFで初期化
    }
}

void update(int k, int a){ //k(0-indexed)番目の値をaに変更
    k += n_edited-1;
    seg_dat[k] = a;
    while(k>0){
        k = (k-1)/2;
        seg_dat[k] = min(seg_dat[k*2+1],seg_dat[k*2+2]); //最小値なので
    }
}

int query(int a,int b,int k,int l,int r){ //[a,b)の最小値を求める、外側からは query(a,b,0,0,n_edited) で呼ぶ
    // kは
    if(r<=a || b <= l){
        return INF; //最小値なので
    }
    if(a<=l && r<= b){
        return seg_dat[k];
    }
    else{
        int vl = query(a,b,k*2+1,l,(l+r)/2);
        int vr = query(a,b,k*2+2,(l+r)/2,r);
        return min(vl,vr); //最小値なので
    }
}

signed main(){
    int n,q;
    cin >> n >> q;
    init(n);
    REP(i,q){
        int c1,x1,y1;
        cin >> c1 >> x1 >> y1;
        if(c1==0){
            update(x1,y1);
        }
        else{
            cout << query(x1,y1+1,0,0,n_edited) << endl;
        }
    }





    return 0;
}

