int get_size(int n){
	int res=0;
	while(n) n=n>>1,res++;

	return (1<<res);
}

int unit(){
	return (1LL<<31)-1;
}

int func(int a,int b){
	return min(a,b);
}

int build(int n){
	sz=get_size(n);
	REP(i,0,sz+1) seg[i]=unit();
	return 0;
}

int update(int k,int x){
	k+=sz-1;
	seg[k]=x;
	while(k){
		k=(k-1)>>1;
		seg[k]=func(seg[k*2+1],seg[k*2+2]);
	}

	return 0;
}

int _get(int a,int b,int k,int l,int r){
	if(b<=l||r<=a) return unit();
	if(a<=l&&r<=b) return seg[k];

	return func(_get(a,b,2*k+1,l,(l+r)>>1), _get(a,b,2*k+2,(l+r)>>1,r));
}

int get(int a,int b){
	return _get(a,b,0,0,sz);
}

