template<typename T>
class SegmentTree {
private:
    int n;
    T dat[2*(1<<17)-1];
public:
    SegmentTree(int& n_) {
	n = 1;
	while (n < n_) n *= 2;
	n_ = n;
	for (int i = 0; i < 2*n-1; i++) dat[i] = (1LL<<31) - 1;
    }

    void update(int k, T a) {
	k += n - 1;
	dat[k] = a;
	while (k > 0) {
	    k = (k - 1) / 2;
	    dat[k] = min(dat[k*2+1], dat[k*2+2]);
	}
    }

    // call query(a, b, 0, 0, n)
    T query(int a, int b, int k, int l, int r) {
	if (r <= a || b <= l) return (1LL<<31)-1;

	if (a <= l && r <= b) return dat[k];
	else {
	    T vl = query(a, b, k*2+1, l, (l+r)/2);
	    T vr = query(a, b, k*2+2, (l+r)/2, r);
	    return min(vl, vr);
	}
    }
};

void solve(int n, int q) {
    SegmentTree<ll> st(n);
    for (int i = 0; i < q; i++) {
	int com;
