	if (com == 0) {
	    int x;
	    ll y;
	    scanf("%d%lld", &x, &y);
	    st.update(x, y);
	} else {
	    int x, y;
	    scanf("%d%d", &x, &y);
	    printf("%d\n", st.query(x, y+1, 0, 0, n));
	}
    }
}

