//kは接点の番号, l,rはその接点が持つ範囲[l,r)を表す
ll getmin(int a,int b,int k=0,int l=0,int r=-1){
    if(r<0)r=N;
    if(r<=a||b<=l)return INF;
    if(a<=l&&r<=b)return dat[k];
    else{
        ll chl=getmin(a,b,2*k+1,l,(l+r)/2);
        ll chr=getmin(a,b,2*k+2,(l+r)/2,r);
        return min(chl,chr);
    }
}

