template<class T>
class SqrtDecomposition {
    using Func = function<T(T, T)>;
    const Func f;
    const T def;
    const int cap = 512;
    int N, K;
    vector<T> data, bucket;
public:
    SqrtDecomposition(int n, T _def, const Func f);
    void update(int x, T y);
    T query(int x, int y);
};

template<class T>
inline SqrtDecomposition<T>::SqrtDecomposition(int n, T _def, const Func f) : N(n), def(_def), f(f) {
    K = (N + cap - 1) / cap;
    data.assign(K * cap, def);
    bucket.assign(K, def);
}

template<class T>
inline void SqrtDecomposition<T>::update(int x, T y) {
    int k = x / cap;
    T val = data[x] = y;
    for(int i = k * cap; i < (k + 1) * cap; ++i) {
        val = f(val, data[i]);
    }
    bucket[k] = val;
}

template<class T>
inline T SqrtDecomposition<T>::query(int x, int y) {
    T val = def;
    for(int k = 0; k < K; ++k) {
        int l = k * cap, r = (k + 1) * cap;
        if(r <= x || y <= l) continue;
        if(x <= l && r <= y) {
            val = f(val, bucket[k]);
        } else {
            for(int i = max(x, l); i < min(y, r); ++i) {
                val = f(val, data[i]);
            }
        }
    }
    return val;
}

int main() {
    int n, q;
    cin >> n >> q;
    SqrtDecomposition<int> sd(n, numeric_limits<int>::max(), [](int a, int b) { return min(a, b); });
    while(q--) {
        int c, x, y;
        cin >> c >> x >> y;
        if(c) cout << sd.query(x, y + 1) << '\n';
        else sd.update(x, y);
    }
    return 0;
}

