constexpr ll DEF_VAL = (1LL << 31) - 1;
constexpr ll SEG_LEN = (1LL << 17);

ll segTree[SEG_LEN * 2];

void initialize() {
	for (ll i = 0; i < SEG_LEN * 2; i++) {
		segTree[i] = DEF_VAL;
	}
}

void setVal(ll idx, ll val) {
	idx += SEG_LEN;
	segTree[idx] = val;
	while (true) {
		idx /= 2;
		if (idx <= 0) break;
		segTree[idx] = min(segTree[2 * idx], segTree[2 * idx + 1]);
	}
}

ll getMin(ll ql, ll qr, ll sl = 0, ll sr = SEG_LEN, ll idx = 1) {
	if (qr <= sl || sr <= ql) {
		return DEF_VAL;
	}
	if (ql <= sl && sr <= qr) {
		return segTree[idx];
	}
	ll sm = (sl + sr) / 2;
	ll m1 = getMin(ql, qr, sl, sm, 2 * idx);
	ll m2 = getMin(ql, qr, sm, sr, 2 * idx + 1);
	return min(m1, m2);

}

