class RMQ{
	private:
	vi rmq;
	bool two_judge(int x){
		if(x==1) return 0;
		if(x==0) return 1;
		return two_judge(x/2);
	}
	public:
	int N;
	RMQ(int x){
		N=1;
		while(N<x) N*=2;
		rmq=vi(2*N-1,inf);
	}
	void update(int x,int y){
		x+=N-1;
		rmq[x]=y;
		while(x>0){
			x=(x-1)/2;
			rmq[x]=min(rmq[x*2+1],rmq[x*2+2]);
		}
	}
	int find(int a,int b,int k,int l,int r){
		if(r<=a||b<=l) return inf;
		if(a<=l&&r<=b) return rmq[k];
		int vl=find(a,b,k*2+1,l,(l+r)/2);
		int vr=find(a,b,k*2+2,(l+r)/2,r);
		return min(vl,vr);
	}
	void open(){
		for(int i=0;i<N;i++){
			if(two_judge(i)) cout<<endl;
			cout<<rmq[i]<<' ';
		}
	}
};

