  int n, q;
  std::cin >> n >> q;
  SegmentTree<long long int> seg(
      n, (1LL << 31) - 1, [](long long int a, long long int b) -> long long int { return std::min(a, b); },
      [](long long int _, long long int b) -> long long int { return b; });
  for (int i = 0; i < q; i++) {
