int find(int N) {
  int x = 1;
  while (x < N) x <<= 1;
  return x;
}

void update(int x, int y) {
  int p = find(N) + x;
  tree[p] = y;
  while (p > 0) {
    p = p / 2;
    tree[p] = min(tree[p * 2], tree[p * 2 + 1]);
  }
}

int query(int a, int b, int k, int l, int r) {
  if (r <= a || b <= l) {
    return INT_MAX;
  } else if (a <= l && r <= b) {
    return tree[k];
  } else {
    int m = (l + r) / 2;
    int lv = query(a, b, k * 2,     l, m);
    int rv = query(a, b, k * 2 + 1, m, r);
    return min(lv, rv);
  }
}

