        size=a.size();
        initialize(a,0,0,size-1);
        return ;
    }
    void set(T n,int SIZE){
        arr.resize(2*SIZE-1);
        size=SIZE;
        arr[0].val=n;
        arr[0].lazytag=n;
        for(int i=1;i<arr.size();i++)arr[i].lazytag=0;
