struct RMQ {
    ll N;
    const ll MAX = (1ll << 31) - 1ll;
    vector<ll> dat;
    void init(ll n){
        ll tmp = 1;
        while(tmp < n){
            tmp *= 2;
        }
        N = tmp;
        dat = vector<ll>(4 * n);
        for (int i = 0; i < dat.size(); ++i) {
            dat[i] = MAX;
        }
    }
    void update(int i,ll x){
        i += N - 1;
        dat[i] = x;
        while(i > 0){
            i = (i-1)/2;
            dat[i] = min(dat[i * 2 + 1], dat[i * 2 + 2]);
        }
        //OutputVec(dat);
    }
    ll query(ll a, ll b){
        return sub_query(a,b,0,0,N);
    }
    ll sub_query(ll a,ll b,ll k,ll l,ll r){
            if (r <= a || b <= l) { // 範囲外なら考えない
                return MAX;
            } else if (a <= l && r <= b) { // 範囲内なので自身の値を返す
                return dat[k];
            } else {
                ll vl = sub_query(a, b, k * 2 + 1, l, (l + r) / 2);
                ll vr = sub_query(a, b, k * 2 + 2, (l + r) / 2, r);
                return min(vr,vl);
            }
    }
};

int main() {
    ll n,q;
    cin >> n >> q;
    RMQ rmq;
    rmq.init(n);
    for (int i = 0; i < q; ++i) {
        ll com,x,y;
        cin >> com >> x >> y;
        if(com == 0){
            rmq.update(x,y);
        }else{
            cout << rmq.query(x,y+1) << endl;
        }
        //OutputVec(rmq.dat);
    }
}

