const int depth = 17;
class Segtree {
public:
	unsigned int data[1<<(depth+1)];
	void ini() {
		for(int i= 0; i < (1<<(depth+1)); i++)
			data[i] = ((unsigned int)1<<31)-1;
	}

	void update(int x, int v) {
		x = (1<<depth)-1 + x;
		data[x] = v;
		while( x > 0 ) {
			x = (x-1)/2;
			data[x] = min(data[x*2 + 1], data[x*2 + 2]);
		}
	}

	unsigned int find(int l, int r, int a=0, int b=(1<<depth)-1, int index=0) {
		if ( a > r || b < l ) return ((unsigned int)1<<31)-1;
		if ( l <= a && b <= r ) return data[index];
		unsigned int u = find(l, r, a, a+(b-a-1)/2, index*2+1);
		unsigned int v = find(l, r, a+(b-a+1)/2, b, index*2+2);
		return min(u, v);
	}
}seg;

int main() {
	seg.ini();
	int n, q;
	int com, x, y;

	cin >> n >> q;
	for(int i = 0; i < q; i++ ) {
		cin >> com >> x >> y;
		if ( com == 0 )
			seg.update(x, y);
		else
			cout << seg.find(x, y) << endl;
	}
	return 0;
}

