//Segment Tree for Range Maximum Query
class SegmentTree{
public:
  int n;
  vector<int> node;
  SegmentTree(vector<int> a){
    int n_ = a.size();
    n=1;
    while(n<n_)n*=2;  // rounding to power of 2
    node.resize(2*n-1, (1<<31)-1);
    for(int i=0;i<n_;i++)node[n-1+i] = a[i];
    for(int i=n-2;i>=0;i--)node[i] = min(node[2*i+1], node[2*i+2]);
  }

  //return maximum value in [a,b). ( [l,r) is interval in which k is.)
  int RMQ(int a,int b,int k=0,int l=0,int r=0){
    if(l>=r)r = n;
    if(r<=a || b<=l)return (1<<31)-1;
    if(a<=l && r<=b)return node[k];
    int vl = RMQ(a,b,2*k+1,l,(l+r)/2);
    int vr = RMQ(a,b,2*k+2,(l+r)/2,r);
    return min(vl,vr);
  }

  void update(int k, int v){
    k += n-1;
    node[k] = v;
    while(k>0){
      k = (k-1)/2;
      node[k] = min(node[k*2+1],node[k*2+2]);
    }
  }
};

int main(){
  int n,q;
  cin >> n >> q;
  vector<int> a(n,(1<<31)-1);
  SegmentTree st(a);

  for(int i=0;i<q;i++){
    int c,x,y;
    cin >> c >> x >> y;
    if(c==0)st.update(x,y);
    else cout << st.RMQ(x,y+1) << endl;
  }
}

