template<typename T>
struct RangeMinimumQuery {
	int n;
	vector<T>d;
	RangeMinimumQuery(int m) {
		for (n = 1; n < m; n <<= 1);
		d.assign(2 * n, INF);
	}
	void update(int i, T x) {
		d[n + i] = x;
		for (int j = (n + i) / 2; j > 0; j >>= 1)d[j] = min(d[2 * j], d[2 * j + 1]);
	}
	T find(int a, int b, int k = 1, int l = 0, int r = -1) {
		if (r < 0)r = n;

		if (r <= a || b <= l)return INF;
		else if (a <= l&&r <= b)return d[k];
		else {
			T vl, vr;
			vl = find(a, b, 2 * k, l, (l + r) / 2);
			vr = find(a, b, 2 * k + 1, (l + r) / 2, r);
			return min(vl, vr);
		}
	}

};
