using namespace std;

template<typename T>
class SegTree
{
public:
  SegTree(const int size);
  void set(const int index, const T value);
  T query(const int a, const int b, const int l, const int r, const int k) const;
  T query(const int a, const int b) const;
  void print() const;
private:
  int left(const int parent) const;
  int right(const int parent) const;
  int parent(const int child) const;

  std::vector<T> array;
  int size_2;
};

template<typename T>
SegTree<T>::SegTree(const int size)
{
  size_2 = 1;
  while(size_2 < size) size_2 *= 2;

  array.resize(size_2 * 2 - 1);
  std::fill(array.begin(), array.end(), std::numeric_limits<T>::max());
}

template<typename T>
int SegTree<T>::left(const int parent) const
{
  return parent * 2 + 1;
}

template<typename T>
int SegTree<T>::right(const int parent) const
{
  return parent * 2 + 2;
}

template<typename T>
int SegTree<T>::parent(const int child) const
{
  return (child - 1) / 2;
}   

template<typename T>
void SegTree<T>::set(int index, const T value)
{
  index += size_2 - 1;
  array[index] = value;
  while(index > 0)
  {
	index = parent(index);
	array[index] = min(array[left(index)], array[right(index)]);
  }
}

template<typename T>
void SegTree<T>::print() const
{
  for(auto v : array)
  {
	cerr << v << ", ";
  }
  cerr << endl;
}

template<typename T>
T SegTree<T>::query(const int a, const int b) const
{
  return query(a, b, 0, size_2, 0);
}

