template<typename T>
T SegTree<T>::query(const int a, const int b, const int l, const int r, const int k) const
{
  if(r <= a || b <= l)
  {
	return std::numeric_limits<T>::max();
  }
  else if(a <= l && r <= b)
  {
	return array[k];
  }
  else
  {
	int l_val = query(a, b, l, (l + r) / 2, left(k));
	int r_val = query(a, b, (l + r) / 2, r, right(k));
	return std::min(l_val, r_val);
  }
}

