    int n;

    int query(int l, int r){
        // get merge(a[l..r]);
        return query(1, 0, n-1,l ,r);
    }

    void update(int idx, int value){
        // set a[idx]=value
        update(1, 0, n-1, idx, value);
    }

    int merge(int l, int r){
        return min(l, r);
    }

    SegmentTree(vi &b){
        a = b;
        n = a.size();
        t = vi(4*n);
        build(1, 0, n-1);
    }

private:
    void build(int id, int l, int r){
        // build t[l,r] using a
        if(l==r) {
            t[id]=a[l];
        } else {
            int mid=(l+r)/2;
            build(2*id, l, mid);
            build(2*id+1, mid+1, r);
            t[id] = merge(t[2*id], t[2*id+1]);
        }
    }

    int query(int id, int l, int r, int lr, int rr){
        //printf("querying [%d,%d] in [%d,%d]\n",lr,rr,l,r);
        // get query for [lr,rr] in subarray [l,r]
        if(l==lr && r==rr)
            return t[id];
        int mid = (l+r)/2;
        if(lr>mid){
            // fully in r
            return query(2*id+1,mid+1,r,lr,rr);
        }
        if(rr <= mid){
            // fully in l
            return query(2*id, l, mid, lr, rr);
        }
        // in l and r
        int left = query(2*id, l, mid, lr, mid);
        int right = query(2*id+1, mid+1, r, mid+1, rr);
        return merge(left, right);
    }

    void update(int id, int l, int r, int idx, int value){
        if(l==r){
            t[id] = value;
            a[l] = value;
        } else {
            int mid = (l+r)/2;
            if(idx <= mid)
                update(2*id, l, mid, idx, value);
            else
                update(2*id+1, mid+1, r, idx, value);
            t[id] = merge(t[2*id], t[2*id+1]);
        }
    }

};

int main(int argc, const char * argv[]) {
    #ifdef LOCAL_TEST
    freopen("input", "r", stdin);
    freopen("output", "w", stdout);
    #endif
    //http://judge.u-aizu.ac.jp/onlinejudge/description.jsp?id=DSL_2_A

    int n,q;
    cin>>n>>q;
    vi a(n, (1<<31)-1);
    SegmentTree st(a);

    F(i,0,q){
        int t,x,y;
        cin>>t>>x>>y;
        if(t==0){
            //update
            st.update(x,y);
        } else {
            // print min
            cout<<st.query(x,y)<<"\n";
        }
    }
}

