template<class T>
class SegmentTree{
	vector<T> tree;
	size_t n;
	function<T(T,T)> merge;

	public:
	SegmentTree(size_t n_, T init,function<T(T,T)> fn){
		if(n_ == 0)throw std::invalid_argument("n > 0");
		n = 1 << (32 - __builtin_clz(n_));
		merge = fn;
		size_t treesize = 2*n;
		tree = vector<T>(treesize,init);
	}
	~SegmentTree(){}

	void update(size_t idx, T x){
		idx += n;
		tree[idx] = x;
		while(idx >>= 1){
			tree[idx] = merge(tree[idx*2 +0], tree[idx*2 +1]);
		}
	}

	T query(size_t a, size_t b){
		T ret = tree[0];
		a += n; b += n;
		for(; a < b; a >>= 1, b >>= 1){
			if(a&1)ret = merge(ret, tree[a++]);
			if(b&1)ret = merge(ret, tree[--b]);
		}
		return ret;
	}
};

