vector<int> dat;
int leaves;

void init(int n){
    int t = 1;
    while(t<n)t*=2;
    leaves = t;
    dat.resize(leaves*2,INF);
    for(int i=leaves;i<2*leaves;i++)dat[i] = (1LL<<31)-1;
    for(int i=leaves-1;i>=1;i--){
        dat[i] = min(dat[2*i],dat[2*i+1]);
    }
}

void update(int ind,int x){
    int m = ind+leaves;
    dat[m] = x;
    int p = m/2;
    while(p>0){
        dat[p] = min(dat[p],x);
        p/=2;
    }
}

int find(int s,int t,int num=1,int l=0,int r=-1){
    if(r==-1)r = leaves;

    if(s<=l && r<=t)return dat[num];
    else if(r<=s || t<=l)return (1LL<<31)-1;
    else{
        return min(find(s,t,num*2,l,(l+r)/2),
                   find(s,t,num*2+1,(l+r)/2,r));
    }
}


