        SqrtDecomp<int32_t> rmq(n, (1LL<<31)-1);
        for(int i = 0; i < q; i++){
            int a,b,c;
            cin >> a >> b >> c;
            if(a == 0){
                rmq.setVal(b,c);
            } else {
