        n *= n;
    }
    return res;
}
template<class T>
struct segtree{
    using FX = function<T(T,T)>;
    ll n;
    FX fx;
    const T ex;
    vector<T> dat;
    segtree(ll _n,FX _fx,T _ex):n(),fx(_fx),ex(_ex),dat(_n * 4,_ex){
        ll x = 1;
        while(x < _n){
            x *= 2;
        }
        n = x;
    }
    void update(ll a,T m){
        a += n - 1;
        dat[a] = m;
        while(a > 0){
            a = (a - 1) / 2;
            dat[a] = fx(dat[a * 2 + 1],dat[a * 2 + 2]);
        }
    }
    T query_sub(ll a,ll b,ll k,ll l,ll r){
        if(a >= r || b <= l){
            return ex;
        }
        else if(a <= l && r <= b){
            return dat[k];
        }
        else{
            T le = query_sub(a,b,k * 2 + 1,l,(l + r) / 2);
            T ri = query_sub(a,b,k * 2 + 2,(l + r) / 2,r);
            return fx(le,ri);
        }
    }
    T query(ll a,ll b){
        return query_sub(a,b,0,0,n);
    }
};
