struct Rmin {
private:
	int N;
	vector<ll> node;

public:
	Rmin(vector<ll> v) {
		int size = v.size();
		N = 1;
		while (N < size) N <<= 1;
		node.resize(2*N-1, INF);

		for (int i=0; i < size; i++) node[i+N-1] = v[i];
		for (int i=N-2; i>=0; i--) node[i] = min(node[(i<<1)+1], node[(i<<1)+2]);
	}

	Rmin(int size) {
		N = 1;
		while (N < size) N <<= 1;
		node.resize(2*N-1, INF);		
	}

	ll Access(int x) {
		return node[x+N-1];
	}

	void Update(int x, ll val) {
		x += N-1;
		node[x] = val;
		while (x > 0) {
			x = (x-1)>>1;
			node[x] = min(node[(x<<1)+1], node[(x<<1)+2]);
		}
		return;
	}

	//[a, b)
	ll GetValue(int a, int b, int k=0, int l=0, int r=-1) {
		if (r < 0) r = N;
		if (a >= r || b <= l) return INF;
		if (a <= l && r <= b) return node[k];
		ll vl = GetValue(a, b, (k<<1)+1, l, (l+r)>>1);
		ll vr = GetValue(a, b, (k<<1)+2, (l+r)>>1, r);
		return min(vl, vr);
	}
};

