class RMQ{
public:
  int n,dat[2*MAX_N-1];

  void init(int n_){
    n = 1;
    while(n < n_){ n *= 2; }
    for(int i = 0 ; i < 2*n-1 ; i++){
      dat[i] = INT_MAX;
    }
  }

  void update(int k,int a){
    k += n - 1;
    dat[k] = a;
    while(k > 0){
      k = (k - 1) / 2;
      dat[k] = min(dat[k*2+1],dat[k*2+2]);
    }
