bool cmp(ppi a,ppi b){return a.F.F/SQRTN==b.F.F/SQRTN?a.F.S==b.F.S?a.F.F<b.F.F:a.F.S<b.F.S:a.F.F<b.F.F;}
int main(){
    int n,q,a[N],now=-1,nowl=0,nowr=-1,k,l,r,ans[Q];
