                    if(m.find(upd[now].S.S)==m.end())m.insert(MP(upd[now].S.S,1));
                    else m[upd[now].S.S]++;
                }
                now--;
            }
            while(nowl>v[i][j].S.F){
                nowl--;
                if(m.find(a[nowl])==m.end())m.insert(MP(a[nowl],1));
                else m[a[nowl]]++;
            }
            while(nowr<v[i][j].F.F){
