}

#include<bits/stdc++.h>
using namespace std;
const int maxn=4e5+7;
int minv[maxn];
void build(int k,int l,int r){
    minv[k]=2147483647;
    if(l==r) return;
    int m=(l+r)>>1;
    build(k<<1,l,m);
    build(k<<1|1,m+1,r);
    minv[k]=min(minv[k<<1],minv[k<<1|1]);
}
void update(int k,int l,int r,int p,int v){
    if(l==r){
        minv[k]=v;
        return;
    }
    int m=(l+r)>>1;
    if(p<=m) update(k<<1,l,m,p,v);
    else update(k<<1|1,m+1,r,p,v);
    minv[k]=min(minv[k<<1],minv[k<<1|1]);
}
int query(int k,int l,int r,int pl,int pr){
    if(pl<=l&&r<=pr) return minv[k];
    int m=(l+r)>>1;
    int res=2147483647;
    if(pl<=m) res=min(res,query(k<<1,l,m,pl,pr));
    if(pr>m) res=min(res,query(k<<1|1,m+1,r,pl,pr));
    return res;
}
int main(){
    int n,q;
    cin>>n>>q;
    build(1,1,n);
    while(q--){
        int op,x,y;
        cin>>op>>x>>y;
        if(!op){
            update(1,1,n,++x,y);
        }
        else{
            if(x>y) swap(x,y);
            printf("%d\n",query(1,1,n,++x,++y));
        }
    }
    return 0;
