struct seg_t {
	int size;
	vector<int> data;
	int pool_size;
	vector<int> pool;
	seg_t(int n) {
		int i = 1;
		while(i * i < n) i++;
		size = i * i;
		pool_size = i;
		data.assign(size, INF);
		pool.assign(pool_size, INF);
	}
	void update(int k, int x) {
		data[k] = x;
		int pool_k = k / pool_size;
		pool[pool_k] = INF;
		for(int i = pool_k * pool_size; i < (pool_k + 1) * pool_size; i++) {
			pool[pool_k] = min(pool[pool_k], data[i]);
		}
	}
	int minimum(int a, int b) {
		int pool_a = a / pool_size;
		int pool_b = b / pool_size;
		if(pool_a == pool_b) {
			int minvalue = INF;
			for(int i = a; i < b; i++) {
				minvalue = min(minvalue, data[i]);
			}
			return minvalue;
		}
		else {
			int minvalue = INF;
			for(int i = a; i < (pool_a + 1)*pool_size; i++) {
				minvalue = min(minvalue, data[i]);
			}
			for(int i = pool_a + 1; i < pool_b; i++) {
				minvalue = min(minvalue, pool[i]);
			}
			for(int i = pool_b*pool_size; i < b; i++) {
				minvalue = min(minvalue, data[i]);
			}
			return minvalue;
		}
	}
};
