struct SegmentTree {
	int N;
	std::vector<int> seg;
	SegmentTree(int n) : N(1) {
		while (N < n) N <<= 1;
		seg.resize(N * 2 - 1, INFINT_LIM);
	}
	void update(int i, int x) {
		int p = i + N - 1;
		seg[p] = x;
		while (true) {
			seg[p] = std::min(seg[p], x);
			if (p == 0) break;
			p = (p - 1) / 2;
		}
	}
	int query_(int s, int t, int k, int l, int r) {
		if (r <= s || t <= l) return INFINT_LIM;
		if (s <= l && r <= t) return seg[k];
		int m = (l + r) / 2;
		int vl = query_(s, t, k * 2 + 1, l, m);
		int vr = query_(s, t, k * 2 + 2, m, r);
		return std::min(vl, vr);
	}
	int query(int s, int t) {
		return query_(s, t, 0, 0, N);
	}
};

signed main() {
	INIT;
	VAR(int, n, q);
	SegmentTree st(n);
	REP(_, q) {
		VAR(int, c, x, y);
		if (c == 0) {
			st.update(x, y);
		}
		else {
			OUT(st.query(x, y + 1))BR;;
		}
	}
	return 0;
}

