void build(int start, int end, int index = 1) {
    if (start == end) {
        t[index] = 2147483647;
        return;
    }

    int mid = start + end >> 1;
    build(start, mid, index << 1);
    build(mid + 1, end, index << 1 | 1);

    t[index] = doit(t[index << 1], t[index << 1 | 1]);
}

int query(int start, int end, int l, int r, int index = 1) {
    //Invalid range
    if (r < start or l > end)
        return 2147483647;

    //In range
    if (l <= start and end <= r) {
        return t[index];
    }

    int mid = start + end >> 1;
    return doit(query(start, mid, l, r, index << 1), query(mid + 1, end, l, r, index << 1 | 1));
}

