template<typename T>
class RmqSparseTable{

public:
  RmqSparseTable(vector<T> a){
    this-> a = a;
    int n = a.size();
    logTable.resize(n + 1);
    for (int i = 2; i <= n; i++){
      logTable[i] = logTable[i >> 1] + 1;
    }
    rmq.resize(logTable[n] + 1);
    for (int i = 0; i < rmq.size(); i++){
      rmq[i].resize(n);
    }
    for (int i = 0; i < n; i++){
      rmq[0][i] = i;
    }
    for (int k = 1; (1 << k) < n; k++){
      for (int i = 0; i + (1 << k) <= n; i++){
	int x = rmq[k - 1][i];
	int y = rmq[k - 1][i + (1 << k - 1)];
	rmq[k][i] = a[x]  <= a[y] ? x : y;
      }
    }
  }
    int minPos(int i, int j){
      int k = logTable[j - 1];
      int x = rmq[k][i];
      int y = rmq[k][j - (1 << k) + 1];
      return a[x] <= a[y] ? x : y;
    }

private:
  vector<T> logTable;
  vector<vector<T>> rmq;
  vector<T> a;
};



