int stepen2(int x)
{
    if(x%2==1)
    {
        x++;
        return stepen2(x);
    }
    return x;
}

int query (int idx, int left, int right, int l, int r)
{
    if(l<=left && r >= right)
    {
        return seg[idx];


    }
    if(r < left || l > right)
        return 2147483647;

    int mid = (left+right)/2;
    int k = query(2*idx,left,mid, l, r);
    int nj = query(2*idx+1,mid+1,right, l, r);
    //if(idx == 7)
       // cout << k << " " << nj << endl;
    return min(k,nj);

}

void nmp (int idx,int left,int right)
{
    if(left == right)
    {
        seg[idx] = a[left];
        return;
    }
    int mid = (left + right)/2;
    nmp(2*idx, left, mid);
    nmp(2*idx+1, mid+1, right);
    seg[idx] = min(seg[2*idx], seg[2*idx+1]);
    cout <<"idx " <<  idx << endl;
}

int update (int idx, int left, int right, int pos, int val)
{
    if (left == right)
    {
        seg[idx] = val;
        return 1;
    }
    int mid = (left+right)/2;
    if(pos > mid)
        update(2*idx+1, mid+1, right, pos, val);
    else
        update(2*idx, left, mid, pos, val);
    seg[idx] = min(seg[2*idx], seg[2*idx+1]);
}


