struct RMQ {
	int n;
	vector<int> t;
	RMQ (int l) :
		n(1 << (32 - __builtin_clz(l - 1))),
		t(n * 2, INT_MAX) {}
	void update(int i, int v) {
		i += n, t[i] = v;
		while (i > 1) {
			i >>= 1;
			t[i] = min(t[i << 1], t[i << 1 | 1]);
		}
	}
	int find(int a, int b) {
		int x = INT_MAX;
		for (a += n, b += n; a < b; a >>= 1, b >>= 1) {
			if (a & 1) x = min(x, t[a++]);
			if (b & 1) x = min(x, t[--b]);
		}
		return x;
	}
};

int main() {
	RMQ r(in());
	for (int q = in(); q; q--) {
		int o = in(), x = in(), y = in();
		if (o)
			outl(r.find(x, y + 1));
		else
			r.update(x, y);
	}
}

