Node *change(Node *node, int k, long long int v){
  if(node == NULL){ return NULL; }

  Node *result;
  if(cnt(node->left) == k){
    node->value = v;
    result = node;
  }
  if(k < cnt(node->left)){ result = change(node->left, k, v); }
  else{ result = change(node->right, k - cnt(node->left) - 1, v); }

  update(node);
  return result;  
}


// l????????¨????????¨?????¨????????´???r????????¨????????¨?????¨????????????
// ?????????: root = (root, s);
Node* merge(Node *l, Node *r){
  if(!l){ return r; }
  if(!r){ return l; }

  if(l->priority > r->priority){
    l->right = merge(l->right, r);
    update(l);
    return l;
  }
  else{
    r->left = merge(l, r->left);
    update(r);
    return r;
  }
}


// node????????¨????????¨?????¨???k?????????????´???§??????
// ?????????: pair<Node*, Node*> s = split(root, k);
pair<Node*, Node*> split(Node* node, int k){
  if(!node){ return pair<Node*, Node*>(NULL, NULL); }
  if(k <= cnt(node->left)){
    pair<Node*, Node*> s = split(node->left, k);
    node->left = s.second;
    update(node);
    return make_pair(s.first, node);
  }
  else{
    pair<Node*, Node*> s = split(node->right, k - cnt(node->left) - 1);
    node->right = s.first;
    update(node);
    return make_pair(node, s.second);
  }
}


// root????????¨????????¨???k????????????v????????\??????
