Node* insert(Node* root, int k, int v){
  Node* newNode = (Node *)malloc(sizeof(Node));
  newNode->init(v);
  if(root == NULL){ return newNode; }
  pair<Node*, Node*> s = split(root, k);
  return merge(merge(s.first, newNode), s.second);
}


// root????????¨????????¨?????????k?????????????´????????????????
// ?????????: root = erase_position(root, k);
Node* erase(Node* root, int k){
  pair<Node*, Node*> s2 = split(root, k);
  pair<Node*, Node*> s1 = split(s2.first, k - 1);
  free(s1.second);
  return merge(s1.first, s2.second);
}


