template <typename T> struct AbstractMonoid {
  T d;
  static const T e;
  AbstractMonoid(T d = e) : d(d) {}
  void operator=(const T& x) { d = x; }
  void operator=(const AbstractMonoid& x) { d = x.d; }
  bool operator==(const AbstractMonoid& x) { return d == x.d; }
};

struct AddMonoid : public AbstractMonoid<ll> {
  static const ll e = 0LL;
  AddMonoid(ll d = e) : AbstractMonoid<ll>(d) {}
  void operator-=(const AddMonoid& x) { d = operator-(x).d; }
  AddMonoid operator-(const AddMonoid& x) { return AddMonoid(x.d - d); }
  void operator+=(const AddMonoid& x) { d = operator+(x).d; }
  AddMonoid operator+(const AddMonoid& x) { return AddMonoid(x.d + d); }
};

struct MinMonoid : public AbstractMonoid<ll> {
  static const ll e = INF;
  MinMonoid(ll d = e) : AbstractMonoid<ll>(d) {}
  void operator+=(const MinMonoid& x) { d = operator+(x).d; }
  MinMonoid operator+(const MinMonoid& x) { return MinMonoid(min(x.d, d)); }
};

struct MaxMonoid : public AbstractMonoid<ll> {
  static const ll e = -INF;
  MaxMonoid(ll d = e) : AbstractMonoid<ll>(d) {}
  void operator+=(const MaxMonoid& x) { d = operator+(x).d; }
  MaxMonoid operator+(const MaxMonoid& x) { return MaxMonoid(max(x.d, d)); }
};

struct SubstituteMonoid : public AbstractMonoid<ll> {
  static const ll e = INF - 1;
  SubstituteMonoid(ll d = e) : AbstractMonoid<ll>(d) {}
  void operator+=(const SubstituteMonoid& x) { d = operator+(x).d; }
  SubstituteMonoid operator+(const SubstituteMonoid& x) { return SubstituteMonoid(x.d); }
};

struct VectorMonoid {
  vector<P> d;
  static const vector<P> e;
  VectorMonoid() {}
  VectorMonoid(vector<P>& _d) { copy(_d.begin(), _d.end(), back_inserter(d)); }
  void operator=(const vector<P>& x) { copy(x.begin(), x.end(), back_inserter(d)); }
  void operator=(const VectorMonoid& x) { copy(x.d.begin(), x.d.end(), back_inserter(d)); }
  bool operator==(const VectorMonoid& x) { return d == x.d; }
  VectorMonoid operator+(const VectorMonoid& x) {
    vector<P> temp;
    merge(d.begin(), d.end(), x.d.begin(), x.d.end(), back_inserter(temp));
    return VectorMonoid(temp);
  }
};

