template <typename T> function<T(T)> identity = [](T t) { return t; };

template <typename T> function<T(T, ll)> _segmentTreeIdentity = [](T t, ll num) { return t; };

template <typename T1, typename T2> function<T1(T1, T2)> _segmentTreeSubstitute = [](T1 y, T2 x) {
