// SegmentTree
// T1 -> M1 -> f -> M2 -> T2
template <typename T1, typename Monoid1, typename T2, typename Monoid2>
class AbstractSegmentTree {
  using F = function<Monoid2(Monoid1)>;
  ll n;
  vector<Monoid1> data;
  F f;
public:
  AbstractSegmentTree(const vector<T1>& _data, F f) : f(f) {
    n = 1;
    while ((ll)_data.size() > n) n *= 2;
    data.resize(2*n);
    for (ll i = 0; i < (ll)_data.size(); i++) data[n+i] = _data[i];
    for (ll i = n-1; i > 0; i--) data[i] = data[2*i] + data[2*i+1];
  }
  T2 at(ll num) { return data[n+num].d; }
  void add(ll num, T1 x) {
    num += n;
    data[num].d += x;
    num /= 2;
    while (num > 0) data[num] = data[2*num] + data[2*num+1], num /= 2;
  }
  void update(ll num, T1 x) {
    num += n;
    data[num] = x;
    num /= 2;
    while (num > 0) data[num] = data[2*num] + data[2*num+1], num /= 2;
  }
  // [a, b)
  T2 query(ll a, ll b) {
    return subquery(a, b, 1, 0, n).d;
  }
  Monoid2 subquery(ll a, ll b, ll num, ll s, ll t) {
    if (b <= s || t <= a) return Monoid2::e;
    if (a <= s && t <= b) return f(data[num], num);
    ll mid = (s + t) / 2;
    return subquery(a, b, 2*num, s, mid) + subquery(a, b, 2*num+1, mid, t);
  }
};

