// T2 -> A ( -> p ) -> f -> M -> T1
template <typename T1, typename Monoid, typename T2, typename Action>
class AbstractLazySegmentTree {
  using F = function<Monoid(Monoid, Action)>;
  using P = function<Action(Action, ll)>;
  ll n;
  F f;
  P p;
  vector<Monoid> data;
  vector<Action> lazy;
public:
  AbstractLazySegmentTree(const vector<T2>& _data, F f, P p = _segmentTreeIdentity<Action>) : f(f), p(p) {
    n = 1;
    while ((ll)_data.size() > n) n *= 2;
    data.resize(2*n);
    lazy.resize(2*n);
    for (ll i = 0; i < (ll)_data.size(); i++) data[n+i] = _data[i];
    for (ll i = n-1; i > 0; i--) data[i] = data[2*i] + data[2*i+1];
  }
  inline void eval(ll k, ll len) {
    if (lazy[k] == Action::e) return;
    if (2*k + 1 < 2*n) {
      lazy[2*k] += lazy[k];
      lazy[2*k + 1] += lazy[k];
    }
    data[k] = f(data[k], p(lazy[k], len));
    lazy[k] = Action::e;
  }
  Monoid update(ll a, ll b, T2 x, ll k = 1, ll l = 0, ll r = -1) {
    if (r == -1) r = n;
    eval(k, r-l);
    if (r <= a || b <= l) return data[k];
    if (a <= l && r <= b) {
      lazy[k] += x;
      return f(data[k], p(lazy[k], r-l));
    }
    ll mid = (l + r) / 2;
    return data[k] = update(a, b, x, 2*k, l, mid) + update(a, b, x, 2*k+1, mid, r);
  }
  T1 query(ll a, ll b) {
    return query(a, b, 1, 0, n).d;
  }
  Monoid subquery(ll a, ll b, ll k, ll l, ll r) {
    eval(k, r-l);
    if (r <= a || b <= l) return Monoid::e;
    if (a <= l && r <= b) return data[k];
    ll mid = (l + r) / 2;
    return subquery(a, b, 2*k, l, mid) + subquery(a, b, 2*k+1, mid, r);
  }
};

template <typename T, typename Monoid>
class DynamicSegmentTree {
  struct edge {
    Monoid data;
    ll l, r; // [l, r)
    edge *par, *left, *right;
    edge(Monoid data, ll l, ll r, edge *par, edge *left, edge *right) :
      data(data), l(l), r(r), par(par), left(left), right(right) {}
  };
  edge *root;
public:
  DynamicSegmentTree(ll l, ll r) { // [l, r)
    root = new edge(Monoid::e, l, r, NULL, NULL, NULL);
  }
  edge* getPointer(ll num, edge *e = NULL) {
    if (e == NULL) e = root;
    if (e->l + 1 == e->r) return e;
    ll mid = (e->l + e->r) / 2;
    edge *next;
    ll l = e->l, r = e->r;
    if (num < mid) next = e->left, r = mid;
    else next = e->right, l = mid;
    if (next == NULL) next = new edge(Monoid::e, l, r, e, NULL, NULL);
    if (num < mid) e->left = next;
    else e->right = next;
    return getPointer(num, next);
  }
  T at(ll num) { return getPointer(num)->data.d; }
  void eval(edge *e) {
    e->data = Monoid::e;
    if (e->left != NULL) e->data = e->data + e->left->data;
    if (e->right != NULL) e->data = e->data + e->right->data;
  }
  void add(ll num, T x) {
    edge *e = getPointer(num);
    e->data += x;
    while (e->par != NULL) e = e->par, eval(e);
  }
  void update(ll num, T x) {
    edge *e = getPointer(num);
    e->data = x;
    while (e->par != NULL) e = e->par, eval(e);
  }
  // [a, b)
  T query(ll a, ll b) {
    return subquery(a, b, root).d;
  }
  Monoid subquery(ll a, ll b, edge *e) {
    if (e == NULL) return Monoid::e;
    if (b <= e->l || e->r <= a) return Monoid::e;
    if (a <= e->l && e->r <= b) return e->data;
    ll mid = (e->l + e->r) / 2;
    return subquery(a, b, e->left) + subquery(a, b, e->right);
  }
};

