	segtree(int n) {
		while (N < n) N *= 2;
		val = vi(2*N);
		for (int i = 0; i < 2 * N;i++) {
			val[i] = INF;
		}
	}
	void replace(int k, int a) {
		k += N;
		val[k] = a;
		while (k > 0) {
			k =  k / 2;
			val[k] = min(val[k * 2],val[k * 2 + 1]);
		}
	}
