	{
		if (r <= a || b <= l) { return make_pair(INF, -INF); }
		if (a <= l && r <= b) { return make_pair(minvalue[k], maxvalue[k]); }

		pair<long long, long long> vl = _query(a, b, 2 * k + 1, l, (l + r) / 2);
		pair<long long, long long> vr = _query(a, b, 2 * k + 2, (l + r / 2), r);

		return make_pair(min(vl.first, vr.first), max(vl.second, vr.second));
	}

public:

	RMQ(int size_)
	{
		for (size = 1; size < size_;) { size <<= 1; }

		minvalue = vector<long long>(size * 2 - 1, INF);
		maxvalue = vector<long long>(size * 2 - 1, -INF);
	}

