	{
		i += size - 1;

		minvalue[i] = x;
		maxvalue[i] = x;

		while (i > 0)
		{
			i = (i - 1) / 2;

			minvalue[i] = min(minvalue[2 * i + 1], x);
			maxvalue[i] = max(maxvalue[2 * i + 2], x);
		}
	}

	pair<long long, long long> query(int s, int t)
	{
		return _query(s, t, 0, 0, size);
	}
};

