template<class T>
class Treap {
public:
	template<class T>
	struct node_treap {
		T value;				// ???
		node_treap<T> *ch[2];	// ??????{???, ???}???
		double priority;			// ?????????
		int count;				// ??¨?????¨????????????
		T range_value;				// ??¨?????¨?????????sum???min

									// ?????????????????????
		node_treap(int v, double p) :value(v), priority(p), count(1), range_value(v) {
			ch[0] = ch[1] = NULL;
		}
	};

	node_treap<T> *root = NULL;

	// ???????????¨?????¨?????????????????????
	T def() {
		if (is_same<T, int>::value) {
			// int?????´???
			return (int)((1LL << 31) - 1);		// min?????´???
		}
		else if (is_same<T, ll>::value) {
			// ll?????´???
			return INFL;	// min?????´???
		}
	}
	// ???????????¨?????¨????????????sum??¨???min??¨??????
	T operation(T a, T b) {
		return min<T>(a, b);
	}

	int count(node_treap<T> *t) { return !t ? 0 : t->count; }
	int range_value(node_treap<T> *t) { return !t ? def() : t->range_value; }

	node_treap<T> *update(node_treap<T> *t) {
		t->count = count(t->ch[0]) + count(t->ch[1]) + 1;
		t->range_value = operation(operation(range_value(t->ch[0]), range_value(t->ch[1])), t->range_value);
		return t;
	}

	// ?????????????????¨???????????????
	node_treap<T> *Merge(node_treap<T> *l, node_treap<T> *r) {
		if (!l || !r)return !l ? r : l;

		if (l->priority > r->priority) {
			l->ch[1] = Merge(l->ch[1], r);
			return update(l);
		}
		else {
			r->ch[0] = Merge(l, r->ch[0]);
			return update(r);
		}
	}

	// ??¨???k????????§?????????[0,k)??¨[k,n)??????k?????¨n-k???????????????
	pair<node_treap<T> *, node_treap<T> *> split(node_treap<T> *t, int k) {
		if (!t)return make_pair((node_treap<T> *)NULL, (node_treap<T> *)NULL);

		if (k <= count(t->ch[0])) {
			pair<node_treap<T> *, node_treap<T> *> s = split(t->ch[0], k);
			t->ch[0] = s.second;
			return make_pair(s.first, update(t));
		}
		else {
			pair<node_treap<T> *, node_treap<T> *> s = split(t->ch[1], k - count(t->ch[0]) - 1);
			t->ch[1] = s.first;
			return make_pair(update(t), s.second);
		}
	}

	// ??´???k??????val?????????
	node_treap<T> *insert(node_treap<T> *t, int k, int val) {
		pair<node_treap<T> *, node_treap<T> *> s = split(t, k);
		return Merge(Merge(s.first, new node_treap<T>(val, drand(0, 1))), s.second);
	}

	// ??´???k?????????
	node_treap<T> *erase(node_treap<T> *t, int k) {
		pair<node_treap<T> *, node_treap<T> *> s1 = split(t, k);
		pair<node_treap<T> *, node_treap<T> *> s2 = split(s1.second, 1);
		return Merge(s1.first, s2.second);
	}

	node_treap<T> *update(node_treap<T> *t, int k, int val) {
		return insert(erase(t, k), k, val);
	}

	// ???????????¨???[a,b)
	T query(node_treap<T> *t, int a, int b) {
		return _query(t, a, b, 0, t->count);
	}
	// ??????[a,b)?????????????????????k=[l,r)????????????????????????
	T _query(node_treap<T> *t, int a, int b, int l, int r) {
		if (r <= a || b <= l)return def();  // ???????????????
		if (a <= l && r <= b)return t->range_value;   // a,l,r,b????????§?????¨???????????????
		else {
			T c1 = !t->ch[0] ? def() : _query(t->ch[0], a, b, l, l + t->ch[0]->count);	// ?????????
			T c2 = !t->ch[1] ? def() : _query(t->ch[1], a, b, l + t->ch[1]->count + 1, r);	// ?????????
			return operation(operation(c1, c2), t->value);
		}
	}

	void show() {
		cout << "Treap(" << root->count << "): "; _show(root); cout << endl;
	}

	void _show(node_treap<T> *t) {
		if (!t) {
			cout << "(NULL)";
			return;
		}
		cout << "(";
		_show(t->ch[0]);
		cout << t->value << " ";
		_show(t->ch[1]);
		cout << ")";
	}
};

