class SquareDivision{
    private:
        const int BUCKET_SIZE=256;
        ll N, B;
        vector<ll> data, bucket_sum, bucket_min;

    public:
        void prepare(int n){
            B=(n+BUCKET_SIZE-1)/BUCKET_SIZE;
            N=B*BUCKET_SIZE;
            data.assign(N, INF);
            bucket_min.assign(B, INF);
        }

        void add(int x, int y){
            ll k=x/BUCKET_SIZE;
            data[x]+=y;
            int sum=0;
            for(int i=k*BUCKET_SIZE; i<(k+1)*BUCKET_SIZE; i++){
                sum+=data[i];
            }
            bucket_sum[k]=sum;
        }

        // [x, y)
        int getsum(int x, int y){
            int sum=0;
            for(int i=0; i<B; i++){
                int l=i*BUCKET_SIZE, r=(i+1)*BUCKET_SIZE;

                if(r<=x || y<=l) continue;

                if(x<=l && r<=y) sum+=bucket_sum[i];
                else{
                    for(int j=max(x, l); j<min(y, r); j++){
                        sum+=data[j];
                    }
                }
            }
            return sum;
        }

        void update(int x, int y){
            int k=x/BUCKET_SIZE;
            ll minval=data[x]=y;
            for(int i=k*BUCKET_SIZE; i<(k+1)*BUCKET_SIZE; i++){
                minval=min(minval, data[i]);
            }
            bucket_min[k]=minval;
        }

        // [x, y)
        int find(int x, int y){
            ll minval=INF;
            for(int i=0; i<B; i++){
                int l=i*BUCKET_SIZE, r=(i+1)*BUCKET_SIZE;

                if(r<=x || y<=l) continue;

                if(x<=l && r<=y) minval=min(minval, bucket_min[i]);
                else{
                    for(int j=max(x, l); j<min(y, r); j++){
                        minval=min(minval, data[j]);
                    }
                }
            }
            return minval;
        }
};

signed main(){
    int n, q; cin>>n>>q;
    SquareDivision ans;
    ans.prepare(n);

    while(q--){
        int c, x, y; cin>>c>>x>>y;
        if(c==0){
            ans.update(x, y);
        }
        else{
            cout << ans.find(x, y+1) << endl;
        }
    }
}

