template<typename MonoidTrait> class SegTree {
  using Monoid = MonoidTrait;
  using T = typename Monoid::value_type;

public:
  Monoid m;
  std::vector<T> data;
  int size = 1;

  // public:
  SegTree(const int &n = 0) {
    m = Monoid();
    while (size < n) size *= 2;
    data.assign(size * 2, m.id());
  }

  template<typename InputIterator> SegTree(InputIterator first, InputIterator last) {
    m = Monoid();
    int n = std::distance(first, last);
    while (size < n) size *= 2;
    data.resize(size * 2, m.id());
    std::copy(first, last, data.begin() + size);
    for (int i = size - 1; i >= 1; --i) data[i] = m(data[i * 2], data[i * 2 + 1]);
  }

  T fold(int l, int r) const {
    T acc = m.id();
    for (l += size, r += size; l < r; l >>= 1, r >>= 1) {
      cerr << l << ' ' << r << endl;
      if (l & 1) acc = m(acc, data[l++]);
      if (r & 1) acc = m(acc, data[--r]);
    }
    return acc;
  }

  void update(int i, const T &x) {
    data[i += size] = x;
    while (i /= 2) data[i] = m(data[i * 2], data[i * 2 + 1]);
  }

  const T &operator[](int i) const { return data[i + size]; }
};

template<typename T, T upperInf = std::numeric_limits<T>::max()> struct minMonoid {
  using value_type = T;
  constexpr T id() const { return upperInf; }
  T operator()(const T &a, const T &b) const { return std::min(a, b); }
};

main {
  using RMQ = SegTree<minMonoid<int, 2147483647>>;
  int n, q;
  cin >> n >> q;
  RMQ t(n);
  while (q--) {
    int com, x, y;
    cin >> com >> x >> y;
    if (com) {
      rep(i, t.data.size()) cerr << t.data[i] << ' ';
      cerr << endl;
      cout << t.fold(x, y + 1) << endl;
    } else {
      t.update(x, y);
    }
  }
}

