struct SegT {
private:
    int sz; vector<int> node;
    const int INT = 2147483647;
public:
    SegT(int n) {
        sz = 1;
        while(sz < n) sz *= 2;
        node.resize(2 * sz - 1, INT);
    }
    SegT(vector<int> &v) {
        int n = v.size();
        sz = 1;
        while(sz < n) sz *= 2;
        node.resize(2 * sz - 1, INT);
        rep(i, n) {
            node[i + sz - 1] = v[i];
        }
        per(i, sz - 1) {
            node[i] = min(node[2 * i + 1], node[2 * i + 2]);
        }
    }
    void update(int k, int a) {
        k += sz - 1;
        node[k] = a;
        while(k > 0) {
            k = (k - 1) / 2;
            node[k] = min(node[2 * k + 1], node[2 * k + 2]);
        }
    }
    int query(int a, int b, int k, int l, int r = -1) {
        if(r < 0) r = sz;
        if(r <= a || b <= l) return INT;

        if(a <= l && r <= b) return node[k];
        else {
            int vl = query(a, b, 2 * k + 1, l, (l + r) / 2);
            int vr = query(a, b, 2 * k + 2, (l + r) / 2, r);
            return min(vl, vr);
        }
    }
};

