struct RMQ{
 UL N;
 vector<UL> V;
 const UL Z=(1u<<31)-1;
 void init(UL n){
  N=1; while(N<n) N*=2;
  V.assign(N*2,Z);
 }
 void upd(UL p,UL v){
  UL i=N+p;
  V[i]=v;
  while(i!=1){
   i>>=1;
   V[i]=min(V[i<<1],V[(i<<1)+1]);
  }
 }
 UL query(UL l,UL r){
  UL ans=Z;
  l+=N; r+=N;
  while(l<r){
   if(l&1) ans=min(ans,V[l++]);
   if(r&1) ans=min(ans,V[--r]);
   l>>=1; r>>=1;
  }
  return ans;
 }
};

int main() {
 UL N,Q; scanf("%u%u",&N,&Q);
 RMQ G; G.init(N);
 rep(i,Q){
  UL c,x,y; scanf("%u%u%u",&c,&x,&y);
  if(c==0) G.upd(x,y);
  else if(c==1) printf("%u\n",G.query(x,y+1));
 }
 return 0;
}

