     ll mn=f[0][l];
     for(; A(l)<=r; l=A(l)) mn=min(mn, f[2][l]);
     for(; B(r)>=l; r=B(r)) mn=min(mn, f[1][r]);
     return min(mn, f[0][l]);
}

