     f[0][p]=v;
     ll mn=v, l=p-1, r=p+1;
     for(int i=p; i<=n; i=A(i)){
          mn=min(mn, f[0][i]);
          for(; l>0 && B(l)+1>=B(i)+1; l=B(l)) mn=min(mn, f[1][l]);
          for(; r<=n && A(r)-1<=i; r=A(r)) mn=min(mn, f[2][r]);
          f[1][i]=mn;
     }
