     for(int i=p; i>0; i=B(i)){
          mn=min(mn, f[0][i]);
          for(; l>0 && B(l)+1>=i; l=B(l)) mn=min(mn, f[1][l]);
          for(; r<=n && A(r)-1<=A(i)-1; r=A(r)) mn=min(mn, f[2][r]);
