template<typename T>
struct segtree {
	vector<T> seg;
	ll siz;
	T unit;
	//const function<T(T, T)> f;
	segtree(ll n, const T a) {//n の大きさ, a で segtree を初期化する
		siz = 1;
		while (siz < n)siz <<= 1;
		seg.assign(2 * siz, a);
		unit = a;
	}

	void update(ll k, T a, const function<T(T, T)> f) {//k の値を a に更新,更新に使う二項演算
		k += siz - 1;
		seg[k] = a;
		while (k > 0) {
			k = ((k - 1) >> 1);
			seg[k] = f(seg[k * 2 + 1], seg[k * 2 + 2]);
		}
	}

private:
	T queryr(const ll a, const ll b, ll k, ll l, ll r, const function<T(T, T)> f) {//再帰用関数
		if (r <= a || b <= l)return unit;//全く関係ないので単位元を返す
		else if (a <= l && r <= b)return seg[k];//全部おおわれているのでその seg を返す
		else {
			T vall = queryr(a, b, k * 2 + 1, l, ((r + l) >> 1), f);
			T valr = queryr(a, b, k * 2 + 2, ((r + l) >> 1), r, f);
			return f(vall, valr);
		}
	}
public:
	T query(ll a, ll b, const function<T(T, T)> f) {//a, b について f した結果を返す
		return queryr(a, b + 1, 0L, 0L, siz, f);//再帰関数内は[a, b)
	}

};

int main() {

	int n, q;
	scanf("%d%d", &n, &q);
	int com, x, y;
	segtree<int> tree(n, pow(2, 31) - 1);
	auto f = [](int a, int b) { return min(a, b); };
	rep(i, q) {
		scanf("%d%d%d", &com, &x, &y);
		if (com) {
			printf("%d\n", tree.query(x, y, f));
		}
		else {
			tree.update(x, y, f);
		}
	}

	Please AC;
}

