class RangeMinimumQuery {
public:
	int n;
	vector<int> d;
	RangeMinimumQuery(int m) {
		for (n = 1; n < m; n *= 2);
		d.assign(n * 2, INF);
	}
	void update(int i, int x) {
		d[n + i] = x;
		for (int j = (n + i) / 2; j > 0; j >>= 1)
			d[j] = min(d[j * 2], d[j * 2 + 1]);
	}
	int query(int l, int r) {
		int mi = get(l);
		for (; l && l + (l&-l) <= r; l += l&-l)
			mi = min(mi, d[(n + l) / (l&-l)]);
		for (; l < r; r -= r&-r)
			mi = min(mi, d[(n + r) / (r&-r) - 1]);
		return mi;
	}
	int get(int i) { return d[n + i]; }
};

signed main() {
	int n, q; cin >> n >> q;
	RangeMinimumQuery RMQ(n);
	rep(i, 0, q) {
		int com, x, y; cin >> com >> x >> y;
		if (com == 0)RMQ.update(x, y);
		else cout << RMQ.query(x, y) << endl;
	}
	return 0;
}

