	for (int i = 0; i < max_array ;i ++) {
		dat[i] = INF;
	}
}

void update(int k,int x) {
	k += max_n - 1;
	dat[k] = x;
	while(k > 0) {
		k = (k - 1) / 2;
		dat[k] = min(dat[k * 2 + 1] ,dat[k * 2 + 2]);
