int B=300;
int a[200000]={};
int b[2000]={};
int n;

void init(){
    rep(i,200000){
        a[i]=INF;
    }
    rep(i,2000){
        b[i]=INF;
    }
}


void update(int m,int x){
    a[m]=x;
    int base=m-(int)(m%B);
    int mini=INF;
    rep(i,B){
        if(base+i<n)
            mini = min(mini,a[base+i]);
    }
    b[m/B] = mini;
}

int find(int s,int t){
    int i=s;
    t++;
    int mini = INF;
    while(i<t){
        if(i%B==0&&i+B<=t){
            mini = min(mini,b[i/B]);
            i+=B;
        }else{
            mini = min(mini,a[i]);
            i++;
        }
    }
    return mini;
}


int main(){
    int q;
    cin>>n>>q;
    init();
    rep(i,q){
        int a,b,c;
        cin>>a>>b>>c;
        if(a==0){
            update(b,c);
        }else{
            cout<<find(b,c)<<endl;
        }
    }
}

