typedef long long ll;

const int INF = (1LL << 31) - 1;

template<class T> class SegT {

   int N;
   vector<T> node;

   public:
      SegT(vector<T> v) {
         int SIZE = v.size();
         N = 1;
         while (N < SIZE) N *= 2;
         node.resize(2 * N - 1);

         // lowest level
         for (int i = 0; i < SIZE; i++) 
            node[i + N - 1] = v[i];
         // others
         for (int i = N - 2; i >= 0; i--) 
            node[i] = node[2 * i + 1] > node[2 * i + 2] ? node[2 * i + 2] : node[2 * i + 1];
      }

      // x: 0-indexed
      void update(int x, T val) {
         // go to the lowest
         x += (N - 1);
         node[x] = val;
         // got to the parent
         while (x > 0) {
            x = (x - 1) / 2;
            node[x] = node[2 * x + 1] > node[2 * x + 2] ? node[2 * x + 2] : node[2 * x + 1];
         }
      }

      // get min in [a, b)
      // k: current node index, 0-indexed

      T getmin(int a, int b, int k = 0, int l = 0, int r = -1) {
         if (r < 0) r = N;
         // no crossing
         if (r <= a || b <= l) return INF;
         // covering
         if (a <= l && r <= b) return node[k];

         T vl = getmin(a, b, 2 * k + 1, l, (l + r) / 2);
         T vr = getmin(a, b, 2 * k + 2, (l + r) / 2, r);
         return vl > vr ? vr : vl;
      }

};

int main() {
   int n, Q;
   cin >> n >> Q;
   SegT<int> segt( vector<int>(n, INF) );
   int c, x, y;
   for (int q = 0; q < Q; q++) {
      cin >> c >> x >> y;
      if (c == 0) segt.update(x, y);
      else cout << segt.getmin(x, y + 1) << endl;
   }
   return 0;
}

