struct BigSegmentTree {
  typedef int T;
  T value;
  int lpos, rpos;
  BigSegmentTree *lch, *rch;
  T empty = 2147483647;

  BigSegmentTree(int n) {
    int n_ = 1;
    while (n_ < n) { n *= 2; }
    lpos = 0, rpos = n_, value = empty;
    lch = rch = nullptr;
  }
  BigSegmentTree(int l, int r) :
    lpos(l), rpos(r), value(empty), lch(nullptr), rch(nullptr) {;}

  T merge(T x, T y) {
    return (x < y ? x : y);
  }

  void update(int pos, T a) {
    cout << "[" << lpos << " " << rpos << "]" << endl;
    if (rpos - lpos <= 1) { 
      value = a; 
      return;
    }
    int mid = (lpos + rpos) / 2;
    if (pos < mid) {
      if (!lch) lch = new BigSegmentTree(lpos, mid);
      lch->update(pos, a);
    } else {
      if (!rch) rch = new BigSegmentTree(mid, rpos);
      rch->update(pos, a);
    }
    T lv = lch ? lch->value:empty, rv = rch ? rch->value:empty;
    value = merge(lv, rv);
  }

  // merge([a, b))
  T query(int a, int b) {
    cout << "(" << a << " " << b << ")" << endl;
    if (rpos <= a || b <= lpos) {
      return empty;
    } else if (a <= lpos && rpos <= b) {
      return value;
    } else {
      T vl = lch ? lch->query(a, b) : empty;
      T vr = rch ? rch->query(a, b) : empty;
      return merge(vl, vr);
    }
  }
};

int main() {
  int n, q;
  BigSegmentTree seg(n);
  cin >> n >> q;

  for (int i = 0; i < q; i++) {
    int com, x, y;
    cin >> com >> x >> y;
    if (com == 0) {
      seg.update(x, y);
    } else {
      cout << seg.query(x, y + 1) << endl;
    }
  }
}

