template<typename T>
struct Segtree{
	vector<T> node;
	int n;
	const T unit=(1ll<<31)-1;
	Segtree(vector<T> data):node(2*(1<<(int)ceil(log2(data.size()))),((1ll<<31)-1)){
		int sz = data.size();
		n = 1<<(int)ceil(log2(sz));
		for(int i=0; i<sz; i++){
			node.at(n+i) = data.at(i);
		}
		for(int i=n-1; i>0; i--){
			node.at(i) = comp( node.at(i*2),node.at(i*2+1) );
		}
	} 
	T comp(const T &a, const T &b){
		return min(a,b);
	}
	void update(int i, T v){
		i += n;
		node.at(i) = v;
		while(i/2){
			i /= 2;
			node.at(i) = comp( node.at(i*2),node.at(i*2+1) );
		}
		for(int i=0; i<node.size(); i++){
			//cout << node.at(i) << endl;
		}
		//cout << endl;
	}
	T find(int a, int b, int now=1, int l=0, int r=-1){
		if(r<0) r = n;
		if(r <= a || b <= l) return unit;
		if(a <= l && r <= b) return node.at(now);
		T lv = find(a, b, 2*now,   l, (l+r)/2);
		T rv = find(a, b, 2*now+1, (l+r)/2, r);
		return comp(lv, rv);
	}
};

