void build(int rt, int l, int r) {
    if (l == r)arr[rt] = 2147483647;
    else {
        build(lson);
        build(rson);
        arr[rt] = min(arr[rt << 1], arr[rt << 1 | 1]);
    }
}

void update(int rt, int l, int r, int pos, int num) {
    if (l == r && r == pos)
        arr[rt] = num;
    else {
        if (pos <= Mid)
            update(lson, pos, num);
        else
            update(rson, pos, num);
        arr[rt] = min(arr[rt << 1], arr[rt << 1 | 1]);
    }
}

