#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

typedef long long ll;

//半開区間なことに注意
//L<=P<R
template <typename Monoid>
class SegmentTree{
public:
    //コンストラクタ n:サイズ pr:初期値
    SegmentTree(ll n,Monoid pr){
        size = pow(2,ceil(log2(n)));
        vec.resize(2*size-1,pr);
    }

    //値の更新　pos:位置(0-indexed) v:更新後の値
    void Update(ll pos,Monoid v){
        ll index = size-1+pos;
        vec[index] = v;
        //上方向に更新
        while(index>0){
            index = (index-1)/2;
            //更新方法
            /*RMQ*/vec[index] = min(vec[index*2+1],vec[index*2+2]);
            /*RSQvec[index] = vec[index*2+1]+vec[index*2+2]*/
        }
    }

    //クエリの処理 L:区間左端 R:区間右端 index:添字(0)
    //begin:ノード左端(0) end:ノード右端(n)
    Monoid Query(ll L,ll R,ll index,ll begin,ll end){
        if (end<=L || R<=begin) {
            //区間に重ならない
            return INT_MAX;
        }
        if (L<=begin && end<=R){
            //完全に含む
            return vec[index];
        }
        Monoid retL = Query(L,R,index*2+1,begin,(begin+end)/2);
        Monoid retR = Query(L,R,index*2+2,(begin+end)/2,end);
        return min(retL,retR);
    }

    //L<=P<R
    Monoid Query(ll L,ll R){
        return Query(L,R,0,0,size);
    }

private:
    vector<Monoid> vec;
    ll size;
};


int main(){
