//セグメント木を持つグローバル配列
int N;
int dat[2 * 1000010 - 1];

//初期化
void init(int N_) {
    N = 1;
    //簡単のため、要素数を2のべき乗に
    while(N < N_) {
        N *= 2;
    }
    //すべての値をINFに
    for(int i = 0;i < 2 * N - 1;i++) {
        dat[i] = pow(2,31) - 1;
    }
}

//k番目の値(0-indexed)をaに変更
void update(int k,int a) {
    //葉の節点
    k += N - 1;
    dat[k] = a;
    //登りながら更新
    while(k > 0) {
        k = (k - 1) / 2;
        dat[k] = min(dat[k * 2 + 1],dat[k * 2 + 2]);
    }
}

//[a,b)の最小値を求める
//後ろの方の引数は、計算のための引数。
//kは節点の番号、1,rはその節点が[1,r)に対応づいていることを表す。
//したがって、外からはquery(a,b,0,0,n)として呼ぶ。
int query(int a,int b,int k,int l,int r) {
    //[a,b)と[l,r)が交差しなければ、INF
    if(r <= a || b <= l) {
        return pow(2,31) - 1;
    }

    //[a,b)が[l,r)を完全に含んでいれば、この節点の値
    if(a <= l && r <= b) {
        return dat[k];
    }
    else {
        //そうでなければ、2つの子の最小値
        int vl = query(a,b,k * 2 + 1,l,(l + r) / 2);
        int vr = query(a,b,k * 2 + 2,(l + r) / 2,r);
        return min(vl,vr);
    }
}

