#define REP(i, a, n) for(ll i = ((ll) a); i < ((ll) n); i++)
using namespace std;
typedef long long ll;

/* 0-indexed, [0, n) */
template<typename Monoid, typename Effect> class SegmentTree {
public:
  typedef function<Monoid (Monoid, Monoid)> Operator;
  typedef function<Monoid (Monoid, Effect)> Apply;

private:
  vector<Monoid> dat;
  ll n;        // size of elements (2^x alignment)
  Monoid e;    // identity of monoid
  Operator op; // binary operator of monoid
  Apply apply; // apply effect to monoid

public:
  SegmentTree(ll _n, Monoid e, Operator op, Apply apply): e(e), op(op), apply(apply) {
    for(n = 1; n < _n; n *= 2);
    dat.resize(n * 2 - 1, e);
  }

  // query for [a, b)
  Monoid query(ll a, ll b) { return query(a, b, 0, 0, n); }
  Monoid query(ll a, ll b, ll k, ll l, ll r) {
    if(r <= a || b <= l) return e;
    if(a <= l && r <= b) return dat[k];
    Monoid vl = query(a, b, k * 2 + 1, l, (l + r) / 2);
    Monoid vr = query(a, b, k * 2 + 2, (l + r) / 2, r);
    return op(vl, vr);
  }

  // update value at k
  void update(ll k, Effect x) {
    k += n - 1;
    dat[k] = apply(dat[k], x);
    while(k > 0) {
      k = (k - 1) / 2;
      dat[k] = op(dat[k * 2 + 1], dat[k * 2 + 2]);
    }
  }

  friend ostream& operator<<(ostream& os, const SegmentTree& segtree) {
    os << "SegmentTree: size = " << segtree.n << endl;
    function<void (ll, ll)> dfs = [&](ll k, ll d) {
      if(k >= segtree.dat.size()) return;
      dfs(k * 2 + 1, d + 1);
      REP(i, 0, d) os << "  ";
      os << segtree.dat[k];
      if(k >= segtree.n - 1) os << " : #" << (k - (segtree.n - 1));
      if(k + 1 != segtree.dat.size()) os << endl;
      dfs(k * 2 + 2, d + 1);
    };
    dfs(0, 0);
    return os;
  }
};

