using namespace std;
#define MOD ((1<<31)-1)
#define f(i,n) for(int i=0;i<int(n);i++)
#define N (1000000)
#define M (1000000000)
int a[N];
int sl[N];
int sr[N];
int l[N];
int r[N];
int nx;

//初期化
void init(void){
	f(i, N){
		a[i] = MOD;
		sl[i] = -1;
		sr[i] = -1;
	}
	l[0] = 0;
	r[0] = M;
	nx = 1;
	return;
}


//変更(k=0-(M-1))
void change(int k, int x){
	stack<int>st;
	int p = 0;
	int y;
	while (l[p] + 1 < r[p]){
		st.push(p);
		y = (l[p] + r[p]) / 2;
		if (k < y){
			if (sl[p] == -1){
				l[nx] = l[p];
				r[nx] = y;
				sl[p] = nx;
				p = nx;
				nx++;
			}
			else{
				p = sl[p];
			}
		}
		else{
			if (sr[p] == -1){
				l[nx] = y;
				r[nx] = r[p];
				sr[p] = nx;
				p = nx;
				nx++;

			}
			else{
				p = sr[p];
			}
		}
	}
	a[p] = x;
	while (!st.empty()){
		p = st.top();
		if (sr[p] == -1)a[p] = a[sl[p]];
		else if (sl[p] == -1)a[p] = a[sr[p]];
		else a[p] = min(a[sl[p]], a[sr[p]]);
		st.pop();
	}
	return;
}
//探索(0<=l<r<=n)範囲は(l<=x<r)初期は(l,r,0)
int min_search(int ll, int rr, int k){
	int vl, vr;
	if (rr <= l[k] || r[k] <= ll)return MOD;
	else if (ll <= l[k] && r[k] <= rr) return a[k];
	else{
		if (sl[k] != -1)vl = min_search(ll, rr, sl[k]);
		else vl = MOD;
		if (sr[k] != -1)vr = min_search(ll, rr, sr[k]);
		else vr = MOD;
		return min(vl, vr);
	}
}


