      rep2(i,n,2*n) {
         ls[i] = i-n;
         rs[i] = i-n+1;
      }
      for(Int i = n-1; i >= 1; --i) {
         ls[i] = ls[2*i];
         rs[i] = rs[2*i+1];
      }
   }
   Int n;
   std::vector<Int> xs;
   std::vector<Int> ls, rs;
