using namespace std;

struct RBTree{

  struct node_t{
    int val,size,rank,color;
    node_t *lp,*rp;

    node_t(int v):val(v){
      size = 1;
      rank = 0;
      color = BLACK;
      lp = rp = NULL;
    }

    node_t(node_t *l,node_t *r,int c){
      val = min(r->val,l->val);
      size = l->size + r->size;
      rank = r->rank + r->color;
      color = c;
      lp=l, rp=r;
    }

    bool isBlack(){return color;}
    bool isRed(){return !color;}
  };


  node_t *merge_r(node_t *l,node_t *r){

    if(l->rank > r->rank){
      node_t *tmp = merge(l->rp, r);
      if(l->isBlack() && tmp->isRed() && tmp->rp->isRed()){
	if(l->lp->isBlack()){
	  return new node_t(new node_t(l->lp,tmp->lp,RED),tmp->rp,BLACK);
	}
	else {
	  return new node_t(new node_t(l->lp,tmp->lp,BLACK),
			    new node_t(tmp->rp->lp,tmp->rp->rp,BLACK),RED);
	}
      }
      else {
	return new node_t(l->lp,tmp,RED);
      }
    }
    else if(l->rank < r->rank){
      node_t *tmp = merge(l, r->lp);
      if(r->isBlack() && tmp->isRed() && tmp->lp->isRed()){
	if(r->rp->isBlack()){
	  return new node_t(tmp->lp, new node_t(tmp->rp,r->rp,RED),BLACK);
	}
	else {
	  return new node_t(new node_t(tmp->lp->lp,tmp->lp->rp,BLACK),
			    new node_t(tmp->rp,r->rp,BLACK),RED);

	  /*
	  return new node_t(new node_t(tmp->lp,tmp->rp,BLACK),
			    new node_t(r->rp->lp,r->rp->rp,BLACK),RED);	  
	  */	
	}
      }
      else {
	return new node_t(tmp,r->rp,RED);
      }
    }
    else {
      return new node_t(l,r,RED);
    }
  }

  node_t *merge(node_t *l, node_t *r){
    if(!l || !r)return l?l:r;
    node_t *res = merge_r(l,r);
    res->color = BLACK;
    return res;
  }

  typedef pair<node_t *,node_t *>P;

  P split(node_t *x, int pos){
    if(pos == 0)return P(0,x);
    if(!x || x->size == pos)return P(x,0);

    int lsize = x->lp?x->lp->size:0;
    if(lsize > pos){
      P tmp = split(x->lp,pos);
      return P(tmp.first,merge(tmp.second, x->rp));
    }
    else if(pos < lsize){
      P tmp = split(x->rp, pos - lsize);
      return P(merge(x->lp,tmp.first),tmp.second);
    }
    else {
      return P(x->lp, x->rp);
    }
  }

  node_t *root;
  RBTree(){
    //root = new node_t(INF);
  }

  /*
  node_t *insert(node_t *x, int val, int pos){
    node_t *p = new node_t(val);
    P tmp = split(x,pos);
    node_t *l = merge(tmp.first,p), *r = tmp.second;
    return merge(l,r);
  }

  node_t *erase(node_t *x, int pos){
    P tmp = split(x,pos);
    node_t *l = tmp.first;
    node_t *r = split(tmp.second,1).second;
    return merge(l,r);
  }
  */
  node_t *insert(node_t *t,int k,int val){
    pair<node_t *,node_t *>s=split(t,k);
    t=merge(s.first, new node_t(val));
    t=merge(t,s.second);
    return t;
  }

  node_t *erase(node_t *t,int k){
    pair<node_t *,node_t *>s1,s2;
    s2=split(t,k+1);
    s1=split(s2.first,k);
    delete s1.second;
    return (t=merge(s1.first,s2.second));
  }

  void insert(int k,int val){ root=insert(root,k,val); }
  void erase(int k){ root=erase(root,k); }

  void update(int id,int val){
    erase(id);
    insert(id,val);
  }

  int query(node_t *x, int left, int right){
    //if(x)cout << "aaa " << x->val << endl;
    if(right <= 1)return x?x->val:INF;
    if(x->size <= left)return INF;
    if(left <= 1 && x->size < right)return x->val;
    int lsize = x->lp->size;
    int lv = query(x->lp,left,right);
    int rv = query(x->rp,left-lsize,right-lsize);
    return min(lv,rv);
  }

};

int main(void){

  int n,q,com,x,y;
  RBTree t;

  cin >> n >> q;

  for(int i=0;i<=n;i++)t.insert(i,INF);

  while(q--){
    cin >> com >> x >> y;
    if(com==0)t.update(x,y);
    else cout << t.query(t.root,x,y+1) << endl;
  }

  return 0;
}

