int min(int a, int b) {
    return (a < b) ? a : b;
}

typedef struct node {
    int value, size;
    struct node *lch, *rch;
} node_t;

typedef node_t* segtree_t;

void combine_segtree(segtree_t root) {
    root->size = root->lch->size + root->rch->size;
    root->value = min(root->lch->value, root->rch->value);
}

segtree_t make_segtree(int size) {
    segtree_t root = (segtree_t)malloc(sizeof(node_t));
    root->size = size;
    root->value = INT_MAX;
    root->lch = root->rch = NULL;
    if (size == 1) return root;
    root->lch = make_segtree(size / 2);
    root->rch = make_segtree(size - size / 2);
    combine_segtree(root);
    return root;
}

void free_segtree(segtree_t root) {
    if (root->lch) free(root->lch);
    if (root->rch) free(root->rch);
    free(root);
}

void update_segtree(segtree_t root, int k, int x) {
    if (root->lch == NULL && root->rch == NULL) {
        free_segtree(root);
        root = make_segtree(1);
        if (k == 0) root->value = x;
    }
    else if (k < root->lch->size) {
        update_segtree(root->lch, k, x);
        combine_segtree(root);
    }
    else {
        int lsize = root->lch->size;
        update_segtree(root->rch, k - lsize, x);
        combine_segtree(root);
    }
}

int min_query(segtree_t root, int a, int b) {
    if (root->lch == NULL)
        return (a <= 0 && b > 0)
            ? root->value
            : INT_MAX;
    if (a <= 0 && root->size <= b) return root->value;
    if (b <= 0 || root->size <= a) return INT_MAX;
    int lsize = root->lch->size,
        left = min_query(root->lch, a, b),
        right = min_query(root->rch, a - lsize, b - lsize);
    return min(left, right);
}

enum command { Update, Find, };

int main(void) {
    int n, q, i;
    scanf("%d%d", &n, &q);
    segtree_t rmq = make_segtree(n);
    for (i = 0; i < q; i++) {
