void update(int arrIndex, int val) {
  //printf("updating node %d\n", arrIndex);
  mins[arrIndex] = val;

  if (arrIndex <= 1)
    return;

  if (mins[arrIndex / 2] > val)
    update(arrIndex / 2, val);
}

int find(int node, int l, int r, int i, int j) {
  if (r < i || l > j)
    return INT_MAX;
  else if (l >= i && r <= j)
    return mins[node];
  else {
    int lValue = find(2*node, l, (l + r) / 2, i, j);
    int rValue = find((2*node)+1, (l + r) / 2 + 1, r, i, j);

    return lValue < rValue ? lValue : rValue;
  }
}

