    } while (c >= '0' && c <= '9');
    return -n;
  } else {
    do {
      n = 10 * n + c - '0';
      c = getchar_unlocked();
    } while (c >= '0' && c <= '9');
    return n;
  }
}

void update(LL k, LL a, LL n)
{
  k += n - 1;
  dat[k] = a;
  while (k > 0) {
    k = (k - 1)/ 2;
    dat[k] = min(dat[k * 2 + 1], dat[k * 2 + 2]);
  }
}

LL minimize(LL a, LL b, LL k, LL l, LL r)
{
  if (a >= r || b <= l) return INF;
  else if (a <= l && b >= r) return dat[k];
  else {
    LL vl , vr;
    vl = minimize(a, b, k * 2 + 1, l, (l + r) / 2);
    vr = minimize(a, b, k * 2 + 2 , (l + r) / 2, r);
    return min(vl, vr);
  }
}

