                result = A_MAX;
                if(que.x > que.y){
                    r1 = que.y;
                    r2 = que.x;
                }else{
                    r1 = que.x;
                    r2 = que.y;
                }
                if((r2 - r1) < (call_count * 3)){
                    for(ii = r1; ii <= r2; ii++){
                        if(result > a[ii]){
                            result = a[ii];
                        }
                    }
                }else{
                    for(ii = 0; ii < call_count; ii++){
                        if(result > a[call_list[ii]]){
                            if(r1 <= call_list[ii] && call_list[ii] <= r2){
                                result = a[call_list[ii]];
                            }
                        }
                    }
                }
                que_cache = que;
                result_cache = result;
            }else{
                result = A_MAX;
                que_cache = que;
                result_cache = result;
            }
            call_count_cache = call_count;
            printf("%d\n", result);
            break;
        default:
            break;
    } 
}

