    int R = y / offset;

    if (L <= R) {
        for (i = x; i < L * offset; i++) ans = min(ans, A[i]);
        for (i = L; i < R; i++) ans = min(ans, rmq[i]);
        for (i = R * offset; i <= y; i++) ans = min(ans, A[i]);
