    int i;
    int ans = INT_MAX;

    int L = (x + offset - 1) / offset + 1;
    int R = y / offset;

    if (L <= R) {
        for (i = x; i < L * offset; i++) ans = min(ans, A[i]);
        for (i = L; i < R; i++) ans = min(ans, rmq[i]);
        for (i = R * offset; i < y; i++) ans = min(ans, A[i]);
    }else{/* minimua value is included in one bucket. */
        for (i = x; i < y; i++) ans = min(ans, A[i]);
    }
    return ans;
}



