  int i, left, right;

  for (i = 1; i < size; i++) {
    left = mins[2 * i];
    right = mins[2 * i + 1];
    if (mins[i] < left && mins[i] < right) {
      mins[i] = min(left, right);
      check(size);
      break;
    }
  }
}

int find(int node, int l, int r, int i, int j) {
  if (r < i || l > j)
    return INT_MAX;
  else if (l == i && r == j)
    return mins[node];
  else {
    int lValue = find(2*node, l, (l + r) / 2, i, j);
    int rValue = find((2*node)+1, (l + r) / 2 + 1, r, i, j);

    return lValue < rValue ? lValue : rValue;
  }
}

