static int[] seg;
static int MAX_ELE;

public static void seg_init(int n){
 MAX_ELE=1;
 while(MAX_ELE<n) MAX_ELE<<=2;
 seg=new long[MAX_ELE<<1-1];
 Arrays.fill(seg,(long)Math.pow(2,31)-1);
}

public static void update(int k,long val){
 k+=MAX_ELE-1;
 seg[k]=val;
 while(k>0){
  k--; k>>=1;
  seg[k]=Math.min(seg[k<<1+1],seg[k<<1+2]);
 }
}

public static long query(int a,int b){
 return _query(a,b,0,0,MAX_ELE);
}

public static long _query(int a,int b,int k,int l,int r){
 if(a<=l&&b>=r) return seg[k];
 if(a>=r||b<=l) return (long)Math.pow(2,31)-1;
 long cl=_query(a,b,k<<1+1,l,(l+r)>>1);
 long cr=_query(a,b,k<<1+2,(l+r)>>1,r);
 return Math.min(cl,cr);
}

public static void main(String[] args) throws Exception{
 ir=new InputReader(System.in);
 out=new PrintWriter(System.out);
 solve();
 out.flush();
}

static class InputReader {
 private InputStream in;
 private byte[] buffer=new byte[1024];
 private int curbuf;
 private int lenbuf;

 public InputReader(InputStream in) {this.in=in; this.curbuf=this.lenbuf=0;}

 public boolean hasNextByte() {
  if(curbuf>=lenbuf){
   curbuf= 0;
   try{
    lenbuf=in.read(buffer);
   }catch(IOException e) {
    throw new InputMismatchException();
   }
   if(lenbuf<=0) return false;
  }
  return true;
 }

 private int readByte(){if(hasNextByte()) return buffer[curbuf++]; else return -1;}

 private boolean isSpaceChar(int c){return !(c>=33&&c<=126);}

 private void skip(){while(hasNextByte()&&isSpaceChar(buffer[curbuf])) curbuf++;}

 public boolean hasNext(){skip(); return hasNextByte();}

 public String next(){
  if(!hasNext()) throw new NoSuchElementException();
  StringBuilder sb=new StringBuilder();
  int b=readByte();
  while(!isSpaceChar(b)){
   sb.appendCodePoint(b);
   b=readByte();
  }
  return sb.toString();
 }

 public int nextInt() {
  if(!hasNext()) throw new NoSuchElementException();
  int c=readByte();
  while (isSpaceChar(c)) c=readByte();
  boolean minus=false;
  if (c=='-') {
   minus=true;
   c=readByte();
  }
  int res=0;
  do{
   if(c<'0'||c>'9') throw new InputMismatchException();
   res=res*10+c-'0';
   c=readByte();
  }while(!isSpaceChar(c));
  return (minus)?-res:res;
 }

 public long nextLong() {
  if(!hasNext()) throw new NoSuchElementException();
  int c=readByte();
  while (isSpaceChar(c)) c=readByte();
  boolean minus=false;
  if (c=='-') {
   minus=true;
   c=readByte();
  }
  long res = 0;
  do{
   if(c<'0'||c>'9') throw new InputMismatchException();
   res=res*10+c-'0';
   c=readByte();
  }while(!isSpaceChar(c));
  return (minus)?-res:res;
 }

 public double nextDouble(){return Double.parseDouble(next());}

 public BigInteger nextBigInteger(){return new BigInteger(next());}

 public int[] nextIntArray(int n){
  int[] a=new int[n];
  for(int i=0;i<n;i++) a[i]=nextInt();
  return a;
 }

 public long[] nextLongArray(int n){
  long[] a=new long[n];
  for(int i=0;i<n;i++) a[i]=nextLong();
  return a;
 }

 public char[][] nextCharMap(int n,int m){
  char[][] map=new char[n][m];
  for(int i=0;i<n;i++) map[i]=next().toCharArray();
  return map;
 }
}
}

import java.io.IOException;
import java.io.BufferedReader;
import java.io.InputStreamReader;

public class Main {
    static int[] A = new int[100000];
    static int[] B = new int[101];

    static void update(int i, int x){
        if (A[i] == Integer.MAX_VALUE){
            A[i] = x;
            B[i/1000] = Math.min(x, B[i/1000]);
        }else{
            A[i] = x;
            int min = Integer.MAX_VALUE;
            for (int j = i/1000 * 1000; j < (i/1000 + 1) * 1000; j++){
                if (A[j] < min){
                    min = A[j];
                }
            }
            B[i/1000] = min;
        }
    }

    static void find(int s, int t){
        int min = Integer.MAX_VALUE;
        if (s/1000 == t/1000 || s/1000 + 1 == t/1000){
            for (int i = s; i < t + 1; i++){
                if (A[i] < min){
                    min = A[i];
                }
            }            
        }else{
            //left range
            for (int i = s; i < (s/1000 +1)*1000; i++){
                if (A[i] < min){
                    min = A[i];
                }
            }

            for (int j = s/1000 + 1; j < t/1000; j++){
                if (B[j] < min){
                    min = B[j];
                }
            }   
            //right range
            for (int i = (t/1000) * 1000; i < t + 1; i++){
                if (A[i] < min){
                    min = A[i];
                }
            }
        }System.out.println(min);
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] line = br.readLine().split(" ");
        int n = Integer.parseInt(line[0]);
        int q = Integer.parseInt(line[1]);
        for (int i = 0; i < 100000; i++){
            A[i] = Integer.MAX_VALUE;
        }
        for (int i = 0; i < 101; i++){
            B[i] = Integer.MAX_VALUE;
        }
        for (int k = 0; k < q; k++){
            String[] ln = br.readLine().split(" ");
            int com = Integer.parseInt(ln[0]);
            int x = Integer.parseInt(ln[1]);
            int y = Integer.parseInt(ln[2]);
            if (com == 0){
                update(x,y);
            }else{
                find(x,y);
            }
        }
    }
}

import java.io.BufferedReader;
