public class Main {

	public static void main(String[] args) throws IOException {
		new Main().run();
	}

	public void run() throws IOException {
		BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
		StringTokenizer st = new StringTokenizer(reader.readLine());
		int n = Integer.parseInt(st.nextToken());
		int[] a = new int[n];
		for (int i = 0; i < n; i++) a[i] = 2147483647;
		int q = Integer.parseInt(st.nextToken());
		for (int i = 0; i < q; i++) {
			st = new StringTokenizer(reader.readLine());
			int c = Integer.parseInt(st.nextToken());
			int x = Integer.parseInt(st.nextToken());
			int y = Integer.parseInt(st.nextToken());
			if (c == 0) {
				a[x] = y;
			} else {
				System.out.println(find(a, x, y));
			}
		}
		reader.close();
	}

	private int find(int[] a, int x, int y) {
		int min = Integer.MAX_VALUE;
		for (int i = x; i <= y; i++) {
			min = Math.min(min, a[i]);
		}
		return min;
	}
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

public class Main {
	private static FastScanner sc = new FastScanner();
	static NodeSegmentTree[] V;
	static int N;

	public static void main(String[] args) {
		int n = sc.nextInt();
		int q = sc.nextInt();

		N = 1;
		while(N < n) {
			N *= 2;
		}
		N = N * 2 - 1;
		if(N == 1) {
			N = 3;
		}

		V = new NodeSegmentTree[N];
		for(int i=0; i<N; i++) {
			V[i] = new NodeSegmentTree(i);
		}

		for(int i=N/2 - 1; i>=0; i--) {
			V[i].setSegment();
		}

		StringBuilder sb = new StringBuilder();
		for(int i=0; i<q; i++) {
			int cmd = sc.nextInt();
			int x = sc.nextInt();
			int y = sc.nextInt();

			if(cmd == 0) {
				V[N/2 + x].updateValue(y);
			} else {
				int ans = V[0].getMinimum(x, y);
				sb.append(ans);
				sb.append("\n");
			}
		}

		System.out.print(sb);

	}

	static class NodeSegmentTree {
		int seg_left;
		int seg_right;
		int id;
		int value = Integer.MAX_VALUE;
		//left = 2 * id + 1
		//right = 2 * id + 2
		//parent = (id - 1) / 2
		//array[i] -> V[N/2 + i]

		NodeSegmentTree(int id) {
			this.id = id;
			this.seg_left = id - N/2;
			this.seg_right = id - N/2;
		}

		void setSegment() {
			seg_left = V[2 * id + 1].seg_left;
			seg_right = V[2 * id + 2].seg_right;
		}

		void updateValue(int value) {
			if(id >= N/2 || value < this.value) {
				this.value = value;
				V[(id - 1) / 2].updateValue(value);
			} else if(value != V[2 * id + 1].value && value != V[2 * id + 2].value) {
				this.value = Math.min(V[2 * id + 1].value, V[2 * id + 2].value);
				V[(id - 1) / 2].updateValue(value);
			}
		}

		public int getMinimum(int l, int r) {
//			System.out.println(id + " " + value);
			if(l <= seg_left && r >= seg_right) {
				return value;
			}
			if(l > seg_right || r < seg_left) {
				return Integer.MAX_VALUE;
			}

			int a = V[2 * id + 1].getMinimum(l, r);
			int b = V[2 * id + 2].getMinimum(l, r);
			return Math.min(a, b);
		}

	}

	static class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException  e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }

        String nextLine() {
            String str = "";
            try {
                str = br.readLine();
            } catch (IOException e) {
                e.printStackTrace();
            }
            return str;
        }
    }
}

import java.io.InputStream;
import java.io.PrintStream;
import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;
import java.util.function.BinaryOperator;

class SegmentTree<T> {

	private List<T> nodes;
	private T e; // 単位元
	private int n;
	private BinaryOperator<T> operator;

	/**
	 * セグメント木を生成
	 * 
	 * @param n  要素数
	 * @param e  単位元
	 * @param op
	 */
	public SegmentTree(int n, T e, BinaryOperator<T> op) {
		this.e = e;
		this.operator = op;

		n = 1 << (32 - Integer.numberOfLeadingZeros(Math.max(n - 1, 0))); // n以上で最小の2のべき乗
		this.n = n;

		nodes = new ArrayList<>(2 * n - 1);
		for (int i = 0; i < 2 * n - 1; i++) {
			nodes.add(e);
		}
	}

	//
	public void update(int k, T val) {
		k += n - 1;
		nodes.set(k, val);

		while (k > 0) {
			k = (k - 1) / 2;
			nodes.set(k, operator.apply(nodes.get(2 * k + 1), nodes.get(2 * k + 2)));
		}
	}

	// 区間 [a,b) のoperatorの結果を返す
	// 0-indexed
	public T query(int a, int b) {
		return query(a, b, 0, 0, n);
	}

	private T query(int a, int b, int k, int l, int r) {
		if (a >= r || b <= l) {
			return e;
		}

		if (a <= l && r <= b) {
			return nodes.get(k);
		}

		T vl = query(a, b, 2 * k + 1, l, (l + r) / 2);
		T vr = query(a, b, 2 * k + 2, (l + r) / 2, r);
		return operator.apply(vl, vr);
	}

}

public class Main {
	InputStream in = System.in;
	PrintStream out = System.out;

	public void _main(String[] args) {
		Scanner sc = new Scanner(in);

		int n = sc.nextInt();
		int q = sc.nextInt();

		SegmentTree<Integer> seg = new SegmentTree<>(n, (1 << 31) - 1, (a, b) -> Math.min(a, b));

		for (int i = 0; i < q; i++) {
			int com = sc.nextInt();
			int x = sc.nextInt();
			int y = sc.nextInt();

			switch (com) {
			case 0:
				seg.update(x, y);
				break;
			case 1:
				out.println(seg.query(x, y + 1)); // [x,y] なので半開区間にする
				break;
			}
		}

		sc.close();

	}

	public static void main(String[] args) {
		new Main()._main(args);
	}
}

