import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.NoSuchElementException;

public class Main implements Runnable {

	int N,Q;

	static class SimpleSegTree {
		static int DEF = Integer.MAX_VALUE;
		int[] seg;
		int n;

		public SimpleSegTree(int size,int fill){

			n = 1;
			while(n < size){
				n <<= 1;
			}

			seg = new int[2 * n - 1];
			Arrays.fill(seg,fill);
		}

		public void set(int ind,int val){

			ind += n - 1;
			seg[ind] = val;

			while(ind > 0){

				ind = ind-1 >> 1;
				seg[ind] = Math.min(seg[ind * 2 + 1],seg[ind * 2 + 2]);
			}
		}

		public int query(int a,int b,int k,int l,int r){

			if(r <= a || b <= l){
				return DEF;
			}

			if(a <= l && r <= b){
				return seg[k];
			}

			int left = query(a,b,k * 2 + 1,l,(l+r)>>1);
			int right = query(a,b,k * 2 + 2,(l+r)>>1,r);

			return Math.min(left, right);
		}

		public int min(int l,int r){
			return query(l,r,0,0,n);
		}
	}


	public void solve() {
		N = nextInt();
        Q = nextInt();

        SimpleSegTree segTree = new SimpleSegTree(N,Integer.MAX_VALUE);

        for(int i = 0;i < Q;i++){
            int c = nextInt();
            int x = nextInt();
            int y = nextInt();

            if(c == 0){
                segTree.set(x,y);
            }else{
                out.println(segTree.min(x,y+1));
            }
        }

	}

	public static void main(String[] args) {
		new Thread(null, new Main(), "", 32 * 1024 * 1024).start();
	}

	/* Input */
	private static final InputStream in = System.in;
	private static final PrintWriter out = new PrintWriter(System.out);
	private final byte[] buffer = new byte[2048];
	private int p = 0;
	private int buflen = 0;

	private boolean hasNextByte() {
		if (p < buflen)
			return true;
		p = 0;
		try {
			buflen = in.read(buffer);
		} catch (IOException e) {
			e.printStackTrace();
		}
		if (buflen <= 0)
			return false;
		return true;
	}

	public boolean hasNext() {
		while (hasNextByte() && !isPrint(buffer[p])) {
			p++;
		}
		return hasNextByte();
	}

	private boolean isPrint(int ch) {
		if (ch >= '!' && ch <= '~')
			return true;
		return false;
	}

	private int nextByte() {
		if (!hasNextByte())
			return -1;
		return buffer[p++];
	}

	public String next() {
		if (!hasNext())
			throw new NoSuchElementException();
		StringBuilder sb = new StringBuilder();
		int b = -1;
		while (isPrint((b = nextByte()))) {
			sb.appendCodePoint(b);
		}
		return sb.toString();
	}

	public int nextInt() {
		return Integer.parseInt(next());
	}

	public long nextLong() {
		return Long.parseLong(next());
	}

	public double nextDouble() {
		return Double.parseDouble(next());
	}

	@Override
	public void run() {
		out.flush();
		new Main().solve();
		out.close();

	}
}

public class Main {

	public void run(java.io.InputStream in, java.io.PrintStream out) {
		final java.util.Scanner sc = new java.util.Scanner(in);
		final RankInADynamicSubset lis = new RankInADynamicSubset(sc.nextInt());
		final int q = sc.nextInt();

		for (int i = 0; i < q; ++i) {
			final int com = sc.nextInt();
			final int x = sc.nextInt();
			final int y = sc.nextInt();

			if (com == 0) {
				lis.add(x, y);
			} else if (com == 1) {
				out.println(lis.currentRankOf(x, y));
			}
		}

		sc.close();
	}

	public static void main(String[] args) {
		(new Main()).run(System.in, System.out);
	}

	private static class RankInADynamicSubset {
		private int[] d;
		private int   n;

		public RankInADynamicSubset(int n) {
			this.n = 1;
			while (this.n < n) {
				this.n *= 2;
			}
			d = new int[this.n * 2];
			java.util.Arrays.fill(d, 2147483647);
		}

		public void add(int i, int x) {
			i = n + i;
			d[i] = x;
			while (i != 1) {
				i /= 2;
				d[i] = Math.min(d[i * 2], d[i * 2 + 1]);
			}
		}

		public int currentRankOf(int s, int t) {
			return currentRankOf(s, t, 0, n - 1, 1);
		}

		private int currentRankOf(int s, int t, int lb, int ub, int i) {
			final int m = (lb + ub) / 2;
			int res;

			if (s <= lb && ub <= t) {
				return (d[i]);
			}

			res = Integer.MAX_VALUE;
			if (s <= m) {
				res = Math.min(res, currentRankOf(s, t, lb, m, i * 2));
			}
			if (m + 1 <= t) {
				res = Math.min(res, currentRankOf(s, t, m + 1, ub, i * 2 + 1));
			}

			return (res);
		}
	}

}

