/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        Scanner in = new Scanner(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        HackerEarthRangeMinimumQuery solver = new HackerEarthRangeMinimumQuery();
        solver.solve(1, in, out);
        out.close();
    }

    static class HackerEarthRangeMinimumQuery {
        public void solve(int testNumber, Scanner in, PrintWriter out) {
            int n = in.nextInt();
            int q = in.nextInt();
            int[] a = new int[n];
            int[] b = new int[4 * n];
            for (int i = 0; i < n; i++) {
                a[i] = in.nextInt();
            }

            build(0, 0, n - 1, a, b);
            while (q-- != 0) {
                String s = in.next();
                int l = in.nextInt() - 1;
                int r = in.nextInt() - 1;

                if (s.equals("q")) {
                    out.printf("%d\n", query(0, 0, n - 1, l, r, b));
                } else {
                    update(0, 0, n - 1, l, r + 1, a, b);
                }
            }
        }

        private void build(int n, int s, int e, int[] a, int[] b) {
            if (s == e) {
                b[n] = a[s];
            } else {
                int m = (s + e) / 2;
                build(2 * n + 1, s, m, a, b);
                build(2 * n + 2, m + 1, e, a, b);

                b[n] = Math.min(b[2 * n + 1], b[2 * n + 2]);
            }
        }

        private void update(int n, int s, int e, int idx, int val, int[] a, int[] b) {
            if (s == e) {
                a[idx] = val;
                b[n] = val;
            } else {
                int m = (s + e) / 2;
                if (s <= idx && idx <= m) {
                    update(2 * n + 1, s, m, idx, val, a, b);
                } else {
                    update(2 * n + 2, m + 1, e, idx, val, a, b);
                }

                b[n] = Math.min(b[2 * n + 1], b[2 * n + 2]);
            }
        }

        private int query(int n, int s, int e, int l, int r, int[] b) {
            if (r < s || e < l) {
                return Integer.MAX_VALUE;
            } else if (l <= s && e <= r) {
                return b[n];
            } else {
                int m = (s + e) / 2;
                int ml = query(2 * n + 1, s, m, l, r, b);
                int mr = query(2 * n + 2, m + 1, e, l, r, b);

                return Math.min(ml, mr);
            }
        }

    }
}

import java.util.Arrays;
import java.util.Scanner;


public class Main {

    public static class SegmentTree {

        int[] tree;
        int rawLen;

        public SegmentTree(int rawLen) {
            int len = Integer.highestOneBit(rawLen) << 2;
            tree = new int[len];
            this.rawLen = rawLen;
//            initTree(1, 0, rawLen - 1);
            Arrays.fill(tree, Integer.MAX_VALUE);

        }

//        /**
//         * @param idx of tree[]
//         * @param rangeBegin of raw[]
//         * @param rangeEnd of raw[]
//         */
//        private void initTree(int idx, int rangeBegin, int rangeEnd) {
//            if (rangeBegin == rangeEnd) {
//                tree[idx] = raw[rangeBegin];
//            } else {
//                initTree(idx * 2, rangeBegin, (rangeEnd + rangeBegin) / 2);
//                initTree(idx * 2 + 1, (rangeEnd + rangeBegin) / 2 + 1, rangeEnd);
//                tree[idx] = tree[idx * 2] < tree[idx * 2 + 1] ? tree[idx * 2] : tree[idx * 2 + 1];
//            }
//        }
        public int query(int left, int right) {
            return query(1, 0, rawLen - 1, left, right);
        }

        public void update(int idx, int newValue) {
            update(idx, newValue, 1, 0, rawLen - 1);
        }

        /**
         * Invariant: rangeBegin <= left <= right <= rangeEnd
         */
        private int query(int idx, int rangeBegin, int rangeEnd, int left, int right) {
            Integer leftResult = null;
            Integer rightResult = null;
            if (rangeBegin == rangeEnd) {
                return tree[idx];
            }
            int rangeMid = (rangeBegin + rangeEnd) / 2;
            if (left <= rangeMid) {
                leftResult = query(idx * 2, rangeBegin, rangeMid, left, Math.min(right, rangeMid));
            }
            if (rangeMid + 1 <= right) {
                rightResult = query(idx * 2 + 1, rangeMid + 1, rangeEnd, Math.max(left, rangeMid + 1), right);
            }
            if (leftResult == null) {
                return rightResult;
            } else if (rightResult == null) {
                return leftResult;
            } else {
                return Math.min(leftResult, rightResult);
            }
        }

        private void update(int idxToUpdate, int newValue, int idx, int rangeBegin, int rangeEnd) {
            if (rangeBegin == rangeEnd) {
                tree[idx] = newValue;
            } else {
                int rangeMid = (rangeBegin + rangeEnd) / 2;
                if (idxToUpdate > rangeMid) {
                    update(idxToUpdate, newValue, idx * 2 + 1, rangeMid + 1, rangeEnd);
                } else {
                    update(idxToUpdate, newValue, idx * 2, rangeBegin, rangeMid);
                }
                tree[idx] = tree[idx * 2] < tree[idx * 2 + 1] ? tree[idx * 2] : tree[idx * 2 + 1];
            }
        }

    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        SegmentTree segTree = new SegmentTree(n);
        int q = scanner.nextInt();
        while (q-- > 0) {
            if (scanner.nextInt() == 0) { // update
                int idx = scanner.nextInt();
                int value = scanner.nextInt();
                segTree.update(idx, value);
            } else { // query
                int l = scanner.nextInt();
                int r = scanner.nextInt();
                System.out.println(segTree.query(l, r));
            }
        }
    }
}

