// by heap DST
class RMinQ{
    int[] heap;
    int n;

    static int log2(int n) {
        int ret = 0, pow = 1;
        while (pow <= n-1) {
            pow = pow * 2;
            ret += 1;
        }
        return ret;
    }

    RMinQ(int n, int val) {
        // construct complelte binary heap
        this.n = n;
        int heapLen = (int) Math.pow(2, log2(n) + 1);
        heap = new int[heapLen];
        Arrays.fill(heap, val);
    }

    void update(int i, int val) {
        if (i >= n || i < 0) {
            return;
        }

//        if(val < heap[1]) heap[1] = val;
        heap[1] = val;
        if (n <= 1) {
            return;
        }

        if (i < n / 2) {
            update(2, val, i, 0, n / 2);
        }else {
            update(3, val, i, n/2, n);
        }
    }
    private void update(int iheap, int val, int i, int left, int right) {
//        if(val < heap[iheap]) heap[iheap] = val;
        heap[iheap] = val;

        if (right - left <= 1) {
            return;
        }

        if (i < (left + right) / 2) {
            update(iheap * 2, val, i, left, (left + right) / 2);
        }else {
            update(iheap * 2 + 1, val, i, (left + right) / 2, right);
        }
    }

    int find(int s, int t) {
        int iheap = 1;
        return find(s, t+1, 0, n, iheap);
    }
    private int find(int s, int t, int left, int right, int iheap) {
        if (s >= t) {
            return Integer.MAX_VALUE;
        }
        if (left == s && right == t) {
            return heap[iheap];
        }

        int mid = (left + right) / 2;

        return Math.min(
                find(Math.max(s, left), Math.min(t, mid), left, mid, iheap * 2),
                find(Math.max(s, mid), Math.min(t, right), mid, right, iheap * 2 + 1)
        );
    }

}

