import java.io.OutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.Scanner;

/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        Scanner in = new Scanner(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        AizuRangeMinimumQuery solver = new AizuRangeMinimumQuery();
        solver.solve(1, in, out);
        out.close();
    }

    static class AizuRangeMinimumQuery {
        public void solve(int testNumber, Scanner in, PrintWriter out) {
            int n = in.nextInt();
            int q = in.nextInt();
            int[] a = new int[n];
            int[] b = new int[4 * n];
            for (int i = 0; i < n; i++) {
                a[i] = Integer.MAX_VALUE;
            }

            build(0, 0, n - 1, a, b);
            while (q-- != 0) {
                int o = in.nextInt();
                int l = in.nextInt();
                int r = in.nextInt();

                if (o == 0) {
                    update(0, 0, n - 1, l, r, a, b);
                } else {
                    out.printf("%d\n", query(0, 0, n - 1, l, r, b));
                }
            }
        }

        private void build(int n, int s, int e, int[] a, int[] b) {
            if (s == e) {
                b[n] = a[s];
            } else {
                int m = (s + e) / 2;
                build(2 * n + 1, s, m, a, b);
                build(2 * n + 2, m + 1, e, a, b);

                b[n] = Math.min(b[2 * n + 1], b[2 * n + 2]);
            }
        }

        private void update(int n, int s, int e, int idx, int val, int[] a, int[] b) {
            if (s == e) {
                a[idx] = val;
                b[n] = val;
            } else {
                int m = (s + e) / 2;
                if (s <= idx && idx <= m) {
                    update(2 * n + 1, s, m, idx, val, a, b);
                } else {
                    update(2 * n + 2, m + 1, e, idx, val, a, b);
                }

                b[n] = Math.min(b[2 * n + 1], b[2 * n + 2]);
            }
        }

        private int query(int n, int s, int e, int l, int r, int[] b) {
            if (r < s || e < l) {
                return Integer.MAX_VALUE;
            } else if (l <= s && e <= r) {
                return b[n];
            } else {
                int m = (s + e) / 2;
                int m1 = query(2 * n + 1, s, m, l, r, b);
                int m2 = query(2 * n + 2, m + 1, e, l, r, b);

                return Math.min(m1, m2);
            }
        }

    }
}

import java.util.Scanner;

class Node{
	int Hcover;
	int Lcover; 
	int min;
	Node parent;
	Node left;
	Node right;
	public Node(){
		parent=null;
		left=null;
		right=null;
	}

	public Node(int l,int h,int m){
		Hcover=h;
		Lcover=l;
		min=m;
		parent=null;
		left=null;
		right=null;
	}

	public boolean between(int a){
		return (Lcover<=a)&&(a<=Hcover);
	}
}

public class Main {
	static Node table[]=new Node[100001];

	public static Node cousei(Node n,int l,int h,int m){
		Node mob=new Node(h,l,m);
		mob.parent=n;
		if(h>l){
			mob.left=cousei(mob,l, (h+l)/2, m);
			mob.right=cousei(mob,(h+l)/2+1, h, m);
		}
		if(h==l) table[h]=mob;
		return mob;
	}

	public static int find(Node n,int l,int h){
		//System.out.println("f:"+n.Lcover+"to"+n.Hcover+":"+n.min+"::"+l+"to"+h);
		if(n.Lcover==l&&n.Hcover==h)return n.min;

		if(n.left.between(l)&&n.left.between(h)){
			return find(n.left, l, h);
		}else if(n.right.between(l)&&n.right.between(h)){
			return find(n.right, l, h);
		}else{
			return Math.min(find(n.left, l, n.left.Hcover), find(n.right, n.right.Lcover,h));
		}
	}

	public static void update(Node n,int p,int x,int bef){
		for(Node it=n;it!=null;it=it.parent){
				it.min=Math.min(it.left.min, it.right.min);
		}
	}
	public static void prin(Node n){
		//System.out.println(n.Lcover+"to"+n.Hcover+":"+n.min);
		if(n.Hcover==n.Lcover)return;
		prin(n.left);
		prin(n.right);
	}

	public static void main(String[] args) {
		Node root=new Node();
		int n;
		int q;
		Scanner stdin=new Scanner(System.in);
		n=stdin.nextInt();
		q=stdin.nextInt();
		root.min=(1<<31)-1;
		root.Hcover=n;
		root.Lcover=1;
		root.parent=null;
		root.left=cousei(root,1,(n+1)/2,root.min);
		root.right=cousei(root,(n+1)/2+1,n,root.min);
		for(int XXX=0;XXX<q;XXX++){
			int com=stdin.nextInt();
			int x=stdin.nextInt();
			int y=stdin.nextInt();
			x++;
			if(com==0){
				// update
				int m=table[x].min;
				table[x].min=y;
				update(table[x].parent, x, y,m);
				prin(root);
			}else{
				// find
				y++;
				System.out.println(find(root, x, y));
			}
		}
		stdin.close();
	}

}

