    static void find(int s, int t){
        int min = Integer.MAX_VALUE;
        if (s/1000 == t/1000 || s/1000 + 1 == t/1000){
            for (int i = s; i < t + 1; i++){
                if (A[i] < min){
                    min = A[i];
                }
            }            
            System.out.println(min);
        }else{
            //left range
            for (int i = s; i < (s/1000 +1)*1000; i++){
                if (A[i] < min){
                    min = A[i];
                }
            }

            for (int j = s/1000 + 1; j < t/1000; j++){
                if (B[j] < min){
                    min = B[j];
                }
            }   
            //right range
            for (int i = (t/1000) * 1000; i < t + 1; i++){
                if (A[i] < min){
                    min = A[i];
                }
            }
            System.out.println(min);
