class RMQ{

	int n;

	int[] dat;


	RMQ(int[] val){

		int size=val.length;
		n=1;

		//元の配列のサイズ以上になる最小の2のべき乗をnとすると
		//セグメント木の大きさは2n-1である。
		while(n<size) {
			n *=2;
		}

		init();

		//セグメント木の最下段に元の配列の値を入れておく。
		for(int i=0;i<size;i++) {
			dat[i+n-1]=val[i];
		}

		//最下段から子を比べて親を格納していく。

		for(int i=n-2;i>=0;i--) {
			dat[i]=Math.min(dat[2*i+1],dat[2*i+2]);
		}

	}






	void init() {

		dat=new int[2*n-1];

		for(int i=0;i<2*n-1;i++) {
			dat[i]=Integer.MAX_VALUE;
		}

	}

	void update(int i,int val) {

		//葉のノード番号
		i+=n-1;
		dat[i]=val;

		//登りながら更新
		while(i>0) {

			//子から親を求めるには-1して/2
			//切り捨てられて、左からでも右からでも同じ値になる。
			i=(i-1)/2;

			//親は左右の子のうち、小さい値を持っている。
			dat[i]=Math.min(dat[i*2+1],dat[i*2+2]);
		}

	}

	//[a,b)クエリで求められる区間の端。
	//k自分が今いるノードのインデックス
	//今みてる区間[l,r)

	//呼び出す時はquery(a,b,0,0,n)とする。

	int query(int a,int b,int k,int l,int r) {

		if(r<0) {
			r=n;
		}

		if(r<=a||b<=l)return Integer.MAX_VALUE;//交差しない?
		if(a<=l && r<=b) return dat[k];		  //完全に含む?

			int vl=query(a,b,k*2+1,l,(l+r)/2);
			int vr=query(a,b,k*2+2,(l+r)/2,r);

			return Math.min(vl,vr);

	}



}

import java.util.Arrays;
import java.util.Scanner;

public class Main {

    public static class SegmentTree {

        int[] tree;
        int n, rawLen;

        public SegmentTree(int rawLen) {
            n = 1;
            while (n < rawLen) {
                n <<= 1;
            }
            tree = new int[2 * n - 1];
            this.rawLen = rawLen;
            Arrays.fill(tree, Integer.MAX_VALUE);
        }

        public int query(int left, int right) {
            return query(0, 0, n - 1, left, right);
        }

        public void update(int idx, int newValue) {
            idx += n - 1;
            tree[idx] = newValue;
            while (idx > 0) {
                idx = (idx - 1) / 2;
                tree[idx] = Math.min(tree[idx * 2 + 1], tree[idx * 2 + 2]);
            }
        }

        /**
         * Invariant: rangeBegin <= left <= right <= rangeEnd
         */
        private int query(int idx, int rangeBegin, int rangeEnd, int left, int right) {
            int leftResult = Integer.MAX_VALUE;
            int rightResult = Integer.MAX_VALUE;
            if (rangeBegin == rangeEnd) {
                return tree[idx];
            }
            int rangeMid = (rangeBegin + rangeEnd) / 2;
            if (left <= rangeMid) {
                leftResult = query(idx * 2 + 1, rangeBegin, rangeMid, left, Math.min(right, rangeMid));
            }
            if (rangeMid + 1 <= right) {
                rightResult = query(idx * 2 + 2, rangeMid + 1, rangeEnd, Math.max(left, rangeMid + 1), right);
            }

            return Math.min(leftResult, rightResult);

        }

    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        SegmentTree segTree = new SegmentTree(n);
        int q = scanner.nextInt();
        while (q-- > 0) {
            int cmd = scanner.nextInt();
            int x = scanner.nextInt();
            int y = scanner.nextInt();

            if (cmd == 0) { // update
                segTree.update(x, y);
            } else { // query
                System.out.println(segTree.query(x, y));
            }
        }
    }
}

