    public static void main(String[] args) {
        FastScanner sc = new FastScanner(System.in);
        N = sc.nextInt();
        Q = sc.nextInt();

        C = new int[Q];
        X = new int[Q];
        Y = new int[Q];
        for (int i = 0; i < Q; i++) {
            C[i] = sc.nextInt();
            X[i] = sc.nextInt();
            Y[i] = sc.nextInt();
        }

