    // returns (x, y, d) s.t. ax + by = d
    static long[] exgcd(long a, long b) {
        int sa = a < 0 ? -1 : 1;
        int sb = b < 0 ? -1 : 1;
        a *= sa;
        b *= sb;
        long x = 1;
        long y = 0;
        long z = 0;
        long w = 1;
        while (b > 0) {
            long q = a / b;
            long t = z;
            z = x - q * z;
            x = t;
            t = w;
            w = y - q * w;
            y = t;
            t = b;
            b = a - q * b;
            a = t;
        }
        return new long[] { x * sa, y * sb, a };
    }
 
    static int[] lis(int[] s) {
        int n = s.length;
        int[] dp = new int[n];
        int[] ids = new int[n];
        int[] pids = new int[n];
        dp[0] = s[0];
        int len = 1;
        int lidx = 0;
        for (int i = 1; i < n; i++) {
            int idx = bs(s[i], dp, 0, len);
            dp[idx] = s[i];
            ids[idx] = i;
            if (idx == len) {
                lidx = i;
                len++;
            }
            if (idx > 0)
                pids[i] = ids[idx - 1];
        }
        int[] lis = new int[len];
        lis[len - 1] = s[lidx];
        for (int i = len - 1; i >= 0; i--) {
            lis[i] = s[lidx];
            lidx = pids[lidx];
        }
        return lis;
    }
 
    static int bs(int a, int[] as, int from, int num) {
        int min = from;
        int max = from + num - 1;
        while (min < max) {
            int mid = min + max >> 1;
            if (as[mid] < a)
                min = mid + 1;
            else if (as[mid] > a)
                max = mid;
            else
                return mid;
        }
        return as[min] < a ? min + 1 : min;
    }
 
    static int gcd(int x, int y) {
        x = (x ^ x >> 31) - (x >> 31);
        y = (y ^ y >> 31) - (y >> 31);
        if (x < y) {
            x ^= y;
            y ^= x;
            x ^= y;
        }
        int z = x % y;
        if (z == 0)
            return y;
        return gcd(y, z);
    }
 
    static long gcd(long x, long y) {
        x = (x ^ x >> 63) - (x >> 63);
        y = (y ^ y >> 63) - (y >> 63);
        if (x < y) {
            x ^= y;
            y ^= x;
            x ^= y;
        }
        long z = x % y;
        if (z == 0)
            return y;
        return gcd(y, z);
    }
 
    static long modinv(long a, long mod) {
        return modpow(a, mod - 2, mod);
    }
 
    static long modpow(long a, long b, long mod) {
        if (b == 0)
            return 1;
        if ((b & 1) == 0) {
            long sqrt = modpow(a, b >> 1, mod);
            return sqrt * sqrt % mod;
        }
        return a * modpow(a, b - 1, mod) % mod;
    }
 
    static long fact(long n) {
        if (n <= 1)
            return 1;
        long res = 2;
        for (long i = 3; i <= n; i++) {
            res *= i;
        }
        return res;
    }
 
    static long modfact(long n, long mod) {
        if (n <= 1)
            return 1 % mod;
        long res = 2;
        for (long i = 3; i <= n; i++) {
            res *= i;
            res %= mod;
        }
        return res % mod;
    }
 
    // returns facts([0]) and invfacts([1])
    static long[][] enumfacts(int n, long mod) {
        int num = n + 10;
        long[][] res = new long[2][num];
        long[] facts = res[0];
        long[] invfacts = res[1];
        for (int i = 0; i < num; i++) {
            if (i <= 1) {
                facts[i] = 1;
                invfacts[i] = 1;
            } else {
                facts[i] = facts[i - 1] * i % mod;
                invfacts[i] = modinv(facts[i], mod);
            }
        }
        return res;
    }
 
    static long modcomb(long n, long m, long mod) {
        if (m > n)
            return 0;
        if (m > n - m) {
            m = n - m;
        }
        long numer = 1;
        for (int i = 0; i < m; i++) {
            numer = numer * (n - i) % mod;
        }
        long denom = modfact(m, mod);
        return numer * modinv(denom, mod) % mod;
    }
 
    static long modcomb(int n, int m, long[] facts, long[] invfacts, long mod) {
        if (m > n)
            return 0;
        long numer = facts[n];
        long denom = invfacts[m] * invfacts[n - m] % mod;
        return numer * denom % mod;
    }
 
    // res[i][0]: prime factor, res[i][1]: exponent
    static int[][] factorize(int n) {
        int[][] pfs = new int[32][2];
        int num = 0;
        for (int i = 2; i * i <= n; i++) {
            int count = 0;
            while (n % i == 0) {
                n /= i;
                count++;
            }
            if (count > 0) {
                pfs[num][0] = i;
                pfs[num][1] = count;
                num++;
            }
        }
        if (n > 1) {
            pfs[num][0] = n;
            pfs[num][1] = 1;
            num++;
        }
        int[][] res = new int[num][2];
        for (int i = 0; i < num; i++) {
            res[i][0] = pfs[i][0];
            res[i][1] = pfs[i][1];
        }
        return res;
    }
 
