import java.util.*;
public class Main{
	public static final long INF = (long)Math.pow(2,31) - 1L;
	public static boolean check(int n){
		if(n == 1)
			return true;
		else if(n % 2 != 0)
			return false;
		else
			return check(n / 2);
	}
	public static void update(long rmq[], int i, int x, int n){
		i += (n - 1);
		rmq[i] = x;
		if(i == 0)
			return;
		i = (i-1) / 2;
		while(i >= 0){
			long tmp = Math.min(rmq[2*i + 1],rmq[2*i + 2]);
			if(tmp == rmq[i])
				break;
			else{
				rmq[i] = tmp;
				i = (i-1) / 2;
			}
		}
	}
	public static long find(long rmq[], int s, int t, int left, int right, int i){
		if(right <= s || left > t)
			return INF;
		else if(left >= s && right <= t+1)
			return rmq[i];
		else{
			return Math.min(find(rmq,s,t,left,(left+right)/2, 2*i+1),find(rmq,s,t,(left+right)/2,right,2*i+2));
		}
	}
	public static void main(String[] args){
		Scanner sc = new Scanner(System.in);
		int n = sc.nextInt();
		int n_ = n;
		while(!check(n_))
			n_++;
		int q = sc.nextInt();
		long rmq[] = new long[2*n_ - 1];
		for(int i = 0 ; i < 2*n_ - 1 ; i++)
			rmq[i] = INF;
		for(int i = 0 ;i < q ; i++){
			int com = sc.nextInt();
			int x = sc.nextInt();
			int y = sc.nextInt();
			switch(com){
				case 0: update(rmq,x,y,n_); break;
				case 1: System.out.println(find(rmq,x,y,0,n_,0)); break;
			}
		}
	}
}

import java.util.Scanner;

/**
 * http://judge.u-aizu.ac.jp/onlinejudge/description.jsp?id=DSL_2_A
 */
public class Main {

    public static class SegmentTree {

        int[] tree;
        int[] raw;
        int rawLen;

        public SegmentTree(int[] arr) {
            int len = Integer.highestOneBit(arr.length) << 2;
            tree = new int[len];
            raw = arr;
            rawLen = raw.length;
            initTree(1, 0, arr.length - 1);
        }

        /**
         * @param idx of tree[]
         * @param rangeBegin of raw[]
         * @param rangeEnd of raw[]
         */
        private void initTree(int idx, int rangeBegin, int rangeEnd) {
            if (rangeBegin == rangeEnd) {
                tree[idx] = raw[rangeBegin];
            } else {
                initTree(idx * 2, rangeBegin, (rangeEnd + rangeBegin) / 2);
                initTree(idx * 2 + 1, (rangeEnd + rangeBegin) / 2 + 1, rangeEnd);
                tree[idx] = tree[idx * 2] < tree[idx * 2 + 1] ? tree[idx * 2] : tree[idx * 2 + 1];
            }
        }

        public int query(int left, int right) {
            return query(1, 0, rawLen - 1, left, right);
        }

        public void update(int idx, int newValue) {
            update(idx, newValue, 1, 0, rawLen - 1);
        }

        /**
         * Invariant: rangeBegin <= left <= right <= rangeEnd
         */
        private int query(int idx, int rangeBegin, int rangeEnd, int left, int right) {
            Integer leftResult = null;
            Integer rightResult = null;
            if (rangeBegin == rangeEnd) {
                return tree[idx];
            }
            int rangeMid = (rangeBegin + rangeEnd) / 2;
            if (left <= rangeMid) {
                leftResult = query(idx * 2, rangeBegin, rangeMid, left, Math.min(right, rangeMid));
            }
            if (rangeMid + 1 <= right) {
                rightResult = query(idx * 2 + 1, rangeMid + 1, rangeEnd, Math.max(left, rangeMid + 1), right);
            }
            if (leftResult == null) {
                return rightResult;
            } else if (rightResult == null) {
                return leftResult;
            } else {
                return Math.min(leftResult, rightResult);
            }
        }

        private void update(int idxToUpdate, int newValue, int idx, int rangeBegin, int rangeEnd) {
            if (rangeBegin == rangeEnd) {
                tree[idx] = newValue;
            } else {
                int rangeMid = (rangeBegin + rangeEnd) / 2;
                if (idxToUpdate > rangeMid) {
                    update(idxToUpdate, newValue, idx * 2 + 1, rangeMid + 1, rangeEnd);
                } else {
                    update(idxToUpdate, newValue, idx * 2, rangeBegin, rangeMid);
                }
                tree[idx] = tree[idx * 2] < tree[idx * 2 + 1] ? tree[idx * 2] : tree[idx * 2 + 1];
            }
        }

    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int[] arr = new int[n];
        for (int i = 0; i < n; i++) {
            arr[i] = Integer.MAX_VALUE;
        }
        SegmentTree segTree = new SegmentTree(arr);
        int q = scanner.nextInt();
        while (q-- > 0) {
            if (scanner.nextInt() == 0) { // update
                int idx = scanner.nextInt();
                int value = scanner.nextInt();
                segTree.update(idx, value);
            } else { // query
                int l = scanner.nextInt();
                int r = scanner.nextInt();
                System.out.println(segTree.query(l, r));
            }
        }
    }
}

