static long seg_INF=1<<31-1;

public static void seg_init(int n){
 MAX_ELE=1;
 while(MAX_ELE<n) MAX_ELE<<=1;
 seg=new long[2*MAX_ELE-1];
 Arrays.fill(seg,seg_INF);
}

public static void update(int k,long val){
 k+=MAX_ELE-1;
 seg[k]=val;
 while(k>0){
  k--;
  k>>=1;
  seg[k]=Math.min(seg[k<<1+1],seg[k<<2+2]);
 }
}

