}

public static long _query(int a,int b,int k,int l,int l){
 if(a>=r||b<=l) return seg_INF;
 if(a<=l&&b>=r) return seg[k];
 long cl=_query(a,b,k<<1+1,l,(l+r)>>1);
 long cr=_query(a,b,k<<1+2,(l+r)>>1,r);
 return Math.min(cl,cr);
}

