 seg=new int[MAX_ELE<<1-1];
 Arrays.fill(seg,Integer.MAX_VALUE);
}

public static void update(int k,int val){
 k+=MAX_ELE-1;
 seg[k]=val;
 while(k>0){
  k--; k>>=1;
