}

public static int _query(int a,int b,int k,int l,int r){
 if(a<=l&&b>=r) return seg[k];
 if(a>=r||b<=l) return Integer.MAX_VALUE;
 int cl=_query(a,b,k<<1+1,l,(l+r)>>1);
 int cr=_query(a,b,k<<1+2,(l+r)>>1,r);
 return Math.min(cl,cr);
}

