        for (int i = 0; i < MAX_ELE * 2 - 1; i++) {
            seg[i] = Integer.MAX_VALUE;
        }
    }

public static void update(int k,int val){
 k+=MAX_ELE-1;
 seg[k]=val;
 while(k>0){
  k--; k>>=1;
  seg[k]=Math.min(seg[k<<1+1],seg[k<<1+2]);
 }
}

public static int query(int a,int b){
 return _query(a,b,0,0,MAX_ELE);
}

public static int _query(int a,int b,int k,int l,int r){
 if(a<=l&&b>=r) return seg[k];
 if(a>=r||b<=l) return Integer.MAX_VALUE;
 int cl=_query(a,b,k<<1+1,l,(l+r)>>1);
 int cr=_query(a,b,k<<1+2,(l+r)>>1,r);
 return Math.min(cl,cr);
}

