//Unordered Pair
class UP<A, B> {
    A a;
    B b;

    UP(A a, B b) {
        this.a = a;
        this.b = b;
    }

    static <A, B> UP<A, B> make(A a, B b) {
        return new UP<A, B>(a, b);
    }

    public UP<A, B> clone() {
        return make(a, b);
    }

    public boolean equals(Object o) {
        if (o == this)
            return true;
        if (!(o instanceof UP))
            return false;
        UP<?, ?> p = (UP<?, ?>) o;
        boolean aok = a == null ? p.a == null : a.equals(p.a);
        boolean bok = b == null ? p.b == null : b.equals(p.b);
        return aok && bok;
    }

    public String toString() {
        return "(" + a.toString() + ", " + b.toString() + ")";
    }
}

interface F1<A> {
    A f();
}

interface F2<A, B> {
    B f(A a);
}

interface F3<A, B, C> {
    C f(A a, B b);
}

interface F4<A, B, C, D> {
    D f(A a, B b, C c);
}

// util
class U {
    static <A> ArrayList<A> make(int n, F2<Integer, A> maker) {
        ArrayList<A> res = new ArrayList<A>();
        for (int i = 0; i < n; i++) {
            res.add(maker.f(i));
        }
        return res;
    }

    static <A> ArrayList<A> filter(ArrayList<A> as, F2<A, Boolean> pred) {
        ArrayList<A> res = new ArrayList<A>();
        for (A a : as) {
            if (pred.f(a))
                res.add(a);
        }
        return res;
    }

    static <A> ArrayList<A> map(ArrayList<A> as, F2<A, A> f) {
        return make(as.size(), (i) -> f.f(as.get(i)));
    }

    static <A, B> ArrayList<UP<A, B>> zip(ArrayList<A> as, ArrayList<B> bs) {
        return make(min(as.size(), bs.size()), (i) -> UP.make(as.get(i), bs.get(i)));
    }

    static <A extends Comparable<A>> A min(A a, A b) {
        return a.compareTo(b) < 0 ? a : b;
    }

    static <A extends Comparable<A>> A max(A a, A b) {
        return a.compareTo(b) > 0 ? a : b;
    }

    static <A extends Comparable<A>> A clamp(A a, A min, A max) {
        return a.compareTo(min) < 0 ? min : a.compareTo(max) > 0 ? max : a;
    }
}

//Segment Tree
class ST<A> {
	// 0: unused, 1: root
	private ArrayList<A> dat;
	private int h;
	private int n;
	private F3<A, A, A> merger;
	private A e;

	ST(int num, F3<A, A, A> merger, A e) {
		this.merger = merger;
		this.e = e;
		h = 0;
		while ((1 << h) < num)
			h++;
		n = 1 << h;
		int size = 2 * n;
		dat = U.make(size, i -> e);
	}

	void init(A[] as) {
		for (int i = 0; i < n; i++) {
			this.dat.set(n + i, i < as.length ? as[i] : e);
		}
		for (int i = n - 1; i > 0; i--) {
			dat.set(i, merge(dat.get(i << 1), dat.get(i << 1 | 1)));
		}
	}

	A get(int i) {
		return query(i, i + 1);
	}

	void set(int i, A a) {
		i += n;
		dat.set(i, a);
		while ((i >>= 1) > 0) {
			dat.set(i, merge(dat.get(i << 1), dat.get(i << 1 | 1)));
		}
	}

	A query(int from, int until) {
		int l = from + n;
		int r = until + n;
		A res = e;
		while (l < r) {
			if ((r & 1) != 0) {
				res = merge(res, dat.get(--r));
			}
			if ((l & 1) != 0) {
				res = merge(res, dat.get(l++));
			}
		}
		return res;
	}

	private A merge(A a, A b) {
		return a == e ? b : b == e ? a : merger.f(a, b);
	}
}

