            A[j] = Integer.MAX_VALUE;
        }
        for (int j = 0; j < 100; j++){
            B[j] = Integer.MAX_VALUE;
        }
        for (int i = 0; i < q; i++){
            String[] ln = br.readLine().split(" ");
            int com = Integer.parseInt(ln[0]);
            int x = Integer.parseInt(ln[1]);
            int y = Integer.parseInt(ln[2]);
            if (com == 0){
                update(x,y);
            }else{
                System.out.println(find(x,y));
            }
        }
    }
