class RangeMinQuery{
    int height;
    int tree[];
    RangeMinQuery(int size){
        for(height = 0; 1 << height < size; height++);
        tree = new int[1 << (height + 1)];
        for(int i = 0; i < tree.length; i++) tree[i] = (1 << 31) - 1;
        //System.out.println("height: " + height);
    }

    private int sibling(int i){
        if(i == 0) throw new IllegalArgumentException("RangeMinQuery.sibling(0)");
        return ((i - 1) ^ 1) + 1;
    }

    void update(int i, int x){
        i += (1 << height) - 1;
        tree[i] = x;
        for(; i != 0; i = (i - 1) / 2){
            int min = Math.min(tree[i], tree[sibling(i)]);
            if(min == tree[(i - 1) / 2]) break;
            tree[(i - 1) / 2] = min;
        }
        //dump();
    }

    int rangemin(int from, int to){
        if(!(0 <= from && from <= to && to < (1 << height)))
            throw new IllegalArgumentException("from < to");
        int depth = height, size = (to - from) + 1;
        from += (1 << height) - 1;
        int r = tree[from];
        while(0 < size){
            for(; from % 2 == 1 && 2 << (height - depth) <= size; depth--, from /= 2);
            for(; size < 1 << (height - depth); depth++, from = from * 2 + 1);
            r = Math.min(r, tree[from]);
            from++;
            size -= 1 << (height - depth);
        }
        return r;
    }

    void dump(){
        int subarr[];
        for(int i = 0; i <= height; i++){
            subarr = Arrays.copyOfRange(tree, (1 << i) - 1, (1 << i + 1) - 1);
            System.out.println(Arrays.toString(subarr));
        }
    }
}

import java.util.Scanner;

public class Main
{
    //RMQ in aizu
    //refernece https://blog.csdn.net/u013174702/article/details/44161821
    //size 4*maxn
    static int maxN = 100005;
    static int size = 4*maxN;//segment tree
    static int tree[] = new int[size];//start from 0
    public static void main(String[] args) {
        int n,q;
        Scanner in = new Scanner(System.in);
        n = in.nextInt();
        q = in.nextInt();
        int N = 1;
        while(N<n){
            N = N<<1;
        }
        //init tree
        //System.out.println(N);
        for(int i = 0; i<size; i++) tree[i] = 0x7fffffff;
        //System.out.println(tree[0]);
        //the number of max leaf
        if(N==1) N = 2;
        for(int i = 0; i<q; i++){

            int num1 = in.nextInt();
            int a = in.nextInt();
            int b = in.nextInt();
            if(num1==0){
                update(a,a,0,N-1,b,0);
            }else if(num1==1){
                int res = query(a,b,0,N-1,0);
                System.out.println(res);
            }

        }

    }

    private static int query(int L, int R, int l, int r, int node) {
        if(l>R || r<L) return 0x7fffffff;//or mid
        if(l>=L && r<=R){
            return tree[node];
        }
        int p = query(L,R,l,(l+r)/2,node*2+1);
        int q = query(L,R,(l+r)/2+1,r,node*2+2);

        return Math.min(p,q);
    }

    //node stores min value
    //node correspond to l and r
    private static void update(int L, int R, int l, int r, int val,int node) {
        if(l>R || r<L) return;//or mid
        if(l>=L && r<=R){
            tree[node] = val;
            return;
        }
        int mid = (l+r)/2;
        //System.out.println(node+" "+l+" "+r);
        update(L,R,l,mid,val,node*2+1);
        update(L,R,mid+1,r,val,node*2+2);
        //push up
        if(tree[node*2+1]<tree[node*2+2]) tree[node] = tree[node*2+1];
        else tree[node] = tree[node*2+2];
    }
}

