public class Main {
    static int[] nodes;
    static int size;
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int n = in.nextInt();
        int q = in.nextInt();
        init(n);
        for (int i = 0; i < q; i++) {
            if (in.nextInt() == 0) {
                update(in.nextInt(), in.nextInt());
            } else {
                System.out.println(find(in.nextInt(), in.nextInt()));
            }
        }
    }
    static void init(int n) {
     size=1;
     while (size<n)
         size*=2;
     nodes = new int[size*2-1];
     for (int i=0;i<nodes.length;i++) {
         nodes[i] = Integer.MAX_VALUE;
     }
 }
 static void update(int target, int value) {
     int up = size-1 + target;
     nodes[up] = value;
     if (up==0) return;
     up = (up-1)/2;
     while (true) {
         nodes[up] = Math.min(nodes[up*2+1], nodes[up*2+2]);
         if (up==0)
             break;
         up = (up-1)/2;
     }
 }
 static int find(int s, int t) {
     return _find(s, t, 0, 0, size-1);
 }
 static int _find(int s, int t, int node, int node_s, int node_t) {
     if (t<node_s||s>node_t)
         return Integer.MAX_VALUE;
     if (s<=node_s&&node_t<=t)
         return nodes[node];
     int cl = _find(s, t, node*2+1, node_s, (node_s+node_t)/2);
     int rl = _find(s, t, node*2+2, (node_s+node_t)/2+1, node_t);
     return Math.min(cl, rl);
 }
}

package com.tzj;

import java.util.Scanner;
import java.io.PrintWriter;

public class AizuRangeMinimumQuery {
    public void solve(int testNumber, Scanner in, PrintWriter out) {
        int n = in.nextInt();
        int q = in.nextInt();
        int[] a = new int[n];
        int[] b = new int[4*n];
        for (int i = 0; i < n; i++) {
            a[i] = Integer.MAX_VALUE;
        }

        build(0, 0, n-1, a, b);
        while (q-- != 0) {
            int o = in.nextInt();
            int l = in.nextInt();
            int r = in.nextInt();

            if (o == 0) {
                update(0, 0, n-1, l, r, a, b);
            } else {
                out.printf("%d\n", query(0, 0, n-1, l, r, b));
            }
        }
    }

    private void build(int n, int s, int e, int[] a, int[] b) {
        if (s == e) {
            b[n] = a[s];
        } else {
            int m = (s + e) / 2;
            build(2 * n + 1, s, m, a, b);
            build(2 * n + 2, m + 1, e, a, b);

            b[n] = Math.min(b[2 * n + 1], b[2 * n + 2]);
        }
    }

    private void update(int n, int s, int e, int idx, int val, int[] a, int[] b) {
        if (s == e) {
            a[idx] = val;
            b[n] = val;
        } else {
            int m = (s + e) / 2;
            if (s <= idx && idx <= m) {
                update(2 * n + 1, s, m, idx, val, a, b);
            } else {
                update(2 * n + 2, m + 1, e, idx, val, a, b);
            }

            b[n] = Math.min(b[2 * n + 1], b[2 * n + 2]);
        }
    }

    private int query(int n, int s, int e, int l, int r, int[] b) {
        if (r < s || e < l) {
            return Integer.MAX_VALUE;
        } else if (l <= s && e <= r) {
            return b[n];
        } else {
            int m = (s + e) / 2;
            int m1 = query(2 * n + 1, s, m, l, r, b);
            int m2 = query(2 * n + 2, m + 1, e, l, r, b);

            return Math.min(m1, m2);
        }
    }
}

