import java.util.Scanner;
import java.util.ArrayList;

class RMQ {
	ArrayList<Integer> node;
	int defval;
	int N;
	int n;

	public int func(int a, int b) {
		return Math.min(a, b);
	}
	public void init(int n, int defval) {
		node = new ArrayList<>();
		N = 1;
		while (N < n)N *= 2;
		this.n = n;
		this.defval = defval;
		for (int i = 0; i < N * 2 - 1; i++)
			node.add(defval);
	}
	public int query(int a, int b, int l, int r, int i) {
		if (r == -1) r = N;
		if (b <= l || r <= a) return defval;
		if (a <= l && r <= b) return node.get(i);
		return func(query(a, b, l, (l + r) / 2, i * 2 + 1), query(a, b, (l + r) / 2, r, i * 2 + 2));
	}
	public void update(int p, int v) {
		int q = p + N - 1;
		node.set(q, v);
		while (q != 0) {
			q = (q - 1) / 2;
			node.set(q, func(node.get(q * 2 + 1), node.get(q * 2 + 2)));
		}
	}
	public int get(int p) { return node.get(p + N - 1); }
};


public class Main{
	public static void main(String[] args){
		RMQ t; t = new RMQ();
		Scanner sc = new Scanner(System.in);
		int n = Integer.parseInt(sc.next());
		int q = Integer.parseInt(sc.next());
		ArrayList<Integer> ans = new ArrayList<>();
		t.init(n, 0x7fffffff);
		for(int i = 0; i < q; i ++){
			int c = Integer.parseInt(sc.next());
			int x = Integer.parseInt(sc.next());
			int y = Integer.parseInt(sc.next());
			if (c == 0) {
				t.update(x, y);
			}
			 else {
				ans.add(t.query(x, y + 1, 0, -1, 0));
			}
		}
		for (int i = 0; i < ans.size(); i++)
		    System.out.println(ans.get(i));
	}
}

import java.util.Scanner;


public class Main {

    public static class SegmentTree {

        int[] tree;
        int rawLen;

        public SegmentTree(int[] arr) {
            int len = Integer.highestOneBit(arr.length) << 2;
            tree = new int[len];
            rawLen = arr.length;
            initTree(arr, 1, 0, arr.length - 1);
        }

        /**
         * @param idx of tree[]
         * @param rangeBegin of raw[]
         * @param rangeEnd of raw[]
         */
        private void initTree(int[] raw, int idx, int rangeBegin, int rangeEnd) {
            if (rangeBegin == rangeEnd) {
                tree[idx] = raw[rangeBegin];
            } else {
                initTree(raw, idx * 2, rangeBegin, (rangeEnd + rangeBegin) / 2);
                initTree(raw, idx * 2 + 1, (rangeEnd + rangeBegin) / 2 + 1, rangeEnd);
                tree[idx] = tree[idx * 2] < tree[idx * 2 + 1] ? tree[idx * 2] : tree[idx * 2 + 1];
            }
        }

        public int query(int left, int right) {
            return query(1, 0, rawLen - 1, left, right);
        }

        public void update(int idx, int newValue) {
            update(idx, newValue, 1, 0, rawLen - 1);
        }

        /**
         * Invariant: rangeBegin <= left <= right <= rangeEnd
         */
        private int query(int idx, int rangeBegin, int rangeEnd, int left, int right) {
            Integer leftResult = null;
            Integer rightResult = null;
            if (rangeBegin == rangeEnd) {
                return tree[idx];
            }
            int rangeMid = (rangeBegin + rangeEnd) / 2;
            if (left <= rangeMid) {
                leftResult = query(idx * 2, rangeBegin, rangeMid, left, Math.min(right, rangeMid));
            }
            if (rangeMid + 1 <= right) {
                rightResult = query(idx * 2 + 1, rangeMid + 1, rangeEnd, Math.max(left, rangeMid + 1), right);
            }
            if (leftResult == null) {
                return rightResult;
            } else if (rightResult == null) {
                return leftResult;
            } else {
                return Math.min(leftResult, rightResult);
            }
        }

        private void update(int idxToUpdate, int newValue, int idx, int rangeBegin, int rangeEnd) {
            if (rangeBegin == rangeEnd) {
                tree[idx] = newValue;
            } else {
                int rangeMid = (rangeBegin + rangeEnd) / 2;
                if (idxToUpdate > rangeMid) {
                    update(idxToUpdate, newValue, idx * 2 + 1, rangeMid + 1, rangeEnd);
                } else {
                    update(idxToUpdate, newValue, idx * 2, rangeBegin, rangeMid);
                }
                tree[idx] = tree[idx * 2] < tree[idx * 2 + 1] ? tree[idx * 2] : tree[idx * 2 + 1];
            }
        }

    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int[] arr = new int[n];
        for (int i = 0; i < n; i++) {
            arr[i] = Integer.MAX_VALUE;
        }
        SegmentTree segTree = new SegmentTree(arr);
        int q = scanner.nextInt();
        while (q-- > 0) {
            if (scanner.nextInt() == 0) { // update
                int idx = scanner.nextInt();
                int value = scanner.nextInt();
                segTree.update(idx, value);
            } else { // query
                int l = scanner.nextInt();
                int r = scanner.nextInt();
                System.out.println(segTree.query(l, r));
            }
        }
    }
}

