interface F1<A> {
	A f();
}

interface F2<A, B> {
	B f(A a);
}

interface F3<A, B, C> {
	C f(A a, B b);
}

interface F4<A, B, C, D> {
	D f(A a, B b, C c);
}

class U {
	static <A> ArrayList<A> make(int n, F2<Integer, A> maker) {
		ArrayList<A> res = new ArrayList<A>();
		for (int i = 0; i < n; i++) {
			res.add(maker.f(i));
		}
		return res;
	}

	static <A> ArrayList<A> filter(ArrayList<A> as, F2<A, Boolean> pred) {
		ArrayList<A> res = new ArrayList<A>();
		for (A a : as) {
			if (pred.f(a))
				res.add(a);
		}
		return res;
	}

	static <A> ArrayList<A> map(ArrayList<A> as, F2<A, A> f) {
		return make(as.size(), (i) -> f.f(as.get(i)));
	}

	static <A extends Comparable<A>> A min(A a, A b) {
		return a.compareTo(b) < 0 ? a : b;
	}

	static <A extends Comparable<A>> A max(A a, A b) {
		return a.compareTo(b) > 0 ? a : b;
	}

	static <A extends Comparable<A>> A clamp(A a, A min, A max) {
		return a.compareTo(min) < 0 ? min : a.compareTo(max) > 0 ? max : a;
	}
}

//Persistent Segment Tree
class PST<A> {
	static int cnt = 0;

	private class N {
		N l;
		N r;
		A a;
		int id;

		N(A a) {
			this.a = a;
			this.id = ++cnt;
		}

		public String toString() {
			return a + "(id=" + id + ",l=" + (l == null ? 0 : l.id) + ",r=" + (r == null ? 0 : r.id) + ")";
		}
	}

	private ArrayList<N> roots;
	private int h;
	private int n;
	private F3<A, A, A> merger;
	private A e;

	PST(int num, F3<A, A, A> merger, A e) {
		this.merger = merger;
		this.e = e;
		h = 0;
		while ((1 << h) < num)
			h++;
		n = 1 << h;

		N root = makeTree(1, i -> e);
		roots = new ArrayList<N>();
		roots.add(root);
	}

	private N makeTree(int k, F2<Integer, A> maker) {
		N node = new N(k >= n ? maker.f(k - n) : e);
		if (k < n) {
			node.l = makeTree(k << 1, maker);
			node.r = makeTree(k << 1 | 1, maker);
		}
		return node;
	}

	int init(A[] vals) {
		N root = makeTree(1, i -> i < vals.length ? vals[i] : e);
		roots.add(root);
		return roots.size() - 1;
	}

	A get(int root, int i) {
		return query(root, i, i + 1);
	}

	int set(int root, int i, A a) {
		N newRoot = set(roots.get(root), 0, n, i, a);
		roots.add(newRoot);
		return roots.size() - 1;
	}

	private N set(N node, int l, int r, int i, A a) {
		if (r - l == 1) {
			return new N(a);
		}
		boolean updateL = i < l + r >> 1;
		N lc = updateL ? set(node.l, l, l + r >> 1, i, a) : node.l;
		N rc = !updateL ? set(node.r, l + r >> 1, r, i, a) : node.r;
		N newNode = new N(merge(lc.a, rc.a));
		newNode.l = lc;
		newNode.r = rc;
		return newNode;
	}

	void dump(int root) {
		dump(roots.get(root), 1);
		System.out.println();
	}

	private void dump(N node, int k) {
		System.out.println(k + " " + node);
		if (node.l != null) {
			dump(node.l, k * 2);
		}
		if (node.r != null) {
			dump(node.r, k * 2 + 1);
		}
	}

	A query(int root, int from, int until) {
		return query(roots.get(root), from, until, 0, n, 1);
	}

	private A query(N node, int a, int b, int l, int r, int k) {
		if (a <= l && b >= r) {
			return node.a;
		}
		if (a >= r || b <= l) {
			return e;
		}
		A al = query(node.l, a, b, l, l + r >> 1, k * 2);
		A ar = query(node.r, a, b, l + r >> 1, r, k * 2 + 1);
		return merge(al, ar);
	}

	private A merge(A a, A b) {
		return a == e ? b : b == e ? a : merger.f(a, b);
	}
}

