class RQ {
	class ELEM {
		int parant;
		int front;
		int behind;
		int value;
	}

	ELEM[] elem;
	int root;
	boolean debug;

	public RQ(int n, boolean d) {
		debug = d;

		elem = new ELEM[n];
		int y = (int) (Math.pow(2, 31) - 1);
		for (int i = 0; i < n; i++) {
			elem[i] = new ELEM();
			elem[i].parant = i - 1;
			elem[i].front = -1;
			elem[i].behind = i + 1;
			elem[i].value = y;
		}
		elem[n - 1].behind = -1;
		root = 0;
	}

	public int find(int x1, int x2) {
		if (x1 == x2)
			return elem[x1].value;
		if (elem[x1].value > elem[x2].value)
			return find(elem[x1].parant, x2);
		else if (elem[x1].value == elem[x2].value)
			if (elem[x1].parant >= 0 && elem[elem[x1].parant].value == elem[x1].value)
				return find(elem[x1].parant, x2);
			else
				return find(x1, elem[x2].parant);
		else
			return find(x1, elem[x2].parant);
	}

	public void update(int x, int y) {
		if (debug) {
			System.out.println("---------------------");
			System.out.println("-- " + x + " " + y);
		}

		elem[x].value = y;
		updown(x);
		if (debug) {
			System.out.println("---------------------");
			printAll(root, 0);

		}
	}

	private void printAll(int p, int c) {
		if (p < 0)
			return;
		printAll(elem[p].front, c + 1);
		String x = new String(new char[c + 1]).replace("\0", ">");
		System.out.println("--- " + p + "\t" + elem[p].value + "\t" + x + " L=" + c + " F=" + elem[p].front + " B="
				+ elem[p].behind);
		printAll(elem[p].behind, c + 1);
	}

	private void updown(int x) {
		int min = x;
		if (elem[x].front >= 0 && elem[elem[x].front].value < elem[min].value)
			min = elem[x].front;
		if (elem[x].behind >= 0 && elem[elem[x].behind].value < elem[min].value)
			min = elem[x].behind;

		if (min == elem[x].front) {
			downfront(x, min);
			updown(x);
		} else if (min == elem[x].behind) {
			downbehind(x, min);
			updown(x);
		}

		if (elem[x].parant >= 0 && elem[elem[x].parant].value > elem[x].value)
			if (elem[elem[x].parant].front == x) {
				downfront(elem[x].parant, x);
				updown(x);
			} else {
				downbehind(elem[x].parant, x);
				updown(x);
			}
	}

	private void downbehind(int x, int nx) {
		if (elem[x].parant >= 0)
			if (elem[elem[x].parant].front == x)
				elem[elem[x].parant].front = nx;
			else
				elem[elem[x].parant].behind = nx;
		else
			root = nx;
		elem[nx].parant = elem[x].parant;

		elem[x].behind = elem[nx].front;
		if (elem[x].behind >= 0)
			elem[elem[x].behind].parant = x;

		elem[x].parant = nx;
		elem[nx].front = x;
	}

	private void downfront(int x, int nx) {
		if (elem[x].parant >= 0)
			if (elem[elem[x].parant].front == x)
				elem[elem[x].parant].front = nx;
			else
				elem[elem[x].parant].behind = nx;
		else
			root = nx;
		elem[nx].parant = elem[x].parant;

		elem[x].front = elem[nx].behind;
		if (elem[x].front >= 0)
			elem[elem[x].front].parant = x;

		elem[x].parant = nx;
		elem[nx].behind = x;
	}

}

import java.util.*;
class RMQ {
	private int size_, dat[];
	private int query_(int a, int b, int k, int l, int r) {
		if(r <= a || b <= l) return 2147483647;
		if(a <= l && r <= b) return dat[k];
		int lc = query_(a, b, 2 * k, l, (l + r) / 2);
		int rc = query_(a, b, 2 * k + 1, (l + r) / 2, r);
		return Math.min(lc, rc);
	}
	RMQ(int s) {
		for(size_ = 1; size_ < s;) size_ *= 2;
		dat = new int[size_ * 2];
		for(int i = 0; i < size_ * 2; i++) dat[i] = 2147483647;
	}
	public void update(int pos, int x) {
		pos += size_; dat[pos] = x;
		while(pos > 1) {
			pos /= 2;
			dat[pos] = Math.min(dat[2 * pos], dat[2 * pos + 1]);
		}
	}
	public int query(int l, int r) {
		return query_(l, r, 1, 0, size_);
	}
}
class Main {
	public static void main (String[] args) throws java.lang.Exception {
		Scanner sc = new Scanner(System.in);
		int n = sc.nextInt(), q = sc.nextInt();
		RMQ r = new RMQ(n);
		for(int i = 0; i < q; i++) {
			int c = sc.nextInt(), x = sc.nextInt(), y = sc.nextInt();
			if(c == 0) r.update(x, y);
			else System.out.println(r.query(x, y + 1));
		}
	}
}

