static int[] seg;
static int MAX_ELE;

public static void seg_init(int n){
 MAX_ELE=1;
 while(MAX_ELE<n) MAX_ELE<<=1;
 seg=new int[MAX_ELE<<1-1];
 Arrays.fill(seg,Integer.MAX_VALUE);
}


public static int query(int a,int b){
 return _query(a,b,0,0,MAX_ELE);
}

static int _query(int a, int b, int k, int l, int r) {
        if (a <= l && r <= b) return seg[k];
        if (r <= a || b <= l) return Integer.MAX_VALUE;
        int vl = _query(a, b, k * 2 + 1, l, (l + r) / 2);
        int vr = _query(a, b, k * 2 + 2, (l + r) / 2, r);
        return Math.min(vl, vr);
    }

   static void update(int i, int x) {
        i += MAX_ELE - 1;
        seg[i] = x;
        while (i > 0) {
            i = (i - 1) / 2;
            seg[i] = Math.min(seg[i * 2 + 1], seg[i * 2 + 2]);
        }
    }

