public class Main {

	int N,Q,size;
	int[] segment;

	public void init(int _size){
		size = 1;

		while(size < _size)size *= 2;
		segment = new int[2 * size];
		for(int i = 0;i < 2 * size - 1;i++){
			segment[i] = Integer.MAX_VALUE;
		}
	}

	public void update(int i,int a){
		i += size - 1;
		segment[i] = a;

		while(i > 0){
			i = (i - 1) / 2;
			segment[i] = Math.min(segment[i * 2 + 1], segment[i * 2 + 2]);
		}
	}

	public int query(int a,int b,int k,int l,int r){
		if(r <= a || b <= l)return Integer.MAX_VALUE;

		if(a <= l && r <= b)return segment[k];
		else{
			int vl = query(a,b,k * 2 + 1,l,(l + r) /2);
			int vr = query(a,b,k * 2 + 2,(l + r) / 2,r);

			return Math.min(vl, vr);
		}
	}

	public void solve() {
		N = nextInt();
		Q = nextInt();

		init(N);

		for(int i = 0;i < Q;i++){
			int c = nextInt();
			int x = nextInt();
			int y = nextInt();

			if(c == 0){
				update(x,y);
			}else{
				out.println(query(x,y + 1,0,0,size));
			}
		}
	}

	public static void main(String[] args) {
		out.flush();
		new Main().solve();
		out.close();
	}

