import java.util.*;

public class Main {

    static int INF = (1<<31)-1;
    static int n;
    static int[] dat;

    static void update(int x, int y) {
        dat[x+n-1] = y;
        int tmp = x+n-1;
        while (tmp>0) {
            tmp = (tmp-1)/2;
            dat[tmp] = Math.min(dat[tmp*2+1], dat[tmp*2+2]);
        }
    }

    static int query(int a, int b, int k, int l, int r) {
        if (a<=l && r<=b) return dat[k];
        if (b<=l || r<=a) return INF;
        int lv = query(a, b, 2*k+1, l, (l+r)/2);
        int rv = query(a, b, 2*k+2, (l+r)/2, r);
        return Math.min(lv, rv);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n_ = sc.nextInt();
        n = 1;
        while (n<n_) n*=2;
        dat = new int[2*n-1];
        Arrays.fill(dat, INF);
        int q = sc.nextInt();
        for (int i=0;i<q;i++) {
            int com = sc.nextInt();
            int x = sc.nextInt();
            int y = sc.nextInt();
            if (com==0) {
                update(x, y);
            } else { // com==1
                System.out.println(query(x, y+1, 0, 0, n));
            }
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.util.*;

public class Main {
    static int INF = (1 << 31) - 1;
    // static long L_INF = (1L << 62) - 1;
    // static long MOD = (long) 1e9 + 7;

    // セグメント木による RMQ (Range Minimum Query) の実装
    // RMQ以外にする場合は、minの部分を全て他の関数に置換する
    //
    // 計算量
    // - 初期化: O(nlogn)
    // - O(n)でも実装できるが、O(nlogn)の実装になっている
    // - init後にupdateで初期化
    // - update: O(logn)
    // - query: O(logn)
    static class SegmentTree {
        int MAX_N = 1 << 17;

        int n;
        int[] dat = new int[2 * MAX_N - 1];

        SegmentTree(int n_) {
            // 簡単のため、要素数を2のべき乗に
            n = 1;
            while (n < n_) {
                n *= 2;
            }
            // すべての値をINFに
            for (int i = 0; i < 2 * n - 1; i++) {
                dat[i] = INF;
            }
        }

        // k番目の値 (0-indexed) をaに変更
        void update(int k, int a) {
            // 葉の節点
            k += n - 1;
            dat[k] = a;
            // 登りながら更新
            while (k > 0) {
                k = (k - 1) / 2;
                dat[k] = Math.min(dat[k * 2 + 1], dat[k * 2 + 2]);
            }
        }

        // [a, b) の最小値を求める
        // 後ろのほうの引数は、計算の簡単のための引数。
        // kは節点の番号、l, rはその節点が [l, r) に対応づいていることを表す。
        // したがって、外からは inner_query(a, b, 0, 0, n) として呼ぶ。
        int inner_query(int a, int b, int k, int l, int r) {
            // [a, b) と [l, r) が交差しなければ INF
            if (r <= a || b <= l) {
                return INF;
            }

            // [a, b) が [l, r) を完全に含んでいれば、この節点の値
            if (a <= l && r <= b) {
                return dat[k];
            } else {
                // そうでなければ、2つの子の最小値
                int vl = inner_query(a, b, k * 2 + 1, l, (l + r) / 2);
                int vr = inner_query(a, b, k * 2 + 2, (l + r) / 2, r);
                return Math.min(vl, vr);
            }
        }

        // [a, b) の最小値を求める
        int query(int a, int b) {
            return inner_query(a, b, 0, 0, n);
        }
    }

    static class Solver {
        int n, q;

        // write your code
        // http://judge.u-aizu.ac.jp/onlinejudge/description.jsp?id=DSL_2_A&lang=jp
        void solve(InputReader in, PrintWriter out) {
            n = in.nextInt();
            q = in.nextInt();
            SegmentTree st = new SegmentTree(n);
            for (int i = 0; i < q; i++) {
                int com = in.nextInt();
                int xi = in.nextInt();
                int yi = in.nextInt();
                if (com == 0) {
                    st.update(xi, yi);
                } else {
                    out.println(st.query(xi, yi + 1));
                }
            }
        }

        void debug(Object... os) {
            System.err.println(Arrays.deepToString(os));
        }
    }

    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        Solver solver = new Solver();
        solver.solve(in, out);
        out.close();
    }

    static class InputReader {
        BufferedReader reader;
        StringTokenizer tokenizer;

        InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

import java.util.Arrays;

public class Main {

	public static class RMQ {
		long[][] sparse_table; // queryを O(1)にするなら, k をメモ化する事.

		public RMQ(long[] array){ // O(n log n)
			final int depth = Integer.numberOfTrailingZeros(Integer.highestOneBit(array.length));
			sparse_table = new long[depth + 1][]; sparse_table[0] = new long[array.length];
			System.arraycopy(array, 0, sparse_table[0], 0, array.length);

			for(int k = 1; k < sparse_table.length; k++){
				sparse_table[k] = new long[array.length - (1 << k) + 1];
				for(int i = 0; i + (1 << k) <= array.length; i++) { // [i, i + (1 << k))
					// [i, i + (1 << k) -> [i, i + (1 << k) / 2), [i + (1 << k) / 2, i << (k - 1))
					sparse_table[k][i] =
							Math.min(sparse_table[k-1][i], sparse_table[k-1][i + (1 << (k - 1))]);
				}
			}
		}

		public void update(int index, long v){ // index: 0-index
			//update O(n log n) で効率が悪い. SegTreeでどうぞ.
			sparse_table[0][index] = v;
			for(int k = 1; k < sparse_table.length; k++){
				final int begin = Math.max(0, index - (1 << k) + 1);
				final int end = Math.min(sparse_table[k].length, index + (1 << k));
				// 最大で index + [-(1 << k) + 1, (1 << k)) の範囲を更新する必要がある
				for(int i = begin; i < end; i++){
					sparse_table[k][i] =
							Math.min(sparse_table[k - 1][i], sparse_table[k-1][i + (1 << (k - 1))]);
				}
			}
		}

		public long query(int l, int r){ // [l, r) O(log log n)
			final int k = Integer.numberOfTrailingZeros(Integer.highestOneBit(r - l));
			// k -> 区間をオーバーしない最大の2の冪乗
			// left -> [i, i + (1 << k)), right -> [r - (1 << k)] (開区間なので±0)
			return Math.min(sparse_table[k][l], sparse_table[k][r - (1 << k)]);
		}
	}

	public static void main(String[] args){
		Scanner sc = new Scanner(System.in);

		final int n = sc.nextInt();
		final int q = sc.nextInt();

		long[] array = new long[n];
		Arrays.fill(array, Integer.MAX_VALUE);

		RMQ rmq = new RMQ(array);
		for(int tt = 0; tt < q; tt++){
			final int op = sc.nextInt();
			final int x  = sc.nextInt();
			final int y  = sc.nextInt();

			if(op == 0){
				rmq.update(x, y);
			}else{
				System.out.println(rmq.query(x, y + 1));
			}
		}
	}

	public static class Scanner {
		private BufferedReader br;
		private StringTokenizer tok;

		public Scanner(InputStream is) {
			br = new BufferedReader(new InputStreamReader(is));
		}

		private void getLine() {
			try {
				while (!hasNext()) {tok = new StringTokenizer(br.readLine());}
			} catch(IOException e){ /* ignore */ }
		}

		private boolean hasNext() {
			return tok != null && tok.hasMoreTokens();
		}

		public String next() {
			getLine(); return tok.nextToken();
		}

		public int nextInt(){
			return Integer.parseInt(next());
		}
		// 他のnextXXXもXXX.parseXXX()メソッドを使って作れるので省略

		public void close() {
			try{ br.close(); } catch (IOException e){ /*ignore*/ }
		}
	}
}

