import java.io.*;
import java.util.*;


public class Main {

	private static Scanner sc;
	private static Printer pr;

	private static void solve() {
		int n = sc.nextInt();
		int q = sc.nextInt();

		long[] data = new long[n];
		Arrays.fill(data, Integer.MAX_VALUE);
		SegmentTree rmq = new SegmentTree(SegmentTree.QueryType.RMinQ_Update, data);

		for (int i = 0; i < q; i++) {
			int cmd = sc.nextInt();

			if (cmd == 0) {
				int x = sc.nextInt();
				int y = sc.nextInt();

				rmq.update(x, y);
			} else if (cmd == 1) {
				int x = sc.nextInt();
				int y = sc.nextInt();

				pr.println(rmq.query(x, y + 1));
			}
		}
	}

	/**
	 * Segment Tree
	 */
	static class SegmentTree {
		enum QueryType {
			RSumQ_Update,
			RMinQ_Update,
			RMaxQ_Update,
		};

		QueryType qt;

		long INIT; // 要素の単位元
		long[] st; // 要素用SegmentTree
		int n; // 要素数(2のべき乗に補正)

		public SegmentTree(SegmentTree.QueryType qt, long[] data) {
			this.qt = qt;

			n = 1;
			while (n < data.length) {
				n *= 2;
			}

			init();

			st = new long[2 * n - 1];
			for (int k = 0, size = data.length; k < n; k++) {
				if (k < size) {
					st[n - 1 + k] = data[k];
				} else {
					st[n - 1 + k] = INIT;
				}
			}
			for (int k = n - 2; k >= 0; k--) {
				long q1 = st[2 * k + 1];
				long q2 = st[2 * k + 2];

				st[k] = f(q1, q2);
			}
		}

		// l,r:0-indexed
		// [l,r)の値をupdate
		void update(int i, int x) {
			int k = n - 1 + i;
			st[k] = x;
			while (k > 0) {
				k = (k - 1) / 2;
				long q1 = st[2 * k + 1];
				long q2 = st[2 * k + 2];

				st[k] = f(q1, q2);
			}
		}

		// l,r:0-indexed
		// [l,r)に対するクエリ
		long query(int l, int r) {
			return query(l, r, 0, 0, n);
		}

		private long query(int l, int r, int k, int ll, int rr) {
			long ret;

			if (ll >= l && rr <= r) {
				ret = st[k];
			} else if (ll >= r || rr <= l) {
				// 交差なし
				ret = INIT;
			} else {
				int mm = (ll + rr) / 2;

				long q1 = query(l, r, 2 * k + 1, ll, mm);
				long q2 = query(l, r, 2 * k + 2, mm, rr);

				ret = f(q1, q2);
			}

			return ret;
		}

		// 要素の単位元の設定
		private void init() {
			switch (qt) {
			case RSumQ_Update:
				INIT = 0;
				return;
			case RMinQ_Update:
				INIT = Long.MAX_VALUE;
				return;
			case RMaxQ_Update:
				INIT = Long.MIN_VALUE;
				return;
			}

			return;
		}

		// 2つの区間の要素をマージする二項演算
		private long f(long st1, long st2) {
			switch (qt) {
			case RSumQ_Update:
				return st1 + st2;
			case RMinQ_Update:
				return Math.min(st1, st2);
			case RMaxQ_Update:
				return Math.max(st1, st2);
			}

			return 0;
		}
	}

