  return Math.min(cl,cr);
 }

 public void update(int i,long val) {
  i+=n-1;
  seg[i]=val;
  while(i>0) {
   i=(i-1)/2;
   seg[i]=Math.min(seg[i*2+1],seg[i*2+2]);
  }
 }
}

