    class Program
    {
        static readonly int INFTY = int.MaxValue;
        static int[] segment;
        static int size;

        static void Main(string[] args)
        {
            string[] input1 = Console.ReadLine().Split(' ');
            int n = int.Parse(input1[0]);
            int q = int.Parse(input1[1]);

            Init(n);

            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < q; i++)
            {
                string[] input2 = Console.ReadLine().Split(' ');
                int c = int.Parse(input2[0]);
                int x = int.Parse(input2[1]);
                int y = int.Parse(input2[2]);

                if (c == 0) Update(x, y);
                else
                {
                    sb.AppendLine(Query(x, y + 1, 0, 0, size).ToString());
                }
            }
            Console.Write(sb);
        }

        static void Init(int n)
        {
            size = 1;

            while (size < n) size *= 2;

            segment = Enumerable.Repeat(INFTY, 2 * size - 1).ToArray();
        }

        static void Update(int i, int a)
        {
            i += size - 1;
            segment[i] = a;

            while (i > 0)
            {
                i = (i - 1) / 2;
                segment[i] = Math.Min(segment[i * 2 + 1], segment[i * 2 + 2]);
            }
        }

        static int Query(int a, int b, int k, int l, int r)
        {
            if (r <= a || b <= l) return INFTY;

            if (a <= l && r <= b) return segment[k];
            else
            {
                int vl = Query(a, b, k * 2 + 1, l, (l + r) / 2);
                int vr = Query(a, b, k * 2 + 2, (l + r) / 2, r);

                return Math.Min(vl, vr);
            }
        }
    }
}

