class SegmentTree<T>
{
    private List<T> item;
    private int _num;
    private Func<T, T, T> _func;
    private Func<T, T> updateFunc;
    private T _inf;

    public int Parent(int index)
        => (index + 1) / 2 - 1;
    public int Left(int index)
        => 2 * index + 1;
    public int Right(int index)
        => 2 * (index + 1);

    public SegmentTree(int num, T inf, Func<T, T, T> func, Func<T, T> updateFunc=null)
    {
        _func = func;
        _num = 1;
        _inf = inf;
        this.updateFunc = updateFunc ?? ((T value) => value);
        while (_num < num)
            _num *= 2;
        item = new List<T>(2 * _num - 1);
        for (var i = 0; i < 2 * _num - 1; i++)
            item.Add(inf);
    }
    public void Update(int index, T value)
    {
        index += _num - 1;
        item[index] = updateFunc(value);
        while (Parent(index) >= 0)
        {
            index = Parent(index);
            item[index] = _func(item[Left(index)], item[Right(index)]);
        }
    }
    public T query(int left, int right)
        => query(left, right, 0, 0, _num);
    private T query(int left, int right, int k, int l, int r)
    {
        if (r <= left || right <= l) return _inf;
        if (left <= l && r <= right) return item[k];
        else
            return _func(query(left, right, Left(k), l, (l + r) / 2), query(left, right, Right(k), (l + r) / 2, r));
    }
}

