class Main {
    class SegTree {
        private const long MAX = int.MaxValue;
        long[] nodes;
        int l = 1;
        public SegTree(int n) {
            while (l < n) {
                l *= 2;
            }

            this.nodes = new long[2 * l - 1];
            for (int i = 0; i < nodes.Length; i++) {
                nodes[i] = MAX;
            }
        }

        public void Update(int i, long x) {
            int cur = l - 1 + i;
            nodes[cur] = x;

            // 親に向かって更新
            while (cur > 0) {
                var p = (cur - 1) / 2;
                nodes[p] = Math.Min(nodes[2 * p + 1], nodes[2 * p + 2]);
                cur = p;
            }
        }

        public long Search(int searchL, int searchR) {
            return Search(searchL, searchR, 0, 0, l);
        }

        private long Search(int searchL, int searchR, int nowP, int nowL, int nowR) {
            if (searchL >= nowR || searchR <= nowL) {
                return MAX;
            }

            if (searchL <= nowL && nowR <= searchR) {
                return nodes[nowP];
            }

            return Math.Min(
                Search(searchL, searchR, 2 * nowP + 1, nowL, (nowL + nowR) / 2),
                Search(searchL, searchR, 2 * nowP + 2, (nowL + nowR) / 2, nowR)
                );
        }
    }

