    #region SegmentTree

    /// <summary>
    /// 行う演算は結合法則を満たす必要あり
    /// </summary>
    public class SegmentTree<T> where T : IComparable
    {
        /// <summary>
        /// 完全二分木
        /// </summary>
        public T[] Data { get; }

        /// <summary>
        /// 完全二分木に含まれる葉の数
        /// </summary>
        private int LeavesCount { get; }

        /// <summary>
        /// 数列(問題などで与えられる)の要素数
        /// </summary>
        public int Count { get; }

        /// <summary>
        /// 葉のうち使われなかったもの、そしてQueryで引数として取得した範囲がDataのインデックスの外である場合に使う
        /// </summary>
        public T Default { get; }


        public SegmentTree(T[] data, T def)
        {

            //初期値の設定
            Count = data.Length;
            Default = def;
            LeavesCount = (int)Pow(2, Ceiling(Log(data.Length, 2)));
            Data = new T[LeavesCount * 2];
            //

            //完全二分木の全要素を初期化
            for (int i = 0; i < LeavesCount * 2; i++)
            {
                Data[i] = def;
            }

            //dataを用いて必要な要素をすべて埋める
            for (int i = 0; i < data.Length; i++)
            {
                this[i] = data[i];
            }
        }

        public T this[int index]
        {
            get
            {
                //取得したい要素の位置は、実際は LeavesCount-1+index となる
                index = LeavesCount - 1 + index;

                return Data[index];
            }
            set
            {
                //偏光したい要素の位置は、実際は LeavesCount-1+index となる
                index = LeavesCount - 1 + index;

                //子を変更
                Data[index] = value;

                //親たちも含めて、要素を変更
                while (index > 0)
                {
                    //indexを親のインデックスに更新
                    index = GetParentIndex(index);

                    //要素を更新
                    Data[index] = DecideNewElementFromTwoChildren(index);
                }
            }
        }


        /// <summary>
        /// 唯一の親のインデックスを返す
        /// </summary>
        /// <param name="childIndex"></param>
        /// <returns></returns>
        private int GetParentIndex(int childIndex)
        {
            return (childIndex - 1) / 2;
        }

        /// <summary>
        /// 二つの子のインデックスを返す
        /// </summary>
        /// <param name="parentIndex"></param>
        /// <returns>小さいほうはl、大きいほうはr</returns>
        //private (int l, int r) GetChildIndexes(int parentIndex)
        //{
        //    return (2 * parentIndex + 1, 2 * parentIndex + 2);
        //}

        /// <summary>
        /// 親の値を二つの子から決定する
        /// </summary>
        /// <param name="index"></param>
        /// <returns></returns>
        private T DecideNewElementFromTwoChildren(int index)
        {
            int[] children = { 2 * index + 1, 2 * index + 2 };

            return Select(Data[children[0]], Data[children[1]]);
        }



        /// <summary>
        /// [a,b)の範囲で回答を探す
        /// </summary>
        /// <param name="a"></param>
        /// <param name="halfOpen_b"></param>
        /// <returns></returns>
        public T Query(int a, int halfOpen_b)
        {
            return _Query(a, halfOpen_b, 0, LeavesCount, 0);
        }

        private T _Query(int a, int b, int l, int r, int current)
        {
            //Φ
            if (a >= r || b <= l)
            {
                return Default;
            }
            //部分集合
            else if (a <= l && b >= r)
            {
                return Data[current];
            }
            //一部
            else
            {

                //(1) 範囲[l,r)を分割し、子lの回答と子rの回答を取得
                //(2) 二つの回答を比べて、適切(Selectメソッド)な方を返す


                //(1)
                int[] children = { 2 * current + 1, 2 * current + 2 };
                T t1 = _Query(a, b, l, (l + r) / 2, children[0]);
                T t2 = _Query(a, b, (l + r) / 2, r, children[1]);

                //(2)
                return Select(t1, t2);
            }

        }





        /// <summary>
        /// カスタマイズするところ。二つの子の値から、親の値を決定する方法を定める。
        /// </summary>
        /// <param name="t1">子の値1</param>
        /// <param name="t2">子の値2</param>
        /// <returns></returns>
        private T Select(T t1, T t2)
        {
            return t1.CompareTo(t2) < 0 ? t1 : t2;
        }

    }

    #endregion

    static void Main()
    {
        int[] NQ = ReadInts;
        int N = NQ[0];
        int Q = NQ[1];

        int infty = (int)Pow(2, 31) - 1;
        int[] init = new int[N];
        for (int i = 0; i < N; i++)
        {
            init[i] = infty;
        }
        var tree = new SegmentTree<int>(init ,infty);

        List<int> ans = new List<int>();
        for (int i = 0; i < Q; i++)
        {
            int[] CXY = ReadInts;
            int C = CXY[0];
            int X = CXY[1];
            int Y = CXY[2];

            if(C == 0)
            {
                tree[X] = Y;
            }
            else
            {
                ans.Add(tree.Query(X, Y+1));
            }
        }

        WriteLine(string.Join("\n", ans));
    }


