class SegmentTree<T> {
    public int Size;
    public T[] Node;
    public Func<T, T, T> Calc;
    T Def;

    public SegmentTree(int n, T[] init, T def, Func<T, T, T> calc) {
        Calc = calc;
        Def = def;
        Size = 1;
        while(Size < n) Size *= 2;
        Node = new T[2 * Size - 1];
        for(int i = 0; i < init.Length; i++) {
            Node[(Size - 1) + i] = init[i];
        }
        for(int i = init.Length; i < Size; i++) {
            Node[(Size - 1) + i] = Def;
        }
        for(int i = (Size - 1) - 1; 0 <= i; i--) {
            Node[i] = Calc(Node[2 * i + 1], Node[2 * i + 2]);
        }
    }

    public void Update(int index, T value) {
        int pos = (Size - 1) + index;
        Node[pos] = value;
        while(0 < pos) {
            pos = (pos - 1) / 2;
            Node[pos] = Calc(Node[2 * pos + 1], Node[2 * pos + 2]);
        }
    }

    public T GetRange(int index, int length) {
        return GetRange(index, length, 0, 0, Size);
    }

    public T GetRange(int index, int length, int k, int l, int r) {
        if(r <= index || index + length <= l) {
            return Def;
        }
        if(index <= l && r <= index + length) {
            return Node[k];
        }
        T vl = GetRange(index, length, k * 2 + 1, l, (l + r) / 2);
        T vr = GetRange(index, length, k * 2 + 2, (l + r) / 2, r);
        return Calc(vl, vr);
    }
}

