public class SegTree
{
    int[] buffer;
    int N;

    public SegTree(int cap)
    {
        buffer = new int[cap * 2 - 1];
        for (int i = 0; i < buffer.Length; i++)
        {
            buffer[i] = int.MaxValue;
        }
        N = cap;
    }

    public void Update(int index, int value)
    {
        index += N - 1;
        buffer[index] = value;
        while (index > 0)
        {
            index = (index - 1) / 2;
            buffer[index] = Math.Min(buffer[index * 2 + 1], buffer[index * 2 + 2]);
        }
    }

    public int Query(int l, int r)
    {
        var y = int.MaxValue;
        l += N - 1;
        r += N - 1;
        while (l < r)
        {
            if ((l & 1) == 0)
            {
                y = Math.Min(y, buffer[l]);
            }
            if ((r & 1) == 0)
            {
                y = Math.Min(y, buffer[r - 1]);
            }
            l /= 2;
            r = (r - 1) / 2;
        }
        return y;
    }
}

