                int vl = findQuery(a, b, 2 * k + 1, l, (l + r) / 2, dat);
                int vr = findQuery(a, b, 2 * k + 2, (l + r) / 2, r, dat);
                return Math.Min(vl, vr);
            }

        }
    }
}

