namespace AOJ2
{
    class Program
    {
        static void Main()
        {

            var nq = Console.ReadLine().Split(' ').Select(x => int.Parse(x)).ToArray();
            var array = Enumerable.Repeat(int.MaxValue, nq[0]).ToArray();
            var input = Read(nq[1]).ToArray();
            var result = new StringBuilder();
            string[] before = { "" };
            var beforeValue = 0;
            foreach (var com in input)
            {
                if (before.SequenceEqual(com))
                {
                    if (com[0] == "1")
                    {
                        result.Append(beforeValue.ToString() + Environment.NewLine);
                    }
                    continue;
                }
                var x = int.Parse(com[1]);
                var y = int.Parse(com[2]);
                if (com[0] == "0")
                {
                    array[x] = y;
                }
                else
                {
                    int[] ary2 = new int[y - x + 1];
                    Buffer.BlockCopy(array, x*4, ary2,0, ary2.Length * 4);
                    beforeValue = ary2.Min();
                    result.Append(beforeValue.ToString()+Environment.NewLine);

                }
                before = com;
            }
            Console.WriteLine(result.ToString());

        }

        private static IEnumerable<string[]> Read(int loop)
        {
            for (int i = 0; i < loop; i++)
            {
                yield return Console.ReadLine().Split(' ').ToArray();
            }
        }
    }
