            else res.Add(seg.query(qu[1], qu[2] + 1));
        }
        WriteLine(string.Join("\n", res));
    }
    class Seg
    {
        private List<long> item;
        private int _num;
        public int Parent(int index)
            => (index + 1) / 2 - 1;
        public int Left(int index)
            => 2 * index + 1;
        public int Right(int index)
            => 2 * (index + 1);
        public Seg(int num)
        {
            var inf = (1L << 31) - 1;
            _num = 1;
            while (_num < num)
                _num *= 2;
            item = new List<long>(2 * _num - 1);
            for (var i = 0; i < 2 * _num - 1; i++)
                item.Add(inf);
        }
        public void Update(int index,int value)
        {
            var ii = _num + index - 1;
            item[ii] = value;
            while (Parent(ii) >= 0)
            {
                ii = Parent(ii);
                item[ii] = Min(item[Left(ii)], item[Right(ii)]);
            }
        }
        public long query(int left, int right)
            => query(left, right, 0, 0, _num);
        private long query(int left,int right,int k,int l,int r)
        {
            if (r <= left || right <= l) return (1L << 31) - 1;
            if (left <= l && r <= right) return item[k];
            else
                return Min(query(left, right, Left(k), l, (l + r) / 2), query(left, right, Right(k), (l + r) / 2, r));
        }
    }
}
