struct RMQ
{
    private int n;
    private int[] dat;
    public int Length { get; private set; }

    /* nを要素数として、すべてint.MaxValueで初期化 */
    public RMQ(int n)
    {
        Length = n;
        this.n = 1;
        while (this.n < n) this.n *= 2;
        dat = new int[2 * this.n];
        for (int i = 0; i < 2 * this.n - 1; i++)
            dat[i] = int.MaxValue;
    }

    /* nを要素数として、すべてNで初期化 */
    public RMQ(int n, int N)
    {
        Length = n;
        this.n = 1;
        while (this.n < n) this.n *= 2;
        dat = new int[2 * this.n];
        for (int i = 0; i < 2 * this.n - 1; i++)
            dat[i] = N;
    }

    /* k番目(0-indexed)をaに変更 */
    public void Update(int k, int a)
    {
        k += n - 1;
        dat[k] = a;
        while (k > 0)
        {
            k = (k - 1) / 2;
            dat[k] = Math.Min(dat[k * 2 + 1], dat[k * 2 + 2]);
        }
    }

    private int Query_(int a, int b, int k, int l, int r)
    {
        if (r <= a || b <= l) return int.MaxValue;
        if (a <= l && r <= b) return dat[k];
        int v1 = Query_(a, b, k * 2 + 1, l, (l + r) / 2);
        int v2 = Query_(a, b, k * 2 + 2, (l + r) / 2, r);
        return Math.Min(v1, v2);
    }

    /* [a,b)の最小値を求める */
    public int Query(int a, int b)
    {
        return Query_(a, b, 0, 0, n);
    }
}

