    public class SegmentTree<Monoid>
    {
        private bool debug = false;
        // 0-indexed SegmentTree
        public int size;
        Monoid[] segTree;
        Monoid unit;

        public SegmentTree(int inSize, Monoid unit)
        {
            this.unit = unit;
            size = 2;
            while (size < inSize) size *= 2;
            segTree = new Monoid[2 * size];
            for (int i = 0; i < segTree.Length; i++)
            {
                segTree[i] = unit;
                // 単位元なので全部に代入しておけばよい
            }
        }


        public void set(int iter, Monoid val)
        {
            segTree[iter + size - 1] = val;
        }

        public void build()
        {
            // 2段目より上の構築
            for (int k = size - 2; k >= 0; k--)
            {
                segTree[k] = F(segTree[2 * k + 1], segTree[2 * k + 2]);
            }
        }

        public Monoid F(Monoid m1, Monoid m2)
        {
            Monoid res = Math.Min((dynamic)m1, (dynamic)m2);
            // 何らかの操作, ここではMax
            // dynamicでとればなんとかなるのか?
            return res;
        }

        public Monoid Query(int ql, int qr, int index, int nl, int nr)
        {

            // [ql, qr)について考える
            // index に対応する範囲 nl <= x <= nr
            if(nr <= ql || qr <= nl)
            {
                if(debug) Console.WriteLine("Out: [l , r), index: [" + nl + " ," + nr + "), "+ index + " ,unit:" + unit); 
                return unit;
            }
            if(ql <= nl && nr <= qr)
            {
                if(debug) Console.WriteLine("All in [l , r), index: [" + nl + " ," + nr + "), " + index + ",rangeAns:" + segTree[index]);
                return segTree[index];
            }
            else
            {
                Monoid vl = Query(ql, qr, index * 2 + 1, nl, (nl + nr) / 2);
                Monoid vr = Query(ql, qr, index * 2 + 2, (nl + nr) / 2, nr);
                if (debug) Console.WriteLine("Recursive: [l , r), index: [" + nl + " ," + nr + "), " + index);
                if (debug) Console.WriteLine("(vl, vr): (" + vl + ", " + vr + ")");
                return F(vl, vr);
            }
        }

        public void update(int k, Monoid x)
        {
            k += size-1;
            segTree[k] = x;
            while (true)
            {
                k = (k - 1) / 2;
                segTree[k] = F(segTree[k * 2 + 1], segTree[k * 2 + 2]);
                if(k == 0)
                {
                    break;
                }
            }
        }

        public void print()
        {
            Console.Write("Print:");
            for (int i = 0; i < segTree.Length; i++)
            {
                Console.Write(segTree[i] + " ");
            }
            Console.WriteLine("");
        }

    }


    static int Nibutan(long[] array, long k)
    {
        int low = 0 ;
        int high = array.Length-1;
        int mid = high;

        while (low < high)
        {
            mid = (low + high) / 2;
            if(array[mid] >= k) // k以上の最小index.ココを変えるだけ
            {
                high = mid;
            }
            else
            {
                low = mid + 1;
            }
            mid = (low + high) / 2;
        }
        return mid;
    }   

