type Memo struct {
	minList   []int
	valueList []int
	numValue  int
}

func NewMemo(n int) Memo {
	valueList := make([]int, n)
	minList := make([]int, int(math.Ceil(float64(n)/float64(math.Floor(math.Sqrt(float64(n)))))))
	for i := range valueList {
		valueList[i] = DEF_VAL
	}
	for i := range minList {
		minList[i] = DEF_VAL
	}
	m := Memo{minList, valueList, int(math.Floor(math.Sqrt(float64(n))))}
	return m
}

func (this *Memo) Update(index int, value int) {
	this.valueList[index] = value
	indexes := this.GetIndexes(index, index)
	period := this.GetPeriod(index)
	// fmt.Printf("list:%v\n", this.minList)
	// fmt.Printf("index: %v\n", indexes)
	// fmt.Printf("[%d] <- %d, %v\n", index, value, period)
	min := DEF_VAL
	for _, i := range period {
		if this.valueList[i] < min {
			min = this.valueList[i]
		}
	}
	this.minList[indexes[0]] = min
}

func (this *Memo) Find(begin int, end int) int {
	// begin - end のと index の境界は異なるので、最初と最後は走査しないと正しくない
	indexes := this.GetIndexes(begin, end)
	// fmt.Printf("indexes:%v\n", indexes)
	min := DEF_VAL
	for i := indexes[0] + 1; i < indexes[len(indexes)-1]; i++ {
		if this.minList[i] < min {
			min = this.minList[i]
		}
	}
	beginEnd := Min(end, indexes[0]*this.numValue+this.numValue-1) //begin/this.numValue + (this.numValue - 1)
	for i := begin; i <= beginEnd && i <= end; i++ {
		if this.valueList[i] < min {
			min = this.valueList[i]
		}
	}
	endBegin := Max(begin, indexes[len(indexes)-1]*this.numValue)
	for i := endBegin; i <= end; i++ {
		if this.valueList[i] < min {
			min = this.valueList[i]
		}
	}
	// fmt.Printf("Find(%d, %d)\n BeginEnd: %d\n EndBegin: %d\n min: %d\n", begin, end, beginEnd, endBegin, min)
	// fmt.Printf("    %v\n", this.valueList)
	// fmt.Printf("    %v\n", indexes)
	return min
}

func (this *Memo) GetIndexes(begin int, end int) []int {
	// 範囲をカバーする minListのインデックスを計算する
	result := make([]int, 0)
	for i := begin; i <= end; i += this.numValue {
		x := i / this.numValue
		result = append(result, x)
	}
	return result
}

func (this *Memo) GetPeriod(index int) []int {
	begin := index / this.numValue * this.numValue
	end := begin + this.numValue - 1
	result := make([]int, 0)
	for i := begin; i <= end && i < len(this.valueList); i++ {
		result = append(result, i)
	}
	return result
}

