// Segment Tree for Range Minimum Query (RMQ)
type SegTree []int

const Unit = 1<<31 - 1

func MakeSegTree(n_ int) SegTree {
	n := 1
	for n < n_ {
		n <<= 1
	}
	t := make([]int, n*2)
	for i := 1; i < len(t); i++ {
		t[i] = Unit
	}
	return t
}

func (t SegTree) Update(i, x int) {
	i += len(t) >> 1
	t[i] = x
	for i > 1 {
		i >>= 1
		t[i] = Min(t[i*2], t[i*2+1])
	}
}

func (t SegTree) Query(a, b int) int {
	return t.queryRecur(a, b, 1, 0, len(t)>>1)
}

func (t SegTree) queryRecur(a, b, k, l, r int) int {
	if b <= l || r <= a {
		return Unit
	}
	if a <= l && r <= b {
		return t[k]
	}
	return Min(
		t.queryRecur(a, b, k*2, l, (l+r)>>1),
		t.queryRecur(a, b, k*2+1, (l+r)>>1, r),
	)
}

func Min(xs ...int) int {
	min := xs[0]
	for _, x := range xs[1:] {
		if min > x {
			min = x
		}
	}
	return min
}

