type Scanner struct {
	reader  *bufio.Reader
	buffer  []string
	pointer int
}

func NewScanner() *Scanner {
	return &Scanner{
		reader:  bufio.NewReaderSize(os.Stdin, 4096),
		pointer: 0,
	}
}

func (self *Scanner) NextLine() string {
	var buffer []byte
	for {
		line, isPrefix, _ := self.reader.ReadLine()
		buffer = append(buffer, line...)
		if !isPrefix {
			break
		}
	}
	return string(buffer)
}

func (self *Scanner) Next() string {
	if self.pointer >= len(self.buffer) {
		line := self.NextLine()
		self.buffer = strings.Fields(line)
		self.pointer = 0
	}
	self.pointer++
	return self.buffer[self.pointer-1]
}

func (self *Scanner) NextInt() int {
	s := self.Next()
	i, _ := strconv.ParseInt(s, 10, 32)
	return int(i)
}

func (self *Scanner) NextLong() int64 {
	s := self.Next()
	l, _ := strconv.ParseInt(s, 10, 64)
	return int64(l)
}

func (self *Scanner) NextFloat() float32 {
	s := self.Next()
	f, _ := strconv.ParseFloat(s, 32)
	return float32(f)
}

func (self *Scanner) NextFloat64() float64 {
	s := self.Next()
	d, _ := strconv.ParseFloat(s, 64)
	return float64(d)
}

// SegTreeIntMin ... 区間内の最小値を求める
type SegTreeIntMin struct {
	segment []int
	size    int
}

// NewSegTreeIntMin ... 初期化
func NewSegTreeIntMin(vals []int, n int) *SegTreeIntMin {

	size := 1
	for size < n {
		size <<= 1
	}
	segment := make([]int, size*4-1)
	for i := 0; i < size*4-1; i++ {
		segment[i] = (1 << 31) - 1
	}

	for i := 0; i < n; i++ {
		segment[size+i-1] = vals[i]
	}

	return &SegTreeIntMin{
		segment: segment,
		size:    size,
	}
}

// Set ... indexの位置のvalueを更新,最小値を更新していく
func (segtree *SegTreeIntMin) Set(index int, value int) {

	k := segtree.size + index - 1
	segtree.segment[k] = value

	for k > 0 {
		k = (k - 1) >> 1
		if segtree.segment[(k<<1)+1] <= segtree.segment[(k<<1)+2] {
			segtree.segment[k] = segtree.segment[(k<<1)+1]
		} else {
			segtree.segment[k] = segtree.segment[(k<<1)+2]
		}
	}
}

// Query ... 区間[a,b)に含まれる最小値を返す
func (segtree *SegTreeIntMin) Query(a, b, left, right, k int) int {
	if b <= left || right <= a {
		return (1 << 31) - 1
	}

	if left <= a && b <= right {
		return segtree.segment[k]
	}

	leftValue := segtree.Query(a, (a+b)>>1, left, right, (k<<1)+1)
	rightValue := segtree.Query((a+b)>>1, b, left, right, (k<<1)+2)

	if leftValue <= rightValue {
		return leftValue
	}
	return rightValue
}

func main() {
	cin := NewScanner()

	N := cin.NextInt()
	Q := cin.NextInt()

	A := make([]int, N)
	for i := 0; i < N; i++ {
		A[i] = (1 << 31) - 1
	}

	segTree := NewSegTreeIntMin(A, N)

	for i := 0; i < Q; i++ {
		com := cin.NextInt()
		x := cin.NextInt()
		y := cin.NextInt()

		if com == 0 {
			segTree.Set(x, y)
		} else {
			value := segTree.Query(0, segTree.size, x, y+1, 0)
			fmt.Println(value)
		}
	}
}

