let split str delim =
  let open String in
  let rec doit s acc =
    match
      try Some (rindex s delim) with _ -> None
    with
    | None -> s :: acc
    | Some i -> doit (sub s 0 i) (sub s (i + 1) (length s - i - 1) :: acc) in
  doit str []

let parent i = int_of_float ((float_of_int (i - 1)) /. 2.)

let left i = 2*i + 1

let right i = 2*i + 2

let to_pow_of_2 n =
  let rec doit i =
    if i >= n then i
    else doit (i * 2) in
  doit 1

let solve n q =
  let n = to_pow_of_2 n in
  let s = Array.make (2*n-1) 2147483647 in
  let update i x =
    let j = n + i - 1 in
    s.(j) <- x;
    let rec doit j =
      if j > 0 then begin
        s.(j) <- min s.(left j) s.(right j);
        doit (parent j)
      end in
    doit (parent j) in
  let rec find a b k l r =
    if r <= a || b <= l then 2147483647
    else if a <= l && r <= b then s.(k)
    else min (find a b (left k) l ((l + r) / 2)) (find a b (right k) ((l + r) / 2) r) in
  let find a b = find a b 0 0 n in
