class SegmentTree
{
private:
    long size;
    long[] xs;
public:
    this(long size)
    {
        long i = 1;
        while (i <= size)
        {
            i *= 2;
        }
        this.size = size;
        xs = new long[](i * 2);
    }

    this(long size, long initial_value)
    {
        this(size);
        this.xs.fill(initial_value);
    }

    void update(long i, long x)
    {
        i += this.size;
        xs[i] = x;
        while (i != 0)
        {
            i /= 2;
            xs[i] = min(xs[i * 2], xs[i * 2 + 1]);
        }
    }

    long find(long l, long r)
    {
        l += this.size;
        r += this.size;

        long ans = long.max / 2;
        while (l < r)
        {
            if (l % 2 == 1)
            {
                ans = min(ans, xs[l]);
                l++;
            }
            l /= 2;
            if (r % 2 == 1)
            {
                ans = min(ans, xs[r - 1]);
                r--;
            }
            r /= 2;
        }
        return ans;
    }
}

