class SegTree(T){
private:
    T[] data;
    int N;

public:
    int depth;

    this(T[] a){
        N = a.length.to!int;

        while(2^^depth < N){
            depth++;
        }

        data = new int[](2^^(depth + 1) - 1);

        data[] = int.max;
        data[2^^depth - 1 .. 2^^depth - 1 + N] = a[];

        foreach_reverse(i ; 0 .. 2^^depth - 1){
            data[i] = min(data[2*i + 1], data[2*i + 2]);
        }
    }

    void update(int i, T x){
        i += 2^^depth - 1;
        data[i] = x;

        while(i > 0){
            i = (i - 1) / 2;
            data[i] = min(data[2*i + 1], data[2*i + 2]);
        }
    }

    T find(int s, int t, int k, int l, int r){
        if (r <= s || t <= l) {
            return int.max;
        }

        if (s <= l && r <= t) {
            return data[k];
        }

        auto vl = find(s, t, 2*k + 1, l, (l + r) / 2);
        auto vr = find(s, t, 2*k + 2, (l + r) / 2, r);

        return min(vl, vr);
    }

    void print(){
        stderr.writefln("%(%s %)", data);
    }
}

class FenwickTree(T){
private:
    T[] data;
    int N;

public:
    this(T[] a){
        data = [0] ~ a[];
        N = a.length.to!int;

        foreach (i ; 1 .. N + 1) {
            if (i + (i & (-i)) <= N) {
                data[i + (i & (-i))] += data[i];
            }
        }
    }

    void add(int i, T x) {
        i++;

        while (i <= N) {
            data[i] += x;
            i += i & (-i);
        }
    }

    T getSum(int r) {
        T res;

        while(r > 0){
            res += data[r];
            r -= r & (-r);
        }

        return res;
    }

    void print(){
        stderr.writefln("%(%s %)", data);
    }
}


