struct SqrtDecomp {
    private {
        enum sqrtN = 512;
        int N, K;
        int[] bucket;
        int[] data;
    }

    this(int n) {
        N = n;
        K = (N + sqrtN - 1) / sqrtN;
        bucket = new int[](K);
        data = new int[](K * sqrtN);
        bucket[] = int.max;
        data[] = int.max;
    }

    void update(int i, int x) {
        int k = i / sqrtN;
        data[i] = x;
        foreach (j ; k * sqrtN .. (k + 1) * sqrtN) {
            bucket[k] = min(bucket[k], data[j]);
        }
    }

    int getMin(int l, int r) {
        int res = int.max;

        foreach (k ; 0 .. K) {
            int bl = k * sqrtN, br = (k + 1) * sqrtN;
            if (r <= bl || br <= l) continue;
            if (l <= bl && br <= r) {
                res = min(res, bucket[k]);
            }
            else {
                foreach (i ; max(l, bl) .. min(r, br)) {
                    res = min(res, data[i]);
                }
            }
        }

        return res;
    }
}



