  def __init__(self,n,e):
    self.n = 2**((n-1).bit_length())
    self.e = e
    self.d = [e]*(self.n<<1)

  def update(self,k,x):
    k += self.n-1
    self.d[k] = x
    while k > 0:
      k = (k-1)>>1
      self.d[k] = min(self.d[(k<<1)+1],self.d[(k<<1)+2])

  def query(self,l,r):
    L = l+self.n; R = r+self.n
    s = self.e
    while L < R:
      if R & 1:
        R -= 1
        s = min(s,self.d[R-1])
      if L & 1:
        s = min(s,self.d[L-1])
        L += 1
      L >>= 1; R >>= 1
    return s

