class SegmentTree:
    def __init__(self, N, mode=min):
        n_ = 1

        while n_ < N:
            n_ *= 2

        self.n = n_
        self.mode = mode

        if self.mode == min:
            self.arr = [2**31-1] * (2*self.n - 1)
        elif self.mode == max:
            self.arr = [-2**31+1] * (2*self.n - 1)

    def update(self, k, a):
        k += self.n - 1
        self.arr[k] = a

        while k > 0:
            k = (k - 1) // 2
            self.arr[k] = self.mode(self.arr[2*k+1], self.arr[2*k+2])

    def query(self, l, r):
        L, R = l + self.n, r + self.n

        if self.mode == min:
            res = 2**31-1
        else:
            res = -2**31+1

        while L < R:
            if R & 1:
                R -= 1
                res = self.mode(res, self.arr[R-1])

            if L & 1:
                res = self.mode(res, self.arr[L-1])
                L += 1

            L >>= 1
            R >>= 1

        return res

