class SegmentTree:
    def __init__(self, n, f, gen):
        self.n = n
        self.size = 1
        self.gen = gen
        self.f = f
        while self.size < n:
            self.size *= 2
        self.seg = [gen] * (2 * self.size)

    def set(k, x):
        self.seg[k + self.size] = x

    def build(self):
        k = self.size - 1
        while k>0:
            self.seg[k] = self.f(self.seg[2 * k], self.seg[2 * k + 1])
            k -= 1

    def update(self, i, x):
        k = i + self.size
        self.seg[k] = x
        while k > 0:
            k >>= 1
            self.seg[k] = self.f(self.seg[2 * k], self.seg[2 * k + 1])

    def query(self, a, b):
        """
        [a,b)
        """
        L = self.gen
        R = self.gen
        A = a + self.size
        B = b + self.size
        while A<B:
            if A%2:
                L = self.f(L, self.seg[A])
                A += 1
            if B%2:
                B -= 1
                R = self.f(self.seg[B], R)
            A >>= 1
            B >>= 1
        return f(L, R)



