class MIN_SEGMENTTREE:
    def __init__(self,lis):
        length=len(lis)
        self.n=2**length.bit_length()
        self.node=[float("inf")]*(2*self.n-1)

        for i in range(length):
            self.node[i+self.n-1]=lis[i]
        for i in range(self.n-2,-1,-1):
            if self.node[2*i+1]>self.node[2*i+2]:
                self.node[i]=self.node[2*i+2]
            else:
                self.node[i]=self.node[2*i+1]

    def update(self,point,value):
        point+=self.n-1
        self.node[point]=value
        while point>0:
            point=(point-1)//2
            if self.node[2*point+1]>self.node[2*point+2]:
                self.node[point]=self.node[2*point+2]
            else:
                self.node[point]=self.node[2*point+1]

    def getmin(self,a,b):
        l,r = a+self.n,b+self.n
        ret = float("inf")
        while l<r:
            if r&1:
                r-=1
                if ret>self.node[r-1]:
                    ret=self.node[r-1]

            if l&1:
                if ret>self.node[l-1]:
                    ret=self.node[l-1]
                l+=1

            l>>=1
            r>>=1
        return ret

