class RangeMinimumQuery(object):

    def __init__(self, size):
        self.size = 1
        while self.size < size:
            self.size *= 2
        self.data = [float("inf") for _ in xrange(self.size*2+2)]

    def update(self, idx, value):
        k = idx + self.size - 1
        self.data[k] = value
        while k > 0:
            k = (k - 1) / 2
            self.data[k] = min(self.data[k*2+1], self.data[k*2+2])

    def find(self, start, end):
        def query(k, left, right):
            if right <= start or end <= left:
                return float("inf")
            if start <= left and right <= end:
                return self.data[k]
            vl = query(k*2+1, left, (left+right)/2)
            vr = query(k*2+2, (left+right)/2, right)
            return min(vl, vr)
        return query(0, 0, self.size)


