backet = [MAX for i in range(span)]

def update(i, x):
    data[i] = x
    if backet[int(i/span)] > x:
        backet[int(i/span)] = x

def minimum(x, y):
    b_min = math.ceil(x/span)
    b_max = math.floor(y/span)
    #print("x: " + str(x) + " y: "+str(y))
    #print("backet from: " + str(b_min) + " to:" +str(b_max))
    result = MAX
    for i in range(x, b_min * span):
        if data[i] < result:
             result = data[i]
    for i in range(b_min, b_max+1):
        if backet[i] < result:
             result = backet[i]
    for i in range(b_max * span, y+1):
        if data[i] < result:
             result = data[i]

    return result


