class SegmentTree():
    maxval=(1<<31)-1

    def __init__(self,n,val=maxval):
        self.offset=self.setOffset(n)
        self.segTree=[val]*(2*self.offset+1)

    def init_array(self,array):
        for i in range(len(array)):
            self.segTree[i+self.offset]=array[i]
        for i in range(offset-1,-1,-1):
            self.segTree[i]=self.minChild(i)

    def setOffset(self,n):
        if n==1:
            return 1
        else:
            return (1<<(n-1).bit_length())-1

    def update(self,k,x):
        k+=self.offset
        self.segTree[k]=x
        while k:
            k=(k-1)>>1
            self.segTree[k]=self.minChild(k)

    def min_query(self,p,q):
        if p>=q:
            return

        p+=self.offset
        q+=self.offset-1
        segmin=self.maxval

        while q-p>1:
            #p%2==0
            if not p&1:
                segmin=min(segmin,self.segTree[p])
            #q%2==1
            if q&1:
                segmin=min(segmin,self.segTree[q])
                q-=1
            p=p>>1
            q=(q-1)>>1

        if p==q:
            return min(segmin,self.segTree[p])
        else:
            return min(min(segmin,self.segTree[p]),self.segTree[q])

    def minChild(self,n):
        return min(self.segTree[2*n+1],self.segTree[2*n+2])

