class RMQ:
    INF = int((1<<31)-1)

    def __init__(self, n_:int):
        """param: n_(int) 葉の要素数"""
        # 葉の要素数を2のべき乗に
        n = 1
        while n<n_: n*=2
        self.n = n
        # 木全体では n + n/2 + ... = 2n-1
        self.dat = [self.INF]*(2*n-1)

    def update(self, k:int, a:int):
        k += self.n - 1
        self.dat[k] = a

        while k>0:
            k = (k-1)//2
            self.dat[k] = min(self.dat[2*k+1], self.dat[2*k+2])

    def dfs(self, a:int, b:int, k:int, l:int, r:int):
        """
        param a,b(int): 区間[a,b)
        param k(int):   節点の番号
        param l,r(int): 節点kが区間[l,r)に対応"""
        if r<=a or b<=l: return self.INF

        if a<=l and r<=b: 
            return self.dat[k]
        else:
            vl = self.dfs(a, b, 2*k+1, l, (l+r)//2)
            vr = self.dfs(a, b, 2*k+2, (l+r)//2, r)
            return min(vl, vr)

    def query(self, a:int, b:int):
        return self.dfs(a, b, 0, 0, self.n)

