class segTree:
    def __init__(self,n,identity):
        if bin(n).count("1") == 1:
            self.depth = n.bit_length()
        else:
            self.depth = n.bit_length()+1
        self.leaves = 2**(self.depth-1)
        self.identity = identity
        self.tree = [self.identity] * (2**self.depth)

    def merge(self,x,y):
        return min(x,y)

    def update(self,i,x):
        i += self.leaves
        self.tree[i] = x
        target = i//2
        while target > 0:
            self.tree[target] = min(self.tree[target*2],self.tree[target*2+1])
            target //= 2

    def find(self,l,r):
        ret = self.identity
        l += self.leaves
        r += self.leaves
        while r > l:
            if l&1:
                ret = min(ret,self.tree[l])
                l += 1
            if r&1:
                r -= 1
                ret = min(ret,self.tree[r])
            l //= 2
            r //= 2
        return ret

