        self.n = 2**(n-1).bit_length()
        self.data = [float('inf')]*(2*self.n)

    def update(self, k, a):
        k += self.n-1
        self.data[k] = a

        while k >= 0:
            k = (k-1)//2
            self.data[k] = min(self.data[k*2+1], self.data[k*2+2])

    def query(self, l, r):
        L = l+self.n
        R = r+self.n
        ret = float('inf')
        while L < R:
            if R & 1:
                R -= 1
                ret = min(ret, self.data[R-1])
            if L & 1:
                ret = min(ret, self.data[L-1])
                L += 1
            L >>= 1
            R >>= 1
        return ret


