      self.nodes[x] = self.func(self.nodes[2*x+1], self.nodes[2*x+2])

  def get(self, a, b):
    return self._get(a, b)

  def _get(self, a, b, k=0, l=0, r=-1):
    if (r < 0):
      r = self.n
    if (r <= a or b <= l):
      return self.init_val
    if (a <= l and r <= b):
      return self.nodes[k]
    return self.func(
      self._get(a, b, 2*k+1, l, (l + r) // 2),
      self._get(a, b, 2*k+2, (l + r) // 2, r)
