struct SegmentTree {
  v: Vec<i32>,
  e: i32,
  n: usize,
}

impl SegmentTree {
  fn new(size: usize, e: i32) -> Self {
    let mut n = 1;
    while n < size {
      n <<= 1;
    }
    let v: Vec<i32> = vec![e; n * 2];
    SegmentTree { v, e, n }
  }
  fn set(&mut self, k: usize, x: i32) {
    self.v[k + self.n] = x;
  }
  fn build(&mut self) {
    for i in (1..self.n).rev() {
      self.v[i] = min(self.v[i * 2 + 0], self.v[i * 2 + 1]);
    }
  }
  fn update(&mut self, mut k: usize, x: i32) {
    self.v[k + self.n] = x;
    k += self.n;
    while (k >> 1) > 0 {
      k >>= 1;
      self.v[k] = min(self.v[k * 2 + 0], self.v[k * 2 + 1]);
    }
  }
  fn query(&self, mut a: usize, mut b: usize) -> i32 {
    let mut l = self.e;
    let mut r = self.e;
    a += self.n;
    b += self.n;
    while a < b {
      if a & 1 == 1 {
        l = min(l, self.v[a]);
        a += 1;
      }
      if b & 1 == 1 {
        b -= 1;
        r = min(self.v[b], r);
      }
      a >>= 1;
      b >>= 1;
    }
    min(l, r)
  }
  fn reset(&mut self, k: usize) {
    self.update(k, 2147483647);
  }
}

mod segtree {
    pub trait Monoid {
        type Elem;
        fn id(&self) -> Self::Elem;
        fn ops(&self, lhs: &Self::Elem, rhs: &Self::Elem) -> Self::Elem;
    }

    pub struct SegmentTree<T: Monoid> {
        v: Vec<T::Elem>,
        n: usize,
        t: T,
    }

    impl<T: Monoid> SegmentTree<T>
    where
        T::Elem: ::std::clone::Clone,
    {
        pub fn new(n: usize, t: T) -> SegmentTree<T> {
            let mut st = SegmentTree {
                n: 1,
                t: t,
                v: Vec::new(),
            };
            while st.n < n {
                st.n *= 2;
            }
            st.v.resize(st.n * 2 - 1, st.t.id());
            if n >= 2 {
                for i in 0..st.n - 2 + 1 {
                    let i = st.n - 2 - i;
                    st.v[i] = st.t.ops(&st.v[i * 2 + 1], &st.v[i * 2 + 2]);
                }
            }
            st
        }
        #[allow(dead_code)]
        pub fn set(&mut self, i: usize, x: T::Elem) {
            let mut i = i + self.n - 1;
            self.v[i] = x;
            while i > 0 {
                i = (i - 1) / 2;
                self.v[i] = self.t.ops(&self.v[i * 2 + 1], &self.v[i * 2 + 2]);
            }
        }
        #[allow(dead_code)]
        pub fn get(&self, a: usize, b: usize) -> T::Elem { self.q(a, b, 0, 0, self.n) }

        fn q(&self, a: usize, b: usize, k: usize, l: usize, r: usize) -> T::Elem {
            if r <= a || b <= l {
                self.t.id()
            } else if a <= l && r <= b {
                self.v[k].clone()
            } else {
                let c = (l + r) / 2;
                self.t.ops(
                    &self.q(a, b, k * 2 + 1, l, c),
                    &self.q(a, b, k * 2 + 2, c, r),
                )
            }
        }
    }

    impl<T: Monoid> ::std::ops::Index<usize> for SegmentTree<T> {
        type Output = T::Elem;
        #[allow(dead_code)]
        fn index(&self, i: usize) -> &Self::Output { &self.v[i] }
    }
}

struct MinMonoid {}
impl segtree::Monoid for MinMonoid {
    type Elem = u64;
    fn id(&self) -> Self::Elem { (1u64 << 31) - 1 }
    fn ops(&self, lhs: &Self::Elem, rhs: &Self::Elem) -> Self::Elem { std::cmp::min(*lhs, *rhs) }
}

