use std::cmp::min;
use std::io;
use std::io::prelude::*;
use std::iter::repeat;

struct MinSegTree {
    n: usize,
    nodes: Vec<i32>,
}

impl MinSegTree {
    fn init(n: usize) -> MinSegTree {
        let n = 1 << f64::log2(n as f64).ceil() as usize;
        let mut ret = MinSegTree {
            n,
            nodes: repeat(std::i32::MAX).take(2 * n - 1).collect(),
        };
        for i in (0..(n - 1)).rev() {
            ret.update1(i);
        }
        ret
    }

    fn update1(&mut self, idx: usize) {
        self.nodes[idx] = min(self.nodes[2 * idx + 1], self.nodes[2 * idx + 2]);
    }

    fn update_rec(&mut self, idx: usize) {
        self.update1(idx);
        if idx > 0 {
            self.update_rec((idx - 1) / 2);
        }
    }

    fn update(&mut self, i: usize, x: i32) {
        let ni = self.n + i - 1;
        self.nodes[ni] = x;
        if self.n > 1 {
            self.update_rec((ni - 1) / 2);
        }
    }

    fn find(&self, i: usize, j: usize, ni: usize, l: usize, r: usize) -> i32 {
        if i <= l && r <= j {
            self.nodes[ni]
        } else if r <= i || j <= l {
            std::i32::MAX
        } else {
            min(
                self.find(i, j, 2 * ni + 1, l, (l + r) / 2),
                self.find(i, j, 2 * ni + 2, (l + r) / 2, r),
            )
        }
    }
}

