struct CustomIO<'a> {
    sin: ::std::io::Bytes<::std::io::StdinLock<'a>>,
    sout: ::std::io::StdoutLock<'a>,
    buf: [u8; 20],
}
impl<'a> CustomIO<'a> {
    pub fn new(
        sin: ::std::io::Bytes<::std::io::StdinLock<'a>>,
        sout: ::std::io::StdoutLock<'a>,
    ) -> Self {
        CustomIO::<'a> {
            sin: sin,
            sout: sout,
            buf: [0u8; 20],
        }
    }

    pub fn readu32(&mut self) -> u32 {
        self.sin
            .by_ref()
            .map(|c| c.unwrap() as char)
            .skip_while(|c| c.is_whitespace())
            .take_while(|c| !c.is_whitespace())
            .fold(0u32, |a, x| a * 10 + (x as u8 - b'0') as u32)
    }

    pub fn readu64(&mut self) -> u64 {
        self.sin
            .by_ref()
            .map(|c| c.unwrap() as char)
            .skip_while(|c| c.is_whitespace())
            .take_while(|c| !c.is_whitespace())
            .fold(0u64, |a, x| a * 10 + (x as u8 - b'0') as u64)
    }

    pub fn readusize(&mut self) -> usize {
        self.sin
            .by_ref()
            .map(|c| c.unwrap() as char)
            .skip_while(|c| c.is_whitespace())
            .take_while(|c| !c.is_whitespace())
            .fold(0usize, |a, x| a * 10 + (x as u8 - b'0') as usize)
    }

    pub fn writeu32(&mut self, mut v: u32) {
        let mut i = 20usize;
        while v != 0u32 {
            i -= 1usize;
            self.buf[i] = (v % 10) as u8 + b'0';
            v /= 10;
        }
        if i == 20usize {
            i = 19usize;
            self.buf[19] = b'0';
        }
        let _ = self.sout.write(&self.buf[i..20]);
    }

    pub fn writeu64(&mut self, mut v: u64) {
        let mut i = 20usize;
        while v != 0u64 {
            i -= 1usize;
            self.buf[i] = (v % 10) as u8 + b'0';
            v /= 10;
        }
        if i == 20usize {
            i = 19usize;
            self.buf[19] = b'0';
        }
        let _ = self.sout.write(&self.buf[i..20]);
    }

    pub fn writeusize(&mut self, mut v: usize) {
        let mut i = 20usize;
        while v != 0usize {
            i -= 1usize;
            self.buf[i] = (v % 10) as u8 + b'0';
            v /= 10;
        }
        if i == 20usize {
            i = 19usize;
            self.buf[19] = b'0';
        }
        let _ = self.sout.write(&self.buf[i..20]);
    }

    pub fn endl(&mut self){
        let _ = self.sout.write(&[b'\n']);
    }
}

pub struct SegmentTree<T>
where
    T: ::math::algebra::Magma,
{
    c: ::std::vec::Vec<<T as ::math::algebra::Magma>::T>,
}
impl<T> SegmentTree<T>
where
    T: ::math::algebra::Magma + ::math::algebra::Identity,
    <T as ::math::algebra::Magma>::T: ::std::clone::Clone,
{
    pub fn new(len: usize) -> Self {
        Self {
            c: vec![<T as ::math::algebra::Identity>::identity(); len << 1u32],
        }
    }
}
impl<T> SegmentTree<T>
where
    T: ::math::algebra::Magma,
{
    pub fn is_empty(&self) -> bool {
        self.c.is_empty()
    }

    pub fn len(&self) -> usize {
        self.c.len() >> 1u32
    }
}
impl<T> SegmentTree<T>
where
    T: ::math::algebra::Magma + ::math::algebra::Associativity + ::math::algebra::Identity,
{
    pub fn fold(&self, range: ::std::ops::Range<usize>) -> <T as ::math::algebra::Magma>::T {
        let (mut first, mut last) = (range.start + self.len(), range.end + self.len());
        let (mut ret_l, mut ret_r) = (
            <T as ::math::algebra::Identity>::identity(),
            <T as ::math::algebra::Identity>::identity(),
        );
        while first < last {
            if (first & 1usize) != 0usize {
                ret_l = <T as ::math::algebra::Magma>::operation(&ret_l, &self.c[first]);
                first += 1usize;
            }
            if (last & 1usize) != 0usize {
                ret_r = <T as ::math::algebra::Magma>::operation(&ret_r, &self.c[last - 1usize]);
            }
            first >>= 1u32;
            last >>= 1u32;
        }
        <T as ::math::algebra::Magma>::operation(&ret_l, &ret_r)
    }
}
impl<T> SegmentTree<T>
where
    T: ::math::algebra::Magma + ::math::algebra::Associativity,
{
    pub fn update<F>(&mut self, mut index: usize, f: F)
    where
        F: ::std::ops::FnOnce(&<T as ::math::algebra::Magma>::T)
            -> <T as ::math::algebra::Magma>::T,
    {
        index += self.len();
        self.c[index] = f(&self.c[index]);
        index >>= 1u32;
        while index != 0usize {
            self.c[index] = <T as ::math::algebra::Magma>::operation(
                &self.c[index << 1u32],
                &self.c[index << 1u32 | 1usize],
            );
            index >>= 1u32;
        }
    }

    pub fn set(&mut self, index: usize, value: <T as ::math::algebra::Magma>::T) {
        self.update(index, move |_| value)
    }
}
impl<T> ::std::ops::Index<usize> for SegmentTree<T>
where
    T: ::math::algebra::Magma,
{
    type Output = <T as ::math::algebra::Magma>::T;
    fn index(&self, index: usize) -> &Self::Output {
        &self.c[index + self.len()]
    }
}

