#[allow(dead_code)]
impl SegTree {
  fn new(xs: &[usize]) -> SegTree {
    let l = xs.len();
    let d = (0..).skip_while(|&i|(1<<i)<l).next().unwrap();
    let mut v = vec![(1<<31)-1; 1<<(d+1)];

    for (&x,i) in xs.iter().zip((1<<d)..) {v[i] = x}
    for i in (1..(1<<d)).rev() {v[i] = min!(v[i<<1], v[(i<<1)|1])}

    SegTree {size: l, depth: d, vec: v}
  }

  fn update(&mut self, i: usize, x: usize) {
    self.vec[i+(1<<self.depth)-1] = x;

    let mut parent = (i+(1<<self.depth)-1) >> 1;
    while parent > 0 {
      self.vec[parent] = min!(self.vec[parent<<1], self.vec[(parent<<1)|1]);
      parent = parent >> 1
    }
  }

  fn query(&self, i: usize, j: usize) -> usize {
    fn rec(seg: &SegTree, i: usize, j: usize, k: usize, l: usize, r: usize) -> usize {
      if j < l || r < i {return (1<<31)-1}
      if i <= l && r <= j {return seg.vec[k]}
      let left = rec(seg, i, j, k<<1, l, l+((r-l)>>1));
      let right = rec(seg, i, j, (k<<1)|1, r-((r-l)>>1), r);
      min!(left, right)
    }

    rec(self, i, j, 1, 1, 1<<self.depth)
  }
}


