            l: usize,
            r: usize,
        ) -> U::Elem
        where
            U::Elem: std::clone::Clone,
        {
            if r <= a || b <= l {
                st.t.id()
            } else if a <= l && r <= b {
                st.v[k].clone()
            } else {
                let c = (l + r) / 2;
                st.t
                    .ops(&q(st, a, b, k * 2 + 1, l, c), &q(st, a, b, k * 2 + 2, c, r))
            }
        }
        q(self, a, b, 0, 0, self.n)
    }
}

