struct SEG {
    buf: Vec<u64>,
    n: usize,
}

impl SEG {
    fn new(size: usize) -> SEG {
        let n = (1..).map(|i| 1 << i).find(|&x| x > size).unwrap();

        SEG {
            buf: vec![(1 << 31) - 1; n * 2],
            n: n,
        }
    }

    fn update(&mut self, i: usize, x: u64) {
        let mut i = self.n + i - 1;
        self.buf[i] = x;
        while i > 0 {
            i = (i - 1) / 2;
            self.buf[i] = min(self.buf[2 * i + 1], self.buf[2 * i + 2]);
        }
    }

    fn query(&self, a: usize, b: usize, k: usize, l: usize, r: usize) -> u64 {
        if r <= a || b <= l {
            return 1 << 60;
        }

        if a <= l && r <= b {
            return self.buf[k];
        }

        let vl = self.query(a, b, 2 * k + 1, l, (l + r) / 2);
        let vr = self.query(a, b, 2 * k + 2, (l + r) / 2, r);
        min(vl, vr)
    }
}

