            size: {
                let mut tmp_size: usize = 1;
                while tmp_size < n as usize {
                    tmp_size *= 2;
                }
                tmp_size
            },
            node: {
                let mut tmp_size: usize = 1;
                while tmp_size < n as usize {
                    tmp_size *= 2;
                }
                vec![MAX; 2*tmp_size-1]
            }
        }
    }

    fn update(&mut self, mut k: usize, val: i64) {
        k += self.size - 1;
        self.node[k] = val;
        while k > 0 {
            k = (k - 1) / 2;
            self.node[k] = std::cmp::min(self.node[2*k+1], self.node[2*k+2]);
        }
    }

    fn get(&self, queryL: usize, queryR: usize) -> i64 {
        self._get(queryL, queryR, 0, self.size, 0)
    }

    fn _get(&self, queryL: usize, queryR: usize, nodeL: usize, nodeR: usize, k: usize) -> i64 {
        if nodeR <= queryL || queryR <= nodeL {return MAX;}
        if queryL <= nodeL && nodeR <= queryR {return self.node[k];}
        let nodeM: usize = (nodeL + nodeR) / 2;
        let vl: i64 = self._get(queryL, queryR, nodeL, nodeM, 2*k+1);
        let vr: i64 = self._get(queryL, queryR, nodeM, nodeR, 2*k+2);
        std::cmp::min(vl, vr)
    }
}

