use std::cmp::min;

struct RMQSegmentTree<T> {
    n: usize,
    dat: Vec<T>,
}

impl RMQSegmentTree<i32> {
    // 要素数nの配列に対し、セグメント木を構築する。
    pub fn new(n: usize) -> RMQSegmentTree<i32> {
        let mut n_ = 1;
        while n_ < n {
            n_ *= 2;
        }
        let n = n_;
        let dat = vec![i32::max_value(); 2 * n - 1];

        RMQSegmentTree {
            n,
            dat
        }
    }

    /// k番目の値をaに変更する
    pub fn update(&mut self, k: usize, a: i32) {
        let mut k = k + self.n - 1;
        self.dat[k] = a;

        while k > 0 {
            // k > 0 => k - 1 >= 0
            // k points index of parent
            k = (k - 1) / 2;

            self.dat[k] = min(self.dat[2 * k + 1].clone(), self.dat[2 * k + 2].clone());
        }
    }

    // 区間[a, b)の最小値を求める
    pub fn query(&self, a: usize, b: usize) -> Option<i32> {
        self._query(a, b, 0, 0, self.n)
    }

    fn _query(&self, a: usize, b: usize, k: usize, l:usize, r: usize) -> Option<i32> {
        // [a, b) と[l, r)が交差しなければ None
        if r <= a || b <= l {
            None
        } // [a, b)が[l, r)を内包するとき 
        else if a <= l && r <= b {
            Some(self.dat[k].clone())
        } else {
            let vl = self._query(a, b, k * 2 + 1, l, (l + r) / 2);
            let vr = self._query(a, b, k * 2 + 2, (l + r) / 2, r);

            match vl {
                Some(min_vl) => {
                    match vr {
                        Some(min_vr) => Some(min(min_vl, min_vr)),
                        None => Some(min_vl),
                    }
                },
                None => {
                    // match vr { Some(min_vr) => Some(min_vr), None => None,}
                    vr
                },
            }
        }
    }
}


