struct Segtree{
    n:i64,
    t:i64,
    node:Vec<i64>,
}
impl Segtree{
    fn init(&mut self){
        for i in 0..2*self.n+1{
            self.node.push(self.t);
        }
    }
    fn update(&mut self,k:i64,x:i64){
        let mut k=k+self.n;
        let mut i=k as usize;
        self.node[i]=x;
        k>>=1;
        while k>0{
            i=k as usize;
            self.node[i]=cmp::min(self.node[i<<1],self.node[i<<1|1]);
            k>>=1;
        }
    }
    fn query(&mut self,l:i64,r:i64)->i64{
        let mut vl:i64=self.t;
        let mut vr:i64=self.t;
        let mut l=l+self.n;
        let mut r=r+self.n;
        while l<r{
            if (l&1)>0{
                let i:usize=l as usize;
                vl=cmp::min(vl,self.node[i]);
                l=l+1;
            }
            if (r&1)>0{
                r=r-1;
                let i:usize=r as usize;
                vr=cmp::min(vr,self.node[i]);
            }
            l>>=1;
            r>>=1;
        }
        cmp::min(vl,vr)
    }
}
